/** Ícone do imbuement, o mesmo PNG que o client usa (iconid do imbuements.xml). */
function imbuementIcon(iconId, size = 32) {
  const img = document.createElement('img');
  img.className = 'imbue-icon';
  img.width = size;
  img.height = size;
  img.src = `/client/assets/imbuing/${iconId}.png`;
  img.alt = '';
  img.onerror = () => img.remove();
  return img;
}

const el = (tag, className, text) => {
  const node = document.createElement(tag);
  if (className) node.className = className;
  if (text != null) node.textContent = text;
  return node;
};

const money = (value) => Number(value ?? 0).toLocaleString('pt-BR');

/*
 * ---- O OURO do jogador e o do bolso MAIS o do banco ----
 *
 * Report do painel: "no Mercado deveria contar o gold TOTAL do player, nao so o
 * da mao".
 *
 * Ele esta certo, e o resto do jogo ja era assim ha tempo: `server/src/ouro.mjs`
 * cobra da carteira primeiro e do banco no que faltar, e potion, municao, forja,
 * imbuement, blessing e NPC passam todos por la. O Mercado era a excecao — a
 * unica loja que ainda perguntava `character.gold` sozinho.
 *
 * O estrago era o mesmo dos dois lados: o servidor recusava uma compra que ele
 * teria como pagar, e a tela apagava o botao antes mesmo de tentar, dizendo
 * "faltam 25kk" para quem tinha cinquenta milhoes no banco.
 *
 * A tela do Mercado agora recebe o total ja somado do servidor (`market.gold` e
 * `coinMarket.gold`); isto aqui e o mesmo numero para quando ela precisa decidir
 * sozinha, antes da resposta chegar.
 */
const ouroDoJogador = (state) => (state?.character?.gold ?? 0) + (state?.character?.bank ?? 0);

const formatLeft = (ms) => {
  const minutes = Math.ceil(ms / 60000);
  if (minutes >= 1440) return `${Math.floor(minutes / 1440)}d ${Math.floor((minutes % 1440) / 60)}h`;
  return minutes >= 60 ? `${Math.floor(minutes / 60)}h${String(minutes % 60).padStart(2, '0')}` : `${minutes} min`;
};

let ctx = null; // { state, send, openModal, body, refresh }

export function initPanels(context) {
  ctx = context;
  /*
   * A mochila usa a caixa de confirmar que mora aqui.
   *
   * Pendurada no contexto e não importada de lá: `panels.mjs` já importa de
   * `inventory.mjs` (a célula do item, o soltar, a régua de quantidade), e um
   * import de volta fecharia um ciclo entre os dois. O contexto é o mesmo
   * objeto nos dois arquivos — ver `initInventory(panelCtx)`, em `main.mjs`.
   */
  ctx.pedirUso = pedirUso;
}

/*
 * ---- Clicar num item que COBRA pergunta antes ----
 *
 * "quando clicar no item tem que aparecer o que será consumido e se a pessoa
 *  quer aceitar ou não."
 *
 * Vale para os Buff Power e só para eles, porque só eles cobram: uma poção
 * gasta a si mesma e o clique é a decisão inteira. Estes gastam trinta ou
 * cinquenta milhões de ouro — ou dez Draevor Coins — POR CLIQUE, e o item
 * continua na mochila parecendo intacto. Sem esta caixa, dois cliques sem
 * querer custam 60kk e não deixam rastro na tela.
 *
 * A caixa é a mesma da loja (`confirmPurchase`): ela já diz preço, saldo e
 * saldo depois, que são exatamente as três coisas que a pessoa precisa ver
 * antes de aceitar. O que muda é a moeda — aqui a maioria cobra OURO.
 *
 * Quem não é Buff Power passa direto, como sempre passou.
 */
function pedirUso(id, onde) {
  /*
   * ---- Os dois pergaminhos de acesso avisam ANTES de serem usados ----
   *
   * "impede as pessoas de usar esses itens sem o nivel minimo e sem a premium,
   *  e bota no modal do item o nivel minimo, pra pessoa nao correr o risco de
   *  usar."
   *
   * Quem RECUSA e' o servidor (`ligarAcesso`), e ele devolve o item — nada se
   * perde. Mas descobrir pelo erro depois de clicar e' ruim: a caixa diz a
   * exigencia antes, e quando ela nao esta' cumprida pede a marca, como a
   * compra ja' pedia.
   *
   * `cost: 0` de proposito: usar nao cobra nada. A caixa mostra as linhas de
   * preco zeradas, que e' o jeito honesto de dizer "isto nao custa moeda" — o
   * que custa e' o item, e ele some.
   */
  const porta = PORTAS_ESPECIAIS.find((p) => p.item === Number(id));
  if (porta) {
    const personagem = ctx.state.character;
    const semPremium = (personagem?.premium ?? 0) <= 0;
    const abaixo = (personagem?.level ?? 0) < (porta.level ?? 0);
    /*
     * Quem NÃO pode usar não recebe uma pergunta — recebe a resposta.
     *
     * A primeira versão abria a caixa de confirmar com uma caixinha de "tentar
     * mesmo assim". Estava errado: confirmar existe para uma decisão que é da
     * pessoa, e esta não é. O servidor vai recusar de qualquer jeito
     * (`ligarAcesso`), então perguntar só faz ela marcar uma caixinha para
     * ouvir "não" um segundo depois.
     *
     * Quem PODE usar também não recebe pergunta nenhuma: o pergaminho não cobra
     * moeda, e um clique a mais em algo que só faz bem é fricção sem motivo.
     */
    if (semPremium || abaixo) {
      const falta = [
        semPremium ? 'ser PREMIUM' : null,
        abaixo ? `estar no level ${porta.level} (você está no ${personagem?.level ?? 0})` : null,
      ].filter(Boolean).join(' e ');
      return void ctx.notice?.(
        `As ${porta.titulo} pedem ${falta}. O pergaminho continua na sua mochila — nada foi gasto.`
      );
    }
    return void ctx.send({ t: 'usar', id, onde });
  }

  const linha = (ctx.state.character?.efeitos?.buffPower ?? []).find((buff) => buff.item === Number(id));
  if (!linha) return void ctx.send({ t: 'usar', id, onde });

  const emCoin = linha.custo?.moeda === 'coins';
  const quanto = linha.custo?.quanto ?? 0;
  /*
   * O saldo é o das DUAS carteiras quando o preço é em ouro — é assim que o
   * servidor cobra (bolso primeiro, banco no que faltar). Mostrar só o bolso
   * faria a caixa dizer "faltam 25kk" para quem tem cinquenta no banco.
   */
  const saldo = emCoin
    ? (ctx.state.store?.coins ?? ctx.state.character?.coins ?? 0)
    : ouroDoJogador(ctx.state);

  const jaTem = linha.restante > 0;
  const nota =
    `${linha.resumo}, por 1 hora.` +
    (jaTem
      ? ` Você já tem ${duracaoCurta(Math.round(linha.restante / 1000))} — este clique SOMA mais uma hora, até o teto de 10.`
      : ' O item NÃO some: fica na mochila e o que se gasta é o preço.');

  confirmPurchase({
    cabecalho: 'Ligar o bônus',
    title: `Ligar ${linha.nome}`,
    cost: quanto,
    balance: saldo,
    currency: emCoin ? 'coin-store' : 'coin-gold',
    unit: emCoin ? 'Draevor Coins' : 'de ouro (bolso + banco)',
    preview: itemCanvas(linha.item, 48),
    note: nota,
    onConfirm: () => ctx.send({ t: 'usar', id, onde }),
  });
}

/*
 * `alertas` acende a aba que TEM alguma coisa esperando.
 *
 * "quando eu tiver recompensas disponíveis e estiver na aba de quests, tem que
 *  ficar meio que chamativo as abas ali pra clicar."
 *
 * É um mapa de `id -> função que diz se há algo`, e não um campo no `tabs`,
 * porque a resposta muda a cada quadro: o prêmio aparece enquanto a janela está
 * aberta, e uma lista fixa mostraria o estado de quando ela abriu.
 */
function tabBar(tabs, active, onSelect, icones = null, alertas = null) {
  const bar = el('div', 'tabs');
  for (const [id, label] of Object.entries(tabs)) {
    /*
     * ---- O botao ganha o NOME da aba como classe, e o rotulo um <span> ----
     *
     * "onde esta escrito Especial Hunts coloca as letras em dourado e com
     *  efeito."
     *
     * Duas coisas faltavam para isso ser possivel sem tocar em toda barra de
     * abas do jogo:
     *
     * `aba-<id>` no botao e o endereco — sem ela nao ha como o CSS falar de UMA
     * aba, e o dourado cairia nas cinco. E o texto solto dentro do botao nao
     * podia receber o brilho: o degrade recortado na letra
     * (`background-clip: text`) come o fundo do proprio botao, que e o que
     * desenha a aba. Dentro de um <span> ele pinta so as letras.
     *
     * As duas mudancas valem para TODAS as abas do jogo e nao mudam nada nelas:
     * uma classe a mais que ninguem estiliza, e um <span> que num flex em
     * coluna ocupa exatamente o lugar onde o texto ja estava.
     */
    const button = el('button', `aba-${id}`);
    /* Uma função que explode não pode derrubar a barra de abas inteira. */
    let temAlgo = false;
    try { temAlgo = !!alertas?.[id]?.(); } catch { temAlgo = false; }
    if (temAlgo && id !== active) button.classList.add('aba-chama');
    button.append(el('span', 'aba-rotulo', label));
    /*
     * ---- Um ícone na aba, SE ele existir ----
     *
     * `artOrUiIcon` tenta `client/assets/icons/aba-<id>.png`, cai para
     * `client/assets/ui/` e, não achando nenhum dos dois, TIRA a si mesmo do
     * documento. Então uma aba sem arte fica exatamente como está hoje: só o
     * texto, sem buraco e sem quadrado quebrado.
     *
     * É o mesmo desenho dos cards do treino, e é o que deixa a arte entrar
     * depois — basta pôr o PNG na pasta, sem tocar em código.
     */
    /*
     * `icones` aponta para arte que JÁ EXISTE com outro nome — as perícias são
     * `sk-sword`, `sk-axe`, e a experiência é `ficha-exp`. Sem esse desvio, o
     * Highscores pediria dez arquivos `aba-*` que ninguém desenhou e ficaria
     * com dez abas de texto puro no meio de um jogo em que toda aba tem cara.
     */
    button.prepend(artOrUiIcon(icones?.[id] ?? `aba-${id}`, ''));
    button.setAttribute('aria-selected', String(id === active));
    button.onclick = () => onSelect(id);
    bar.append(button);
  }
  return bar;
}

/** Modal com abas que se redesenha sozinho quando o estado muda. */
/*
 * Modal com abas que se redesenha sozinho quando o estado muda.
 *
 * `opcoes.padrao`   — a aba de quando a janela abre pela primeira vez. Sem ela,
 *                     a primeira da lista. As duas coisas deixaram de ser a
 *                     mesma quando o Level Reward foi para a frente das outras:
 *                     ele é o primeiro na fila, e não o assunto da janela.
 *
 * `opcoes.efemeras` — abas que a janela NÃO guarda como "a última que você
 *                     viu". Quem abriu Tarefas para ver as boss tasks e passou
 *                     no Level Reward voltava ao Level Reward em toda abertura
 *                     seguinte, para sempre. Uma aba lateral não pode sequestrar
 *                     a janela inteira por causa de uma visita.
 */
/*
 * `opcoes.icones` empresta o desenho de outra aba a uma delas.
 *
 * A barra procura `aba-<id>.png` sozinha, e é o certo quase sempre. A
 * Recompensa Diária é a exceção: ela já tem um ícone desenhado (o do baú da
 * faixa de baixo), e pedir um segundo arquivo com o mesmo desenho seria pedir
 * dois arquivos para manter iguais.
 */
function tabbedModal(title, tabs, stateKey, render, variant, opcoes = {}) {
  const padrao = opcoes.padrao ?? Object.keys(tabs)[0];
  const efemeras = opcoes.efemeras ?? [];
  ctx.openModal(title, (body) => {
    const draw = () => {
      body.innerHTML = '';
      // O canto de ações é remontado por quem desenha a aba; limpar aqui é o
      // que impede o botão de uma aba de sobreviver na aba seguinte.
      ctx.acoesDoModal?.();
      body.append(tabBar(tabs, ctx.tabs[stateKey], (tab) => {
        ctx.tabs[stateKey] = tab;
        draw();
      }, opcoes.icones ?? null, opcoes.alertas ?? null));
      render(body, ctx.tabs[stateKey], draw);
    };
    // Aba nenhuma guardada, ou uma que não se guarda: volta para o padrão.
    if (!ctx.tabs[stateKey] || efemeras.includes(ctx.tabs[stateKey])) ctx.tabs[stateKey] = padrao;
    ctx.redraw = draw;
    draw();
  }, null, variant);
}

// ---------- hunts, bosses, treino ----------

/*
 * O item de acesso e a duração dele. Os mesmos números do `instance.mjs` do
 * servidor — aqui eles são só desenho: quem decide quem entra é ele.
 */
const ACESSO_INSTANCE_MS = 24 * 60 * 60 * 1000;

/*
 * ---- As DUAS portas da aba Especial ----
 *
 * `campo` é onde o relógio daquela porta chega no personagem (o servidor manda
 * os dois em `publicCharacter`, ver `acessoView`), e `lista` é onde as hunts
 * dela chegam no catálogo. Uma linha por porta: a tela desenha o mesmo bloco
 * duas vezes em vez de ter duas cópias dele.
 */
/**
 * Onde o catálogo guarda hunts. Toda tela que procura uma hunt por id tem de
 * olhar as quatro — ver `acharNoCatalogo`, no filtro de loot.
 */
/*
 * ---- Todas as prateleiras de hunt do catálogo, por nome ----
 *
 * Quem procura uma hunt pelo id — o Filtro de Loot é o caso — tem de olhar
 * TODAS: o servidor manda cinco listas separadas (`hunts`, `vips`, `especiais`,
 * `divinas`, `bosses`).
 *
 * Esta linha já foi consertada três vezes, sempre do mesmo jeito: uma
 * prateleira nova nasce no servidor, ninguém a acrescenta aqui, e a coluna
 * "Loot desta caçada" fica VAZIA lá dentro — sem erro no console, sem nada no
 * log. Foi assim com as Especial Hunts, com as Divine Hunts e agora com as
 * Hunts Vip ("o loot filter quando abre pela bolsa de loot as hunts vips nao
 * mostra o loot dessa caçada, as outras hunts estao ok").
 *
 * Por isso ela deixou de depender só de memória: `test-filtro-tela` compara
 * esta lista com as prateleiras que o servidor realmente monta, e fica vermelho
 * no dia em que a sexta nascer.
 */
const PRATELEIRAS_DE_HUNT = ['hunts', 'vips', 'especiais', 'divinas', 'bosses'];

const PORTAS_ESPECIAIS = [
  {
    id: 'instance',
    titulo: 'Instance Hunts',
    item: PORTAS_DE_ACESSO.instance.item,
    campo: 'instance',
    lista: 'especiais',
    /*
     * O level da hunt mais barata desta porta — o mesmo de `PORTAS`, em
     * `server/src/instance.mjs`, que e' quem RECUSA o uso abaixo dele. Aqui ele
     * so' avisa; la' ele decide.
     */
    level: PORTAS_DE_ACESSO.instance.level,
    legenda: 'Level 800. O passe vale 24 horas, e usar outro soma mais 24.',
    /*
     * ---- O que se vai buscar lá dentro ----
     *
     * "no mesmo cardzinho que mostra acesso liberado coloque escrito: aqui
     *  dropa o item essencial e único para pegar Armas Draevor, e aí a sprite da
     *  Draevor Bag, e ao passar o mouse mostra o que pode vir."
     *
     * É a razão de a prateleira existir, e ela não estava escrita em lugar
     * nenhum: quem abria a aba via duas cavernas caras e nenhum motivo para
     * entrar. O balão da bag (a lista de prêmios) já vem de graça — é o mesmo
     * `tipFor` de qualquer item da tela.
     */
    bag: 55216,
    premio: 'Aqui dropa o item essencial e único para pegar as Armas Draevor',
  },
  {
    id: 'divina',
    titulo: 'Divine Hunts',
    item: PORTAS_DE_ACESSO.divina.item,
    campo: 'divina',
    lista: 'divinas',
    level: PORTAS_DE_ACESSO.divina.level,
    legenda: 'Level 1000 (1300 nas cinco novas). O pergaminho vale 24 horas, e usar outro soma mais 24.',
    /* A mesma frase, e a bag do SET: é o que sai daqui e não sai de lá. */
    bag: 55517,
    premio: 'Aqui dropa o item essencial e único para pegar os Sets Draevor',
  },
];

export function openHunts() {
  /*
   * A LOJA, por causa da aba de Treino.
   *
   * Os dois cartazes de lá anunciam preço — o das armas de exercise e o do
   * Scroll Speed —, e preço escrito à mão envelhece calado. O pedido vai uma
   * vez, ao abrir a janela, e a resposta redesenha o modal aberto.
   */
  ctx.send({ t: 'store' });
  // Aberta pela barra (e nao pelo "Voltar"), a lista comeca no topo — e o topo
  // e' mandado de verdade, porque o corpo do modal e' o mesmo elemento de antes
  // e ele guarda a rolagem de quando foi fechado.
  if (chegadaNaLista !== 'voltar') {
    chegadaNaLista = 'nova';
    rolagemDaLista.hunts = 0;
    rolagemDaLista.bosses = 0;
    rolagemDaLista.especiais = 0;
  }
  /*
   * ---- Normal Hunts e Especial Hunts ----
   *
   * As cavernas de sempre continuam na primeira aba, agora com nome proprio; a
   * de Especial e a das Instance Hunts, que se abrem com o item de acesso e
   * premium. A tela nao sabe o que e uma instance: ela desenha a lista que o
   * servidor manda em `catalog.especiais`, separada em `content.mjs` pela marca
   * `especial` do arquivo — o mesmo caminho da aba de Bosses.
   */
  /*
   * ---- A aba de Arena saiu ----
   *
   * Ela estava lá dizendo "em construção" desde que as arenas procedurais foram
   * embora, e a razão para mantê-la era "tirar a aba esconderia que ela existe e
   * vem". Passou tempo e ela não veio; uma aba que só serve para pedir desculpa
   * é uma aba a menos de espaço para as que fazem alguma coisa. O dono pediu
   * para tirar.
   *
   * O que roda por baixo (`arenaView`, `startArena`, `arenaVictory` e a melhor
   * marca de cada personagem) continua no servidor, intocado — quando a arena de
   * verdade chegar, ela reaproveita a progressão em vez de recomeçar do zero.
   */
  tabbedModal('Aventuras', { hunts: 'Normal Hunts', vips: 'Hunts Vip', especiais: 'Especial Hunts', bosses: 'Bosses', training: 'Treino' }, 'hunts', (body, tab) => {
    // As hunts normais são a CAMPANHA: 4 atos, 3 dificuldades, fases que se liberam (ver `campanhaCards`).
    if (tab === 'hunts') campanhaCards(body);
    /*
     * ---- A aba das Hunts Vip ----
     *
     * "coloque a direita de normal hunts Hunts Vip que sera so pras pessoas com
     *  premium."
     *
     * Ao lado das normais e não junto das Especiais de propósito: as Especiais
     * pedem premium E um pergaminho comprado com coins, e as duas coisas moram
     * naquela aba (os botões das portas, os dois relógios). A Vip não tem nada
     * disso — tem uma tranca só, e uma aba com uma tranca só não cabe numa aba
     * que existe para explicar duas.
     *
     * O aviso de premium é o MESMO da aba Especial, com outra frase: a regra é
     * a mesma metade, e ter dois avisos parecidos que dizem a mesma coisa de
     * jeitos diferentes é como um deles fica desatualizado.
     */
    else if (tab === 'vips') {
      body.append(avisoDePremium('Hunts Vip'));
      const lista = ctx.state.catalog.vips ?? [];
      if (lista.length) huntCards(body, lista, false);
      else body.append(el('p', 'empty', 'Nenhuma Hunt Vip disponível ainda.'));
    }
    else if (tab === 'especiais') {
      /*
       * ---- Dois blocos, cada um com o relógio dele ----
       *
       * "na aba de especial hunts você vai separar Instance Hunts e Divine
       *  Hunts (...) e faz mostrar o tempo restante de instance hunts e divine
       *  hunts também."
       *
       * Blocos empilhados e não sub-abas: são duas listas curtas, e os dois
       * relógios têm de aparecer JUNTOS — quem tem os dois pergaminhos quer
       * saber de quanto está cada um sem clicar em nada.
       *
       * O aviso de premium fica em cima dos dois, uma vez só: ele vale para a
       * aba inteira e repeti-lo por bloco seria dizer a mesma coisa duas vezes.
       */
      body.append(avisoDePremium());

      /*
       * ---- Um botão para cada prateleira ----
       *
       * "lá em especial hunts separe um botão clicável pras duas seção de hunt."
       *
       * O relógio de cada uma vai no PRÓPRIO botão ("Divine Hunts · 23h07"): as
       * duas seções deixaram de aparecer juntas, e sem isso descobrir quanto
       * sobra do outro passe pediria um clique. É a mesma informação de antes,
       * no lugar onde ela ainda cabe.
       */
      const escolhida = PORTAS_ESPECIAIS.some((p) => p.id === ctx.tabs.especialPorta)
        ? ctx.tabs.especialPorta
        : PORTAS_ESPECIAIS[0].id;
      body.append(
        botoesDasPortas(escolhida, (next) => {
          ctx.tabs.especialPorta = next;
          ctx.redraw();
        })
      );

      const porta = PORTAS_ESPECIAIS.find((p) => p.id === escolhida);
      const lista = ctx.state.catalog[porta.lista] ?? [];
      body.append(blocoDaPorta(porta, lista.length));
      if (lista.length) huntCards(body, lista, false);
      else body.append(el('p', 'empty', `Nenhuma ${porta.titulo} disponível ainda.`));
    }
    else if (tab === 'bosses') {
      body.append(atalhoDaArenaDeBoss());
      huntCards(body, ctx.state.catalog.bosses, true);
    }
    else renderTraining(body);
  });
}

/*
 * ---- Os dois botões da aba Especial ----
 *
 * "deixa elas mais bonitas no botão da aba que escolhe Instance Hunts e Divine
 *  Hunts, e coloca o ícone dos itens de acesso e das bags também."
 *
 * Eram duas abas de texto. Agora cada botão diz as três coisas que decidem a
 * escolha, e diz por FIGURA: o pergaminho que abre a porta, o nome com o
 * relógio do acesso embaixo, e a bag que se vai buscar lá dentro.
 *
 * O balão da bag continua valendo dentro do botão — passar o mouse nela lista
 * as peças que podem sair, sem trocar de aba.
 *
 * A classe `tabs` fica junto de propósito: é ela que dá o desenho de aba
 * (cantos, linha de baixo, o realce do escolhido) que o resto do jogo usa. O
 * que `especial-portas` acrescenta é o miolo — as duas figuras e a segunda
 * linha.
 */
/*
 * ---- A CAMPANHA na aba "Normal Hunts" ----
 *
 * "4 atos e dentro deles fácil, médio, difícil igual Path of Exile" — as 48
 * hunts normais em 4 atos de 12 fases, jogadas em Fácil, depois Médio, depois
 * Difícil. Cada fase pede X bichos (a barra do card); completou, abre a
 * próxima; o boss fecha o ato. Quem decide o que abre é o servidor
 * (`systems/campanha.mjs`): a tela pede a campanha (`{t:'campanha'}`) e
 * desenha o que chegou.
 */
function campanhaCards(body) {
  const { state, send } = ctx;
  // Pede de novo ao abrir (o progresso anda caçando) — com folga, para o
  // redesenho que a resposta provoca não virar um pedido em laço.
  if (!state.campanha || Date.now() - (ctx.tabs.campanhaPedidaEm ?? 0) > 5000) {
    ctx.tabs.campanhaPedidaEm = Date.now();
    send({ t: 'campanha' });
  }
  const campanha = state.campanha;
  if (!campanha) return void body.append(el('p', 'empty', 'carregando a campanha...'));

  // A última dificuldade escolhida no WORLD volta (se o servidor ainda a mantém aberta).
  ctx.tabs.dificuldade ??= preferenciaDoMundo().dificuldade;
  const escolhida = campanha.dificuldades.find((d) => d.id === ctx.tabs.dificuldade && d.liberada) ?? campanha.dificuldades.findLast((d) => d.liberada);
  const visao = ctx.tabs.campanhaVisao ?? 'mapa';
  ctx.tabs.dificuldade = escolhida.id;

  // No WORLD, as dificuldades e o "quando completar" ficam dentro da própria tela (cabeçalho e barra de atalhos).
  if (visao !== 'mapa') {
    // ---- as três dificuldades ----
    const barra = el('div', 'tabs campanha-dificuldades');
    for (const d of campanha.dificuldades) {
      const botao = el('button', d.id === escolhida.id ? 'active' : null);
      botao.type = 'button';
      botao.append(el('b', null, d.liberada ? d.nome : `🔒 ${d.nome}`), el('span', null, `level ${d.faixa[0]}–${d.faixa[1]}`));
      botao.disabled = !d.liberada;
      tipTexto(botao, d.liberada ? `Campanha no ${d.nome}` : `O ${d.nome} abre depois de vencer o boss do Ato 4 na dificuldade anterior.`);
      botao.onclick = () => {
        ctx.tabs.dificuldade = d.id;
        ctx.redraw();
      };
      barra.append(botao);
    }
    body.append(barra);

    // ---- ao completar a fase: repetir (loop) ou seguir ----
    const modo = el('div', 'campanha-modo');
    modo.append(el('span', null, 'Quando a fase estiver completa:'));
    const opcoes = el('div', 'campanha-modo-opcoes');
    for (const [valor, rotulo, dica] of [
      ['repetir', '🔁 Ficar na fase', 'Continua em loop na mesma fase, mesmo completa (bom para farmar). Offline é sempre assim.'],
      ['seguir', '⏭ Avançar sozinho', 'Jogando online, com a fase completa vai para a próxima do ato — na hora, se você já está numa fase completa. Na party, quem também marcou "Avançar sozinho" vai junto com você. No fim do ato para: o boss é você quem chama. Offline fica sempre em loop.'],
    ]) {
      const botao = el('button', campanha.aoCompletar === valor ? 'active' : null, rotulo);
      botao.type = 'button';
      tipTexto(botao, dica);
      botao.onclick = () => {
        campanha.aoCompletar = valor;
        send({ t: 'aoCompletarFase', value: valor });
        ctx.redraw();
      };
      opcoes.append(botao);
    }
    modo.append(opcoes);
    body.append(modo);
  }

  const porId = new Map((state.catalog.hunts ?? []).map((h) => [h.id, h]));
  const bossPorId = new Map((state.catalog.bosses ?? []).map((b) => [b.id, b]));
  const catalog = state.catalog.bestiary;

  // ---- WORLD (o mapa do mundo) ou a lista de sempre ----
  const visoes = el('div', 'tabs campanha-visao');
  for (const [id, rotulo] of [['mapa', '🗺 Mapa do mundo'], ['lista', '☰ Lista']]) {
    const botao = el('button', visao === id ? 'active' : null, rotulo);
    botao.type = 'button';
    botao.onclick = () => {
      ctx.tabs.campanhaVisao = id;
      ctx.redraw();
    };
    visoes.append(botao);
  }
  if (visao !== 'mapa') body.append(visoes);
  if (visao === 'mapa') {
    // Aberto, o WORLD acompanha o progresso: pergunta de novo a cada 8 s e some quando a tela fecha.
    if (!ctx.tabs.worldPoll) {
      ctx.tabs.worldPoll = setInterval(() => {
        if (!document.querySelector('.w2')) {
          clearInterval(ctx.tabs.worldPoll);
          ctx.tabs.worldPoll = null;
          return;
        }
        send({ t: 'campanha' });
      }, 8000);
    }
    return void desenharMundo(body, {
      campanha,
      escolhida,
      hunts: porId,
      bosses: bossPorId,
      bestiario: catalog,
      h: {
        figuraDaCriatura,
        entrarNaFase: (hunt, lista) => {
          rolagemDaLista.hunts = document.getElementById('modal-body')?.scrollTop ?? 0;
          askRunMode(hunt, lista);
        },
        portalAberto: (b) => {
          const p = ctx.state.hunt?.portalDoBoss;
          return !!p && p.ato === b.ato && p.dificuldade === escolhida.id;
        },
        enfrentarBoss: (b) => {
          // Só pelo portal da limpeza atual; o servidor recusa o resto (`entrar` sem `viaPortal`).
          const p = ctx.state.hunt?.portalDoBoss;
          if (p && p.ato === b.ato && p.dificuldade === escolhida.id) send({ t: 'portalDoBoss' });
          ctx.closeModal();
        },
        escolherDificuldade: (id) => {
          ctx.tabs.dificuldade = id;
          ctx.redraw();
        },
        definirAoCompletar: (valor) => {
          campanha.aoCompletar = valor;
          send({ t: 'aoCompletarFase', value: valor });
          ctx.redraw();
        },
        fechar: () => ctx.closeModal(),
        verLista: () => {
          ctx.tabs.campanhaVisao = 'lista';
          ctx.redraw();
        },
      },
    });
  }

  // Os atos que o servidor mandou: os 4 legados e, se houver, os do editor (5 em diante).
  for (const ato of [...new Set(escolhida.fases.map((f) => f.ato))].sort((x, y) => x - y)) {
    const fases = escolhida.fases.filter((f) => f.ato === ato);
    const feitas = fases.filter((f) => f.completa).length;
    body.append(el('h4', 'store-degrau campanha-ato', `Ato ${ato} · level ${fases[0]?.nivel}–${fases.at(-1)?.nivel} · ${feitas}/${fases.length} fases`));
    const grade = el('div', 'hunt-grid');
    const listaDoAto = fases.map((f) => porId.get(f.huntId)).filter(Boolean);
    fases.forEach((f, i) => {
      const hunt = porId.get(f.huntId);
      const card = el('div', `hunt-card campanha-fase${f.liberada ? '' : ' locked'}${f.completa ? ' completa' : ''}`);
      card.append(el('h3', null, f.nome));
      if (hunt?.creatures?.length) {
        const bichos = el('div', 'hunt-card-bichos');
        for (const creature of hunt.creatures.slice(0, 4)) bichos.append(figuraDaCriatura(creature, catalog, 40));
        card.append(bichos);
      }
      card.append(el('span', 'lv', `Fase ${ato <= 4 ? (ato - 1) * 12 + i + 1 : i + 1} · level ~${f.nivel}`));
      const progresso = el('div', 'fase-progresso');
      const trilho = el('div', 'fase-trilho');
      const cheio = el('i');
      cheio.style.width = `${f.completa ? 100 : 0}%`;
      trilho.append(cheio);
      progresso.append(
        trilho,
        el(
          'span',
          null,
          f.pular
            ? '🔒 travada (em obras)'
            : f.completa
              ? `completa ✓${f.limpezas > 1 ? ` · ${f.limpezas} limpezas` : ''}`
              : f.liberada
                ? 'limpe a hunt inteira para completar'
                : '🔒 complete a fase anterior'
        )
      );
      card.append(progresso);
      if (f.liberada && hunt && !f.pular) {
        card.onclick = () => {
          rolagemDaLista.hunts = document.getElementById('modal-body')?.scrollTop ?? 0;
          askRunMode(hunt, listaDoAto);
        };
      }
      // ---- o boss que fecha o ato mora DENTRO do cartão da última fase: Fase 12 → portal → boss ----
      const bossDoAto = i === fases.length - 1 ? escolhida.bosses.find((x) => x.ato === ato) : null;
      if (bossDoAto) card.append(secaoDoBossDoAto(bossDoAto, ato, f, escolhida, bossPorId, catalog));
      grade.append(card);
    });

    body.append(grade);
  }
}

// O boss final do ato, preso ao cartão da última fase (nunca um 13º cartão da grade). Só exibe o que o servidor
// já decidiu (`liberado`/`vencido`); entrar continua validado lá. Sem recarga: pode ser enfrentado de novo.
function secaoDoBossDoAto(b, ato, ultimaFase, escolhida, bossPorId, catalog) {
  const dados = bossPorId.get(b.bossId);
  // Portal aberto = o SERVIDOR mandou `portalDoBoss` desta execução (hunt limpa agora). Histórico (fase completa, boss vencido) não abre.
  const portal = ctx.state.hunt?.portalDoBoss;
  const aberto = !!portal && portal.ato === ato && portal.dificuldade === escolhida.id;
  const estado = aberto ? 'aberto' : b.liberado ? 'aguardando' : 'bloqueado';
  const sec = el('div', `campanha-boss-secao ${estado}${b.vencido ? ' vencido' : ''}`);
  sec.append(el('span', 'campanha-boss-elo', `${ultimaFase.nome} → ${aberto ? 'Portal aberto' : 'Portal fechado'} → Boss final`));
  sec.append(el('h4', null, `Boss do Ato ${ato}: ${b.nome}`));
  if (dados?.creatures?.length) {
    const bichos = el('div', 'hunt-card-bichos');
    bichos.append(figuraDaCriatura(dados.creatures[0], catalog, 52));
    sec.append(bichos);
  }
  sec.append(el('span', 'lv', `level ~${b.nivel}`));
  sec.append(
    el(
      'p',
      null,
      aberto
        ? `Portal aberto. Toque para enfrentar${ato < 4 ? ` e liberar o Ato ${ato + 1}` : ''}.`
        : b.liberado
          ? `${b.vencido ? 'Vencido ✓ — sem espera, ' : ''}Elimine todos os monstros da ${ultimaFase.nome} (de novo, nesta execução) para abrir o portal.`
          : `🔒 Conclua a ${ultimaFase.nome} para liberar o boss.`
    )
  );
  if (aberto) {
    sec.classList.add('clicavel');
    sec.onclick = (ev) => {
      ev.stopPropagation(); // não dispara a fase que hospeda a seção
      send({ t: 'portalDoBoss' });
      ctx.closeModal();
    };
  }
  return sec;
}

function botoesDasPortas(escolhida, aoTrocar) {
  const barra = el('div', 'tabs especial-portas');
  for (const porta of PORTAS_ESPECIAIS) {
    const acesso = ctx.state.character?.[porta.campo] ?? null;
    const botao = el('button', porta.id === escolhida ? 'active' : null);
    botao.type = 'button';

    const chave = el('i', 'porta-chave');
    try {
      chave.append(itemCanvas(porta.item, 26));
    } catch {
      /* sem sprite o botão continua, só com o texto */
    }
    botao.append(chave);

    const texto = el('span', 'porta-texto');
    texto.append(el('b', null, porta.titulo));
    /*
     * O relógio embaixo do nome: as duas seções deixaram de aparecer juntas
     * quando viraram botões, e sem isto saber quanto sobra do OUTRO passe
     * pediria um clique.
     */
    texto.append(
      el('em', acesso ? 'ligado' : null, acesso ? `${duracaoCurta(Math.round(acesso.restante / 1000))} restantes` : 'sem acesso')
    );
    botao.append(texto);

    if (porta.bag) {
      const bag = el('i', 'porta-bag');
      try {
        bag.append(itemCanvas(porta.bag, 26));
      } catch {
        /* idem */
      }
      tipFor(bag, porta.bag);
      botao.append(bag);
    }

    botao.onclick = () => aoTrocar(porta.id);
    barra.append(botao);
  }
  return barra;
}

/*
 * ---- O cabeçalho da aba Especial Hunts: o premium ----
 *
 * Ele vale para as duas portas, e por isso aparece uma vez só, em cima das
 * duas. Mora aqui e não escrito em cada card porque a recusa do servidor chega
 * DEPOIS do clique — quem lê a regra antes de clicar não precisa da recusa.
 *
 * O estado vem pronto do servidor: `character.premium` é o que falta de premium
 * em ms. A conta é a mesma que o `podeEntrar` faz do lado de lá; se as
 * respostas discordarem, quem manda é o servidor, e o card recusa.
 */
function avisoDePremium(onde = 'Especial Hunts') {
  const character = ctx.state.character ?? {};
  const caixa = el('div', 'especial-aviso');

  const temPremium = (character.premium ?? 0) > 0;
  const premium = el('div', `especial-porta${temPremium ? ' ok' : ' falta'}`);
  premium.append(uiIcon(temPremium ? 'st-premium' : 'st-premium-off'));
  premium.append(
    el(
      'span',
      null,
      temPremium
        ? `Só premium entra nas ${onde} — o seu está ativo.`
        : `Só premium entra nas ${onde}. O seu não está ativo.`,
    ),
  );
  caixa.append(premium);
  return caixa;
}

/*
 * ---- E o bloco de UMA porta: o título, o relógio e a barra ----
 *
 * O mesmo desenho para as duas (ver `PORTAS_ESPECIAIS`). O que muda é o item
 * desenhado, o campo do personagem de onde o relógio sai e o nome.
 *
 * `character[porta.campo]` é o que o `acessoView` do servidor manda —
 * `{ restante, ate }`, ou nulo quando não há acesso.
 */
function blocoDaPorta(porta, quantasHunts) {
  const character = ctx.state.character ?? {};
  const caixa = el('div', 'especial-aviso especial-porta-bloco');

  const cabeca = el('div', 'especial-porta-cabeca');
  cabeca.append(el('h4', null, porta.titulo));
  cabeca.append(el('span', null, `${quantasHunts} ${quantasHunts === 1 ? 'caverna' : 'cavernas'}`));
  caixa.append(cabeca);
  caixa.append(el('p', 'shop-note', porta.legenda));

  /*
   * ---- A barra do acesso ----
   *
   * Ela mede contra as 24 horas CHEIAS do passe (`ACESSO_MS` do servidor), e
   * não contra o que sobrou quando a janela abriu: uma barra cujo cheio muda
   * de significado a cada abertura não mede nada. Assim ela sempre nasce cheia
   * ao usar o item e esvazia até o fim, que é o que uma barra de tempo promete.
   */
  const acesso = character[porta.campo] ?? null;
  const barra = el('div', `especial-acesso${acesso ? ' ligado' : ''}`);
  const titulo = el('div', 'especial-acesso-topo');
  titulo.append(itemCanvas(porta.item, 22));
  const rotulo = el('b', null, '');
  const relogio = el('em', 'especial-acesso-tempo', '');
  titulo.append(rotulo, relogio);
  barra.append(titulo);

  const trilho = el('div', 'especial-acesso-trilho');
  const preenche = el('i');
  trilho.append(preenche);
  barra.append(trilho);
  caixa.append(barra);

  /*
   * O relógio anda SOZINHO, de segundo em segundo.
   *
   * O `restante` do servidor só chega quando o estado é empurrado, e com a
   * janela aberta e o personagem parado isso pode demorar. Uma barra de tempo
   * congelada é pior que barra nenhuma — ela diz que sobra mais do que sobra.
   *
   * `ate` é o instante de vencimento no relógio do SERVIDOR, então a conta
   * local parte do `restante` que veio com ele e desconta o que passou aqui:
   * assim um relógio de máquina adiantado não faz o acesso vencer antes.
   */
  const partiuEm = Date.now();
  const inicial = acesso?.restante ?? 0;
  const pintar = () => {
    const resta = Math.max(0, inicial - (Date.now() - partiuEm));
    if (!resta) {
      barra.classList.remove('ligado');
      rotulo.textContent = `Sem acesso às ${porta.titulo}`;
      relogio.textContent = `${porta.titulo} (24 horas), na loja`;
      preenche.style.width = '0%';
      return;
    }
    rotulo.textContent = 'Acesso liberado';
    relogio.textContent = duracaoCurta(Math.round(resta / 1000)) + ' restantes';
    /*
     * A barra mede contra as 24 horas CHEIAS de um pergaminho, e por isso ela
     * ENCHE e para quando o tempo acumula: com 48 horas na conta ela fica em
     * 100% por um dia inteiro. É o certo — ela responde "ainda tenho?", e o
     * número ao lado responde "quanto".
     */
    preenche.style.width = `${Math.min(100, (resta / ACESSO_INSTANCE_MS) * 100).toFixed(1)}%`;
  };
  pintar();

  if (inicial > 0) {
    const tique = setInterval(() => {
      // A janela fechou (ou a aba trocou): o nó saiu da página e o relógio para.
      if (!trilho.isConnected) return void clearInterval(tique);
      pintar();
    }, 1000);
  }

  /*
   * ---- E o motivo de entrar, com a bag desenhada ----
   *
   * A frase e a figura ficam DENTRO do mesmo cartão do acesso, e não numa nota
   * solta embaixo: é ali que o olho já está quando ele lê "acesso liberado".
   *
   * O balão da bag é o de qualquer item — e, desde que o catálogo manda
   * `sacos`, ele lista as peças que podem sair. Uma linha aqui, e a pergunta
   * "vale a pena?" passa a ter resposta sem sair da tela.
   */
  if (porta.bag) {
    const premio = el('div', 'especial-premio');
    const figura = el('i', 'especial-premio-arte');
    try {
      figura.append(itemCanvas(porta.bag, 32));
    } catch {
      /* sem sprite a frase continua, só sem a figura */
    }
    tipFor(figura, porta.bag);
    premio.append(figura);
    premio.append(el('span', null, porta.premio ?? ''));
    caixa.append(premio);
  }

  return caixa;
}

/* O item do passe das Instance Hunts, para a loja saber pedir premium. */
const ITEM_INSTANCE_HUNTS = PORTAS_ESPECIAIS[0].item;
/* E o das Divine Hunts, pela mesma razão. */
const ITEM_DIVINE_HUNTS = PORTAS_ESPECIAIS[1].item;

/*
 * As estrelas do bestiary da criatura, com o vazio marcado.
 *
 * Elas dizem a dificuldade de um relance, e por isso ficam **debaixo do bicho**
 * — na lista de hunts e na ficha dele. Ao lado do nome elas competiam com o
 * nome; embaixo do desenho elas pertencem a ele.
 */
function estrelasDaCriatura(entry) {
  const quantas = entry?.stars ?? 0;
  return el('em', 'bestiary-stars', '\u2605'.repeat(quantas) + '\u2606'.repeat(Math.max(0, 5 - quantas)));
}

/*
 * Bicho animado com as estrelas embaixo — a peça que se repete nas duas telas.
 *
 * ---- A paleta vem do BESTIÁRIO, e não do arquivo da hunt ----
 *
 * Um outfit humanoide é desenhado em duas camadas: o desenho, quase branco, e
 * uma máscara que diz onde pintar cabeça, corpo, pernas e pés. Sem as cores a
 * máscara não é aplicada e todos saem com a mesma roupa clara — era por isso
 * que o card da Cults Carlin mostrava quatro bonecos iguais quando ali há
 * quatro criaturas diferentes. Bicho de corpo próprio (dragão, minotauro) não
 * usa máscara, e por isso o defeito só aparecia nos humanoides.
 *
 * As hunts exportadas do editor gravam `look` e não `colors`, então a cor sai
 * daqui. Do catálogo do bestiário de propósito, e não copiada para dentro do
 * arquivo: ele é lido do servidor a cada sessão, então repintar uma criatura no
 * `monsters.json` repinta as setenta e cinco hunts. Copiada, cada arquivo
 * guardaria a cor do dia em que foi exportado.
 */
function figuraDaCriatura(creature, catalog, tamanho) {
  const entry = catalog?.[creature.key];
  const caixa = el('div', 'hunt-bixo');
  const cores = creature.colors ?? entry?.colors ?? null;
  /*
   * ---- A criatura desenhada com sprite de ITEM ----
   *
   * `lookTypeEx` no `monster.lua`: bicho sem outfit, cuja aparencia e a de um
   * item. A Percht Queen e o Brain Head sao dois deles, e o card de boss dos
   * dois vinha com o quadrado vazio.
   *
   * O id vem do CATALOGO e nao do arquivo da hunt, pelo mesmo motivo que a cor
   * logo acima: as hunts foram exportadas antes de este campo existir, e o
   * bestiario e lido do servidor a cada sessao.
   */
  const item = creature.lookItem ?? entry?.lookItem ?? 0;
  if (outfitInfo(creature.look)) caixa.append(outfitCanvas(creature.look, cores, tamanho, 2, true));
  else if (item) caixa.append(itemCanvas(item, tamanho));
  else caixa.append(el('span', 'hunt-bicho-vazio'));
  if (entry) caixa.append(estrelasDaCriatura(entry));
  return caixa;
}

/*
 * ---- O filtro da lista de Aventuras ----
 *
 * São dezenove hunts e vão ser mais. Rolar tudo para achar a de level 100 é o
 * gesto que o dono pediu para tirar.
 *
 * O que ele guarda vive FORA da função de desenho, como os convidados: quem
 * filtrou, entrou numa hunt e voltou encontra a lista como deixou. Zerar a cada
 * abertura faria a pessoa refiltrar toda vez.
 *
 * Ele vale para Hunts e para Bosses — são a mesma lista com molduras
 * diferentes, e quem procura "de Edron" procura nas duas.
 */
const filtroDeHunts = { busca: '', ordem: 'level', soPodeEntrar: false };

/*
 * ---- Onde a lista estava quando alguem entrou num card ----
 *
 * Descer a lista, abrir uma hunt e voltar devolvia a pessoa ao TOPO — e quem
 * estava olhando as de level 400 tinha de rolar tudo de novo a cada hunt que
 * quisesse comparar. Comparar e' justamente o que se faz nessa tela.
 *
 * Entao "Voltar para as hunts" repoe a rolagem, e SO' ele: fechar a janela e
 * abrir de novo comeca no topo, como qualquer janela que se abre. A diferenca
 * entre os dois gestos e' a intencao — voltar e' continuar de onde parou,
 * reabrir e' comecar de novo.
 *
 * Uma memoria para cada aba: quem desceu a lista de bosses e depois a de hunts
 * tem duas posicoes para voltar, e uma so' devolveria a errada.
 */
const rolagemDaLista = { hunts: 0, bosses: 0 };
/*
 * Como se chegou na lista desta vez: 'voltar', 'nova' ou nada.
 *
 * O "nada" e' o caso que importa proteger: a janela se redesenha sozinha a cada
 * mudanca do personagem (ganhou XP, mudou o ouro), e nesses redesenhos a
 * rolagem NAO pode ser mexida — a lista saltaria para o topo debaixo de quem
 * esta' lendo, sem que ninguem tivesse clicado em nada.
 */
let chegadaNaLista = null;

/*
 * Sem acento e em minúsculas, para "piramide" achar "Pirâmide".
 *
 * Uma tabelinha e não `normalize('NFD')`: são catorze letras, e a tabela é
 * legível no lugar onde se lê o que a busca faz.
 */
const ACENTOS = {
  'á': 'a', 'à': 'a', 'â': 'a', 'ã': 'a', 'ä': 'a',
  'é': 'e', 'è': 'e', 'ê': 'e',
  'í': 'i', 'ì': 'i', 'î': 'i',
  'ó': 'o', 'ò': 'o', 'ô': 'o', 'õ': 'o', 'ö': 'o',
  'ú': 'u', 'ù': 'u', 'û': 'u', 'ü': 'u',
  'ç': 'c', 'ñ': 'n',
};
const semAcento = (texto) => {
  let saida = '';
  for (const letra of String(texto ?? '').toLowerCase()) saida += ACENTOS[letra] ?? letra;
  return saida;
};

/*
 * As ordens que a lista aceita.
 *
 * `level` é a que o servidor já manda, e continua sendo o padrão: é a pergunta
 * mais comum — "o que eu posso caçar agora?". As outras respondem as seguintes:
 * onde se ganha mais experiência, e onde cai mais tipo de coisa.
 *
 * `lootCount` é quantos TIPOS de item o elenco larga, e não quanto vale — o
 * servidor conta a lista de drops de cada bicho. Serve para achar a hunt de
 * encher a bolsa, que é o que o jogador quer dizer com "onde tem mais loot".
 */
const ORDENS_DA_LISTA = {
  level: { nome: 'Level', valor: (h) => h.level ?? 0 },
  exp: { nome: 'Experiência', valor: (h) => -(h.exp ?? 0) },
  loot: { nome: 'Tipos de loot', valor: (h) => -(h.lootCount ?? 0) },
  nome: { nome: 'Nome', valor: (h) => h.name ?? '' },
};

/** A lista peneirada e ordenada, do jeito que o filtro está agora. */
function huntsFiltradas(lista, meuLevel) {
  const termo = semAcento(filtroDeHunts.busca).trim();
  const ordem = ORDENS_DA_LISTA[filtroDeHunts.ordem] ?? ORDENS_DA_LISTA.level;

  const combina = (hunt) => {
    if (!termo) return true;
    /*
     * A busca alcança o BICHO, e não só o nome do lugar.
     *
     * Quem quer matar hydra não sabe que a hunt se chama "Oramond Hydras" — e
     * quem procura por "demon" tem de achar a catacumba. O nome do lugar
     * sozinho responderia só a quem já conhece a lista.
     */
    const campos = [hunt.name, hunt.blurb, ...(hunt.creatures ?? []).map((c) => c.name)];
    return campos.some((campo) => semAcento(campo).includes(termo));
  };

  /*
   * As FAVORITAS vêm primeiro, sempre, seja qual for a ordem escolhida.
   *
   * Favoritar é justamente dizer "esta eu quero à mão"; deixá-la no meio de
   * trinta e oito cards ordenados por level esvaziaria o gesto. Dentro do grupo
   * das favoritas a ordem escolhida continua valendo.
   */
  const favoritas = new Set(ctx.state.character.favoritas ?? []);

  return lista
    .filter((hunt) => combina(hunt) && (!filtroDeHunts.soPodeEntrar || meuLevel >= hunt.level))
    .sort((a, b) => {
      const fa = favoritas.has(a.id) ? 0 : 1;
      const fb = favoritas.has(b.id) ? 0 : 1;
      if (fa !== fb) return fa - fb;
      const va = ordem.valor(a);
      const vb = ordem.valor(b);
      // Empate desfeito pelo nome, para a ordem não dançar entre redesenhos.
      if (va === vb) return String(a.name).localeCompare(String(b.name));
      return typeof va === 'string' ? va.localeCompare(vb) : va - vb;
    });
}

/*
 * A barra do filtro, encostada à direita da fileira de abas.
 *
 * Ela entra DENTRO da `.tabs` (que o `tabbedModal` acabou de pôr no corpo) em
 * vez de virar uma linha própria: é meia dúzia de controles, e uma faixa só
 * para eles comeria a altura de um card. `margin-left: auto` no CSS faz o
 * encosto à direita.
 *
 * `aoMudar` redesenha SÓ a grade. Redesenhar o painel inteiro tiraria o cursor
 * do campo de busca no meio da digitação — o mesmo defeito que a janela da
 * troca teve com o campo de ouro.
 */
function barraDeFiltro(aoMudar) {
  const barra = el('div', 'hunt-filtros');

  const busca = document.createElement('input');
  busca.className = 'search';
  busca.type = 'search';
  busca.placeholder = 'lugar ou bicho...';
  busca.value = filtroDeHunts.busca;
  busca.oninput = () => {
    filtroDeHunts.busca = busca.value;
    aoMudar();
  };

  const ordem = document.createElement('select');
  for (const [id, entrada] of Object.entries(ORDENS_DA_LISTA)) {
    ordem.append(new Option(entrada.nome, id));
  }
  ordem.value = filtroDeHunts.ordem;
  ordem.onchange = () => {
    filtroDeHunts.ordem = ordem.value;
    aoMudar();
  };

  const rotulo = el('label', 'hunt-filtro-check');
  const caixa = document.createElement('input');
  caixa.type = 'checkbox';
  caixa.checked = filtroDeHunts.soPodeEntrar;
  caixa.onchange = () => {
    filtroDeHunts.soPodeEntrar = caixa.checked;
    aoMudar();
  };
  rotulo.append(caixa, el('span', null, 'no meu level'));

  barra.append(busca, ordem, rotulo);
  return barra;
}

/*
 * ---- A rotação automática de bosses ----
 *
 * "Poderia criar uma forma do personagem rotacionar todos os boss (ou só os
 * favoritos) como é feito nas hunts. Assim nao teria que ficar clicando em cada
 * um e esperar a batalha acabar."
 *
 * A faixa fica NO ALTO da aba de Bosses, e não num card no meio da grade: ela
 * fala da lista inteira, e um card dentro da lista falando sobre a lista seria
 * lido como mais um boss.
 *
 * O que ela mostra muda conforme o estado, e os quatro estados são bem
 * diferentes um do outro — desligado, rodando, leva cheia esperando, e passe
 * ativo. A frase de cada um responde a pergunta daquele estado, e não a média
 * das quatro.
 */
/** Abre a Store em Serviços, onde mora o passe do Auto Boss. */
function irParaOPasseNaLoja() {
  openStore();
  ctx.tabs.storeSection = 'services';
  ctx.tabs.storeBusca = '';
  ctx.redraw?.();
}

function faixaDoAutoBoss(lista) {
  const { state, send } = ctx;
  const auto = state.character.autoBoss;
  const caixa = el('div', `auto-boss${auto?.ligado ? ' rodando' : ''}${auto?.passe ? ' com-passe' : ''}`);
  if (!auto) return caixa;

  const topo = el('div', 'auto-boss-topo');
  topo.append(el('b', null, 'Auto Boss'));
  /*
   * O selo do passe da conta, com quanto falta. Pedido do dono (15/09): "deixar
   * isso mais bonito". O texto de baixo continua dizendo as regras.
   */
  if (auto.passe) {
    const selo = el('span', 'auto-boss-selo', '∞ Sem limite · conta');
    const falta = (auto.passeAte ?? 0) - Date.now();
    if (falta > 0) selo.append(el('i', null, formatLeft(falta)));
    topo.append(selo);
  }

  /*
   * O contador da leva, sempre visível.
   *
   * É o número que decide se vale a pena ligar agora: com catorze das quinze
   * gastas, quem ligar roda um boss e para. Escondê-lo até a leva fechar faria
   * a espera de seis horas chegar sem aviso.
   */
  if (auto.passe) {
    topo.append(el('span', 'auto-boss-passe', 'quantos bosses quiser, sem espera'));
  } else if (auto.espera > 0) {
    topo.append(el('span', 'auto-boss-espera', `próxima leva em ${formatLeft(auto.espera)}`));
  } else {
    topo.append(el('span', null, `${auto.usados} de ${auto.teto} bosses desta leva`));
  }
  caixa.append(topo);

  caixa.append(
    el(
      'p',
      null,
      auto.ligado
        ? `Rodando: ${auto.nomes.join(' → ')}`
        : auto.semLimite
          ? 'Monte a fila e o personagem enfrenta um boss depois do outro, sozinho. Entram só os bosses em que você e a party têm level, acesso e cooldown livre.'
          : `Escolha até ${auto.teto} bosses e o personagem entra em um depois do outro sozinho. Cada leva de ${auto.teto} entradas pede ${Math.round(auto.esperaTotal / 3600000)} horas de espera — e o cooldown de cada boss continua valendo.`,
    ),
  );

  /*
   * ---- A espera é o único momento em que o passe se explica sozinho ----
   *
   * "caso a pessoa esteja em coldown do autoboss sem ter comprado o autoboss da
   * store tem que aparecer la informando que ela pode comprar o autoboss 7 dias
   * sem coldown e botao clicavel pra store".
   *
   * O produto existia na loja e não existia AQUI, que é o único lugar do jogo
   * em que alguém quer saber dele: numa vitrine com sete serviços, "Auto Boss
   * sem espera" não diz nada a quem nunca esbarrou na espera. Quem está lendo
   * "próxima leva em 4h12" está exatamente com a pergunta que ele responde.
   *
   * A frase diz o que ele NÃO tira, e é a linha mais importante da caixa: o
   * nome que o dono deu ao produto ("sem cooldown") promete mais do que ele
   * entrega, e descobrir isso depois de pagar 150 coins é um pedido de
   * reembolso. Aqui está antes do clique.
   *
   * Só sem passe: para quem já comprou, a mesma caixa seria um anúncio de uma
   * coisa que ele já tem.
   */
  if (auto.espera > 0 && !auto.passe) {
    const oferta = el('div', 'auto-boss-oferta');
    oferta.append(el('b', null, 'Auto Boss sem limite (vale para a conta)'));
    /*
     * O preço vem da LOJA, e não escrito aqui.
     *
     * Estava escrito: "Por 150 Draevor Coins...". O passe mudou de preço e esta
     * frase continuaria anunciando o antigo, num lugar em que ninguém iria
     * procurar — e a pessoa clicaria em "Ver na Store" para encontrar
     * outro número. Uma promessa de preço tem de sair do mesmo lugar que cobra.
     *
     * Quando a loja ainda não chegou nesta aba, a frase sai SEM número em vez
     * de sair com um chute: o resto dela já vende o produto sozinho.
     */
    const passes = (ctx.state.store?.services ?? []).filter((s) => s.kind === 'autoBoss');
    const precos = passes
      .slice()
      .sort((um, outro) => (um.days ?? 0) - (outro.days ?? 0))
      .map((s) => `${s.days} dias por ${money(s.coins)} Draevor Coins`)
      .join(', ou ');
    oferta.append(
      el(
        'em',
        null,
        (precos ? `${precos[0].toUpperCase()}${precos.slice(1)}: t` : 'T') +
          'odos os personagens da conta ficam sem o limite de 15 bosses e sem a espera de 6 horas: ' +
          'coloque quantos bosses quiser na lista. O cooldown de cada boss continua valendo — o passe não o encurta.',
      ),
    );
    const verNaLoja = el('button', 'primary', 'Ver na Store');
    verNaLoja.onclick = irParaOPasseNaLoja;
    oferta.append(verNaLoja);
    caixa.append(oferta);
  }

  const acoes = el('div', 'confirm-actions auto-boss-acoes');
  /*
   * ---- O atalho pequeno para a store ----
   *
   * O dono (15/09): "pra quem não tem o auto boss ainda, um botãozinho pequeno
   * 'adquira auto-boss sem espera na store', e ao clicar leva pra store". Na
   * espera a oferta grande de cima já faz isso, então ele só aparece fora dela.
   */
  if (!auto.passe && !(auto.espera > 0)) {
    const atalho = el('button', 'auto-boss-atalho', '✦ Adquira Auto Boss sem espera na Store');
    tipTexto(atalho, 'Sem limite de bosses e sem a espera de 6 horas, por 7 dias, em todos os personagens da conta.');
    atalho.onclick = irParaOPasseNaLoja;
    acoes.append(atalho);
  }
  if (auto.ligado) {
    const parar = el('button', 'danger', 'Parar o Auto Boss');
    /*
     * A MESMA porta da faixa do alto da tela (`pararAutoBoss`, em main.mjs):
     * ela pergunta antes quando há uma sala em curso. Este botão mandava o
     * `stop` direto, e era o único jeito de perder um boss em cooldown sem
     * ninguém avisar — bastava clicar aqui em vez de lá em cima.
     */
    parar.onclick = () => (ctx.pararAutoBoss ? ctx.pararAutoBoss() : send({ t: 'autoBoss', action: 'stop' }));
    acoes.append(parar);
  } else {
    // `brilho`: o botão que começa a rotação chama o olho. Ver `.auto-boss-brilho` no style.css.
    const montar = el('button', 'primary auto-boss-brilho', auto.bosses.length ? 'Mudar a lista e começar' : 'Escolher os bosses');
    /*
     * A espera trava o botão, e o título diz por quê.
     *
     * Deixá-lo clicável para o servidor recusar seria fazer o jogador
     * atravessar duas telas para descobrir o que a faixa já sabe.
     */
    if (auto.espera > 0 && !auto.passe) {
      montar.disabled = true;
      montar.title = `A próxima leva abre em ${formatLeft(auto.espera)}.`;
    }
    if (state.hunt) {
      montar.disabled = true;
      montar.title = 'Saia da caçada antes de ligar o Auto Boss.';
    }
    montar.onclick = () => escolherAutoBoss(lista);
    acoes.append(montar);
  }
  caixa.append(acoes);
  return caixa;
}

/*
 * ---- Montar a lista da rotação ----
 *
 * A mesma grade do ciclo de hunts (`ciclo-card`), e não uma parecida: são o
 * mesmo gesto — marcar vários numa ordem que importa — e duas telas parecidas
 * divergiriam na primeira vez que alguém mexesse numa só.
 *
 * ---- Boss em cooldown vai para o FIM, apagado, e não se marca ----
 *
 * "na hora de escolher a lista do autoboss os que estao com coldown tem que
 * aparecer apagados no final e sem ter como escolher".
 *
 * A tela fazia o contrário, e por uma razão que continua verdadeira: um boss de
 * doze horas está preso na maior parte do dia, e uma lista que só aceita o que
 * está livre AGORA precisa ser remontada toda vez — que é o trabalho que a
 * rotação existe para tirar.
 *
 * O que resolve as duas coisas ao mesmo tempo são as SEQUÊNCIAS GUARDADAS, aqui
 * embaixo. Marcar passa a ser sobre o que dá para fazer agora; a lista de
 * sempre fica salva com nome e volta inteira num clique — inclusive com os
 * bosses presos, que a rotação pula sozinha na hora de entrar. Uma coisa é
 * escolher, a outra é lembrar, e elas deixaram de ser o mesmo gesto.
 *
 * Já marcado e depois travado (veio de uma sequência guardada) continua
 * clicável — para TIRAR. Impedir de tirar não estava no pedido, e prender o
 * jogador a um card que ele não pode nem escolher nem desmarcar seria o pior
 * dos dois mundos.
 */
/*
 * ---- As sequências guardadas, e os dois atalhos ----
 *
 * "tem que ter como salvar uma lista de sequencia ou ir apenas em bosses
 * favoritado e etc".
 *
 * São a outra metade da regra nova de que boss em cooldown não se marca (ver o
 * comentário de `escolherAutoBoss`). Sem elas, quem montou uma lista de doze
 * bosses ontem teria de montá-la de novo hoje, e amanhã, e sempre com um
 * pedaço faltando — porque metade estaria presa no relógio na hora em que ele
 * abrisse a tela.
 *
 * Uma sequência é a lista COMO ELE A QUER, e não como o relógio a permite: ela
 * guarda os ids todos, volta inteira num clique, e a rotação pula na hora de
 * entrar o que estiver preso. É a mesma divisão de trabalho do resto do jogo —
 * a escolha é do jogador, o relógio é do servidor.
 *
 * Os favoritos entram aqui e não como uma terceira lista guardada porque eles
 * JÁ são uma lista que o jogador mantém, com o coração no card de cada boss.
 * Repeti-la seria pedir para ele dizer duas vezes a mesma coisa.
 */
function faixaDasSequencias(escolhidos, abertas, teto, desenhar) {
  const { state, send } = ctx;
  const auto = state.character.autoBoss ?? {};
  const guardadas = auto.listas ?? [];
  const maximo = auto.listasMax ?? 5;
  const podeEntrar = new Set(abertas.map((boss) => boss.id));
  // Os atalhos ("só os favoritos", "todos os livres") pulam também o que a party segura.
  const esperaDe = (id) => esperaNoAuto(id).falta;

  const caixa = el('div', 'auto-boss-listas');

  // ---- o que já está guardado ----
  const linha = el('div', 'auto-boss-listas-linha');
  linha.append(el('b', null, 'Sequências'));
  if (!guardadas.length) {
    linha.append(el('em', null, 'nenhuma guardada ainda — monte uma e dê um nome abaixo'));
  }
  for (const guardada of guardadas) {
    const pilula = el('span', 'auto-boss-lista');
    /*
     * Carregar SUBSTITUI o que está marcado, e não soma.
     *
     * Somar daria uma lista de 27 cortada em 15 sem dizer quais sobraram — e
     * "carregar a minha sequência" quer dizer ver a minha sequência, não uma
     * mistura dela com o que estava na tela.
     */
    const usar = el('button', 'ghost', `${guardada.nome} (${guardada.ids.length})`);
    /*
     * Só os que este personagem ainda pode enfrentar. Um boss de task fechada
     * não abre mais para ele, e carregá-lo daria um card marcado que não existe
     * na grade — o contador diria 12 com 11 na tela.
     *
     * O COOLDOWN não peneira: é justamente o que a sequência existe para
     * atravessar.
     */
    usar.onclick = () => {
      escolhidos.length = 0;
      for (const id of guardada.ids) if (podeEntrar.has(id) && escolhidos.length < teto) escolhidos.push(id);
      desenhar();
    };
    const fora = el('button', 'ghost auto-boss-lista-x', '×');
    tipTexto(fora, `Apagar a sequência "${guardada.nome}".`);
    fora.onclick = () => send({ t: 'autoBoss', action: 'remove', nome: guardada.nome });
    pilula.append(usar, fora);
    linha.append(pilula);
  }
  caixa.append(linha);

  // ---- guardar a que está montada ----
  const gravar = el('div', 'auto-boss-listas-linha');
  const nome = document.createElement('input');
  nome.type = 'text';
  nome.className = 'search';
  nome.maxLength = 24;
  nome.placeholder = 'nome da sequência (ex.: os de sexta)';
  const guardar = el('button', 'ghost', 'Guardar esta sequência');
  /*
   * Só com boss marcado e com nome: guardar uma lista vazia não é um erro que
   * mereça uma viagem até o servidor para ouvir não.
   */
  const conferir = () => {
    guardar.disabled = !escolhidos.length || !nome.value.trim();
  };
  nome.oninput = conferir;
  guardar.onclick = () => {
    send({ t: 'autoBoss', action: 'save', nome: nome.value.trim(), ids: [...escolhidos] });
    nome.value = '';
    conferir();
  };
  conferir();
  gravar.append(nome, guardar);
  if (guardadas.length >= maximo) {
    gravar.append(el('em', null, `${maximo} é o limite — salvar com um nome já usado regrava aquela.`));
  }
  caixa.append(gravar);

  // ---- os atalhos ----
  const atalhos = el('div', 'auto-boss-listas-linha');
  /*
   * "só os favoritos": os que o jogador marcou com o coração na aba de Bosses,
   * na ordem em que eles aparecem na lista — e sem os que estão em cooldown,
   * porque este botão é um jeito rápido de marcar, e marcar preso é justamente
   * o que a tela deixou de fazer.
   */
  const favoritas = new Set(state.character.favoritas ?? []);
  const favoritos = abertas.filter((boss) => favoritas.has(boss.id) && esperaDe(boss.id) <= 0);
  const soFavoritos = el('button', 'ghost', `Só os favoritos (${favoritos.length})`);
  soFavoritos.disabled = !favoritos.length;
  if (!favoritos.length) {
    tipTexto(soFavoritos, 'Nenhum boss favoritado e livre agora. O coração fica no canto do card, na aba de Bosses.');
  }
  soFavoritos.onclick = () => {
    escolhidos.length = 0;
    for (const boss of favoritos.slice(0, teto)) escolhidos.push(boss.id);
    desenhar();
  };

  /*
   * "todos os livres": o pedido original do jogador era "rotacionar todos os
   * boss (ou só os favoritos)", e sem este botão marcar quinze é quinze
   * cliques.
   */
  const livres = abertas.filter((boss) => esperaDe(boss.id) <= 0);
  const todos = el('button', 'ghost', `Todos os livres (${Math.min(livres.length, teto)})`);
  todos.disabled = !livres.length;
  todos.onclick = () => {
    escolhidos.length = 0;
    for (const boss of livres.slice(0, teto)) escolhidos.push(boss.id);
    desenhar();
  };

  const limpar = el('button', 'ghost', 'Limpar');
  limpar.disabled = !escolhidos.length;
  limpar.onclick = () => {
    escolhidos.length = 0;
    desenhar();
  };

  atalhos.append(soFavoritos, todos, limpar);
  caixa.append(atalhos);
  return caixa;
}

/*
 * ---- A espera de um boss para a rotação: a minha OU a de alguém da party ----
 *
 * O dono (15/09): "o boss que estiver em cooldown deixa apagado no final da
 * fila, informando quem está em cooldown". A maior espera do time manda — é
 * ela que a rotação respeita (`proximoBossDoAuto`). A dos companheiros vem de
 * `autoBoss.presosPelaParty` (o instante e o nome de quem segura).
 *
 * `{ falta, quem }`, com `quem` nulo quando a espera é minha.
 */
function esperaNoAuto(id) {
  const minha = ctx.state.character.bossCooldowns?.[id] ?? 0;
  const preso = ctx.state.character.autoBoss?.presosPelaParty?.[id];
  const doTime = preso ? preso.ate - Date.now() : 0;
  return doTime > minha ? { falta: doTime, quem: preso.quem } : { falta: minha, quem: null };
}

function escolherAutoBoss(lista) {
  const { state, send } = ctx;
  // Com o passe da conta a lista não tem teto. Ver `tetoDaLista`, no servidor.
  const teto = state.character.autoBoss?.semLimite ? Infinity : state.character.autoBoss?.teto ?? 15;
  const escolhidos = [...(state.character.autoBoss?.bosses ?? [])];

  ctx.openModal('Auto Boss', (body) => {
    const desenhar = () => {
      body.replaceChildren();

      const voltar = el('button', 'ghost', '‹ voltar');
      voltar.onclick = () => {
        ctx.closeModal();
        chegadaNaLista = 'voltar';
        openHunts();
      };
      body.append(voltar);

      body.append(
        el(
          'p',
          'shop-note',
          teto === Infinity
            ? 'Sem limite (passe da conta): marque quantos bosses quiser. O personagem entra em um depois do outro, na ordem em que você marcou, e pula os que estiverem em cooldown. Morrer para a rotação.'
            : `Marque até ${teto} bosses. O personagem entra em um depois do outro, na ordem em que você marcou, e pula os que estiverem em cooldown. Morrer para a rotação.`,
        ),
      );

      /*
       * Só o que ele PODE enfrentar: level e boss task. O cooldown não peneira
       * — ver o comentário no alto desta função.
       */
      const abertas = (lista ?? []).filter((boss) => {
        if (state.character.level < boss.level) return false;
        const task = (state.character.bossTasks ?? []).find((linha) => linha.boss === boss.id);
        return !task || (task.feito && !task.matou);
      });

      // A minha espera ou a de alguém da party, a maior. Ver `esperaNoAuto`.
      const esperaDe = (id) => esperaNoAuto(id).falta;

      // ---- as sequências guardadas, e os dois atalhos ----
      body.append(faixaDasSequencias(escolhidos, abertas, teto, desenhar));

      /*
       * Os presos vão para o fim, e a ordem entre os livres não muda.
       *
       * `sort` é estável no JavaScript moderno, então esta linha só empurra os
       * travados para baixo — a ordenação por nome/level que a lista já trazia
       * continua valendo dentro de cada metade.
       */
      const ordenadas = abertas.slice().sort((a, b) => (esperaDe(a.id) > 0 ? 1 : 0) - (esperaDe(b.id) > 0 ? 1 : 0));

      const grade = el('div', 'ciclo-grade');
      for (const boss of ordenadas) {
        const posicao = escolhidos.indexOf(boss.id);
        const marcado = posicao >= 0;
        const cheio = escolhidos.length >= teto;
        const cooldown = esperaDe(boss.id);
        const preso = cooldown > 0;

        const card = el('button', `ciclo-card${marcado ? ' escolhido' : ''}${preso ? ' em-cooldown' : ''}`);
        /*
         * Travado de três jeitos diferentes, e eles não são o mesmo:
         *   - em cooldown e não marcado: não dá para escolher (o pedido);
         *   - lista cheia e não marcado: não cabe mais;
         *   - marcado: sempre clicável, para desmarcar.
         */
        card.disabled = !marcado && (cheio || preso);
        if (marcado) card.append(el('i', 'ciclo-ordem', String(posicao + 1)));

        const bichos = el('div', 'ciclo-bichos');
        for (const creature of (boss.creatures ?? []).slice(0, 3)) {
          bichos.append(figuraDaCriatura(creature, state.catalog.bestiary, 30));
        }
        card.append(bichos);
        card.append(el('b', null, boss.name));
        const quem = esperaNoAuto(boss.id).quem;
        card.append(
          el('span', null, preso ? `${quem ? `${quem} em cooldown` : 'em cooldown'} · volta em ${formatLeft(cooldown)}` : `level ${boss.level}`),
        );
        if (preso) {
          const deQuem = quem ? `${quem} (da sua party) está em cooldown neste boss` : 'Você está em cooldown neste boss';
          tipTexto(
            card,
            marcado
              ? `${deQuem} — a rotação vai pulá-lo. Clique para tirar da lista.`
              : `${deQuem}: só dá para marcar quando o relógio virar. Guarde a sequência para não precisar remontá-la.`,
          );
        }

        card.onclick = () => {
          const onde = escolhidos.indexOf(boss.id);
          if (onde >= 0) escolhidos.splice(onde, 1);
          else if (!preso && escolhidos.length < teto) escolhidos.push(boss.id);
          desenhar();
        };
        grade.append(card);
      }
      if (!abertas.length) grade.append(el('p', 'empty', 'Nenhum boss liberado para você ainda.'));
      body.append(grade);

      const roda = el('div', 'run-preview');
      for (const [passo, id] of escolhidos.entries()) {
        const boss = abertas.find((entry) => entry.id === id);
        roda.append(el('span', passo === 0 ? 'first' : null, boss?.name ?? id));
      }
      if (!escolhidos.length) roda.append(el('em', 'words', 'nenhum boss marcado'));
      body.append(roda);

      /*
       * Quantos DESTES dá para entrar agora.
       *
       * Uma lista inteira em cooldown liga a rotação e ela para no mesmo
       * segundo, dizendo "todos em cooldown" — tecnicamente certo e irritante.
       * A conta aqui responde antes do clique.
       */
      const prontos = escolhidos.filter((id) => !(esperaDe(id) > 0)).length;
      if (escolhidos.length && !prontos) {
        body.append(
          el('p', 'relatorio-motivo', 'Todos os marcados estão em cooldown — a rotação não teria por onde começar.'),
        );
      }

      /*
       * ---- Com party, a rotação também passa pelo LOBBY ----
       *
       * "auto boss sequencia de boss tem que da pra fazer em party."
       *
       * A mesma decisão de `startRun`, e no mesmo formato: quem está sozinho
       * liga com um clique; quem tem party chama o time, todo mundo dá pronto e
       * a sequência começa junta. A lista continua sendo a do líder — é ela que
       * a rotação vai andar —, e a peneira do cooldown de cada um acontece no
       * servidor, sala por sala.
       */
      const party = state.character?.party;
      const emParty = party?.membros?.length > 1;

      if (emParty) {
        body.append(
          el(
            'p',
            'gate-note',
            party.souLider
              ? 'Você tem party: o time vai junto. A sequência só entra nos bosses em que TODOS estiverem sem espera — os demais são pulados.'
              : `${party.lider} é o líder da party — ele monta a sequência e chama o time.`
          )
        );
      }

      const acoes = el('div', 'confirm-actions');
      const cancelar = el('button', 'ghost', 'Cancelar');
      cancelar.onclick = () => ctx.closeModal();
      const confirmar = el(
        'button',
        'primary',
        emParty && party.souLider ? `Chamar a party (${escolhidos.length})` : `Começar (${escolhidos.length})`
      );
      confirmar.disabled = !escolhidos.length || !prontos || (emParty && !party.souLider);
      confirmar.onclick = () => {
        if (emParty && party.souLider) {
          send({ t: 'lobby', action: 'armar', tipo: 'autoboss', ids: escolhidos });
          ctx.closeModal();
          return openLobby();
        }
        send({ t: 'autoBoss', action: 'start', ids: escolhidos });
        ctx.closeModal();
      };
      acoes.append(cancelar, confirmar);
      body.append(acoes);
    };
    ctx.redraw = desenhar;
    desenhar();
  });
}

/*
 * O card da hunt: o bicho, o nome, a descrição, o level e as estrelas.
 *
 * Ele tinha um botão "Detalhes" no canto, mais três números de rodapé (xp, hp,
 * drops) que ninguém compara entre vinte cards. Tudo isso virava ruído em volta
 * da única coisa que a lista precisa responder: o que mora aqui e se eu já
 * posso entrar. Os detalhes mudaram de lugar — estão dentro da hunt, junto da
 * decisão de entrar nela.
 */
/*
 * ---- O atalho para a área de Boss Diários, no topo da aba de Bosses ----
 *
 * O dono: "na aba de bosses coloque um atalho que levaria pra área de bosses
 *  diário ok, faz meio que chamativo, e quando tiver algum boss lá ativo
 *  informar boss ativo, e ao deixar o mouse por cima mostra qual boss tem na
 *  sala no momento, e ao clicar leva pra sala".
 *
 * ---- Por que ele não é um card como os outros ----
 *
 * Os 87 cards desta aba são SALAS: cada um tem level, cooldown de doze horas e
 * uma porta que abre uma vez por dia. A arena não é nada disso — é um lugar
 * público, sem level, sem cooldown, com um boss que a equipe põe lá. Um card
 * igual aos outros prometeria as regras dos outros.
 *
 * Então é uma faixa, em cima de todos, com a cara de aviso: quem abre a aba de
 * Bosses num dia de Ghazbaran tem de ver isso antes de rolar a lista.
 *
 * ---- E ele diz QUEM está lá ----
 *
 * A lista vem do servidor e só é espalhada quando muda (ver
 * `vigiarBossesDaArena`, no index.mjs). Vazia, a faixa continua ali como porta
 * — o caminho para a arena não depende de haver boss —, mas sem o selo aceso:
 * um "boss ativo" que está sempre aceso não avisa nada.
 */
/*
 * Redesenha a janela que estiver aberta.
 *
 * O `ctx.redraw` é posto por quem abriu o modal, e chamá-lo de fora é o que
 * deixa uma notícia do servidor — "entrou um boss na arena" — trocar o selo do
 * atalho sem a pessoa fechar e abrir Aventuras. Sem janela aberta não faz nada.
 */
export function redesenharJanelaAberta() {
  /*
   * `ctx?` e não `ctx.`: a lista de bosses da arena vem dentro do `hello`, que
   * chega ANTES de o jogador escolher o personagem — e o `initPanels`, que põe
   * o `ctx`, só roda depois disso. Sem a interrogação, todo login começava com
   * um TypeError no console.
   */
  ctx?.redraw?.();
}

/*
 * A grade de loot dos bosses que estão na arena, montada uma vez.
 *
 * Com mais de um lá dentro sai uma seção por boss: somar as tabelas daria uma
 * parede de itens sem dizer de quem cai o quê, que é justamente a pergunta.
 *
 * O teto de 40 linhas é o mesmo da ficha do bestiary, do cartaz e da barra de
 * dentro da arena — 33 bichos deste jogo passam disso.
 */
function pintarLootDaArena(caixa, dentro) {
  caixa.innerHTML = '';
  for (const boss of dentro) {
    const entry = ctx.state.catalog?.bestiary?.[boss.key];
    if (!entry) continue;
    caixa.append(el('b', null, `O que ${entry.name} solta`));
    const lista = lootComGemas({ ...entry, loot: (entry.loot ?? []).slice(0, 40), boss: true });
    const grade = el('div', 'bag');
    let quantos = 0;
    for (const drop of lista) {
      if (!drop.id || !ctx.state.items[drop.id]) continue;
      const cela = el('div', 'cell');
      cela.append(itemCanvas(drop.id, 30));
      tipFor(cela, drop.id, `${(drop.chance * 100).toFixed(drop.chance < 0.01 ? 2 : 1)}% de chance`);
      grade.append(cela);
      quantos++;
    }
    caixa.append(quantos ? grade : el('p', 'empty', 'Sem tabela de loot.'));
  }
  if (!caixa.childElementCount) caixa.append(el('p', 'empty', 'Sem loot conhecido.'));
}

function atalhoDaArenaDeBoss() {
  const dentro = ctx.state.bossesNaArena ?? [];
  const ativo = dentro.length > 0;
  const faixa = el('button', `arena-atalho${ativo ? ' ativo' : ''}`);
  faixa.type = 'button';

  const arte = el('div', 'arena-atalho-arte');
  /*
   * O desenho é o do PRIMEIRO boss de lá, tirado do bestiário pela chave —
   * mesmo caminho do cartaz e da barra de vida. Sem ninguém dentro fica a
   * caveira do ícone da aba, que é o que a faixa é quando é só uma porta.
   */
  const primeiro = dentro[0];
  const entry = primeiro ? ctx.state.catalog?.bestiary?.[primeiro.key] : null;
  if (entry && outfitInfo(entry.look)) arte.append(outfitCanvas(entry.look, entry.colors, 40, 2, true));
  else if (entry?.lookItem) arte.append(itemCanvas(entry.lookItem, 40));
  else arte.append(el('span', 'arena-atalho-vazio', '☠'));

  const dizeres = el('div', 'arena-atalho-dizeres');
  dizeres.append(el('b', null, 'Área de Boss Diários'));
  dizeres.append(
    el(
      'span',
      null,
      ativo
        ? dentro.length === 1
          ? `${dentro[0].nome} está na área agora.`
          : `${dentro.length} bosses estão na área agora.`
        : 'Nenhum boss na área. O próximo entra pela rotação.'
    )
  );

  /*
   * ---- A vida, em barra ----
   *
   * "tem que mostrar a vida atual do boss da área de boss diário (essas coisas
   *  não podem causar lag ok)".
   *
   * O número vem do servidor já arredondado em por cento, e só é espalhado
   * quando MUDA de ponto (ver `vigiarBossesDaArena`, no index.mjs): numa luta
   * inteira são cem avisos, e com a área parada, nenhum. Aqui não há relógio
   * nenhum — a faixa se redesenha quando a notícia chega, e só.
   *
   * Uma barra por boss, com o nome em cima quando há mais de um: com dois
   * dentro, uma barra sem dono não diz de quem é a vida que está caindo.
   */
  if (ativo) {
    const barras = el('div', 'arena-atalho-vidas');
    for (const boss of dentro) {
      const pct = Math.max(0, Math.min(100, Number(boss.pct ?? 100)));
      const linha = el('div', `arena-atalho-vida${pct <= 33 ? ' aperto' : ''}`);
      if (dentro.length > 1) linha.append(el('em', null, boss.nome));
      const trilho = el('div', 'arena-atalho-trilho');
      const cheio = el('i', null);
      cheio.style.width = `${pct}%`;
      trilho.append(cheio, el('span', null, `${pct}%`));
      linha.append(trilho);
      barras.append(linha);
    }
    dizeres.append(barras);
  }

  faixa.append(arte, dizeres);

  /*
   * ---- E o loot, no mesmo gesto da barra de dentro ----
   *
   * "e negócio pra ver loot também."
   *
   * Sai do BESTIÁRIO, que o cliente já tem inteiro: nenhum byte a mais no fio
   * para isto. Passar o mouse abre, clicar prende para quem quiser ler com
   * calma, e no celular o clique é o único gesto que há.
   *
   * O `stopPropagation` não é detalhe: a faixa inteira é um botão que ENTRA na
   * arena, e sem ele olhar o loot mandaria a pessoa para dentro da sala.
   */
  if (ativo) {
    const caixaDoLoot = el('div', 'arena-atalho-loot-caixa');
    caixaDoLoot.hidden = true;
    const botao = el('button', 'arena-atalho-loot');
    botao.type = 'button';
    botao.textContent = 'Loot';

    let presa = false;
    const abrir = () => {
      if (!caixaDoLoot.childElementCount) pintarLootDaArena(caixaDoLoot, dentro);
      caixaDoLoot.hidden = false;
      botao.classList.add('aberto');
    };
    const fechar = () => {
      if (presa) return;
      caixaDoLoot.hidden = true;
      botao.classList.remove('aberto');
    };
    botao.addEventListener('mouseenter', abrir);
    botao.addEventListener('mouseleave', fechar);
    caixaDoLoot.addEventListener('mouseleave', fechar);
    botao.addEventListener('click', (evento) => {
      evento.stopPropagation();
      presa = !presa;
      if (presa) abrir();
      else { caixaDoLoot.hidden = true; botao.classList.remove('aberto'); }
    });
    caixaDoLoot.addEventListener('click', (evento) => evento.stopPropagation());
    faixa.append(botao, caixaDoLoot);
  }

  if (ativo) faixa.append(el('span', 'arena-atalho-selo', 'Boss ativo'));

  /*
   * O balão lista TODOS, com nome — é o "ao deixar o mouse por cima mostra qual
   * boss tem na sala". A frase de dentro da faixa só cabe um nome; o balão cabe
   * os que houver.
   */
  const quebra = String.fromCharCode(10);
  tipTexto(
    faixa,
    ativo
      ? ['Na área agora:', ...dentro.map((b) => '\u2022 ' + b.nome), '', 'Clique para entrar.'].join(quebra)
      : 'A arena onde a equipe solta os bosses do dia. Clique para entrar.'
  );

  /*
   * Entrar pela MESMA porta do portal do templo: o servidor recusa quem está
   * numa caçada, e é ele quem manda o recado. Duplicar a regra aqui daria duas
   * respostas diferentes para a mesma pergunta no dia em que uma mudasse.
   */
  faixa.onclick = () => {
    ctx.send({ t: 'entrarNaArena' });
    ctx.closeModal?.();
  };
  return faixa;
}

function huntCards(body, list, isBoss) {
  const { state } = ctx;
  const catalog = state.catalog.bestiary;
  // Boss vira uma pilha de seções (cada uma com a sua grade dentro); hunt
  // continua sendo uma grade só. Ver `pintar`.
  const grid = el('div', isBoss ? 'hunt-secoes' : 'hunt-grid');
  // A linha que responde "filtrei e sobrou o quê?" — sem ela, uma busca sem
  // resultado é uma tela vazia sem explicação.
  const recado = el('p', 'hunt-filtro-vazio');

  /*
   * A boss task deste boss, quando ele for de task. É o que decide se o card
   * abre, e é o que ele escreve em vez do cooldown: "faltam 1.200 Minotauros"
   * responde a pergunta que "volta em 340 min" não responderia — esperar não
   * abre esta porta.
   */
  const taskDoBoss = (huntId) => (state.character.bossTasks ?? []).find((task) => task.boss === huntId) ?? null;

  const cartao = (hunt) => {
    const locked = state.character.level < hunt.level;
    const task = isBoss ? taskDoBoss(hunt.id) : null;
    const cooldown = isBoss && !task ? state.character.bossCooldowns?.[hunt.id] ?? 0 : 0;
    const blocked = locked || cooldown > 0 || (task ? !task.feito || task.matou : false);

    // `boss` marca o cartao de sala de boss: e' o unico que leva a moldura de
    // login. Ver o bloco das molduras no fim da folha de estilo.
    const card = el('div', `hunt-card${isBoss ? ' boss' : ''}${blocked ? ' locked' : ''}`);
    card.dataset.active = String(state.hunt?.huntId === hunt.id);

    /*
     * ---- O coração de favorita ----
     *
     * Ele mora no canto do card e não numa fileira de botões: favoritar é uma
     * marca que se põe NA COISA, e um botão "favoritar" ao lado de "entrar"
     * seriam duas ações de peso muito diferente disputando o mesmo olhar.
     *
     * `stopPropagation` porque o card inteiro é clicável — sem ele, marcar a
     * hunt entraria nela, que é o contrário do que a pessoa quis.
     */
    const favorita = (state.character.favoritas ?? []).includes(hunt.id);
    const coracao = el('button', 'hunt-fav', favorita ? '♥' : '♡');
    coracao.type = 'button';
    coracao.setAttribute('aria-pressed', String(favorita));
    tipTexto(coracao, favorita ? 'Tirar dos favoritos' : 'Favoritar — sobe para o topo da lista');
    coracao.onclick = (evento) => {
      evento.stopPropagation();
      ctx.send({ t: 'favorita', id: hunt.id });
    };
    card.append(coracao);

    card.append(el('h3', null, hunt.name));

    const bichos = el('div', 'hunt-card-bichos');
    for (const creature of hunt.creatures.slice(0, 4)) {
      bichos.append(figuraDaCriatura(creature, catalog, isBoss ? 52 : 40));
    }
    card.append(bichos);

    card.append(el('p', null, hunt.blurb));
    card.append(el('span', 'lv', locked ? `requer level ${hunt.level}` : `level ${hunt.level}+`));
    if (cooldown > 0) card.append(el('div', 'boss-locked', `volta em ${formatLeft(cooldown)}`));
    if (task) card.append(faixaDaBossTask(task));

    if (!blocked) {
      /*
       * A hunt seguinte do ciclo sai da lista FILTRADA, e não da lista inteira.
       *
       * É o que o jogador está vendo: marcar um ciclo depois de filtrar por
       * "de Edron" tem de rodar as de Edron, e não as dezenove.
       */
      card.onclick = () => {
        rolagemDaLista[isBoss ? 'bosses' : 'hunts'] = document.getElementById('modal-body')?.scrollTop ?? 0;
        return isBoss ? askBoss(hunt) : askRunMode(hunt, huntsFiltradas(list, state.character.level));
      };
    }
    return card;
  };

  const pintar = () => {
    const escolhidas = huntsFiltradas(list, state.character.level);
    /*
     * ---- Os bosses vêm em dois grupos, e não numa lista só ----
     *
     * São duas coisas diferentes com o mesmo formato de card. O de TASK sai uma
     * vez por personagem e se abre matando duas mil de alguma coisa; o DIÁRIO
     * volta sozinho num relógio. Lado a lado sem separação, o jogador lê os dois
     * como a mesma promessa — e a diferença entre "volto amanhã" e "não volta
     * nunca mais" é a informação mais importante da tela.
     *
     * O grupo vazio continua aparecendo, com a frase dizendo que está vazio: um
     * título que some é um recurso que parece não existir.
     */
    if (isBoss) {
      const secoes = [
        { titulo: 'Boss Tasks — uma vez por personagem', bosses: escolhidas.filter((b) => b.task) },
        { titulo: 'Bosses Diários — voltam no cooldown', bosses: escolhidas.filter((b) => !b.task) },
      ];
      grid.replaceChildren();
      for (const secao of secoes) {
        grid.append(el('h4', 'store-degrau', secao.titulo));
        if (!secao.bosses.length) {
          grid.append(el('p', 'empty', 'Nenhum por enquanto.'));
          continue;
        }
        const dentro = el('div', 'hunt-grid');
        montarAosPoucos(dentro, secao.bosses, cartao, { lote: 12 });
        grid.append(dentro);
      }
    } else {
      // No telefone os cartões vêm aos poucos, conforme a rolagem (aos-poucos.mjs).
      grid.replaceChildren();
      montarAosPoucos(grid, escolhidas, cartao, { lote: 12 });
    }
    if (!escolhidas.length) {
      recado.textContent = 'Nada com esse filtro — apague a busca ou desmarque "no meu level".';
    } else if (escolhidas.length < list.length) {
      recado.textContent = `${escolhidas.length} de ${list.length}`;
    } else {
      recado.textContent = '';
    }
  };

  /*
   * ---- O filtro virou uma GAVETA, aberta pelo cabeçalho ----
   *
   * Ele já morou dentro da fileira de abas e depois numa faixa embaixo delas.
   * Nos dois lugares gastava altura o tempo todo para uma coisa que quase nunca
   * se mexe — e altura, nesta janela, é card de hunt que sai da tela.
   *
   * Agora é um botão "Filtro" ao lado do X, e a gaveta cai dele. Fechada, a
   * janela é só as abas e os cards. O botão acende e ganha um ponto quando há
   * filtro valendo: uma gaveta fechada escondendo metade da lista sem avisar
   * seria pior do que a faixa que ela substituiu.
   *
   * O estado de aberto vive em `ctx.tabs` porque o painel se redesenha sozinho
   * (a cada mudança de estado do personagem), e uma variável local voltaria a
   * fechar a gaveta debaixo de quem estava digitando.
   */
  const gaveta = el('div', 'filtro-gaveta');
  gaveta.append(barraDeFiltro(pintar));
  gaveta.hidden = !ctx.tabs.filtroAberto;

  const botao = el('button', 'modal-acao', 'Filtro');
  botao.type = 'button';
  botao.setAttribute('aria-expanded', String(!!ctx.tabs.filtroAberto));
  if (filtroDeHunts.busca.trim() || filtroDeHunts.soPodeEntrar || filtroDeHunts.ordem !== 'level') {
    botao.append(el('i', 'modal-acao-ponto'));
  }
  botao.onclick = () => {
    ctx.tabs.filtroAberto = !ctx.tabs.filtroAberto;
    gaveta.hidden = !ctx.tabs.filtroAberto;
    botao.setAttribute('aria-expanded', String(!!ctx.tabs.filtroAberto));
    if (ctx.tabs.filtroAberto) gaveta.querySelector('input.search')?.focus();
  };
  ctx.acoesDoModal?.().append(botao);

  /*
   * A Loja de Boss Token, no mesmo canto e SÓ na aba de Bosses.
   *
   * "ao lado de aventuras (apenas estando na aba boss)". Aqui as duas metades
   * da frase valem: e' o canto de ações da janela de Aventuras, e ele só existe
   * enquanto a aba de Bosses estiver aberta.
   *
   * Ao lado do filtro de propósito: os dois são coisas que se fazem OLHANDO a
   * lista de bosses, e o token que a loja cobra é o que essa lista larga.
   */
  if (isBoss) {
    const loja = el('button', 'modal-acao bt-atalho');
    const moeda = itemCanvas(55287, 16);
    if (moeda) loja.append(moeda);
    loja.append(document.createTextNode('Loja de Boss Token'));
    tipTexto(loja, 'Troque os Boss Token que caem dos bosses por wildcards, passes, exercise e conjuntos.');
    loja.onclick = () => openLojaDeBossToken();
    ctx.acoesDoModal?.().append(loja);
  }

  // A faixa da rotação só na aba de Bosses: ela fala de bosses, e a lista de
  // hunts tem o ciclo dela, que é outra coisa.
  if (isBoss) body.append(faixaDoAutoBoss(list));
  body.append(gaveta, recado, grid);
  pintar();

  /*
   * Depois do quadro, e nao agora: os cards acabaram de entrar no DOM e a altura
   * rolavel ainda e' a de antes deles. Marcar `scrollTop` aqui seria marcar num
   * corpo que ainda nao tem para onde rolar.
   */
  if (chegadaNaLista) {
    const ondeEstava = chegadaNaLista === 'voltar' ? rolagemDaLista[isBoss ? 'bosses' : 'hunts'] ?? 0 : 0;
    chegadaNaLista = null;
    requestAnimationFrame(() => {
      const corpo = document.getElementById('modal-body');
      if (corpo) corpo.scrollTop = ondeEstava;
    });
  }
}

/**
 * A faixa de estado de uma boss task, no card do boss.
 *
 * Três estados, três frases — e nenhuma delas é um número solto. "1.243 / 2.000
 * Minotauros" diz onde a pessoa está; "já derrotado" diz por que o card está
 * apagado; e o aberto diz que é agora ou nunca, porque de fato é.
 */
function faixaDaBossTask(task) {
  if (task.matou) return el('div', 'boss-locked boss-feito', 'já derrotado — sai uma vez por personagem');
  if (!task.feito) {
    const faixa = el('div', 'boss-task');
    const barra = el('div', 'boss-task-barra');
    const cheio = el('i');
    cheio.style.width = `${Math.min(100, (task.kills / task.alvo) * 100).toFixed(1)}%`;
    barra.append(cheio);
    faixa.append(barra);
    faixa.append(
      el('span', null, `${task.kills.toLocaleString('pt-BR')} / ${task.alvo.toLocaleString('pt-BR')} ${task.name}`),
    );
    return faixa;
  }
  return el('div', 'boss-task boss-task-aberta', 'liberado — e sai uma vez só');
}

// A lista fica recolhida até alguém pedir por ela: aberta, ela comia quatro
// linhas do rodapé para dizer "ninguém online", que é o caso quase sempre.
let listaDeAmigosAberta = false;

/*
 * ---- QUEM da party vai nesta ida ----
 *
 * Pedido do dono: "quando eu for entrar em algo, uma hunt, um boss ou sei lá,
 * tem que ter opção de entrar sozinho também, em vez de só ter opção de entrar
 * com a party. E marcar quem da party quer chamar — a princípio vêm todos
 * marcados."
 *
 * O que se guarda são os DESMARCADOS, e não os marcados. É o que faz "a
 * princípio vêm todos" ser verdade sem ninguém escrever lista nenhuma: quem
 * entra na party depois já nasce dentro, e um nome que sobra aqui de uma party
 * antiga não tira ninguém de uma nova por acaso — ele só existe enquanto a
 * pessoa estiver no time.
 *
 * Mora no módulo e não no personagem: é uma escolha desta ida, tomada nesta
 * tela, e o servidor a recebe inteira no `armar`.
 */
const foraDaConvocacao = new Set();
const chaveDoNome = (nome) => String(nome ?? '').toLowerCase();

/*
 * ---- E o "Entrar sozinho", que é um botão e não uma dedução ----
 *
 * "a princípio todos da party teriam que vir marcados por padrão, ok? E ao lado
 * a opção (entrar sozinho)."
 *
 * Desmarcar as fichas uma a uma já levava ao mesmo lugar, e isso não basta: com
 * quatro pessoas na party são quatro cliques para dizer uma coisa só, e o
 * estado "ninguém marcado" é uma conclusão que a pessoa tem de tirar olhando as
 * fichas em vez de uma escolha que ela tomou.
 *
 * A chave é separada da marcação de propósito: desligá-la devolve o time
 * inteiro marcado, que é o padrão. Quem só queria deixar UMA pessoa de fora
 * continua desmarcando a ficha dela.
 */
let irSozinho = false;

/**
 * Os companheiros de party marcados agora — eu nunca entro na conta.
 *
 * `membros` vem do servidor como uma lista de FICHAS (`{ name, level, hunt,
 * ... }`), e não de nomes: ver `partyView`, em grupo.mjs. O `?? membro` do
 * final é para uma aba velha que ainda receba nomes crus não sair chamando
 * `undefined`.
 */
function convocadosAgora() {
  if (irSozinho) return [];
  const party = ctx.state.character?.party;
  const eu = chaveDoNome(ctx.state.character?.name);
  return (party?.membros ?? [])
    .map((membro) => (typeof membro === 'string' ? membro : membro?.name ?? ''))
    .filter((nome) => nome && chaveDoNome(nome) !== eu && !foraDaConvocacao.has(chaveDoNome(nome)));
}

/*
 * O convite para caçar junto, encolhido a um botão.
 *
 * Ele era um quadro com título, uma frase de ajuda e uma linha por amigo — três
 * a seis linhas de rodapé para uma escolha que quase ninguém faz, e era parte
 * do que empurrava os botões de modo para fora da tela. Agora é o desenho dos
 * amigos com um "+" em cima, do tamanho de um botão de barra: quem quer chamar
 * alguém clica e a lista abre ali mesmo; quem não quer nem vê a lista.
 *
 * Só aparece gente que já é amiga, está online e está livre — quem só recebeu
 * um pedido ainda não é amigo, e quem já está caçando não pode ser puxado para
 * outra caçada. Um líder e até dois convidados.
 */
function blocoDeAmigos(aoMudar) {
  const { state, send } = ctx;
  // Pede a lista quando ela ainda não chegou; a prévia se redesenha sozinha.
  if (!state.friends) send({ t: 'friends', action: 'list' });
  const lista = state.friends?.amigos ?? [];
  const livres = lista.filter((amigo) => amigo.online && amigo.livre);

  const caixa = el('div', 'run-convidar');

  const party = state.character?.party ?? null;
  const teto = party?.maximo ?? 2;
  const jaNaParty = party?.membros?.length ?? 1;

  const botao = el('button', 'convidar-botao');
  const arte = document.createElement('img');
  arte.src = '/client/assets/icons/amigos.png';
  arte.alt = '';
  botao.append(arte, el('i', 'convidar-mais', '+'));
  botao.disabled = !livres.length || jaNaParty >= teto;
  tipTexto(
    botao,
    jaNaParty >= teto
      ? `A party já está com ${jaNaParty} de ${teto} — para ir além, todo mundo dela precisa do slot de party da loja.`
      : livres.length
        ? `Chamar amigos para a party — cabem ${teto - jaNaParty} a mais\nA experiência é dividida com bônus por vocações diferentes.`
        : lista.length
          ? 'Ninguém da sua lista está online e livre agora.'
          : 'Sua lista de amigos está vazia — abra Amigos no menu para adicionar alguém.'
  );
  botao.onclick = () => {
    listaDeAmigosAberta = !listaDeAmigosAberta;
    aoMudar?.();
  };
  caixa.append(botao);

  /*
   * Quem JÁ ESTÁ na party, ao lado do botão.
   *
   * Antes eram as marcas de quem seria convidado depois; agora é o time de
   * verdade, o mesmo que o painel de Party mostra. A diferença importa: uma
   * ficha aqui quer dizer "esta pessoa vai", e não "eu pretendo chamar".
   *
   * Sair da party não se faz daqui — o ✕ de antes tirava uma intenção, e tirar
   * gente da party de dentro da tela de escolher hunt seria uma expulsão
   * escondida num canto. Quem manda embora usa o painel de Party.
   */
  /*
   * ---- E cada ficha virou uma MARCA ----
   *
   * Ela dizia "esta pessoa vai", e não havia como dizer que não: com party
   * montada, entrar era sempre entrar com o time inteiro. Quem quisesse caçar
   * sozinho tinha de sair da party e montá-la de novo depois.
   *
   * Agora a ficha é clicável e nasce MARCADA. Desmarcar todas quer dizer
   * "vou sozinho", e o botão de modo diz isso antes de ser apertado — ver
   * `startRun`.
   *
   * Desmarcar não tira ninguém da party nem a desfaz: o time continua de pé,
   * e a próxima hunt já vem com todo mundo marcado de novo se você remarcar.
   * Sair da party continua sendo coisa do painel de Party, como sempre foi.
   */
  const fichas = el('div', 'convidar-fichas');
  const euMesmo = state.character?.name;
  /*
   * Só o LÍDER marca quem vai — é ele quem arma o lobby, e o servidor recusa
   * qualquer outro (ver `armarLobby`). Para quem não é líder as fichas seriam
   * botões que não fazem nada, então ele vê os nomes sem marca nenhuma: quem
   * vai continua sendo informação dele.
   *
   * O "Entrar sozinho" fica para os dois, e é a razão de ele existir aqui: sem
   * ele, quem não é líder não tinha como caçar sozinho sem sair da party.
   */
  const souLider = party?.souLider !== false;
  for (const membro of party?.membros ?? []) {
    const nome = typeof membro === 'string' ? membro : membro.name;
    if (nome === euMesmo) continue;
    const k = nome.toLowerCase();
    const dentro = !irSozinho && !foraDaConvocacao.has(k);
    const ficha = el('button', `convidar-ficha${dentro ? ' marcada' : ''}`);
    ficha.type = 'button';
    ficha.disabled = !souLider;
    ficha.setAttribute('aria-pressed', String(dentro));
    ficha.append(el('i', 'convidar-marca', dentro ? '✓' : ''));
    ficha.append(el('b', null, nome));
    tipTexto(
      ficha,
      !souLider
        ? `${party.lider} é quem escolhe quem vai — ele é o líder da party.`
        : dentro
          ? `${nome} vai junto. Clique para deixá-lo de fora desta caçada — ele continua na party.`
          : `${nome} fica de fora desta caçada. Clique para chamá-lo de volta.`
    );
    if (souLider)
      ficha.onclick = () => {
      /*
       * Marcar alguém desliga o "entrar sozinho": os dois dizem coisas opostas,
       * e o clique mais recente é o que vale. Sem isto a ficha acenderia e o
       * botão continuaria dizendo que você vai só — dois estados na tela, um
       * contradizendo o outro.
       */
      if (dentro) foraDaConvocacao.add(k);
      else {
        irSozinho = false;
        foraDaConvocacao.delete(k);
      }
      aoMudar?.();
    };
    fichas.append(ficha);
  }
  if (!fichas.childElementCount) {
    fichas.append(el('em', 'convidar-vazio', livres.length ? 'sozinho' : ''));
  } else {
    /*
     * O "Entrar sozinho", ao lado das fichas — o lugar em que ele responde à
     * pergunta que as fichas fazem ("quem vai?") em vez de virar mais um botão
     * no rodapé.
     *
     * Ele aparece só com party montada: sozinho de verdade, ele diria o óbvio.
     */
    const so = el('button', `convidar-sozinho${irSozinho ? ' marcada' : ''}`);
    so.type = 'button';
    so.setAttribute('aria-pressed', String(irSozinho));
    so.append(el('i', 'convidar-marca', irSozinho ? '✓' : ''));
    so.append(el('b', null, 'Entrar sozinho'));
    tipTexto(
      so,
      irSozinho
        ? 'Você entra sozinho: ninguém da party vai junto, e a party continua montada. Clique para chamar o time de volta.'
        : 'Entrar sem levar ninguém. A party continua montada — só esta caçada é sua.'
    );
    so.onclick = () => {
      irSozinho = !irSozinho;
      /* Voltar atrás devolve o time INTEIRO marcado, que é o padrão. */
      if (!irSozinho) foraDaConvocacao.clear();
      aoMudar?.();
    };
    fichas.append(so);

    if (!convocadosAgora().length && !irSozinho) {
      /* Todas desmarcadas à mão dá no mesmo, e a tela diz isso antes de acontecer. */
      fichas.append(el('em', 'convidar-vazio', 'você vai sozinho'));
    }
  }
  caixa.append(fichas);

  /*
   * ---- A lista virou um botão por amigo, e o convite sai NA HORA ----
   *
   * Eram caixas de marcar, e o convite só partia quando a caçada começasse. A
   * marca guardava uma intenção que ninguém do outro lado via — e se a pessoa
   * fechasse a prévia para olhar outra hunt, a intenção sumia sem nunca ter
   * virado convite.
   *
   * Agora é o mesmo gesto do painel de Amigos e do de Party: clicou, o convite
   * saiu, e a party cresce na tela de quem convidou. É o "funcionar igual
   * chamar pra party" do pedido, e é o que o lobby precisa: o time tem de estar
   * montado ANTES de alguém entrar.
   */
  if (listaDeAmigosAberta && livres.length) {
    const fileira = el('div', 'convidar-lista');
    const naParty = new Set((party?.membros ?? []).map((m) => m.name));
    for (const amigo of livres) {
      const linha = el('button', 'convidar-amigo');
      linha.append(el('span', 'run-parada-nome', amigo.name));
      linha.append(el('em', 'run-parada-unidade', `Lv ${amigo.level}`));
      if (naParty.has(amigo.name)) {
        linha.append(el('i', null, 'na party'));
        linha.disabled = true;
      } else if (jaNaParty >= teto) {
        linha.disabled = true;
        tipTexto(linha, `A party já está com ${jaNaParty} de ${teto}.`);
      } else {
        linha.onclick = () => {
          send({ t: 'grupo', action: 'convidar', name: amigo.name });
          listaDeAmigosAberta = false;
          aoMudar?.();
        };
      }
      fileira.append(linha);
    }
    caixa.append(fileira);
  }
  return caixa;
}

/*
 * As condições de parada, guardadas fora do painel.
 *
 * A prévia se redesenha a cada mudança de regra de loot; o que o jogador marcou
 * aqui não pode se perder nesse redesenho. Ficam no módulo, como a ficha aberta.
 */
const paradas = {
  cap: { ligada: false, valor: 100, rotulo: 'Cap', campo: 'Cap mínimo', sufixo: 'oz' },
  gold: { ligada: false, valor: 5000, rotulo: 'Gold', campo: 'Gold mínimo', sufixo: 'gold' },
  // A stamina viaja em minutos, que é como o servidor conta; a tela pergunta
  // em horas, que é como o jogador lê o relógio dela.
  stamina: { ligada: false, valor: 38, rotulo: 'Stamina', campo: 'Stamina mínima', sufixo: 'h', emHoras: true },
  mortes: { ligada: false, valor: 3, rotulo: 'Mortes', campo: 'Mortes', sufixo: '' },
};

/*
 * ---- A MARCAÇÃO É DA PESSOA, e volta do servidor ----
 *
 * "cada um marca o teu ... e isso só deve parar o char q configurou pra isso."
 *
 * Antes isto era estado de TELA: viajava dentro do `startHunt` e morria com ele.
 * Quem entrava a convite nunca passava por esta prévia, e por isso entrava sem
 * condição de parada nenhuma — a party caçava até alguém fechar a aba.
 *
 * Agora a marcação mora no personagem, no servidor (`settings.limites`). Estas
 * duas funções são as duas pontas disso: `sincronizarParadas` traz o que ele
 * marcou da última vez, e `salvarParadas` manda o que ele acabou de mexer.
 *
 * A sincronia acontece UMA vez por personagem: refazer a cada redesenho
 * apagaria o número no meio da digitação, porque o servidor só responde depois.
 */
let paradasDe = null;

export function sincronizarParadas(character) {
  if (!character?.name || paradasDe === character.name) return;
  paradasDe = character.name;
  const guardado = character.settings?.limites;
  for (const [chave, parada] of Object.entries(paradas)) {
    const valor = guardado?.[chave];
    parada.ligada = valor != null && valor > 0;
    // A stamina viaja em minutos e a tela pergunta em horas. Ver `paradas`.
    if (parada.ligada) parada.valor = parada.emHoras ? Math.max(1, Math.round(valor / 60)) : valor;
  }
}

/*
 * Mandar a cada tecla seria uma mensagem por dígito; o pequeno atraso junta a
 * digitação inteira numa só.
 */
let salvandoParadas = null;
function salvarParadas() {
  clearTimeout(salvandoParadas);
  salvandoParadas = setTimeout(() => ctx.send({ t: 'limites', limites: limitesEscolhidos() }), 350);
}

/** O que vai para o servidor: só o que está marcado. */
function limitesEscolhidos() {
  const saida = {};
  for (const [chave, parada] of Object.entries(paradas)) {
    if (!parada.ligada || parada.valor <= 0) continue;
    saida[chave] = parada.emHoras ? Math.round(parada.valor * 60) : parada.valor;
  }
  return saida;
}

/*
 * O quadro das condições, na tela de antes de entrar — numa linha só.
 *
 * Todas opcionais e desmarcadas: sem marcar nada, a caçada continua mesmo com
 * capacidade no talo ou ouro no fim, que é como sempre funcionou.
 *
 * O que mudou foi o tamanho. Título numa linha, quatro condições em outra,
 * resumo numa terceira e uma nota numa quarta somavam quatro linhas de rodapé
 * para uma coisa que quase sempre fica desmarcada — e era isso, somado ao
 * quadro de amigos, que empurrava os dois botões de modo para fora da tela. O
 * rótulo "Parar em" agora é a primeira coluna da mesma fileira, e o resumo só
 * aparece quando existe algo para resumir.
 */
/*
 * ---- Recolhido até alguém pedir ----
 *
 * O dono: "muda isso pro topo da pagina a direita do 'voltar pra hunts' e deixa
 * meio que oculto o parar; ai se a pessoa marcar aparece as opcao, so que deixa
 * mais compacto e bonito".
 *
 * Ele estava numa fileira inteira do rodapé, sempre aberta, com quatro campos
 * de número — e desmarcada na esmagadora maioria das vezes. Agora é um botão no
 * TOPO, ao lado do "Voltar para as hunts": fechado ele diz só "Parar em"; com
 * alguma condição ligada, diz quais, e fica aceso.
 *
 * Fora da função, como as próprias condições: a prévia se redesenha a cada
 * mudança, e a gaveta não pode fechar sozinha no meio da digitação.
 */
let paradasAbertas = false;

/** O resumo curto que o botão mostra fechado: "Cap 100 · Gold 5.000". */
function resumoDasParadas() {
  return Object.values(paradas)
    .filter((parada) => parada.ligada && parada.valor > 0)
    .map((parada) => `${parada.rotulo} ${parada.valor.toLocaleString('pt-BR')}${parada.sufixo}`);
}

/**
 * O botão do topo. A gaveta que ele abre é `blocoDeParadas`, logo abaixo.
 */
function botaoDeParadas(aoMudar) {
  sincronizarParadas(ctx.state?.character);
  const ligadas = resumoDasParadas();
  const botao = el('button', `modal-back paradas-botao${ligadas.length ? ' on' : ''}`);
  botao.setAttribute('aria-expanded', String(paradasAbertas));
  botao.append(el('b', null, 'Parar em'));
  botao.append(el('em', null, ligadas.length ? ligadas.join(' · ') : 'nada — a caçada não para sozinha'));
  botao.append(el('i', 'paradas-seta', paradasAbertas ? '⌃' : '⌄'));
  tipTexto(
    botao,
    'Condições para a caçada encerrar sozinha: capacidade, ouro, stamina ou mortes.'
  );
  botao.onclick = () => {
    paradasAbertas = !paradasAbertas;
    aoMudar?.();
  };
  return botao;
}

function blocoDeParadas(aoMudar) {
  const caixa = el('div', 'run-paradas');

  const fileira = el('div', 'run-paradas-fila');
  for (const [chave, parada] of Object.entries(paradas)) {
    const linha = el('label', `run-parada${parada.ligada ? ' on' : ''}`);
    tipTexto(linha, `${parada.campo} — a caçada encerra sozinha ao chegar nesse valor`);

    const marca = document.createElement('input');
    marca.type = 'checkbox';
    marca.checked = parada.ligada;

    const campo = document.createElement('input');
    campo.type = 'number';
    campo.min = '1';
    campo.step = '1';
    campo.value = String(parada.valor);
    campo.disabled = !parada.ligada;
    campo.onclick = (evento) => evento.preventDefault();
    campo.oninput = () => {
      parada.valor = Math.max(0, Math.floor(Number(campo.value) || 0));
      salvarParadas();
      aoMudar?.();
    };

    marca.onchange = () => {
      parada.ligada = marca.checked;
      campo.disabled = !marca.checked;
      linha.classList.toggle('on', marca.checked);
      salvarParadas();
      aoMudar?.();
    };

    linha.append(marca, el('span', 'run-parada-nome', parada.rotulo), campo);
    if (parada.sufixo) linha.append(el('em', 'run-parada-unidade', parada.sufixo));
    fileira.append(linha);
  }
  caixa.append(fileira);

  /*
   * O resumo do que está ligado saiu daqui: ele agora mora no PRÓPRIO botão,
   * onde é lido mesmo com a gaveta fechada. O que sobra é a nota das mortes,
   * que não é resumo — é uma regra que surpreende quem marca a condição sem
   * saber que morrer não encerra a caçada.
   */
  if (paradas.mortes.ligada) {
    caixa.append(el('p', 'run-paradas-resumo', 'Morrer não encerra: ele volta ao começo do percurso.'));
  }
  return caixa;
}

/**
 * Manda o personagem para a hunt, sozinha ou como primeira do ciclo.
 *
 * ---- Com party, isto vira um LOBBY ----
 *
 * "a pessoa convida e tem que dar pronto e ai o lider comeca."
 *
 * Quem esta' sozinho continua entrando com um clique, como sempre. Quem tem
 * party nao entra sozinho e deixa o time para tras: o clique passa a ser
 * "chamar o time para ca'", e a entrada acontece quando todo mundo disser que
 * esta' pronto.
 *
 * A decisao mora AQUI, num lugar so', e por isso vale para a hunt e para o boss
 * sem escrever a regra duas vezes — que e' o "o sistema de boss tem que ser o
 * mesmo sistema de hunt" do pedido.
 *
 * Quem nao e' lider nao arma nada: para ele o botao diz o que fazer em vez de
 * mandar um comando que o servidor vai recusar.
 */
function startRun(hunt, mode, ids = null) {
  const party = ctx.state.character?.party;
  /*
   * ---- Com party, o clique só vira lobby se ALGUÉM foi chamado ----
   *
   * "tem que ter opção de entrar sozinho também, em vez de só ter opção de
   * entrar com a party."
   *
   * Com todas as fichas desmarcadas, a party continua existindo e esta caçada é
   * sua: cai no mesmo `startHunt` de quem não tem party nenhuma. Não é um
   * segundo jeito de entrar — é o de sempre, alcançado por uma escolha nova.
   */
  const chamados = convocadosAgora();
  if (party?.membros?.length > 1 && chamados.length) {
    if (!party.souLider) {
      return ctx.notice?.(`${party.lider} é o líder da party — ele escolhe onde o time vai.`);
    }
    ctx.send({
      t: 'lobby',
      action: 'armar',
      huntId: hunt.id,
      modo: mode === 'online' ? 'online' : 'auto',
      // Quem foi marcado nas fichas. O servidor põe o líder de volta sozinho.
      convocados: chamados,
    });
    ctx.closeModal();
    return openLobby();
  }
  ctx.send({
    t: 'startHunt',
    huntId: hunt.id,
    // A dificuldade escolhida na aba da campanha (as hunts normais são fases dela).
    dificuldade: ctx.tabs.dificuldade ?? 'facil',
    strategy: document.getElementById('strategy').value,
    mode,
    // A roda inteira, na ordem em que o jogador marcou os cards. Sem `ids` o
    // servidor cai na regra antiga de vizinhança, que é o que uma aba velha
    // ainda em pé vai mandar.
    ids,
    // As condições de parada marcadas na prévia; vazio quando não há nenhuma.
    limites: limitesEscolhidos(),
  });
  ctx.closeModal();
}

/*
 * A prévia da hunt, em cima da escolha de modo.
 *
 * Escolher onde caçar era escolher por um nome e um número de level. Aqui vêm
 * as duas coisas que respondem "vale a pena?": a cara do lugar e o que cai dele.
 *
 * **O que cai** é dado de verdade — a tabela de loot de cada criatura da hunt,
 * do bestiary, com as chances somadas por item e as doze melhores na frente. Um
 * item que cai de dois bichos diferentes conta as duas chances, que é o que o
 * jogador sente na prática.
 *
 * **A cara do lugar** é uma ilustração por tema do gerador, não por hunt. São
 * sete temas para vinte hunts, e a imagem é honesta assim: o mapa de dezoito
 * delas é gerado do zero a cada sessão, então uma "foto da hunt" seria a foto
 * de um mapa que o jogador nunca vai ver. O tema, esse sim, é sempre o mesmo.
 * Enquanto a arte não existe, a faixa some sozinha (`onerror`).
 */
const artesSemArquivo = new Set();
// De quem é a ficha aberta na prévia. Fora da função porque o painel é
// redesenhado a cada mudança de regra de loot, e a escolha tem que sobreviver.
let escolhidoNaPrevia = null;

/*
 * ---- As duas marcas de um item, e os dois botões do mouse ----
 *
 * `não coletar` e `não vender` são independentes. As quatro combinações valem:
 *
 *     coleta e vende          (sem marca)
 *     coleta e guarda         (não vender)
 *     nem apanha              (não coletar)
 *     nem apanha, nem vende   (as duas)
 *
 * Antes era um ciclo de três estados num clique só, e as duas listas se
 * excluíam: marcar "não vender" apagava "não coletar" e vice-versa. Isso
 * obrigava a passar por um estado que não se queria para chegar no que se
 * queria, e tornava impossível dizer "apanha e guarda" sem passar por "não
 * apanha".
 *
 *     BOTÃO ESQUERDO = NÃO COLETAR
 *     BOTÃO DIREITO  = NÃO VENDER
 *
 * O servidor já tratava as duas listas como independentes (`shouldLoot` olha
 * `noLoot`, `isProtected` olha `noSell`); quem impunha a exclusão era esta tela.
 *
 * Esta função é a ÚNICA que liga uma célula às regras — a prévia da hunt e o
 * filtro de loot chamam as duas o mesmo código. Antes eram duas cópias quase
 * iguais, e a de um lado já tinha divergido da do outro.
 */
function ligarRegrasDoItem(cell, id, { titulo = '', aoMudar = null } = {}) {
  const { state, send } = ctx;
  const rules = state.character.itemRules ?? { noSell: [], noLoot: [] };
  const naoColeta = (rules.noLoot ?? []).includes(id);
  const naoVende = (rules.noSell ?? []).includes(id);

  if (naoColeta) cell.classList.add('barred');
  if (naoVende) cell.classList.add('protected');

  const estado = naoColeta && naoVende
    ? 'não coleta e não vende'
    : naoColeta
      ? 'não coletar'
      : naoVende
        ? 'coleta e guarda'
        : 'coleta e vende';
  tipFor(cell, id, [titulo, estado].filter(Boolean).join(' — '));

  /*
   * A guarda dos cinco pixels: um arrasto que o navegador não promove a
   * arrasto de verdade chega aqui como clique, e sem ela ele mexia na regra
   * por engano.
   */
  let apertou = null;
  cell.addEventListener('pointerdown', (event) => {
    apertou = { x: event.clientX, y: event.clientY };
  });
  const arrastou = (event) => apertou && Math.hypot(event.clientX - apertou.x, event.clientY - apertou.y) > 5;

  cell.onclick = (event) => {
    if (arrastou(event)) return;
    send({ t: 'itemRule', rule: 'noLoot', id });
    aoMudar?.();
  };
  /*
   * A célula vem de `itemCell`, que já liga o direito da MOCHILA: usar o item.
   * Os dois ouvintes disparavam juntos, e marcar "não vender" numa bag a ABRIA
   * (report do Appa). No filtro o direito é só a regra.
   */
  cell.oncontextmenu = null;
  cell.addEventListener('contextmenu', (event) => {
    // O menu do navegador não pode abrir por cima da grade.
    event.preventDefault();
    if (arrastou(event)) return;
    send({ t: 'itemRule', rule: 'noSell', id });
    aoMudar?.();
  });

  cell.draggable = true;
  cell.addEventListener('dragstart', (event) => {
    event.dataTransfer.setData('text/plain', JSON.stringify({ from: 'filter', id }));
    cell.classList.add('dragging');
  });
  cell.addEventListener('dragend', () => cell.classList.remove('dragging'));
  return cell;
}

/*
 * ---- Até onde a estrela salva a peça da venda automática ----
 *
 * As duas listas do filtro marcam POR ID, e por id não dá para dizer "esta
 * spear sim, aquela não": as duas cópias têm o mesmo id e só o afixo as separa.
 * Era o buraco do filtro desde que a peça passou a ter estrela.
 *
 * Antes isto era uma trava fixa — qualquer estrela salvava —, e com 22% dos
 * itens comuns saindo estrelados a bolsa parava de esvaziar: a mochila enchia
 * de `hand axe ★` e a proteção virava o entulho. A linha agora é escolha.
 *
 * As cores são as MESMAS das estrelas do item, e é isso que torna a escolha
 * legível sem explicação: quem viu uma estrela roxa numa peça sabe o que
 * "roxa ou melhor" vai guardar. Ver `estrelasDosAfixos`.
 */

/*
 * ---- O sistema de itens trocou a pergunta ----
 * O atributo tem NÍVEL (N1–N5, cada um com a cor da estrela dele) e a peça
 * até seis atributos. A fileira de cima é o nível mínimo; a de baixo, quantos
 * atributos desse nível ou mais. Quem gravou a regra de antes (a cor em três
 * degraus) é traduzido como no servidor: ver `regraDoAtributo`, afixos.mjs.
 */
function regraDoAtributo(s = {}) {
  const nivel = s.guardarNivel != null ? Number(s.guardarNivel) : ({ 0: 0, 1: 1, 2: 3, 3: 5 }[Number(s.guardarAfixo ?? 1)] ?? 1);
  const quantos = s.guardarQuantos != null ? Number(s.guardarQuantos) : Math.max(1, Number(s.guardarEstrelas ?? 0));
  return { nivel: Math.max(0, Math.min(5, nivel || 0)), quantos: Math.max(1, Math.min(6, quantos || 1)) };
}
const nomeDoNivel = (nivel) => (nivel === 1 ? 'de qualquer nível' : nivel === 5 ? 'N5' : `N${nivel} ou mais`);

/*
 * ---- ATRIBUTOS DO ITEM (pedido do dono, 30/09) ----
 * Duas perguntas: QUANTOS atributos a peça tem (os reais, depois do drop) e o
 * NÍVEL MÍNIMO (pelo menos um atributo desse nível). Vale com OU junto da
 * raridade e dos sockets: a peça comum com atributo fica mesmo com a raridade
 * ligada em "raro para cima". O servidor decide (`Afixos.decisaoDoLoot`); aqui
 * é a mesma tradução das chaves (`Afixos.regraDeAtributos`).
 */
function regraDeAtributos(s = {}) {
  if (s.guardarAtributos != null || s.guardarNivelMinimo != null) {
    const quantos = Math.max(0, Math.min(6, Math.round(Number(s.guardarAtributos ?? 1)) || 0));
    const nivel = Math.max(1, Math.min(5, Math.round(Number(s.guardarNivelMinimo ?? 1)) || 1));
    return { quantos, nivel };
  }
  const antiga = regraDoAtributo(s);
  return antiga.nivel ? { quantos: antiga.quantos, nivel: antiga.nivel } : { quantos: 0, nivel: 1 };
}
const LINHAS_DA_QUANTIDADE = [
  { valor: 0, rotulo: 'Não considerar', dica: 'os atributos não seguram nada — só a raridade e os sockets (se ligados) decidem' },
  { valor: 1, rotulo: 'Qualquer atributo', dica: 'guarda a peça com 1 atributo ou mais (é o padrão)' },
  { valor: 2, rotulo: '2+ atributos', dica: 'guarda a peça com 2 atributos ou mais' },
  { valor: 3, rotulo: '3+ atributos', dica: 'guarda a peça com 3 atributos ou mais' },
  { valor: 4, rotulo: '4+ atributos', dica: 'guarda a peça com 4 atributos ou mais' },
];
const LINHAS_DO_NIVEL_MINIMO = [
  { valor: 1, rotulo: 'Qualquer', dica: 'qualquer nível serve' },
  { valor: 2, rotulo: 'N2', dica: 'pelo menos um atributo N2 ou mais' },
  { valor: 3, rotulo: 'N3', dica: 'pelo menos um atributo N3 ou mais' },
  { valor: 4, rotulo: 'N4', dica: 'pelo menos um atributo N4 ou mais' },
  { valor: 5, rotulo: 'N5', dica: 'pelo menos um atributo N5' },
];

/*
 * ---- A regra de atributos, dita numa frase só ----
 * Aparece no pé do bloco e no resumo da gaveta recolhida: "o que exatamente eu
 * vou guardar?" sem abrir nada. Desde 30/09 a quantidade é de atributos REAIS
 * da peça e o nível é "pelo menos um desse nível"; vale com OU junto da
 * raridade e dos sockets (ver `Afixos.decisaoDoLoot`).
 */
function fraseDaRegraDoAfixo() {
  const { quantos, nivel } = regraDeAtributos(ctx.state.character?.settings);
  if (!quantos) return 'Os atributos não seguram nada: só a raridade e os sockets (se ligados) decidem o que fica.';
  const daContagem = quantos === 1 ? 'pelo menos um atributo' : `${quantos} atributos ou mais`;
  return `Guarda a peça com ${daContagem}${nivel > 1 ? `, sendo um deles ${nomeDoNivel(nivel)}` : ''} — de qualquer raridade.`;
}

/*
 * ---- Na prévia da hunt ela vem RECOLHIDA ----
 *
 * O dono: "a página de filtro de loot na hora de escolher a caçada ficou
 * bugado; vê uma forma de otimizar ou compactar, porque tá ruim."
 *
 * Este bloco tem oito fileiras quando está ligado — o título, a legenda, os
 * quatro botões da cor, os quatro da contagem, a frase do "onde" e o botão de
 * escolher itens —, e ele mora ACIMA da grade de loot na coluna da esquerda. Na
 * tela do dono, com o rodapé grudado no pé, o que sobrava para a grade era menos
 * do que ela precisava e a última fileira de botões saía cortada por baixo do
 * rodapé.
 *
 * No filtro de loot ele continua aberto: aquela tela É sobre isso. Aqui ele é um
 * ajuste de passagem, e uma linha que diz a regra de agora basta para saber se
 * vale abrir. Uma vez aberto ele FICA aberto — `ctx.tabs` guarda a escolha,
 * para o redesenho a cada clique não fechar a gaveta na cara de quem a abriu.
 */
function resumoDaVendaAutomatica() {
  const marcados = (ctx.state.character?.itemRules?.soAfixo ?? []).length;
  const onde = marcados ? ` Só em ${marcados} ${marcados === 1 ? 'item' : 'itens'}.` : '';
  const raridade = fraseDaRaridade();
  const sockets = fraseDosSockets();
  const especificas = (ctx.state.character?.lootRegras ?? []).filter((r) => r.ativa !== false).length;
  return `Venda automática: ${fraseDaRegraDoAfixo()}${onde}${raridade ? ` OU ${raridade}.` : ''}${sockets ? ` OU sockets: ${sockets}.` : ''}${especificas ? ` E ${especificas} regra${especificas === 1 ? '' : 's'} específica${especificas === 1 ? '' : 's'} antes.` : ''}`;
}

/*
 * ---- Guardar por RARIDADE ----
 *
 * "aqui no loot filter tem que ter opção de escolher por raridade também."
 *
 * Mora ao lado da regra do afixo, no espaço que ela deixava vazio, e fala a
 * mesma língua: uma fileira de botões, o escolhido aceso, a legenda embaixo.
 * Cada botão sai na cor da raridade dele — a mesma do nome do item no balão, no
 * chat de loot e no mercado —, então não precisa de explicação.
 *
 * É um PISO, como "roxa para cima": "Épico para cima" guarda também o
 * lendário e o mítico. Ver `pisoDeRaridade`, no store.mjs.
 */
const LINHAS_DA_RARIDADE = [
  { valor: 0, raridade: null, rotulo: 'Não olhar', dica: 'a raridade não segura nada (é o padrão)' },
  { valor: 1, raridade: 'incomum', plural: 'incomuns', rotulo: 'Incomum para cima', dica: 'só o comum vai para o NPC' },
  { valor: 2, raridade: 'raro', plural: 'raros', rotulo: 'Raro para cima', dica: 'guarda o raro, o épico, o lendário e o mítico' },
  { valor: 3, raridade: 'épico', plural: 'épicos', rotulo: 'Épico para cima', dica: 'guarda o épico, o lendário e o mítico' },
  { valor: 4, raridade: 'lendário', plural: 'lendários', rotulo: 'Lendário para cima', dica: 'guarda o lendário e o mítico' },
  { valor: 5, raridade: 'mítico', plural: 'míticos', rotulo: 'Só mítico', dica: 'guarda apenas o mítico' },
];

function fraseDaRaridade() {
  const atual = Number(ctx.state.character?.settings?.guardarRaridade ?? 0);
  const linha = LINHAS_DA_RARIDADE.find((o) => o.valor === atual);
  return atual && linha ? `guarda ${linha.rotulo.toLowerCase()}` : '';
}

function escolhaDeRaridade() {
  const { state, send } = ctx;
  const atual = Number(state.character?.settings?.guardarRaridade ?? 0);

  const caixa = el('div', 'filtro-afixo filtro-raridade');
  caixa.append(el('b', null, 'Raridade na venda automática'));
  /*
   * A frase diz O QUE será guardado, com os nomes, e não a regra em abstrato.
   * O dono: "em vez de 'o item daquela raridade para cima nunca vai para o NPC',
   * fala que esses itens serão guardados, com estrela ou sem".
   */
  const guardadas = LINHAS_DA_RARIDADE.filter((o) => o.raridade && o.valor >= atual).map((o) => o.plural);
  const lista = guardadas.length > 1 ? `${guardadas.slice(0, -1).join(', ')} e ${guardadas.at(-1)}` : guardadas[0];
  /*
   * ---- Com a estrela ligada, as duas regras se SOMAM ----
   *
   * Report do Appa: com "épico para cima", o comum dourado continuava indo para
   * a mochila. Agora, com as duas regras ligadas, a peça precisa passar nas duas
   * (ver `presoNaBolsa`, no store.mjs) — e a frase diz exatamente isso, com o
   * degrau da estrela que está marcado ao lado.
   */
  let frase;
  if (!atual) frase = 'Escolha uma raridade: os itens dela para cima serão guardados, com atributo ou sem.';
  else frase = `Itens ${lista} são guardados, com atributo ou sem. Vale com OU junto dos atributos: uma peça de raridade mais baixa ainda fica se passar na regra de atributos.`;
  caixa.append(el('em', 'filter-legend', frase));

  const linha = el('div', 'filtro-afixo-opcoes');
  for (const opcao of LINHAS_DA_RARIDADE) {
    const cor = opcao.raridade ? ` ${classeDaRaridade({ rarity: opcao.raridade })} com-raridade` : '';
    const botao = el('button', `filtro-afixo-opcao${cor}${opcao.valor === atual ? ' ativo' : ''}`);
    botao.type = 'button';
    botao.append(el('span', null, opcao.rotulo));
    botao.title = opcao.dica;
    botao.onclick = () => {
      send({ t: 'settings', guardarRaridade: opcao.valor });
      // Pinta na hora, como as fileiras do afixo.
      state.character.settings = { ...(state.character.settings ?? {}), guardarRaridade: opcao.valor };
      ctx.redraw?.();
    };
    linha.append(botao);
  }
  caixa.append(linha);
  return caixa;
}

/*
 * As duas regras da venda automática lado a lado — afixo à esquerda, raridade
 * à direita —, no espaço que o dono marcou. Numa tela estreita elas empilham
 * (ver `.filtro-venda-regras`).
 */
function regrasDaVendaAutomatica() {
  const tudo = el('div', 'filtro-venda');
  const lado = el('div', 'filtro-venda-regras');
  // Os sockets moram na coluna da raridade: são as duas regras "da peça", e o grid fica em duas colunas.
  const raridade = escolhaDeRaridade();
  raridade.append(escolhaDeSockets());
  lado.append(escolhaDeAfixo(), raridade);
  tudo.append(lado, escolhaDeRegrasEspecificas(), comoOFiltroDecide());
  return tudo;
}

/*
 * ---- REGRAS ESPECÍFICAS (pedido do dono, 30/09) ----
 * "Comum E 1+ atributo E um N3+ → não vender", "Raro+ OU 2+ atributos OU N4+":
 * cada linha é um E (raridade + quantidade + nível) com uma ação; entre as
 * linhas, a PRIMEIRA que bate decide. Elas vêm ANTES das seções de cima.
 * Só olham equipamento. O servidor limpa e decide (`Bolsa.definirRegrasDeLoot`).
 */
const RARIDADES_DA_REGRA = ['comum', 'incomum', 'raro', 'épico', 'lendário', 'mítico'];
/*
 * O RASCUNHO das regras enquanto a pessoa mexe: a resposta do servidor a uma
 * mudança pode chegar DEPOIS da seguinte, e redesenhar com ela voltava o campo
 * ao valor antigo — que a próxima mudança gravava por cima (medido no teste da
 * tela: "Sem atributo" virava "1+"). Por 2 s depois de cada mudança vale o
 * rascunho; depois, o que o servidor confirmou.
 */
let rascunhoDasRegras = null;
function escolhaDeRegrasEspecificas() {
  const { state, send } = ctx;
  const regras = rascunhoDasRegras && Date.now() < rascunhoDasRegras.ate ? rascunhoDasRegras.lista : structuredClone(state.character?.lootRegras ?? []);
  // `estrutural`: criar, apagar ou mudar a ordem redesenha; mudar um campo não (o select já mostra).
  const gravar = (estrutural = false) => {
    rascunhoDasRegras = { lista: regras, ate: Date.now() + 2000 };
    send({ t: 'lootRegras', regras });
    state.character.lootRegras = structuredClone(regras);
    if (estrutural) ctx.redraw?.();
  };
  const caixa = el('div', 'filtro-regras-especificas');
  caixa.append(el('b', null, 'Regras específicas'));
  caixa.append(el('em', 'filter-legend', 'Cada linha junta raridade E atributos E nível. A primeira linha que bate decide, antes das seções de cima. Só olham equipamento.'));
  const select = (opcoes, valor, aoMudar, rotulo) => {
    const s2 = document.createElement('select');
    s2.setAttribute('aria-label', rotulo);
    for (const [v, texto] of opcoes) {
      const o = document.createElement('option');
      o.value = v;
      o.textContent = texto;
      s2.append(o);
    }
    s2.value = valor;
    s2.onchange = () => aoMudar(s2.value);
    return s2;
  };
  const opcoesDeRaridade = [['', 'Qualquer raridade'], ...RARIDADES_DA_REGRA.flatMap((r) => [[r, `Só ${r}`], ...(r !== 'mítico' ? [[`${r}+`, `${r[0].toUpperCase()}${r.slice(1)} ou acima`]] : [])])];
  regras.forEach((r, i) => {
    const linha = el('div', 'filtro-regra-linha');
    linha.dataset.indice = String(i);
    linha.append(el('span', 'filtro-regra-n', `${i + 1}.`));
    linha.append(
      select(opcoesDeRaridade, r.raridade ? `${r.raridade}${r.acima ? '+' : ''}` : '', (v) => {
        r.raridade = v ? v.replace('+', '') : null;
        r.acima = v.endsWith('+');
        gravar();
      }, 'Raridade'),
      el('span', 'filtro-regra-e', 'E'),
      select([['', 'Qualquer quantidade'], ['0', 'Sem atributo'], ['1', '1+ atributo'], ['2', '2+ atributos'], ['3', '3+ atributos'], ['4', '4+ atributos'], ['5', '5+ atributos'], ['6', '6 atributos']], r.quantos == null ? '' : String(r.quantos), (v) => {
        r.quantos = v === '' ? null : Number(v);
        gravar();
      }, 'Atributos'),
      el('span', 'filtro-regra-e', 'E'),
      select([['1', 'Qualquer nível'], ['2', 'um N2+'], ['3', 'um N3+'], ['4', 'um N4+'], ['5', 'um N5']], String(r.nivel ?? 1), (v) => {
        r.nivel = Number(v);
        gravar();
      }, 'Nível mínimo'),
      el('span', 'filtro-regra-e', '→'),
      select([['naoVender', 'Não vender'], ['naoColetar', 'Não coletar']], r.acao ?? 'naoVender', (v) => {
        r.acao = v;
        gravar();
      }, 'Ação')
    );
    const liga = document.createElement('input');
    liga.type = 'checkbox';
    liga.checked = r.ativa !== false;
    liga.title = 'Ligada';
    liga.onchange = () => {
      r.ativa = liga.checked;
      gravar();
    };
    const subir = el('button', 'ghost step', '↑');
    subir.title = 'Subir (a de cima decide primeiro)';
    subir.disabled = i === 0;
    subir.onclick = () => {
      [regras[i - 1], regras[i]] = [regras[i], regras[i - 1]];
      gravar(true);
    };
    const tirar = el('button', 'danger step', '✕');
    tirar.title = 'Apagar a regra';
    tirar.onclick = () => {
      regras.splice(i, 1);
      gravar(true);
    };
    linha.append(liga, subir, tirar);
    caixa.append(linha);
  });
  if (!regras.length) caixa.append(el('p', 'empty', 'Nenhuma regra específica. As seções de cima decidem sozinhas.'));
  const nova = el('button', 'ghost filtro-regra-nova', '+ Nova regra');
  nova.disabled = regras.length >= 12;
  nova.onclick = () => {
    regras.push({ raridade: 'comum', acima: false, quantos: 1, nivel: 1, acao: 'naoVender', ativa: true });
    gravar(true);
  };
  caixa.append(nova);
  return caixa;
}

/** A ordem da decisão e a prévia "com a sua configuração" (a mesma função da venda, no servidor). */
function comoOFiltroDecide() {
  const caixa = el('details', 'filtro-como-decide');
  caixa.open = !!ctx.tabs.comoDecideAberto;
  caixa.ontoggle = () => (ctx.tabs.comoDecideAberto = caixa.open);
  const resumo = document.createElement('summary');
  resumo.textContent = 'Como o filtro decide (e o que acontece com a sua configuração)';
  caixa.append(resumo);
  const ordem = el('ol', 'filtro-ordem');
  for (const passo of [
    'Não coletar (a lista) — fica no chão',
    'Não vender (a lista) — fica na bolsa',
    'Tier, imbuement, essência ou gema encaixada — fica',
    'Regras específicas — a primeira que bate decide',
    'Atributos do item (respeitando "Afixo só nestes")',
    'Sockets',
    'Raridade',
    'Nenhuma segurou — vende',
  ]) ordem.append(el('li', null, passo));
  caixa.append(ordem, el('em', 'filter-legend', 'Os passos 5, 6 e 7 valem com OU: basta um segurar. Uma regra de cima nunca é desfeita por uma de baixo.'));
  const previa = ctx.state.character?.filtroPrevia ?? [];
  if (previa.length) {
    const tabela = el('div', 'filtro-previa');
    const NOMES = { vender: 'vende', naoVender: 'não vende', naoColetar: 'não coleta' };
    for (const l of previa) {
      const linha = el('div', `filtro-previa-linha acao-${l.acao}`);
      linha.append(el('span', null, l.rotulo), el('b', null, NOMES[l.acao] ?? l.acao), el('i', null, l.motivo));
      tabela.append(linha);
    }
    caixa.append(tabela);
  }
  return caixa;
}

/*
 * ---- SOCKETS na venda automática ----
 *
 * O dono: "coloque o socket". A regra vale SOZINHA — a peça com os sockets
 * pedidos fica mesmo sem passar na raridade e no atributo: uma peça comum de
 * 4 sockets ligados vale pelos sockets (é assim no Path of Exile). Duas
 * fileiras: quantos ABERTOS e o maior grupo LIGADO. O servidor decide
 * (`Afixos.guardaPelosSockets`).
 */
const LINHAS_DE_SOCKETS = [
  { valor: 0, rotulo: 'Não olhar', dica: 'os sockets não seguram nada (é o padrão)' },
  { valor: 1, rotulo: '1+', dica: 'guarda a peça com pelo menos 1 socket aberto' },
  { valor: 2, rotulo: '2+', dica: 'guarda a peça com 2 sockets abertos ou mais' },
  { valor: 3, rotulo: '3+', dica: 'guarda a peça com 3 sockets abertos ou mais' },
  { valor: 4, rotulo: '4', dica: 'guarda só a peça com 4 sockets abertos (o máximo)' },
];
const LINHAS_DE_LIGADOS = [
  { valor: 0, rotulo: 'Não olhar', dica: 'os links não seguram nada (é o padrão)' },
  { valor: 2, rotulo: '2 ligados+', dica: 'guarda a peça com um grupo de 2 sockets ligados ou mais' },
  { valor: 3, rotulo: '3 ligados+', dica: 'guarda a peça com um grupo de 3 ligados ou mais' },
  { valor: 4, rotulo: '4 ligados', dica: 'guarda só a peça com os 4 sockets ligados' },
];

function fraseDosSockets() {
  const s = ctx.state.character?.settings ?? {};
  const abertos = Number(s.guardarSockets ?? 0);
  const ligados = Number(s.guardarLigados ?? 0);
  const partes = [];
  if (abertos) partes.push(abertos === 4 ? '4 sockets abertos' : `${abertos}+ socket${abertos === 1 ? '' : 's'} aberto${abertos === 1 ? '' : 's'}`);
  if (ligados) partes.push(ligados === 4 ? '4 sockets ligados' : `${ligados}+ sockets ligados`);
  return partes.length ? `guarda a peça com ${partes.join(' ou ')}, mesmo sem passar nas outras regras` : '';
}

function escolhaDeSockets() {
  const { state, send } = ctx;
  const caixa = el('div', 'filtro-sockets');
  caixa.append(el('b', null, 'Sockets na venda automática'));
  caixa.append(el('em', 'filter-legend', fraseDosSockets() ? `Vale sozinha: ${fraseDosSockets()}.` : 'Vale sozinha: a peça com os sockets escolhidos fica, mesmo sem passar na raridade e no atributo.'));
  for (const [chave, titulo, linhas] of [
    ['guardarSockets', 'Abertos', LINHAS_DE_SOCKETS],
    ['guardarLigados', 'Ligados', LINHAS_DE_LIGADOS],
  ]) {
    const atual = Number(state.character?.settings?.[chave] ?? 0);
    const linha = el('div', 'filtro-afixo-opcoes');
    linha.append(el('span', 'filtro-sockets-rotulo', titulo));
    for (const opcao of linhas) {
      const botao = el('button', `filtro-afixo-opcao${opcao.valor === atual ? ' ativo' : ''}`);
      botao.type = 'button';
      botao.dataset.regra = chave;
      botao.dataset.valor = String(opcao.valor);
      botao.append(el('span', null, opcao.rotulo));
      botao.title = opcao.dica;
      botao.onclick = () => {
        send({ t: 'settings', [chave]: opcao.valor });
        // Pinta na hora, como as outras fileiras.
        state.character.settings = { ...(state.character.settings ?? {}), [chave]: opcao.valor };
        ctx.redraw?.();
      };
      linha.append(botao);
    }
    caixa.append(linha);
  }
  return caixa;
}

function escolhaDeAfixo({ recolhido = false } = {}) {
  const { state, send } = ctx;
  const { quantos, nivel } = regraDeAtributos(state.character?.settings);
  const gravar = (chave, valor) => {
    send({ t: 'settings', [chave]: valor });
    // Pinta na hora: esperar a volta do servidor faz o clique parecer perdido.
    state.character.settings = { ...(state.character.settings ?? {}), [chave]: valor };
    // A regra nova grava as DUAS chaves: sem a outra, o servidor cairia na tradução das de antes.
    if (state.character.settings.guardarAtributos == null) state.character.settings.guardarAtributos = quantos;
    if (state.character.settings.guardarNivelMinimo == null) state.character.settings.guardarNivelMinimo = nivel;
    ctx.redraw?.();
  };
  const fileira = (titulo, linhas, atual, chave, outra) => {
    const bloco = el('div', 'filtro-atributos-fileira');
    bloco.append(el('span', 'filtro-sockets-rotulo', titulo));
    const linha = el('div', 'filtro-afixo-opcoes');
    for (const opcao of linhas) {
      const botao = el('button', `filtro-afixo-opcao${opcao.valor === atual ? ' ativo' : ''}`);
      botao.type = 'button';
      botao.dataset.regra = chave;
      botao.dataset.valor = String(opcao.valor);
      if (chave === 'guardarNivelMinimo' && opcao.valor > 1) {
        // Uma estrela na cor do nível, como no item (N1 cinza ... N5 dourada).
        const selo = el('i', 'item-estrelas');
        selo.append(el('b', `estrela n${opcao.valor}`, '★'));
        botao.append(selo);
      }
      botao.append(el('span', null, opcao.rotulo));
      botao.title = opcao.dica;
      botao.onclick = () => {
        // Gravar uma fileira grava a outra junto (a regra nova é o par).
        send({ t: 'settings', [outra.chave]: outra.valor });
        gravar(chave, opcao.valor);
      };
      linha.append(botao);
    }
    bloco.append(linha);
    return bloco;
  };

  const caixa = el('div', 'filtro-afixo');
  caixa.append(el('b', null, 'Atributos do item'));
  caixa.append(el('em', 'filter-legend', 'Itens com atributos podem ser preservados mesmo quando possuem raridade baixa. Conta os atributos REAIS da peça. Tier, imbuement, essência e gema encaixada nunca são vendidos.'));
  caixa.append(fileira('Quantidade', LINHAS_DA_QUANTIDADE, quantos, 'guardarAtributos', { chave: 'guardarNivelMinimo', valor: nivel }));
  if (quantos > 0) caixa.append(fileira('Nível mínimo', LINHAS_DO_NIVEL_MINIMO, nivel, 'guardarNivelMinimo', { chave: 'guardarAtributos', valor: quantos }));
  const regra = el('div', 'filtro-afixo-regra');
  regra.append(el('b', null, fraseDaRegraDoAfixo()));
  if (quantos > 0) regra.append(el('em', null, 'Vale com OU junto da raridade e dos sockets: basta passar em uma delas para a peça ficar.'));
  caixa.append(regra);

  if (quantos > 0) {
    const marcados = ctx.state.character?.itemRules?.soAfixo ?? [];
    const onde = el('div', 'filtro-afixo-onde');
    onde.append(
      el(
        'em',
        'filter-legend',
        marcados.length
          ? `Vale só em ${marcados.length} ${marcados.length === 1 ? 'item escolhido' : 'itens escolhidos'} — nos outros, os atributos não contam (a raridade e os sockets decidem).`
          : 'Vale em qualquer peça. Dá para escolher só algumas.'
      )
    );
    const escolher = el('button', 'ghost filtro-afixo-escolher', marcados.length ? `Escolher itens (${marcados.length})` : 'Escolher itens...');
    escolher.type = 'button';
    escolher.title = 'Marca em que peças a regra de atributos vale. Nenhuma marcada = vale em todas.';
    escolher.onclick = () => openItemPicker('soAfixo', 'Afixo só nestes itens');
    onde.append(escolher);
    if (marcados.length) {
      const grade = el('div', 'filter-grid');
      for (const id of marcados) {
        const cell = itemCell({ id, count: 1 }, 'soAfixo');
        cell.classList.add('so-afixo');
        cell.title = `${ctx.state.items[id]?.name ?? id} — clique para tirar`;
        cell.onclick = () => send({ t: 'itemRule', rule: 'soAfixo', id });
        grade.append(cell);
      }
      onde.append(grade);
    }
    caixa.append(onde);
  }
  if (!recolhido) return caixa;

  const gaveta = el('details', 'filtro-afixo-gaveta');
  gaveta.open = !!ctx.tabs.afixoAberto;
  gaveta.ontoggle = () => {
    ctx.tabs.afixoAberto = gaveta.open;
  };
  const resumo = document.createElement('summary');
  resumo.textContent = resumoDaVendaAutomatica();
  resumo.title = 'As regras de atributos, raridade e sockets na venda automática. Clique para mexer.';
  const raridade = escolhaDeRaridade();
  raridade.append(escolhaDeSockets());
  gaveta.append(resumo, caixa, raridade);
  return gaveta;
}

/** A legenda curta dos dois botões, para quem nunca viu a tela. */
function legendaDoFiltro() {
  const linha = el('div', 'filtro-legenda');
  linha.append(
    el('span', 'filtro-legenda-loot', 'Clique esquerdo: não coletar'),
    el('span', 'filtro-legenda-sell', 'Clique direito: não vender')
  );
  return linha;
}

/*
 * O botão do preset, o MESMO nos dois lugares que o usam: a prévia da hunt e o
 * filtro de loot. Quem decide o que o NPC compra é o servidor, com o catálogo
 * dele — aqui só se conta quantos são, para o botão dizer o que vai fazer.
 */
function botaoApenasNpc(ids) {
  const { state, send } = ctx;
  const compram = ids.filter((id) => (state.items[id]?.sell ?? 0) > 0).length;
  const botao = el('button', 'previa-pincel npc', 'Apenas o que NPC compra');
  botao.title =
    `${compram} de ${ids.length} itens têm comprador. Os outros passam a ficar no chão. ` +
    'É um ponto de partida: depois dá para marcar o que quiser à mão.';
  botao.disabled = !ids.length;
  botao.onclick = () => {
    send({ t: 'lootPreset', preset: 'npc', ids });
    ctx.redraw?.();
  };
  return botao;
}

/*
 * Uma celula de loot. `semRegra` tira o clique que marca "nao vender" e "nao
 * pegar" — e' a celula da sala de boss, onde as duas marcas nao teriam efeito
 * (ver `blocoDeDrops`), e uma marca sem efeito e' pior que marca nenhuma.
 */
function celulaComRegra(id, extra, { semRegra = false } = {}) {
  const cela = itemCell({ id, count: 1 }, 'filter');
  if (semRegra) {
    // A ficha do item continua; o que sai e' o clique que marca a regra.
    tipFor(cela, id, extra ?? '');
    return cela;
  }
  return ligarRegrasDoItem(cela, id, { titulo: extra });
}

/*
 * A ficha do bicho mostra as gemas do Gem Atelier — ver `loot-do-bicho.mjs`,
 * que guarda a queixa inteira e a regra. Aqui fica so' o atalho com o catalogo
 * ja' preenchido, que e' como as cinco telas desta casa chamam.
 */
const lootComGemas = (entry) => lootDoBicho(entry, ctx.state.catalog);

/** Os ids das gemas, para a tela poder dizer de onde elas vem. */
let idsDeGema = null;
function ehGema(id) {
  const gemas = ctx.state.catalog?.gemas;
  if (!gemas) return false;
  idsDeGema ??= new Set([...(gemas.caca ?? []), ...(gemas.boss ?? [])].map((linha) => linha.id));
  return idsDeGema.has(Number(id));
}

/*
 * ---- O que cai, e o que fazer com o que cai ----
 *
 * `semFiltro` desliga a segunda metade — as marcas de nao-vender/nao-pegar, o
 * preset do NPC e a regra de estrela.
 *
 * Ele existe para a sala de boss. "bosses sao reward chest, nao precisa ter o
 * filtro la do q pegar pq tudo que dropar vai para o deposito": o que cai de um
 * boss nunca passa pela bolsa de loot — vira UMA sacola no bau de recompensa
 * (ver `guardarSacola`, no servidor) e fica la ate' o dono ir buscar. Nao ha
 * venda automatica para escapar, nem capacidade para estourar, nem nada que uma
 * marca pudesse mudar.
 *
 * A lista de drops continua: ela e' o "vale a pena entrar?", que e' a pergunta
 * daquela tela. O que sai e' so' o que nao teria efeito nenhum ali.
 */
function blocoDeDrops(criaturas, titulo, { semFiltro = false } = {}) {
  const { state } = ctx;

  /*
   * A chance mostrada é a MAIOR entre as criaturas, não a soma.
   *
   * Somando, um item que cai de quatro bichos da mesma hunt aparecia com "180%
   * de chance". No ciclo, com quinze hunts, seria pior. O que o jogador quer
   * saber é o quanto aquilo aparece quando aparece — e isso é a melhor chance
   * entre quem larga.
   */
  const chances = new Map();
  for (const creature of criaturas ?? []) {
    for (const drop of lootComGemas(state.catalog.bestiary?.[creature.key])) {
      if (!state.items[drop.id]) continue;
      chances.set(drop.id, Math.max(chances.get(drop.id) ?? 0, drop.chance ?? 0));
    }
  }
  const drops = [...chances.entries()].sort((a, b) => b[1] - a[1]);

  const bloco = el('div', 'hunt-previa-bloco');
  bloco.append(el('b', null, `${titulo} (${drops.length})`));

  if (!drops.length) {
    bloco.append(el('em', 'words', 'nenhum drop registrado'));
    return bloco;
  }

  if (semFiltro) {
    bloco.append(
      el(
        'p',
        'previa-recompensa',
        'Tudo que ele largar vai inteiro para o baú de recompensa, numa sacola com o nome dele. ' +
          'Nada é vendido nem filtrado aqui.'
      )
    );
    const gradeSo = el('div', 'filter-grid rolagem');
    for (const [id, chance] of drops) {
      const pct = (chance * 100).toFixed(chance >= 0.01 ? 1 : 2).replace('.', ',');
      gradeSo.append(celulaComRegra(id, `${pct}% de chance`, { semRegra: true }));
    }
    bloco.append(gradeSo);
    return bloco;
  }

  // A barra de ferramentas: o preset do NPC e o botão de limpar.
  const ferramentas = el('div', 'previa-pinceis');
  ferramentas.append(botaoApenasNpc(drops.map(([id]) => id)));

  /*
   * Zerar: tira deste loot tudo que está marcado, nas duas listas.
   *
   * Só os itens desta tela, e não o filtro inteiro — quem entra aqui está
   * mexendo nesta caçada, e apagar de uma vez o que foi marcado em outras seria
   * uma surpresa cara. Para limpar tudo existe o botão do filtro de loot, que é
   * onde o filtro inteiro vive.
   */
  const rules = state.character.itemRules ?? { noSell: [], noLoot: [] };
  const marcados = drops.filter(([id]) => rules.noSell.includes(id) || rules.noLoot.includes(id));
  const zerar = el('button', 'previa-pincel zerar', `Zerar (${marcados.length})`);
  zerar.title = 'tira as marcas dos itens desta lista, nas duas listas';
  zerar.disabled = !marcados.length;
  zerar.onclick = () => {
    for (const [id] of marcados) {
      if (rules.noSell.includes(id)) ctx.send({ t: 'itemRule', rule: 'noSell', id });
      if (rules.noLoot.includes(id)) ctx.send({ t: 'itemRule', rule: 'noLoot', id });
    }
  };
  ferramentas.append(zerar);
  bloco.append(ferramentas);
  bloco.append(legendaDoFiltro());
  // O mesmo seletor do filtro de loot: quem esta escolhendo a hunt tambem
  // esta decidindo o que fazer com o que ela larga.
  bloco.append(escolhaDeAfixo({ recolhido: true }));

  /*
   * Todos, e não os vinte e quatro primeiros.
   *
   * O corte existia para a grade não empurrar o resto da tela para fora; agora
   * quem segura é a rolagem da própria grade. Cortar aqui escondia justamente o
   * que se quer marcar: o que não vender é quase sempre a ponta rara da lista,
   * que é onde o corte caía.
   */
  const grade = el('div', 'filter-grid rolagem');
  for (const [id, chance] of drops) {
    const pct = (chance * 100).toFixed(chance >= 0.01 ? 1 : 2).replace('.', ',');
    grade.append(celulaComRegra(id, `${pct}% de chance`));
  }
  bloco.append(grade);
  return bloco;
}

function previaDaHunt(hunt, { comFoto = true } = {}) {
  const { state } = ctx;
  const caixa = el('div', 'hunt-previa');

  /*
   * O mapa de verdade vem primeiro; o tema é a rede embaixo.
   *
   * Hunt desenhada no editor tem miniatura do próprio mapa — `npm run
   * hunt-thumb` recorta o trecho onde a rota mais passa, desenha a linha do
   * percurso por cima e planta as criaturas da hunt nele. Para as dezoito que
   * geram o mapa a cada sessão não há mapa para fotografar, e aí entra a
   * ilustração do tema.
   */
  /*
   * Boss não tem foto, e não é falta de arte.
   *
   * Ele acontece numa arena montada para a luta, não num pedaço de mapa que o
   * personagem percorre — não há percurso para recortar nem lugar para
   * fotografar. O que importa ali é o bicho e o que ele larga, e os dois estão
   * logo abaixo.
   */
  const candidatos = comFoto ? [hunt.id, hunt.theme].filter((nome) => nome && !artesSemArquivo.has(nome)) : [];
  if (candidatos.length) {
    const arte = document.createElement('img');
    arte.className = 'hunt-previa-arte';
    arte.alt = '';
    let vez = 0;
    const tentar = () => {
      if (vez >= candidatos.length) return void arte.remove();
      arte.src = `/client/assets/hunts/${candidatos[vez]}.png`;
    };
    arte.onerror = () => {
      artesSemArquivo.add(candidatos[vez]);
      vez += 1;
      tentar();
    };
    tentar();
    caixa.append(arte);
  }

  // Quantas voltas completas o personagem já deu neste percurso. Só aparece
  // depois da primeira: "0 voltas" não é informação, é ruído.
  const voltas = state.character.huntLaps?.[hunt.id] ?? 0;
  if (voltas) {
    caixa.append(el('p', 'hunt-previa-voltas', `Você já completou este percurso ${voltas}x`));
  }

  const colunas = el('div', 'hunt-previa-colunas');

  // ---- o que cai ----
  const bloco = blocoDeDrops(hunt.creatures, 'O que cai aqui', { semFiltro: !!hunt.boss });

  colunas.append(bloco);

  // ---- quem mora lá ----
  /*
   * A ficha da criatura mudou de lugar.
   *
   * Ela vivia atrás de um botão "Detalhes" no card da lista, o que pedia um
   * clique a mais para ver aquilo de que a decisão depende — se o bicho resiste
   * ao dano da sua arma, quanto ele bate, quanto ele dá. Agora ela está aqui,
   * do lado do loot, na mesma tela em que se escolhe entrar.
   *
   * O loot ficou de fora de propósito: ele já está na coluna da esquerda, somado
   * entre todas as criaturas, que é como o jogador vai encontrá-lo. Repetir por
   * bicho seria a mesma informação duas vezes na mesma tela.
   */
  const bichos = el('div', 'hunt-previa-bloco');
  const roster = (hunt.creatures ?? []).filter((creature) => state.catalog.bestiary?.[creature.key]);
  bichos.append(el('b', null, `Monstros daqui (${roster.length})`));

  if (!roster.length) {
    bichos.append(el('em', 'words', 'sem criaturas registradas'));
    colunas.append(bichos);
    caixa.append(colunas);
    return caixa;
  }

  // Com mais de um bicho, uma fileira de retratos escolhe de quem é a ficha.
  // Com um só, ela apareceria como uma aba solitária e sem função.
  if (!escolhidoNaPrevia || !roster.some((c) => c.key === escolhidoNaPrevia)) {
    escolhidoNaPrevia = roster[0].key;
  }

  if (roster.length > 1) {
    const abas = el('div', 'hunt-previa-abas');
    for (const creature of roster) {
      const entry = state.catalog.bestiary[creature.key];
      const aba = el('button', 'hunt-aba');
      aba.setAttribute('aria-selected', String(escolhidoNaPrevia === creature.key));
      aba.append(figuraDaCriatura(creature, state.catalog.bestiary, 34));
      aba.append(el('span', null, entry.name));
      aba.onclick = () => {
        escolhidoNaPrevia = creature.key;
        ctx.redraw?.();
      };
      abas.append(aba);
    }
    bichos.append(abas);
  }

  const entry = state.catalog.bestiary[escolhidoNaPrevia];
  const ficha = el('div', 'hunt-previa-ficha');

  const cabeca = el('div', 'hunt-previa-cabeca');
  cabeca.append(figuraDaCriatura({ key: escolhidoNaPrevia, look: entry.look, colors: entry.colors }, state.catalog.bestiary, 52));
  const titulo = el('div', 'action-text');
  titulo.append(el('b', null, entry.name));
  titulo.append(el('em', 'words', entry.class));
  cabeca.append(titulo);
  ficha.append(cabeca);

  // Passo 3: vida, experiência, armadura, velocidade, pontos de charm,
  // ocorrência e resistências. O 4 traria o loot, que já está na outra coluna.
  creatureSheet(ficha, entry, 3, { dicaDeLoot: false, key: escolhidoNaPrevia, huntId: hunt.id, dificuldade: ctx.tabs.dificuldade ?? 'facil' });
  bichos.append(ficha);
  colunas.append(bichos);

  caixa.append(colunas);
  return caixa;
}

/**
 * Escolher a hunt é escolher também como caçar nela: ficar só ali, repetindo,
 * ou girar entre ela e as próximas que o level já abriu, voltando à primeira
 * depois da última.
 */
function askRunMode(hunt, list) {
  ctx.openModal(hunt.name, (body) => {
    /*
     * `ctx.redraw` é o que faz as marcas de loot aparecerem.
     *
     * `openModal` chama o construtor uma vez e pronto. Sem registrar o redesenho
     * aqui, marcar um item não pintava a célula. O painel também é redesenhado
     * sozinho quando as listas do filtro mudam, porque elas entram na
     * assinatura do `refreshOpenPanel`.
     */
    const desenhar = () => {
      body.innerHTML = '';
      montarEscolha(body, hunt, list);
    };
    ctx.redraw = desenhar;
    desenhar();
  });
}

function montarEscolha(body, hunt, list) {
  /*
   * "Voltar" agora é a primeira coisa da tela, e não a última.
   *
   * Ele vivia no pé do rodapé, abaixo dos dois botões de modo — o lugar mais
   * distante da tela justo para a ação mais inocente dela, e a única saída
   * visível para quem só queria olhar outra hunt. No topo ele fica onde a mão
   * já está quando o olho corre a lista de volta, e o rodapé fica só com o que
   * COMEÇA a caçada.
   */
  const topo = el('div', 'previa-topo');
  const voltar = el('button', 'ghost modal-back', '← Voltar para as hunts');
  voltar.onclick = () => {
    chegadaNaLista = 'voltar';
    openHunts();
  };
  topo.append(voltar);
  // O botão das paradas, à direita do Voltar. Ver `botaoDeParadas`.
  topo.append(botaoDeParadas(() => ctx.redraw?.()));
  body.append(topo);
  // A gaveta abre LOGO ABAIXO do botão, e não no rodapé: uma gaveta que abre
  // do outro lado da tela não é lida como resposta ao clique.
  if (paradasAbertas) body.append(blocoDeParadas(() => ctx.redraw?.()));

  body.append(previaDaHunt(hunt));

  /*
   * Os botões moram num rodapé grudado no pé da janela.
   *
   * A prévia é alta de propósito — foto, todo o loot, a ficha do bicho —, e
   * numa tela de 848px de altura ela passava do fundo. Como `sticky`, o rodapé
   * fica sempre à vista e quem rola é só a prévia acima dele.
   *
   * O que ele carrega tem de caber sem rolagem, e por isso os ajustes ficam
   * numa fileira só: o convite virou um botão, as condições de parada viraram
   * uma linha, e a frase "Como você quer caçar aqui?" saiu — os dois botões
   * grandes logo abaixo já são a pergunta.
   */
  const rodape = el('div', 'modal-rodape');

  const ajustes = el('div', 'previa-ajustes');
  ajustes.append(blocoDeAmigos(() => ctx.redraw?.()));
  rodape.append(ajustes);

  /*
   * Dois modos, e não três.
   *
   * "Só esta hunt" era a Caça Automática com uma hunt só — dois caminhos para
   * a mesma coisa, e o jogador tinha de escolher entre eles antes de saber o
   * que queria. Agora marcar uma hunt na Caça Automática já quer dizer
   * "repete esta"; a roda fecha a volta e cai nela mesma.
   *
   * A cor separa os dois de longe: laranja é o modo que joga sozinho, verde é
   * o modo em que quem joga é você. Eram dois retângulos iguais de borda
   * cinzenta, e para saber qual era qual era preciso ler.
   */
  const opcoes = el('div', 'run-modes');

  const ciclo = el('button', 'run-mode cycle', 'Caça Automática');
  /*
   * Direto na hunt clicada. A tela de rota (marcar até 5 hunts) saiu — o
   * dono: "clico em caça automática e abre isso, sendo que não aparece nem a
   * hunt que cliquei; quero tirar isso". Ela listava as hunts pelo LEVEL, e
   * na campanha elas abrem pelo progresso; e o "Avançar sozinho" da barra da
   * fase já faz o papel de seguir de uma hunt para a outra.
   */
  ciclo.append(el('em', null, 'ele anda, mira e bate sozinho'));
  ciclo.onclick = () => startRun(hunt, 'single');

  /*
   * O outro modo: jogar a hunt no braço.
   *
   * Mesmo mapa, mesmos monstros, mesma conta de loot e experiência — só sem a
   * rota e sem a mira automáticas. É o Tibia dentro do Draevor Idle.
   */
  const online = el('button', 'run-mode manual', 'Caça Online');
  /*
   * O bônus anunciado na própria placa.
   *
   * Ele já era pago desde que a Caça Online existe, e em lugar nenhum era dito:
   * o jogador escolhia entre os dois modos sem saber que um deles rende 15% a
   * mais. O número vem do catálogo do servidor — que é quem o cobra —, então a
   * placa não pode ficar mentindo se o valor mudar.
   */
  const bonus = ctx.state.catalog?.bonusOnline ?? 0;
  if (bonus) online.append(el('b', 'run-mode-bonus', `+${bonus}% de XP e +${bonus}% de loot`));
  /*
   * ---- Uma linha, e o resto no balão ----
   *
   * A frase inteira — "esquerdo anda, direito ataca, nada dispara sozinho" —
   * quebrava em duas linhas dentro do botão, e com o bônus em cima disso os
   * dois modos passavam de 125px de altura. Eles moram no rodapé grudado no pé
   * da janela: cada pixel deles é um pixel que a grade de loot perde, e foi
   * daí que veio o "a página de filtro de loot ficou bugado" — a grade ficava
   * sem espaço e a coluna transbordava por baixo do rodapé.
   *
   * A frase completa não se perdeu: ela já estava, palavra por palavra, no
   * balão logo abaixo. Aqui fica o que decide entre os dois modos.
   */
  online.append(el('em', null, 'você anda, mira e dispara'));
  // O convite vale aqui também: cada um comanda o próprio boneco no mesmo mapa.
  tipTexto(
    online,
    `Você anda, mira e dispara. Por jogar no braço, a caçada paga ${bonus}% a mais de experiência e ${bonus}% a mais de loot. Os amigos marcados entram junto — cada um no comando do personagem dele.`
  );
  online.onclick = () => startRun(hunt, 'online');

  opcoes.append(ciclo, online);
  rodape.append(opcoes);
  body.append(rodape);
}

/*
 * A tela do boss: mesma prévia, sem a foto.
 *
 * Ela não existia — clicar num boss entrava direto na luta, sem chance de ver
 * o que ele resiste e o que ele larga. O que muda em relação à hunt é a roda:
 * boss é sempre entrada única (tem espera própria), então não há lista de
 * hunts para marcar.
 *
 * ---- Os DOIS modos, e o que a sala cobra ----
 *
 * "tem que ter a opçao de enfrentar o boss no modo automatico tambem, só que ai
 * no modo online é 15% mais chance de loot".
 *
 * Havia um botão só, e ele entrava sempre na Caça Online — não por escolha:
 * a sala não tem rota, e o servidor empurrava toda hunt sem rota para o manual.
 *
 * As três regras da sala vão escritas ANTES dos botões, e não num balão, porque
 * as três custam caro e nenhuma dá para descobrir de dentro: a espera é cobrada
 * na entrada (perder gasta a vez), o relógio é de 25 minutos, e a saída é um
 * teleporte no chão da sala. Quem entra sem saber disso entra enganado.
 */
function askBoss(hunt) {
  ctx.openModal(hunt.name, (body) => {
    const desenhar = () => {
      body.innerHTML = '';
      body.append(previaDaHunt(hunt, { comFoto: false }));

      const rodape = el('div', 'modal-rodape');
      if (hunt.blurb) rodape.append(el('p', 'gate-note', hunt.blurb));

      const horas = hunt.cooldownHours ?? 0;
      const regras = el('ul', 'boss-regras');
      // Boss de fim de ato: sem espera nenhuma (entra quantas vezes quiser, inclusive depois de morrer ou de vencer).
      regras.append(
        el(
          'li',
          null,
          hunt.semEspera
            ? 'Sem espera: este é o boss de fim de ato — você pode entrar de novo quantas vezes quiser.'
            : horas
              ? `A espera de ${horas}h começa quando você ENTRA — mesmo que ele não caia.`
              : 'A espera começa quando você ENTRA — mesmo que ele não caia.'
        )
      );
      regras.append(el('li', null, 'Você tem 25 minutos lá dentro, nos dois modos.'));
      regras.append(el('li', null, 'Para sair antes, pise no teleporte da sala: você volta ao templo.'));
      regras.append(el('li', null, 'Tudo que ele largar vai para o baú de recompensa — um por pessoa.'));
      regras.append(
        el(
          'li',
          null,
          'Dá para ir em até cinco: monte a party, marque quem vai e o time entra junto, pelo lobby. ' +
            'Ou vá sozinho, sem desfazer o time.'
        )
      );
      /*
       * A regra que fecha a sala, escrita ANTES de alguém entrar.
       *
       * Ela vale para quem fica de fora: depois do primeiro ponto de dano, nem
       * convite nem "entrar na caçada" alcançam mais a sala. Quem descobrir
       * isso só no momento de entrar vai achar que o botão quebrou.
       */
      regras.append(
        el('li', null, 'Depois que a luta começa, ninguém mais entra — chame antes, pelo lobby.')
      );
      rodape.append(regras);

      /*
       * ---- O convite também aqui ----
       *
       * "no fazer boss tem que ter a opção de entrar no boss com até 5 pessoas".
       *
       * O mesmo botão da prévia de hunt, e de propósito: quem monta o time faz
       * o mesmo gesto nos dois lugares. E é AQUI que ele precisa estar — depois
       * de entrar na sala o convite está fechado (a espera de doze horas já
       * começou a correr para quem entrou), então esta tela é a última chance
       * de chamar alguém.
       */
      const ajustes = el('div', 'previa-ajustes');
      ajustes.append(blocoDeAmigos(() => ctx.redraw?.()));
      rodape.append(ajustes);

      const opcoes = el('div', 'run-modes');

      const automatica = el('button', 'run-mode cycle', 'Caça Automática');
      automatica.append(el('em', null, 'ele mira e bate sozinho'));
      tipTexto(
        automatica,
        'O personagem persegue o boss e ataca sozinho, com a barra de ações que você montou. ' +
          'Na sala não há rota para seguir: o alvo é um só e está a três casas.'
      );
      automatica.onclick = () => startRun(hunt, 'single');

      const online = el('button', 'run-mode manual', 'Caça Online');
      const bonus = ctx.state.catalog?.bonusOnline ?? 0;
      if (bonus) online.append(el('b', 'run-mode-bonus', `+${bonus}% de XP e +${bonus}% de loot`));
      online.append(el('em', null, 'você anda, mira e dispara'));
      tipTexto(
        online,
        `Você anda, mira e dispara. Por jogar no braço, a luta paga ${bonus}% a mais de experiência ` +
          `e ${bonus}% a mais de chance em cada linha do loot dele.`
      );
      online.onclick = () => startRun(hunt, 'online');

      opcoes.append(automatica, online);
      rodape.append(opcoes);

      const acoes = el('div', 'confirm-actions');
      const voltar = el('button', 'ghost', 'Voltar');
      voltar.onclick = () => {
        chegadaNaLista = 'voltar';
        openHunts();
      };
      acoes.append(voltar);
      rodape.append(acoes);
      body.append(rodape);
    };
    ctx.redraw = desenhar;
    desenhar();
  });
}


/*
 * ---- A tela de treino ----
 *
 * Três cards, e mais nada.
 *
 * Havia um passo antes: escolher a perícia numa grade de sete botões. Ele saiu
 * porque era uma pergunta que o jogo já responde sozinho — quem treina é a ARMA
 * EQUIPADA, exatamente como numa caçada. De machado na mão sobe axe; de rod,
 * magic level; de arco, distance. Perguntar "o que você quer treinar" e depois
 * treinar outra coisa é a pior combinação possível: a tela promete uma escolha
 * que ela não tem como cumprir.
 *
 * Quem quiser treinar outra perícia troca de arma, que é o gesto que o jogo
 * inteiro já usa para isso.
 */
const MODOS_DE_TREINO = [
  {
    id: 'exercise',
    nome: 'Exercise',
    resumo: 'Gasta as cargas de uma arma de treino e sobe rápido, sem sair da cidade.',
    pronto: true,
  },
  {
    id: 'online',
    nome: 'Treino online',
    resumo: 'Você vai ao pátio e bate num boneco que não morre. Rende como caçar — e custa o mesmo tempo.',
    pronto: true,
  },
  {
    id: 'offline',
    nome: 'Treino offline',
    resumo:
      'Você sai do jogo treinando. Rende menos que o pátio, não precisa da aba aberta — e gasta a stamina de treino, que caçar devolve.',
    pronto: true,
  },
];

/*
 * ---- Confirmar o treino offline ----
 *
 * Duas perguntas numa tela só: o QUE treinar e se é isso mesmo.
 *
 * `shielding` não está na lista porque ele sobe junto com qualquer escolha —
 * oferecê-lo seria oferecer o que a pessoa já ganha, e escolhê-lo trocaria um
 * treino de duas perícias por um de uma.
 *
 * O aviso de que ela vai SAIR do jogo aparece em cima do botão, e não no
 * título. É a consequência que ninguém espera de um botão chamado "confirmar",
 * e ela tem de estar onde o olho já está quando a mão vai clicar.
 */
function confirmarOffline(body) {
  const { state, send } = ctx;
  const character = state.character;
  const lista = state.catalog.treinoOffline ?? state.catalog.trainable ?? [];
  let escolhida = lista.includes(character.derived?.skillName)
    ? character.derived.skillName
    : lista[0];

  body.replaceChildren();

  const voltar = el('button', 'ghost', '‹ voltar');
  voltar.onclick = () => {
    body.replaceChildren();
    renderTraining(body);
  };
  body.append(voltar, el('h3', null, 'Treino offline'));
  body.append(
    el(
      'p',
      'shop-note',
      'Escolha o que treinar. O escudo sobe junto, qualquer que seja a escolha — por isso ele não está na lista.',
    ),
  );

  const grid = el('div', 'train-grid');
  const desenhar = () => {
    grid.replaceChildren();
    for (const skill of lista) {
      const info = skill === 'magic' ? character.magic : character.skills[skill];
      const botao = el('button');
      botao.setAttribute('aria-selected', String(escolhida === skill));
      botao.append(
        artOrUiIcon(`sk-${skill}`, skill),
        el('b', null, skill === 'magic' ? 'magic level' : skill),
        el('em', null, `atual ${info?.value ?? 0}`),
      );
      botao.onclick = () => {
        escolhida = skill;
        desenhar();
      };
      grid.append(botao);
    }
  };
  desenhar();
  body.append(grid);

  body.append(
    el(
      'p',
      'relatorio-motivo',
      'Ao confirmar, você sai deste personagem e volta para a lista. O treino continua rodando.',
    ),
  );

  /*
   * `confirm-actions` traz as duas cores que o jogo já usa para esse par: verde
   * no que segue, vermelho no que desfaz. São as mesmas do filtro de loot para
   * "protegido" e "barrado" — não vale inventar um terceiro vocabulário de cor
   * para a mesma pergunta.
   */
  const acoes = el('div', 'confirm-actions');
  const cancelar = el('button', 'danger', 'Cancelar');
  cancelar.onclick = () => {
    body.replaceChildren();
    renderTraining(body);
  };
  const confirmar = el('button', 'primary', 'Confirmar');
  confirmar.onclick = () => send({ t: 'training', action: 'start', mode: 'offline', skill: escolhida });
  acoes.append(cancelar, confirmar);
  body.append(acoes);
}

/*
 * ---- Escolher a arma de treino ----
 *
 * Duas telas em uma: a arma que já está NA MÃO (com as cargas que sobraram) e
 * as que estão na mochila.
 *
 * A da mão vem primeiro e sozinha porque ela manda: enquanto houver uma pela
 * metade, o servidor recusa trocar — a mochila guarda id e quantidade, não
 * cargas, e devolvê-la significaria devolvê-la cheia. Mostrar as outras como
 * clicáveis nesse estado seria oferecer um botão que só sabe dizer não.
 */
/*
 * `semVoltar` é para quando esta tela é a janela inteira (o clique direito no
 * boneco): ali não há para onde voltar, e um botão "‹ voltar" que leva à aba de
 * Aventuras seria uma porta para um lugar em que o jogador nunca esteve.
 */
/*
 * ---- O lobby: a tela de combinar antes de entrar ----
 *
 * "faz meio que um lobby bonitinho pra chamar a pessoa e quando todos derem
 * pronto todos entram, comeca contar o coldown e etc."
 *
 * Ela desenha tres coisas, e só três: para onde o time vai, quem está pronto, e
 * quem NÃO PODE entrar — com o motivo do lado do nome. A terceira é a que
 * justifica a tela existir: num "não dá para entrar" sem dono, cinco pessoas
 * ficam adivinhando de quem é o problema.
 *
 * O botão de começar é do líder e só acende com todo mundo pronto e ninguém
 * barrado. O servidor confere de novo — ver a ação `comecar`, no `index.mjs`.
 */
/*
 * O título da janela, num lugar só.
 *
 * O `main.mjs` compara por ele para saber se o que está aberto é o lobby — é
 * assim que a janela se fecha sozinha quando o líder começa a caçada. Escrever
 * a frase duas vezes faria a comparação parar de valer no dia em que alguém
 * mudasse uma das duas, sem erro nenhum aparecer.
 */
/*
 * O lobby no formato que `escolhasDaPosicao` lê.
 *
 * Aquela função foi escrita para a party DA CAÇADA, e os nomes dos campos são
 * os de lá. Traduzir aqui — numa função de quatro linhas — é o que permite as
 * duas telas usarem a mesma caixa de escolhas em vez de terem uma cada.
 *
 * Só os CONVOCADOS entram na lista: pôr na ponta alguém que não vai seria uma
 * formação sem ponta no instante em que a caçada abrisse, e é o que o servidor
 * recusa (ver `escolherAFrente`).
 */
function grupoDoLobby(lobby, state) {
  const chamados = (lobby.membros ?? []).filter((m) => m.convocado !== false);
  return {
    lider: lobby.lider,
    /* Quem manda na fila é quem armou o lobby — ele é o líder da party. */
    mandaNaFila: lobby.lider,
    frente: lobby.frente ?? lobby.lider,
    membros: chamados.map((m) => ({ name: m.nome })),
    seguirQuem: state.character?.settings?.seguirQuem ?? '',
    coleira: state.character?.settings?.coleira ?? 5,
  };
}

export const TITULO_DO_LOBBY = 'Lobby da party';

export function openLobby() {
  const { state, send } = ctx;

  ctx.openModal(TITULO_DO_LOBBY, (body) => {
    const desenhar = () => {
      body.innerHTML = '';
      const lobby = state.character?.lobby;
      if (!lobby) {
        body.append(el('p', 'gate-note', 'Não há lobby aberto. O líder escolhe a sala pela tela de Aventuras.'));
        const acoes = el('div', 'confirm-actions');
        const fechar = el('button', 'ghost', 'Fechar');
        fechar.onclick = () => ctx.closeModal();
        acoes.append(fechar);
        body.append(acoes);
        return;
      }

      const cabeca = el('div', 'lobby-cabeca');
      cabeca.append(el('b', null, lobby.hunt));
      cabeca.append(
        el(
          'em',
          null,
          lobby.tipo === 'autoboss'
            ? 'Sequência automática — um boss atrás do outro, pulando quem estiver em espera'
            : lobby.modo === 'online'
              ? 'Caça Online — você anda, mira e dispara'
              : 'Caça Automática'
        )
      );
      cabeca.append(el('span', 'lobby-conta', `${lobby.prontos} de ${lobby.total} ${lobby.prontos === 1 ? 'pronto' : 'prontos'}`));
      body.append(cabeca);

      const lista = el('div', 'lobby-gente');
      for (const membro of lobby.membros) {
        /*
         * Quem NAO foi chamado desta vez aparece apagado, e nao some.
         *
         * Sumir deixaria o time sem saber se a pessoa foi deixada de fora de
         * proposito ou se a tela quebrou — e quem ficou de fora precisa ver
         * para pedir ao lider que o chame. Ver `convocadosDo`, no servidor.
         *
         * `convocado` so' vem de servidores novos: uma aba velha nao recebe o
         * campo, e `!== false` faz todo mundo continuar sendo chamado.
         */
        const chamado = membro.convocado !== false;
        const card = el(
          'div',
          `lobby-membro${chamado && membro.pronto ? ' pronto' : ''}${
            chamado && membro.impedido ? ' impedido' : ''
          }${chamado ? '' : ' fora'}`
        );
        /*
         * ---- O boneco, a vocação e o level ----
         *
         * "no lobby da party seria interessante mostrar a vocação de cada um, o
         * level, a sprite do addon atual, o ícone de vocação ao lado da vocação".
         *
         * O card dizia NOME e nada mais, e esta é a última tela antes de uma
         * sala que cobra doze horas de espera: quem lidera decide se entra com
         * dois druidas olhando exatamente estas três coisas, e antes tinha de
         * fechar o lobby, abrir a party, olhar, e voltar.
         *
         * O desenho é o mesmo do card da party — `outfitCanvas` com o outfit
         * VIVO, addons inclusive — e o ícone é o da PERÍCIA da vocação, como
         * lá. Duas telas que mostram a mesma pessoa não podem mostrá-la de
         * jeitos diferentes.
         */
        const topo = el('div', 'lobby-topo');
        if (membro.outfit?.type && outfitInfo(membro.outfit.type)) {
          const retrato = el('div', 'lobby-retrato');
          retrato.append(outfitCanvas(membro.outfit.type, membro.outfit, 32, 2, true));
          topo.append(retrato);
        }

        const coluna = el('div', 'lobby-coluna');
        const nome = el('div', 'lobby-nome');
        nome.append(el('b', null, membro.nome));
        if (membro.lider) nome.append(el('i', 'lobby-coroa', '★'));
        /* Quem puxa a fila, dito no card de quem puxa. */
        if (membro.nome === lobby.frente) nome.append(el('i', 'lobby-ponta', 'na frente'));
        coluna.append(nome);

        if (membro.vocation) {
          const sub = el('div', 'lobby-sub');
          const arte = artOrUiIcon(PERICIA_DA_VOCACAO[membro.vocation] ?? 'sk-misc', '');
          arte.classList.add('party-voc-icone');
          sub.append(arte);
          sub.append(el('span', null, `${membro.vocationName ?? NOME_DA_VOCACAO[membro.vocation] ?? membro.vocation} ${membro.level ?? ''}`.trim()));
          coluna.append(sub);
        }
        topo.append(coluna);
        card.append(topo);
        /*
         * O card diz POR QUE a pessoa está pronta.
         *
         * Um "pronto" que ninguém deu deixa o time sem saber se aquela pessoa
         * está mesmo na frente da tela. "pronto (automático)" responde isso sem
         * ocupar uma linha a mais. Ver `autoNoLobby`, no servidor.
         */
        card.append(
          el(
            'em',
            null,
            !chamado
              ? 'fica de fora desta'
              : membro.impedido
              ? membro.impedido
              : membro.pronto
                ? membro.auto
                  ? 'pronto (automático)'
                  : 'pronto'
                : membro.auto
                  ? 'no automático'
                  : 'esperando'
          )
        );
        lista.append(card);
      }
      body.append(lista);

      if (lobby.impedidos.length) {
        body.append(
          el(
            'p',
            'gate-note',
            'Ninguém entra enquanto alguém estiver barrado — entrar com o time pela metade gastaria a espera de quem foi.'
          )
        );
      }

      /*
       * ---- E as configurações de formação, aqui dentro ----
       *
       * "as mesmas configurações do modal party ali no lobby da party também:
       * tipo, quem seguir, andar atrás de, e pro líder escolher quem vai na
       * frente. A mesma coisa que tem no modal de party, mas que dê para mexer
       * no lobby da party também, pra ficar mais fácil de a pessoa conseguir
       * mexer antes de entrar na caçada/boss. Mas o modal de party não mexa em
       * nada, vai continuar como está — isso seria apenas uma melhoria física e
       * atalho pra conseguir mexer antes."
       *
       * Então é o MESMO `escolhasDaPosicao` do painel de Amigos, com o mesmo
       * visual e os mesmos comandos: uma segunda implementação das três caixas
       * seria duas telas que configuram a mesma coisa e discordam no dia em que
       * uma delas mudasse.
       *
       * O que muda é a fonte: lá o `grupo` é a party DA CAÇADA (`state.hunt`),
       * e aqui não há caçada nenhuma — o grupo é o próprio lobby, traduzido
       * para os campos que a função lê. Ver `grupoDoLobby`.
       */
      if (lobby.tipo !== 'autoboss') {
        const config = el('div', 'lobby-config');
        escolhasDaPosicao(config, grupoDoLobby(lobby, state), state, (m) => {
          /*
           * A escolha da PONTA vai para o lobby, e não para a caçada: o
           * `party action: 'frente'` exige uma sessão em pé, e aqui ninguém
           * entrou ainda. As outras duas (andar atrás de, coleira) vivem no
           * personagem e valem fora da caçada — essas passam direto.
           */
          if (m.t === 'party' && m.action === 'frente') return send({ t: 'lobby', action: 'frente', name: m.name });
          return send(m);
        });
        if (config.childElementCount) body.append(config);
      }

      /* E a frase para quem abriu a janela e não foi chamado desta vez. */
      if (lobby.membros.find((m) => m.eu)?.convocado === false) {
        body.append(
          el(
            'p',
            'gate-note',
            `${lobby.lider} não chamou você para esta caçada. Você continua na party — é só pedir para ser chamado na próxima.`
          )
        );
      }

      /*
       * ---- "Parar em", aqui também: CADA UM marca o seu ----
       *
       * "cada um marca o teu, só que deixa otimizado pra mostrar assim igual a
       * foto 2, igual como é lá em hunts."
       *
       * É o MESMO botão da prévia da hunt — `botaoDeParadas` e `blocoDeParadas`,
       * sem cópia — porque é a mesma pergunta: fechado ele cabe numa linha e diz
       * o que está ligado; aberto mostra as quatro caixas. Quem entra pelo lobby
       * nunca passa pela prévia, e era por isso que o convidado entrava sem
       * condição de parada nenhuma.
       *
       * Vale para o líder também: ele entra por aqui, e a marcação dele viajava
       * só pela prévia — pelo lobby ela se perdia.
       *
       * `desenhar` refaz a janela (é assim que a gaveta abre); o que a pessoa
       * mexe vai para o servidor sozinho, dentro de `blocoDeParadas`.
       */
      const paradasNoLobby = el('div', 'lobby-paradas');
      paradasNoLobby.append(botaoDeParadas(desenhar));
      if (paradasAbertas) paradasNoLobby.append(blocoDeParadas(desenhar));
      body.append(paradasNoLobby);

      const acoes = el('div', 'confirm-actions');
      const sair = el('button', 'ghost', lobby.souLider ? 'Cancelar' : 'Fechar');
      sair.onclick = () => {
        if (lobby.souLider) send({ t: 'lobby', action: 'cancelar' });
        ctx.closeModal();
      };
      acoes.append(sair);

      /*
       * O "pronto" é de quem NÃO é líder. O líder já disse que vai no instante em
       * que escolheu a sala; um segundo botão para ele confirmar o que ele
       * mesmo acabou de dizer não pergunta nada.
       */
      const eu = lobby.membros.find((m) => m.eu);
      /*
       * ---- Quem não foi chamado não dá "pronto" ----
       *
       * Report do dono: "mesmo eu desmarcando alguém tá aparecendo o convite
       * pra pessoa". A janela já não salta mais na tela dele (ver
       * `chamadoNoLobby`, em main.mjs), mas ele ainda pode abri-la pelo menu —
       * e ali o botão "Pronto" prometia uma coisa que o servidor recusa.
       *
       * Apagado com o motivo escrito, e não sumido: ele precisa entender que o
       * time foi sem ele de propósito, e é o líder quem pode mudar isso.
       */
      const fuiChamado = eu?.convocado !== false;
      if (!lobby.souLider) {
        const pronto = el('button', eu?.pronto ? 'ghost' : 'primary', eu?.pronto ? 'Ainda não' : 'Pronto');
        pronto.disabled = !!eu?.impedido || !fuiChamado;
        if (!fuiChamado) {
          tipTexto(pronto, `${lobby.lider} não chamou você para esta — o time vai sem você desta vez.`);
        } else if (eu?.impedido) tipTexto(pronto, `Você não pode entrar: ${eu.impedido}.`);
        pronto.onclick = () => {
          // A marcação dele, antes do "pronto": o salvamento é atrasado (ver
          // `salvarParadas`) e o clique pode vir no mesmo quadro da digitação.
          send({ t: 'limites', limites: limitesEscolhidos() });
          send({ t: 'lobby', action: eu?.pronto ? 'esperar' : 'pronto' });
        };
        acoes.append(pronto);

        /*
         * ---- "Da próxima vez, aceite por mim" ----
         *
         * Report do O O: com dois personagens em telas diferentes, ele troca de
         * tela a cada boss só para apertar este botão. Ele pediu o automático
         * "na primeira vez que for aceitar" — e é por isso que a caixinha fica
         * AQUI, colada no botão, e não enterrada numa tela de opções: o momento
         * de oferecer é o momento em que a pessoa está aceitando.
         *
         * Só para quem não é líder, como o próprio botão: o líder já vai pelo
         * ato de escolher a sala.
         */
        const auto = el('label', 'lobby-auto');
        const marca = document.createElement('input');
        marca.type = 'checkbox';
        marca.checked = !!state.character?.autoPronto;
        marca.onchange = () => send({ t: 'settings', autoPronto: marca.checked });
        auto.append(marca, el('span', null, 'Aceitar automaticamente'));
        tipTexto(
          auto,
          'O líder escolhe a sala e você entra pronto, sem trocar de tela.\n' +
            'Quem entra continua sendo o líder, e dá para desmarcar antes de ele ir.'
        );
        body.append(auto);
      } else {
        const comecar = el('button', 'primary', lobby.podeComecar ? 'Todos prontos — entrar' : 'Esperando o time');
        comecar.disabled = !lobby.podeComecar;
        if (!lobby.podeComecar && lobby.impedidos.length) tipTexto(comecar, lobby.impedidos.join('\n'));
        comecar.onclick = () => {
          // A marcação dele vai junto: o servidor cai no `settings.limites`
          // quando ela não vem, mas o clique pode ser no mesmo quadro em que
          // ele mexeu no campo — e aí o salvamento atrasado ainda não chegou.
          send({ t: 'lobby', action: 'comecar', limites: limitesEscolhidos() });
          ctx.closeModal();
        };
        acoes.append(comecar);
      }
      body.append(acoes);
    };
    ctx.redraw = desenhar;
    desenhar();
  });
}

/*
 * ---- A Loja de Boss Token ----
 *
 * "no rodape da pagina ao lado de aventuras (apenas estando na aba boss)
 * coloque Loja De Boss Token, que tera algumas coisas pra comprar".
 *
 * Ela vive no canto de acoes da janela de Aventuras, e SO na aba de Bosses — do
 * lado do filtro, que e o outro botao daquele canto. E o unico lugar em que as
 * duas metades da frase valem ao mesmo tempo: "ao lado de aventuras" e "apenas
 * estando na aba boss". No rodape da pagina o botao ficaria visivel com a
 * janela fechada, quando nao ha aba nenhuma para se estar.
 *
 * ---- O saldo vem do SERVIDOR, e nao da mochila ----
 *
 * Contar `inventory` aqui daria um numero que discorda do que a compra vai
 * cobrar assim que a venda automatica mexer na bolsa. O servidor manda `saldo`
 * junto da vitrine, e e' ele que aparece — mesma regra do preco de lote da
 * Store: a tela nunca calcula o que a compra vai cobrar.
 */
/*
 * ---- A Loja de Task Token ----
 *
 * "cria uma loja de task token, na aba de tarefas ao lado do x de fechar igual
 * fizemos na boss token loja sabe, mas por enquanto deixa vazia essa loja de
 * task token."
 *
 * Ela é a irmã da Loja de Boss Token, e a semelhança é o ponto: mesma moeda na
 * cabeça, mesmo lugar (o canto de ações da janela), mesmo gesto. O que muda é
 * de onde a moeda vem — de toda task que fecha, e não de boss.
 *
 * VAZIA por enquanto, a pedido. Ela abre, mostra o saldo e diz que ainda não há
 * o que comprar. Não é um placeholder: o caminho inteiro está de pé (item,
 * pagamento, vitrine, compra), e a primeira oferta é uma linha na lista
 * `OFERTAS` de `tasktoken.mjs`.
 *
 * O desenho dos cards é o mesmo `cardDaLojaDeToken` da outra — no dia em que
 * houver oferta aqui, ela já sai parecendo a mesma loja.
 */
export function openLojaDeTaskToken() {
  const { state, send } = ctx;
  send({ t: 'taskToken' });

  ctx.openModal('Loja de Task Token', (body) => {
    const desenhar = () => {
      body.innerHTML = '';
      const loja = state.taskToken;
      if (!loja) {
        body.append(el('p', 'gate-note', 'Consultando a loja...'));
        return;
      }

      const topo = el('p', 'bt-saldo');
      const moeda = itemCanvas(loja.token, 22);
      if (moeda) topo.append(moeda);
      topo.append(el('b', null, `${money(loja.saldo)} Task Token`));
      topo.append(
        el(
          'em',
          null,
          loja.saldo
            ? 'Cai de toda task que fecha — um por mil mortes.'
            : 'Cai de toda task que fecha, um por mil mortes — vá fechar uma.'
        )
      );
      body.append(topo);

      if (!loja.ofertas?.length) {
        body.append(el('p', 'empty', 'Ainda não há o que comprar aqui. Vá juntando: as ofertas chegam.'));
      } else {
        /*
         * O mesmo card da outra loja. Ele pergunta `loja.token` para desenhar a
         * moeda no preço, então a Task Token sai desenhada sozinha — não há um
         * segundo card a manter.
         */
        const grade = el('div', 'bt-grade');
        for (const oferta of loja.ofertas) {
          grade.append(cartaoDeBossToken(oferta, loja, desenhar, 'Task Token', 'taskToken'));
        }
        body.append(grade);
      }

      const acoes = el('div', 'confirm-actions');
      const fechar = el('button', 'ghost', 'Fechar');
      fechar.onclick = () => ctx.closeModal();
      acoes.append(fechar);
      body.append(acoes);
    };
    ctx.redraw = desenhar;
    desenhar();
  });
}

export function openLojaDeBossToken() {
  const { state, send } = ctx;
  send({ t: 'bossToken' });

  ctx.openModal('Loja de Boss Token', (body) => {
    const desenhar = () => {
      body.innerHTML = '';
      const loja = state.bossToken;
      if (!loja) {
        body.append(el('p', 'gate-note', 'Consultando a loja...'));
        return;
      }

      const topo = el('p', 'bt-saldo');
      const moeda = itemCanvas(loja.token, 22);
      if (moeda) topo.append(moeda);
      topo.append(el('b', null, `${money(loja.saldo)} Boss Token`));
      topo.append(
        el(
          'em',
          null,
          loja.saldo
            ? 'Cai de todo boss, em metade das mortes.'
            : 'Cai de todo boss, em metade das mortes — vá derrubar um.'
        )
      );
      body.append(topo);

      /*
       * Tres prateleiras, na ordem do que custa menos. As Lasting Exercise sao
       * oito ofertas iguais em tudo menos na pericia, e ficam num bloco proprio
       * — soltas no meio das outras elas afogariam os dois produtos caros.
       */
      const grupos = [
        { chave: null, titulo: 'Consumíveis' },
        { chave: 'exercise', titulo: 'Lasting Exercise — 14.400 cargas cada' },
        { chave: 'outfit', titulo: 'Conjuntos completos' },
      ];
      for (const grupo of grupos) {
        const ofertas = loja.ofertas.filter((oferta) => (oferta.grupo ?? null) === grupo.chave);
        if (!ofertas.length) continue;
        body.append(el('h4', 'bt-titulo', grupo.titulo));
        const grade = el('div', 'bt-grade');
        for (const oferta of ofertas) grade.append(cartaoDeBossToken(oferta, loja, desenhar));
        body.append(grade);
      }

      const acoes = el('div', 'confirm-actions');
      const fechar = el('button', 'ghost', 'Fechar');
      fechar.onclick = () => ctx.closeModal();
      acoes.append(fechar);
      body.append(acoes);
    };
    ctx.redraw = desenhar;
    desenhar();
  });
}

/*
 * Um card de loja de token.
 *
 * Serve às DUAS lojas — a de Boss Token e a de Task Token —, e por isso o nome
 * da moeda e o canal da compra são parâmetros em vez de estarem escritos aqui
 * dentro. Um segundo card copiado seria a mesma tela mantida em dois lugares, e
 * o dia em que um preço ou um estado mudasse só um dos dois mudaria.
 */
function cartaoDeBossToken(oferta, loja, desenhar, unidade = 'Boss Token', canal = 'bossToken') {
  const card = el('div', `bt-card${oferta.owned ? ' bt-tem' : ''}`);

  /*
   * O desenho: o ITEM quando a oferta entrega um item, o BONECO quando ela
   * entrega um conjunto. Sem nenhum dos dois, a arte da loja pelo nome (a
   * wildcard tem uma).
   */
  const arte = oferta.itemId
    ? itemCanvas(oferta.itemId, 40)
    : oferta.look && outfitInfo(oferta.look)
      ? outfitCanvas(oferta.look, null, 40, 2, true)
      : null;
  if (arte) card.append(arte);
  else if (oferta.art) {
    const img = document.createElement('img');
    img.className = 'bt-arte';
    img.src = `/client/assets/store/${oferta.art}.png`;
    img.alt = '';
    img.onerror = () => img.remove();
    card.append(img);
  }

  card.append(el('b', null, oferta.name));
  if (oferta.blurb) card.append(el('em', null, oferta.blurb));

  const comprar = el('button', oferta.podeComprar ? 'primary' : null);
  const preco = el('span', 'bt-preco');
  const moeda = itemCanvas(loja.token, 16);
  if (moeda) preco.append(moeda);
  preco.append(document.createTextNode(String(oferta.tokens)));
  comprar.append(preco);
  comprar.disabled = !oferta.podeComprar;
  if (oferta.owned) {
    comprar.textContent = 'você já tem';
  } else if (!oferta.podeComprar) {
    tipTexto(comprar, `Faltam ${oferta.tokens - loja.saldo} ${unidade}.`);
  }
  /*
   * A mesma caixa da Store, com a moeda trocada. Ela mostra saldo antes e
   * depois — e e' isso que faz um preco de 250 parecer o que ele e': meio ano
   * de bosses, e nao um numero na tela.
   */
  comprar.onclick = () =>
    confirmPurchase({
      title: oferta.name,
      cost: oferta.tokens,
      balance: loja.saldo,
      currency: null,
      unit: unidade,
      preview: oferta.itemId ? itemCanvas(oferta.itemId, 48) : null,
      onConfirm: () => ctx.send({ t: canal, action: 'buy', id: oferta.id }),
    });
  card.append(comprar);
  return card;
}

/**
 * A tela do Exercise sozinha, sem passar pelas quatro abas de Aventuras.
 *
 * Existe para a sonda (`sonda-treino`), pelo mesmo motivo que `limparMochila` e
 * `venderMochila` existem em `__abrir`: chegar ate' aqui pelo caminho do
 * jogador sao quatro cliques em abas, e uma sonda que atravessa quatro telas
 * falha por qualquer uma delas em vez de falhar pela que ela mede.
 *
 * O desenho e' o MESMO da aba — ela chama a funcao de baixo, e nao uma copia.
 */
export function openExercise() {
  // Os cartazes desta tela anunciam preço, e quem sabe o preço é a loja. Ver
  // `escolherExercise`. Uma vez por abertura, como em `openStore`.
  ctx.send({ t: 'store' });
  ctx.openModal('Exercise', (body) => {
    const desenhar = () => escolherExercise(body, { semVoltar: true });
    ctx.redraw = desenhar;
    desenhar();
  });
}

function escolherExercise(body, { semVoltar = false } = {}) {
  const { state, send, closeModal } = ctx;
  const character = state.character;
  const naMao = character.exercicio ?? null;
  const guardadas = character.exercicios ?? [];

  body.replaceChildren();
  if (!semVoltar) {
    const voltar = el('button', 'ghost', '‹ voltar');
    voltar.onclick = () => {
      body.replaceChildren();
      renderTraining(body);
    };
    body.append(voltar);
  }
  body.append(el('h3', null, 'Exercise'));

  /*
   * ---- A marca de continuar sozinho ----
   *
   * "se tiver mais de uma varinha de treino na bag, continuar treinando (...) e
   * coloca pra pessoa habilitar essa função direto nessa página tipo um negócio
   * pra marcar; se ela marcar sempre ficará marcado a menos que ela desmarque".
   *
   * Ela vai para `settings` no servidor, e não para o navegador: quem marcou
   * num computador não precisa marcar no outro, e o treino que continua sozinho
   * roda do lado de lá — a marca tem de estar onde a decisão é tomada.
   *
   * A frase abaixo diz o que ela GASTA, e não só o que ela faz. É a única
   * marca do jogo que consome coins sem perguntar de novo, e quem a liga tem
   * de ler isso antes e não descobrir depois.
   */
  const auto = el('label', 'exercise-auto');
  const marca = document.createElement('input');
  marca.type = 'checkbox';
  marca.checked = !!character.settings?.exerciseAuto;
  marca.onchange = () => send({ t: 'settings', exerciseAuto: marca.checked });
  const dizeres = el('span');
  dizeres.append(el('b', null, 'Continuar com a próxima arma do mesmo tipo'));
  dizeres.append(
    el(
      'em',
      null,
      'Quando as cargas acabarem, o treino pega outra arma do mesmo tipo que estiver com você — a começada primeiro, depois a mais barata. Isso gasta as cargas dela sem perguntar.',
    ),
  );
  auto.append(marca, dizeres);
  body.append(auto);

  if (naMao) {
    body.append(
      el('p', 'shop-note', 'Esta é a arma na sua mão. Trocar por outra não gasta as cargas dela — ela fica guardada.'),
    );
    const caixa = el('div', 'exercise-mao');
    const arte = itemCanvas(naMao.arte ?? naMao.itemId, 48);
    if (arte) caixa.append(arte);
    const texto = el('div', 'exercise-mao-texto');
    texto.append(el('b', null, naMao.name));
    texto.append(
      el(
        'em',
        null,
        `${naMao.restantes.toLocaleString('pt-BR')} de ${naMao.cargas.toLocaleString('pt-BR')} cargas · ${duracaoCurta(naMao.segundos)} de treino`,
      ),
    );
    texto.append(el('em', null, `Treina ${PERICIA_EM_PT[naMao.skill] ?? naMao.skill}.`));
    caixa.append(texto);
    body.append(caixa);

    /*
     * ---- Quanto tempo falta para acabar TUDO ----
     *
     * Report do Kemm: "adicionar na tela de treinamento, uma estimativa de
     * quanto tempo vai demorar pra consumir todas as varinhas".
     *
     * A linha de cima ja diz o tempo da arma da mao. Esta responde a outra
     * pergunta — a que se faz olhando a mochila cheia de armas, e nao a que
     * esta na mao —, e ela so' existe quando a resposta e' diferente: com a
     * troca automatica DESLIGADA o treino para na primeira, e somar as outras
     * prometeria um tempo que nao vai acontecer.
     *
     * Por isso a frase muda com a marca em vez de sumir: desligada, ela diz o
     * que a marca daria. E' a resposta certa para "por que o meu nao mostra?",
     * dita antes da pergunta.
     */
    const falta = character.exercicioFalta;
    if (falta && falta.armas > 1) {
      const linha = el('p', 'exercise-falta');
      if (falta.seguido) {
        linha.append(
          el('b', null, `${duracaoCurta(falta.segundosTipo)} até acabar tudo`),
          el(
            'em',
            null,
            `${falta.armas} armas deste tipo, ${falta.cargasTipo.toLocaleString('pt-BR')} cargas somadas — ` +
              'o treino passa de uma para a outra sozinho.',
          ),
        );
      } else {
        linha.classList.add('apagada');
        linha.append(
          el('b', null, `${duracaoCurta(falta.segundos)} até esta arma acabar`),
          el(
            'em',
            null,
            `Você tem ${falta.armas} deste tipo, ${duracaoCurta(falta.segundosTipo)} somando todas. ` +
              'Marque acima para o treino seguir nelas.',
          ),
        );
      }
      body.append(linha);
    }

    const acoes = el('div', 'confirm-actions');
    if (naMao.treinando) {
      const parar = el('button', 'danger', 'Parar');
      parar.onclick = () => {
        send({ t: 'training', action: 'stop' });
        closeModal();
      };
      acoes.append(parar);
    } else {
      const seguir = el('button', 'primary', 'Continuar treinando');
      seguir.onclick = () => {
        send({ t: 'training', action: 'start', mode: 'exercise' });
        closeModal();
      };
      acoes.append(seguir);
    }
    body.append(acoes);
  }

  /*
   * A lista aparece SEMPRE, mesmo com uma arma na mão.
   *
   * Ela não aparecia, e trocar de perícia no meio era impossível — foi a
   * primeira coisa que o dono tentou fazer. A recusa existia para não perder as
   * cargas da arma pela metade; agora elas ficam guardadas (ver
   * `startExercicio`), e não há mais motivo para esconder as outras.
   */
  if (guardadas.length) {
    body.append(
      el('p', 'shop-note', naMao ? 'Trocar para:' : 'Escolha a arma. Cada golpe gasta uma carga.'),
    );
    const grid = el('div', 'train-grid');
    for (const arma of guardadas) {
      if (naMao && arma.itemId === naMao.itemId && !arma.quantidade) continue;
      const botao = el('button');
      const arte = itemCanvas(arma.arte ?? arma.itemId, 32);
      if (arte) botao.append(arte);
      botao.append(el('b', null, arma.name));
      botao.append(el('em', null, PERICIA_EM_PT[arma.skill] ?? arma.skill));
      /*
       * Uma começada mostra o que sobrou; uma fechada mostra o total. São
       * coisas diferentes e a mesma linha diria o mesmo número para as duas.
       */
      botao.append(
        el(
          'em',
          null,
          arma.restantes
            ? `${arma.restantes.toLocaleString('pt-BR')} cargas (começada)`
            : `${arma.cargas.toLocaleString('pt-BR')} cargas`,
        ),
      );
      if (arma.quantidade > 1) botao.append(el('em', null, `x${arma.quantidade}`));
      botao.onclick = () => {
        send({ t: 'training', action: 'start', mode: 'exercise', itemId: arma.itemId });
        closeModal();
      };
      grid.append(botao);
    }
    body.append(grid);
  } else if (!naMao) {
    body.append(el('p', 'empty', 'Você não tem nenhuma arma de treino.'));
  }

  /*
   * ---- O atalho para a loja ----
   *
   * Fica SEMPRE, e não só quando a mochila está vazia. Uma arma de exercise
   * acaba — é o que ela faz —, e o momento em que a pessoa está nesta tela é
   * justamente quando a pergunta "onde compro outra?" aparece. Esconder a
   * resposta até acabar a última é responder tarde.
   */
  /*
   * ---- E o pergaminho ao lado, porque ele é desta tela ----
   *
   * "tem que ter indicaçao do scroll speed exercise informando o que ele faz
   * tambem ao lado do 'as armas de treino estao na store', ai deixa so um botao
   * no meio que abre a loja".
   *
   * O Scroll Speed Exercise só serve para uma coisa no jogo inteiro — dobrar a
   * velocidade DESTE treino —, e até aqui ele só se anunciava na faixa do topo,
   * que aparece depois de o treino já ter começado. Quem está nesta tela está
   * decidindo como vai treinar; é aqui que a informação vale.
   *
   * UM botão para os dois cartazes, e não um em cada: os dois levam à mesma
   * loja, e dois botões lado a lado obrigariam a ler qual é qual antes de
   * clicar. Ele abre em Armas de Treino, que é a prateleira desta tela — e o
   * cartaz do pergaminho diz onde ele mora, que é a informação que falta.
   */
  const loja = el('div', 'exercise-loja');

  const cartazes = el('div', 'exercise-loja-cartazes');

  /*
   * ---- Os dois preços saem da LOJA, e não daqui ----
   *
   * "na aba de boneco de treino está informando que o Scroll Speed Exercise é
   *  100 Draevor Coins, quando na verdade agora é 25."
   *
   * Os dois cartazes tinham o número escrito à mão. A régua de preços caiu, o
   * pergaminho foi de 100 para 25, e esta tela continuou anunciando o preço
   * velho — quatro vezes maior — sem quebrar nada e sem avisar ninguém. É o
   * mesmo defeito que o pacote de blessings tinha.
   *
   * Agora os dois vêm de `state.store`: a faixa das armas é o menor e o maior
   * preço da prateleira de exercise (hoje 25 e 100), e o do pergaminho é o
   * `coins` dele na prateleira de Boosts. O dono mexe em `exercicios.mjs` ou em
   * `consumiveis.mjs` e a tela acompanha sozinha.
   *
   * Enquanto a loja não chegou, cada frase sai SEM a parte do preço, e não com
   * um número de reserva: uma frase mais curta é uma frase certa, e o pedido de
   * `openHunts` já está a caminho — a chegada redesenha isto.
   */
  const armasNaLoja = (ctx.state.store?.exercises ?? []).map((arma) => arma.coins).filter(Number.isFinite);
  const faixaDasArmas = armasNaLoja.length
    ? `Da mais barata à melhor: ${Math.min(...armasNaLoja)} a ${Math.max(...armasNaLoja)} Draevor Coins.`
    : '';
  const pergaminhoNaLoja =
    (ctx.state.store?.boosts ?? []).find((boost) => boost.itemId === ITEM_DO_PERGAMINHO) ?? null;

  const armas = el('div', 'exercise-loja-cartaz');
  armas.append(
    el('b', null, 'As armas de treino estão na Store'),
    el(
      'em',
      null,
      `Exercise, Lasting, Durable e as Boosted — que treinam 30% mais rápido.${faixaDasArmas ? ` ${faixaDasArmas}` : ''}`,
    ),
  );
  cartazes.append(armas);

  const pergaminho = el('div', 'exercise-loja-cartaz');
  const titulo = el('b');
  const figura = itemCanvas(ITEM_DO_PERGAMINHO, 22);
  if (figura) titulo.append(figura);
  titulo.append(document.createTextNode('Scroll Speed Exercise'));
  pergaminho.append(titulo);
  /*
   * As horas também saem da loja (`duracao`, em milissegundos) — são a outra
   * metade da oferta, e ficariam mentindo pelo mesmo motivo que o preço.
   */
  const horasDoPergaminho = pergaminhoNaLoja?.duracao ? Math.round(pergaminhoNaLoja.duracao / 3600000) : null;
  const ofertaDoPergaminho =
    horasDoPergaminho && pergaminhoNaLoja?.coins != null
      ? `São ${horasDoPergaminho} horas de treino dobrado por ${pergaminhoNaLoja.coins} Draevor Coins, e o`
      : 'O';
  pergaminho.append(
    el(
      'em',
      null,
      `Dobra a velocidade das exercise weapons: um golpe a cada 0,2s em vez de 0,4s. ${ofertaDoPergaminho} ` +
        'saldo só desce enquanto você está treinando — fora do treino ele fica guardado.',
    ),
  );
  /*
   * Quanto ele TEM, quando tem.
   *
   * É a diferença entre um anúncio e uma informação: quem já comprou não
   * precisa que a tela ofereça de novo, precisa saber quanto sobrou. O mesmo
   * saldo que a pílula do topo mostra durante o treino (`efeitos.exerciseSpeed`).
   */
  const saldo = character.efeitos?.exerciseSpeed?.restante ?? 0;
  if (saldo > 0) {
    pergaminho.append(el('span', 'exercise-loja-saldo', `Você tem ${duracaoCurta(Math.round(saldo / 1000))} guardados.`));
  }
  cartazes.append(pergaminho);
  loja.append(cartazes);

  const ir = el('button', 'primary', 'Abrir a loja');
  ir.onclick = () => {
    closeModal();
    openStore();
    // Já na prateleira certa: quem clicou aqui não quer procurar montaria.
    ctx.tabs.storeSection = 'exercises';
    ctx.tabs.storeBusca = '';
    ctx.redraw?.();
  };
  loja.append(ir);
  body.append(loja);
}

function renderTraining(body) {
  const { state, send, closeModal } = ctx;
  const character = state.character;

  /*
   * O que ele vai treinar, dito ANTES de ele escolher o modo.
   *
   * `skillName` é o que o servidor deriva da arma equipada — a mesma conta que
   * decide a perícia no combate. Mostrá-la aqui é o que substitui a grade de
   * escolha: em vez de perguntar, a tela informa, e quem não gostou troca de
   * arma antes de entrar.
   */
  const pericia = character?.derived?.skillName ?? null;
  body.append(
    el(
      'p',
      'shop-note',
      pericia
        ? `Você treina a perícia da arma equipada: ${pericia === 'magic' ? 'magic level' : pericia}. Troque de arma para treinar outra.`
        : 'Você treina a perícia da arma equipada. Troque de arma para treinar outra.',
    ),
  );

  /*
   * ---- Os mesmos cards dos bosses ----
   *
   * `hunt-grid` + `hunt-card boss`: as classes que a aba de Bosses já usa, e
   * não uma cópia delas. Assim os três cards do treino têm exatamente o mesmo
   * tamanho, a mesma moldura ornamentada e o mesmo comportamento de hover —
   * porque SÃO os mesmos cards, e não dois conjuntos de regras parecidas que
   * vão divergir na primeira vez que alguém mexer num só.
   *
   * A `locked` é a mesma que trava um boss em cooldown, pelo mesmo motivo
   * visual: mostrar que existe e não dá para entrar agora.
   */
  const grid = el('div', 'hunt-grid');
  for (const modo of MODOS_DE_TREINO) {
    const travado = !modo.pronto || !!state.hunt;
    const card = el('div', `hunt-card boss treino${travado ? ' locked' : ''}`);

    card.append(el('h3', null, modo.nome));
    /*
     * A arte de `assets/icons/treino-<modo>.png`. Enquanto ela não existir,
     * `artOrUiIcon` cai no caminho antigo e o card aparece sem figura — com o
     * nome e o resumo, que é o que ele precisa para funcionar.
     */
    const arte = el('div', 'treino-arte');
    arte.append(artOrUiIcon(`treino-${modo.id}`, modo.nome));
    card.append(arte);
    card.append(el('p', null, modo.resumo));
    /*
     * O card do Exercise diz o que está na mão.
     *
     * Sem isso ele promete a mesma coisa esteja o jogador com uma arma pela
     * metade ou sem nenhuma — e as duas levam a telas diferentes. A linha aqui
     * é o que evita abrir o card para descobrir.
     */
    const emUso = modo.id === 'exercise' ? character?.exercicio : null;
    card.append(
      el(
        'span',
        'lv',
        emUso
          ? `${emUso.name} · ${emUso.restantes.toLocaleString('pt-BR')} cargas${emUso.treinando ? ' (treinando)' : ''}`
          : modo.pronto
            ? 'disponível'
            : 'ainda não',
      ),
    );

    if (modo.pronto && !state.hunt) {
      card.onclick = () => {
        /*
         * O offline PERGUNTA antes; o pátio não.
         *
         * A diferença não é capricho: confirmar o treino offline TIRA a pessoa
         * do jogo e a devolve para a lista de personagens. Uma ação que fecha o
         * personagem por engano é a que mais dói desfazer — e não dá para
         * desfazer, o tempo já correu. O pátio, por outro lado, é só andar até
         * um mapa; sair de lá é um clique.
         */
        if (modo.id === 'offline') return confirmarOffline(body);
        // O exercise PERGUNTA qual arma: quem decide não é a que está vestida,
        // é a que ele comprou — e ele pode ter mais de uma.
        if (modo.id === 'exercise') return escolherExercise(body);
        send({ t: 'training', action: 'start', mode: modo.id });
        closeModal();
      };
    }
    grid.append(card);
  }
  body.append(grid);

  if (state.hunt) body.append(el('p', 'empty', 'Saia da caçada antes de treinar.'));

  /*
   * ---- O tanque do treino offline, aqui e não no canto da tela ----
   *
   * Esta é a única tela em que a stamina de treino muda alguma decisão: é aqui
   * que a pessoa escolhe treinar offline. Um medidor a mais no HUD, ao lado dos
   * outros, seria um número que quase nunca importa competindo por atenção com
   * a vida e a mana, que importam sempre.
   *
   * Ele aparece SEMPRE, e não só quando está baixo: um recurso que só se mostra
   * na hora em que acaba é um recurso que a pessoa descobre sendo punida por
   * ele.
   */
  const tanque = character?.treinoStamina;
  if (tanque) {
    const caixa = el('div', 'treino-tanque');
    caixa.append(el('b', null, 'Stamina de treino'));
    const track = el('div', `track ${tanque.baixa ? 'copper' : 'accent'}`);
    const fill = el('i');
    fill.style.width = `${Math.max(0, Math.min(100, tanque.fracao * 100)).toFixed(1)}%`;
    track.append(fill);
    caixa.append(track);
    caixa.append(
      el(
        'em',
        null,
        `${duracaoCurta(Math.round(tanque.restante / 1000))} de ${duracaoCurta(Math.round(tanque.teto / 1000))} — o treino offline gasta daqui, e caçar devolve.`,
      ),
    );
    body.append(caixa);
  }
  /*
   * Não há botão de parar o treino offline, e não é esquecimento.
   *
   * Entrar no personagem JÁ para o treino — é o fim do trato de "eu saio, ele
   * treina". Então quando esta tela é vista, `character.training` já foi
   * desligado: um botão para desfazer o que a própria entrada desfez seria uma
   * pergunta que ninguém precisa responder, e que nunca apareceria de qualquer
   * forma.
   */
}

// ---------- prey ----------

export function openPrey() {
  ctx.openModal('Prey', (body) => {
    const draw = () => {
      body.innerHTML = '';
      renderPrey(body);
    };
    ctx.redraw = draw;
    draw();
  });
}

function bonusIcon(bonus) {
  return uiIcon(`prey-${bonus === 'exp' ? 'xp' : bonus ?? 'none'}`, bonus ?? '');
}

function stars(rarity) {
  const row = el('div', 'prey-stars');
  for (let index = 0; index < 10; index++) {
    row.append(uiIcon(index < rarity ? 'prey-star' : 'prey-nostar'));
  }
  return row;
}

/*
 * Prey em três cartas, uma por slot.
 *
 * Slot travado mostra o cadeado, o porquê e o botão de liberar — nada de uma
 * linha de texto solta. Slot com presa escolhida vira um retrato: o bicho
 * grande, o nome por cima, o estandarte de raridade e a barra do tempo que
 * ainda resta. Slot livre mostra a grade de candidatos.
 */
function renderPrey(body) {
  const { state, send } = ctx;
  const character = state.character;
  const prices = state.catalog.preyPrices;

  const topo = el('div', 'prey-head');
  topo.append(
    el('p', null, 'Cada slot dá um bônus enquanto você caça a presa escolhida. O relógio só corre dentro da hunt.')
  );
  const carteira = el('div', 'prey-wallet');
  carteira.append(uiIcon('prey-wildcard'), el('b', null, `${character.wildcards}`), el('span', null, 'wildcards'));
  topo.append(carteira);
  body.append(topo);

  const grid = el('div', 'prey-grid');
  for (const slot of character.prey) {
    const travado = slot.state === 'locked';
    const box = el('div', `prey-slot${travado ? ' locked' : ''}`);

    const cabeca = el('div', 'prey-slot-head');
    cabeca.append(el('h4', null, `Slot ${slot.index + 1}`));
    if (travado) cabeca.append(el('span', 'prey-lock', 'bloqueado'));
    box.append(cabeca);

    if (travado) {
      const vazio = el('div', 'prey-empty');
      vazio.append(uiIcon('prey-inactive'));
      vazio.append(el('b', null, 'Slot bloqueado'));
      vazio.append(el('em', null, 'Liberado de vez na loja de Draevor Coins.'));
      const buy = el('button', 'prey-unlock', 'Liberar slot');
      // Liberar o terceiro slot é permanente e custa quase mil coins; um clique
      // sem volta na tela da prey não pode ser o suficiente.
      const preco = state.catalog.storePrices?.['prey-slot'] ?? 300;
      buy.onclick = () =>
        confirmPurchase({
          title: 'Terceiro slot de prey — liberado para sempre',
          cost: preco,
          balance: character.coins ?? 0,
          onConfirm: () => send({ t: 'store', action: 'buy', id: 'prey-slot' }),
        });
      vazio.append(buy);
      box.append(vazio);
      grid.append(box);
      continue;
    }

    const nomeBonus = state.catalog.preyBonuses.find((entry) => entry.id === slot.bonus)?.name ?? 'sem bônus';

    if (slot.key) {
      const info = state.catalog.bestiary[slot.key];
      const retrato = el('div', 'prey-portrait');
      retrato.append(el('b', 'prey-name', info?.name ?? slot.key));

      const palco = el('div', 'prey-stage');
      if (info?.look && outfitInfo(info.look)) palco.append(outfitCanvas(info.look, info.colors, 72, 2, true));
      const estandarte = el('div', 'prey-banner');
      estandarte.append(bonusIcon(slot.bonus), stars(slot.rarity));
      palco.append(estandarte);
      retrato.append(palco);

      retrato.append(el('div', 'prey-gain', `${nomeBonus} +${slot.percent}%`));

      // Barra do tempo: o quanto sobrou das duas horas de caçada.
      const total = slot.total ?? 2 * 60 * 60 * 1000;
      const barra = el('div', 'prey-time');
      const cheio = el('i');
      cheio.style.width = `${Math.max(0, Math.min(100, (slot.left / total) * 100))}%`;
      barra.append(cheio, el('b', null, `Tempo restante: ${formatLeft(slot.left)}`));
      retrato.append(barra, el('em', 'prey-note', 'Pausado fora da hunt — só conta caçando.'));
      box.append(retrato);
    } else {
      const bonus = el('div', 'prey-bonus');
      bonus.append(bonusIcon(slot.bonus), el('b', null, `${nomeBonus} +${slot.percent}%`), stars(slot.rarity));
      box.append(bonus);

      const options = el('div', 'prey-options');
      for (const key of slot.options ?? []) {
        const info = state.catalog.bestiary[key];
        const button = el('button');
        if (info?.look && outfitInfo(info.look)) button.append(outfitCanvas(info.look, info.colors, 40));
        button.append(el('span', null, info?.name ?? key));
        button.title = info?.name ?? key;
        button.onclick = () => send({ t: 'prey', action: 'choose', slot: slot.index, key });
        options.append(button);
      }
      box.append(options);
    }

    // Rodapé: três cartas de ação com o preço embaixo, como as fichas do jogo.
    const buttons = el('div', 'prey-buttons');
    const livre = slot.freeReroll <= 0;
    const acoes = [
      {
        icone: 'prey-reroll',
        rotulo: 'Trocar bônus',
        preco: `${prices.bonus}`,
        moeda: 'prey-wildcard',
        travado: character.wildcards < prices.bonus,
        acao: () => send({ t: 'prey', action: 'rerollBonus', slot: slot.index }),
      },
      {
        icone: 'prey-select',
        rotulo: 'Nova lista',
        preco: livre ? 'grátis' : money(character.preyRerollCost),
        moeda: livre ? null : 'coin-gold',
        travado: !livre && character.gold < character.preyRerollCost,
        acao: () => send({ t: 'prey', action: 'rerollList', slot: slot.index }),
      },
      {
        icone: 'prey-none',
        rotulo: 'Escolher da lista',
        preco: `${prices.select}`,
        moeda: 'prey-wildcard',
        travado: character.wildcards < prices.select,
        acao: () => openPreySelect(slot.index),
      },
    ];
    for (const { icone, rotulo, preco, moeda, travado: bloqueado, acao } of acoes) {
      const card = el('button', 'prey-action');
      card.append(uiIcon(icone));
      const linha = el('span', 'price');
      linha.append(document.createTextNode(preco));
      if (moeda) linha.append(uiIcon(moeda));
      card.append(linha);
      card.title = rotulo;
      card.disabled = bloqueado;
      card.onclick = acao;
      buttons.append(card);
    }
    box.append(buttons);

    const toggles = el('div', 'prey-toggles');
    for (const [key, label, custo] of [
      ['autoReroll', 'Renovar sozinho', prices.bonus],
      ['lock', 'Travar bônus', prices.select],
    ]) {
      const toggle = el('label');
      const input = document.createElement('input');
      input.type = 'checkbox';
      input.checked = key === 'lock' ? slot.locked : slot.autoReroll;
      input.onchange = () => send({ t: 'prey', action: 'option', slot: slot.index, option: key, value: input.checked });
      toggle.append(input, el('span', null, label));
      const preco = el('span', 'price');
      preco.append(document.createTextNode(String(custo)), uiIcon('prey-wildcard'));
      toggle.append(preco);
      toggles.append(toggle);
    }
    box.append(toggles);

    grid.append(box);
  }
  body.append(grid);
}

function openPreySelect(index) {
  const { state, send } = ctx;
  ctx.openModal(`Prey — slot ${index + 1}`, (body) => {
    const search = document.createElement('input');
    search.className = 'search';
    search.placeholder = 'buscar criatura...';
    body.append(search);

    const list = el('div', 'prey-all');
    const draw = () => {
      const term = search.value.trim().toLowerCase();
      list.innerHTML = '';
      // Criatura que já está em outro slot sai da lista: o bônus não empilha,
      // e o servidor recusa a escolha de qualquer jeito.
      const tomadas = new Set(
        (state.character.prey ?? [])
          .filter((slot, outro) => outro !== index && slot.key && slot.left > 0)
          .map((slot) => slot.key)
      );
      const entries = Object.entries(state.catalog.bestiary)
        .filter(([key, info]) => info.exp > 0 && !tomadas.has(key) && (!term || info.name.toLowerCase().includes(term)))
        .sort((a, b) => a[1].name.localeCompare(b[1].name))
        .slice(0, 120);

      for (const [key, info] of entries) {
        const button = el('button');
        if (outfitInfo(info.look)) button.append(outfitCanvas(info.look, info.colors, 32));
        button.append(el('b', null, info.name), el('em', null, `${money(info.exp)} xp`));
        button.onclick = () => {
          send({ t: 'prey', action: 'selectAll', slot: index, key });
          openPrey();
        };
        list.append(button);
      }
    };
    search.oninput = draw;
    draw();
    body.append(list);
  });
}

// ---------- imbuements ----------

const IMBUEMENT_SLOTS = ['weapon', 'shield', 'head', 'body', 'legs', 'feet', 'neck', 'ring'];

// Nome do encaixe quando não há nada vestido nele.
const SLOT_LABEL = {
  weapon: 'Arma',
  shield: 'Escudo',
  head: 'Cabeça',
  body: 'Corpo',
  legs: 'Pernas',
  feet: 'Pés',
  neck: 'Colar',
  ring: 'Anel',
};

export function openImbuements() {
  ctx.send({ t: 'imbuements' });
  /*
   * `imbue` alarga o modal.
   *
   * Os tres graus ganharam moldura de 24px por lado — 48px de ornamento por
   * cartao —, e nos 980px de sempre sobrava coluna estreita demais para o texto
   * do efeito. O dono autorizou: "aumentei um pouquinho o tamanho do modal da
   * pagina de imbuements, mas so' se for necessario". Era.
   */
  ctx.openModal(
    'Imbuements',
    (body) => {
      const draw = () => {
        body.innerHTML = '';
        renderImbuements(body);
      };
      ctx.redraw = draw;
      draw();
    },
    null,
    'imbue'
  );
}

/*
 * ---- Um menu suspenso que é NOSSO ----
 *
 * A foto do Imbuing Shrine tem duas listas suspensas, e o dono pediu esse gesto
 * com todas as letras: "seleciona o item, escolhe o imbue pela setinha e etc".
 *
 * O que ele NÃO pode ser é um `<select>`. A lista aberta de um `<select>` é uma
 * janela do sistema: não está no DOM, o CSS não a alcança, e qualquer redesenho
 * da página a fecha. Com uma caçada rodando atrás — loot, dano, chat, oito
 * quadros por segundo — ela fecha antes de o dedo chegar no nome. Foi por isso
 * que o `<select>` saiu dos charms ("os charms está bugado, não dá para colocar
 * o bicho") e da quantidade da loja.
 *
 * Então é um botão com uma seta e um painel comum embaixo. Mesmo gesto, mesma
 * cara, e nada o fecha além do clique da pessoa.
 *
 * `qual` identifica o menu (há dois na tela), e quem está aberto mora em
 * `ctx.tabs` — a gaveta que sobrevive ao redesenho.
 */
function menuSuspenso({ qual, valor, itens, aoEscolher, comBusca = false, aoRedesenhar }) {
  const caixa = el('div', 'suspenso');
  const aberto = ctx.tabs.imbueAberto === qual;
  const atual = itens.find((item) => item.id === valor) ?? null;

  const botao = el('button', `suspenso-botao${aberto ? ' aberto' : ''}`);
  if (atual?.arte) {
    const arte = atual.arte();
    if (arte) botao.append(arte);
  }
  const texto = el('span', 'grow');
  texto.append(el('b', null, atual?.nome ?? 'escolha'));
  if (atual?.sub) texto.append(el('em', null, atual.sub));
  botao.append(texto, el('i', 'suspenso-seta'));
  botao.onclick = () => {
    ctx.tabs.imbueAberto = aberto ? null : qual;
    aoRedesenhar();
  };
  caixa.append(botao);
  if (!aberto) return caixa;

  const painel = el('div', 'suspenso-painel');
  const lista = el('div', 'suspenso-itens');

  let busca = null;
  if (comBusca) {
    busca = document.createElement('input');
    busca.type = 'search';
    busca.placeholder = `buscar entre ${itens.length}...`;
    busca.value = ctx.tabs.imbueSearch ?? '';
    painel.append(busca);
  }

  const pintar = () => {
    const filtro = (ctx.tabs.imbueSearch ?? '').trim().toLowerCase();
    lista.innerHTML = '';
    let desenhados = 0;
    for (const item of itens) {
      if (comBusca && filtro && !`${item.nome} ${item.sub ?? ''}`.toLowerCase().includes(filtro)) continue;
      desenhados++;
      const linha = el('button', `suspenso-item${item.id === valor ? ' escolhido' : ''}`);
      if (item.arte) {
        const arte = item.arte();
        if (arte) linha.append(arte);
      }
      const dentro = el('span', 'grow');
      dentro.append(el('b', null, item.nome));
      if (item.sub) dentro.append(el('em', null, item.sub));
      linha.append(dentro);
      linha.onclick = () => {
        ctx.tabs.imbueAberto = null;
        aoEscolher(item.id);
      };
      lista.append(linha);
    }
    if (!desenhados) lista.append(el('em', 'suspenso-vazio', 'nada com esse nome'));
  };

  /*
   * A busca redesenha só a LISTA, e não o painel: refazer o painel jogaria fora
   * o campo e o cursor a cada tecla — a versão de teclado do mesmo defeito que
   * tirou o `<select>` daqui.
   */
  if (busca) {
    busca.oninput = () => {
      ctx.tabs.imbueSearch = busca.value;
      pintar();
    };
  }
  pintar();
  painel.append(lista);
  caixa.append(painel);
  return caixa;
}

/*
 * ---- A Oficina de Imbuir, no desenho da foto ----
 *
 * O dono mandou o Imbuing Shrine do cliente antigo e depois apertou o pedido:
 * "pode ser mais parecida com a da foto: seleciona o item, escolhe o imbue pela
 *  setinha e etc".
 *
 * A foto tem três coisas, e as três estão aqui:
 *
 *   1. BLOCOS COM TÍTULO — "Item information", "Imbue empty slot". A tela
 *      deixou de ser uma pilha e passou a ter partes;
 *   2. OS ENCAIXES DESENHADOS — quadrados com a arte do encaixe vazio
 *      (`encaixe-vazio.png`, do próprio cliente, que foi o dono quem apontou
 *      onde estava). Um relance diz quantos a peça tem e quantos estão em uso;
 *   3. ESCOLHER PELA SETINHA — o encantamento num menu, o grau noutro, e só
 *      então o efeito, os reagentes e o preço. É o "escolha, depois compare"
 *      da foto.
 *
 * O que mudou desde a versão anterior desta tela: a lista de 24 famílias com os
 * três cartões abertos de cada uma virou dois menus e UM cartão. O DOM da
 * página caiu de 72 cartões emoldurados para um.
 *
 * Nada do FUNCIONAMENTO mudou: mesmas mensagens (`imbue` e `imbue/remove`),
 * mesmas regras de qual encantamento serve em qual peça, mesmos reagentes,
 * mesmos preços e a mesma duração.
 */
function renderImbuements(body) {
  const { state, send } = ctx;
  const character = state.character;

  /*
   * ---- Só as peças que ACEITAM imbuement ----
   *
   * "se a peça não aceita imbuements ela não deve aparecer lá."
   *
   * Eram oito quadrados fixos, e cinco deles costumam estar apagados: slot
   * vazio, peça sem encaixe, peça que a base não deixa encantar. Um botão
   * apagado ocupa o mesmo espaço de um que serve e ainda faz procurar entre os
   * dois — a fileira dizia mais sobre o que NÃO dá para fazer do que sobre o
   * que dá.
   *
   * `imbuementSlots` vem do servidor peça por peça (é o `imbuementslot` do
   * items.xml), então quem responde não é a tela: é a base.
   */
  const aceitam = IMBUEMENT_SLOTS.filter((slot) => (character.imbuementSlots?.[slot] ?? 0) > 0);

  /*
   * A peça escolhida tem de ser uma das que sobraram: guardada de antes, ela
   * pode ter sido desequipada, e aí a tela abriria em "nada equipado" com a
   * fileira inteira apontando para outro lugar.
   */
  const chosen = aceitam.includes(ctx.tabs.imbueSlot) ? ctx.tabs.imbueSlot : (aceitam[0] ?? 'weapon');
  ctx.tabs.imbueSlot = chosen;
  const equipada = character.equipment[chosen];
  const ativos = character.imbuements?.[chosen] ?? [];
  const totalSlots = character.imbuementSlots?.[chosen] ?? 0;

  /** Um bloco com título, como as faixas da foto. */
  const bloco = (titulo) => {
    const caixa = el('section', 'imbue-bloco');
    caixa.append(el('h4', null, titulo));
    const dentro = el('div', 'imbue-bloco-corpo');
    caixa.append(dentro);
    body.append(caixa);
    return dentro;
  };

  // ======== 1. A peça ========
  const daPeca = bloco('Informações da peça');

  const foco = el('div', 'imbue-focus');
  const moldura = el('div', 'imbue-frame');
  if (equipada) moldura.append(itemCanvas(equipada.id, 48));
  else moldura.append(el('span', 'empty', 'vazio'));
  foco.append(moldura);
  const nomes = el('div', 'grow');
  nomes.append(el('b', null, state.items[equipada?.id]?.name ?? 'nada equipado'));
  nomes.append(
    el('em', null, totalSlots ? `${ativos.length} de ${totalSlots} encaixes usados` : 'esta peça não aceita imbuement')
  );
  foco.append(nomes);

  const linhaDaPeca = el('div', 'imbue-peca-linha');
  linhaDaPeca.append(foco);

  /*
   * ---- Os encaixes ----
   *
   * Eram bolinhas de 6px. O quadrado diz a mesma coisa e mais três: qual
   * encantamento está ali, quanto tempo falta e o botão de tirar — que antes
   * morava numa lista separada logo abaixo, repetindo a mesma informação com
   * outro desenho.
   */
  const encaixes = el('div', 'imbue-encaixes');
  for (let index = 0; index < Math.max(totalSlots, 1); index++) {
    const imbued = ativos[index] ?? null;
    const fonte = imbued ? state.catalog.imbuements.find((entry) => entry.id === imbued.id) : null;
    const caixa = el(
      'div',
      `imbue-encaixe${imbued ? ' cheio' : ''}${totalSlots ? '' : ' morto'}${fonte?.base ? ` grau-${fonte.base}` : ''}`
    );

    const quadro = el('div', 'imbue-encaixe-quadro');
    if (imbued && fonte?.iconId) quadro.append(imbuementIcon(fonte.iconId, 34));
    caixa.append(quadro);

    if (imbued) {
      /* O apelido no lugar do nome: no quadrado de 108px só cabe um dos dois. */
      caixa.append(el('b', null, apelidoDoImbuement(imbued.name) ?? imbued.name));
      caixa.append(el('em', null, `${formatLeft(imbued.left)} restantes`));
      const tirar = el('button', 'ghost', 'Remover');
      tirar.onclick = () => send({ t: 'imbue', action: 'remove', slot: chosen, id: imbued.id });
      caixa.append(tirar);
    } else {
      caixa.append(el('b', null, totalSlots ? 'vazio' : 'sem encaixe'));
    }
    encaixes.append(caixa);
  }
  linhaDaPeca.append(encaixes);
  daPeca.append(linhaDaPeca);

  // A fileira de peças — só as que aceitam. Ver `aceitam`, lá em cima.
  const picker = el('div', 'imbue-slots');
  for (const slot of aceitam) {
    const equipped = character.equipment[slot];
    const slots = character.imbuementSlots?.[slot] ?? 0;
    const usados = (character.imbuements?.[slot] ?? []).length;
    const button = el('button');
    button.setAttribute('aria-selected', String(slot === chosen));
    if (equipped) button.append(itemCanvas(equipped.id, 30));
    else button.append(el('span', 'hole', ''));
    button.append(el('span', null, state.items[equipped?.id]?.name ?? SLOT_LABEL[slot] ?? slot));
    /*
     * "1/2" em vez de "1 encaixe(s)": o que interessa ao escolher a peça é
     * quantos ainda estão livres, e o texto antigo só dizia o total.
     */
    button.append(el('em', null, equipped ? `${usados}/${slots}` : 'vazio'));
    button.title = state.items[equipped?.id]?.name ?? SLOT_LABEL[slot] ?? slot;
    button.onclick = () => {
      ctx.tabs.imbueSlot = slot;
      /* Peça nova, escolha nova: o encantamento anterior pode nem servir nela. */
      ctx.tabs.imbueAberto = null;
      ctx.redraw();
    };
    picker.append(button);
  }
  if (!aceitam.length) {
    picker.append(
      el('p', 'empty', 'Nenhuma peça vestida aceita imbuement. Equipe uma arma, um escudo ou uma peça com encaixe.')
    );
  }
  daPeca.append(picker);

  // ======== 2. Imbuir ========
  const daEscolha = bloco('Imbuir encaixe');
  const oficina = el('div', 'imbue-oficina');
  daEscolha.append(oficina);

  /* Quanto o personagem tem de um reagente, no inventário mais a bolsa. */
  const quantosTem = (id) =>
    [...(character.inventory ?? []), ...(character.pouch ?? [])]
      .filter((entry) => entry.id === id)
      .reduce((total, entry) => total + (entry.count ?? 1), 0);

  /*
   * Só esta parte se redesenha quando a pessoa mexe nos menus. Refazer a tela
   * inteira apagaria o campo de busca com o cursor dentro dele.
   */
  const desenhar = () => {
    oficina.innerHTML = '';

    // Agrupa por nome, mantendo a ordem em que o catálogo veio.
    const familias = new Map();
    for (const imbuement of state.catalog.imbuements) {
      // Cada categoria só entra na peça certa: dano na arma, proteção na
      // armadura, velocidade nas botas — a mesma divisão do jogo.
      if (imbuement.slots?.length && !imbuement.slots.includes(chosen)) continue;
      /*
       * E a regra DAQUELA peça, que é mais estreita.
       *
       * O dono: "a shiny blade pode imbuir elemento, o souleater não". A base diz
       * isso item por item, no `imbuementslot` do items.xml — e faz sentido: a
       * souleater já é 47 de gelo em 57 de ataque.
       *
       * `null` quer dizer "esta peça não restringe", e não "não aceita nada":
       * item fora do items.xml não pode ser barrado por falta de informação.
       */
      const aceitos = character.imbuementTipos?.[chosen];
      if (Array.isArray(aceitos) && aceitos.length && !aceitos.includes(imbuement.category)) continue;
      if (!familias.has(imbuement.name)) familias.set(imbuement.name, []);
      familias.get(imbuement.name).push(imbuement);
    }

    if (!familias.size) {
      oficina.append(el('p', 'empty', 'Nenhum imbuement serve nessa peça.'));
      return;
    }

    /* A escolhida some quando a peça muda; aí vale a primeira da lista. */
    const nomes = [...familias.keys()];
    const escolhida = nomes.includes(ctx.tabs.imbueFamilia) ? ctx.tabs.imbueFamilia : nomes[0];
    ctx.tabs.imbueFamilia = escolhida;

    const graus = [...familias.get(escolhida)].sort((a, b) => a.base - b.base);
    const grauAtual = graus.find((g) => g.base === ctx.tabs.imbueGrau) ?? graus[0];
    ctx.tabs.imbueGrau = grauAtual.base;

    // ---- Os dois menus ----
    const menus = el('div', 'imbue-menus');
    menus.append(
      menuSuspenso({
        qual: 'familia',
        valor: escolhida,
        comBusca: true,
        aoRedesenhar: desenhar,
        itens: nomes.map((nome) => {
          const dela = familias.get(nome);
          const apelido = apelidoDoImbuement(nome);
          return {
            /*
             * `id` é o nome EM INGLÊS, e não o apelido: ele é a chave do
             * agrupamento (`familias`) e o que fica guardado em `ctx.tabs`.
             * Traduzir a chave junto com o rótulo faria a escolha se perder
             * no primeiro redesenho.
             */
            id: nome,
            nome: apelido ? `${nome} — ${apelido}` : nome,
            sub: categoriaEmPortugues(dela[0].categoryName),
            arte: () => (dela[0].iconId ? imbuementIcon(dela[0].iconId, 24) : null),
          };
        }),
        aoEscolher: (nome) => {
          ctx.tabs.imbueFamilia = nome;
          /*
           * O grau NÃO é zerado de propósito: quem está comparando famílias
           * quer ver todas no mesmo grau. Se o grau escolhido não existir na
           * família nova, o `find` acima cai no primeiro.
           */
          desenhar();
        },
      })
    );
    menus.append(
      menuSuspenso({
        qual: 'grau',
        valor: grauAtual.base,
        aoRedesenhar: desenhar,
        itens: graus.map((imbuement) => ({
          id: imbuement.base,
          nome: grauEmPortugues(imbuement.baseName),
          sub: `${money(imbuement.price)}g`,
        })),
        aoEscolher: (base) => {
          ctx.tabs.imbueGrau = base;
          desenhar();
        },
      })
    );
    oficina.append(menus);

    // ---- O que este grau faz ----
    const efeito = el('div', `imbue-efeito grau-${grauAtual.base}`);
    if (grauAtual.iconId) efeito.append(imbuementIcon(grauAtual.iconId, 34));
    const dito = el('div', 'grow');
    const apelidoDoGrau = apelidoDoImbuement(grauAtual.name);
    dito.append(
      el('b', null, `${grauAtual.name}${apelidoDoGrau ? ` (${apelidoDoGrau})` : ''} — ${grauEmPortugues(grauAtual.baseName)}`)
    );
    dito.append(el('span', null, textoDoImbuement(grauAtual.description)));
    efeito.append(dito);
    oficina.append(efeito);

    // ---- O que ele custa ----
    /*
     * ---- O reagente que FALTA vem marcado ----
     *
     * Desde que a receita virou "N silver token + N gold token + N kk", o que
     * trava um imbuement quase nunca é o ouro: é o token. O número é o que ele
     * TEM ao lado do que precisa — "1/3" responde "quanto falta" sem obrigar a
     * abrir a mochila e contar.
     */
    const faltando = grauAtual.items.filter((need) => quantosTem(need.id) < need.count);

    const conta = el('div', 'imbue-conta');
    const receita = el('div', 'imbue-receita');
    receita.append(el('span', 'imbue-receita-titulo', 'Precisa de:'));
    const fichas = el('div', 'imbue-fichas');
    for (const need of grauAtual.items) {
      const tem = quantosTem(need.id);
      const falta = tem < need.count;
      const chip = el('span', `reagent${falta ? ' falta' : ''}`);
      chip.append(itemCanvas(need.id, 18), document.createTextNode(`${tem}/${need.count}`));
      tipFor(chip, need.id, falta ? `faltam ${need.count - tem}` : `${need.count} para este imbuement`);
      fichas.append(chip);
    }
    const ouro = el('span', `reagent ouro${character.gold < grauAtual.price ? ' falta' : ''}`);
    ouro.append(uiIcon('coin-gold'), document.createTextNode(`${money(grauAtual.price)}g`));
    tipTexto(ouro, `${money(character.gold)} no bolso`);
    fichas.append(ouro);
    receita.append(fichas);
    conta.append(receita);

    const apply = el('button', 'imbue-aplicar', 'Aplicar');
    const semPeca = !character.equipment[chosen];
    /*
     * Encaixe cheio: o servidor recusaria de qualquer jeito, mas o botão
     * apagado com o motivo no balão poupa o clique e a recusa.
     */
    const semEncaixe = totalSlots > 0 && ativos.length >= totalSlots;
    const semOuro = character.gold < grauAtual.price;
    apply.disabled = semPeca || semEncaixe || semOuro || faltando.length > 0;
    if (semPeca) tipTexto(apply, 'nada equipado neste encaixe');
    else if (semEncaixe) tipTexto(apply, 'os encaixes desta peça já estão ocupados — remova um primeiro');
    else if (semOuro) tipTexto(apply, `faltam ${money(grauAtual.price - character.gold)} gold`);
    else if (faltando.length) {
      tipTexto(
        apply,
        `faltam ${faltando
          .map((need) => `${need.count - quantosTem(need.id)}x ${ctx.state.items?.[need.id]?.name ?? need.id}`)
          .join(' e ')}`
      );
    }
    apply.onclick = () => send({ t: 'imbue', slot: chosen, id: grauAtual.id });
    conta.append(apply);
    oficina.append(conta);
  };

  desenhar();
}
// ---------- blessings ----------

export function openBlessings() {
  ctx.send({ t: 'blessings' });
  /*
   * E a LOJA, para saber quanto custa o pacote.
   *
   * O rodapé desta tela manda para a Store, e mandar com o preço errado
   * é pior do que mandar sem preço nenhum. O pedido vai UMA vez, na abertura —
   * como em `openStore` —, e não a cada redesenho: a tela se redesenha a cada
   * empurrão de estado, e um pedido por redesenho viraria enxurrada.
   */
  ctx.send({ t: 'store' });
  ctx.openModal('Blessings', (body) => {
    const draw = () => {
      body.innerHTML = '';
      renderBlessings(body);
    };
    ctx.redraw = draw;
    draw();
  });
}

/*
 * ---- As bênçãos, e o que elas evitam ----
 *
 * A tela abre com TRÊS números e não com um parágrafo: quantas estão ativas, o
 * desconto que elas somam, e quanto a próxima morte custaria agora. É o que a
 * pessoa veio saber, e é o que muda no instante em que ela compra uma.
 *
 * A conta é do servidor (`contaDaMorte`), nunca escrita à mão aqui: o texto que
 * morava neste lugar falava em "40% do que a caçada rendeu" e estava três
 * fórmulas atrasado. Um painel de loja que descreve errado o que vende é pior
 * do que um painel calado.
 */
/** O pacote das sete, na prateleira de serviços da loja (`store.mjs`). */
const PACOTE_DE_BLESSINGS = 'bless-pack';

function renderBlessings(body) {
  const { state, send } = ctx;
  const list = state.blessings;
  if (!list) return void body.append(el('p', 'empty', 'carregando...'));

  const ativas = list.filter((bless) => bless.owned).length;
  const resumo = state.blessingsResumo;

  // ------------------------------------------------------------- os números
  const chips = el('div', 'bless-chips');
  const chip = (rotulo, valor, classe = '') => {
    const caixa = el('div', `bless-chip ${classe}`);
    caixa.append(el('b', null, valor));
    caixa.append(el('span', null, rotulo));
    chips.append(caixa);
  };
  chip('ativas', `${ativas}/${list.length}`, ativas === list.length ? 'cheio' : '');
  if (resumo) {
    chip('de desconto na morte', `${resumo.descontoPercent}%`, resumo.descontoPercent >= 50 ? 'bom' : '');
    const emLevels = (resumo.expPerdida / Math.max(1, resumo.umLevel)).toFixed(2).replace('.', ',');
    chip('perderia agora', `${money(resumo.expPerdida)} XP`, 'perda');
    chip('em levels', emLevels, 'perda');

    /*
     * ---- E o OURO, que a tela não dizia ----
     *
     * "na aba de blessings tem que informar lá em cima o ouro que a pessoa
     *  perderia também se morresse."
     *
     * A tela media a morte só em experiência, e a morte também custa 20% do
     * ouro CARREGADO. Quem caça com quatro milhões no bolso perde oitocentos
     * mil ao morrer e não tinha onde ler isso.
     *
     * A conta é a do servidor (`ouroFracao`, em `contaDaMorte`) vezes o ouro
     * de agora — e não uma porcentagem escrita à mão aqui, que envelheceria na
     * primeira vez que o dono mexesse no `deathLoseGoldPercent` do painel.
     *
     * O chip não desconta bênção nenhuma porque a regra não desconta: elas
     * seguram a experiência, e o ouro é o custo que sobra igual para todo
     * mundo. Por isso o rótulo diz "não conta bênção" — sem isso, a leitura
     * natural é que comprar as sete zeraria também este número.
     */
    const ouroNaMao = Math.max(0, state.character?.gold ?? 0);
    const ouroPerdido = Math.round(ouroNaMao * (resumo.ouroFracao ?? 0));
    chip('de ouro (não conta bênção)', money(ouroPerdido), 'perda');
  }
  body.append(chips);

  /*
   * E o lembrete do banco, que é o que de fato protege o ouro.
   *
   * Ele só aparece quando há ouro em risco: com o bolso vazio a frase seria
   * ruído, e a tela já tem quatro números em cima.
   */
  if (resumo && (state.character?.gold ?? 0) > 0) {
    body.append(
      el(
        'p',
        'bless-poupanca',
        `Morrer também custa ${Math.round((resumo.ouroFracao ?? 0) * 100)}% do ouro que você estiver CARREGANDO — ` +
          `hoje ${money(Math.round((state.character?.gold ?? 0) * (resumo.ouroFracao ?? 0)))}. ` +
          'O que está no banco não é tocado.'
      )
    );
  }

  /*
   * Quanto ainda dá para economizar, dito como economia e não como regra.
   *
   * A explicação da fórmula continua embaixo, para quem quiser; aqui em cima
   * fica só a diferença entre o que ele perde hoje e o que perderia sem nada,
   * que é a razão de a tela existir.
   */
  if (resumo && ativas < list.length) {
    const semNada = Math.round(Math.min(resumo.expCheia, resumo.teto));
    const poupado = Math.max(0, semNada - resumo.expPerdida);
    body.append(
      el(
        'p',
        'bless-poupanca',
        poupado
          ? `Suas ${ativas} bênçãos já poupam ${money(poupado)} de XP por morte. Sem nenhuma seriam ${money(semNada)}.`
          : `Sem bênção nenhuma, morrer custa ${money(semNada)} de XP.`
      )
    );
  }

  // --------------------------------------------------------------- os cards
  const grid = el('div', 'bless-grid');
  for (const blessing of list) {
    const card = el('div', `bless-card${blessing.owned ? ' owned' : ''}`);

    const arte = el('div', 'bless-arte');
    if (blessing.charm && state.items[blessing.charm]) arte.append(itemCanvas(blessing.charm, 40));
    card.append(arte);

    card.append(el('b', 'bless-nome', blessing.name));
    card.append(el('em', 'bless-tipo', blessing.type === 'enhanced' ? 'aprimorada' : 'comum'));

    if (blessing.owned) {
      card.append(el('div', 'bless-ativa', 'Ativa'));
    } else {
      const preco = el('div', 'bless-preco');
      preco.append(el('b', null, money(blessing.price)));
      preco.append(el('span', null, 'gold'));
      card.append(preco);

      const comprar = el('button', 'bless-comprar', 'Comprar');
      comprar.disabled = state.character.gold < blessing.price;
      if (comprar.disabled) tipTexto(comprar, `faltam ${money(blessing.price - state.character.gold)}g`);
      comprar.onclick = () => send({ t: 'bless', id: blessing.id });
      card.append(comprar);
    }
    grid.append(card);
  }
  body.append(grid);

  // ------------------------------------------------------------- o rodapé
  /*
   * Dois caminhos para comprar tudo, e só dois — porque só existem dois.
   *
   * A loja vende um PACOTE (`bless-pack`, 10 coins) que aplica as sete de uma
   * vez; ela não vende bênção avulsa. Por isso o botão da loja mora aqui
   * embaixo e não dentro de cada card: um botão de loja por bênção compraria
   * as sete, e um botão que faz outra coisa além do que diz é defeito, não
   * atalho.
   */
  const rodape = el('div', 'bless-rodape');

  const faltando = list.filter((bless) => !bless.owned);
  const total = faltando.reduce((sum, bless) => sum + bless.price, 0);
  const todas = el('button', 'bless-todas', total ? `Comprar as ${faltando.length} que faltam — ${money(total)}g` : 'Você já tem todas');
  todas.disabled = !total || state.character.gold < total;
  todas.onclick = () => send({ t: 'bless', all: true });
  rodape.append(todas);

  if (total) {
    /*
     * ---- O preço sai da LOJA, e não daqui ----
     *
     * "arruma pra mostrar o valor certo do pacote de blessings: está mostrando
     *  180 Draevor Coins mas na verdade é 10."
     *
     * O número estava escrito à mão neste arquivo. Quando a régua de preços
     * caiu — o pacote foi de 180 para 10 —, a loja mudou e esta tela continuou
     * anunciando o preço velho, dezoito vezes maior. Ninguém tinha como saber:
     * um número escrito no client não quebra nada e não avisa nada, só mente.
     *
     * Agora ele vem de `state.store`, a mesma lista que a Store desenha.
     * O dono muda `coins` em `store.mjs` e as duas telas acompanham.
     *
     * Enquanto a loja não chegou (o pedido de `openBlessings` está a caminho),
     * o botão sai só com a moeda e sem dígito — melhor mudo do que errado. Ele
     * ganha o número sozinho: a chegada de `store` redesenha o modal aberto.
     */
    const custo = ctx.state.store?.services?.find((servico) => servico.id === PACOTE_DE_BLESSINGS)?.coins ?? null;
    const naLoja = el('button', 'bless-loja');
    // A moeda de verdade, e não uma ficha com o número solto: é a mesma arte da
    // Store, e é o que diz que este botão cobra em coin e não em ouro.
    const preco = el('span', 'bless-loja-moeda');
    preco.append(uiIcon('coin-store'));
    if (custo !== null) preco.append(el('b', null, String(custo)));
    naLoja.append(preco);
    naLoja.append(el('span', null, 'Pacote na Store'));
    tipTexto(
      naLoja,
      custo !== null
        ? `aplica as sete bênçãos de uma vez, por ${custo} Draevor Coins`
        : 'aplica as sete bênçãos de uma vez, pagas em coins'
    );
    naLoja.onclick = () => openStore();
    rodape.append(naLoja);
  }
  body.append(rodape);

  body.append(
    el(
      'p',
      'shop-note',
      `Cada bênção tira 8% da perda de experiência ao morrer e a promoção tira mais 30% — é a conta do ` +
        `crystalserver. A perda cheia é aparada num teto de 80% de um level, e o desconto morde o que sobra: ` +
        `com as sete ativas sobram 44%, com a promoção junto sobram 14%. Morrer queima todas. ` +
        `O ouro é conta à parte: morrer custa 20% do que você estiver carregando, com bênção ou sem — ` +
        `o que protege ouro é o banco.`
    )
  );
}

// ---------- tarefas: boss tasks e entregas ----------

/*
 * ---- A janela de Tarefas, em três abas ----
 *
 * Ela tinha quatro, e duas delas não eram tarefa nenhuma:
 *
 *   Tasks    — um quadro de bicho SORTEADO a cada vinte horas, que o dono
 *              mandou apagar. Ele pagava ouro e experiência por matar cem de
 *              alguma coisa, e não tinha ligação com o resto da janela;
 *   Entrega  — o botão de receber daquele quadro. Foi junto;
 *   Outfits  — um MOSTRUÁRIO: a lista inteira, o que falta apagado, e uma frase
 *              dizendo que o resto sai na loja. Não havia o que fazer ali;
 *   Mounts   — o mesmo mostruário, com montarias.
 *
 * As três que ficaram têm todas um verbo:
 *
 *   Boss Tasks — matar até abrir a luta contra um boss
 *   Outfits    — ENTREGAR o loot que o bicho larga e levar a roupa (ou o addon)
 *   Montarias  — a mesma troca, para as montarias
 */
/*
 * ---- A Loja de Task Token, no canto de ações ----
 *
 * "cria uma loja de task token, na aba de tarefas ao lado do x de fechar igual
 * fizemos na boss token loja sabe."
 *
 * O mesmo canto e o mesmo gesto da Loja de Boss Token. Ela vale em toda janela
 * cujo conteúdo PAGA em Task Token — hoje as tasks (de boss e de bicho), as
 * montarias e as outfits —, e por isso virou função: as três janelas nasceram
 * separadas (ver `openQuests`) e a loja tinha de ir junto sem ser copiada três
 * vezes.
 *
 * É chamada de dentro do desenho porque o canto é remontado a cada redesenho.
 */
function lojaDeTaskTokenNoCanto() {
  const loja = el('button', 'modal-acao bt-atalho');
  const moeda = itemCanvas(55729, 16);
  if (moeda) loja.append(moeda);
  loja.append(document.createTextNode('Loja de Task Token'));
  tipTexto(loja, 'Troque os Task Token que caem das tasks. Um token por mil mortes.');
  loja.onclick = () => openLojaDeTaskToken();
  ctx.acoesDoModal?.().append(loja);
}

/*
 * ---- Tarefas: só as TASKS ----
 *
 * O dono: "quando eu abrir tasks, só tem que aparecer no modal tasks e
 * montarias sabe? E renomeia pra Tasks de Montarias. O level reward, recompensa
 * diária e outfits não deve ficar no mesmo modal — assim como eu abrir level
 * reward terá sua própria aba e etc."
 *
 * A janela tinha cinco abas e elas não eram a mesma coisa. Duas são TASK — uma
 * conta de mortes que fecha e paga —, e as outras três são cada uma de uma
 * natureza: o Level Reward é um calendário do que o level já deu, a Recompensa
 * Diária é uma tela pintada inteira com botão próprio, e as Outfits são uma
 * troca de loot por roupa. Cinco portas para cinco assuntos numa janela só é o
 * tipo de arrumação que obriga a pessoa a abrir a aba errada para achar a
 * certa.
 *
 * Agora cada uma abre a sua, e a gaveta de Tarefas na barra de cima leva direto
 * a todas — o caminho não ficou mais longo para nenhuma.
 *
 * `aba` continua existindo porque as duas que sobraram são irmãs de verdade: as
 * duas são task, e a diferença entre elas é o que se caça.
 */
export function openQuests(aba) {
  if (aba) ctx.tabs.tarefas = aba;
  tabbedModal(
    'Tarefas',
    { tasks: 'Tasks', mounts: 'Tasks de Montarias' },
    'tarefas',
    (body, tab) => {
      lojaDeTaskTokenNoCanto();
      if (tab === 'mounts') return void renderEntregas(body, 'mount');
      /*
       * ---- As duas listas de task moram na MESMA aba ----
       *
       * A primeira versão pôs as tasks de criatura numa aba nova, e o dono
       * corrigiu: "nao era pra tu criar uma aba nova, era pra ser na mesma aba
       * de tasks sabe? igual esta, tudo bonitinho".
       *
       * Ele tem razão, e o motivo é o nome da aba: as duas SÃO tasks, e a
       * diferença entre elas é de escala, não de natureza — matar muito de um
       * bicho até uma conta fechar. Numa aba à parte, quem abrisse "Tasks"
       * veria três linhas e concluiria que o sistema tem três tasks.
       *
       * As boss tasks vêm primeiro porque são três e cabem na primeira tela;
       * a lista longa, com o filtro, vem embaixo.
       */
      renderTasksDeBicho(body);
    },
    undefined,
    {
      padrao: aba ?? 'tasks',
      /*
       * Nenhuma efêmera sobrou: as duas abas de agora são para ficar. As três
       * que eram (`recompensas`, `diario`) saíram para janelas próprias — a
       * regra existia porque elas não deviam ser lembradas como "a aba da
       * próxima vez", e agora elas nem moram aqui.
       */
      efemeras: [],
    },
  );
}

/*
 * ---- Level Reward: a janela que JÁ existia ----
 *
 * "assim como eu abrir level reward terá sua própria aba."
 *
 * Ela já tinha: é a `openPresente`, a que o presente da faixa de baixo abre
 * desde sempre. Escrever uma segunda janela para o mesmo calendário deixaria
 * duas telas do mesmo assunto envelhecendo separadas — e a do presente é a que
 * os jogadores já conhecem.
 *
 * Por isso não há uma `openLevelReward` aqui: a gaveta de Tarefas chama a
 * `openPresente` direto (ver `TAREFAS`, em main.mjs).
 */

/*
 * ---- Outfits, janela própria ----
 *
 * A troca de loot por roupa (e pelos addons dela). Ela paga em Task Token como
 * as tasks, então a loja vem junto no canto — ver `lojaDeTaskTokenNoCanto`.
 */
export function openOutfits() {
  ctx.openModal('Outfits', (body) => {
    const draw = () => {
      body.innerHTML = '';
      lojaDeTaskTokenNoCanto();
      renderEntregas(body, 'outfit');
    };
    ctx.redraw = draw;
    draw();
  });
}

/*
 * ---- A aba das BOSS TASKS ----
 *
 * Três cards, e cada um responde a três perguntas que o card antigo não
 * respondia: o que matar (com a cara do bicho), quanto falta, e o que se ganha.
 *
 * A recompensa é a frase que o dono pediu — "Recompensa: libera a luta contra
 * the Horned Fox" — e ela vem do SERVIDOR, escrita ao lado da regra que a
 * cumpre. Um texto redigitado aqui continuaria prometendo o boss antigo no dia
 * em que a task trocasse de prêmio.
 */
/*
 * ---- As tasks de criatura: uma linha para cada bicho que dá para caçar ----
 *
 * São 309, e é por isso que esta aba tem filtro enquanto as outras não têm.
 *
 * ---- O filtro mora FORA da função, de propósito ----
 *
 * Este modal se refaz sozinho: o ouro e o peso mudam por conta própria, e o
 * painel inteiro é reconstruído a cada empurrão de estado. Guardado no DOM, o
 * texto digitado e a faixa escolhida voltariam ao padrão sozinhos, no meio da
 * leitura — foi exatamente o defeito que os filtros do mercado tiveram.
 *
 * O `main.mjs` já devolve o FOCO e o cursor do campo depois do redesenho (ver
 * `typing`, lá); o que falta é a memória do que foi escolhido, e ela é isto.
 *
 * ---- E a lista é paginada ----
 *
 * Cada linha desenha a criatura, e desenhar 309 bonecos de uma vez é 309
 * canvas novos num quadro só. Sessenta de cada vez mantém a janela leve, e com
 * o filtro quase ninguém chega ao botão de ver mais.
 */
/*
 * `estado` é uma escolha ÚNICA, e não três interruptores.
 *
 * "com prêmio", "em andamento" e "quase finalizadas" se sobrepõem: uma task
 * quase finalizada está em andamento, e uma com prêmio também. Como três
 * chaves independentes, metade das combinações não quer dizer nada ("com
 * prêmio E quase finalizada" é um subconjunto, não um cruzamento) e a barra
 * viraria um quebra-cabeça. Como fichas de uma escolha só, cada uma responde
 * uma pergunta inteira.
 */
const ESTADOS = [
  { id: 'todas', nome: 'Todas' },
  { id: 'premio', nome: 'Com prêmio' },
  { id: 'andamento', nome: 'Em andamento' },
  { id: 'quase', nome: 'Quase finalizadas' },
];
/* Acima de quanto do progresso da etapa uma task conta como "quase". */
const QUASE = 0.7;

/*
 * ---- As regras saíram da tela e foram para um "?" ----
 *
 * "essas informações da aba de tasks — contam sozinhas, último degrau, ao pegar
 *  o prêmio etc — tira elas dali pra ocupar espaço e coloca tudo num ícone
 *  chamativo de interrogação '?' ao lado de quase finalizadas".
 *
 * Eram dois parágrafos em cima da lista, lidos uma vez na vida e relidos nunca.
 * Numa janela que já tem cinco abas, um filtro de duas famílias e uma linha de
 * resumo, eles empurravam o primeiro card para debaixo da dobra — todo dia,
 * para todo mundo, por causa de uma explicação que se lê uma vez.
 *
 * Aberto ou fechado mora AQUI, fora do desenho: o painel se refaz sozinho a
 * cada dez segundos, e um estado guardado no DOM fecharia a ajuda no meio da
 * leitura.
 */
let ajudaDasTasksAberta = false;

const filtroDeBichos = { texto: '', faixa: 'todos', estado: 'todas', mostrar: 24 };

/*
 * A ficha é pedida UMA vez por abertura, e não a cada redesenho — senão o
 * painel, que se refaz sozinho, mandaria um pedido por quadro.
 */
let ultimoPedidoDeBichos = 0;

/*
 * E ela se RENOVA enquanto a aba está aberta.
 *
 * As mortes mudam enquanto a pessoa caça, e a lista é uma foto. Sem isto, quem
 * abrisse a aba, caçasse uma hora e voltasse veria os números de uma hora atrás
 * — e um "faltam 12" que não anda parece sistema quebrado, não foto velha.
 *
 * Dez segundos: o suficiente para a régua andar à vista, e raro o bastante para
 * não ser tráfego. O pedido só sai enquanto ESTA aba está sendo desenhada, então
 * fechar a janela o encerra sozinho.
 */
const RITMO_DA_RENOVACAO = 10_000;

/*
 * ---- A faixa do Auto Task, no alto da aba de Tasks ----
 *
 * "coloca um botão chamativo lá em tasks: comprar auto task, que vai direto pra
 *  store, e informa se está ativo ou não etc — igual o auto boss na aba de boss".
 *
 * É a mesma ideia da `faixaDoAutoBoss`, e de propósito com as mesmas classes: a
 * aba de Bosses já ensinou esse desenho, e um segundo desenho para a mesma
 * função faria o jogador aprender duas vezes.
 *
 * O motivo de ela existir é o mesmo daquela: o produto mora numa vitrine com
 * dez serviços, onde "Auto Task sem limite" não diz nada a quem nunca esbarrou
 * no botão "Aceitar". Aqui está exatamente a tela em que a pergunta nasce.
 *
 * E ela diz o que o passe NÃO faz: não dá token a mais, não baixa alvo. Quem
 * descobre isso depois de pagar 200 coins tem razão em pedir o dinheiro de
 * volta — e é barato dizer antes.
 */
function faixaDoAutoTask(ficha) {
  const passe = ficha?.autoTask;
  const ativo = !!passe?.ativo;
  const caixa = el('div', `auto-boss auto-task${ativo ? ' com-passe' : ''}`);

  const topo = el('div', 'auto-boss-topo');
  topo.append(el('b', null, 'Auto Task'));
  if (ativo) {
    const selo = el('span', 'auto-boss-selo', '\u221e Sem parar \u00b7 conta');
    const falta = (passe.ate ?? 0) - Date.now();
    if (falta > 0) selo.append(el('i', null, formatLeft(falta)));
    topo.append(selo);
  } else {
    topo.append(el('span', 'auto-boss-espera', 'desligado'));
  }
  caixa.append(topo);

  caixa.append(
    el(
      'p',
      null,
      ativo
        ? 'Fechou uma etapa: o Task Token cai sozinho na mochila e a pr\u00f3xima j\u00e1 come\u00e7a a contar. '
          + 'Nenhuma morte cai no vazio, em qualquer personagem da conta.'
        : 'Sem ele, cada etapa fechada pede dois cliques \u2014 pegar o pr\u00eamio e aceitar de novo \u2014 e o que '
          + 'morrer entre um e outro n\u00e3o conta. Ele n\u00e3o d\u00e1 Task Token a mais nem baixa alvo: tira a parada.',
    ),
  );

  const acoes = el('div', 'confirm-actions auto-boss-acoes');
  if (ativo) {
    /* Quem já tem não precisa de anúncio; precisa do caminho para renovar. */
    const renovar = el('button', 'auto-boss-atalho', '\u2726 Renovar na Store');
    renovar.onclick = irParaOPasseNaLoja;
    acoes.append(renovar);
  } else {
    /*
     * O preço vem da LOJA, e não escrito aqui — a mesma regra da faixa do Auto
     * Boss. Enquanto a loja não chegou nesta aba, o botão sai sem número em vez
     * de sair com um chute que envelhece na primeira mudança de preço.
     */
    const passes = (ctx.state.store?.services ?? []).filter((s) => s.kind === 'autoTask');
    const menor = passes.slice().sort((um, outro) => (um.coins ?? 0) - (outro.coins ?? 0))[0];
    const comprar = el(
      'button',
      'primary auto-task-comprar',
      menor ? `\u2726 Comprar Auto Task \u2014 a partir de ${money(menor.coins)} Draevor Coins` : '\u2726 Comprar Auto Task na Store',
    );
    tipTexto(comprar, 'Abre a Store em Servi\u00e7os, onde ficam os dois prazos.');
    comprar.onclick = irParaOPasseNaLoja;
    acoes.append(comprar);
  }
  caixa.append(acoes);
  return caixa;
}

function renderTasksDeBicho(body) {
  const { state, send } = ctx;
  const ficha = state.tasksDeBicho;

  /*
   * Todo botão e toda tecla desta aba redesenham por AQUI.
   *
   * `ctx.redraw` cru refaz a janela e leva junto o foco e a rolagem — e num
   * campo de busca isso significa uma letra por clique, que foi o defeito que o
   * dono reportou. O `??` é só para esta função continuar de pé se alguém abrir
   * o painel por um caminho que não monta o `panelCtx` inteiro.
   */
  const redesenharTasks = () => (ctx.redrawSuave ?? ctx.redraw)?.();

  const agora = Date.now();
  if (agora - ultimoPedidoDeBichos > RITMO_DA_RENOVACAO) {
    ultimoPedidoDeBichos = agora;
    send({ t: 'tasksDeBicho' });
  }

  /*
   * ---- O FILTRO VEM PRIMEIRO ----
   *
   * "coloca o filtro la pra cima". Ele estava depois da nota e do cabeçalho, e
   * numa lista de trezentas linhas o filtro não é um detalhe da seção — é o
   * jeito de chegar ao que se procura. Quem abre a aba para achar um bicho não
   * devia ter de rolar até o filtro primeiro.
   */
  const barra = el('div', 'tbicho-filtro');
  const busca = el('input');
  /* O id é o que faz o `main.mjs` devolver o foco a ESTE campo depois do
     redesenho, e não a outro qualquer da janela. */
  busca.id = 'tbicho-busca';
  busca.type = 'search';
  busca.placeholder = 'Procurar criatura ou task...';
  busca.value = filtroDeBichos.texto;
  busca.oninput = () => {
    filtroDeBichos.texto = busca.value;
    filtroDeBichos.mostrar = 24;
    redesenharTasks();
  };
  barra.append(busca);

  const faixas = el('div', 'tbicho-faixas');
  for (const faixa of ficha?.faixas ?? []) {
    const botao = el('button', 'tbicho-faixa' + (filtroDeBichos.faixa === faixa.id ? ' ativa' : ''), faixa.nome);
    botao.onclick = () => {
      filtroDeBichos.faixa = faixa.id;
      filtroDeBichos.mostrar = 24;
      redesenharTasks();
    };
    faixas.append(botao);
  }
  /*
   * ---- As duas famílias de ficha na MESMA fileira ----
   *
   * "o filtro debaixo coloca ao lado do filtro de cima sabe, pra poupar
   *  espaço". Elas nasceram em duas fileiras porque peneiram coisas diferentes
   * — onde o bicho vive, e onde eu estou na task —, mas duas fileiras de fichas
   * empurravam o primeiro card para baixo da dobra numa janela que já tem abas,
   * título e nota.
   *
   * O que separa as duas famílias passa a ser a COR (turquesa para level,
   * dourado para estado) e uma divisa fina, e não uma linha inteira de altura.
   */
  const estados = el('div', 'tbicho-estados');
  for (const estado of ESTADOS) {
    const botao = el(
      'button',
      'tbicho-faixa tbicho-estado' + (filtroDeBichos.estado === estado.id ? ' ativa' : ''),
      estado.nome,
    );
    botao.onclick = () => {
      filtroDeBichos.estado = estado.id;
      filtroDeBichos.mostrar = 24;
      redesenharTasks();
    };
    estados.append(botao);
  }
  /*
   * O "?" fecha a fileira, encostado em "Quase finalizadas" como o dono pediu.
   * Dourado e redondo: é o único botão da barra que não peneira nada, e a forma
   * é o que o separa das fichas sem precisar de uma linha só para ele.
   */
  const ajuda = el('button', 'tbicho-ajuda' + (ajudaDasTasksAberta ? ' ativa' : ''), '?');
  tipTexto(ajuda, ajudaDasTasksAberta ? 'Esconder como as tasks funcionam' : 'Como as tasks funcionam');
  ajuda.onclick = () => {
    ajudaDasTasksAberta = !ajudaDasTasksAberta;
    redesenharTasks();
  };
  estados.append(ajuda);
  faixas.append(estados);
  barra.append(faixas);
  body.append(barra);

  body.append(faixaDoAutoTask(ficha));

  /*
   * A regra inteira em uma linha, embaixo do filtro. Sem ela cada card teria de
   * explicar sozinho por que o alvo daquele bicho é 2.000 e o do vizinho é
   * 25.000.
   */
  if (ajudaDasTasksAberta) {
  const degraus = (ficha?.escada ?? []).map((d) => `${money(d.mortes)} → ${d.tokens}`).join('   ·   ');
  /*
   * ---- A escada do BOSS não cabe escrita degrau a degrau ----
   *
   * São dez, todos iguais, e "10 → 1 · 20 → 1 · 30 → 1..." seria uma linha
   * inteira para dizer uma frase de seis palavras. O que a pessoa precisa saber
   * é o passo, o preço do passo e onde acaba.
   */
  const boss = ficha?.escadaDeBoss ?? [];
  const passoDoBoss = boss.length > 1 ? boss[1].mortes - boss[0].mortes : boss[0]?.mortes ?? 0;
  body.append(
    el(
      'p',
      'shop-note',
      'Contam sozinhas, sem aceitar nem desistir — e o que você já matou desde sempre conta. '
        + (degraus ? `Etapas (mortes → Task Token): ${degraus}. ` : '')
        + (boss.length
          ? `Boss conta separado: ${money(passoDoBoss)} em ${money(passoDoBoss)} mortes, `
            + `${boss[0].tokens} Task Token por etapa, até ${money(boss[boss.length - 1].mortes)}. `
          : '')
        + 'A task termina no último degrau.',
    ),
  );
  /*
   * ---- A regra do aceite, dita em cima e não só no card ----
   *
   * Ela muda o que o jogador faz depois de pegar o prêmio, e quem só a descobre
   * pelo botão descobre tarde — depois de uma hora caçando sem contar nada.
   *
   * Com o passe, a frase é outra: não adianta ensinar um botão que não vai
   * aparecer.
   */
  const passe = ficha?.autoTask;
  body.append(
    el(
      'p',
      'shop-note' + (passe?.ativo ? ' tbicho-passe' : ''),
      passe?.ativo
        ? 'Auto Task ativo' + (passe.ate ? ` até ${new Date(passe.ate).toLocaleDateString('pt-BR')}` : '')
          + ': ao pegar o prêmio a task já volta a contar sozinha, sem aceitar de novo.'
        : 'Ao pegar o prêmio a task pára: clique em Aceitar para a próxima etapa começar a contar. '
          + 'O que morrer com ela parada não conta. O passe Auto Task, na Store, aceita e resgata sozinho.',
    ),
  );
  }

  if (!ficha) {
    body.append(el('p', 'gate-note', 'Consultando as tasks...'));
    return;
  }

  // ---- a peneira ----
  /*
   * A ficha "Bosses" não tem faixa de level: ela peneira pela MARCA, e por isso
   * fica fora desta tabela. Misturada nela precisaria de um intervalo inventado,
   * e um boss de sala de level 116 (Demodras) ficaria fora do próprio filtro.
   */
  const soBosses = filtroDeBichos.faixa === 'bosses';
  const limites = {
    todos: [0, Infinity],
    inicio: [0, 99],
    medio: [100, 299],
    alto: [300, 699],
    elite: [700, Infinity],
  }[filtroDeBichos.faixa] ?? [0, Infinity];
  const procura = filtroDeBichos.texto.trim().toLowerCase();
  const naFaixa = (level) => level >= limites[0] && level <= limites[1];

  /*
   * ---- As boss tasks entram na MESMA lista ----
   *
   * "nao precisa separar as tasks normais das tasks que libera luta com os
   *  bosses". Elas eram uma lista à parte, com nota e cabeçalho próprios, e o
   *  dono tem razão: são tasks, o card é o mesmo, e duas listas na mesma aba
   *  obrigavam a rolar uma inteira para chegar à outra.
   *
   * Elas vêm primeiro porque são três e porque abrem uma luta — o prêmio delas
   * não é moeda, é conteúdo. E entram na peneira como todo o resto: o level
   * delas é o do bicho mais fácil que elas pedem, tirado da própria lista de
   * criaturas (o cliente não tem level de bicho em outro lugar).
   */
  const levelPorChave = new Map((ficha.bichos ?? []).map((b) => [b.key, b.level]));
  const levelDaBossTask = (task) => {
    const levels = (task.alvos ?? []).map((a) => levelPorChave.get(a.key)).filter(Number.isFinite);
    return levels.length ? Math.min(...levels) : 0;
  };
  /*
   * O estado de uma task, para a peneira. As duas famílias respondem igual:
   * boss task tem `kills`/`alvo` e `feito`; criatura tem `progresso` e
   * `completa`. Traduzir as duas para o mesmo vocabulário aqui é o que deixa
   * uma ficha só peneirar as duas listas.
   */
  const passaNoEstado = ({ temPremio, andando, progresso, pronta }) => {
    switch (filtroDeBichos.estado) {
      case 'premio': return temPremio;
      case 'andamento': return andando;
      /*
       * "Quase" é quem está CHEGANDO, e o corte é 70% do degrau atual.
       *
       * O `progresso < 1` é o que separa "quase" de "acabou": quando a escada
       * inteira fecha não há degrau seguinte, o progresso trava em 1, e a task
       * apareceria aqui a 100% para sempre. Enquanto houver degrau à frente o
       * progresso é sempre menor que 1 — fechar um degrau já move a conta para
       * o próximo —, então isto nunca esconde quem ainda tem o que fazer.
       *
       * (A primeira tentativa excluía quem tivesse QUALQUER prêmio esperando, e
       * esvaziava a ficha: quem não resgata há uma semana tem prêmio em tudo, e
       * "quase finalizadas" ficava em zero justamente para quem mais precisa
       * dela.)
       */
      case 'quase': return !pronta && progresso >= QUASE && progresso < 1;
      default: return true;
    }
  };

  const bossTasks = (state.character?.bossTasks ?? []).filter((task) => {
    /* Com a ficha de bosses ligada elas ficam: são tasks de boss por definição. */
    if (!soBosses && !naFaixa(levelDaBossTask(task))) return false;
    if (procura && !String(task.name ?? '').toLowerCase().includes(procura)) return false;
    const progresso = task.alvo > 0 ? Math.min(1, (task.kills ?? 0) / task.alvo) : 0;
    return passaNoEstado({
      /* Boss task não tem token para pegar: o prêmio dela é a luta em si. */
      temPremio: false,
      andando: (task.kills ?? 0) > 0 && !task.feito,
      progresso,
      pronta: !!task.feito,
    });
  });

  const bichos = (ficha.bichos ?? []).filter((b) => {
    if (soBosses ? !b.boss : !naFaixa(b.level)) return false;
    if (procura) {
      const nome = state.catalog?.bestiary?.[b.key]?.name ?? b.key;
      if (!nome.toLowerCase().includes(procura)) return false;
    }
    return passaNoEstado({
      temPremio: b.aResgatar > 0,
      /* "já tenho algumas kills" — e a task ainda não acabou. */
      andando: b.mortes > 0 && !b.completa,
      progresso: b.progresso ?? 0,
      pronta: !!b.completa,
    });
  });

  const prontasTotal = (ficha.bichos ?? []).filter((b) => b.aResgatar > 0).length;
  const quaseTotal = (ficha.bichos ?? []).filter(
    (b) => !b.completa && (b.progresso ?? 0) >= QUASE && (b.progresso ?? 0) < 1).length;
  const total = (ficha.bichos ?? []).length + (state.character?.bossTasks ?? []).length;
  body.append(
    el(
      'p',
      'tbicho-resumo',
      `${money(bossTasks.length + bichos.length)} de ${money(total)} tasks`
        + (prontasTotal ? ` · ${prontasTotal} com prêmio para pegar` : '')
        + (quaseTotal ? ` · ${quaseTotal} quase lá` : ''),
    ),
  );

  if (!bossTasks.length && !bichos.length) {
    body.append(el('p', 'empty', 'Nenhuma task com esse filtro.'));
    return;
  }

  /*
   * ---- QUEM VAI PARA O TOPO ----
   *
   * "as tasks que mostram no topo sao as que estao com mais andamento sabe?
   *  perto de concluir a etapa atual no caso".
   *
   * A ordem era level e depois nome — a mesma do seletor de hunt. Ela servia
   * para PROCURAR um bicho, e procurar é o que o campo de busca faz. O que a
   * lista precisa responder ao abrir é outra coisa: "o que está quase pronto?".
   * Com 313 linhas em ordem de level, a task a 97% podia estar na página nove.
   *
   * Três patamares, e o resto é desempate:
   *
   *   0  tem prêmio esperando (ou o boss já abriu) — é clique, não caçada
   *   1..2  em andamento, do mais adiantado para o menos (1 + (1 - progresso))
   *   3  acabou — sai da frente de quem ainda tem o que fazer
   *
   * As duas famílias entram na MESMA ordenação. As boss tasks vinham sempre
   * coladas no topo, e com esta regra isso deixaria três cards de 0% na frente
   * de uma task a 99% — exatamente o que o pedido quer desfazer.
   */
  const pesoDoProgresso = (progresso) => 1 + (1 - Math.min(1, Math.max(0, progresso || 0)));
  const emOrdem = [
    ...bossTasks.map((task) => {
      const progresso = task.alvo > 0 ? Math.min(1, (task.kills ?? 0) / task.alvo) : 0;
      return {
        /* Boss task "pronta" é a que abriu a luta e ainda não foi morta. */
        peso: task.matou ? 3 : task.feito ? 0 : pesoDoProgresso(progresso),
        level: levelDaBossTask(task),
        nome: String(task.name ?? ''),
        node: () => cardDeBossTask(task),
      };
    }),
    ...bichos.map((bicho) => ({
      /*
       * Pausada vai junto com "tem prêmio" no topo, e não no meio da fila por
       * progresso: as duas são um CLIQUE parado esperando, e uma task pausada
       * esquecida no fundo da lista é caçada jogada fora sem ninguém saber.
       */
      peso: bicho.aResgatar > 0 || bicho.pausada ? 0 : bicho.completa ? 3 : pesoDoProgresso(bicho.progresso),
      level: bicho.level,
      nome: state.catalog?.bestiary?.[bicho.key]?.name ?? bicho.key,
      node: () => cardDeTaskDeBicho(bicho),
    })),
  ];
  /*
   * O desempate continua sendo level e nome, e não é detalhe: num personagem
   * novo TODA task está em zero, empatada no mesmo peso, e sem ele a lista sairia
   * na ordem em que o `Map` foi montado — que não é ordem nenhuma para quem lê.
   */
  emOrdem.sort((a, b) => a.peso - b.peso || a.level - b.level || a.nome.localeCompare(b.nome, 'pt-BR'));

  const grade = el('div', 'bosstask-lista');
  for (const linha of emOrdem.slice(0, filtroDeBichos.mostrar)) grade.append(linha.node());
  body.append(grade);

  if (emOrdem.length > filtroDeBichos.mostrar) {
    const mais = el('button', 'tbicho-mais', `Ver mais ${Math.min(24, emOrdem.length - filtroDeBichos.mostrar)}`);
    mais.onclick = () => {
      filtroDeBichos.mostrar += 24;
      redesenharTasks();
    };
    body.append(mais);
  }
}

/*
 * ---- O card de uma task de criatura ----
 *
 * O MESMO desenho de três colunas da boss task e da task de montaria, e de
 * propósito. O dono foi direto ao ponto: "as novas tasks era pra ter os cards
 * bonito igual tem a da task de minotaur sabe?".
 *
 * A primeira versão era uma lista de linhas baixas, escolhida por medo do peso:
 * são 309 bichos, e 309 cards é muito DOM. Mas o medo estava resolvido do lado
 * errado — quem resolve o peso é a paginação (e o filtro), não encolher o
 * desenho. Com 24 por página o card cabe, e a aba fica igual às vizinhas.
 *
 * As três colunas dizem a mesma coisa que nas outras duas:
 *
 *   esquerda — quem precisa morrer, com a cara
 *   meio     — quanto falta, com a régua
 *   direita  — o que se ganha, e o botão de pegar quando há o que pegar
 */
function cardDeTaskDeBicho(bicho) {
  const { state, send } = ctx;
  const pronta = bicho.aResgatar > 0;
  /* Fechou, recebeu, e espera o "Aceitar". Ver `tasks-de-bicho.mjs`. */
  const pausada = !!bicho.pausada;
  /*
   * Nome e alvo NÃO vêm do servidor: o nome está no bestiário que o cliente já
   * tem, e o alvo é o degrau da etapa atual. Os dois viajavam e foram cortados
   * — 309 cópias de um nome que já estava na memória custavam 12 KB por
   * consulta.
   */
  const nome = state.catalog?.bestiary?.[bicho.key]?.name ?? bicho.key;
  /*
   * A escada é UMA só para todo bicho, e vem uma vez na ficha. Ela viajou por
   * bicho enquanto houve correção por raridade; hoje não há, e 309 cópias do
   * mesmo vetor eram 16 KB por consulta.
   *
   * O alvo sai das etapas FECHADAS, e não das pagas: quem tem duas fechadas e
   * nenhuma recebida está perseguindo a terceira — com `etapa` a tela mostraria
   * o alvo da primeira, que ele passou faz tempo.
   */
  /*
   * ---- Boss lê a OUTRA escada ----
   *
   * São duas, e vieram as duas na ficha. Com uma só, o card do Demodras
   * desenharia cinco marcas de etapa pedindo 2.000 mortes enquanto o servidor
   * cobrava dez — a tela e o resgate contariam coisas diferentes, e só quem
   * clicasse descobriria qual das duas estava certa.
   */
  const tabela = ctx.state.tasksDeBicho;
  const degraus = ((bicho.boss ? tabela?.escadaDeBoss : tabela?.escada) ?? []).map((d) => d.mortes);
  /*
   * `fechadas` é a etapa ATUAL: as pagas mais as que esperam o botão. Quando a
   * escada endurece e as pagas passam as fechadas, `aResgatar` é zero e a conta
   * dá as pagas — que é justamente a etapa que a pessoa persegue.
   */
  const fechadas = bicho.etapa + bicho.aResgatar;
  /*
   * O alvo vem PRONTO do servidor, e não é mais refeito aqui.
   *
   * Refazer dava dois donos para o mesmo degrau, e eles discordaram: o alvo
   * saía das etapas pagas e a barra, lá no servidor, das mortes. Report do
   * dono: "estou 9.318/25.000 mortes e a barra ta no final".
   */
  const alvo = bicho.alvo ?? degraus[Math.min(fechadas, Math.max(0, degraus.length - 1))] ?? 0;
  const card = el('div', 'bosstask-card ui-frame ui-frame--card'
    + (pronta ? ' tbicho-pronta' : pausada ? ' tbicho-pausada' : bicho.completa ? ' bosstask-feita' : ''));
  const dentro = el('div', 'bosstask-dentro');

  // ---- quem precisa morrer, com a cara ----
  const alvos = el('div', 'bosstask-alvos');
  const cela = el('div', 'bosstask-alvo');
  /*
   * O `look` tem de vir JUNTO, e não só a chave.
   *
   * `figuraDaCriatura` cai no catálogo para a cor e para o sprite de item, mas
   * o desenho do bicho ela tira de `creature.look` — não de `entry.look`. Com
   * só a chave, `outfitInfo(undefined)` dá falso, o item é zero, e o que sobra
   * é o quadrado vazio: os cards saíram com as estrelas e o nome, e nenhum
   * bicho. Não quebra nada, não dá erro nenhum, e só aparece olhando.
   */
  const ficha = state.catalog?.bestiary?.[bicho.key];
  cela.append(
    figuraDaCriatura(
      { key: bicho.key, look: ficha?.look, colors: ficha?.colors, lookItem: ficha?.lookItem },
      state.catalog?.bestiary,
      44,
    ),
  );
  cela.append(el('span', null, nome));
  alvos.append(cela);
  dentro.append(alvos);

  // ---- o alvo da etapa e a régua ----
  const meio = el('div', 'bosstask-meio');
  meio.append(el('b', 'bosstask-titulo', money(alvo) + '× ' + nome));
  /*
   * A linha de baixo do título diz onde o bicho vive e em que etapa a pessoa
   * está. "level 250" é o que faz alguém entender por que nunca viu aquele
   * bicho, e a etapa é o que explica um alvo de 50.000 ao lado de um de 2.000.
   */
  meio.append(
    el(
      'em',
      'bosstask-blurb',
      /*
       * ---- Boss não "aparece em hunt" ----
       *
       * A frase valia quando a lista era só de bicho de elenco. Para o Demodras
       * ela ficava quase certa (a sala dele é uma hunt, e tem level), e para o
       * Orshabaal ficava errada: ele não tem sala nenhuma, e mandar alguém
       * procurar "hunt de level 250" é mandá-lo procurar o que não existe.
       */
      (bicho.semSala
        ? 'Boss de evento — invocado na arena de Boss Diários'
        : bicho.boss
          ? `Boss · sala de level ${bicho.level}`
          : `Aparece em hunt de level ${bicho.level}`)
        + (pausada
          ? ' · parada — aceite para contar'
          : bicho.completa
          ? ' · task concluída'
          /*
           * Conta as etapas FECHADAS, e não as recebidas. Com as recebidas, um
           * troll com duas etapas fechadas e nada resgatado dizia "primeira
           * etapa" embaixo de um título que pedia 25.000 — as duas linhas do
           * card se contradiziam.
           */
          : fechadas > 0 ? ` · na ${fechadas + 1}ª etapa` : ' · primeira etapa'),
    ),
  );

  /*
   * A régua mede o trecho DA ETAPA, e não a vida inteira. Medindo do zero, um
   * bicho com 99.000 mortes indo para 100.000 apareceria quase cheio na etapa
   * anterior e quase cheio nesta — a barra não diria nada.
   */
  const track = el('div', 'track accent');
  const fill = el('i');
  fill.style.width = Math.round((bicho.progresso ?? 0) * 100) + '%';
  track.append(fill);
  meio.append(track);

  /*
   * ---- A fileira de ETAPAS ----
   *
   * "faz tipo as etapas mostrando ali com um simbolozinho sabe? e cada que eu
   *  concluir tem que ficar um certinho."
   *
   * Cinco marcas, uma por degrau. Elas respondem de relance o que a barra não
   * responde: a barra mostra a etapa ATUAL, e estas mostram a task inteira —
   * quantas já foram, em qual estou, quantas faltam.
   *
   * Três estados, e cada um tem símbolo próprio em vez de só uma cor: cor
   * sozinha não se lê em quem enxerga mal, e a fileira é pequena.
   *
   *   ✓  fechada e recebida
   *   ●  fechada esperando o botão (é o mesmo dourado do "Pegar")
   *   ·  ainda não
   */
  const etapas = el('div', 'tbicho-etapas');
  degraus.forEach((alvoDaEtapa, i) => {
    const estado = i < bicho.etapa ? 'feita' : i < fechadas ? 'pegar' : 'aberta';
    const marca = el('i', 'tbicho-marca tbicho-marca-' + estado, estado === 'feita' ? '✓' : estado === 'pegar' ? '●' : '·');
    tipTexto(
      marca,
      `${i + 1}ª etapa — ${money(alvoDaEtapa)} mortos`
        + (estado === 'feita' ? ' · recebida' : estado === 'pegar' ? ' · pronta para pegar' : ''),
    );
    etapas.append(marca);
  });
  meio.append(etapas);

  /*
   * O numerador não passa do alvo.
   *
   * Quem fechou a escada inteira e ainda não resgatou tem mais mortes do que o
   * último degrau pede — um Wyrm com 150.000 mortos numa escada que acaba em
   * 45.000 aparecia como "150.000 / 45.000", que lê como defeito. O `min` não
   * muda nada no caso normal: enquanto há degrau à frente, as mortes são
   * sempre menores que ele.
   */
  meio.append(
    el('em', 'bosstask-conta', money(Math.min(bicho.mortes, alvo)) + ' / ' + money(alvo) + ' mortos'),
  );
  dentro.append(meio);

  // ---- o que se ganha ----
  const premio = el('div', 'bosstask-premio');
  const moeda = itemCanvas(55729, 40);
  if (moeda) premio.append(moeda);
  const texto = el('div', 'bosstask-premio-texto');
  texto.append(el('span', 'bosstask-premio-rotulo', 'Recompensa'));
  texto.append(
    el('b', null, bicho.completa && !pronta
      ? 'tudo recebido'
      : `${pronta ? bicho.tokens : bicho.premio} Task Token`),
  );

  if (pronta) {
    const pegar = el('button', 'tbicho-pegar', `Pegar ${bicho.tokens}`);
    tipTexto(pegar, `${bicho.aResgatar} etapa(s) fechada(s) — ${bicho.tokens} Task Token.`);
    pegar.onclick = () => send({ t: 'tasksDeBicho', action: 'resgatar', key: bicho.key });
    texto.append(pegar);
  } else if (pausada) {
    /*
     * ---- O botão de ACEITAR ----
     *
     * Ele é o mesmo dourado do "Pegar" de propósito: os dois são a mesma
     * espécie de coisa — um clique parado esperando o jogador —, e pintá-los
     * diferente faria o segundo parecer menos urgente do que é. A diferença
     * está no card, que fica apagado enquanto a task não conta.
     */
    const aceitar = el('button', 'tbicho-pegar tbicho-aceitar', 'Aceitar');
    tipTexto(
      aceitar,
      'A task está parada desde que você pegou o prêmio: o que morrer agora não conta.'
        + ' Aceitar recomeça a contagem de onde ela parou.',
    );
    aceitar.onclick = () => send({ t: 'tasksDeBicho', action: 'aceitar', key: bicho.key });
    texto.append(aceitar);
  } else {
    /*
     * A task ACABA no último degrau (o dono: "teto maximo de 100k de kill e
     * depois encerra"). Sem esta linha, uma task fechada mostraria "faltam 0" —
     * que lê como travada, e não como terminada.
     */
    texto.append(
      el('em', 'bosstask-estado' + (bicho.completa ? ' feito' : ''),
        bicho.completa
          ? `concluída — ${money(alvo)} mortos`
          : `faltam ${money(Math.max(0, alvo - bicho.mortes))}`),
    );
  }
  premio.append(texto);
  dentro.append(premio);

  card.append(dentro);
  return card;
}

/*
 * (`degrauAnteriorDe` saiu daqui. Ela refazia, no cliente, a conta de onde a
 * etapa atual comecou — para desenhar a barra. Hoje o servidor manda
 * `progresso` pronto, e a regua passou a ter um dono so': duas copias dela
 * discordariam no dia em que a escada mudasse, e o filtro "quase finalizadas"
 * usa exatamente o mesmo numero.)
 */


/*
 * ---- `renderBossTasks` foi embora ----
 *
 * Ela desenhava as boss tasks numa lista propria, com nota e titulo proprios.
 * O dono juntou as duas: "nao precisa separar as tasks normais das tasks que
 * libera luta com os bosses". Hoje quem desenha as duas e' o
 * `renderTasksDeBicho`, numa grade so' — os cards eram ja' os mesmos, e o que
 * havia de diferente era so' a separacao.
 *
 * O `cardDeBossTask` continua vivo, logo abaixo: e' ele que a grade usa.
 */
/*
 * ---- O Task Token, escrito junto da recompensa ----
 *
 * "la na aba de tasks e task montarias tem que ter aonde ta a recompensa
 *  pequeno escrito a quantidade de task token que ganha tambem (nao aumente
 *  nem quebre o modal)".
 *
 * Uma linha de 10px na coluna do prêmio, e não um card novo nem um selo ao lado
 * do título. A coluna já tinha três linhas (rótulo, nome, estado) e o lado
 * ESQUERDO do card é sempre mais alto que ela — os retratos das criaturas e as
 * réguas de progresso —, então a quarta linha cabe na altura que já existe. É
 * isso que o "não aumente o modal" pede.
 *
 * O número vem do SERVIDOR (`tokens`, nas duas views), e não de uma conta feita
 * aqui: quem paga é `tokensDaTask`, e uma segunda conta na tela prometeria o
 * valor velho no dia em que a régua mudasse.
 */
function linhaDoTaskToken(task) {
  if (!(task?.tokens > 0)) return null;
  const linha = el(
    'em',
    'bosstask-token',
    '+' + money(task.tokens) + ' Task Token'
  );
  linha.title = 'esta task paga ' + money(task.tokens) + ' Task Token quando fechar';
  return linha;
}
/*
 * ---- O card de uma task de montaria ----
 *
 * O mesmo desenho de três colunas da boss task, e de propósito: quem já
 * entendeu um entende o outro sem reaprender nada. O que ele NÃO tem é o que o
 * dono pediu que não tivesse — "nao precisa ter esses detalhezinhos ok so a
 * imagem doq ganha, a imagem dos bixo da task e o progresso igual ja esta".
 * Então não há frase de prêmio nem descrição: a montaria desenhada já diz o que
 * se ganha.
 *
 * A barra é UMA POR ALVO, e não uma só. O baú do Gloomwurm pede quatro
 * aparições, duas mil de cada, e cada uma é uma conta própria (ver
 * `tasks-de-montaria.mjs`): uma barra só somando as quatro mostraria 100% para
 * quem matou oito mil de um bicho e nenhum dos outros três.
 */
function cardDeTaskDeMontaria(task) {
  const card = el('div', 'bosstask-card ui-frame ui-frame--card' + (task.feito ? ' bosstask-feita' : ''));
  const dentro = el('div', 'bosstask-dentro');

  // ---- quem precisa morrer, com a cara ----
  const alvos = el('div', 'bosstask-alvos');
  for (const alvo of task.alvos ?? []) {
    const cela = el('div', 'bosstask-alvo');
    if (outfitInfo(alvo.look)) cela.append(outfitCanvas(alvo.look, alvo.colors ?? null, 44));
    cela.append(el('span', null, alvo.name));
    alvos.append(cela);
  }

  // ---- o nome da montaria e uma régua por alvo ----
  const meio = el('div', 'bosstask-meio');
  meio.append(el('b', 'bosstask-titulo', task.name));
  for (const alvo of task.alvos ?? []) {
    const track = el('div', 'track accent');
    const fill = el('i');
    fill.style.width = Math.min(100, (alvo.kills / alvo.alvo) * 100) + '%';
    track.append(fill);
    meio.append(track);
    meio.append(
      el('em', 'bosstask-conta', money(alvo.kills) + ' / ' + money(alvo.alvo) + ' ' + alvo.name),
    );
  }

  // ---- e o que cai ----
  const premio = el('div', 'bosstask-premio');
  if (outfitInfo(task.mountLook)) premio.append(outfitCanvas(task.mountLook, null, 56));
  const texto = el('div', 'bosstask-premio-texto');
  texto.append(el('span', 'bosstask-premio-rotulo', 'Montaria'));
  texto.append(el('b', null, task.name));
  { const tt = linhaDoTaskToken(task); if (tt) texto.append(tt); }
  texto.append(el('em', 'bosstask-estado' + (task.feito ? ' feito' : ''), task.feito ? 'sua' : 'trancada'));
  premio.append(texto);

  dentro.append(alvos, meio, premio);
  card.append(dentro);
  return card;
}

function cardDeBossTask(task) {
  const estado = task.matou ? ' bosstask-feita' : task.feito ? ' bosstask-aberta' : '';
  const card = el('div', 'bosstask-card ui-frame ui-frame--card' + estado);
  const dentro = el('div', 'bosstask-dentro');

  // ---- quem precisa morrer, com a cara ----
  const alvos = el('div', 'bosstask-alvos');
  for (const alvo of task.alvos ?? []) {
    const cela = el('div', 'bosstask-alvo');
    if (outfitInfo(alvo.look)) cela.append(outfitCanvas(alvo.look, alvo.colors ?? null, 44));
    cela.append(el('span', null, alvo.name));
    alvos.append(cela);
  }

  // ---- o título e a régua ----
  const meio = el('div', 'bosstask-meio');
  meio.append(el('b', 'bosstask-titulo', money(task.alvo) + '× ' + task.name));
  meio.append(el('em', 'bosstask-blurb', task.blurb));

  const track = el('div', 'track accent');
  const fill = el('i');
  fill.style.width = Math.min(100, (task.kills / task.alvo) * 100) + '%';
  track.append(fill);
  meio.append(track);
  meio.append(el('em', 'bosstask-conta', money(task.kills) + ' / ' + money(task.alvo) + ' mortos'));

  /*
   * A recompensa, com a cara do boss ao lado.
   *
   * "Libera a luta contra Demodras" e um Demodras desenhado dizem a mesma coisa
   * por dois canais — e quem nunca viu o bicho só entende pelo segundo.
   */
  const premio = el('div', 'bosstask-premio');
  if (outfitInfo(task.bossLook)) premio.append(outfitCanvas(task.bossLook, task.bossColors ?? null, 56));
  const texto = el('div', 'bosstask-premio-texto');
  texto.append(el('span', 'bosstask-premio-rotulo', 'Recompensa'));
  texto.append(el('b', null, task.recompensa ?? 'Libera a luta contra ' + task.bossName));
  { const tt = linhaDoTaskToken(task); if (tt) texto.append(tt); }
  texto.append(
    el(
      'em',
      'bosstask-estado' + (task.matou ? ' feito' : task.feito ? ' aberto' : ''),
      task.matou
        ? 'já derrotado — sai uma vez por personagem'
        : task.feito
          ? 'liberado — entre pela aba de Aventuras'
          : 'trancado',
    ),
  );
  premio.append(texto);

  dentro.append(alvos, meio, premio);
  card.append(dentro);
  return card;
}

/*
 * ---- O balcão de entregas ----
 *
 * Um card por PEÇA, e não por entrega.
 *
 * Antes cada linha do balcão virava um card: "Mage — addon 1" e "Mage — addon
 * 2" apareciam como duas coisas sem relação, em pontos diferentes da grade,
 * cada uma com um bonequinho igual ao do outro. Quem olhava não tinha como
 * saber que os dois são a mesma roupa nem em que ordem fazia sentido buscá-los.
 *
 * Agora o Mage é UM card, com os passos dele dentro — a roupa, o addon 1, o
 * addon 2 — cada passo com a sprite do que ele veste, o item que pede, quantos
 * você tem e de quem cai. O boneco grande da esquerda mostra o que você JÁ
 * conquistou; os pequenos, o que cada passo acrescenta.
 */
/*
 * ---- O que depende do ouro no bolso, calculado aqui ----
 *
 * `temOuro`, `pronta` e `podeAdiantar` mudam a cada moeda, e o servidor
 * reenviava as 33 entregas (26 KB) por isso — 97% do tráfego do personagem numa
 * caçada. Agora ele manda só `itensProntos`/`temAlgumItem`, e a conta (a MESMA
 * de `comOuroDoBolso`, em game/systems/entregas.mjs) é feita com o `gold` que o
 * cliente já tem. Entrega que já vem com `pronta` (servidor antigo) passa como veio.
 */
function comOuroDoBolso(entrega, gold) {
  if ('pronta' in entrega) return entrega;
  const temOuro = Math.max(0, Math.min(entrega.ouro - entrega.ouroEntregue, gold));
  return {
    ...entrega,
    temOuro,
    pronta: !entrega.feita && entrega.itensProntos && entrega.ouroEntregue + temOuro >= entrega.ouro,
    podeAdiantar: !entrega.feita && (entrega.temAlgumItem || temOuro > 0),
  };
}

function renderEntregas(body, tipo) {
  const { state, send } = ctx;
  const todas = (state.character.entregas ?? []).map((entrega) => comOuroDoBolso(entrega, state.character.gold ?? 0));
  const lista = todas.filter((entrega) => entrega.tipo === tipo);

  /*
   * ---- Na aba das montarias, as TASKS vêm primeiro ----
   *
   * "so deixa meio separado oq sera entrega e oq sera task".
   *
   * São duas maneiras de conseguir a mesma coisa e elas não se parecem em nada:
   * a task conta mortes sozinha e paga quando fecha; a entrega pede loot e um
   * clique no balcão. Misturadas na mesma lista, o jogador não saberia por que
   * um card tem botão e o outro não.
   *
   * Então cada uma tem o seu título e a sua frase, e a régua horizontal entre
   * elas é o que diz "aqui começa outra coisa". As tasks vêm em cima porque
   * andam sozinhas — quem abre a aba quer ver quanto falta antes de ver o que
   * há para entregar.
   */
  if (tipo === 'mount') {
    const tasks = state.character.mountTasks ?? [];
    if (tasks.length) {
      body.append(el('h4', 'bosstask-secao', 'Tasks de montaria'));
      body.append(
        el(
          'p',
          'shop-note',
          'Contam sozinhas, sem aceitar nem desistir: cada morte entra na conta enquanto você caça. ' +
            'A montaria entra na sua coleção na hora em que a conta fecha.',
        ),
      );
      const grade = el('div', 'bosstask-lista');
      for (const task of tasks) grade.append(cardDeTaskDeMontaria(task));
      body.append(grade);
      body.append(el('hr', 'secao-corte'));
      body.append(el('h4', 'bosstask-secao', 'Entregas no balcão'));
    }
  }

  const feitas = lista.filter((entrega) => entrega.feita).length;
  const oQue = tipo === 'mount' ? 'a montaria' : 'a roupa e os addons';
  const contadas = tipo === 'mount' ? 'conquistadas' : 'conquistados';
  body.append(
    el(
      'p',
      'shop-note',
      'Traga o que o bicho larga e leve ' + oQue + '. ' + feitas + ' de ' + lista.length + ' ' + contadas +
        ' — o resto continua à venda na loja, para quem preferir pagar.',
    ),
  );
  if (!lista.length) return void body.append(el('p', 'empty', 'Nada por aqui ainda.'));

  const track = el('div', 'track accent colecao-track');
  const fill = el('i');
  fill.style.width = (lista.length ? (feitas / lista.length) * 100 : 0) + '%';
  track.append(fill);
  body.append(track);

  // ---- o filtro, na gaveta do cabeçalho (o mesmo gesto das Aventuras) ----
  const gaveta = el('div', 'filtro-gaveta');
  gaveta.append(filtroDeEntregas(() => (ctx.redraw ? ctx.redraw() : null)));
  gaveta.hidden = !ctx.tabs.filtroAberto;

  const botao = el('button', 'modal-acao', 'Filtro');
  botao.type = 'button';
  botao.setAttribute('aria-expanded', String(!!ctx.tabs.filtroAberto));
  if (filtroDeEntrega.busca.trim() || filtroDeEntrega.soProntas || filtroDeEntrega.esconderFeitas) {
    botao.append(el('i', 'modal-acao-ponto'));
  }
  botao.onclick = () => {
    ctx.tabs.filtroAberto = !ctx.tabs.filtroAberto;
    gaveta.hidden = !ctx.tabs.filtroAberto;
    botao.setAttribute('aria-expanded', String(!!ctx.tabs.filtroAberto));
    if (ctx.tabs.filtroAberto) gaveta.querySelector('input.search')?.focus();
  };
  /*
   * ---- "Entregar tudo" ----
   *
   * Quem volta de uma caçada longa costuma ter o item de quatro ou cinco passos
   * ao mesmo tempo, e entregar um por um são cinco cliques e cinco
   * confirmações. Este botão faz a varredura de uma vez — e a confirmação dele
   * LISTA o que vai sair e para onde vai, porque uma entrega em lote é
   * justamente a que mais precisa ser conferida antes.
   *
   * Ele só existe quando há o que entregar: um botão permanentemente cinza é um
   * botão que a pessoa aprende a ignorar.
   */
  const acoes = ctx.acoesDoModal?.();
  const prontas = lista.filter((entrega) => entrega.pronta);
  if (prontas.length > 1) {
    const tudo = el('button', 'modal-acao modal-acao-forte', 'Entregar tudo');
    tudo.type = 'button';
    tudo.append(el('i', 'modal-acao-conta', String(prontas.length)));
    tudo.onclick = () => confirmarLote(prontas, send);
    acoes?.append(tudo);
  }
  acoes?.append(botao);
  body.append(gaveta);

  /*
   * ---- Um grupo por PEÇA ----
   *
   * A chave é o nome (o Assassin, o Mage), que é como o servidor já organiza as
   * entregas — a roupa e os dois addons dela apontam para o mesmo 'alvo'. Os
   * passos ficam na ordem em que se conquistam: primeiro a roupa, depois os
   * addons.
   */
  const grupos = new Map();
  for (const entrega of lista) {
    if (!grupos.has(entrega.nome)) grupos.set(entrega.nome, []);
    grupos.get(entrega.nome).push(entrega);
  }
  for (const passos of grupos.values()) passos.sort((a, b) => (a.addon || 0) - (b.addon || 0));

  const combina = (passos) => {
    const termo = semAcento(filtroDeEntrega.busca).trim();
    if (termo) {
      /* Procura pelo nome do outfit e pelo de QUALQUER item que ele peça. */
      const campos = [
        passos[0].nome,
        ...passos.flatMap((p) => (p.itens ?? []).map((i) => i.name)),
        ...passos.flatMap((p) => (p.itens ?? []).flatMap((i) => i.de ?? [])),
      ];
      if (!campos.some((campo) => semAcento(campo).includes(termo))) return false;
    }
    if (filtroDeEntrega.soProntas && !passos.some((p) => p.pronta)) return false;
    if (filtroDeEntrega.esconderFeitas && passos.every((p) => p.feita)) return false;
    return true;
  };

  /*
   * O que dá para entregar AGORA vem primeiro, e o que está completo por
   * último: quem abre esta aba veio entregar.
   */
  const ordenados = [...grupos.values()]
    .filter(combina)
    .sort((a, b) => {
      const pronta = (passos) => (passos.some((p) => p.pronta) ? 0 : passos.every((p) => p.feita) ? 2 : 1);
      return pronta(a) - pronta(b) || String(a[0].nome).localeCompare(String(b[0].nome));
    });

  if (!ordenados.length) {
    return void body.append(el('p', 'empty', 'Nada com esse filtro — abra o Filtro e limpe a busca.'));
  }

  const grade = el('div', 'entrega-grid');
  for (const passos of ordenados) grade.append(cardDeGrupo(passos, send));
  body.append(grade);
}

/*
 * O filtro do balcão. Três controles, e cada um responde a uma pergunta que se
 * faz de verdade nesta tela: "onde está o X?", "o que eu já posso pegar?" e
 * "some com o que eu já tenho".
 */
const filtroDeEntrega = { busca: '', soProntas: false, esconderFeitas: false };

function filtroDeEntregas(aoMudar) {
  const barra = el('div', 'hunt-filtros');

  const busca = document.createElement('input');
  busca.className = 'search';
  busca.type = 'search';
  busca.placeholder = 'peça, item ou bicho...';
  busca.value = filtroDeEntrega.busca;
  busca.oninput = () => {
    filtroDeEntrega.busca = busca.value;
    aoMudar();
  };
  barra.append(busca);

  const marca = (rotulo, campo) => {
    const label = el('label', 'hunt-filtro-check');
    const caixa = document.createElement('input');
    caixa.type = 'checkbox';
    caixa.checked = filtroDeEntrega[campo];
    caixa.onchange = () => {
      filtroDeEntrega[campo] = caixa.checked;
      aoMudar();
    };
    label.append(caixa, el('span', null, rotulo));
    barra.append(label);
  };
  marca('só o que dá para entregar', 'soProntas');
  marca('esconder conquistados', 'esconderFeitas');

  return barra;
}

function cardDeGrupo(passos, send) {
  const cabeca = passos[0];
  const completo = passos.every((p) => p.feita);
  const algumaPronta = passos.some((p) => p.pronta);
  const estado = completo ? ' entrega-feita' : algumaPronta ? ' entrega-pronta' : '';
  const card = el('div', 'entrega-card ui-frame ui-frame--card' + estado);
  const dentro = el('div', 'entrega-dentro');

  // ---- o que você já tem desta peça ----
  const premio = el('div', 'entrega-premio');
  if (outfitInfo(cabeca.look)) {
    /*
     * O boneco grande vem COMPLETO, com os dois addons.
     *
     * Ele já mostrou o que estava conquistado — o que dava, num Assassin sem
     * addon nenhum, exatamente a versão pelada que a pessoa está tentando
     * deixar para trás. O card é uma vitrine: ele existe para dizer "é isto que
     * você leva quando terminar", e quem conta o progresso é o "1 de 2" logo
     * abaixo e os passos ao lado, que já se apagam sozinhos.
     */
    const vestido = cabeca.tipo === 'mount' ? null : { addons: 3 };
    premio.append(outfitCanvas(cabeca.look, vestido, 72));
  }
  premio.append(el('b', null, cabeca.nome));
  premio.append(
    el('em', 'entrega-premio-tipo', passos.filter((p) => p.feita).length + ' de ' + passos.length),
  );

  // ---- os passos ----
  const trilha = el('div', 'entrega-passos');
  for (const passo of passos) trilha.append(linhaDePasso(passo, send));

  dentro.append(premio, trilha);
  card.append(dentro);
  return card;
}

function linhaDePasso(passo, send) {
  const linha = el(
    'div',
    'entrega-passo' + (passo.feita ? ' passo-feito' : passo.pronta ? ' passo-pronto' : ''),
  );

  /*
   * A sprite DAQUELE passo: a roupa com aquele addon aceso, e só ele. É o que
   * responde "o que este addon muda?" sem a pessoa precisar conquistá-lo antes
   * de descobrir.
   *
   * A MONTARIA não repete: ela tem um passo só, e o desenho dele seria idêntico
   * ao boneco grande ao lado — duas cópias da mesma coisa, uma do lado da
   * outra, espremendo o nome do item até ele quebrar no meio da palavra.
   */
  if (passo.tipo !== 'mount' && outfitInfo(passo.look)) {
    linha.append(outfitCanvas(passo.look, { addons: passo.addon || 3 }, 44));
  }

  const meio = el('div', 'entrega-passo-meio');
  meio.append(el('b', null, passo.premio));

  /*
   * ---- A GRADE de itens ----
   *
   * O balcão pedia um item por entrega, e a linha tinha um ícone com "3 / 10".
   * Com os dados do NPC Addoner são até TREZE por addon (o addon 1 do Mage
   * pede as dez varinhas, magic sulphur, ankh e uma soul stone), e treze linhas
   * empilhadas fariam um card de meia tela.
   *
   * Então eles viram uma grade de ícones. Cada um traz o quanto falta e, no
   * balão, de quem cai — é ali que mora a resposta de "onde eu consigo isso",
   * que com um item só cabia numa frase embaixo.
   */
  const grade = el('div', 'entrega-itens');
  for (const pedido of passo.itens ?? []) {
    /*
     * `item-guardado`: já saiu da mochila e está no balcão, mas ainda falta.
     * Sem essa marca, quem adiantou 20 de 50 veria a mesma cela de quem tem os
     * 20 na mochila — e as duas coisas pedem gestos diferentes.
     */
    const guardado = pedido.entregue > 0 && pedido.falta > 0;
    const cela = el(
      'div',
      'entrega-item'
        + (pedido.falta > 0 ? '' : ' item-ok')
        + (guardado ? ' item-guardado' : '')
        + (pedido.semFonte ? ' item-sem-fonte' : ''),
    );
    const arte = itemCanvas(pedido.id, 26);
    if (arte) cela.append(arte);
    /* Sem espaço em volta da barra: a cela tem 58px, e "0 / 50" não cabia. */
    cela.append(el('b', null, pedido.tem + '/' + pedido.count));
    tipTexto(
      cela,
      `${pedido.count}× ${pedido.name}`
        + (pedido.entregue > 0 ? ` — ${pedido.entregue} já no balcão` : '')
        + (pedido.semFonte
          /*
           * A verdade, e não um silêncio. Hoje nenhum item do balcão está
           * nesta situação — os 23 que não caíam de ninguém ganharam fonte em
           * `loot-de-entrega.mjs` —, e a frase fica para o próximo que entrar
           * sem ter de onde cair.
           */
          ? ' — ainda não cai de nenhum bicho das hunts'
          : `
larga de ${pedido.de.join(', ')}`),
    );
    grade.append(cela);
  }
  if (passo.ouro > 0) {
    const cela = el('div', 'entrega-item entrega-ouro' + (passo.temOuro >= passo.ouro ? ' item-ok' : ''));
    cela.append(el('b', null, money(passo.ouro)));
    cela.append(el('span', null, 'ouro'));
    tipTexto(cela, `${money(passo.ouro)} de ouro — você tem ${money(passo.temOuro)}`);
    grade.append(cela);
  }
  /*
   * A grade sai do MEIO e vira filha do passo.
   *
   * Dentro do meio ela dividia a coluna do meio com o botão e o boneco, e
   * sobravam 111px — uma cela por fileira, medido. Como filha do passo ela
   * ocupa a fileira de baixo inteira (ver `.entrega-passo` no CSS) e o botão
   * sobe para o lado do título, que é curto.
   */
  linha.append(meio);

  /*
   * ---- Dois gestos no mesmo botão ----
   *
   * "Entregar" quando a conta fecha e a peça sai; "Adiantar" quando só dá para
   * deixar no balcão o que já se tem. A palavra muda porque o resultado muda —
   * um botão escrito "Entregar" que não entrega nada é uma promessa quebrada.
   *
   * Antes ele ficava cinza até o último item chegar. Numa entrega de treze
   * itens de treze bichos, isso queria dizer carregar tudo até o fim.
   */
  const podeAdiantar = !passo.pronta && !!passo.podeAdiantar;
  const botao = el(
    'button',
    passo.pronta ? 'primary' : podeAdiantar ? 'ghost entrega-adiantar' : 'ghost',
    passo.feita ? '✓' : passo.pronta ? 'Entregar' : 'Adiantar',
  );
  botao.disabled = passo.feita || (!passo.pronta && !podeAdiantar);
  if (!passo.feita && podeAdiantar) {
    tipTexto(botao, 'Deixa no balcão o que você já tem. O resto continua faltando, e a peça só sai quando a conta fechar.');
  }
  botao.onclick = () => confirmarEntrega(passo, () => send({ t: 'entrega', id: passo.id }));
  linha.append(botao);
  linha.append(grade);
  return linha;
}

/*
 * ---- A confirmação da entrega ----
 *
 * Entregar CONSOME os itens da mochila, e é um gesto sem volta: quem clicou por
 * engano com 20 honeycombs na bolsa não tem como desfazer. Por isso a pergunta.
 *
 * E por isso mesmo ela tem o "não perguntar de novo": quem está no meio de dez
 * entregas seguidas já sabe o que o botão faz, e uma pergunta repetida deixa de
 * ser proteção e vira ruído — a pessoa aprende a clicar em "confirmar" sem ler,
 * que é exatamente o estado em que a próxima confirmação não protege mais nada.
 *
 * A escolha vale a SESSÃO, e não para sempre: ela mora em 'ctx.tabs', que morre
 * quando a aba fecha. Uma decisão tomada no meio de uma sequência de entregas
 * não deveria valer para a sequência de daqui a um mês.
 */
function confirmarEntrega(passo, aoConfirmar) {
  if (ctx.tabs.entregaSemPerguntar) return void aoConfirmar();

  /*
   * Uma caixa POR CIMA, e não um modal.
   *
   * A janela de Tarefas já é o '#modal'; abrir a confirmação com 'openModal'
   * substituiria o conteúdo dela, e confirmar fecharia a janela inteira — a
   * pessoa terminaria a entrega olhando para o mapa. Esta é a mesma caixa
   * flutuante da compra da loja ('confirmPurchase'), pelo mesmo motivo.
   */
  const back = el('div', 'confirm-back');
  /* Mais larga que a de compra: aqui cabem os dois lados da troca e a grade. */
  const box = el('div', 'confirm-box confirm-largo');

  /* Adiantar e entregar são gestos diferentes, e a caixa diz qual é. */
  const fecha = !!passo.pronta;
  box.append(el('h3', null, fecha ? 'Confirmar entrega' : 'Adiantar o que você tem'));

  const resumo = el('div', 'entrega-confirma');

  const oQueVai = el('div', 'entrega-confirma-lado');
  /* Todos os itens, e não o primeiro: é um gesto sem volta, e o que some tem
     de estar inteiro na tela antes do clique. */
  const saindo = el('div', 'entrega-itens');
  for (const pedido of passo.itens ?? []) {
    const cela = el('div', 'entrega-item');
    const arte = itemCanvas(pedido.id, 26);
    if (arte) cela.append(arte);
    cela.append(el('b', null, pedido.count + '×'));
    tipTexto(cela, `${pedido.count}× ${pedido.name}`);
    saindo.append(cela);
  }
  oQueVai.append(saindo);
  if (passo.ouro > 0) oQueVai.append(el('b', null, money(passo.ouro) + ' de ouro'));
  oQueVai.append(el('em', null, 'sai da sua mochila'));

  const oQueVem = el('div', 'entrega-confirma-lado');
  if (outfitInfo(passo.look)) {
    const vestido = passo.tipo === 'mount' ? null : { addons: passo.addon || 3 };
    oQueVem.append(outfitCanvas(passo.look, vestido, 48));
  }
  oQueVem.append(el('b', null, passo.nome));
  oQueVem.append(el('em', null, passo.premio));

  resumo.append(oQueVai, el('div', 'entrega-confirma-seta', '→'), oQueVem);
  box.append(resumo);
  box.append(
    el(
      'p',
      'shop-note',
      fecha
        ? 'Os itens somem da mochila e a peça fica sua para sempre. Não tem volta.'
        : 'O que você tem sai da mochila e fica guardado nesta entrega. A peça só sai quando a conta fechar — e o que for guardado não volta.',
    ),
  );

  const naoPerguntar = el('label', 'hunt-filtro-check');
  const caixa = document.createElement('input');
  caixa.type = 'checkbox';
  naoPerguntar.append(caixa, el('span', null, 'não perguntar de novo nesta sessão'));

  /*
   * `confirm-actions` JUNTO, e não só a classe própria.
   *
   * O estilo dos botões de confirmação mora em `.confirm-actions button`. Esta
   * caixa tinha só a classe dela, então "Confirmar" saía com o botão cru do
   * navegador — branco, no meio de uma janela escura, parecendo desabilitado.
   * Era o "o confirmar está branco". O "Entregar tudo" tinha o mesmo defeito.
   */
  const acoes = el('div', 'confirm-actions entrega-confirma-acoes');
  const cancelar = el('button', 'ghost', 'Cancelar');
  cancelar.onclick = () => back.remove();
  const confirmar = el('button', null, fecha ? 'Confirmar' : 'Adiantar');
  confirmar.onclick = () => {
    if (caixa.checked) ctx.tabs.entregaSemPerguntar = true;
    back.remove();
    aoConfirmar();
  };
  acoes.append(naoPerguntar, cancelar, confirmar);
  box.append(acoes);

  back.append(box);
  fecharAoClicarFora(back, () => back.remove());
  // Enter confirma, Escape desiste — como em toda caixa de confirmar do jogo.
  atalhosDaCaixa(back, { confirmar: () => confirmar.click(), fechar: () => back.remove() });
  document.body.append(back);
  confirmar.focus();
}

/*
 * ---- A confirmação do LOTE ----
 *
 * Ela lista o que vai sair e para onde vai, peça por peça. Uma entrega em lote
 * consome o item de cinco passos de uma vez, e o "não perguntar de novo" da
 * entrega avulsa NÃO vale aqui: aquele atalho foi tomado sobre uma decisão de
 * um item só, e estendê-lo a cinco seria usar um consentimento para uma coisa
 * maior do que ele foi dado.
 */
function confirmarLote(prontas, send) {
  const back = el('div', 'confirm-back');
  const box = el('div', 'confirm-box confirm-lote');

  box.append(el('h3', null, 'Entregar tudo'));
  box.append(
    el('p', 'shop-note', prontas.length + ' entregas de uma vez. Confira antes: os itens somem da mochila.'),
  );

  const lista = el('div', 'lote-lista');
  for (const passo of prontas) {
    const linha = el('div', 'lote-linha');

    const item = el('div', 'lote-item');
    for (const pedido of passo.itens ?? []) {
      const arte = itemCanvas(pedido.id, 22);
      if (arte) item.append(arte);
      item.append(el('b', null, pedido.count + '×'));
    }
    if (passo.ouro > 0) item.append(el('b', null, money(passo.ouro) + ' oz'));
    linha.append(item);

    linha.append(el('div', 'lote-seta', '→'));

    const premio = el('div', 'lote-premio');
    if (outfitInfo(passo.look)) {
      const vestido = passo.tipo === 'mount' ? null : { addons: passo.addon || 3 };
      premio.append(outfitCanvas(passo.look, vestido, 32));
    }
    const texto = el('div', 'lote-premio-texto');
    texto.append(el('b', null, passo.nome));
    texto.append(el('em', null, passo.premio));
    premio.append(texto);
    linha.append(premio);

    lista.append(linha);
  }
  box.append(lista);

  const acoes = el('div', 'confirm-actions entrega-confirma-acoes');
  const cancelar = el('button', 'ghost', 'Cancelar');
  cancelar.onclick = () => back.remove();
  const confirmar = el('button', null, 'Entregar ' + prontas.length);
  confirmar.onclick = () => {
    back.remove();
    // Uma mensagem por entrega: o servidor confere cada uma por conta própria,
    // e uma que falhar não leva as outras junto.
    for (const passo of prontas) send({ t: 'entrega', id: passo.id });
  };
  acoes.append(cancelar, confirmar);
  box.append(acoes);

  back.append(box);
  fecharAoClicarFora(back, () => back.remove());
  atalhosDaCaixa(back, { confirmar: () => confirmar.click(), fechar: () => back.remove() });
  document.body.append(back);
  confirmar.focus();
}

/*
 * Filtro de loot.
 *
 * Duas regras por item: não coletar (nem entra na bolsa) e não vender (fica na
 * bolsa quando a venda passa). Antes eram duas listas soltas dentro da janela
 * da bolsa, onde só cabia o que já tinha caído. Aqui elas aparecem ao lado do
 * loot da hunt em que o personagem está — ou de todas as hunts da roda, se for
 * ciclo —, então dá para marcar o que ainda nem caiu.
 */
/*
 * Limpar a bolsa: joga o loot todo fora de uma vez.
 *
 * Existe para o caso em que a auto-venda está desligada e a bolsa encheu de
 * coisa que ninguém compra — com o teto de tipos batido, o loot bom começa a
 * ficar no chão por falta de vaga. Tirar item por item pelo menu de contexto
 * eram vinte cliques.
 *
 * Como não tem volta, ele passa por aqui antes: a tela mostra exatamente o que
 * vai sumir, com quanto valeria na venda rápida, e o jogador clica no que quer
 * salvar. Sai marcado como "fora" por padrão porque foi isso que ele pediu ao
 * abrir a tela — o trabalho é de quem quer guardar, não de quem quer limpar.
 */
export function openLimparBolsa() {
  const { state, send } = ctx;
  // Fora do `desenhar`: redesenhar a lista a cada clique não pode perder o que
  // já foi salvo.
  const guardados = new Set();

  ctx.openModal('Limpar a bolsa', (body) => {
    const desenhar = () => {
      body.innerHTML = '';
      const bolsa = state.character.pouch ?? [];

      if (!bolsa.length) {
        body.append(el('p', 'gate-note', 'A bolsa já está vazia.'));
        const acoes = el('div', 'confirm-actions');
        const fechar = el('button', 'ghost', 'Fechar');
        fechar.onclick = () => ctx.closeModal();
        acoes.append(fechar);
        body.append(acoes);
        return;
      }

      // Preço unitário da venda rápida, que o servidor já calcula para o rodapé
      // da bolsa. Sem ele o jogador não tem como saber o que está jogando fora.
      const unitario = new Map((state.character.pouchValue?.lines ?? []).map((linha) => [linha.id, linha.unit]));

      body.append(
        el('p', 'shop-note', 'Isto destrói o que estiver marcado em vermelho, e não tem volta. Clique num item para guardá-lo.')
      );

      /*
       * ---- Uma célula por PEÇA quando a peça tem o que mostrar ----
       *
       * O mesmo trato do "Limpar a mochila", e pela mesma razão — ver a nota
       * longa lá. Em resumo: agrupar por id junta num quadradinho só a wand ★★★
       * e a wand limpa do mesmo id, e a tela passa a esconder justamente o que
       * decide se a peça fica ou vai.
       *
       * A bolsa até tem mais motivo para isso do que a mochila: é aqui que o
       * loot cai, e afixo é coisa de loot.
       */
      const assinaturaDaPeca = (entry) =>
        [
          entry.tier ?? 0,
          (entry.af ?? []).map((a) => (typeof a === 'string' ? a : a?.id ?? a?.key ?? JSON.stringify(a))).join('+'),
          (entry.imbu ?? []).map((i) => (typeof i === 'string' ? i : i?.id ?? i?.key ?? JSON.stringify(i))).join('+'),
          entry.carga ?? '',
        ].join('|');

      const grupos = [];
      const juntas = new Map();
      for (let i = 0; i < bolsa.length; i++) {
        const entry = bolsa[i];
        const propria = !!(entry.af?.length || entry.tier || entry.imbu?.length || entry.carga != null);

        if (!propria) {
          const igual = juntas.get(entry.id);
          if (igual) {
            igual.count += entry.count ?? 1;
            igual.indices.push(i);
            continue;
          }
        }

        const grupo = {
          chave: propria ? `${i}|${entry.id}|${assinaturaDaPeca(entry)}` : `id|${entry.id}`,
          entry,
          count: entry.count ?? 1,
          indices: [i],
        };
        grupos.push(grupo);
        if (!propria) juntas.set(entry.id, grupo);
      }

      const grade = el('div', 'filter-grid');
      let pilhasFora = 0;
      let unidadesFora = 0;
      let ouroFora = 0;
      const fora = [];

      for (const grupo of grupos) {
        const fica = guardados.has(grupo.chave);
        // A peça INTEIRA: é ela que carrega as estrelas e o selo do tier.
        const cell = itemCell({ ...grupo.entry, count: grupo.count }, 'filter');
        cell.classList.add(fica ? 'protected' : 'barred');
        const unidade = unitario.get(grupo.entry.id) ?? 0;
        tipFor(
          cell,
          grupo.entry.id,
          [
            `${money(grupo.count)} unidade(s)`,
            unidade ? `${money(unidade * grupo.count)} gold na venda rápida` : 'nenhum NPC compra',
            fica ? 'FICA na bolsa' : 'vai fora',
          ].join(' — '),
          null,
          grupo.entry
        );
        cell.onclick = () => {
          if (fica) guardados.delete(grupo.chave);
          else guardados.add(grupo.chave);
          desenhar();
        };
        grade.append(cell);

        if (fica) continue;
        pilhasFora++;
        unidadesFora += grupo.count;
        ouroFora += unidade * grupo.count;
        for (const i of grupo.indices) fora.push({ i, id: grupo.entry.id });
      }
      body.append(grade);

      const resumo = el('p', 'gate-note');
      resumo.textContent = pilhasFora
        ? `Vão fora ${money(unidadesFora)} item(ns) em ${pilhasFora} ${pilhasFora === 1 ? 'quadradinho' : 'quadradinhos'}` +
          (ouroFora ? ` — ${money(ouroFora)} gold que a venda rápida pagaria.` : '.')
        : 'Nada marcado para jogar fora.';
      body.append(resumo);

      const acoes = el('div', 'confirm-actions');
      const cancelar = el('button', 'ghost', 'Cancelar');
      cancelar.onclick = () => ctx.closeModal();
      const limpar = el('button', 'danger', 'Jogar fora');
      limpar.disabled = !pilhasFora;
      limpar.onclick = () => {
        send({ t: 'clearPouch', fora });
        ctx.closeModal();
      };
      acoes.append(cancelar, limpar);
      body.append(acoes);
    };

    ctx.redraw = desenhar;
    desenhar();
  });
}

/*
 * ---- Limpar a MOCHILA ----
 *
 * "coloca um botão Limpar na mochila igual tem na bolsa de loot, que a pessoa
 * pode limpar a mochila completa, mas ela escolhe o que limpar e tem que ter
 * confirmação dupla."
 *
 * A razão de ele existir: uma mochila de vinte vagas cheia de lixo de caçada
 * não se esvazia item a item.
 *
 * ---- A tela começa VAZIA, e isso é uma correção ----
 *
 * Ela nasceu copiando a "Limpar" da bolsa de loot: tudo já vinha marcado em
 * vermelho para sair, e clicar num item o SALVAVA. O dono mandou inverter:
 *
 *   "o botão limpar da mochila a princípio tem que estar tudo DESSELECIONADO,
 *    e quando a pessoa selecionar o que quer limpar vai aparecer a confirmação
 *    e tudo que será perdido, e informa que não tem volta"
 *
 * Ele está certo, e a razão é que as duas telas não correm o mesmo risco. A
 * bolsa de loot é uma fila de coisas que já iam ser vendidas sozinhas. A
 * mochila é onde mora o equipamento: a peça ★★★ que acabou de cair, a arma de
 * exercise de 15kk, a pedra de tier.
 *
 * Com o padrão invertido, o gesto errado tinha o pior desfecho possível — abrir
 * por curiosidade e apertar o botão vermelho destruía a mochila inteira. O
 * padrão de uma tela que não tem volta tem de ser NÃO FAZER NADA.
 *
 * É também o mesmo gesto da irmã dela, a de vender (`openVenderMochila`), que
 * já nascia vazia pelo mesmo motivo: clicar marca o que SAI, nas duas. Antes
 * as duas telas eram iguais de aparência e opostas de significado.
 *
 * ---- E o que a inversão custou, devolvido em outro lugar ----
 *
 * "Tudo marcado" fazia a limpeza comum — a mochila de sucata — em um clique.
 * Isso volta como o botão "Marcar tudo", igual ao da tela de vender, e ele
 * pega SÓ o que não tem estrela, tier nem imbuement: a proteção que antes vinha
 * da marca inicial continua existindo, agora no botão que marca em massa.
 *
 * A confirmação passou a ser SEMPRE, e ela LISTA peça por peça o que vai
 * embora — ver `confirmarLimpezaDaMochila`.
 */
/*
 * ---- Vender da mochila, escolhendo o que sai ----
 *
 * "criar um botão na mochila ao lado de limpar que seria vender, que ao clicar
 * abre um modal com os itens pra vender pro npc — igual na loot pouch só que
 * manual."
 *
 * Ela é a irmã do `openLimparMochila`, e de propósito: mesma grade, mesmo
 * clique para marcar, mesmo lugar. As duas respondem à mochila cheia, uma
 * destruindo e a outra trocando por ouro, e quem já sabe usar uma sabe usar a
 * outra sem aprender nada.
 *
 * ---- O que muda em relação ao Limpar ----
 *
 * Aqui NADA vem marcado. No Limpar o padrão é jogar fora e a marca salva; se
 * essa mesma inversão valesse aqui, abrir a tela por curiosidade e apertar o
 * botão venderia a mochila inteira. Vender é escolha, e a escolha começa vazia.
 *
 * E as células que não dão para vender aparecem, apagadas, com o motivo no
 * balão. Esconder o que foi recusado faria a tela mentir por omissão: o jogador
 * procuraria a peça, não a acharia, e não saberia por quê.
 *
 * ---- A lista vem do SERVIDOR ----
 *
 * Preço, motivo e índice saem de `previaDaVendaDaMochila`. Montar a mesma
 * régua aqui seria ter duas, e no dia em que uma mudasse a tela prometeria
 * vender o que a venda recusa. Ver o `case 'venderMochila'`, no main.mjs.
 */
/*
 * `lugar` é 'bag' (a mochila) ou 'pouch' (a bolsa de loot). O dono pediu o
 * botão na bolsa "igual o da mochila", e é literalmente a mesma tela: mesma
 * grade, mesmo marcar tudo, mesma segunda confirmação para peça com tier.
 */
export function openVenderMochila(lugar = 'bag') {
  const { state, send } = ctx;
  const daBolsa = lugar === 'pouch';
  const onde = daBolsa ? 'na bolsa' : 'na mochila';
  // Fora do `desenhar`: o redesenho a cada clique não pode perder a escolha.
  const marcadas = new Set();

  // A prévia antiga pode ser da OUTRA lista: some antes de pedir a nova.
  state.vendaDaMochila = null;
  // Pede a prévia agora; a resposta chega pelo websocket e redesenha.
  send(daBolsa ? { t: 'venderMochila', lugar } : { t: 'venderMochila' });

  ctx.openModal(daBolsa ? 'Vender a bolsa de loot para o NPC' : 'Vender para o NPC', (body) => {
    const desenhar = () => {
      body.innerHTML = '';
      const previa = state.vendaDaMochila?.lugar === lugar ? state.vendaDaMochila : null;

      if (!previa) {
        body.append(el('p', 'gate-note', 'Consultando os preços do NPC...'));
        return;
      }
      if (!previa.linhas.length) {
        body.append(el('p', 'gate-note', daBolsa ? 'A bolsa de loot está vazia.' : 'A mochila está vazia.'));
        const acoes = el('div', 'confirm-actions');
        const fechar = el('button', 'ghost', 'Fechar');
        fechar.onclick = () => ctx.closeModal();
        acoes.append(fechar);
        body.append(acoes);
        return;
      }

      // O que "marcar tudo" pega: TUDO o que o NPC compra, com ou sem atributo/raridade (decisão do
      // dono, 29/09: nada trava por causa da raridade). A peça com tier, imbuement ou estrela entra
      // na seleção, e a proteção que sobra é a confirmação da venda, que a LISTA em vermelho.
      const podem = previa.linhas.filter((linha) => !linha.motivo);
      const comAviso = previa.linhas.filter((linha) => !linha.motivo && linha.aviso);
      const recusadas = previa.linhas.filter((linha) => linha.motivo);

      body.append(
        el(
          'p',
          'shop-note',
          daBolsa
            ? 'Clique nos itens que você quer vender. O NPC paga o preço cheio — a venda automática da bolsa cobra desconto porque vende sozinha.'
            : 'Clique nos itens que você quer vender. O NPC paga o preço cheio — a bolsa de loot cobra desconto porque vende sozinha.'
        )
      );

      /*
       * A chave da escolha carrega o índice E o id, como no Limpar: a mochila
       * pode mexer embaixo da janela (loot entrando, venda automática saindo), e
       * um índice que escorregou deixa de bater. O erro cai para o lado seguro —
       * a peça sai da seleção — e o servidor confere o id de novo antes de tirar.
       */
      const grade = el('div', 'filter-grid venda-grade rolagem');
      for (const linha of previa.linhas) {
        const marcada = marcadas.has(linha.i);
        const cell = itemCell({ ...linha, count: linha.count }, 'filter');

        /*
         * ---- O preço vai EMBAIXO de cada quadradinho ----
         *
         * Pedido do dono: "embaixo de cada item mostrar o valor". Antes ele só
         * existia no balão, e balão é uma coisa que se lê um de cada vez — não
         * dá para comparar trinta peças passando o mouse por todas elas. Aqui a
         * escolha é ordenar por valor com o olho, e para isso o número tem de
         * estar na grade.
         *
         * O número é o da PILHA, e não o da unidade: é ele que entra no total do
         * botão, e mostrar o unitário faria as contas do jogador não baterem com
         * a soma. Quando a pilha tem mais de um, o unitário vai no balão.
         */
        const caixa = el('div', 'venda-item');
        const preco = el('span', 'venda-preco', linha.motivo ? '—' : `${money(linha.total)}g`);
        caixa.append(cell, preco);

        if (linha.motivo) {
          cell.classList.add('venda-travada');
          caixa.classList.add('travada');
          tipTexto(cell, `Não dá para vender aqui: ${linha.motivo}.`);
          grade.append(caixa);
          continue;
        }

        /*
         * ---- A peça com tier, imbuement ou estrela: apagada, mas clicável ----
         *
         * "tem que estar desmarcado por padrao, mas se a pessoa marcar podera
         * ser vendido, so que ai tinha que ser dupla confirmacao".
         *
         * Ela nasce fora da seleção e continua apagada enquanto estiver fora —
         * é o mesmo desenho de antes, quando ela era intocável. O que mudou é
         * que o clique agora funciona; e marcada, ela acende de VERMELHO, que é
         * a única cor da tela que quer dizer "isto não volta".
         */
        if (linha.aviso) {
          caixa.classList.add('com-aviso');
          tipTexto(
            cell,
            marcada
              ? `VAI SER VENDIDA mesmo tendo ${linha.aviso}. A tela vai perguntar de novo antes.`
              : `Esta peça tem ${linha.aviso}. O "marcar tudo" a marca, e a tela pergunta de novo antes de vender.`
          );
        }

        cell.classList.add(marcada ? 'barred' : 'protected');
        if (marcada) caixa.classList.add('marcada');
        cell.title =
          `${money(linha.count)}x — ${marcada ? 'VAI SER VENDIDA' : `fica ${onde}`}` +
          (linha.count > 1 ? ` (${money(linha.unidade)}g cada, ${money(linha.total)}g a pilha)` : ` (${money(linha.total)}g)`);
        caixa.onclick = () => {
          if (marcada) marcadas.delete(linha.i);
          else marcadas.add(linha.i);
          desenhar();
        };
        grade.append(caixa);
      }
      body.append(grade);

      if (comAviso.length) {
        body.append(
          el(
            'em',
            'filter-legend',
            `${comAviso.length} ${comAviso.length === 1 ? 'peça tem' : 'peças têm'} tier, imbuement ou estrela. ` +
              'O "marcar tudo" as marca também — e, se saírem, a tela pergunta de novo antes de vender.'
          )
        );
      }
      if (recusadas.length) {
        body.append(
          el(
            'em',
            'filter-legend',
            `${recusadas.length} ${recusadas.length === 1 ? 'peça está travada' : 'peças estão travadas'}: ` +
              'nenhum NPC compra, ou você marcou como "não vender". Essa marca só sai pelo menu do item.'
          )
        );
      }

      const escolhidas = previa.linhas.filter((linha) => !linha.motivo && marcadas.has(linha.i));
      const valiosasEscolhidas = escolhidas.filter((linha) => linha.aviso);
      const ouro = escolhidas.reduce((soma, linha) => soma + linha.total, 0);
      const pecas = escolhidas.reduce((soma, linha) => soma + linha.count, 0);

      const resumo = el('p', 'gate-note');
      resumo.textContent = escolhidas.length
        ? `${money(pecas)} item(ns) em ${escolhidas.length} ${escolhidas.length === 1 ? 'quadradinho' : 'quadradinhos'} — ${money(ouro)} gold.`
        : `Nada marcado. Há ${money(podem.length)} ${podem.length === 1 ? 'quadradinho' : 'quadradinhos'} que o NPC compra, somando ${money(previa.total)} gold.`;
      body.append(resumo);

      const acoes = el('div', 'confirm-actions');
      const fechar = el('button', 'ghost', 'Fechar');
      fechar.onclick = () => ctx.closeModal();

      /*
       * Marcar tudo o que dá, num clique. É o gesto mais comum depois de uma
       * caçada — a mochila cheia de sucata — e sem ele a tela pediria trinta
       * cliques para fazer o que a bolsa faz sozinha.
       */
      /*
       * "Marcar tudo" pega TUDO o que o NPC compra (inclusive peça com atributo). A conta olha
       * quantas das `podem` estão marcadas, e não o tamanho da seleção inteira.
       */
      const limpasMarcadas = podem.filter((linha) => marcadas.has(linha.i)).length;
      const todasLimpas = podem.length > 0 && limpasMarcadas === podem.length;
      const tudo = el('button', 'ghost', todasLimpas ? 'Desmarcar tudo' : 'Marcar tudo');
      tudo.disabled = !podem.length;
      tudo.onclick = () => {
        if (todasLimpas) for (const linha of podem) marcadas.delete(linha.i);
        else for (const linha of podem) marcadas.add(linha.i);
        desenhar();
      };

      const vender = el('button', valiosasEscolhidas.length ? 'danger' : 'primary', escolhidas.length ? `Vender por ${money(ouro)}g` : 'Vender');
      vender.disabled = !escolhidas.length;
      /*
       * ---- A segunda confirmação, e só quando ela faz falta ----
       *
       * Uma caixa de "tem certeza?" em toda venda de sucata vira um clique
       * automático em duas semanas, e aí ela não protege mais nada. Ela aparece
       * exatamente no caso que o dono descreveu: alguma peça com tier,
       * imbuement ou estrela na seleção.
       *
       * E o `mesmoAssim` viaja SÓ nessas linhas. O servidor recusa em silêncio
       * uma peça com aviso que chegue sem a marca — ver `venderDaMochila`.
       */
      const mandar = () => {
        send({
          t: 'venderMochila',
          ...(daBolsa ? { lugar } : {}),
          vender: escolhidas.map((linha) => ({
            i: linha.i,
            id: linha.id,
            ...(linha.aviso ? { mesmoAssim: true } : {}),
          })),
        });
        marcadas.clear();
      };
      /*
       * A confirmação é SEMPRE, e não só quando há peça cara na seleção.
       *
       * "o mesmo você faz pro botão de vender na mochila" — a mesma regra que
       * ele pediu para o Limpar. A objeção antiga (uma caixa em toda venda de
       * sucata vira clique automático) valia quando a caixa só repetia um
       * número; esta LISTA o que sai, e uma lista se lê.
       *
       * Vender também não tem volta: o NPC não devolve, e não paga por tier,
       * imbuement nem estrela.
       */
      vender.onclick = () => confirmarVendaDaMochila(escolhidas, valiosasEscolhidas, ouro, mandar);

      acoes.append(fechar, tudo, vender);
      body.append(acoes);
    };
    ctx.redraw = desenhar;
    desenhar();
  });
}

/*
 * ---- VENDER O QUE ESTÁ NAS SACOLAS DE BOSS ----
 *
 * Pedido do dono: "poderia ter um jeito de vender os drops de boss mais rápido.
 * Do mesmo jeito que tem um botão pra jogar fora, poderia ter um pra vender, lá
 * em depósito na aba de recompensa de boss, ao lado de 'pegar tudo': um botão
 * 'vender tudo que NPC compra', que seria igual o sistema de vender da mochila —
 * aí ele vê o que tem em todas as bolsas de loot de boss, mostra o que seria
 * vendido e quanto de gold vai dar, e botão de confirmar."
 *
 * Ela é a irmã de `openVenderMochila`, e de propósito: mesma grade, mesmo clique
 * para marcar, mesma segunda confirmação. Quem já sabe usar uma sabe usar a
 * outra sem aprender nada.
 *
 * ---- O caminho que existia era o pior possível ----
 *
 * Pegar sacola por sacola para a mochila, e vender da mochila. Quem faz todos os
 * bosses do dia volta com trinta sacolas — e a mochila não tem vaga nem
 * capacidade para trinta sacolas de uma vez, então virava um vaivém de pegar,
 * vender, pegar, vender. Aqui nada passa pela mochila: sai da sacola direto para
 * o NPC.
 *
 * ---- As DUAS diferenças em relação à venda da mochila, e as duas vêm do pedido ----
 *
 * 1. Aqui as peças limpas JÁ NASCEM MARCADAS. Na mochila nada nasce marcado
 *    ("vender é escolha, e a escolha começa vazia"); aqui o botão se chama
 *    "vender tudo que o NPC compra", e uma tela que abrisse vazia mentiria
 *    sobre o que o botão promete.
 *
 *    O que NÃO nasce marcado continua sendo o mesmo: tier, imbuement e afixo.
 *    Essa regra é do dono e é anterior a esta tela — "os itens com imbuiments,
 *    tier ou afixo tem que estar desmarcado por padrao, mas se a pessoa marcar
 *    podera ser vendidos, so que ai tinha que ser dupla confirmacao" — e ela
 *    vale aqui inteira.
 *
 * 2. O endereço de cada peça tem DUAS partes: em qual sacola e em que lugar
 *    dentro dela. O baú é uma lista de listas, e um índice só não a endereça.
 */
export function openVenderSacolas() {
  const { state, send } = ctx;
  // Fora do `desenhar`: o redesenho a cada clique não pode perder a escolha.
  const marcadas = new Set();
  /* A primeira prévia marca o que dá; depois disso a escolha é do jogador. */
  let jaMarcou = false;

  const chaveDe = (linha) => `${linha.sacola}:${linha.i}`;

  // Pede a prévia agora; a resposta chega pelo websocket e redesenha.
  send({ t: 'venderSacolas' });

  ctx.openModal('Vender o baú para o NPC', (body) => {
    const desenhar = () => {
      body.innerHTML = '';
      const previa = state.vendaDasSacolas;

      if (!previa) {
        body.append(el('p', 'gate-note', 'Consultando os preços do NPC...'));
        return;
      }
      if (!previa.linhas.length) {
        body.append(el('p', 'gate-note', 'Não há nada nas sacolas de boss.'));
        const acoes = el('div', 'confirm-actions');
        const fechar = el('button', 'ghost', 'Fechar');
        fechar.onclick = () => ctx.closeModal();
        acoes.append(fechar);
        body.append(acoes);
        return;
      }

      const podem = previa.linhas.filter((linha) => !linha.motivo && !linha.aviso);
      const comAviso = previa.linhas.filter((linha) => !linha.motivo && linha.aviso);
      const recusadas = previa.linhas.filter((linha) => linha.motivo);

      /* A marca inicial: tudo o que o NPC compra e que não tem aviso. */
      if (!jaMarcou) {
        jaMarcou = true;
        for (const linha of podem) marcadas.add(chaveDe(linha));
      }

      body.append(
        el(
          'p',
          'shop-note',
          `O que está nas ${previa.sacolas} sacola(s) de boss, junto. O NPC paga o preço cheio. ` +
            'Clique para tirar da venda o que você quer guardar.'
        )
      );

      const grade = el('div', 'filter-grid venda-grade rolagem');
      for (const linha of previa.linhas) {
        const chave = chaveDe(linha);
        const marcada = marcadas.has(chave);
        const cell = itemCell({ ...linha, count: linha.count }, 'filter');

        const caixa = el('div', 'venda-item');
        const preco = el('span', 'venda-preco', linha.motivo ? '—' : `${money(linha.total)}g`);
        caixa.append(cell, preco);

        if (linha.motivo) {
          cell.classList.add('venda-travada');
          caixa.classList.add('travada');
          tipTexto(cell, `Não dá para vender: ${linha.motivo}. Ela fica no baú.`);
          grade.append(caixa);
          continue;
        }

        /*
         * A peça com tier, imbuement ou estrela: apagada, mas clicável. Marcada,
         * ela acende de vermelho — a única cor da tela que quer dizer "isto não
         * volta". Ver a nota inteira em `openVenderMochila`.
         */
        if (linha.aviso) {
          caixa.classList.add('com-aviso');
          if (!marcada) cell.classList.add('venda-travada');
          tipTexto(
            cell,
            marcada
              ? `VAI SER VENDIDA mesmo tendo ${linha.aviso}. A tela vai perguntar de novo antes.`
              : `Esta peça ${linha.aviso}. Ela nasce fora da venda — clique para vender assim mesmo.`
          );
        }

        cell.classList.add(marcada ? 'barred' : 'protected');
        if (marcada) caixa.classList.add('marcada');
        cell.title =
          `${money(linha.count)}x — ${marcada ? 'VAI SER VENDIDA' : 'fica no baú'} · sacola de ${linha.boss}` +
          (linha.count > 1 ? ` (${money(linha.unidade)}g cada, ${money(linha.total)}g a pilha)` : ` (${money(linha.total)}g)`);
        caixa.onclick = () => {
          if (marcada) marcadas.delete(chave);
          else marcadas.add(chave);
          desenhar();
        };
        grade.append(caixa);
      }
      body.append(grade);

      if (comAviso.length) {
        body.append(
          el(
            'em',
            'filter-legend',
            `${comAviso.length} ${comAviso.length === 1 ? 'peça tem' : 'peças têm'} tier, imbuement ou estrela. ` +
              'Elas nascem fora da venda e só saem se você clicar em cada uma — e aí a tela pergunta de novo.'
          )
        );
      }
      if (recusadas.length) {
        body.append(
          el(
            'em',
            'filter-legend',
            `${recusadas.length} ${recusadas.length === 1 ? 'peça está travada' : 'peças estão travadas'}: ` +
              'nenhum NPC compra, ou você marcou como "não vender". Elas continuam no baú.'
          )
        );
      }

      const escolhidas = previa.linhas.filter((linha) => !linha.motivo && marcadas.has(chaveDe(linha)));
      const valiosasEscolhidas = escolhidas.filter((linha) => linha.aviso);
      const ouro = escolhidas.reduce((soma, linha) => soma + linha.total, 0);
      const pecas = escolhidas.reduce((soma, linha) => soma + linha.count, 0);

      const resumo = el('p', 'gate-note');
      resumo.textContent = escolhidas.length
        ? `${money(pecas)} item(ns) em ${escolhidas.length} ${escolhidas.length === 1 ? 'quadradinho' : 'quadradinhos'} — ${money(ouro)} gold.`
        : `Nada marcado. Há ${money(podem.length)} ${podem.length === 1 ? 'quadradinho' : 'quadradinhos'} que o NPC compra, somando ${money(previa.total)} gold.`;
      body.append(resumo);

      const acoes = el('div', 'confirm-actions');
      const fechar = el('button', 'ghost', 'Fechar');
      fechar.onclick = () => ctx.closeModal();

      const limpasMarcadas = podem.filter((linha) => marcadas.has(chaveDe(linha))).length;
      const todasLimpas = podem.length > 0 && limpasMarcadas === podem.length;
      const tudo = el('button', 'ghost', todasLimpas ? 'Desmarcar tudo' : 'Marcar tudo');
      tudo.disabled = !podem.length;
      tudo.onclick = () => {
        if (todasLimpas) for (const linha of podem) marcadas.delete(chaveDe(linha));
        else for (const linha of podem) marcadas.add(chaveDe(linha));
        desenhar();
      };

      const vender = el(
        'button',
        valiosasEscolhidas.length ? 'danger' : 'primary',
        escolhidas.length ? `Vender por ${money(ouro)}g` : 'Vender'
      );
      vender.disabled = !escolhidas.length;
      /*
       * O `mesmoAssim` viaja SÓ nas linhas com aviso. O servidor recusa em
       * silêncio uma peça com aviso que chegue sem a marca — ver
       * `venderDasSacolas`.
       */
      const mandar = () => {
        send({
          t: 'venderSacolas',
          vender: escolhidas.map((linha) => ({
            sacola: linha.sacola,
            i: linha.i,
            id: linha.id,
            ...(linha.aviso ? { mesmoAssim: true } : {}),
          })),
        });
        marcadas.clear();
        jaMarcou = false;
      };
      // A mesma segunda caixa da mochila, que LISTA o que sai. Vender não tem
      // volta, e o NPC não paga por tier, imbuement nem estrela.
      vender.onclick = () => confirmarVendaDaMochila(escolhidas, valiosasEscolhidas, ouro, mandar);

      acoes.append(fechar, tudo, vender);
      body.append(acoes);
    };
    ctx.redraw = desenhar;
    desenhar();
  });
}

/**
 * Uma segunda caixa, para o que não volta.
 *
 * Genérica de propósito: a limpeza e a venda pedem a mesma coisa e não devem
 * pedi-la com duas caras diferentes. O Enter cai no VOLTAR, como na primeira.
 */
function confirmarDeNovo({ titulo, texto, botao, aoConfirmar }) {
  const back = el('div', 'confirm-back');
  const box = el('div', 'confirm-box');
  box.append(el('h3', null, titulo));
  box.append(el('p', 'confirm-short', texto));

  const fechar = () => back.remove();
  const acoes = el('div', 'confirm-actions');
  const voltar = el('button', 'ghost', 'Voltar e revisar');
  voltar.onclick = fechar;
  const confirmar = el('button', 'danger', botao);
  confirmar.onclick = () => {
    fechar();
    aoConfirmar();
  };
  acoes.append(voltar, confirmar);
  box.append(acoes);
  back.append(box);
  fecharAoClicarFora(back, fechar);
  atalhosDaCaixa(back, { confirmar: fechar, fechar });
  document.body.append(back);
  voltar.focus();
}

/*
 * ---- A confirmação da venda ----
 *
 * Ela LISTA o que vai para o NPC, peça por peça, com o preço de cada uma —
 * porque o erro que ela existe para pegar não é "eu não queria vender", é "eu
 * não vi que essa aí tinha tier 8".
 *
 * ---- Ela aparece SEMPRE ----
 *
 * Antes só aparecia quando havia peça com tier, imbuement ou estrela na
 * seleção, com o argumento de que uma caixa em toda venda de sucata vira um
 * clique automático em duas semanas. O dono pediu que aparecesse sempre — o
 * mesmo que pediu para o Limpar — e o argumento antigo não sobrevive à lista:
 * ele valia para uma caixa que só repetia um número, e esta mostra o que sai.
 *
 * As peças caras continuam ganhando uma linha própria em vermelho no alto: o
 * que mudou é que elas não são mais a única razão de a caixa existir.
 *
 * O Enter cai no VOLTAR, como na caixa de destruir a mochila, e pelo mesmo
 * motivo: quem aperta Enter sem ler não pode vender a peça mais cara da conta
 * usando o atalho da tela que pergunta se ele tem certeza.
 */
function confirmarVendaDaMochila(linhas, valiosas, ouro, aoConfirmar) {
  const back = el('div', 'confirm-back');
  const box = el('div', 'confirm-box');
  box.append(el('h3', null, 'Tem certeza?'));
  box.append(
    el(
      'p',
      'confirm-short',
      `${linhas.length} ${linhas.length === 1 ? 'quadradinho vai' : 'quadradinhos vão'} para o NPC por ${money(ouro)} gold. ` +
        'Vendido, não volta.'
    )
  );
  if (valiosas.length) {
    box.append(
      el(
        'p',
        'confirm-short',
        `${valiosas.length} ${valiosas.length === 1 ? 'delas tem' : 'delas têm'} tier, imbuement ou estrela — e o NPC não paga por nada disso.`
      )
    );
  }

  const lista = el('div', 'venda-valiosas');
  for (const linha of linhas) {
    const item = el('div', 'venda-valiosa');
    const cell = itemCell({ ...linha }, 'filter');
    item.append(cell);
    const texto = el('div');
    texto.append(el('b', null, ctx.state.items[linha.id]?.name ?? `item ${linha.id}`));
    texto.append(el('em', null, `${linha.aviso ? `${linha.aviso} · ` : ''}sai por ${money(linha.total)}g`));
    item.append(texto);
    lista.append(item);
  }
  box.append(lista);

  const fechar = () => back.remove();
  const acoes = el('div', 'confirm-actions');
  const voltar = el('button', 'ghost', 'Voltar e revisar');
  voltar.onclick = fechar;
  const confirmar = el('button', 'danger', 'Vender assim mesmo');
  confirmar.onclick = () => {
    fechar();
    aoConfirmar();
  };
  acoes.append(voltar, confirmar);
  box.append(acoes);

  back.append(box);
  fecharAoClicarFora(back, fechar);
  atalhosDaCaixa(back, { confirmar: fechar, fechar });
  document.body.append(back);
  voltar.focus();
}

export function openLimparMochila() {
  const { state } = ctx;
  /*
   * Fora do `desenhar`, para o redesenho a cada clique não perder a escolha.
   *
   * O conjunto guarda o que VAI FORA, e nasce VAZIO. Antes ele guardava o que
   * ficava e nascia cheio — ver a inversão na nota do topo.
   */
  const marcadas = new Set();

  ctx.openModal('Limpar a mochila', (body) => {
    const desenhar = () => {
      body.innerHTML = '';
      const mochila = state.character.inventory ?? [];

      if (!mochila.length) {
        body.append(el('p', 'gate-note', 'A mochila já está vazia.'));
        const acoes = el('div', 'confirm-actions');
        const fechar = el('button', 'ghost', 'Fechar');
        fechar.onclick = () => ctx.closeModal();
        acoes.append(fechar);
        body.append(acoes);
        return;
      }

      /*
       * ---- Uma célula por PEÇA quando a peça tem o que mostrar ----
       *
       * O dono: "tá vendo que eu tenho 3 itens diferentes na mochila? Mas na
       * hora de limpar ele mostra junto e sem os atributos de cada um."
       *
       * Ele tinha três wands do mesmo id — uma ★★★, outra ★★★ de outros afixos
       * e uma ★ —, e esta tela mostrava um quadradinho só com "3" no canto. As
       * três eram uma decisão só: guardava as três ou perdia as três, e não
       * havia como saber qual era qual porque nem as estrelas apareciam.
       *
       * Agrupar por id nasceu de um caso real e continua valendo para ele: 87
       * piercing bolts em quatro pilhas não são quatro decisões, são uma. O que
       * mudou é a régua — o que separa não é o id, é a peça TER algo próprio:
       *
       *   - afixo (a estrela), tier ou imbuement: cada uma é única, e vale
       *     dinheiro diferente;
       *   - carga ou tempo gastos: duas exercise weapons da mesma marca com 14
       *     e 900 cargas não são intercambiáveis.
       *
       * Sem nada disso, duas cópias são a mesma coisa e continuam num quadrado
       * só. Com qualquer coisa disso, cada uma ganha o seu — desenhada pelo
       * `itemCell` de sempre, que já sabe pôr as estrelas, o selo do tier e o
       * balão com os atributos.
       */
      const assinaturaDaPeca = (entry) =>
        [
          entry.tier ?? 0,
          (entry.af ?? []).map((a) => (typeof a === 'string' ? a : a?.id ?? a?.key ?? JSON.stringify(a))).join('+'),
          (entry.imbu ?? []).map((i) => (typeof i === 'string' ? i : i?.id ?? i?.key ?? JSON.stringify(i))).join('+'),
          entry.carga ?? '',
        ].join('|');

      const grupos = [];
      const juntas = new Map();
      for (let i = 0; i < mochila.length; i++) {
        const entry = mochila[i];
        const valiosa = !!(entry.af?.length || entry.tier || entry.imbu?.length);
        const propria = valiosa || entry.carga != null;

        if (!propria) {
          const igual = juntas.get(entry.id);
          if (igual) {
            igual.count += entry.count ?? 1;
            igual.indices.push(i);
            continue;
          }
        }

        /*
         * A chave carrega o id e a assinatura junto do índice.
         *
         * Ela só vive enquanto a janela está aberta, e a mochila pode mudar
         * embaixo dela (loot entrando, venda automática saindo). Com o id e a
         * assinatura dentro, um índice que escorregou deixa de bater e a peça
         * volta ao estado padrão — que para a peça boa é "guardada". O erro
         * cai para o lado seguro, e o servidor ainda confere o id de novo.
         */
        const grupo = {
          chave: propria ? `${i}|${entry.id}|${assinaturaDaPeca(entry)}` : `id|${entry.id}`,
          entry,
          count: entry.count ?? 1,
          indices: [i],
          valiosa,
        };
        grupos.push(grupo);
        if (!propria) juntas.set(entry.id, grupo);
      }

      body.append(
        el('p', 'shop-note', 'Clique nos itens que você quer JOGAR FORA. O que ficar sem marca continua na mochila.')
      );
      body.append(
        el('em', 'filter-legend', 'Nada vem marcado. Destruir não tem volta — e o que sai daqui não vira ouro.')
      );

      const grade = el('div', 'filter-grid');
      let pilhasFora = 0;
      let unidadesFora = 0;
      let valiosasFora = 0;
      const fora = [];
      const saindo = [];

      for (const grupo of grupos) {
        const fica = !marcadas.has(grupo.chave);
        // A peça INTEIRA, e não `{id, count}`: é ela que carrega as estrelas, o
        // selo do tier e o balão com os atributos.
        const cell = itemCell({ ...grupo.entry, count: grupo.count }, 'filter');
        cell.classList.add(fica ? 'protected' : 'barred');
        // O balão do `itemCell` já diz o que a peça é; esta linha diz o que vai
        // acontecer com ela, que é a pergunta desta tela.
        cell.title = `${money(grupo.count)} unidade(s) — ${fica ? 'FICA na mochila' : 'vai fora'}`;
        cell.onclick = () => {
          if (fica) marcadas.add(grupo.chave);
          else marcadas.delete(grupo.chave);
          desenhar();
        };
        grade.append(cell);

        if (fica) continue;
        pilhasFora++;
        unidadesFora += grupo.count;
        if (grupo.valiosa) valiosasFora++;
        // A caixa de confirmação LISTA o que sai, peça por peça: ela precisa
        // do grupo inteiro, e não só do índice que o servidor recebe.
        saindo.push(grupo);
        for (const i of grupo.indices) fora.push({ i, id: grupo.entry.id });
      }
      body.append(grade);

      const resumo = el('p', 'gate-note');
      resumo.textContent = pilhasFora
        ? `Vão fora ${money(unidadesFora)} item(ns) em ${pilhasFora} ${pilhasFora === 1 ? 'quadradinho' : 'quadradinhos'}.`
        : 'Nada marcado para jogar fora.';
      body.append(resumo);

      /*
       * O aviso do que o jogador DESMARCOU à mão. Separado do resumo e em
       * vermelho porque é a única linha desta tela que fala de uma perda que não
       * dá para desfazer nem repor.
       */
      if (valiosasFora) {
        body.append(
          el(
            'p',
            'confirm-short',
            `${valiosasFora} ${valiosasFora === 1 ? 'tipo tem' : 'tipos têm'} estrela, tier ou imbuement e vão fora junto.`
          )
        );
      }

      const acoes = el('div', 'confirm-actions');
      const cancelar = el('button', 'ghost', 'Cancelar');
      cancelar.onclick = () => ctx.closeModal();

      /*
       * ---- "Marcar tudo", e o que ele NÃO pega ----
       *
       * Com a tela nascendo vazia, esvaziar uma mochila de sucata custaria
       * vinte cliques — era isso que a marca inicial resolvia, e é isso que
       * este botão devolve. É o mesmo gesto da tela de vender, que já o tinha.
       *
       * Ele pega SÓ o que não tem estrela, tier nem imbuement. A proteção que
       * antes vinha do padrão não sumiu: mudou de lugar. Quem quer destruir a
       * peça ★★★ ainda pode — clicando NELA, que é uma decisão, e não um
       * efeito colateral de um botão de atalho.
       */
      const simples = grupos.filter((grupo) => !grupo.valiosa);
      const todasSimples = simples.length > 0 && simples.every((grupo) => marcadas.has(grupo.chave));
      const tudo = el('button', 'ghost', todasSimples ? 'Desmarcar tudo' : 'Marcar tudo');
      tudo.disabled = !simples.length;
      tudo.onclick = () => {
        for (const grupo of simples) {
          if (todasSimples) marcadas.delete(grupo.chave);
          else marcadas.add(grupo.chave);
        }
        desenhar();
      };

      const limpar = el('button', 'danger', 'Jogar fora');
      limpar.disabled = !pilhasFora;
      limpar.onclick = () => confirmarLimpezaDaMochila({ pilhasFora, unidadesFora, valiosasFora, fora, saindo });
      acoes.append(cancelar, tudo, limpar);
      body.append(acoes);
    };

    ctx.redraw = desenhar;
    desenhar();
  });
}

/*
 * A SEGUNDA caixa.
 *
 * Ela não é uma repetição da primeira: a primeira é onde se ESCOLHE, e escolher
 * ocupa a atenção inteira — depois de vinte cliques nos quadradinhos, o vigésimo
 * primeiro sai no automático. Esta tem um número e dois botões, e mais nada.
 */
function confirmarLimpezaDaMochila({ pilhasFora, unidadesFora, valiosasFora, fora, saindo = [] }) {
  const back = el('div', 'confirm-back');
  const box = el('div', 'confirm-box');
  box.append(el('h3', null, 'Tem certeza?'));
  box.append(
    el('p', 'confirm-short', `${money(unidadesFora)} item(ns) em ${pilhasFora} ${pilhasFora === 1 ? 'quadradinho' : 'quadradinhos'} vão ser destruídos. Não tem volta.`)
  );

  /*
   * ---- E a LISTA do que se perde ----
   *
   * "quando a pessoa selecionar o que quer limpar vai aparecer a confirmação e
   * tudo que será perdido, e informa que não tem volta".
   *
   * Um número sozinho não é conferível: "14 itens em 6 quadradinhos" é
   * verdade tanto para seis pilhas de sucata quanto para a arma de exercise
   * junto de cinco. A lista é o que torna a pergunta respondível — o erro que
   * ela pega não é "eu não queria limpar", é "eu não vi que ESSA estava
   * marcada".
   *
   * É a mesma lista da `confirmarVendaDaMochila`, e de propósito: as duas telas
   * fazem a mesma pergunta, e quem já leu uma reconhece a outra.
   */
  if (saindo.length) {
    const lista = el('div', 'venda-valiosas');
    for (const grupo of saindo) {
      const linha = el('div', 'venda-valiosa');
      linha.append(itemCell({ ...grupo.entry, count: grupo.count }, 'filter'));
      const texto = el('div');
      texto.append(el('b', null, ctx.state.items[grupo.entry.id]?.name ?? `item ${grupo.entry.id}`));
      /*
       * A segunda linha diz o que ESTA peça tem de próprio — é ela que separa
       * a wand ★★★ da wand crua no meio de uma lista de nomes iguais.
       */
      const marcas = [];
      if (grupo.entry.tier) marcas.push(`tier ${grupo.entry.tier}`);
      if (grupo.entry.af?.length) marcas.push(`${grupo.entry.af.length} afixo(s)`);
      if (grupo.entry.imbu?.length) marcas.push(`${grupo.entry.imbu.length} imbuement(s)`);
      texto.append(el('em', null, `${money(grupo.count)} unidade(s)${marcas.length ? ` · ${marcas.join(' · ')}` : ''}`));
      linha.append(texto);
      lista.append(linha);
    }
    box.append(lista);
  }

  if (valiosasFora) {
    box.append(
      el(
        'p',
        'confirm-short',
        `E ${valiosasFora} ${valiosasFora === 1 ? 'deles tem' : 'deles têm'} estrela, tier ou imbuement.`
      )
    );
  }

  const fechar = () => back.remove();
  const acoes = el('div', 'confirm-actions');
  const voltar = el('button', 'ghost', 'Voltar e revisar');
  voltar.onclick = fechar;
  const destruir = () => {
    ctx.send({ t: 'clearBackpack', fora });
    ctx.closeModal();
  };
  /*
   * ---- E uma SEGUNDA caixa quando há peça cara na lista ----
   *
   * "se a pessoa marcar podera ser limpados ou vendidos, so que ai tinha que
   * ser dupla confirmacao".
   *
   * Só quando `valiosasFora` existe, e por isso: uma segunda caixa em toda
   * limpeza de sucata vira um clique automático em duas semanas, e uma
   * confirmação que virou reflexo não protege mais nada. Aparecendo só no caso
   * raro, ela continua sendo lida.
   */
  const confirmar = el('button', 'danger', valiosasFora ? 'Destruir' : 'Destruir');
  confirmar.onclick = () => {
    fechar();
    if (!valiosasFora) return destruir();
    confirmarDeNovo({
      titulo: 'Sério mesmo?',
      texto:
        `${valiosasFora} ${valiosasFora === 1 ? 'peça que você desmarcou tem' : 'peças que você desmarcou têm'} estrela, tier ou imbuement. ` +
        'Elas vão ser DESTRUÍDAS, e não vendidas — não volta nada, nem ouro.',
      botao: 'Destruir assim mesmo',
      aoConfirmar: destruir,
    });
  };
  acoes.append(voltar, confirmar);
  box.append(acoes);

  back.append(box);
  fecharAoClicarFora(back, fechar);
  /*
   * O Enter cai no VOLTAR, e não no destruir.
   *
   * `atalhosDaCaixa` liga o Enter ao confirmar, que é o certo em toda outra
   * caixa do jogo. Aqui seria o contrário do que a caixa existe para fazer:
   * quem apertou Enter sem ler apagaria a mochila usando o atalho da tela que
   * pergunta se ele tem certeza.
   */
  atalhosDaCaixa(back, { confirmar: fechar, fechar });
  document.body.append(back);
  voltar.focus();
}

/*
 * ---- As DUAS marcações do filtro de loot, no cabeçalho ----
 *
 * "cancela o negócio de predefinições, deixa o modal do loot filter como era. A
 * única coisa que você vai fazer é duas coisas: um negócio pra marcar 'sempre
 * salvar alterações', e outro 'usar configurações desse loot filter para todos
 * chares da conta'. Pode colocar resumido lá em cima mesmo, ao lado do x."
 *
 * Aqui esteve uma tela de predefinições com nome, lista e botões de salvar e
 * aplicar. Ele cancelou, e estava certo: quem monta um filtro de loot monta UM,
 * e quer que ele fique. As duas caixinhas dizem a mesma coisa sem lista nenhuma
 * — "guarde" e "vale para todos" — e cabem no canto do cabeçalho.
 *
 * ---- O rótulo curto na tela, o inteiro no balão ----
 *
 * `#modal-acoes` é a faixa entre o título e o ✕: nela cabem duas palavras, não
 * duas frases. O que cada uma faz está no `title`, com as palavras do próprio
 * pedido.
 *
 * ---- E elas nascem marcadas sem perguntar nada ----
 *
 * O estado das duas viaja dentro do personagem (`character.lootFiltro`, posto
 * pelo servidor em `publicCharacter`). Pedir ao abrir custaria uma viagem e uma
 * piscada — as caixinhas apareceriam desmarcadas e se marcariam sozinhas meio
 * segundo depois.
 */
function marcacoesDoFiltro() {
  const { state, send } = ctx;
  const canto = ctx.acoesDoModal?.();
  if (!canto) return;
  const config = state.character?.lootFiltro ?? { sempreSalvar: true, paraTodos: false };

  for (const [chave, curto, inteiro] of [
    [
      'sempreSalvar',
      'Salvar sempre',
      'Sempre salvar alterações: o filtro de cada caçada fica como você deixou e volta sozinho quando você entrar ali de novo.',
    ],
    [
      'paraTodos',
      'Toda a conta',
      'Usar as configurações deste loot filter para todos os chares da conta.',
    ],
  ]) {
    const rotulo = el('label', 'filtro-marca');
    rotulo.title = inteiro;
    const caixa = document.createElement('input');
    caixa.type = 'checkbox';
    caixa.checked = !!config[chave];
    caixa.onchange = () => send({ t: 'lootFiltro', [chave]: caixa.checked });
    rotulo.append(caixa, el('span', null, curto));
    canto.append(rotulo);
  }
}

export function openLootFilter() {
  const { state, send } = ctx;

  ctx.openModal('Filtro de loot', (body) => {
    const draw = () => {
      body.innerHTML = '';
      const rules = state.character.itemRules ?? { noSell: [], noLoot: [], soAfixo: [] };

      // Quais hunts entram na conta: a atual, ou a roda inteira no ciclo.
      const ids = state.run?.mode === 'cycle' && state.run.ids?.length
        ? state.run.ids
        : [state.hunt?.huntId].filter(Boolean);
      /*
       * ---- A hunt é procurada nas TRÊS prateleiras ----
       *
       * O relato: "o loot filter pra quem é convidado de party/hunt não mostra
       * os loot dessa caçada".
       *
       * A busca era só em `catalog.hunts`, e o catálogo tem três listas
       * separadas — `hunts`, `bosses` e `especiais` (ver o `staticCatalog` do
       * servidor). Numa Especial Hunt ou numa sala de boss o `find` não achava
       * nada, a lista de drops saía vazia e a coluna "Loot desta caçada" ficava
       * em branco.
       *
       * E é justamente onde o convidado entra: quem é chamado para uma Especial
       * Hunt vê a tela vazia enquanto o dono da conta que abriu a instância vê
       * o mesmo vazio — só que ele já sabia o que ia cair.
       */
      /*
       * E a busca varre TODAS as prateleiras, por nome de lista.
       *
       * Escrever as três à mão foi o conserto da primeira vez, e o defeito
       * voltou na segunda: as Divine Hunts nasceram numa quarta lista
       * (`divinas`) e a coluna "Loot desta caçada" ficou vazia lá dentro
       * exatamente como ficava na instance. Um `??` esquecido não dá erro —
       * dá uma tela em branco.
       *
       * Agora a lista de prateleiras é UMA, aqui, e a próxima que o servidor
       * criar entra acrescentando o nome dela nesta linha.
       */
      const acharNoCatalogo = (id) => {
        for (const prateleira of PRATELEIRAS_DE_HUNT) {
          const achou = state.catalog[prateleira]?.find((hunt) => hunt.id === id);
          if (achou) return achou;
        }
        return null;
      };
      const huntsDaVez = ids.map(acharNoCatalogo).filter(Boolean);

      // Junta os drops de todas as criaturas de todas essas hunts, sem repetir.
      const drops = new Map();
      for (const hunt of huntsDaVez) {
        for (const creature of hunt.creatures ?? []) {
          for (const drop of lootComGemas(state.catalog.bestiary[creature.key])) {
            if (!drop.id || !state.items[drop.id]) continue;
            const atual = drops.get(drop.id);
            // Fica a melhor chance: é o que diz o quanto o item aparece.
            if (!atual || (drop.chance ?? 0) > atual.chance) {
              drops.set(drop.id, { id: drop.id, chance: drop.chance ?? 0 });
            }
          }
        }
      }
      const lista = [...drops.values()].sort((a, b) => b.chance - a.chance);

      /*
       * ---- O topo começa direto nas regras ----
       *
       * "aqui tem um espaço, dá pra subir tudo e organizar melhor? tirar tipo
       * 'Loot de Feru Way'."
       *
       * Eram duas fileiras antes de qualquer escolha: a frase com o nome da
       * hunt e, sozinho numa linha, o botão "Apenas o que NPC compra". O nome
       * vira dica no título da grade de loot, e o botão vai para o cabeçalho
       * DELA — ele marca os itens daquela grade, e ao lado dela é onde se
       * entende sobre o que ele age.
       *
       * O aviso de "fora de hunt" continua, porque ele muda o que a grade
       * mostra — mas mora dentro da grade, e só quando é verdade.
       */
      const nomeDaHunt = huntsDaVez.map((hunt) => hunt.name).join(', ');
      // A escolha do afixo vale para TODA a venda automatica, e nao so' para
      // esta caçada — por isso fica no topo, fora das duas listas por id.
      body.append(regrasDaVendaAutomatica());
      /*
       * E as duas marcações vão para o canto do cabeçalho, ao lado do ✕, onde o
       * dono as pediu. Ficam DENTRO do `draw` porque `acoesDoModal` devolve o
       * canto já limpo — quem desenha o corpo desenha o cabeçalho junto.
       */
      marcacoesDoFiltro();

      const layout = el('div', 'filter-layout');

      // ---- coluna do loot da hunt ----
      const esquerda = el('div', 'filter-box');
      const topo = el('div', 'filter-head');
      const tituloDaGrade = el('b', null, 'Loot desta caçada');
      if (nomeDaHunt) tituloDaGrade.title = `Loot de ${nomeDaHunt}`;
      const npc = botaoApenasNpc(lista.map((drop) => drop.id));
      npc.classList.add('filter-head-npc');
      topo.append(tituloDaGrade, npc, el('span', null, String(lista.length)));
      esquerda.append(topo);
      if (!huntsDaVez.length) {
        esquerda.append(el('em', 'filter-legend', 'Você não está em nenhuma hunt — as listas continuam valendo.'));
      }

      const grade = el('div', 'filter-grid');
      for (const drop of lista) {
        const pct = `${(drop.chance * 100).toFixed(drop.chance >= 0.01 ? 1 : 2).replace('.', ',')}% de chance`;
        // A MESMA função da prévia da hunt: um lugar só decide o que cada botão
        // do mouse faz, e as duas telas não podem mais divergir.
        grade.append(ligarRegrasDoItem(itemCell({ id: drop.id, count: 1 }, 'filter'), drop.id, { titulo: pct }));
      }
      if (!lista.length) grade.append(el('p', 'empty', 'Nenhum drop conhecido por aqui.'));
      esquerda.append(grade);
      esquerda.append(legendaDoFiltro());
      esquerda.append(
        el('em', 'filter-legend', 'Ou arraste um item para uma das listas ao lado. Um item fica numa lista só: marcar a outra troca de lista.')
      );
      layout.append(esquerda);

      // ---- as duas listas ----
      const direita = el('div', 'filter-side');
      for (const [rule, titulo, dica] of [
        ['noSell', 'Não vender', 'ficam na bolsa quando a venda passa'],
        ['noLoot', 'Não coletar', 'nem entram na bolsa — ficam no chão'],
        /*
         * ---- E onde a linha da estrela vale ----
         *
         * A terceira lista responde "em QUE itens" a escolha lá de cima ("roxa
         * para cima") se aplica. Vazia = em todos, que é o de sempre.
         *
         * Ela entra no MESMO laço das outras duas de propósito: o arrasto, o
         * clique para tirar e o "+" da busca são idênticos, e escrever uma
         * quarta cópia disso é como as duas primeiras já divergiram uma vez.
         */
        ['soAfixo', 'Afixo só nestes', 'a linha da estrela vale só neles — vazio vale para todos'],
      ]) {
        const ids = rules[rule] ?? [];
        const caixa = el('div', 'filter-box drop-target');
        const cabecalho = el('div', 'filter-head');
        cabecalho.append(el('b', null, titulo), el('span', null, String(ids.length)));
        caixa.append(cabecalho, el('em', 'filter-legend', dica));

        caixa.addEventListener('dragover', (event) => {
          event.preventDefault();
          caixa.classList.add('over');
        });
        caixa.addEventListener('dragleave', () => caixa.classList.remove('over'));
        caixa.addEventListener('drop', (event) => {
          event.preventDefault();
          caixa.classList.remove('over');
          try {
            const carga = JSON.parse(event.dataTransfer.getData('text/plain'));
            /*
             * As listas vêm do `state` na hora de soltar, não do desenho.
             *
             * O `rules` que este desenho fechou por cima pode já estar solto no
             * ar: cada `pushState` troca `state.character` por um objeto novo, e
             * pintar no antigo não aparece em lugar nenhum.
             */
            const vivas = (ctx.state.character.itemRules ??= { noSell: [], noLoot: [] });
            vivas[rule] ??= [];
            // Já estar na lista não é motivo para tirar: largar de novo no
            // mesmo lugar tem que ser inofensivo.
            if (carga?.id && !vivas[rule].includes(carga.id)) {
              // Soltar aqui manda para cá e mais nada: a outra lista é
              // independente, e um item pode estar nas duas.
              //
              // Pinta na hora e manda depois: esperar a volta do servidor
              // deixava o item parado por um instante, como se o arrasto não
              // tivesse pegado. O `pushState` seguinte confirma o desenho.
              vivas[rule].push(carga.id);
              draw();
              send({ t: 'itemRule', rule, id: carga.id, only: true });
            }
          } catch {
            /* arrasto de fora da página */
          }
        });

        const conteudo = el('div', 'filter-grid');
        for (const id of ids) {
          const cell = itemCell({ id, count: 1 }, rule);
          /* A marca de cada lista: barrado, protegido, ou o fio da estrela. */
          cell.classList.add(rule === 'noLoot' ? 'barred' : rule === 'soAfixo' ? 'so-afixo' : 'protected');
          cell.title = `${state.items[id]?.name ?? id} — clique para tirar da lista`;
          cell.onclick = () => send({ t: 'itemRule', rule, id });
          conteudo.append(cell);
        }
        // O "+" abre a busca por qualquer item do jogo, não só o que já caiu.
        const add = el('button', 'cell add-cell', '+');
        add.title = `Escolher um item para ${titulo.toLowerCase()}`;
        add.onclick = () => openItemPicker(rule, titulo);
        conteudo.append(add);
        caixa.append(conteudo);
        direita.append(caixa);
      }
      layout.append(direita);
      body.append(layout);

      const rodape = el('div', 'filter-foot');
      const limpar = el('button', 'ghost', 'Limpar filtro');
      limpar.disabled = !(rules.noSell.length + rules.noLoot.length + (rules.soAfixo?.length ?? 0));
      limpar.onclick = () => {
        for (const id of [...rules.noSell]) send({ t: 'itemRule', rule: 'noSell', id });
        for (const id of [...rules.noLoot]) send({ t: 'itemRule', rule: 'noLoot', id });
        for (const id of [...(rules.soAfixo ?? [])]) send({ t: 'itemRule', rule: 'soAfixo', id });
      };
      rodape.append(limpar);
      body.append(rodape);
    };
    ctx.redraw = draw;
    draw();
  });
}

/** Busca por qualquer item do jogo, para marcar o que ainda nem caiu. */
function openItemPicker(rule, titulo) {
  const { state, send } = ctx;
  const anterior = ctx.redraw;

  ctx.openModal(titulo, (body) => {
    const search = document.createElement('input');
    search.className = 'search';
    search.placeholder = 'buscar item...';
    body.append(search);

    const grid = el('div', 'filter-grid');
    const draw = () => {
      const termo = search.value.trim().toLowerCase();
      grid.innerHTML = '';
      if (termo.length < 2) {
        grid.append(el('p', 'empty', 'digite ao menos duas letras'));
        return;
      }
      let mostrados = 0;
      for (const [id, meta] of Object.entries(state.items)) {
        if (mostrados >= 120) break;
        if (!meta.name?.toLowerCase().includes(termo)) continue;
        const cell = itemCell({ id: Number(id), count: 1 }, rule);
        cell.title = meta.name;
        cell.onclick = () => {
          send({ t: 'itemRule', rule, id: Number(id) });
          ctx.closeModal();
          openLootFilter();
        };
        grid.append(cell);
        mostrados++;
      }
      if (!mostrados) grid.append(el('p', 'empty', 'nada com esse nome'));
    };
    search.oninput = draw;
    draw();
    body.append(grid);

    const voltar = el('button', 'ghost modal-back', '← Voltar para o filtro');
    voltar.onclick = () => openLootFilter();
    body.append(voltar);
  }, () => (ctx.redraw = anterior));
}

// ---------- montarias e outfits ----------

// Quanto cada peça da coleção vale de crítico. Casa com o COLLECTION_CRIT do
// server/src/character.mjs (30 pontos-base = 0,3%).
const COLLECTION_CRIT = 0.3;

// Porcentagem com vírgula: é assim que se escreve em português, e misturar
// "+0.0%" com "+0,3%" na mesma frase salta aos olhos.
const percent = (value, casas = 1) => `${Number(value).toFixed(casas).replace('.', ',')}%`;

/**
 * Faixa que explica o prêmio de colecionar e mostra onde o personagem está.
 * Aparece na aparência e nas duas abas da loja: quem vê um outfit à venda
 * precisa saber que ele vale mais do que o desenho.
 */
function collectionBanner(character) {
  const collection = character.derived?.collection ?? { pieces: 0, critChance: 0 };
  const banner = el('div', 'collection-note');
  banner.append(uiIcon('prey-damage'));

  const texto = el('div');
  texto.append(
    el('b', null, `Coleção: +${percent(collection.critChance * 100)} de crítico`),
    el(
      'em',
      null,
      /*
       * "aparência", e não "outfit": a conta passou a ser por aparência, e os dois
       * desenhos do Assassin valem uma peça só (ver `pecasDaColecao`, no servidor).
       * O texto dizia "cada outfit", que era o convite a comprar o do outro sexo
       * pelo crítico — coisa que a loja nem vende mais.
       */
      `Cada aparência e cada montaria que você tem valem +${percent(COLLECTION_CRIT)} de chance ` +
        `de crítico. Você tem ${collection.pieces} ${collection.pieces === 1 ? 'peça' : 'peças'}.`
    )
  );
  banner.append(texto);
  return banner;
}

/**
 * Aba de aparência dentro da ficha do personagem.
 *
 * O rascunho vive em `ctx.tabs.outfitDraft`, não em `state.character.outfit`: o
 * servidor reescreve o personagem inteiro quatro vezes por segundo durante a
 * caçada, e mexer direto ali desfazia a troca de addon antes do clique em
 * salvar.
 */
export function renderAppearance(body) {
  const { state, send } = ctx;
  if (!ctx.state.mounts) {
    send({ t: 'mounts' });
    return void body.append(el('p', 'empty', 'carregando...'));
  }

  const draft = (ctx.tabs.outfitDraft ??= { ...state.character.outfit });
  const tab = ctx.tabs.look ?? 'outfits';
  const part = ctx.tabs.colorPart ?? 'head';
  const dir = ctx.tabs.lookDir ?? 2;
  const info = outfitInfo(draft.type);
  const addonCount = Math.max(1, info?.groups?.[0]?.addons ?? 1) - 1;

  body.append(collectionBanner(state.character));

  const wrap = el('div', 'outfit-picker');

  // ---- coluna da esquerda: marcas, preview e cores ----
  const left = el('div', 'outfit-side');

  const marks = el('div', 'outfit-marks');
  const mark = (label, on, disabled, onToggle) => {
    const row = el('label', `outfit-mark${disabled ? ' disabled' : ''}`);
    const input = document.createElement('input');
    input.type = 'checkbox';
    input.checked = on;
    input.disabled = disabled;
    input.onchange = onToggle;
    row.append(input, el('span', null, label));
    marks.append(row);
    return row;
  };

  /*
   * ---- Addon marcável é addon que o personagem TEM ----
   *
   * As duas caixinhas vinham habilitadas em qualquer outfit, e marcar bastava:
   * um personagem recém-criado saía vestido com os dois. Elas eram a única
   * porta, e não estavam trancadas nem aqui nem no servidor.
   *
   * `addonCount` continua mandando no que a ARTE tem (nem todo outfit foi
   * desenhado com dois); `donos` manda no que o JOGADOR tem naquele look. Só
   * abre quem passa nos dois.
   */
  const donos =
    state.mounts?.outfits?.find((entry) => entry.look === draft.type)?.addons ?? 0;
  for (let index = 0; index < 2; index++) {
    const bit = 1 << index;
    const temArte = index < addonCount;
    const meu = !!(donos & bit);
    const linha = mark(`Addon ${index + 1}`, !!(draft.addons & bit), !temArte || !meu, () => {
      draft.addons = (draft.addons ?? 0) ^ bit;
      ctx.redraw();
    });
    if (temArte && !meu) linha.title = 'vem junto com o outfit comprado na loja';
  }
  mark('Montaria', !!draft.mount, !state.mounts.mounts.some((m) => m.owned), () => {
    draft.mount = draft.mount ? 0 : ctx.tabs.lastMount ?? state.mounts.mounts.find((m) => m.owned)?.look ?? 0;
    ctx.redraw();
  });
  // O crítico não muda ao vestir: quem paga é a coleção, não a roupa do dia.
  // Dizer isso aqui evita a leitura de que desmarcar um addon custa bônus.
  const total = state.character.derived?.collection ?? { pieces: 0, critChance: 0 };
  marks.append(
    el(
      'em',
      'outfit-bonus',
      `+${percent(total.critChance * 100)} de crítico por ${total.pieces} ${
        total.pieces === 1 ? 'peça' : 'peças'
      } — vale por ter, não por vestir`
    )
  );
  left.append(marks);

  const preview = el('div', 'outfit-preview');
  preview.append(outfitCanvas(draft.type, draft, 108, dir));

  const turn = el('button', 'step outfit-turn', '⟳');
  turn.title = 'virar o personagem';
  turn.onclick = () => {
    ctx.tabs.lookDir = (dir + 1) % 4;
    ctx.redraw();
  };
  preview.append(turn);
  left.append(preview);

  // Paleta de cores logo abaixo do preview, como no client.
  left.append(
    tabBar({ head: 'Cabeça', body: 'Corpo', legs: 'Pernas', feet: 'Pés' }, part, (next) => {
      ctx.tabs.colorPart = next;
      ctx.redraw();
    })
  );

  const colors = el('div', 'color-grid');
  for (let index = 0; index < 133; index++) {
    const [r, g, b] = outfitColor(index);
    const swatch = el('button');
    swatch.style.background = `rgb(${r}, ${g}, ${b})`;
    swatch.setAttribute('aria-selected', String(draft[part] === index));
    swatch.onclick = () => {
      draft[part] = index;
      ctx.redraw();
    };
    colors.append(swatch);
  }
  left.append(colors);

  const save = el('button', 'wide', 'Salvar aparência');
  save.onclick = () => {
    send({ t: 'outfit', outfit: draft });
    if (draft.mount !== state.character.outfit.mount) {
      const mount = state.mounts.mounts.find((entry) => entry.look === draft.mount);
      send({ t: 'mount', id: mount?.id ?? 0 });
    }
  };
  left.append(save);
  wrap.append(left);

  // ---- coluna da direita: outfits ou montarias ----
  const right = el('div', 'outfit-choices');
  right.append(
    tabBar({ outfits: 'Outfits', mounts: 'Montarias' }, tab, (next) => {
      ctx.tabs.look = next;
      ctx.redraw();
    })
  );

  const grid = el('div', 'outfit-list');
  if (tab === 'mounts') {
    const owned = state.mounts.mounts.filter((mount) => mount.owned && outfitInfo(mount.look));
    for (const mount of owned) {
      const button = el('button');
      button.setAttribute('aria-selected', String(draft.mount === mount.look));
      button.append(outfitCanvas(mount.look, null, 48), el('b', null, mount.name));
      button.append(el('em', null, `+${mount.speed} vel.`));
      button.onclick = () => {
        draft.mount = mount.look;
        ctx.tabs.lastMount = mount.look;
        ctx.redraw();
      };
      grid.append(button);
    }
    if (!owned.length) grid.append(el('p', 'empty', 'Nenhuma montaria ainda — a Store tem as outras.'));
  } else {
    const seen = new Set();
    for (const entry of state.mounts.outfits) {
      if (!entry.owned || seen.has(entry.look) || !outfitInfo(entry.look)) continue;
      seen.add(entry.look);

      /*
       * O bonequinho da lista veste O QUE O PERSONAGEM TEM naquele outfit.
       *
       * Vinha com `addons: 3` fixo, "para ver o desenho completo antes de
       * escolher". Só que esta lista não é vitrine — é o guarda-roupa: tudo aqui
       * já é do jogador. Mostrar com os dois addons um outfit que não tem addon
       * nenhum é prometer roupa que não existe, e foi o que fez a tela toda
       * parecer que o personagem novo nascia vestido de veterano.
       *
       * Quem mostra o desenho completo é a loja, e lá o `addons: 3` continua —
       * porque lá o outfit realmente vem com os dois.
       */
      const button = el('button');
      button.setAttribute('aria-selected', String(draft.type === entry.look));
      button.append(
        outfitCanvas(entry.look, { ...draft, addons: entry.addons ?? 0, mount: 0 }, 48),
        el('b', null, entry.name),
      );
      button.onclick = () => {
        draft.type = entry.look;
        ctx.redraw();
      };
      grid.append(button);
    }
    if (!seen.size) grid.append(el('p', 'empty', 'Nenhum outfit liberado — a Store tem os outros.'));
  }
  right.append(grid);
  wrap.append(right);
  body.append(wrap);
}

// ---------- proficiência de arma ----------

// Os nomes dos perks são os do proficiencies_definitions.hpp do servidor.
const PERK_LABEL = {
  attackDamage: 'Dano de ataque',
  defense: 'Bloqueio',
  weaponShieldMod: 'Bloqueio da arma',
  skillBonus: 'Perícia',
  specialMagicLevel: 'Magic level especial',
  spellAugment: 'Augment de magia',
  bestiaryDamage: 'Dano no bestiary',
  bossDamage: 'Dano em boss',
  critChance: 'Chance de crítico',
  critChanceElemental: 'Crítico elemental',
  critChanceRunes: 'Crítico de runa',
  critChanceAutoAttack: 'Crítico no ataque',
  critDamage: 'Dano crítico',
  critDamageElemental: 'Dano crítico elemental',
  critDamageRunes: 'Dano crítico de runa',
  critDamageAutoAttack: 'Dano crítico no ataque',
  manaLeech: 'Mana leech',
  lifeLeech: 'Life leech',
  manaOnHit: 'Mana por golpe',
  lifeOnHit: 'Vida por golpe',
  manaOnKill: 'Mana por morte',
  lifeOnKill: 'Vida por morte',
  damageAtRange: 'Dano à distância',
  rangedHitChance: 'Precisão à distância',
  attackRange: 'Alcance',
  skillAsDamageAutoAttack: 'Perícia como dano',
  skillAsDamageSpells: 'Perícia como dano de magia',
  skillAsHealingSpells: 'Perícia como cura',
  alphaStrike: 'Alpha strike',
  omegaStrike: 'Omega strike',
  armorPenetration: 'Penetração de armadura',
  elementalPierce: 'Perfuração elemental',
};

const SKILL_LABEL = {
  magic: 'magic level',
  shielding: 'escudo',
  distance: 'distância',
  sword: 'espada',
  club: 'clava',
  axe: 'machado',
  fist: 'punho',
  fishing: 'pesca',
};

/** "+3% de life leech", "+1 de espada" — do jeito que o client escreve. */
function perkText(perk) {
  const label = PERK_LABEL[perk.type] ?? perk.type;
  const skill = perk.skill ? ` de ${SKILL_LABEL[perk.skill] ?? perk.skill}` : '';
  // Valor abaixo de 1 é percentual; acima é ponto cheio.
  const value = perk.value < 1 && perk.value > 0 ? `+${(perk.value * 100).toFixed(perk.value < 0.01 ? 1 : 0)}%` : `+${perk.value}`;
  return `${value} ${label}${skill}`.trim();
}

export function openProficiency() {
  ctx.tabs.profSkill ??= 'all';
  ctx.tabs.profHands ??= 'all';
  ctx.tabs.profOwned ??= 'all';
  ctx.send({ t: 'proficiency' });

  ctx.openModal('Proficiência de arma', (body) => {
    const draw = () => {
      body.innerHTML = '';
      renderProficiency(body);
    };
    ctx.redraw = draw;
    /*
     * ---- Esta tela só renasce quando as ESCOLHAS mudam ----
     *
     * Era a tela do report: "vou escolher perk da proficiência da arma, fica
     * difícil, pq a tela fica re-renderizando o tempo todo". Medido caçando,
     * ela renascia 0,40 vez por segundo — e cada renascimento troca o
     * `innerHTML` inteiro debaixo do dedo.
     *
     * O culpado era a experiência: ela sobe a cada bicho morto, entrava na
     * assinatura global e refazia o painel junto. Mas a experiência não muda
     * NENHUMA das escolhas da tela — muda um número e a largura de uma barra.
     * Aqui ficou só o que troca o que se pode clicar: a arma, o nível dela, os
     * perks já escolhidos e os filtros da coluna da esquerda.
     */
    ctx.redrawKey = () => {
      const v = ctx.state.character?.proficiency;
      return [
        v?.itemId ?? '-',
        v?.level ?? 0,
        v?.max ?? 0,
        v?.equipped ? 1 : 0,
        (v?.levels ?? []).map((passo) => `${passo.unlocked ? 1 : 0}:${passo.chosen ?? '-'}`).join(','),
        (ctx.state.proficiencyList ?? []).length,
        ctx.tabs.profSkill, ctx.tabs.profHands, ctx.tabs.profOwned, ctx.tabs.profSearch ?? '',
      ].join('|');
    };
    /*
     * E a barra de XP acompanha o quadro a quadro SEM refazer nada: dois textos
     * e uma largura. É o que a pessoa quer ver subindo enquanto caça, e é a
     * única parte da tela que precisava daquele redesenho todo.
     */
    ctx.aoVivo = () => {
      const v = ctx.state.character?.proficiency;
      if (!v) return;
      const numero = body.querySelector('.prof-xp b');
      if (numero) numero.textContent = `${money(v.experience)} / ${money(v.next)}`;
      const pct = body.querySelector('.prof-progress-label b');
      if (pct) pct.textContent = `${v.percent.toFixed(1)}%`;
      const cheio = body.querySelector('.prof-progress > i');
      if (cheio) cheio.style.width = `${Math.max(0, Math.min(100, v.percent))}%`;
    };
    draw();
  });
}

/** Recorte de 64x64 da folha de ícones do client para aquele tipo de perk. */
function perkIcon(perk, size = 34) {
  const node = document.createElement('i');
  node.className = 'perk-icon';
  node.style.width = `${size}px`;
  node.style.height = `${size}px`;
  if (!perk.icon) return node;

  const scale = size / 64;
  node.style.backgroundImage = `url(/client/assets/proficiency/${perk.icon.sheet}.png)`;
  node.style.backgroundPosition = `${-perk.icon.x * scale}px ${-perk.icon.y * scale}px`;
  // A folha inteira é escalada junto, senão o recorte sai de outro ícone.
  node.style.backgroundSize = 'auto 200%';
  node.style.backgroundSize = `${SHEET_WIDTH[perk.icon.sheet] ? SHEET_WIDTH[perk.icon.sheet] * scale : 'auto'}px auto`;
  return node;
}

// Largura de cada folha, para escalar o recorte sem cortar o vizinho.
const SHEET_WIDTH = {
  'icons-0': 1216, 'icons-1': 448, 'icons-2': 448, 'icons-3': 1344, 'icons-4': 512,
  'icons-5': 512, 'icons-6': 512, 'icons-7': 512, 'icons-8': 448, 'icons-9': 1280,
  'icons-weaponmastery-elementalPiercing': 448,
};

const SKILL_FILTER = { all: 'Todas', sword: 'Espada', axe: 'Machado', club: 'Clava', distance: 'Distância', fist: 'Punho', magic: 'Mágica' };

/*
 * Proficiência de arma.
 *
 * Duas colunas: a esquerda é a vitrine — busca, filtros e a grade com todas as
 * armas que têm proficiência, as que o personagem carrega marcadas e na frente.
 * A direita é a ficha da arma escolhida: cabeçalho com o grupo, a barra de
 * experiência com a porcentagem, e uma carta por nível com os perks.
 */
function renderProficiency(body) {
  const { state, send } = ctx;
  const view = state.character.proficiency;
  const list = state.proficiencyList ?? [];

  const layout = el('div', 'prof-layout');

  // ---- coluna da esquerda: escolher a arma ----
  const left = el('div', 'prof-side');

  const search = document.createElement('input');
  search.type = 'search';
  search.className = 'search';
  search.placeholder = 'buscar arma...';
  search.value = ctx.tabs.profSearch ?? '';
  search.oninput = () => {
    ctx.tabs.profSearch = search.value;
    ctx.redraw();
  };
  left.append(search);

  const row = el('div', 'prof-filters');
  const seletor = (options, key) => {
    const node = document.createElement('select');
    for (const [id, label] of Object.entries(options)) {
      const option = document.createElement('option');
      option.value = id;
      option.textContent = label;
      node.append(option);
    }
    node.value = ctx.tabs[key];
    node.onchange = () => {
      ctx.tabs[key] = node.value;
      ctx.redraw();
    };
    return node;
  };
  row.append(
    seletor(SKILL_FILTER, 'profSkill'),
    seletor({ all: '1H e 2H', one: 'Uma mão', two: 'Duas mãos' }, 'profHands'),
    seletor({ all: 'Todas as armas', owned: 'Só as minhas' }, 'profOwned')
  );
  left.append(row);

  const term = (ctx.tabs.profSearch ?? '').trim().toLowerCase();
  const weapons = list.filter((entry) => {
    if (term && !`${entry.name} ${entry.proficiency}`.toLowerCase().includes(term)) return false;
    if (ctx.tabs.profSkill !== 'all' && entry.skill !== ctx.tabs.profSkill) return false;
    if (ctx.tabs.profHands === 'one' && entry.twoHanded) return false;
    if (ctx.tabs.profHands === 'two' && !entry.twoHanded) return false;
    if (ctx.tabs.profOwned === 'owned' && !entry.owned) return false;
    return true;
  });

  const grid = el('div', 'prof-weapons');
  /*
   * No telefone a grade vem em páginas: eram as 678 armas desenhadas de uma
   * vez (1.434 elementos, cada uma com o seu canvas), e só umas vinte cabem na
   * tela. "Mostrar mais" acrescenta a próxima página. No computador segue
   * inteira, como era.
   */
  const PAGINA_DE_ARMAS = 60;
  const limite = ehTelefone() ? (ctx.tabs.profLimite ?? PAGINA_DE_ARMAS) : Infinity;
  for (const entry of weapons.slice(0, limite)) {
    const cell = el('button', `prof-weapon${entry.equipped ? ' equipped' : ''}${entry.owned ? ' owned' : ''}`);
    cell.setAttribute('aria-selected', String(view?.itemId === entry.itemId));
    cell.append(itemCanvas(entry.itemId, 32));
    if (entry.level) cell.append(el('i', 'prof-weapon-level', String(entry.level)));
    tipFor(
      cell,
      entry.itemId,
      `Grupo: ${entry.proficiency} — nível ${entry.level}${entry.owned ? '' : ' · você não tem esta arma'}`
    );
    cell.onclick = () => {
      // Escolheu: no telefone a ficha da arma volta a ocupar a tela.
      ctx.tabs.profNaLista = false;
      send({ t: 'proficiency', itemId: entry.itemId });
    };
    grid.append(cell);
  }
  if (!weapons.length) grid.append(el('p', 'empty', 'nenhuma arma com esse filtro'));
  left.append(grid);
  if (weapons.length > limite) {
    const mais = el('button', 'prof-mais', `Mostrar mais (${weapons.length - limite} restantes)`);
    mais.type = 'button';
    mais.onclick = () => {
      ctx.tabs.profLimite = limite + PAGINA_DE_ARMAS;
      ctx.redraw();
    };
    left.append(mais);
  }
  left.append(el('em', 'prof-count', `${weapons.length} de ${list.length} armas`));
  layout.append(left);

  // ---- coluna da direita: a ficha da arma ----
  const right = el('div', 'prof-tree');
  /*
   * No telefone: a ficha da arma (a equipada, de saída) ocupa a tela, e
   * "← Armas" mostra a grade para trocar (lista-detalhe.mjs).
   */
  const mostrarAMetade = () =>
    listaDetalhe(layout, right, {
      id: 'proficiencia',
      rotulo: '← Armas',
      escolhido: !!view && !ctx.tabs.profNaLista,
      voltar: () => {
        ctx.tabs.profNaLista = true;
        ctx.redraw();
      },
    });
  if (!view) {
    right.append(el('p', 'empty', 'Escolha uma arma à esquerda, ou equipe uma que tenha proficiência.'));
    layout.append(right);
    body.append(layout);
    mostrarAMetade();
    return;
  }

  const cabeca = el('div', 'prof-head');
  const arte = el('div', 'prof-art');
  arte.append(itemCanvas(view.itemId, 44));
  cabeca.append(arte);

  const identidade = el('div', 'prof-id');
  identidade.append(el('b', null, view.itemName));
  // A proficiência é de um grupo de armas, não de um item só: "grand sanguine
  // axe" treina a "Grand Sanguine 2H Axe", junto com as outras do grupo. Sem o
  // rótulo, o nome diferente embaixo do item parecia erro.
  identidade.append(el('em', null, view.name));
  const estrelas = el('div', 'prof-stars');
  for (let level = 1; level <= view.max; level++) {
    const star = document.createElement('img');
    star.className = 'prof-star-art';
    // A mesma estrela do prey. A do client vinha em duas resoluções
    // diferentes — a dourada em 5x5, a apagada em 9x10 —, e esticar a de 5px
    // até 16 deixava a acesa borrada ao lado da apagada, que estava nítida.
    star.src = `/client/assets/ui/prey-${level <= view.level ? 'star' : 'nostar'}.png`;
    star.alt = '';
    estrelas.append(star);
  }
  identidade.append(estrelas);
  cabeca.append(identidade);

  const ficha = el('div', 'prof-xp');
  ficha.append(el('span', null, 'XP'), el('b', null, `${money(view.experience)} / ${money(view.next)}`));
  cabeca.append(ficha);
  right.append(cabeca);

  const legenda = el('div', 'prof-progress-label');
  legenda.append(
    el('span', null, view.level >= view.max ? 'Proficiência no máximo' : 'Progresso para o próximo nível'),
    el('b', null, `${view.percent.toFixed(1)}%`)
  );
  const barra = el('div', 'prof-progress');
  const cheio = el('i');
  cheio.style.width = `${Math.max(0, Math.min(100, view.percent))}%`;
  barra.append(cheio);
  right.append(legenda, barra);
  if (!view.equipped) right.append(el('em', 'prof-inactive', 'os perks só valem com esta arma na mão'));

  const tree = el('div', 'prof-columns');
  for (const step of view.levels) {
    const column = el('div', `prof-column${step.unlocked ? ' unlocked' : ''}`);
    const topo = el('div', 'prof-column-head');
    const star = document.createElement('img');
    star.className = 'prof-star-art';
    star.src = `/client/assets/ui/prey-${step.unlocked ? 'star' : 'nostar'}.png`;
    star.alt = '';
    topo.append(star, el('b', null, `Nível ${step.level}`));
    column.append(topo);

    /*
     * ---- QUAL perk foi escolhido ----
     *
     * O dono: "o perk escolhido em proficiência não dá pra saber exatamente qual
     * escolheu, não fica marcado nem nada".
     *
     * A marca existia — o `backdrop` do client dele, atrás do aro — e ela é um
     * halo de dois pixels em volta de uma moldura já cheia de detalhe. Contra um
     * ícone colorido de 48px, dois pixels de brilho não são uma marca.
     *
     * Agora a escolha se lê de três jeitos, e nenhum depende de reparar num
     * detalhe: o escolhido ganha um SELO de confirmação no canto, os irmãos dele
     * apagam (é o contraste que responde "qual?" de relance), e o rodapé diz o
     * nome por extenso.
     *
     * Apagar os não escolhidos é a peça mais forte, e a mais barata: numa coluna
     * de três ícones igualmente acesos, nada distingue o ligado do disponível.
     */
    const escolhas = el('div', 'prof-perks');
    const jaEscolheu = step.chosen != null;
    for (const perk of step.perks) {
      const escolhido = step.chosen === perk.slot;
      const option = el(
        'button',
        `prof-perk-slot${escolhido ? ' escolhido' : jaEscolheu ? ' preterido' : ''}`
      );
      option.setAttribute('aria-selected', String(escolhido));
      option.disabled = !step.unlocked;
      // 48px: a medida exata da abertura do aro de 57px (ver `.prof-perk-slot`).
      option.append(perkIcon(perk, 48));
      /*
       * O selo é um filho, e não um `::after` do CSS: assim ele é lido por quem
       * usa leitor de tela junto do `aria-selected`, e some sozinho ao trocar.
       */
      if (escolhido) option.append(el('i', 'prof-perk-selo', '✓'));
      option.title = escolhido ? `Escolhido — ${perkText(perk)}` : perkText(perk);
      option.onclick = () => send({ t: 'proficiency', action: 'perk', itemId: view.itemId, level: step.level, slot: perk.slot });
      escolhas.append(option);
    }
    column.append(escolhas);

    const chosen = step.perks.find((perk) => perk.slot === step.chosen);
    /*
     * "Escolhido:" na frente, e não só o texto do perk.
     *
     * O rodapé mostrava a mesma frase que o balão de qualquer um dos três — lida
     * sozinha, ela parecia a descrição do que está debaixo do mouse, e não a
     * decisão que já foi tomada.
     */
    const rodape = el('em', `prof-column-foot${chosen ? ' tem' : ''}`);
    if (chosen) {
      rodape.append(el('b', null, 'Escolhido: '), document.createTextNode(perkText(chosen)));
    } else {
      rodape.textContent = step.unlocked ? 'escolha um perk' : 'trancado';
    }
    column.append(rodape);
    tree.append(column);
  }
  right.append(tree);
  layout.append(right);
  body.append(layout);
  mostrarAMetade();
}

// ---------- charms do bestiary ----------

/*
 * ---- O LOBBY DA ARENA ----
 *
 * "à esquerda de Mercado você vai criar um ícone chamado Arena... que ao clicar
 *  aparece tipo um lobby que eu consigo desafiar alguém pra um x1."
 *
 * Ele responde três perguntas, na ordem em que elas são feitas: onde se luta,
 * quem está disponível agora, e como estou eu. O ranking fecha a tela porque é
 * o que se olha depois, e não antes.
 *
 * ---- Quem aparece na lista ----
 *
 * Só quem PODE ser desafiado neste instante — level suficiente, na cidade e sem
 * nada em andamento. A conta é a mesma que o servidor faz na hora de aceitar o
 * convite (ver `barra`, no comando `arena`), e isso não é repetição à toa: uma
 * lista que oferece o que o servidor vai recusar é um botão que dá erro, e um
 * botão que dá erro é pior do que um botão que não está lá.
 */
/*
 * ---- O SELO DA PATENTE ----
 *
 * "obviamente a pessoa tem que começar no bronze e mostrar o elo dela no lobby."
 *
 * O desenho vem do arquivo, o nome e a cor vem do servidor (ver
 * `patentes-de-arena.mjs`). A escada NAO e' repetida aqui de proposito: uma
 * segunda copia dos sete cortes no cliente seria a segunda versao da verdade, e
 * um dia as duas discordariam sobre onde comeca o Ouro.
 *
 * `onerror` tirando a imagem e deixando o nome: enquanto um desenho nao existir,
 * le-se "Bronze" — que e' melhor do que um quadrado quebrado.
 */
function seloDaPatente(patente, tamanho = 20) {
  if (!patente) return null;
  const caixa = el('span', 'arena-patente');
  if (patente.cor) caixa.style.setProperty('--patente-cor', patente.cor);
  const img = document.createElement('img');
  img.src = `/client/assets/icons/patente-${patente.id}.png`;
  img.alt = '';
  img.width = tamanho;
  img.height = tamanho;
  img.onerror = () => img.remove();
  caixa.append(img, el('b', null, patente.nome));
  return caixa;
}

/** A moeda da arena, com o desenho dela. Ela nao e' item: so aparece aqui. */
function moedaDaArena(quantas, tamanho = 18) {
  const caixa = el('span', 'arena-moeda');
  const img = document.createElement('img');
  img.alt = '';
  img.width = tamanho;
  img.height = tamanho;
  arteTeimosa(img, '/client/assets/icons/arena-moeda.png');
  caixa.append(img, el('b', null, String(quantas ?? 0)));
  return caixa;
}

export function openArena() {
  ctx.send({ t: 'arena' });
  /*
   * A janela nasce sempre no LOBBY, e não onde ficou da última vez.
   *
   * A aba de loja é um desvio: entra-se nela para gastar e sai-se. Guardar a
   * escolha faria quem comprou uma poção há três dias reabrir a Arena na
   * prateleira, com o lobby e os desafios escondidos atrás de um botão.
   */
  ctx.tabs.arena = 'lobby';
  ctx.openModal(
    /* "renomeie pra arena x1" — e e o que ela e': nao ha outro modo aqui. */
    'Arena x1',
    (body) => {
      const draw = () => {
        body.innerHTML = '';
        renderArena(body);
      };
      ctx.redraw = draw;
      draw();
    },
    null,
    /*
     * A variante existe para o CSS poder dar a esta janela o fundo do mapa e a
     * largura dela. Ver `.modal-box.arena` em `style.css`.
     */
    'arena',
  );
}

/*
 * ---- AS REGRAS SAEM DA TELA E ENTRAM NUM `?` ----
 *
 * O dono: "em vez das informaçoes fica ali exposta ocupando espaço, coloca um
 * interrogaçao que vai ter as informaçoes."
 *
 * Ele tem razão e o motivo é medível: as seis regras ocupavam 150 pixels de
 * altura no topo da janela, todo dia, para uma informação que se lê UMA vez.
 * Abaixo delas ficavam os desafios, o placar e o ranking — que são o motivo de
 * a tela existir e viviam empurrados para fora da dobra.
 *
 * É o mesmo `?` do Baú de Boss, do Baú da Conta e de Chegadas, e de propósito:
 * já é o gesto desta casa para "o que é esta tela".
 */
/* O salto de linha dos balões de várias linhas. Ver `showTexto` em `tooltip.mjs`. */
const SALTO = String.fromCharCode(10);

function regrasDaArena(arena, regras) {
  const minutos = Math.round((regras?.tempoDoPasso ?? 120000) / 60000);
  const passo = Math.round((regras?.passo ?? 0.15) * 100);
  /*
   * ---- SÃO DOIS LEVELS, e o balão dizia o mesmo número para os dois ----
   *
   * `arena.level` é a FORÇA com que se luta lá dentro (500 na Livraria de Fogo,
   * 300 no Skeletinho). O level para ENTRAR é um só para todas as arenas, e vem
   * do servidor em `regras.levelParaEntrar`. Ver a nota em `arena-x1.mjs`.
   *
   * O texto usava `arena.level` nos dois lugares. Na Livraria os dois números
   * calham de ser 500 e ninguém notava; no Skeletinho o balão dizia "Level 300
   * para entrar", e um level 400 que lesse isso concluiria, com razão, que a
   * tela está quebrada — porque o servidor o recusa.
   */
  const forca = arena?.level ?? 400;
  const entrada = regras?.levelParaEntrar ?? forca;
  /*
   * A primeira linha vira CABEÇALHO do balão (ver `showTexto`, em
   * `tooltip.mjs`): num texto de sete linhas, sem ela a primeira regra sairia
   * em negrito e maior que as outras seis, como se fosse a mais importante.
   */
  /*
   * ---- O PRÊMIO DA SEMANA, tirado da tabela que PAGA ----
   *
   * "no interrogação tem que informar melhor que os tops semanal ganham os
   *  bônus e etc."
   *
   * `premiosDoPodio` é a mesma tabela que o servidor usa para pagar. Três
   * números escritos à mão aqui seriam a única parte da tela capaz de mentir
   * sobre quanto o primeiro lugar ganha, no dia em que o prêmio mudar.
   */
  const premios = regras?.premiosDoPodio ?? [];
  const escada = premios.length
    ? premios.map((pr) => `${pr.lugar}º leva +${pr.exp}% de experiência e +${pr.loot}% de loot`).join('; ')
    : '1º leva +8%; 2º +5%; 3º +3%';

  return [
    'Como funciona a arena de x1',
    `Level ${entrada} para usar esta aba — é o mesmo para todas as arenas.`,
    `Nesta arena os dois lutam com a força de um level ${forca}, seja qual for o level de vocês.`,
    'Você volta com o seu level, a sua vida e a sua mana exatamente como entrou.',
    'Morrer não custa nada: sem perda de experiência, sem perda de item.',
    'Matar bicho não rende nada: nem experiência, nem loot.',
    `Os bichos da arena ficam ${passo}% mais fortes a cada ${minutos} minutos enquanto ninguém morre.`,
    /*
     * ---- A DERROTA agora TIRA ponto, e isso precisa estar escrito ----
     *
     * "perder na arena x1 tem que perder 1 ponto também, pra ter regressão de
     *  patente também."
     *
     * É a única regra desta tela que tira alguma coisa de quem já tinha, e por
     * isso é a que mais precisa estar dita ANTES de acontecer.
     */
    `Quem morrer primeiro perde. O vencedor ganha ${regras?.pontosPorVitoria ?? 1} ponto e 1 moeda; quem perde devolve 1 ponto (nunca fica abaixo de zero) e 1 moeda.`,
    'Sair no meio da luta conta como derrota.',
    /*
     * ---- A TEMPORADA, que é o que faz a patente ----
     *
     * Quatro linhas, e as quatro respondem perguntas que a tela não respondia:
     * até quando vale o que eu fiz, o que eu ganho por estar no topo, onde esse
     * ganho aparece, e o que acontece com quem chega ao último degrau.
     */
    'O ranking e a patente são DA SEMANA: os pontos valem até sexta-feira às 18h, e nessa hora a tabela zera e todo mundo volta ao Bronze com zero — inclusive quem está offline.',
    `Quem está no topo leva bônus nas caçadas normais: ${escada}. O bônus é de quem está no topo AGORA, então ele muda durante a semana e some de todo mundo no reset.`,
    'O bônus de experiência aparece na régua da barra de XP, junto dos outros.',
    'A última patente não tem teto de pontos: dá para continuar somando como Lenda, e é isso que desempata dois Lendas na tabela.',
    'O seu total de vitórias de sempre continua sendo contado à parte: ele não zera, mas também não é o que faz a patente.',
    /*
     * As duas regras novas entram aqui, e não numa tela à parte: são as duas
     * que fazem um botão de Desafiar sumir ou recusar, e é neste `?` que se vem
     * procurar por quê.
     */
    `Cada duelo custa ${regras?.custoDoTicket ?? 1} ticket de arena. Você ganha +${regras?.ticketsPorDia ?? 5} por dia e acumula até ${regras?.tetoDeTickets ?? 10} — o contador fica no canto de cima, à esquerda.`,
    'Personagens da mesma conta, ou de dois jogos abertos no mesmo endereço de internet, não podem duelar entre si: o x1 vale ponto de arena.',
  ].join('\n');
}

function renderArena(body) {
  const view = ctx.state.arena;
  if (!view) return void body.append(el('p', 'empty', 'Carregando as arenas...'));

  /*
   * ---- QUAL arena ----
   *
   * Eram `arenas[0]` e pronto, enquanto só havia uma. A segunda chegou
   * (Skeletinho) e a escolha passou a existir: o desafio carrega um `arenaId`,
   * e o servidor já mandava a lista inteira desde o primeiro dia — era só a
   * tela que desenhava a primeira e ignorava o resto.
   *
   * A escolha mora em `ctx.tabs` junto da aba, e não numa variável deste
   * módulo, porque é disso que ela é: um pedaço de onde o jogador está dentro
   * da janela. Se a arena lembrada sumir do servidor, cai na primeira.
   */
  const arenas = view.arenas ?? [];
  const arena = arenas.find((a) => a.id === ctx.tabs.arenaId) ?? arenas[0] ?? null;
  const regras = view.regras ?? {};
  const eu = view.eu ?? {};
  /* O level para USAR a aba, um só para todas. Ver a nota na porta, abaixo. */
  const entrada = regras.levelParaEntrar ?? arena?.level ?? 0;

  /*
   * ---- DOIS FUNDOS, E CADA UM DIZ UMA COISA ----
   *
   * "o fundo com a area a ser desafiado vai ficar atras apenas de onde sera o
   *  preview da arena, pq eu terei varias arenas."
   *
   * Ele estava atrás da janela INTEIRA, e isso só funcionava enquanto houvesse
   * uma arena. Com duas, a janela que mostra a Livraria de Fogo e a Cova do
   * Dragão teria a Livraria pintada por trás das duas — a imagem passaria a
   * mentir sobre metade da tela.
   *
   * Então são duas camadas, com donos diferentes:
   *
   *   a JANELA  ganha um fundo fixo de arena (`client/assets/ui/arena-fundo`),
   *             pintado uma vez e igual para todas. Ele é cenário: diz "isto
   *             aqui é a arena", e não QUAL arena. Mora no CSS, porque não
   *             muda — ver `.modal-box.arena`.
   *
   *   o PREVIEW ganha o mapa daquela arena, desenhado e desfocado (ver
   *             `tools/fundo-da-arena.mjs`). Ele é informação: é o chão que se
   *             vai pisar, e muda a cada arena.
   *
   * A variável vai no bloco do preview e não na caixa da janela, e é essa
   * mudança de dono que faz a segunda arena nascer certa sem mais código.
   */

  /*
   * ---- O CANTO DO CABEÇALHO: o `?` e a Loja ----
   *
   * "a loja vai ser um botao clicavel ao lado do botao de fechar ok, e em vez
   *  das informaçoes fica ali exposta ocupando espaço coloca um interrogaçao."
   *
   * Os dois moram no mesmo canto, ao lado do X, que é onde esta casa já põe as
   * ações de janela (ver `acoesDoModal`). A ordem é Loja, depois `?`: a loja é
   * um lugar aonde se vai, o `?` é uma consulta — e o que se usa mais fica mais
   * longe do X, que é o botão perigoso.
   */
  /* =======================================================================
   * O SELO DE TICKETS, no canto de cima a ESQUERDA
   *
   * "a cada dia cada pessoa recebe 5 tickets para batalhas x1, e acumula no
   *  maximo 10, e a cada batalha que entra consome 1. Coloca la encima na
   *  esquerda ao lado de arena x1 pra mostrar a quantidade de tickets."
   *
   * Ele mora no cabeçalho, e não no corpo, por um motivo que se vê usando: o
   * corpo tem quatro páginas (lobby, loja, ranking, histórico) e o número
   * precisa estar visível nas quatro — dentro do corpo ele sumiria justamente
   * quando o jogador estivesse olhando o ranking e pensando em desafiar
   * alguém.
   *
   * `seloDoModal` é o irmão esquerdo de `acoesDoModal`, e esvazia na chamada:
   * `renderArena` roda a cada redesenho, e sem isso o selo empilharia.
   * ======================================================================= */
  const selo = ctx.seloDoModal?.();
  if (selo && eu.tickets) {
    const t = eu.tickets;
    /*
     * A classe é a leitura de relance, e são três estados e não dois: quem tem
     * 1 ticket precisa saber que é o último ANTES de gastá-lo com a pessoa
     * errada — e "1/10" em dourado não conta isso.
     */
    const estado = t.tem <= 0 ? ' vazio' : t.tem <= (t.custo ?? 1) ? ' ultimo' : t.cheio ? ' cheio' : '';
    const caixa = el('div', `arena-ticket${estado}`);
    caixa.append(el('i', 'arena-ticket-icone'));
    caixa.append(el('b', null, String(t.tem)));
    caixa.append(el('span', null, `/${t.teto}`));
    /*
     * ---- O balão diz PARA QUE SERVE, e não só quantos são ----
     *
     * "ao passar o mouse em cima dos tickets tem que falar o que ele faz, pra
     *  que funciona."
     *
     * Ele dizia "Você tem 3 de 10" — o número que já estava escrito no próprio
     * selo, em letra maior. Quem passa o mouse num número que já leu não quer o
     * número: quer saber o que ele é.
     *
     * Então a primeira linha depois do título é o que o ticket FAZ, e as outras
     * respondem, nesta ordem, as três perguntas seguintes: quanto eu tenho,
     * quando gasta, e de onde vem mais.
     *
     * A linha do "sem ticket" é diferente das outras porque o estado é
     * diferente: ali ele não está informando, está explicando por que os botões
     * de desafiar pararam de funcionar.
     */
    const custo = t.custo ?? 1;
    tipTexto(
      caixa,
      [
        'Ticket de arena',
        'É o que deixa você entrar num duelo de x1: sem ticket, você não consegue desafiar ninguém nem aceitar um desafio.',
        t.tem <= 0
          ? 'Você está sem nenhum. A cota volta na virada do dia.'
          : `Você tem ${t.tem} de ${t.teto}.`,
        `Cada duelo que COMEÇA consome ${custo} — seu e do adversário. Desistir da sala antes de começar não custa nada.`,
        t.cheio
          ? `Você está no máximo. Os +${t.porDia} de amanhã só entram depois de você gastar algum.`
          : `Todo dia entram +${t.porDia}, acumulando até ${t.teto}. Quem não joga não perde a cota — ela junta.`,
      ].join('\n'),
    );
    selo.append(caixa);
  }

  const canto = ctx.acoesDoModal?.();
  if (canto) {
    /*
     * ---- O ícone, com a palavra de volta se ele faltar ----
     *
     * `onerror` devolvendo o TEXTO, e não removendo a imagem e pronto: um botão
     * vazio no canto da janela é pior do que um botão escrito. É a mesma regra
     * do cartaz de hunt, com a diferença de que aqui há o que dizer no lugar.
     */
    const comIcone = (botao, nome) => {
      const arte = document.createElement('img');
      arte.alt = '';
      arte.width = 22;
      arte.height = 22;
      /*
       * Desistindo, a imagem sai e a PALAVRA fica: os tres botoes de pagina ja
       * escrevem o rotulo ao lado, entao um desenho quebrado nao deixa buraco.
       * O `?` nao passa por esta funcao — ele nao tem desenho.
       *
       * E desistir agora e' a SEGUNDA falha, nao a primeira: ver
       * `arte-teimosa.mjs`, que repete uma vez com carimbo. Foi o que faltou em
       * 24/09, quando os icones da loja e do ranking sumiram destes botoes por
       * um 404 de quatro horas guardado no navegador.
       */
      arteTeimosa(arte, `/client/assets/icons/${nome}.png`);
      botao.append(arte);
      return botao;
    };

    /* =====================================================================
     * AS TRÊS PÁGINAS DO CANTO, com ÍCONE E PALAVRA
     *
     * "o icone de loja da arena tem que estar escrito loja, e o de ranking
     *  tambem ... e o historico tem que ser separado de ranking."
     *
     * Eu tinha encolhido os três para discos sem palavra, para a fileira caber
     * encostada no canto. Ele quis a palavra de volta, e está certo: quatro
     * desenhos parecidos em fila — um saco de moedas, um livro, um bestiário e
     * um "?" — não se distinguem de relance, e o balão só aparece depois de
     * parar o mouse em cima.
     *
     * Elas viraram UMA função em vez de três blocos iguais: eram dois, com o
     * histórico ficam três, e o terceiro seria a terceira cópia do mesmo código
     * — a que esquece de acompanhar quando a primeira mudar.
     * ===================================================================== */
    const pagina = (chave, icone, palavra, balao, rotulo) => {
      const nela = ctx.tabs.arena === chave;
      const botao = el('button', `arena-acao${nela ? ' ligado' : ''}`);
      botao.type = 'button';
      botao.setAttribute('aria-label', nela ? 'Voltar para o lobby' : rotulo);
      /* Na volta o desenho é o da própria arena: ele quer dizer "o lobby". */
      comIcone(botao, nela ? 'arena' : icone);
      botao.append(el('span', null, nela ? 'Voltar' : palavra));
      tipTexto(botao, nela ? 'Voltar para o lobby' : balao);
      botao.onclick = () => {
        ctx.tabs.arena = nela ? 'lobby' : chave;
        ctx.redraw?.();
      };
      canto.append(botao);
      return botao;
    };

    pagina(
      'loja',
      'arena-loja',
      'Loja',
      `Loja da arena — você tem ${eu.moedas ?? 0} moeda(s)`,
      'Loja da arena',
    );

    /*
     * ---- Aqui é um "?" e não o ícone de regras ----
     *
     * O `arena-regras.png` foi gerado e está instalado, e chegou a ficar aqui.
     * Ampliado, o botão mostrou por que não podia ficar: desenhado a 16px, a
     * tábua com o ramo de louros vira uma mancha esverdeada sem forma. É
     * exatamente a reprovação que o próprio arquivo de prompts manda fazer
     * ("reduza até o tamanho de uma unha; se virar uma mancha, o problema é
     * detalhe demais").
     *
     * E o dono pediu um "?" com todas as letras: "em vez das informaçoes fica
     * ali exposta ocupando espaço coloca um interrogaçao". Um "?" lê em
     * qualquer tamanho, em qualquer tela, e não precisa de arquivo.
     *
     * O ícone fica no disco para o dia em que as regras tiverem um botão grande
     * ou uma página — ali ele tem espaço para ser o que é.
     */
    /*
     * ---- O RANKING virou página, atrás de um troféu ----
     *
     * "em vez do ranking de arena estar ali embaixo da pagina faz um trofeu
     *  clicavel ao lado de loja."
     *
     * Ele era a última seção de uma lista comprida: quem abre o lobby abre para
     * lutar, e o placar ficava abaixo da dobra — visto por quem rolava até o
     * fim, que é quem menos precisava dele. Como página, ele cabe inteiro na
     * tela e o lobby deixa de precisar de rolagem.
     */
    pagina('ranking', 'arena-regras', 'Ranking', 'Os dez que mais venceram na arena', 'Ranking da arena');

    /*
     * ---- O HISTÓRICO É UMA PÁGINA, e não o rodapé do ranking ----
     *
     * "o historico tem que ser separado de ranking."
     *
     * Ele nasceu embaixo da tabela porque as duas falam da arena. Só que as duas
     * respondem perguntas diferentes — "quem é bom" e "o que aconteceu" — e
     * juntas faziam uma página de rolar: o pódio, dez linhas e mais vinte
     * batalhas. Separadas, cada uma cabe inteira na janela, que é a promessa
     * desta tela desde que ele pediu para não rolar.
     *
     * O bestiário como desenho é escolha dele, e casa: ali também se consulta o
     * que já passou.
     */
    pagina('historico', 'bestiary', 'Histórico', 'As últimas batalhas do servidor', 'Histórico de batalhas');

    const ajuda = el('button', 'arena-acao so-icone', '?');
    ajuda.type = 'button';
    ajuda.setAttribute('aria-label', 'Como funciona a arena');
    tipTexto(ajuda, regrasDaArena(arena, regras));
    canto.append(ajuda);
  }

  /* As três são páginas inteiras, e não seções no fim de uma lista. */
  if (ctx.tabs.arena === 'loja') return void renderLojaDaArena(body, view);
  if (ctx.tabs.arena === 'ranking') return void renderRankingDaArena(body, view);
  if (ctx.tabs.arena === 'historico') return void renderHistoricoDaArena(body, view);

  /* ---- A arena, e o que vale dentro dela ---- */
  const ficha = el('section', 'arena-lobby-ficha');
  if (!arena) {
    ficha.append(el('p', 'empty', 'Nenhuma arena instalada.'));
  } else {
    /*
     * ---- O CABEÇALHO DA ARENA ----
     *
     * O nome grande, o level de entrada ao lado e a descrição embaixo. O cartaz
     * pintado que ficava aqui saiu: a janela INTEIRA agora tem o fundo da arena
     * por trás (ver a nota sobre `--arena-fundo`, mais acima), e uma faixa com
     * a mesma paisagem em cima de um fundo com a mesma paisagem seria a imagem
     * duas vezes, uma delas atrapalhando.
     *
     * O arquivo do cartaz continua no disco (`<id>.webp`): ele serve para o dia
     * em que houver uma LISTA de arenas, onde cada uma precisa de um card.
     */
    /*
     * O PREVIEW: o nome, a porta, a descrição e os bichos, todos em cima do
     * mapa daquela arena. É o bloco que vira card quando houver uma lista de
     * arenas — por isso ele é um elemento próprio e carrega o próprio fundo,
     * em vez de se apoiar na janela.
     */
    /*
     * ---- A tira de arenas ----
     *
     * Só aparece com mais de uma: com uma arena ela seria uma aba solitária
     * dizendo o que o título logo abaixo já diz.
     *
     * Cada uma leva o level na etiqueta porque é o que decide se vale clicar —
     * a Livraria é de 400 e a próxima pode ser de 800, e descobrir isso só
     * depois de escolher seria um clique jogado fora.
     */
    if (arenas.length > 1) {
      const tira = el('div', 'arena-lobby-tira');
      for (const uma of arenas) {
        const aba = el('button', `arena-lobby-aba${uma.id === arena.id ? ' ligada' : ''}`);
        aba.type = 'button';
        aba.append(el('b', null, uma.nome));
        aba.append(el('span', null, `lv ${uma.level}`));
        aba.onclick = () => {
          ctx.tabs.arenaId = uma.id;
          ctx.redraw?.();
        };
        tira.append(aba);
      }
      ficha.append(tira);
    }

    const preview = el('div', 'arena-lobby-preview');
    fundoTeimoso(preview, '--arena-fundo', `/client/assets/arenas/${arena.id}-fundo.webp`);

    /*
     * ---- DUAS COLUNAS ----
     *
     * "aqui na imagem onde to com o mouse encima tem que ter algo escrito ne?
     *  talvez o ranking e as vitorias?"
     *
     * O vazio à direita não era um espaço reservado: era a fila de bichos
     * acabando cedo. A Livraria tem sete espécies e enche a linha; o Skeletinho
     * tem três e sobrava metade do card com o fundo bonito e nada escrito. Um
     * espaço que muda de tamanho conforme a arena não é desenho, é sobra.
     *
     * O que entra ali é o SEU retrospecto — patente, pontos, vitórias, derrotas
     * —, que antes era uma seção inteira logo abaixo. Ele não é conteúdo novo
     * inventado para tapar buraco: é uma seção que saiu de baixo e subiu para o
     * lugar onde já havia espaço. A página encurta uma seção e o card deixa de
     * ter metade vazia.
     */
    const corpo = el('div', 'arena-lobby-preview-corpo');
    const esquerda = el('div', 'arena-lobby-preview-esq');

    /*
     * ---- DOIS levels, e eles dizem coisas diferentes ----
     *
     * "o level minimo pra participar das arenas seria level 500 (mas NAO ALTERE
     *  os nivel cadastrado das arena)."
     *
     *   para ENTRAR  o level que o jogador precisa TER. Um só para todas as
     *                arenas (`regras.levelParaEntrar`, hoje 500).
     *   para LUTAR   a força com que os dois lutam lá dentro (`arena.level`:
     *                500 na Livraria, 300 no Skeletinho).
     *
     * Os dois na tela porque a diferença é surpreendente: sem a segunda linha,
     * um level 500 entraria no Skeletinho e se veria com 300 sem entender por
     * quê — e ia achar que era defeito.
     */
    const cabeca = el('div', 'arena-lobby-cabeca-arena');
    cabeca.append(el('h3', 'arena-lobby-nome', arena.nome));
    const porta = el('span', 'arena-lobby-porta');
    porta.append(el('b', null, `level ${entrada}`));
    porta.append(el('span', null, 'para entrar'));
    if ((eu.level ?? 0) < entrada) porta.classList.add('falta');
    cabeca.append(porta);
    esquerda.append(cabeca);
    esquerda.append(
      el('p', 'shop-note', `Lá dentro os dois lutam com a força de um level ${arena.level}. ${arena.blurb ?? ''}`.trim()),
    );

    /*
     * ---- Quem mora lá dentro ----
     *
     * O desenho do bicho e quantos há de cada um. É a informação que decide se
     * vale entrar: uma arena de 85 Burning Book é outra briga que uma de 7 Ink
     * Blob, e o nome sozinho não diz isso.
     */
    /*
     * ---- O NOME EM CIMA, A COR CERTA E AS ESTRELAS ----
     *
     * "a cor dos bixos estao errados ok, e deixa o nome do bixo encima da sprite
     *  dele igual como é em hunts sabe, e a estrela de dificuldade."
     *
     * A cor estava errada por um motivo especifico e ja conhecido nesta base: um
     * outfit humanoide e' desenhado em DUAS camadas — o desenho, quase branco, e
     * uma mascara que diz onde pintar cabeca, corpo, pernas e pes. Sem as cores
     * a mascara nao e' aplicada e todos saem com a mesma roupa clara. Era o
     * `outfitCanvas(bicho.look, null, ...)` daqui: `null` no lugar da paleta.
     *
     * A resposta nao e' mandar a cor do servidor — e' usar a MESMA funcao que o
     * card de Aventuras usa. `figuraDaCriatura` tira a paleta do bestiario, cai
     * no sprite de ITEM para os bichos sem outfit (Percht Queen, Brain Head) e
     * ja desenha as estrelas de dificuldade embaixo. Tres defeitos que o dono
     * viu separados sao um so' conserto: chamar o que ja existia.
     *
     * O nome vai por cima, como no card de hunt. Numa fileira de sete bichos o
     * numero sozinho nao diz qual e' qual, e passar o mouse para descobrir e' o
     * gesto que a tela devia poupar.
     */
    const bichos = arena.bichos ?? [];
    if (bichos.length) {
      const fila = el('div', 'arena-lobby-bichos');
      for (const bicho of bichos) {
        const caixa = el('div', 'arena-lobby-bicho');
        caixa.append(el('span', 'arena-lobby-bicho-nome', bicho.nome));
        caixa.append(figuraDaCriatura(bicho, ctx.state.catalog?.bestiary, 34));
        caixa.append(el('b', null, `x${bicho.quantos}`));
        tipTexto(caixa, `${bicho.nome} — ${bicho.quantos} na arena`);
        fila.append(caixa);
      }
      esquerda.append(fila);
    }
    corpo.append(esquerda);

    /*
     * ---- A coluna da direita: o seu retrospecto ----
     *
     * A patente grande em cima (é a imagem que dá vontade de lutar de novo), o
     * que falta para a próxima logo abaixo, e os três números que contam a
     * história: pontos, vitórias e derrotas.
     *
     * O "faltam 7 para Prata" vai junto pela mesma razão de sempre: a patente
     * sozinha diz ONDE a pessoa está e não dá vontade de nada. O que falta, dá.
     */
    const direita = el('div', 'arena-lobby-preview-eu');
    direita.append(el('h4', 'arena-lobby-eu-titulo', 'Seu retrospecto'));

    const selo = seloDaPatente(eu.patente, 40);
    if (selo) {
      selo.classList.add('arena-patente-grande');
      direita.append(selo);
    }
    if (eu.patente?.proxima) {
      direita.append(
        el(
          'span',
          'arena-lobby-eu-falta',
          eu.patente.proxima.falta === 1
            ? `falta 1 ponto para ${eu.patente.proxima.nome}`
            : `faltam ${eu.patente.proxima.falta} para ${eu.patente.proxima.nome}`,
        ),
      );
    } else if (eu.patente) {
      /*
       * ---- No TOPO não há "faltam 7 para o próximo" ----
       *
       * "a última patente não pode ter teto máximo de pontos, pra não rolar
       *  empate."
       *
       * Não tem, e aqui é onde isso se vê: no último degrau a linha do que falta
       * não existiria, e a tela ficaria muda justamente para quem mais joga.
       * No lugar dela vai o número cru, que é o que continua subindo — e é ele
       * que separa dois Lendas na tabela.
       */
      direita.append(
        el(
          'span',
          'arena-lobby-eu-falta',
          `${eu.patente.pontos ?? 0} ponto(s) na semana — o topo não tem teto`,
        ),
      );
    }

    /*
     * ---- O placar: a SEMANA em cima, a carreira embaixo ----
     *
     * `Pontos` era o total da vida, e ficava debaixo de uma patente que agora
     * sai da semana: "Bronze" com 300 pontos escritos logo abaixo. São números
     * diferentes e passaram a precisar de nomes diferentes.
     */
    const placar = el('div', 'arena-lobby-eu-placar');
    for (const [rotulo, valor, balao] of [
      ['Na semana', eu.pontos ?? 0, 'Os pontos desta semana. É deles que sai a sua patente, e eles zeram sexta às 18h.'],
      ['Vitórias', eu.vitorias ?? 0, 'Todas as vitórias que você já teve na arena. Não zeram nunca.'],
      ['Derrotas', eu.derrotas ?? 0, 'Todas as derrotas. Cada uma tira um ponto da semana, nunca abaixo de zero.'],
    ]) {
      const linha = el('div', null);
      linha.append(el('b', null, String(valor)));
      linha.append(el('span', null, rotulo));
      if (balao) tipTexto(linha, balao);
      placar.append(linha);
    }
    direita.append(placar);

    const bolso = el('div', 'arena-lobby-eu-moeda');
    bolso.append(moedaDaArena(eu.moedas, 18));
    bolso.append(el('span', null, (eu.moedas ?? 0) === 1 ? 'moeda' : 'moedas'));
    direita.append(bolso);

    /*
     * O aviso de level fica AQUI e não numa seção à parte: ele fala sobre esta
     * arena e sobre este jogador, que são as duas coisas que este card junta.
     * Trocar de aba lá em cima o acende e o apaga na hora.
     */
    if ((eu.level ?? 0) < entrada) {
      direita.append(el('p', 'arena-lobby-eu-trava', `Você precisa de level ${entrada} para a arena de x1.`));
    }

    corpo.append(direita);
    preview.append(corpo);
    ficha.append(preview);
  }
  body.append(ficha);

  /* =======================================================================
   * A SALA DE DUELO
   *
   * "embaixo apareceria a esquerda e a direita quem esta no duelo, e ambos tem
   *  que da pronto antes de começar."
   *
   * Ela vem logo abaixo do preview da arena, e enquanto ela existe o resto do
   * lobby SOME — a lista de gente, os convites, quem está lutando. Não é
   * economia de espaço: é que nada daquilo pode ser feito daqui. Quem está numa
   * sala não desafia ninguém; ele confirma ou sai.
   * ======================================================================= */
  /* `salaDoDuelo` e nao `sala`: a secao "Na cidade" ja usa esse nome. */
  const salaDoDuelo = view.sala;
  if (salaDoDuelo) {
    const caixa = el('section', 'arena-sala');
    caixa.append(el('h4', 'arena-sala-titulo', 'Sala de duelo'));

    const ringue = el('div', 'arena-sala-ringue');
    salaDoDuelo.lados.forEach((lado, i) => {
      if (i) ringue.append(el('span', 'arena-sala-versus', '×'));

      const card = el('div', `arena-sala-lado${lado.pronto ? ' pronto' : ''}${lado.souEu ? ' eu' : ''}`);

      const palco = el('div', 'arena-sala-boneco');
      if (lado.outfit?.type && outfitInfo(lado.outfit.type)) {
        /*
         * `2` e o SUL — de frente para quem olha, como em todo card deste jogo
         * (o da party, o do lobby, o do bestiario). Aqui estava `3`, que e o
         * oeste: os dois duelistas apareciam de perfil, virados para a esquerda.
         * Era um erro de dedo meu — o quarto parametro de `outfitCanvas` e a
         * direcao, e nao a escala.
         */
        palco.append(outfitCanvas(lado.outfit.type, lado.outfit, 64, 2, true));
      }
      card.append(palco);

      const nome = el('div', 'arena-sala-nome');
      nome.append(el('b', null, lado.nome));
      const selo = seloDaPatente(lado.patente, 16);
      if (selo) nome.append(selo);
      card.append(nome);
      /*
       * O crachá de LÍDER, e ele não é enfeite: é o botão de começar que tem
       * dono. Sem a marca no card, quem espera não sabe de quem depende, e
       * quem manda não sabe que a vez é dele.
       */
      if (lado.lider) card.append(el('span', 'arena-sala-lider', 'Líder'));
      card.append(el('span', 'arena-sala-level', `level ${lado.level ?? '?'}`));

      /*
       * O estado, em palavra e em cor. Só a cor não basta: "esperando" e
       * "pronto" precisam ser lidos de longe por quem está decidindo se clica.
       */
      const estado = el('span', 'arena-sala-estado');
      if (!lado.online) estado.textContent = 'desconectou';
      else estado.textContent = lado.pronto ? 'Pronto' : 'Esperando';
      if (!lado.online) estado.classList.add('caiu');
      card.append(estado);

      ringue.append(card);
    });
    caixa.append(ringue);

    const euNaSala = salaDoDuelo.lados.find((l) => l.souEu);
    const botoes = el('div', 'arena-sala-botoes');

    /* =====================================================================
     * PRONTO, e depois COMEÇAR
     *
     * "quando as duas pessoas derem pronto nao tem que começar
     *  automaticamente, o lider tem que clicar em começar."
     *
     * São dois gestos e não um. O PRONTO diz "estou aqui"; o COMEÇAR diz
     * "agora". Antes eles eram a mesma coisa para quem clicasse por último — e
     * quem clica por último não escolhe a hora, ele só confirma e a tela já é
     * outra, com a contagem correndo.
     *
     * O botão de começar SUBSTITUI o de pronto quando a sala enche, em vez de
     * aparecer ao lado: dois botões verdes lado a lado, um deles morto, é a
     * receita para clicar no errado.
     * ===================================================================== */
    if (salaDoDuelo.completa) {
      if (salaDoDuelo.podeComecar) {
        const comecar = el('button', 'arena-comecar', 'Começar o duelo');
        comecar.onclick = () => ctx.send({ t: 'arena', action: 'comecar' });
        botoes.append(comecar);
      } else {
        /*
         * Quem não é líder vê uma FRASE e não um botão apagado: um botão que
         * nunca vai acender é um convite a clicar nele repetidamente.
         */
        const espera = el('span', 'arena-sala-espera-lider');
        espera.append(el('b', null, salaDoDuelo.lider ?? 'O líder'));
        espera.append(el('span', null, 'começa o duelo'));
        botoes.append(espera);
      }
    } else {
      const pronto = el('button', 'arena-pronto', euNaSala?.pronto ? 'Aguardando o outro...' : 'Pronto');
      pronto.disabled = !!euNaSala?.pronto;
      if (euNaSala?.pronto) pronto.classList.add('esperando');
      pronto.onclick = () => ctx.send({ t: 'arena', action: 'pronto' });
      botoes.append(pronto);
    }

    const sair = el('button', 'ghost', 'Sair da sala');
    sair.onclick = () => ctx.send({ t: 'arena', action: 'sairDaSala' });
    botoes.append(sair);

    caixa.append(botoes);

    /*
     * O prazo da sala, em segundos. Ele existe porque a sala vence sozinha (ver
     * `VALIDADE_DA_SALA`): sem o número na tela, o jogador que espera não sabe
     * se deve continuar esperando ou sair e desafiar outra pessoa.
     *
     * É um número parado e não um relógio correndo: o quadro chega do servidor
     * a cada mudança, e um `setInterval` aqui teria de ser desligado em toda
     * troca de aba para não vazar. O que importa é a ordem de grandeza.
     */
    if (salaDoDuelo.faltam > 0) {
      caixa.append(el('p', 'shop-note', `A sala se desfaz sozinha em ${Math.ceil(salaDoDuelo.faltam / 1000)}s.`));
    }

    body.append(caixa);
    return;
  }

  /*
   * ---- "Lutando agora" SAIU ----
   *
   * "nao precisa ter la 'lutando agora' sabe? isso nao importa."
   *
   * E ele tem razão: não dá para entrar naquela luta nem assistir a ela. Era
   * uma faixa de informação sobre a qual ninguém age, ocupando espaço numa tela
   * que precisa caber sem rolagem.
   *
   * O servidor CONTINUA mandando `emLuta`, e de propósito: é por ele que a
   * sonda confere que o servidor sabe quem está num duelo — a verdade sai das
   * sessões vivas, e não de um registro paralelo que um dia mente. O campo é
   * barato; o espaço na tela é que não era.
   */

  /* ---- Como estou eu ---- */
  /*
   * A seção "Você" subiu para dentro do preview, na coluna da direita — ver a
   * nota lá em cima. Ela era quatro números grandes ocupando uma faixa inteira
   * logo abaixo de um card com metade vazia.
   */

  /* =======================================================================
   * OS CONVITES, EM PÍLULAS
   *
   * "tambem aparece dentro do modal (mas deixa mais otimizado, ta ocupando uma
   *  linha inteira dentro do modal)."
   *
   * Cada convite era uma seção com título e uma linha de largura cheia — dois
   * convites custavam 130px numa janela que precisa caber sem rolagem, para
   * dizer um nome e oferecer um botão.
   *
   * Agora é uma faixa só, com os recebidos e os enviados lado a lado. O que se
   * perdeu foram os dois títulos; o que diz qual é qual é a COR — verde no que
   * espera a sua resposta, apagado no que espera a do outro.
   * ======================================================================= */
  const recebidos = view.recebidos ?? [];
  const enviados = view.enviados ?? [];
  if (recebidos.length || enviados.length) {
    const faixa = el('section', 'arena-convites');

    for (const convite of recebidos) {
      const pilula = el('div', 'arena-convite chamando');
      pilula.append(el('b', null, convite.de));
      pilula.append(el('span', null, 'desafiou você'));
      const aceitar = el('button', 'arena-desafiar', 'Aceitar');
      aceitar.onclick = () => ctx.send({ t: 'arena', action: 'aceitar', quem: convite.de, arenaId: convite.arenaId });
      pilula.append(aceitar);
      faixa.append(pilula);
    }

    for (const convite of enviados) {
      const pilula = el('div', 'arena-convite esperando');
      pilula.append(el('b', null, convite.para));
      pilula.append(el('span', null, 'ainda não respondeu'));
      const cancelar = el('button', 'ghost', 'Cancelar');
      cancelar.onclick = () => ctx.send({ t: 'arena', action: 'desistir' });
      pilula.append(cancelar);
      faixa.append(pilula);
    }

    body.append(faixa);
  }

  /* =======================================================================
   * A FILA DO LOBBY — quem QUER lutar, e não quem está livre
   *
   * "em vez de ter o desafiar na arena x1 na cidade, tinha que ter uma espécie
   *  de 'alistar-se ao lobby' que ficaria ali aparecendo (...) é melhor assim,
   *  que não depende da pessoa ficar lá tentando desafiar alguém que não tenha
   *  vontade."
   *
   * A lista mostrava todo mundo livre na cidade. Estar livre não é querer
   * duelar, e o botão Desafiar era quase sempre um convite para quem não pediu
   * nada — do outro lado, um cartão que a pessoa fechava sem ler.
   *
   * Agora entra quem clica em ALISTAR-SE, e é por isso que o clique no card não
   * abre convite nenhum: ele abre a sala. Alistar-se já é o sim.
   *
   * ---- O botão é o mesmo nos dois estados ----
   *
   * Entrar e sair da fila no MESMO lugar da tela, e não um botão que aparece e
   * outro que some. Quem se alistou olha para o lugar onde clicou para saber se
   * deu certo — e o que ele precisa ler ali é "você está na fila", não um botão
   * que sumiu.
   * ======================================================================= */
  const gente = view.gente ?? [];
  const naFila = view.euAlistado === true;
  const sala = el('section', 'arena-lobby-gente');

  const cabeca = el('div', 'arena-fila-cabeca');
  cabeca.append(el('h4', 'deposito-titulo', `Na fila — ${gente.length}`));

  const alistar = el('button', naFila ? 'ghost' : 'arena-desafiar', naFila ? 'Sair da fila' : 'Alistar-se ao lobby');
  /*
   * A trava é o level de PARTICIPAR. O servidor recusa de qualquer jeito (ver
   * `barraDaArena`), e o botão apagado evita a viagem de ida e volta só para
   * ler um "não" — mas o balão diz o motivo, senão um botão cinza sem
   * explicação parece tela quebrada.
   */
  const euFaltoNaFila = (eu.level ?? 0) < entrada;
  alistar.disabled = !arena || euFaltoNaFila;
  tipTexto(
    alistar,
    euFaltoNaFila
      ? `você precisa de level ${entrada} para a arena de x1`
      : naFila
        ? 'Sai da fila. Ninguém mais vai poder te escolher para um duelo.'
        : 'Entra na fila do lobby. Quem estiver aqui pode te escolher — e o duelo começa na hora, sem convite.',
  );
  alistar.onclick = () =>
    ctx.send({ t: 'arena', action: naFila ? 'desalistar' : 'alistar', arenaId: arena?.id });
  cabeca.append(alistar);
  sala.append(cabeca);

  if (naFila) {
    sala.append(
      el(
        'p',
        'shop-note',
        'Você está na fila. Quem abrir este lobby vê o seu card e pode começar o duelo a qualquer momento.',
      ),
    );
  }

  if (!gente.length) {
    sala.append(
      el(
        'p',
        'empty',
        naFila
          ? 'Mais ninguém na fila por enquanto. Você fica aqui até alguém chegar — ou até sair.'
          : 'A fila está vazia. Alistar-se põe o seu card aqui para os outros verem.',
      ),
    );
  } else {
    /*
     * ---- Cards com BONECO, e não uma lista de nomes ----
     *
     * "quero tipo um lobby de jogo mesmo."
     *
     * Uma linha de texto responde "quem está livre"; um card responde "com quem
     * eu vou lutar", que é a pergunta que se faz aqui. O boneco é o mesmo que
     * anda na cidade — mesmo outfit, mesmos addons, mesma montaria.
     *
     * Em grade e não empilhados: três por linha cabem sem rolagem, e era a
     * rolagem que fazia o lobby parecer um formulário.
     */
    const grade = el('div', 'arena-lobby-grade');
    for (const quem of gente) {
      const linha = el('div', 'arena-lobby-card');

      const palco = el('div', 'arena-lobby-card-boneco');
      if (quem.outfit?.type && outfitInfo(quem.outfit.type)) {
        palco.append(outfitCanvas(quem.outfit.type, quem.outfit, 48, 2, true));
      }
      linha.append(palco);

      const texto = el('div', 'arena-lobby-card-texto');
      const nome = el('div', 'arena-lobby-card-nome');
      nome.append(el('b', null, quem.nome));
      const dele = seloDaPatente(quem.patente, 16);
      if (dele) nome.append(dele);
      texto.append(nome);
      texto.append(el('span', null, `level ${quem.level} · ${quem.pontos} ponto${quem.pontos === 1 ? '' : 's'}`));
      linha.append(texto);
      /*
       * ---- O punho de "Desafiar" também não entrou ----
       *
       * Ele chegou a entrar e saiu pela MEDIDA: o ícone é uma manopla de ferro
       * escuro, e este botão é verde chapado. A 14px o desenho escuro em cima
       * do verde vira um borrão vertical — não se lê punho, não se lê espada,
       * não se lê nada.
       *
       * Não é culpa do desenho: ele foi pedido para ler sobre fundo escuro, que
       * é onde os outros dois vivem. Clarear no CSS com `filter` resolveria a
       * silhueta e estragaria a arte, e a palavra DESAFIAR já diz tudo o que o
       * botão faz.
       *
       * `arena-desafiar.png` fica instalado: ele serve a um botão grande, ou a
       * um fundo escuro, no dia em que houver um.
       */
      /*
       * ---- "ENFRENTAR", e não "Desafiar" ----
       *
       * A palavra mudou porque o gesto mudou: não há mais convite pendurado
       * esperando resposta. Quem está neste card se alistou, e clicar aqui abre
       * a sala dos dois na hora. "Desafiar" prometeria uma espera que não
       * existe mais.
       */
      const enfrentar = el('button', 'arena-desafiar', 'Enfrentar');
      /*
       * A trava é o level de PARTICIPAR, e ele é um só — então o do outro nunca
       * falha (a lista já corta por ele, no servidor). O que sobra é o meu.
       */
      const euFalto = (eu.level ?? 0) < entrada;
      enfrentar.disabled = !arena || euFalto;
      tipTexto(
        enfrentar,
        euFalto
          ? `você precisa de level ${entrada} para a arena de x1`
          : `Abre a sala de duelo contra ${quem.nome} agora. Ele já se alistou — não há convite a esperar.`,
      );
      enfrentar.onclick = () => ctx.send({ t: 'arena', action: 'enfrentar', quem: quem.nome, arenaId: arena.id });
      linha.append(enfrentar);
      grade.append(linha);
    }
    sala.append(grade);
  }
  body.append(sala);

  /*
   * O ranking saiu daqui e virou página, atrás do troféu do cabeçalho. Ver
   * `renderRankingDaArena`.
   */

}

/*
 * ---- O RANKING DA ARENA, como página ----
 *
 * "em vez do ranking de arena estar ali embaixo da pagina faz um trofeu
 *  clicavel ao lado de loja."
 *
 * A mesma estrutura da loja, e de propósito: as três telas desta janela (lobby,
 * loja, ranking) se alternam pelo mesmo canto e com a mesma anatomia — um
 * cabeçalho e um corpo. Quem aprendeu a sair da loja já sabe sair daqui.
 *
 * O pódio em cima e a tabela embaixo: os três primeiros são a notícia, e o
 * resto é a consulta. Numa lista corrida de dez linhas o primeiro lugar tem o
 * mesmo peso visual do oitavo.
 *
 * ---- DEZ, e com o BONECO de cada um ----
 *
 * "o ranking tem que mostra o top 10, e tem que mostra o addon atual da pessoa
 *  tambem."
 *
 * O desenho é `outfitCanvas` com a `aparenciaDe` que o servidor manda — o mesmo
 * boneco do lobby, da sala de duelo e da cidade. Ele custa um canvas por linha,
 * e é por isso que a lista encolheu de vinte para dez: treze canvas numa página
 * que já tem o pódio é o limite do que cabe sem rolar.
 */
function renderRankingDaArena(body, view) {
  const eu = view.eu ?? {};
  const ranking = view.ranking ?? [];

  const regras = view.regras ?? {};
  const premios = regras.premiosDoPodio ?? [];

  /* =======================================================================
   * O CABEÇALHO DIZ QUE A TABELA É DA SEMANA
   *
   * "esse ranking é semanal, e reseta toda sexta às 18 horas."
   *
   * A frase antiga — "cada vitória vale um ponto, e ele nunca é perdido" —
   * passou a ser falsa para ESTA tabela no instante em que ela virou semanal.
   *
   * E passou a ser falsa para a PATENTE também, que agora sai daqui: "confirma
   * pra mim que quando resetar o ranking semanal todos voltam pra bronze 0
   * pontos". Voltam — é o mesmo número, então é o mesmo reset.
   *
   * O total da vida continua existindo e continua aparecendo ao lado, no balão
   * de cada linha: sem essa distinção escrita, quem tem 300 vitórias de sempre e
   * 2 pontos na semana acharia que perdeu 298.
   * ======================================================================= */
  const cabeca = el('section', 'arena-loja-cabeca');
  cabeca.append(el('h3', 'arena-lobby-nome', 'Ranking da semana'));
  cabeca.append(
    el(
      'p',
      'shop-note',
      'Só os pontos feitos nesta semana: vitória soma 1, derrota tira 1. Ela vira toda sexta às 18h, e aí a tabela zera e todos voltam ao Bronze — o seu total de vitórias de sempre é outro número, e esse não é tocado.',
    ),
  );
  /* Quanto falta para virar, contado do instante que o servidor mandou. */
  if (regras.semanaAcaba) {
    const falta = Math.max(0, regras.semanaAcaba - Date.now());
    const dias = Math.floor(falta / 86_400_000);
    const horas = Math.floor((falta % 86_400_000) / 3_600_000);
    const minutos = Math.floor((falta % 3_600_000) / 60_000);
    cabeca.append(
      el(
        'p',
        'arena-semana-relogio',
        dias > 0
          ? `Zera em ${dias}d ${horas}h — sexta às 18h`
          : `Zera em ${horas}h ${minutos}min — hoje às 18h`,
      ),
    );
  }
  /*
   * O PRÊMIO aparece mesmo com a tabela vazia, e é de propósito: é assim que
   * quem nunca duelou descobre que há o que ganhar. Uma tabela vazia com um
   * "ninguém pontuou ainda" não convida ninguém a nada.
   */
  if (premios.length) {
    const faixa = el('div', 'arena-premios');
    for (const premio of premios) {
      const chip = el('span', `arena-premio lugar-${premio.lugar}`);
      chip.append(el('b', null, `${premio.lugar}º`));
      chip.append(el('span', null, `+${premio.exp}% exp e loot`));
      faixa.append(chip);
    }
    tipTexto(
      faixa,
      [
        'O prêmio do pódio',
        'Quem está no topo da tabela DESTA semana ganha experiência e loot a mais em todas as caçadas.',
        ...premios.map((p) => `${p.lugar}º lugar: +${p.exp}% de experiência e +${p.loot}% de loot.`),
        'O bônus vale enquanto você estiver no pódio: se alguém passar na frente, ele muda de dono na hora.',
        'Na virada da semana a tabela zera e o bônus sai de todo mundo até alguém pontuar de novo.',
      ].join('\n'),
    );
    cabeca.append(faixa);
  }
  body.append(cabeca);

  if (!ranking.length) {
    body.append(
      el('p', 'empty', 'Ninguém pontuou nesta semana ainda. O primeiro x1 abre a tabela — e leva o pódio.'),
    );
  } else {
    const podio = el('div', 'arena-podio');
    ranking.slice(0, 3).forEach((quem, i) => {
      const card = el('div', `arena-podio-card lugar-${i + 1}`);
      card.append(el('span', 'arena-podio-lugar', `${i + 1}º`));
      /*
       * O boneco ANTES do selo: ele é o que se reconhece de longe, e o elo é a
       * legenda dele. Invertidos, três selos iguais em fila seriam a primeira
       * coisa que a tela diz, e eles são a menos específica das duas.
       */
      const palco = el('div', 'arena-podio-boneco');
      if (quem.outfit?.type && outfitInfo(quem.outfit.type)) {
        palco.append(outfitCanvas(quem.outfit.type, quem.outfit, 56, 2, true));
      }
      card.append(palco);
      const selo = seloDaPatente(quem.patente, 30);
      if (selo) card.append(selo);
      card.append(el('b', 'arena-podio-nome', quem.nome));
      card.append(el('span', 'arena-podio-pontos', `${quem.pontos} ponto${quem.pontos === 1 ? '' : 's'}`));
      /*
       * O que este degrau ESTÁ pagando, agora, para quem está nele. É a única
       * informação do pódio que não é vaidade: ela muda a decisão de quem está
       * em quarto sobre duelar mais uma vez hoje.
       */
      const premio = premios[i];
      if (premio) {
        card.append(el('span', 'arena-podio-premio', `+${premio.exp}% exp · +${premio.loot}% loot`));
      }
      podio.append(card);
    });
    body.append(podio);

    if (ranking.length > 3) {
      const tabela = el('section', 'arena-lobby-ranking');
      for (const [i, quem] of ranking.slice(3).entries()) {
        const linha = el('div', `arena-lobby-linha${quem.nome === eu.nome ? ' eu' : ''}`);
        linha.append(el('span', 'arena-lobby-pos', `${i + 4}º`));
        const palco = el('div', 'arena-rank-boneco');
        if (quem.outfit?.type && outfitInfo(quem.outfit.type)) {
          palco.append(outfitCanvas(quem.outfit.type, quem.outfit, 30, 2, false));
        }
        linha.append(palco);
        linha.append(el('b', null, quem.nome));
        const dele = seloDaPatente(quem.patente, 16);
        if (dele) linha.append(dele);
        /*
         * O placar da pessoa entra aqui e não numa coluna nova: "7 pontos" diz
         * a posição, e "4V · 2D" diz como ela chegou lá. Sem o segundo, dois
         * jogadores com sete pontos parecem iguais, e um deles perdeu doze.
         */
        linha.append(
          el('span', 'arena-rank-placar', `${quem.vitorias ?? 0}V · ${quem.derrotas ?? 0}D`),
        );
        const pontos = el('span', null, `${quem.pontos} ponto${quem.pontos === 1 ? '' : 's'}`);
        /*
         * O total de sempre vai no BALÃO e não na linha: ele não é o que ordena
         * esta tabela, e uma segunda coluna de pontos ao lado da que ordena
         * seria lida como se os dois números disputassem a mesma posição.
         */
        tipTexto(
          pontos,
          [
            `${quem.pontos} ponto(s) nesta semana — é o que faz a patente dele`,
            `${quem.vitorias ?? 0}V ${quem.derrotas ?? 0}D na semana`,
            `${quem.pontosTotais ?? quem.pontos} vitórias desde sempre, que não zeram`,
          ].join(SALTO),
        );
        linha.append(pontos);
        tabela.append(linha);
      }
      body.append(tabela);
    }
  }

}

/* =========================================================================
 * AS ÚLTIMAS BATALHAS
 *
 * "tem que ter um historico das ultimas batalhas e quanto tempo durou etc."
 *
 * Ela mora na MESMA página do ranking, abaixo dele, e não atrás de um quarto
 * botão. As duas respondem à mesma curiosidade — "o que anda acontecendo na
 * arena" — e o ranking sozinho é uma tabela sem vida: ele diz quem é bom e não
 * diz nada sobre o que aconteceu ontem.
 *
 * ---- O que cada linha carrega ----
 *
 * Os dois bonecos, o vencedor primeiro; o tempo que durou; em que degrau de
 * 15% os bichos estavam quando acabou; e há quanto tempo foi. O degrau é o
 * "etc" que diz mais do que o relógio: dois minutos contra bicho no degrau 1 e
 * dois minutos contra bicho no degrau 6 são lutas muito diferentes.
 * ========================================================================= */
/*
 * `duracaoDoDuelo` e nao `duracaoCurta`: aquele nome ja existe nesta casa, na
 * prateleira da loja, e fala em SEGUNDOS ("7h09"). Este fala em milissegundos e
 * em "1m 23s" — duas unidades e dois formatos diferentes debaixo do mesmo nome
 * seriam a armadilha esperando o proximo que passar por aqui.
 */
function duracaoDoDuelo(ms) {
  const total = Math.max(0, Math.round((ms ?? 0) / 1000));
  const min = Math.floor(total / 60);
  const seg = total % 60;
  return min ? `${min}m ${String(seg).padStart(2, '0')}s` : `${seg}s`;
}

/*
 * "há quanto tempo", em uma palavra só.
 *
 * Data e hora exatas não servem numa lista destas: ninguém quer saber que foi
 * às 14:37, quer saber se foi agora ou ontem. E uma hora absoluta ainda
 * levantaria a pergunta de qual fuso — o do servidor ou o de quem olha.
 */
function quandoCurto(ts) {
  const falta = Date.now() - (ts ?? 0);
  if (falta < 60_000) return 'agora';
  const min = Math.floor(falta / 60_000);
  if (min < 60) return `há ${min} min`;
  const horas = Math.floor(min / 60);
  if (horas < 24) return `há ${horas}h`;
  const dias = Math.floor(horas / 24);
  return `há ${dias} dia${dias === 1 ? '' : 's'}`;
}

function bonecoDaBatalha(lado, tamanho) {
  const palco = el('div', 'arena-batalha-boneco');
  if (lado?.outfit?.type && outfitInfo(lado.outfit.type)) {
    palco.append(outfitCanvas(lado.outfit.type, lado.outfit, tamanho, 2, false));
  }
  return palco;
}

function renderHistoricoDaArena(body, view) {
  const historico = view.historico ?? [];

  const cabeca = el('section', 'arena-loja-cabeca');
  cabeca.append(el('h3', 'arena-lobby-nome', 'Histórico de batalhas'));
  cabeca.append(
    el(
      'p',
      'shop-note',
      'Os últimos duelos do servidor, do mais novo para o mais velho — com quanto tempo cada um durou.',
    ),
  );
  body.append(cabeca);

  if (!historico.length) {
    body.append(el('p', 'empty', 'Nenhum duelo ainda. O primeiro x1 abre esta lista.'));
    return;
  }

  const lista = el('section', 'arena-batalhas');
  for (const luta of historico) {
    const linha = el('div', 'arena-batalha');

    const venceu = el('div', 'arena-batalha-lado venceu');
    venceu.append(bonecoDaBatalha(luta.vencedor, 34));
    const nomeV = el('div', 'arena-batalha-quem');
    nomeV.append(el('b', null, luta.vencedor?.nome ?? '—'));
    const seloV = seloDaPatente(luta.vencedor?.patente, 14);
    if (seloV) nomeV.append(seloV);
    venceu.append(nomeV);
    linha.append(venceu);

    linha.append(el('span', 'arena-batalha-versus', 'venceu'));

    const perdeu = el('div', 'arena-batalha-lado perdeu');
    perdeu.append(bonecoDaBatalha(luta.perdedor, 34));
    const nomeP = el('div', 'arena-batalha-quem');
    nomeP.append(el('b', null, luta.perdedor?.nome ?? '—'));
    const seloP = seloDaPatente(luta.perdedor?.patente, 14);
    if (seloP) nomeP.append(seloP);
    perdeu.append(nomeP);
    linha.append(perdeu);

    const conta = el('div', 'arena-batalha-conta');
    conta.append(el('span', 'arena-batalha-tempo', duracaoDoDuelo(luta.duracao)));
    conta.append(el('span', 'arena-batalha-onde', luta.arena ?? 'Arena'));
    /*
     * O degrau só aparece quando houve degrau. "degrau 0" numa luta de quarenta
     * segundos seria uma coluna de zeros na maioria das linhas, e a informação
     * é justamente a exceção: a luta que durou o bastante para os bichos
     * ficarem mais fortes.
     */
    if (luta.degraus > 0) {
      conta.append(
        el('span', 'arena-batalha-degrau', `bichos +${Math.round((1.15 ** luta.degraus - 1) * 100)}%`),
      );
    }
    conta.append(el('span', 'arena-batalha-quando', quandoCurto(luta.quando)));
    linha.append(conta);

    lista.append(linha);
  }
  body.append(lista);
}

/*
 * ---- A LOJA DA ARENA, como página ----
 *
 * "a loja vai ser um botao clicavel ao lado do botao de fechar."
 *
 * Ela era a última seção de uma lista comprida, abaixo do ranking. Duas coisas
 * estavam erradas nisso: quem quer comprar rolava a janela inteira, e quem quer
 * lutar rolava por cima de uma prateleira que não pediu. Um botão no cabeçalho
 * troca as duas telas, e cada uma fica com a janela inteira para ela.
 *
 * ---- Cards e não linhas ----
 *
 * O lobby é lista porque as linhas dele são pessoas, e pessoa tem nome, level e
 * um botão — cabe numa linha. Produto tem DESENHO, e desenho pede espaço: numa
 * linha de 28px o item vira um selo ao lado do texto. Em card, a peça é a
 * primeira coisa que se vê, que é como se escolhe o que comprar.
 */
function renderLojaDaArena(body, view) {
  const eu = view.eu ?? {};
  const loja = view.loja ?? [];

  const cabeca = el('section', 'arena-loja-cabeca');

  /*
   * ---- O balcão ----
   *
   * Uma faixa pintada no topo, recortada em ~110px de altura pelo CSS. Ela não
   * informa nada — e é por isso que existe: a loja era um cabeçalho de texto em
   * cima de uma prateleira de texto, e nada dizia que aquilo era um LUGAR. É a
   * mesma peça que o card de hunt e o cartaz de boss usam.
   */
  const balcao = document.createElement('img');
  balcao.className = 'arena-loja-balcao';
  balcao.alt = '';
  arteTeimosa(balcao, '/client/assets/arenas/loja-da-arena.webp');
  cabeca.append(balcao);

  cabeca.append(el('h3', 'arena-lobby-nome', 'Loja da arena'));
  const bolso = el('div', 'arena-loja-bolso');
  bolso.append(moedaDaArena(eu.moedas, 26));
  bolso.append(el('span', null, (eu.moedas ?? 0) === 1 ? 'moeda de arena' : 'moedas de arena'));
  cabeca.append(bolso);
  cabeca.append(
    el(
      'p',
      'shop-note',
      'A moeda de arena não é item: ela não entra na mochila, não se troca e só aparece aqui. Cada vitória dá uma; cada derrota tira uma.',
    ),
  );
  body.append(cabeca);

  if (!loja.length) {
    body.append(el('p', 'empty', 'A loja ainda não tem nada à venda.'));
    return;
  }

  const prateleira = el('div', 'arena-loja-prateleira');
  for (const produto of loja) {
    const card = el('div', `arena-loja-card${produto.posso ? '' : ' sem-moeda'}`);
    const arte = el('div', 'arena-loja-arte');
    arte.append(itemCanvas(produto.id, 40));
    if (produto.quantos > 1) arte.append(el('b', 'arena-loja-quantos', `${produto.quantos}x`));
    card.append(arte);
    card.append(el('span', 'arena-loja-nome', produto.nome));

    const preco = el('div', 'arena-loja-preco');
    preco.append(moedaDaArena(produto.preco, 18));
    card.append(preco);

    const comprar = el('button', 'primary', 'Comprar');
    comprar.disabled = !produto.posso;
    if (!produto.posso) {
      tipTexto(comprar, `custa ${produto.preco} moeda${produto.preco === 1 ? '' : 's'} — você tem ${eu.moedas ?? 0}`);
    }
    comprar.onclick = () => ctx.send({ t: 'arena', action: 'comprar', item: produto.id });
    card.append(comprar);
    tipFor(card, produto.id);
    prateleira.append(card);
  }
  body.append(prateleira);
}

export function openCharms() {
  ctx.send({ t: 'charms' });
  ctx.tabs.charmKind ??= 'offensive';
  // No telefone a tela abre na grade (a ficha é a segunda tela).
  ctx.tabs.charmNaFicha = false;
  ctx.openModal('Charms', (body) => {
    const draw = () => {
      body.innerHTML = '';
      renderCharms(body);
    };
    ctx.redraw = draw;
    draw();
  });
}

/*
 * ---- O bicho do charm NÃO é escolhido numa lista nativa ----
 *
 * Report do DeividFpp: "os charms está bugado, não dá para colocar o bicho", e
 * o dono fechou o diagnóstico: "quando tu vai escolher o bicho e a ação do
 * personagem caçando fica fechando".
 *
 * Era um `<select>`, e a lista aberta dele é uma janela do SISTEMA — não está no
 * DOM, o CSS não a alcança e qualquer mexida na página a fecha. Com uma caçada
 * rodando atrás (loot, dano, chat, oito quadros por segundo) a lista fecha antes
 * de o dedo chegar no nome. É o mesmo defeito do botão "zerar analisador" e da
 * quantidade da loja, mas com um agravante: aqueles a gente conserta segurando o
 * elemento, e este não dá — a lista aberta não é nossa.
 *
 * Então a escolha passa a acontecer DENTRO da janela, num painel comum. Ele não
 * fecha sozinho porque nada o fecha além do clique da pessoa.
 *
 * De quebra resolve o que a lista nativa já fazia mal: são mais de mil
 * criaturas no bestiary, e rolar isso num popup de sistema procurando um nome é
 * pior do que digitar três letras. O campo de busca vem junto.
 * De quebra resolve o que a lista nativa já fazia mal: são mais de mil
 * criaturas no bestiary, e rolar isso num popup de sistema procurando um nome é
 * pior do que digitar três letras. O campo de busca vem junto.
 *
 * Qual painel está aberto mora em `ctx.tabs`, que é a gaveta que sobrevive ao
 * redesenho — a mesma de que a quantidade da loja precisou.
 */
function escolhaDaCriatura(charm) {
  const { state, send, tabs } = ctx;
  const caixa = el('div', 'charm-alvo');

  /* Só o que este personagem já matou: é a regra do charm. */
  const conhecidas = Object.entries(state.catalog.bestiary ?? {})
    .filter(([key]) => state.character.bestiary?.[key])
    .map(([key, info]) => ({ key, nome: info.name, look: info.look, colors: info.colors, lookItem: info.lookItem }))
    .sort((a, b) => a.nome.localeCompare(b.nome, 'pt-BR'));

  const escolhida = conhecidas.find((c) => c.key === charm.assigned) ?? null;
  const aberta = tabs.charmAberto === charm.id;

  const botao = el('button', `charm-alvo-botao${escolhida ? ' tem' : ''}`);
  if (escolhida) {
    const arte = escolhida.look
      ? outfitCanvas(escolhida.look, escolhida.colors ?? null, 22, 2, true)
      : escolhida.lookItem
        ? itemCanvas(escolhida.lookItem, 22)
        : null;
    if (arte) botao.append(arte);
  }
  botao.append(el('span', null, escolhida?.nome ?? 'sem criatura'));
  botao.append(el('i', null, aberta ? '▴' : '▾'));
  botao.onclick = () => {
    tabs.charmAberto = aberta ? null : charm.id;
    ctx.redraw();
  };
  caixa.append(botao);

  if (!conhecidas.length) {
    botao.disabled = true;
    botao.title = 'o charm aponta para uma criatura que você já matou — cace uma e ela aparece aqui';
    caixa.append(el('em', 'charm-alvo-vazio', 'nenhuma criatura no bestiary ainda'));
    return caixa;
  }
  if (!aberta) return caixa;

  const painel = el('div', 'charm-alvo-lista');
  const busca = document.createElement('input');
  busca.type = 'search';
  busca.placeholder = `buscar entre ${conhecidas.length}...`;
  busca.value = tabs.charmBusca ?? '';
  painel.append(busca);

  const lista = el('div', 'charm-alvo-itens');
  const escolher = (key) => {
    tabs.charmAberto = null;
    tabs.charmBusca = '';
    send({ t: 'charms', action: 'assign', id: charm.id, monster: key });
  };

  const pintar = () => {
    const filtro = (tabs.charmBusca ?? '').trim().toLowerCase();
    lista.innerHTML = '';

    const limpar = el('button', `charm-alvo-item${escolhida ? '' : ' escolhido'}`, 'sem criatura');
    limpar.onclick = () => escolher(null);
    lista.append(limpar);

    /*
     * Um teto na lista desenhada, e não na filtrada: mil e oitocentas linhas de
     * DOM travam a janela por um segundo a cada tecla. Quem tem mais do que isso
     * digita mais uma letra — é para isso que a busca existe.
     */
    let desenhadas = 0;
    for (const bicho of conhecidas) {
      if (filtro && !bicho.nome.toLowerCase().includes(filtro)) continue;
      if (desenhadas >= 60) {
        lista.append(el('em', 'charm-alvo-vazio', 'e mais... refine a busca'));
        break;
      }
      desenhadas++;
      const item = el('button', `charm-alvo-item${bicho.key === charm.assigned ? ' escolhido' : ''}`);
      const arte = bicho.look
        ? outfitCanvas(bicho.look, bicho.colors ?? null, 22, 2, true)
        : bicho.lookItem
          ? itemCanvas(bicho.lookItem, 22)
          : null;
      if (arte) item.append(arte);
      item.append(el('span', null, bicho.nome));
      item.onclick = () => escolher(bicho.key);
      lista.append(item);
    }
    if (!desenhadas && filtro) lista.append(el('em', 'charm-alvo-vazio', 'nenhuma com esse nome'));
  };

  /*
   * A busca redesenha SÓ a lista, e não o painel: redesenhar o painel jogaria
   * fora o campo e o cursor a cada tecla — que é a versão de teclado do mesmo
   * defeito que trouxe a gente até aqui.
   */
  busca.oninput = () => {
    tabs.charmBusca = busca.value;
    pintar();
  };
  pintar();
  painel.append(lista);
  caixa.append(painel);
  return caixa;
}

/*
 * ---- A tela de Charms: uma grade compacta e uma ficha ao lado ----
 *
 * O dono: "a tela de charms eu queria deixar mais bonita e mais compacta, tipo
 *  essa que vou te mandar na foto — não precisa mudar nossa cor e estilo, nem
 *  deixar 100% igual, mas olha bem como está essa tela e tenta fazer parecido
 *  na nossa, porque ela está boa e otimizada".
 *
 * Eram vinte e cinco cartões grandes, cada um com o parágrafo inteiro do efeito
 * repetido dentro. Treze deles cabiam na tela; os outros doze ficavam abaixo da
 * dobra, e comparar dois charms custava rolar a janela de um lado para o outro
 * lendo o mesmo texto vinte e cinco vezes.
 *
 * O desenho da foto resolve isso com uma divisão simples, e é ela que vem para
 * cá: a ESQUERDA é a lista, e nela cabe só o que se usa para escolher — o
 * desenho, o nome, quantos tiers já foram comprados e quanto custa o próximo. A
 * DIREITA é a ficha do que está selecionado, e é lá que mora o texto longo, a
 * chance, a criatura e os botões.
 *
 * O resultado medido: os vinte e cinco charms cabem na primeira tela, e o que
 * era rolagem virou um clique.
 *
 * ---- O que NÃO mudou ----
 *
 * Nada do funcionamento. As ações continuam sendo as duas que o servidor tem
 * (`upgrade` e `assign`), a escolha de criatura continua sendo a mesma
 * `escolhaDaCriatura` — inclusive o motivo de ela existir, que é o `<select>`
 * nativo fechando sozinho durante a caçada —, e as abas continuam separando
 * ofensivos de defensivos.
 *
 * `category` (major/minor) é a única informação nova na tela, e ela já vinha do
 * servidor desde sempre: estava no `charms.json` e nunca tinha sido mostrada.
 */
function renderCharms(body) {
  const { state, send } = ctx;
  const view = state.charms;
  if (!view) return void body.append(el('p', 'empty', 'carregando...'));

  const kind = ctx.tabs.charmKind;
  const daAba = view.list.filter((entry) => entry.kind === kind);

  /*
   * Qual está selecionado. Trocar de aba não pode deixar a ficha mostrando um
   * charm que não está mais na lista ao lado — daí o `find` em vez de confiar
   * no que ficou guardado.
   */
  const selecionado = daAba.find((entry) => entry.id === ctx.tabs.charmSel) ?? daAba[0] ?? null;
  ctx.tabs.charmSel = selecionado?.id ?? null;

  body.append(
    tabBar({ offensive: 'Ofensivos', defensive: 'Defensivos' }, kind, (next) => {
      ctx.tabs.charmKind = next;
      ctx.tabs.charmNaFicha = false;
      /*
       * A criatura aberta fecha junto com a aba.
       *
       * O painel de busca é preso a UM charm (`tabs.charmAberto`), e ele fica
       * dentro da ficha: trocando de aba, a ficha passa a ser de outro charm e
       * o painel apareceria aberto por baixo do nome errado.
       */
      ctx.tabs.charmAberto = null;
      ctx.redraw();
    })
  );

  const tela = el('div', 'charm-tela');

  // ---- A esquerda: a grade ----
  const grade = el('div', 'charm-grade');
  for (const charm of daAba) {
    const tile = el('button', `charm-tile${charm.tier ? ' tem' : ''}${charm.id === ctx.tabs.charmSel ? ' sel' : ''}`);

    const arte = document.createElement('img');
    arte.className = 'charm-icon';
    arte.src = `/client/assets/charms/icon-charms-${charm.category}.png`;
    arte.alt = '';
    tile.append(arte);
    tile.append(el('b', null, charm.name));
    /*
     * O apelido em português embaixo do nome.
     *
     * O nome fica: é por "Wound" que o jogador acha o charm no wiki e conversa
     * com outro jogador sobre ele. O apelido é quem explica, de relance, o que
     * ele faz — e num quadrado de 96px não cabe mais do que isso. A frase
     * inteira mora na ficha ao lado.
     */
    const apelido = apelidoDoCharm(charm.id);
    if (apelido) tile.append(el('i', 'charm-apelido', apelido));

    const tiers = el('span', 'charm-tiers');
    for (let index = 0; index < charm.points.length; index++) {
      tiers.append(el('i', `charm-tier${index < charm.tier ? ' on' : ''}`, '◆'));
    }
    tile.append(tiers);

    /*
     * O número do rodapé é o do PRÓXIMO tier, e não o total gasto: é a única
     * pergunta que se faz olhando uma grade de charms — "qual eu consigo
     * comprar agora". Os que dá para comprar ficam dourados (ver `.pode`).
     */
    if (charm.cost == null) tile.append(el('em', 'charm-max', 'máx'));
    else tile.append(el('em', view.points >= charm.cost ? 'pode' : null, money(charm.cost)));

    tile.onclick = () => {
      ctx.tabs.charmSel = charm.id;
      // Trocar de charm fecha a busca de criatura do anterior.
      if (ctx.tabs.charmAberto !== charm.id) ctx.tabs.charmAberto = null;
      // No telefone, tocar mostra a ficha dele (lista-detalhe.mjs).
      ctx.tabs.charmNaFicha = true;
      ctx.redraw();
    };
    grade.append(tile);
  }
  tela.append(grade);

  // ---- A direita: a ficha do selecionado ----
  const ficha = el('aside', 'charm-ficha');
  if (!selecionado) {
    ficha.append(el('p', 'empty', 'nenhum charm nesta aba'));
  } else {
    const charm = selecionado;

    const topo = el('div', 'charm-ficha-topo');
    const arte = document.createElement('img');
    arte.className = 'charm-icon grande';
    arte.src = `/client/assets/charms/icon-charms-${charm.category}.png`;
    arte.alt = '';
    topo.append(arte);
    const nomes = el('div', 'grow');
    nomes.append(el('b', null, charm.name));
    const apelidoDele = apelidoDoCharm(charm.id);
    if (apelidoDele) nomes.append(el('i', 'charm-ficha-apelido', apelidoDele));
    /*
     * "MAJOR · OFENSIVO": a categoria vinha do servidor desde o primeiro dia e
     * nunca tinha aparecido em lugar nenhum da tela. Ela é o que explica por
     * que um charm custa 240 e o vizinho custa 100.
     */
    nomes.append(
      el('span', null, `${charm.category === 'major' ? 'Major' : 'Minor'} · ${kind === 'offensive' ? 'Ofensivo' : 'Defensivo'}`)
    );
    topo.append(nomes);
    topo.append(
      el('span', `charm-selo${charm.tier ? ' tem' : ''}`, charm.tier ? `tier ${charm.tier}/${charm.points.length}` : 'travado')
    );
    ficha.append(topo);

    ficha.append(el('p', 'charm-text', textoDoCharm(charm.id, charm.description)));

    // ---- As linhas de número ----
    const linhas = el('div', 'charm-linhas');
    const linha = (rotulo, valor, classe = null) => {
      const caixa = el('div', 'charm-linha');
      caixa.append(el('dt', null, rotulo));
      caixa.append(el('dd', classe, valor));
      linhas.append(caixa);
    };
    /*
     * A chance só aparece quando o charm já é do jogador: `chance[tier - 1]` de
     * um charm travado é o valor do PRIMEIRO tier, e mostrá-lo como se fosse o
     * atual diria que um charm que ele não tem já está disparando 5% das vezes.
     */
    linha('Chance de disparo', charm.tier ? `${charm.chance}%` : '—', charm.tier ? 'forte' : null);
    if (charm.percent) linha('Dano', `${charm.percent}% da vida inicial`);
    linha(
      charm.tier ? 'Próximo tier' : 'Para liberar',
      charm.cost == null ? 'no máximo' : `${money(charm.cost)} pontos`,
      charm.cost != null && view.points >= charm.cost ? 'forte' : null
    );
    // Ofensivo E defensivo apontam para uma criatura (o dono: "defensivo tbm tenho que escolher a criatura").
    {
      const bicho = state.catalog.bestiary?.[charm.assigned]?.name;
      linha('Criatura', bicho ?? 'nenhuma');
    }
    ficha.append(linhas);

    // ---- E os botões ----
    const acoes = el('div', 'charm-acoes');
    if (charm.cost != null) {
      const comprar = el('button', null, charm.tier ? `Subir de tier · ${money(charm.cost)}` : `Liberar · ${money(charm.cost)}`);
      comprar.disabled = view.points < charm.cost;
      if (comprar.disabled) tipTexto(comprar, `faltam ${money(charm.cost - view.points)} pontos de charm`);
      comprar.onclick = () => send({ t: 'charms', action: 'upgrade', id: charm.id });
      acoes.append(comprar);
    } else {
      acoes.append(el('span', 'charm-max', 'este charm já está no máximo'));
    }
    ficha.append(acoes);

    /*
     * A escolha da criatura é a MESMA de antes, movida de dentro do cartão para
     * dentro da ficha. Só cabe aqui: ela abre um painel de busca com até
     * sessenta linhas, que dentro de um quadrado de grade não caberia.
     */
    if (charm.tier) ficha.append(escolhaDaCriatura(charm));
  }
  tela.append(ficha);
  body.append(tela);
  // No telefone: a grade, ou a ficha do charm tocado — não os dois empilhados.
  listaDetalhe(tela, ficha, {
    id: 'charms',
    rotulo: '← Charms',
    escolhido: !!selecionado && !!ctx.tabs.charmNaFicha,
    voltar: () => {
      ctx.tabs.charmNaFicha = false;
      ctx.redraw();
    },
  });

  /*
   * ---- O saldo, no rodapé ----
   *
   * Era a primeira linha da tela, escrita em prosa. Um número que a pessoa
   * consulta a cada clique não devia estar no lugar que o olho abandona
   * primeiro — e, no rodapé, ele fica ao lado da grade, que é onde os preços
   * estão.
   */
  const rodape = el('div', 'charm-rodape');
  const saldo = (rotulo, valor) => {
    const caixa = el('div', 'charm-saldo');
    caixa.append(el('span', null, rotulo));
    caixa.append(el('b', null, money(valor)));
    rodape.append(caixa);
  };
  saldo('Pontos de charm', view.points);
  saldo('Já gastos', view.spent);
  rodape.append(
    el('p', null, 'O bestiary paga uma vez por criatura, quando a contagem de mortes dela fecha.')
  );
  body.append(rodape);
}
// ---------- loja de Draevor Coins + mercado ----------

/*
 * As seções da Store. Antes montarias e outfits eram abas irmãs da loja,
 * o que dava a entender que eram outra coisa — são prateleiras da mesma loja.
 * Agora a loja tem uma coluna de seções à esquerda e a prateleira à direita.
 */
const STORE_SECTIONS = {
  services: 'Serviços',
  boosts: 'Boosts',
  buffpower: 'Buff Power',
  pacotes: 'Pacotes',
  itens: 'Itens',
  exercises: 'Armas de treino',
  mounts: 'Montarias',
  outfits: 'Outfits',
  utilities: 'Utilitários',
  upgrades: 'Melhorias',
  /*
   * Extras: o que muda o FAMILIAR e não o personagem.
   *
   * Fica por último porque é a prateleira mais estreita — dez produtos, todos
   * do mesmo bicho —, e porque é a única que só interessa a quem já joga com
   * summon. As de cima valem para qualquer um que abriu a loja.
   */
  extras: 'Extras',
};

/*
 * ---- O desenho de cada prateleira ----
 *
 * O dono: "faltou os ícones em cada categoria da store, lembra — aba-boosts,
 * aba-exercises etc".
 *
 * Toda aba do jogo já tinha o seu: `tabBar` prepende `aba-<id>.png` sozinho, e
 * é por isso que Aventuras e Tarefas aparecem com arte. A coluna da loja é a
 * única lista de abas que NÃO passa por ele — ela é montada à mão aqui —, e
 * por isso ficou com nove linhas de texto puro no meio de um jogo em que toda
 * aba tem cara.
 *
 * Cinco prateleiras já têm o arquivo com o nome certo (`aba-boosts`,
 * `aba-pacotes`, `aba-exercises`, `aba-mounts`, `aba-outfits`) e são achadas
 * sozinhas. As outras quatro ainda não foram desenhadas, e em vez de ficarem
 * sem nada emprestam a arte que JÁ representa aquilo em outro lugar do jogo —
 * a mochila para Itens, a forja para o Tier Up, a engrenagem para as melhorias.
 *
 * É o mesmo desvio que o Highscores usa para as perícias (ver o `icones` de
 * `tabBar`). No dia em que um `aba-itens.png` for desenhado, basta apagar a
 * linha daqui: o nome por id volta a valer sozinho.
 */
const ARTE_DA_PRATELEIRA = {
  services: 'aba-recompensas',
  itens: 'inventory',
  utilities: 'forja',
  upgrades: 'options',
  // Emprestado, como os três de cima: não há `aba-extras.png` desenhado, e
  // `aba-especiais` é o que já representa "o que não cabe nas outras" no jogo.
  extras: 'aba-especiais',
};

/*
 * Mexer no SALDO não é uma prateleira.
 *
 * "Draevor Coins" e "Transferir" eram seções como "Montarias" ou "Melhorias", e
 * não são a mesma coisa: as prateleiras gastam o saldo, estas duas mexem nele —
 * uma enche, a outra manda embora. Quem chegava na loja sem saldo precisava
 * adivinhar que a resposta estava numa aba no meio da lista.
 *
 * As duas viraram botões do rodapé, ao lado do número do saldo — o lugar onde a
 * pergunta "e se faltar?" aparece —, e abrem por CIMA da loja, que continua
 * atrás. Ver `abrirObterCoins` e `abrirTransferir`.
 */

/*
 * A loja e o mercado se separaram.
 *
 * Eram duas abas do mesmo modal, e não são a mesma coisa: uma vende por Draevor
 * Coins e é da casa, o outro é entre jogadores e paga em ouro. Cada um tem a
 * sua placa na barra de cima agora.
 */
export function openStore() {
  ctx.send({ t: 'store' });
  ctx.openModal('Store', (body) => {
    const draw = () => {
      body.innerHTML = '';
      renderStore(body);
    };
    ctx.redraw = draw;
    /*
     * ---- A prateleira só muda quando a PRATELEIRA muda ----
     *
     * Medida caçando, a loja renascia 0,45 vez por segundo: uma lista longa,
     * com figuras, refeita do zero enquanto a pessoa rola procurando o que
     * comprar. O que a movia era o ouro entrando — e ouro não muda nenhuma
     * prateleira.
     *
     * O que muda é o catálogo, a seção, a busca e as COINS, que são a moeda
     * daqui. As coins não entram por loot: mudam quando se compra ou se recebe,
     * e aí a tela tem mesmo de se refazer.
     */
    ctx.redrawKey = () => {
      const loja = ctx.state.store;
      return [
        ctx.tabs.storeSection ?? '-',
        ctx.tabs.storeBusca ?? '',
        Math.round(ctx.state.character?.coins ?? 0),
        loja ? Object.keys(loja).length : 0,
        (loja?.boosts ?? []).length,
        (loja?.services ?? []).length,
        (loja?.exercises ?? []).length,
        (loja?.itens ?? loja?.items ?? []).length,
        (ctx.state.character?.outfitsOwned ?? []).length,
        (ctx.state.character?.mounts ?? []).length,
        (ctx.state.character?.premium ?? 0) > 0 ? 'vip' : '-',
      ].join('|');
    };
    draw();
  }, null, 'store');
}

export function openMarket() {
  /*
   * Tres pedidos ao abrir, e nao um.
   *
   * `browse` traz o resumo (o seu ouro e as SUAS ofertas, que a aba "Minhas"
   * mostra), `offers` traz a pagina de anuncios e `coinMarket` traz o cambio.
   * Sao listas independentes — ver `marketOffers` e `coinMarketView` no
   * servidor —, e pedir as tres aqui evita a tela piscar "carregando..." a cada
   * troca de aba.
   */
  // A peneira da última vez volta ANTES do primeiro pedido: senão o servidor
  // responderia a lista sem filtro e a tela a trocaria um quadro depois.
  lembrarFiltros();
  ctx.send({ t: 'market', action: 'browse' });
  pedirOfertas();
  pedirCoins();
  ctx.openModal('Mercado', (body) => {
    const draw = () => {
      body.innerHTML = '';
      renderMarket(body);
    };
    ctx.redraw = draw;
    /*
     * ---- E o Mercado renasce só quando o MERCADO muda ----
     *
     * Era o pior dos três: 0,65 renascimento por segundo caçando. E o mercado é
     * a tela em que mais se digita — buscar, filtrar, escrever um preço. Cada
     * loot que entrava na mochila refazia a lista inteira debaixo do texto.
     *
     * As ofertas, o câmbio e as suas próprias ordens são o que a tela mostra; o
     * ouro entra porque os botões de comprar acendem e apagam com ele, e ele
     * muda devagar o suficiente para não ser o problema. O peso, a mochila e a
     * experiência ficaram de fora.
     */
    ctx.redrawKey = () => {
      const t = ctx.tabs;
      /*
       * Cada lista entra pelo seu próprio "quantos e quais": trocar de aba,
       * receber a página nova do servidor ou cancelar uma ordem muda isto; pegar
       * um loot, não.
       */
      /*
       * `comoLista` e não `?? []`: as colunas do câmbio nem sempre chegam como
       * vetor — vieram como objeto, `.map` estourou, e a chave inteira virou
       * `null`. Uma chave que estoura cai de volta na assinatura grande sem
       * avisar, e foi por isso que o Mercado continuou renascendo 0,56 vez por
       * segundo depois de eu já ter "consertado" — o conserto nunca rodava.
       */
      const comoLista = (v) => (Array.isArray(v) ? v : []);
      const lista = (dados) => (dados ? `${dados.total ?? ''}:${comoLista(dados.itens ?? dados.offers ?? dados.lista).length}` : '-');
      return [
        t.marketAba ?? 'ofertas', t.marketMoeda ?? '-', t.marketLado ?? '-',
        t.marketBusca ?? '', t.marketSlot ?? '-', t.marketVocacao ?? '-',
        t.marketRaridade ?? '-', t.marketOrdem ?? '-', t.marketPagina ?? 0,
        t.marketEssencias ?? '-',
        /*
         * ---- O OURO não entra; o que entra é o que ele DECIDE ----
         *
         * Medido: o ouro era a única coisa que mudava nesta chave caçando — o
         * loot entra moeda a moeda, e a tela renascia 0,60 vez por segundo por
         * causa do número no canto. O que o ouro de fato muda na tela é (a) o
         * saldo escrito, que agora se atualiza no lugar (ver `aoVivo`), e (b)
         * quais linhas do câmbio dá para comprar.
         *
         * Então entra a SEGUNDA coisa e não a primeira: uma linha de zeros e
         * uns, um por oferta, que só vira outra quando o ouro cruza um preço.
         * Passar de 4.932.151 para 4.932.187 não muda nada disso.
         */
        comoLista(ctx.state.coinMarket?.venda).map((linha) => (ouroDoJogador(ctx.state) >= (linha?.total ?? 0) ? 1 : 0)).join(''),
        comoLista(ctx.state.coinMarket?.compra).map((linha) => ((ctx.state.character?.coins ?? 0) >= (linha?.amount ?? 0) ? 1 : 0)).join(''),
        lista(ctx.state.marketOffers),
        lista(ctx.state.coinMarket),
        lista(ctx.state.marketHistorico),
        comoLista(ctx.state.market?.mine).length,
        comoLista(ctx.state.coinMarket?.minhas).length,
      ].join('|');
    };
    /* E o saldo escrito acompanha o loot entrando, sem refazer a tela. */
    ctx.aoVivo = () => {
      const ouro = body.querySelector('.balcao-moeda.ouro b');
      if (ouro) ouro.textContent = money(ctx.state.market?.gold ?? ouroDoJogador(ctx.state));
      const coin = body.querySelector('.balcao-moeda.coin b');
      if (coin) coin.textContent = money(ctx.state.character?.coins ?? 0);
    };
    draw();
  });
}

/**
 * Confirmação de compra: nome, preço, saldo atual e saldo depois. Sai por cima
 * da loja em vez de trocar de modal, para a loja continuar no lugar atrás.
 */
/*
 * `cabecalho` existe porque nem toda confirmação é uma COMPRA.
 *
 * Ligar um Buff Power passa por esta mesma caixa — ela já diz preço, saldo e
 * saldo depois, que é exatamente o que se precisa ver antes de aceitar —, mas
 * ali não se compra nada: o item já é seu e o que se paga é a hora. "Confirmar
 * compra" naquela tela faria a pessoa procurar o que ela acabou de comprar.
 */
export function confirmPurchase({ title, cost, balance, currency = 'coin-store', unit = 'Draevor Coins', preview, exigencia, note, marcar, cabecalho = 'Confirmar compra', onConfirm }) {
  const back = el('div', 'confirm-back');
  const box = el('div', 'confirm-box');

  box.append(el('h3', null, cabecalho));
  if (preview) box.append(preview);
  box.append(el('p', 'confirm-item', title));

  const rows = el('div', 'confirm-rows');
  const row = (label, value, className) => {
    const line = el('div', className);
    line.append(el('span', null, label), el('b', null, value));
    rows.append(line);
  };
  row('Preço', `− ${money(cost)} ${unit}`, 'cost');
  row('Saldo atual', `${money(balance)} ${unit}`);
  row('Saldo após a compra', `${money(balance - cost)} ${unit}`, 'after');
  box.append(rows);

  /*
   * O aviso de quem chama, quando há um.
   *
   * A caixa de confirmação é o último instante em que dá para desistir, e é
   * onde a pessoa está olhando quando decide — uma arma que ela não pode
   * equipar tem de dizê-lo AQUI, e não só no card que ela já passou.
   */
  /*
   * ---- A EXIGENCIA, sempre, e em destaque ----
   *
   * "informar que essas hunts SO ENTRA LEVEL X+ E COM PREMIUM, e isso bem
   *  destacado, porque tao comprando sem ter level e premy."
   *
   * Diferente do `note` logo abaixo: aquele fala do que ESTA pessoa nao tem, e
   * some para quem esta em dia. A exigencia e' a regra do produto e vale para
   * todo mundo — inclusive para quem tem premium hoje e esta comprando pensando
   * num personagem que ainda vai subir de level.
   */
  if (exigencia) box.append(el('p', 'confirm-exigencia', exigencia));

  if (note) box.append(el('p', 'confirm-aviso', note));

  const short = balance < cost;
  if (short) box.append(el('p', 'confirm-short', `Faltam ${money(cost - balance)} ${unit}.`));

  const actions = el('div', 'confirm-actions');
  const cancel = el('button', 'ghost', 'Cancelar');
  cancel.onclick = () => back.remove();
  const confirm = el('button', null, 'Confirmar');

  /*
   * ---- E a CAIXINHA de "quero comprar mesmo assim" ----
   *
   * "quando a pessoa for comprar o instance hunts na loja tem que ter uma
   * janela de aviso — atenção você não é premium e não poderá usar o item,
   * deseja comprar mesmo assim? — e uma caixinha pra assinalar."
   *
   * `note` sozinho é um texto que se pula: quem já decidiu clica em Confirmar
   * sem ler. A caixinha faz o aviso ser LIDO, porque sem ela o botão não
   * funciona — e é o mesmo gesto que o jogo usa para todo aviso que a pessoa
   * pode legitimamente ignorar.
   *
   * Ela é opcional de propósito: comprar uma espada de level 300 é uma decisão
   * legítima e não precisa de fricção nenhuma. Só o que não FUNCIONA hoje pede
   * a marca.
   */
  let travado = false;
  if (marcar) {
    const linha = el('label', 'confirm-marcar');
    const caixinha = document.createElement('input');
    caixinha.type = 'checkbox';
    linha.append(caixinha, el('span', null, marcar));
    box.append(linha);
    travado = true;
    caixinha.onchange = () => {
      travado = !caixinha.checked;
      confirm.disabled = short || travado;
    };
  }

  confirm.disabled = short || travado;
  confirm.onclick = () => {
    back.remove();
    onConfirm();
  };
  actions.append(cancel, confirm);
  box.append(actions);

  back.append(box);
  fecharAoClicarFora(back, () => back.remove());
  // Enter compra, Escape desiste — como em toda caixa de confirmar do jogo.
  atalhosDaCaixa(back, { confirmar: () => !confirm.disabled && confirm.click(), fechar: () => back.remove() });
  document.body.append(back);
  confirm.focus();
}

/** Montarias e outfits à venda por Draevor Coins. */
function renderStoreList(body, kind) {
  const { state, send } = ctx;
  const store = state.store;
  if (!store) return void body.append(el('p', 'empty', 'carregando...'));

  body.append(collectionBanner(state.character));

  /*
   * Levar a coleção inteira de uma vez.
   *
   * São mais de duzentas peças em cada aba, todas ao mesmo preço; quem decidiu
   * completar a coleção não vai clicar duzentas vezes. A conta e a compra são
   * do servidor — aqui só se mostra o que ele já respondeu, e o botão some
   * quando não falta nada.
   */
  const lote = store.lotes?.[kind];
  if (lote?.faltam) {
    const tudo = el('button', 'store-lote');
    tudo.append(
      el('b', null, kind === 'mounts' ? `Comprar as ${lote.faltam} montarias que faltam` : `Comprar os ${lote.faltam} outfits que faltam`),
      el('span', null, `${lote.coins.toLocaleString('pt-BR')} Draevor Coins`)
    );
    /*
     * O preço cheio riscado ao lado do com desconto.
     *
     * Só o número final não diz que houve desconto — e um desconto que ninguém
     * percebe não faz o que um desconto existe para fazer. Os dois números
     * juntos mostram a conta inteira, e o servidor manda os dois para a tela
     * não ter de recalculá-los (e errar por meio coin de arredondamento).
     */
    if (lote.desconto && lote.cheio > lote.coins) {
      tudo.append(
        el(
          'em',
          'lote-desconto',
          `de ${lote.cheio.toLocaleString('pt-BR')} por ${lote.coins.toLocaleString('pt-BR')} — ${lote.desconto}% de desconto`,
        ),
      );
    }
    const podePagar = (store.coins ?? 0) >= lote.coins;
    if (!podePagar) {
      tudo.classList.add('curto');
      tipTexto(tudo, `Faltam ${(lote.coins - (store.coins ?? 0)).toLocaleString('pt-BR')} Draevor Coins.`);
    }
    /*
     * O botão do lote falava no canal errado.
     *
     * Ele mandava `{ t: 'buy' }`, que é a loja de OURO do NPC: lá o servidor
     * faz `shopIndex.get(Number(id))`, e "todas-montarias" vira NaN — o clique
     * respondia "item não está à venda" e nada acontecia. A Store é
     * `{ t: 'store', action: 'buy' }`, o mesmo canal de todos os outros botões
     * desta tela. E, como qualquer compra da loja, ela agora pergunta antes.
     */
    tudo.onclick = () =>
      confirmPurchase({
        title:
          kind === 'mounts'
            ? `${lote.faltam} montarias que faltam na coleção`
            : `${lote.faltam} outfits que faltam na coleção`,
        cost: lote.coins,
        balance: store.coins ?? 0,
        onConfirm: () => send({ t: 'store', action: 'buy', id: lote.id }),
      });
    body.append(tudo);
  }

  /*
   * A busca desta secao saiu daqui.
   *
   * Havia uma caixa de busca por secao, e a loja passou a ter uma que vale para
   * a loja inteira, no topo da coluna (ver `renderStoreBusca`). Duas caixas na
   * mesma tela, uma logo abaixo da outra, so' levantam a pergunta de qual das
   * duas faz o que — ainda mais quando a de cima ja' acha tudo o que a de baixo
   * achava.
   */
  const grid = el('div', 'mount-grid');
  const all = (store[kind] ?? []).filter((entry) => outfitInfo(entry.look));
  // O que já foi comprado desce para o fim da lista, apagado. Sem corte: com
  // um teto de 160, quem tivesse muita montaria via as próprias sumirem da
  // página, justamente as que precisam aparecer marcadas como adquiridas.
  const list = [...all.filter((entry) => !entry.owned), ...all.filter((entry) => entry.owned)];
  for (const entry of list) grid.append(cartaoDeVisual(entry, kind));
  if (!list.length) grid.append(el('p', 'empty', 'Nada por aqui.'));
  body.append(grid);
}

/** O cartao de uma montaria ou de um outfit da vitrine. */
function cartaoDeVisual(entry, kind) {
  const { state, send } = ctx;
  const store = state.store;
  /*
   * Outfit na vitrine aparece com os dois addons.
   *
   * `null` desenhava o corpo pelado, sem nenhum dos dois — e é justamente o
   * addon que o jogador está comprando. A aba de aparência já mostra assim
   * (`addons: 3`); a loja não mostrava. Montaria ignora o campo, então a mesma
   * chamada serve para as duas listas.
   */
  const vestido = kind === 'mounts' ? null : { addons: 3, mount: 0 };
  const card = el('button', `mount-card${entry.owned ? ' owned' : ''}`);
  // 72 e nao 56: o cartao passou de 140 para 210px de largura (ver
  // `.mount-grid`), e o boneco e' o produto — encolhido ali dentro ele
  // ficava com metade do quadro vazio em volta.
  card.append(outfitCanvas(entry.look, vestido, 72), el('b', null, entry.name));
  if (entry.speed) card.append(el('em', null, `+${entry.speed} de velocidade`));
  /*
   * `critNovo: false` vem do servidor para o outfit cuja APARÊNCIA a pessoa já
   * tem no outro sexo — a coleção conta aparências, e aquele não somaria nada.
   * Montaria não manda o campo e continua como estava.
   */
  if (entry.critNovo !== false) card.append(el('em', 'card-crit', `+${percent(COLLECTION_CRIT)} de crítico`));
  else card.append(el('em', 'card-crit', 'a coleção já conta esta aparência'));

  if (entry.owned) {
    card.append(el('span', 'price owned-tag', 'já adquirido'));
    card.disabled = true;
  } else {
    const price = el('span', 'price');
    price.append(uiIcon('coin-store'), document.createTextNode(money(entry.coins)));
    card.append(price);
    card.onclick = () =>
      confirmPurchase({
        title: entry.name,
        cost: entry.coins,
        balance: store.coins,
        preview: outfitCanvas(entry.look, vestido, 64),
        onConfirm: () => send({ t: 'store', action: 'buy', id: entry.id }),
      });
  }
  return card;
}

/*
 * O desenho de um produto: arte da gamestore, sprite do jogo, ou nada.
 *
 * ---- Por que os dois desenhos têm tamanhos diferentes ----
 *
 * O dono: "faltou as sprites arrumadas da store".
 *
 * Eram os dois no mesmo tamanho, e é justamente isso que os fazia parecer
 * desiguais. A arte desenhada (`xp-boost.png`, `premium-30.png`) preenche o
 * próprio quadro de ponta a ponta; um sprite do jogo é uma célula de 32×32 com
 * o desenho no meio e transparência em volta — uma poção ocupa uns 20 pixels
 * dos 32. Postos os dois a 44px, a poção aparecia com metade do tamanho do
 * ícone do lado.
 *
 * Então o sprite vai maior, e vai em DOBRO EXATO (32 → 64). Escala inteira é o
 * que mantém pixel art nítida: em 1,375× (o 44 de antes) cada pixel virava um
 * pedaço de pixel e meio, e a borda saía tremida.
 */
function storeArt(entry, size = 56) {
  if (!entry.art && !entry.itemId) return null;
  const arte = el('div', 'store-art');
  if (entry.art) {
    const img = document.createElement('img');
    /*
     * `ui:nome` busca em `assets/ui`, e não em `assets/store`.
     *
     * O slot de party usa o mesmo desenho do botão Party da barra de cima. Sem
     * este prefixo o arquivo teria de existir nas duas pastas — e a cópia
     * começaria a divergir no dia em que o dono redesenhasse só uma delas.
     */
    /*
     * E `icone:nome` busca em `assets/icons`, que é onde mora a arte grande
     * desenhada à mão — a mesma que as abas usam. É o terceiro caminho pelo
     * mesmo motivo do `ui:`: o arquivo não precisa existir duas vezes.
     */
    img.src = entry.art.startsWith('ui:')
      ? `/client/assets/ui/${entry.art.slice(3)}.png`
      : entry.art.startsWith('icone:')
        ? `/client/assets/icons/${entry.art.slice(6)}.png`
        : `/client/assets/store/${entry.art}.png`;
    img.alt = '';
    img.width = size;
    img.height = size;
    img.onerror = () => img.remove();
    arte.append(img);
  } else {
    // O dobro exato da célula do jogo. Ver a nota acima.
    arte.append(itemCanvas(entry.itemId, 64));
    tipFor(arte, entry.itemId);
  }
  return arte;
}

function renderStore(body) {
  const { state, send } = ctx;
  const store = state.store;
  if (!store) return void body.append(el('p', 'empty', 'carregando...'));

  const section = (ctx.tabs.storeSection ??= 'services');

  const layout = el('div', 'store-layout');

  // ---- coluna das seções ----
  const side = el('div', 'store-sections');
  // O saldo agora mora no rodapé, junto do botão de enchê-lo. Ele ficava aqui
  // em cima também, e dois lugares mostrando o mesmo número é um a mais.
  for (const [id, label] of Object.entries(STORE_SECTIONS)) {
    const button = el('button', null, label);
    // O mesmo desenho que `tabBar` põe em toda aba do jogo. Ver
    // `ARTE_DA_PRATELEIRA`: sem arquivo, `artOrUiIcon` se apaga sozinho e a
    // linha fica só com o texto, como estava.
    button.prepend(artOrUiIcon(ARTE_DA_PRATELEIRA[id] ?? `aba-${id}`, ''));
    button.setAttribute('aria-selected', String(section === id));
    button.onclick = () => {
      ctx.tabs.storeSection = id;
      // Clicar numa prateleira e' pedir para ver AQUELA prateleira: a busca que
      // estava por cima dela sai do caminho.
      ctx.tabs.storeBusca = '';
      ctx.redraw();
    };
    side.append(button);
  }
  layout.append(side);

  // ---- prateleira, com a busca por cima dela ----
  /*
   * ---- A busca atravessa a loja inteira ----
   *
   * As abas de montaria e de outfit ja' tinham uma busca cada, e as outras tres
   * secoes nao tinham nenhuma: quem procurava "premium" precisava saber de
   * antemao que premium mora em Servicos. Numa loja com cinco prateleiras e
   * varias centenas de produtos, saber ONDE esta a coisa e' justamente o que
   * quem busca nao sabe.
   *
   * Esta busca ignora a secao aberta e varre as cinco, agrupando o que achou por
   * prateleira. Enquanto o campo esta vazio, a loja e' a de sempre.
   */
  const direita = el('div', 'store-direita');
  const busca = document.createElement('input');
  busca.type = 'search';
  busca.className = 'search store-busca';
  busca.placeholder = 'buscar em toda a loja...';
  busca.value = ctx.tabs.storeBusca ?? '';

  const shelf = el('div', 'store-shelf');
  /*
   * A prateleira se refaz sozinha, sem passar pelo `ctx.redraw`.
   *
   * O redesenho do modal esvazia o `body` e monta tudo de novo — e com isso o
   * campo de busca seria destruido no meio da digitacao, levando junto o foco e
   * o cursor. A cada letra o teclado saltava para fora do campo.
   */
  const encher = () => {
    const termo = busca.value.trim().toLowerCase();
    ctx.tabs.storeBusca = busca.value;
    shelf.innerHTML = '';
    if (termo.length >= BUSCA_MINIMA) return void renderStoreBusca(shelf, termo);
    if (termo) {
      return void shelf.append(el('p', 'shop-note', `Escreva ao menos ${BUSCA_MINIMA} letras.`));
    }
    if (section === 'mounts' || section === 'outfits') renderStoreList(shelf, section);
    else if (section === 'boosts') renderBoosts(shelf);
    else if (section === 'buffpower') renderBuffPower(shelf);
    else if (section === 'pacotes') renderPacotes(shelf);
    else if (section === 'itens') renderItens(shelf);
    else if (section === 'exercises') renderExercises(shelf);
    else if (section === 'utilities') renderUtilities(shelf);
    else if (section === 'upgrades') renderUpgrades(shelf);
    else if (section === 'extras') renderExtras(shelf);
    else renderServices(shelf);
  };
  busca.oninput = encher;
  encher();

  direita.append(busca, shelf);
  layout.append(direita);

  body.append(layout);
  body.append(storeFooter(store));
}

/** Menos que isto e' quase a loja inteira, e a busca nao afina nada. */
const BUSCA_MINIMA = 2;
/*
 * Teto por prateleira nos resultados.
 *
 * Cada montaria e cada outfit e' um `canvas` desenhado na hora, e as duas listas
 * passam de duzentos cada uma: um termo curto que pegue metade delas montaria
 * duzentos bonecos de uma vez. O corte e' DITO na tela — resultado escondido em
 * silencio faz a busca parecer que respondeu tudo.
 */
const TETO_DA_BUSCA = 48;

function renderStoreBusca(body, termo) {
  const { state } = ctx;
  const store = state.store;
  const bate = (entry) => `${entry.name ?? ''} ${entry.blurb ?? ''}`.toLowerCase().includes(termo);

  const prateleiras = [
    { id: 'services', lista: store.services ?? [], grade: 'store-grid', cartao: cartaoDaPrateleiraDeServicos },
    { id: 'itens', lista: store.itens ?? [], grade: 'store-grid', cartao: cartaoDeItem },
    { id: 'exercises', lista: store.exercises ?? [], grade: 'store-grid', cartao: cartaoDeExercicio },
    { id: 'utilities', lista: store.utilities ?? [], grade: 'store-grid', cartao: cartaoDeUtilitario },
    { id: 'upgrades', lista: store.upgrades ?? [], grade: 'store-grid', cartao: cartaoDeMelhoria },
    /*
     * Os Extras entram na busca como os outros, e com o cartão deles: quem
     * escreve "ceifador" na busca da loja quer o card que compra a skin, e não
     * um resultado que só diz que ela existe.
     */
    { id: 'extras', lista: store.extras ?? [], grade: 'mount-grid', cartao: cartaoDeExtra },
    {
      id: 'mounts',
      lista: (store.mounts ?? []).filter((entry) => outfitInfo(entry.look)),
      grade: 'mount-grid',
      cartao: (entry) => cartaoDeVisual(entry, 'mounts'),
    },
    {
      id: 'outfits',
      lista: (store.outfits ?? []).filter((entry) => outfitInfo(entry.look)),
      grade: 'mount-grid',
      cartao: (entry) => cartaoDeVisual(entry, 'outfits'),
    },
  ];

  let total = 0;
  for (const prateleira of prateleiras) {
    const achados = prateleira.lista.filter(bate);
    if (!achados.length) continue;
    total += achados.length;

    // O que já foi adquirido desce para o fim, como no resto da loja.
    const ordenados = [...achados.filter((e) => !e.owned), ...achados.filter((e) => e.owned)];
    const mostrados = ordenados.slice(0, TETO_DA_BUSCA);

    const titulo = el('div', 'store-grupo');
    titulo.append(el('b', null, STORE_SECTIONS[prateleira.id]), el('span', null, `${achados.length} resultado(s)`));
    body.append(titulo);

    const grade = el('div', prateleira.grade);
    for (const entry of mostrados) grade.append(prateleira.cartao(entry));
    body.append(grade);

    if (ordenados.length > mostrados.length) {
      body.append(
        el('p', 'shop-note', `Mostrando ${mostrados.length} de ${ordenados.length} — escreva mais para afinar.`)
      );
    }
  }

  if (!total) body.append(el('p', 'empty', `Nada na loja com "${termo}".`));
}

/**
 * O rodapé da loja: o saldo à esquerda, e como enchê-lo à direita.
 *
 * Fica fora da prateleira de propósito — não rola com ela e não muda quando se
 * troca de seção. É a única coisa da loja que vale em todas as seções.
 */
function storeFooter(store) {
  const rodape = el('div', 'store-footer');

  // À esquerda, o saldo e o que se faz com ele: mandar embora fica colado no
  // número, que é a informação de que essa decisão depende.
  const esquerda = el('div', 'store-footer-esq');

  const saldo = el('div', 'store-footer-saldo');
  saldo.append(uiIcon('coin-store'), el('b', null, money(store.coins)), el('span', null, 'Draevor Coins'));
  esquerda.append(saldo);

  // Os três botões do rodapé com ícone (pedido do dono, 15/09). Ver `.store-botao-icone`.
  const comIcone = (botao, icone, texto) => {
    const caixa = el('span', 'store-botao-icone');
    if (icone) caixa.append(icone);
    botao.append(caixa, el('span', 'store-botao-texto', texto));
    return botao;
  };
  const relogio = () => {
    const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
    svg.setAttribute('viewBox', '0 0 24 24');
    svg.innerHTML =
      '<path d="M3 12a9 9 0 1 0 3-6.7" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"/>' +
      '<path d="M3 4v5h5" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/>' +
      '<path d="M12 7.5V12l3 2" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"/>';
    return svg;
  };

  // Duas setinhas verdes, uma indo e outra voltando.
  const setas = () => {
    const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
    svg.setAttribute('viewBox', '0 0 24 24');
    svg.setAttribute('class', 'store-icone-setas');
    svg.innerHTML =
      '<path d="M4 8h14M14 4l4 4-4 4" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/>' +
      '<path d="M20 16H6M10 12l-4 4 4 4" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/>';
    return svg;
  };
  const transferir = comIcone(el('button', 'store-transferir'), setas(), 'Transferir');
  transferir.onclick = () => abrirTransferir();
  esquerda.append(transferir);

  /*
   * O HISTÓRICO, colado no Transferir. Report da Frida: "era bom ter como ver o
   * histórico de compras da store" — e o dono pediu junto as transferências.
   */
  const historico = comIcone(el('button', 'store-transferir'), relogio(), 'Histórico');
  historico.onclick = () => abrirHistoricoDaLoja();
  esquerda.append(historico);

  /*
   * A STORE INBOX, ao lado do Histórico (15/09): "dentro da mochila, dentro da
   * store e ao lado de histórico". É onde chega o que se compra aqui, então a
   * porta mora na loja também. O número é quantas vagas estão ocupadas.
   */
  const naInbox = (ctx.state.character?.storeInbox ?? []).length;
  const inbox = comIcone(el('button', 'store-transferir store-inbox-botao'), itemCanvas(55368, 32), 'Store Inbox');
  if (naInbox) inbox.append(el('b', 'store-inbox-conta', String(naInbox)));
  tipTexto(inbox, 'Tudo o que você compra na Store chega aqui. De lá as compras saem para a mochila.');
  // A loja é um modal e tampa as janelas: fecha e abre a inbox por cima do jogo.
  inbox.onclick = () => {
    ctx.closeModal?.();
    ctx.abrirStoreInbox?.();
  };
  esquerda.append(inbox);
  rodape.append(esquerda);

  const obter = el('button', 'store-obter');
  obter.append(uiIcon('coin-store'), el('span', null, 'Obter Draevor Coins'));
  if (!store.donate) {
    obter.disabled = true;
    tipTexto(obter, 'A recarga ainda não está ligada neste servidor.');
  }
  obter.onclick = () => abrirObterCoins();
  rodape.append(obter);

  return rodape;
}

/**
 * A moldura das duas janelas do saldo — a de comprar e a de transferir.
 *
 * Elas abrem por cima da loja em vez de trocar de tela, e é a mesma casca nas
 * duas: cabeçalho com título e X, corpo, e clique no fundo para fechar.
 */
function janelaDoSaldo(titulo, variante) {
  const back = el('div', 'coins-back');
  const box = el('div', `coins-box${variante ? ` ${variante}` : ''}`);
  const fechar = () => back.remove();

  const cabeca = el('div', 'coins-head');
  const marca = el('div', 'coins-title');
  marca.append(uiIcon('coin-store'), el('h3', null, titulo));
  cabeca.append(marca);
  const x = el('button', 'coins-x', '×');
  x.onclick = fechar;
  cabeca.append(x);

  const corpo = el('div', 'coins-body');
  box.append(cabeca, corpo);
  back.append(box);
  fecharAoClicarFora(back, fechar);
  document.body.append(back);
  return { corpo, fechar };
}

/*
 * ---- A janela do histórico da loja ----
 *
 * Uma lista só, da mais nova para a mais velha — o dono pediu "tudo junto,
 * informando se foi transferência ou compra, a hora e o char, e a sprite do que
 * foi comprado". Tudo da CONTA: coin é da conta.
 */
const TIPO_DO_HISTORICO = {
  compra: 'Compra na loja',
  recarga: 'Recarga de coins',
  enviada: 'Transferência enviada',
  recebida: 'Transferência recebida',
};

/** A imagem da linha: a arte do produto, a sprite do item, a aparência — ou a moeda. */
function imagemDoHistorico(linha) {
  const caixa = el('div', 'historico-imagem');
  const imagem = linha.imagem;
  if (imagem?.art) {
    const img = document.createElement('img');
    img.src = imagem.art.startsWith('ui:')
      ? `/client/assets/ui/${imagem.art.slice(3)}.png`
      : imagem.art.startsWith('icone:')
        ? `/client/assets/icons/${imagem.art.slice(6)}.png`
        : `/client/assets/store/${imagem.art}.png`;
    img.alt = '';
    img.width = 32;
    img.height = 32;
    img.onerror = () => img.replaceWith(uiIcon('coin-store'));
    caixa.append(img);
  } else if (imagem?.itemId) {
    caixa.append(itemCanvas(imagem.itemId, 32));
  } else if (imagem?.look && outfitInfo(imagem.look)) {
    caixa.append(outfitCanvas(imagem.look, null, 32, 2, true));
  } else {
    caixa.append(uiIcon('coin-store'));
  }
  return caixa;
}

export function abrirHistoricoDaLoja() {
  const { corpo, fechar } = janelaDoSaldo('Histórico da loja', 'historico-loja');
  let linhas = null;
  let erro = null;

  const quando = (ms) =>
    new Date(ms).toLocaleString('pt-BR', { day: '2-digit', month: '2-digit', year: '2-digit', hour: '2-digit', minute: '2-digit' });

  const desenhar = () => {
    if (!corpo.isConnected) {
      ctx.aoHistoricoDaLoja = null;
      ctx.recarregarHistoricoDaLoja = null;
      return;
    }
    corpo.innerHTML = '';
    if (!linhas) return void corpo.append(el('p', 'gate-note', 'Carregando o histórico...'));
    // O servidor não conseguiu ler: dizer isso, e não "nenhuma compra".
    if (erro) return void corpo.append(el('p', 'gate-note', erro));

    const lista = el('div', 'historico-lista rolagem');
    if (!linhas.length) lista.append(el('p', 'empty', 'Nada por aqui ainda: nenhuma compra, recarga ou transferência.'));
    for (const linha of linhas) {
      const l = el('div', `historico-linha ${linha.coins >= 0 ? 'entrou' : 'saiu'}`);
      l.append(imagemDoHistorico(linha));
      const meio = el('div', 'historico-meio');
      meio.append(el('span', 'historico-oque', linha.titulo));
      meio.append(el('small', 'historico-tipo',
        [TIPO_DO_HISTORICO[linha.tipo] ?? linha.tipo, linha.personagem].filter(Boolean).join(' · ')));
      l.append(meio);
      l.append(el('span', 'historico-quando', quando(linha.em)));
      // O valor com a moedinha da Draevor Coin do lado, pequena.
      const valor = el('b', 'historico-valor', `${linha.coins >= 0 ? '+' : '−'}${money(Math.abs(linha.coins))}`);
      valor.append(uiIcon('coin-store'));
      l.append(valor);
      lista.append(l);
    }
    corpo.append(lista);
    corpo.append(el('small', 'historico-nota', 'As transferências entre jogadores são registradas desde 12/09/2026; as anteriores não ficaram guardadas.'));
  };

  ctx.aoHistoricoDaLoja = (mensagem) => {
    linhas = mensagem.linhas ?? [];
    erro = mensagem.erro ?? null;
    desenhar();
  };
  /*
   * A prateleira voltou (`store`, depois de uma compra) com a janela aberta:
   * pede as linhas de novo, para a compra nova aparecer sem fechar e abrir.
   * Fechada, não pede nada.
   */
  ctx.recarregarHistoricoDaLoja = () => {
    if (corpo.isConnected) ctx.send({ t: 'historicoDaLoja' });
    else ctx.recarregarHistoricoDaLoja = null;
  };
  desenhar();
  ctx.send({ t: 'historicoDaLoja' });
  return fechar;
}

/** Transferir coins, agora numa janela por cima da loja. */
export function abrirTransferir() {
  const { corpo } = janelaDoSaldo('Transferir Draevor Coins', 'transferencia');
  renderTransfer(corpo);
}

/*
 * ---- Um cartao por produto, e nao um cartao por prateleira ----
 *
 * Cada secao montava os proprios cartoes dentro do proprio laco. Enquanto so'
 * existia a navegacao por secao isso bastava; a busca precisa dos MESMOS
 * cartoes fora da secao deles — um resultado de "premium" tem de ser o cartao de
 * premium, com a arte, o preco e o botao que ja funcionam. Entao a montagem de
 * cada tipo de cartao saiu para uma funcao, e tanto a secao quanto a busca
 * chamam a mesma.
 */
function cartaoDeServico(service) {
  const { state, send } = ctx;
  const store = state.store;
  const card = el('div', `store-card${service.owned ? ' owned' : ''}`);
  const arte = storeArt(service);
  if (arte) card.append(arte);
  card.append(el('b', null, service.name));
  // `destaqueAzul`: a frase que o servidor quer em azul, antes da descrição.
  if (service.destaqueAzul) card.append(el('strong', 'store-destaque store-destaque-azul', service.destaqueAzul));
  card.append(el('em', null, service.blurb));
  const buy = el('button');
  // O passe do Auto Boss é da conta: diz até quando, e que vale em todos os chars.
  if (service.kind === 'autoBoss' && service.owned && service.ativoAte > Date.now()) {
    card.append(el('em', null, `Ativo na conta — faltam ${formatLeft(service.ativoAte - Date.now())}. Vale para todos os personagens.`));
  }
  if (service.owned) {
    buy.textContent = 'já adquirido';
    buy.disabled = true;
  } else {
    buy.append(uiIcon('coin-store'), document.createTextNode(money(service.coins)));
    buy.onclick = () =>
      confirmPurchase({
        title: service.name,
        cost: service.coins,
        balance: store.coins,
        onConfirm: () => send({ t: 'store', action: 'buy', id: service.id }),
      });
  }
  card.append(buy);
  return card;
}

/*
 * O cartão certo para uma entrada de Serviços.
 *
 * A prateleira tem duas espécies desde que o Instance Hunts entrou nela: os
 * serviços de sempre, que têm `art` (um PNG por nome) e ligam alguma coisa na
 * conta, e um ITEM, que tem `itemId` e desenho por sprite. `itemId` é o que os
 * separa, e é o mesmo critério que a prateleira de Boosts usa ao contrário para
 * o XP Boost — ver `renderBoosts`.
 */
const cartaoDaPrateleiraDeServicos = (entry) =>
  entry.itemId ? cartaoDeItem(entry) : cartaoDeServico(entry);

/*
 * ---- Um passe de conta num card só, com os prazos lado a lado ----
 *
 * "da pra colocar o auto boss da store no mesmo card? só que meio que separado
 *  bonito?"
 *
 * São o MESMO produto com dois prazos — o servidor não tem produto novo
 * nenhum, só uma linha de catálogo a mais com outro `days`. Dois cards
 * repetiam a arte, o nome e a descrição inteira, e faziam a pessoa ler duas
 * vezes para comparar dois números.
 *
 * Aqui a descrição aparece uma vez e os prazos ficam numa faixa própria
 * embaixo, um por linha. A COMPRA continua sendo a de cada um: cada botão manda
 * o `id` da sua entrada, então o servidor não sabe que eles viraram um card só
 * — e não precisa saber.
 *
 * ---- E vale para QUALQUER passe, não só o do Auto Boss ----
 *
 * Isto era `cartaoDeAutoBoss`, com o nome e a descrição escritos aqui dentro. O
 * Auto Task chegou com a mesma forma ("mesma coisa praticamente", disse o
 * dono), e copiar a função daria dois lugares para consertar a próxima vez que
 * a descrição mudar — com a garantia de que só um dos dois seria consertado.
 *
 * O nome e a descrição passam a vir do CATÁLOGO, que é onde eles já estavam. Só
 * o prazo sai do nome ("Auto Boss sem limite — 7 dias (conta)" vira "Auto Boss
 * sem limite"), porque num card que oferece os dois prazos anunciar um deles no
 * título é mentira.
 */
const PASSES_EM_UM_CARD = new Set(['autoBoss', 'autoTask']);

function cartaoDePasse(passes) {
  const { state, send } = ctx;
  const store = state.store;
  const base = passes[0];
  const ativo = passes.find((p) => p.owned && p.ativoAte > Date.now());

  const card = el('div', `store-card${ativo ? ' owned' : ''}`);
  const arte = storeArt(base);
  if (arte) card.append(arte);
  card.append(el('b', null, String(base.name ?? '').replace(/\s*—\s*\d+\s*dias?.*$/i, '').trim()));
  card.append(el('strong', 'store-destaque store-destaque-azul', 'Vale para TODOS os personagens da conta.'));
  card.append(el('em', null, base.blurb));

  if (ativo) {
    card.append(el('em', 'auto-boss-ativo',
      `Ativo na conta — faltam ${formatLeft(ativo.ativoAte - Date.now())}. Vale para todos os personagens.`));
    const pronto = el('button');
    pronto.textContent = 'já adquirido';
    pronto.disabled = true;
    card.append(pronto);
    return card;
  }

  /*
   * O mais curto primeiro, e o desconto do maior dito em coins.
   *
   * "menos que o dobro" é uma frase; "economize 80" é a conta feita. E ela é
   * CALCULADA dos dois preços — se um deles mudar amanhã, o desconto anunciado
   * muda junto em vez de virar mentira.
   */
  const ordenados = passes.slice().sort((um, outro) => (um.days ?? 0) - (outro.days ?? 0));
  const menor = ordenados[0];
  const faixa = el('div', 'store-opcoes');
  for (const passe of ordenados) {
    const linha = el('div', 'store-opcao');
    const rotulo = el('span', 'store-opcao-prazo', `${passe.days} dias`);
    const proporcional = menor && menor.days
      ? Math.round((menor.coins / menor.days) * passe.days) - passe.coins
      : 0;
    if (proporcional > 0) rotulo.append(el('i', 'store-opcao-desconto', `economize ${money(proporcional)}`));
    linha.append(rotulo);

    const botao = el('button');
    botao.append(uiIcon('coin-store'), document.createTextNode(money(passe.coins)));
    botao.onclick = () =>
      confirmPurchase({
        title: passe.name,
        cost: passe.coins,
        balance: store.coins,
        onConfirm: () => send({ t: 'store', action: 'buy', id: passe.id }),
      });
    linha.append(botao);
    faixa.append(linha);
  }
  card.append(faixa);
  return card;
}

function renderServices(body) {
  const { state } = ctx;
  const store = state.store;
  body.append(collectionBanner(state.character));

  const grid = el('div', 'store-grid');
  // Já adquirido desce para o fim, como o resto da loja.
  const services = [...store.services.filter((s) => !s.owned), ...store.services.filter((s) => s.owned)];
  /*
   * Os passes de conta saem da fila e viram UM card por espécie, no lugar do
   * primeiro de cada uma — a ordem da vitrine continua sendo a do servidor.
   */
  const jaPostos = new Set();
  for (const service of services) {
    if (PASSES_EM_UM_CARD.has(service.kind)) {
      if (jaPostos.has(service.kind)) continue;
      jaPostos.add(service.kind);
      grid.append(cartaoDePasse(services.filter((s) => s.kind === service.kind)));
      continue;
    }
    grid.append(cartaoDaPrateleiraDeServicos(service));
  }
  body.append(grid);
}

/*
 * ---- As armas de treino ----
 *
 * A categoria "Exercise Weapons" da gamestore do dono, com os preços dele. São
 * consumíveis: nenhuma some da prateleira depois de comprada, e comprar a
 * segunda é o uso normal.
 *
 * Os cards vêm agrupados por DEGRAU, e não misturados por perícia. Quem entra
 * aqui já sabe que arma quer (a da perícia dele) e está escolhendo QUANTO
 * comprar — as boosted em cima, porque são as melhores e é o que ele vende.
 */
function renderExercises(body) {
  const store = ctx.state.store;
  const lista = store.exercises ?? [];
  body.append(
    el(
      'p',
      'shop-note',
      'Cada golpe gasta uma carga e vale sete vezes um golpe de treino comum. As boosted rendem mais 30%. A arma fica na mão até as cargas acabarem.',
    ),
  );
  if (!lista.length) return void body.append(el('p', 'empty', 'Nada por aqui ainda.'));

  const TITULOS = {
    boosted: 'Boosted — 30% mais rápido',
    durable: 'Durable',
    lasting: 'Lasting',
    exercise: 'Exercise',
  };
  for (const degrau of ['boosted', 'durable', 'lasting', 'exercise']) {
    const doDegrau = lista.filter((arma) => arma.degrau === degrau);
    if (!doDegrau.length) continue;
    body.append(el('h4', 'store-degrau', TITULOS[degrau] ?? degrau));
    const grid = el('div', 'store-grid');
    for (const arma of doDegrau) grid.append(cartaoDeExercicio(arma));
    body.append(grid);
  }
}

/*
 * ---- Boosts: as poções de experiência e o pergaminho ----
 *
 * Três produtos, e o que diferencia os dois primeiros é um número dentro do
 * nome ("50%" e "75%"). Por isso o card diz a força e a duração em linha
 * própria, e não só no nome: numa prateleira, dois cards quase idênticos lado a
 * lado são o arranjo em que a pessoa compra o errado.
 */
function renderBoosts(body) {
  const { state, send } = ctx;
  const store = state.store;
  const lista = store.boosts ?? [];
  body.append(
    el(
      'p',
      'shop-note',
      'O XP Boost liga na hora da compra. Os outros vão para a mochila e se usam quando você quiser — clique com o botão direito no item e escolha "Usar". Um boost de experiência mais forte nunca é apagado por um mais fraco: usar dois iguais soma o tempo.',
    ),
  );
  if (!lista.length) return void body.append(el('p', 'empty', 'Nada por aqui ainda.'));

  const grid = el('div', 'store-grid');
  for (const item of lista) {
    /*
     * ---- Boost que se compra aos montes ----
     *
     * As pocoes e a stamina vem com `opcoes` do servidor, e entao usam o mesmo
     * cartao do Summon Upgrade e do Tier Up. E' o cartao que ja sabe desenhar a
     * escada de desconto e lembrar a quantidade escolhida — ensinar o cartao de
     * item a fazer isso de novo seria a segunda copia da mesma tela.
     *
     * O `kind` vai daqui e nao do servidor porque e' escolha de DESENHO: o
     * servidor diz que ha opcoes, e a tela decide como mostra-las.
     */
    if (item.opcoes?.length > 1) {
      grid.append(cartaoDeQuantidade({ ...item, kind: 'quantidade' }));
      continue;
    }

    /*
     * O XP Boost mora nesta prateleira mas não é item: ele não vai para a
     * mochila, liga na hora da compra e não tem desenho por id. O card de
     * serviço já sabe desenhar isso — reaproveitá-lo é melhor do que ensinar o
     * card de item a fingir que existe um `itemId`.
     */
    if (item.servico) {
      grid.append(cartaoDeServico(item));
      continue;
    }
    /*
     * ---- O card que veio ACESO ----
     *
     * Quem chega aqui pelo atalho do treino ("Treine em dobro") veio buscar UM
     * produto, e a prateleira tem cinco. `storeDestaque` é o id dele: o card
     * acende e rola para a vista, e a marca se apaga em seguida — ela vale a
     * chegada, e não a estadia.
     */
    const aceso = ctx.tabs.storeDestaque === item.itemId;
    const card = el('div', `store-card util-card${aceso ? ' store-destaque' : ''}`);
    if (aceso) {
      requestAnimationFrame(() => card.scrollIntoView({ block: 'nearest' }));
      ctx.tabs.storeDestaque = null;
    }
    /*
     * O MESMO quadro das outras prateleiras (`storeArt`): moldura de 70px e o
     * sprite em dobro exato. Aqui o desenho era solto e menor, e era por isso
     * que a poção e o pacote pareciam miúdos ao lado do XP Boost — ver a nota
     * de `storeArt`.
     */
    const arte = storeArt({ itemId: item.itemId });
    if (arte) card.append(arte);
    card.append(el('b', null, item.name));
    card.append(el('em', null, item.blurb));
    /*
     * O que o item entrega, na unidade DELE.
     *
     * Os dois boosts e o pergaminho entregam tempo; a Stamina Extension entrega
     * stamina. Escrever a duração de todos daria "NaN" no card dela — ela não
     * tem duração nenhuma, e nunca teve.
     */
    if (item.duracao) card.append(el('em', 'exercise-cargas', duracaoCurta(Math.round(item.duracao / 1000))));
    else if (item.minutos) card.append(el('em', 'exercise-cargas', `+${duracaoCurta(item.minutos * 60)} de stamina`));
    if (item.tem) card.append(el('em', 'exercise-tem', `você tem ${item.tem}`));

    const buy = el('button');
    buy.append(uiIcon('coin-store'), document.createTextNode(money(item.coins)));
    buy.onclick = () =>
      confirmPurchase({
        title: item.name,
        cost: item.coins,
        balance: store.coins,
        preview: itemCanvas(item.itemId, 48),
        onConfirm: () => send({ t: 'store', action: 'buy', id: item.id }),
      });
    card.append(buy);
    grid.append(card);
  }
  body.append(grid);
}

/*
 * ---- A prateleira Buff Power ----
 *
 * "coloca na store uma nova aba chamada Buff Power e coloca esses itens, 200
 *  Draevor Coins cada, ou os 3 por 500 Draevor Coins."
 *
 * Ela é irmã de Boosts e fica ao lado dela de propósito: as duas vendem TEMPO.
 * A diferença é o que a pessoa leva para casa — em Boosts o item some quando é
 * usado, e aqui ele fica para sempre e o que se gasta a cada clique é o preço
 * da hora.
 *
 * Essa diferença é a única coisa que a prateleira precisa explicar, e por isso
 * ela está na primeira linha da tela e no card de cada um: quem não entender
 * isso acha que comprou uma poção cara.
 */
function renderBuffPower(body) {
  const { state, send } = ctx;
  const store = state.store;
  const lista = store.buffpower ?? [];

  /*
   * ---- O aviso que precisa ser LIDO antes da compra ----
   *
   * "deixa destacado na store que a pessoa tem que pagar pra usar, porque ela
   *  pode pensar que é só comprar e já usa."
   *
   * E ela pensaria com razão: em toda a loja, comprar É receber a coisa. Aqui
   * os 200 coins compram a CHAVE, e cada hora de bônus se paga à parte — em
   * ouro nos dois primeiros, em coin no terceiro. Quem descobrir isso depois de
   * comprar vai achar, com razão, que foi enganado.
   *
   * Por isso o aviso não é a nota cinza de rodapé que as outras prateleiras
   * usam: é uma caixa acesa no alto, antes dos cards, com a frase mais curta
   * possível em cima. O resto explica depois — quem já entendeu não precisa
   * ler, e quem não entendeu já foi avisado na primeira linha.
   */
  const aviso = el('div', 'buff-aviso');
  aviso.append(el('b', null, 'Comprar não é usar — cada hora de bônus se paga à parte.'));
  aviso.append(
    el(
      'span',
      null,
      'O que você leva aqui é o ITEM, e ele NUNCA some: fica na mochila para sempre. ' +
        'Para ligar uma hora do bônus, clique nele na mochila — e é esse clique que cobra ' +
        '(ouro nos dois primeiros, Draevor Coins no de loot). O preço de cada hora está escrito em cada card.',
    ),
  );
  aviso.append(el('em', null, 'Usar de novo soma mais uma hora, até dez acumuladas.'));
  body.append(aviso);
  if (!lista.length) return void body.append(el('p', 'empty', 'Nada por aqui ainda.'));

  /*
   * O relógio de cada buff, que vem no personagem e não na loja.
   *
   * Ele é o que responde a pergunta de quem já comprou: "quanto ainda tenho?".
   * Sem isso, a prateleira só sabe falar com quem nunca esteve aqui.
   */
  const ligados = new Map((state.character?.efeitos?.buffPower ?? []).map((linha) => [linha.item, linha]));

  const grid = el('div', 'store-grid');
  for (const item of lista) {
    // O trio é uma compra e não um item: ele não tem `itemId` nem desenho por id.
    if (item.kind === 'buffTrio') continue;

    const card = el('div', 'store-card util-card');
    const arte = storeArt({ itemId: item.itemId });
    if (arte) card.append(arte);
    card.append(el('b', null, item.name));
    card.append(el('em', null, item.nota ?? item.resumo ?? ''));

    /*
     * O PREÇO DA HORA, que é o número que importa depois da compra.
     *
     * Ele vem do servidor (`efeitos.buffPower[].custo`) e não escrito aqui: os
     * dois que cobram ouro e o que cobra coin mudaram de preço uma vez antes
     * mesmo de entrar no ar, e um número escrito na tela não acompanharia.
     */
    const linha = ligados.get(item.itemId);
    if (linha?.custo) {
      // `buff-custo` e nao a classe cinza das cargas: este numero e' o que a
      // pessoa NAO esperava existir, e ele nao pode ler como nota de rodape.
      const custo = el('em', 'exercise-cargas buff-custo');
      custo.append(document.createTextNode('cada hora custa '));
      if (linha.custo.moeda === 'coins') {
        custo.append(uiIcon('coin-store'), document.createTextNode(` ${money(linha.custo.quanto)}`));
      } else {
        custo.append(document.createTextNode(`${money(linha.custo.quanto)} de ouro`));
      }
      card.append(custo);
    }
    if (linha?.restante > 0) {
      card.append(el('em', 'exercise-tem', `ligado — ${duracaoCurta(Math.round(linha.restante / 1000))} restantes`));
    } else if (item.tem) {
      card.append(el('em', 'exercise-tem', `você já tem ${item.tem} — clique nele na mochila`));
    }

    const buy = el('button');
    buy.append(uiIcon('coin-store'), document.createTextNode(money(item.coins)));
    buy.onclick = () =>
      confirmPurchase({
        title: item.name,
        cost: item.coins,
        balance: store.coins,
        preview: itemCanvas(item.itemId, 48),
        onConfirm: () => send({ t: 'store', action: 'buy', id: item.id }),
      });
    card.append(buy);
    grid.append(card);
  }
  body.append(grid);

  /*
   * ---- E o trio, embaixo ----
   *
   * Depois dos três e não antes: o pacote é a conta de quem já entendeu o que
   * cada um faz. Vender antes de explicar é o que faz alguém pagar 500 e
   * descobrir depois que só queria um.
   */
  const trio = lista.find((entry) => entry.kind === 'buffTrio');
  if (!trio) return;

  const caixa = el('div', 'store-card util-card buff-trio');
  caixa.append(el('b', null, trio.name));
  caixa.append(el('em', null, trio.blurb));

  const figuras = el('div', 'buff-trio-arte');
  for (const peca of trio.itens ?? []) {
    const arte = itemCanvas(peca.itemId, 32);
    if (arte) {
      const moldura = el('i', 'buff-trio-peca');
      moldura.append(arte);
      tipFor(moldura, peca.itemId);
      figuras.append(moldura);
    }
  }
  caixa.append(figuras);

  const levar = el('button', 'primary');
  levar.append(uiIcon('coin-store'), document.createTextNode(money(trio.coins)));
  levar.onclick = () =>
    confirmPurchase({
      title: trio.name,
      cost: trio.coins,
      balance: store.coins,
      onConfirm: () => send({ t: 'store', action: 'buy', id: trio.id }),
    });
  caixa.append(levar);
  body.append(caixa);
}

/*
 * ---- Pacotes ----
 *
 * O card mostra O QUE VEM DENTRO, item por item, e o preço avulso riscado ao
 * lado do preço do pacote. Um pacote é uma compra que a pessoa faz de olho na
 * conta — "vale a pena?" é literalmente a pergunta —, e escondê-la atrás de um
 * "economize!" sem número transforma a oferta em promessa.
 */
function renderPacotes(body) {
  const { state, send } = ctx;
  const store = state.store;
  const lista = store.pacotes ?? [];
  body.append(el('p', 'shop-note', 'O conteúdo cai direto na mochila: não há caixa para abrir nem espaço para perder.'));
  if (!lista.length) return void body.append(el('p', 'empty', 'Nada por aqui ainda.'));

  const grid = el('div', 'store-grid pacote-grid');
  for (const pacote of lista) {
    const card = el('div', 'store-card util-card pacote-card');
    // O mesmo quadro das outras prateleiras. Ver `storeArt`.
    const arte = storeArt({ itemId: pacote.itemId });
    if (arte) card.append(arte);
    card.append(el('b', null, pacote.name));
    card.append(el('em', null, pacote.blurb));

    const dentro = el('ul', 'pacote-conteudo');
    for (const peca of pacote.conteudo) {
      const linha = el('li');
      const icone = itemCanvas(peca.itemId, 24);
      if (icone) linha.append(icone);
      linha.append(el('span', null, `${peca.count}× ${peca.name}`));
      dentro.append(linha);
    }
    card.append(dentro);

    if (pacote.economia > 0) {
      const conta = el('div', 'pacote-conta');
      conta.append(el('s', null, money(pacote.cheio)));
      conta.append(el('i', null, `−${pacote.desconto}%`));
      card.append(conta);
    }

    const buy = el('button');
    buy.append(uiIcon('coin-store'), document.createTextNode(money(pacote.coins)));
    buy.onclick = () =>
      confirmPurchase({
        title: pacote.name,
        cost: pacote.coins,
        balance: store.coins,
        preview: itemCanvas(pacote.itemId, 48),
        onConfirm: () => send({ t: 'store', action: 'buy', id: pacote.id }),
      });
    card.append(buy);
    grid.append(card);
  }
  body.append(grid);
}

/**
 * A escolha dentro de uma Boosted Exercise Box.
 *
 * A mesma tela do presente de nível, e de propósito: são o mesmo gesto (escolher
 * uma arma de uma lista fechada) e a pessoa já aprendeu este desenho uma vez.
 * Aqui não há passo de confirmação porque a caixa se compra às unidades — errar
 * a arma custa uma caixa, e não o presente do level 50.
 */
export function openCaixaBoosted(escolhas) {
  ctx.openModal('Boosted Exercise Box', (body) => {
    body.append(
      el('p', 'shop-note', 'Escolha uma boosted exercise weapon com 64.400 cargas. Elas treinam 30% mais rápido no boneco.'),
    );
    const grid = el('div', 'presente-escolha');
    for (const arma of escolhas ?? []) {
      const botao = el('button');
      const arte = itemCanvas(arma.arte ?? arma.itemId, 40);
      if (arte) botao.append(arte);
      botao.append(el('b', null, arma.name));
      botao.append(el('em', null, PERICIA_EM_PT[arma.skill] ?? arma.skill));
      botao.onclick = () => {
        ctx.send({ t: 'caixa', itemId: arma.itemId });
        ctx.closeModal?.();
      };
      grid.append(botao);
    }
    body.append(grid);
  });
}

/** O nome da perícia como o jogador a conhece. */
const PERICIA_EM_PT = {
  melee: 'melee fighting',
  sword: 'melee fighting',
  axe: 'melee fighting',
  club: 'melee fighting',
  distance: 'distance fighting',
  shielding: 'shielding',
  fist: 'melee fighting',
  magic: 'magic level',
};

function cartaoDeExercicio(arma) {
  const { state, send } = ctx;
  const store = state.store;
  const card = el('div', 'store-card util-card');

  // O mesmo quadro das outras prateleiras. Ver `storeArt`.
  const arte = storeArt({ itemId: arma.arte ?? arma.itemId });
  if (arte) card.append(arte);
  card.append(el('b', null, arma.name));
  card.append(el('em', null, `Treina ${PERICIA_EM_PT[arma.skill] ?? arma.skill}.`));
  /*
   * Cargas E tempo. O número de cargas é o que o jogador compara entre duas
   * ofertas; as horas são o que ele consegue imaginar. Só um dos dois deixaria
   * metade das pessoas sem entender o que está levando.
   */
  card.append(
    el('em', 'exercise-cargas', `${arma.cargas.toLocaleString('pt-BR')} cargas · ${duracaoCurta(arma.duracao)}`),
  );
  if (arma.tem) card.append(el('em', 'exercise-tem', `você tem ${arma.tem}`));

  const buy = el('button');
  buy.append(uiIcon('coin-store'), document.createTextNode(money(arma.coins)));
  buy.onclick = () =>
    confirmPurchase({
      title: arma.name,
      cost: arma.coins,
      balance: store.coins,
      preview: itemCanvas(arma.arte ?? arma.itemId, 48),
      onConfirm: () => send({ t: 'store', action: 'buy', id: arma.id }),
    });
  card.append(buy);
  return card;
}

/** "7h09" / "4min" — o suficiente para comparar duas ofertas de relance. */
function duracaoCurta(segundos) {
  if (!segundos) return '—';
  const horas = Math.floor(segundos / 3600);
  const minutos = Math.round((segundos % 3600) / 60);
  if (horas && minutos) return `${horas}h${String(minutos).padStart(2, '0')}`;
  if (horas) return `${horas}h`;
  return `${Math.max(1, minutos)}min`;
}

/** Itens que vão para a mochila — hoje, a mochila grande. */
/*
 * ---- As gavetas da prateleira de Itens ----
 *
 * O rótulo e o desenho de cada uma. A ORDEM daqui é a ordem em que elas
 * aparecem, e ela não é alfabética: é a de quem procura — primeiro o que muda o
 * combate (armas, armadura), depois os acessórios, e a mochila por último.
 *
 * O desenho é o mesmo cartão vazio que o inventário põe em cada slot
 * (`client/assets/slots`), e é de propósito: o filtro pergunta "onde isto se
 * veste?", e a resposta já tem uma figura conhecida na tela ao lado.
 */
const ITEM_CATEGORIAS = [
  { id: 'armas', nome: 'Armas', arte: 'right-hand' },
  { id: 'armadura', nome: 'Armadura', arte: 'body' },
  { id: 'aneis', nome: 'Anéis', arte: 'finger' },
  { id: 'amuletos', nome: 'Amuletos', arte: 'neck' },
  { id: 'trinkets', nome: 'Trinkets', arte: 'ammo' },
  { id: 'mochilas', nome: 'Mochilas', arte: 'back' },
  { id: 'outros', nome: 'Outros', arte: null },
];

/*
 * As vocações, com o ícone da perícia de cada uma.
 *
 * Não há arte de vocação na pasta — o que existe são os painéis da árvore, de
 * 1122x1402, que a 20 pixels seriam dois megabytes e meio para desenhar um
 * quadradinho. O ícone da PERÍCIA diz a mesma coisa e já está lá: quem usa
 * espada é knight, quem usa distância é paladin.
 *
 * Sorcerer e druid dividem o da magia, e é honesto: as duas são vocações de
 * magia, e o nome ao lado separa uma da outra.
 */
const ITEM_VOCACOES = [
  { id: 'knight', nome: 'Knight', arte: 'sk-sword' },
  { id: 'paladin', nome: 'Paladin', arte: 'sk-distance' },
  { id: 'sorcerer', nome: 'Sorcerer', arte: 'sk-magic' },
  { id: 'druid', nome: 'Druid', arte: 'sk-magic' },
  { id: 'monk', nome: 'Monk', arte: 'sk-fist' },
];

/** O cartão vazio do slot, o mesmo desenho que o inventário usa. */
function slotArt(nome, size = 22) {
  const img = document.createElement('img');
  img.className = 'filtro-arte';
  img.width = size;
  img.height = size;
  img.src = `/client/assets/slots/${nome}.png`;
  img.alt = '';
  img.onerror = () => img.remove();
  return img;
}

/*
 * ---- A prateleira de Itens ----
 *
 * Tudo que o personagem veste ou carrega, comprado com coins. O card diz o
 * essencial para se escolher de relance — os números, a vocação e o level — e o
 * balão do item, que 'storeArt' já pendura no desenho, conta o resto.
 *
 * ---- Os dois filtros ----
 *
 * Onze itens já não cabem numa olhada, e vão ser mais: duas perguntas resolvem
 * quase toda busca aqui, e são sempre as mesmas — "que TIPO de peça eu quero?" e
 * "o que serve para o MEU personagem?".
 *
 * Os dois começam abertos ("Tudo"), porque a prateleira tem de mostrar o que
 * tem antes de pedir que se escolha. E só aparecem as gavetas que têm alguma
 * coisa dentro: um filtro que devolve zero é um botão que ensina a não confiar
 * nos botões — quando o elmo e a armadura Falcon entrarem, "Armadura" aparece
 * sozinha.
 */
function renderItens(body) {
  const { state } = ctx;
  const store = state.store;
  const lista = store.itens ?? [];

  const categoria = ctx.tabs.itensCategoria ?? 'tudo';
  const vocacao = ctx.tabs.itensVocacao ?? 'tudo';

  const filtros = el('div', 'item-filtros');

  /*
   * Uma fileira de fichas. `atual` é a escolhida, `escolher` guarda e redesenha.
   *
   * A ficha "Tudo" vem primeiro e não tem desenho: ela é a ausência de filtro, e
   * um ícone para "nada" seria uma charada.
   */
  const fileira = (rotulo, opcoes, atual, escolher, totalDoTudo) => {
    const linha = el('div', 'item-filtro-linha');
    linha.append(el('span', 'item-filtro-rotulo', rotulo));
    const fichas = el('div', 'item-filtro-fichas');
    const ficha = (id, nome, desenho, conta) => {
      const botao = el('button', 'item-filtro-ficha');
      botao.type = 'button';
      botao.setAttribute('aria-selected', String(atual === id));
      if (desenho) botao.append(desenho);
      botao.append(el('span', null, nome));
      if (conta != null) botao.append(el('i', null, String(conta)));
      botao.onclick = () => {
        escolher(id);
        ctx.redraw();
      };
      fichas.append(botao);
    };
    /*
     * O "Tudo" conta o que ELE mostra, e não a soma das outras fichas.
     *
     * Somá-las parecia igual e não é: uma mochila não é de vocação nenhuma, e
     * por isso não entra em nenhuma das cinco fichas de vocação. Pela soma, o
     * "Tudo" da linha de vocação dizia 6 com onze itens na tela.
     */
    ficha('tudo', 'Tudo', null, totalDoTudo);
    for (const opcao of opcoes) ficha(opcao.id, opcao.nome, opcao.desenho, opcao.conta);
    linha.append(fichas);
    return linha;
  };

  /*
   * As contagens saem da lista JÁ FILTRADA pelo outro filtro.
   *
   * Assim o número em cada ficha é o que aquele clique vai mostrar de verdade —
   * com "Knight" ligado, "Armas" diz 3 e não 6. Uma ficha que promete seis e
   * entrega três é pior do que ficha nenhuma.
   */
  const serveA = (entry, voc) => voc === 'tudo' || !entry.vocations?.length || entry.vocations.includes(voc);
  const daCategoria = (entry, cat) => cat === 'tudo' || entry.categoria === cat;

  const categorias = ITEM_CATEGORIAS.map((cat) => ({
    id: cat.id,
    nome: cat.nome,
    desenho: cat.arte ? slotArt(cat.arte) : null,
    conta: lista.filter((entry) => entry.categoria === cat.id && serveA(entry, vocacao)).length,
  })).filter((cat) => cat.conta > 0);

  const vocacoes = ITEM_VOCACOES.map((voc) => ({
    id: voc.id,
    nome: voc.nome,
    desenho: artOrUiIcon(voc.arte, ''),
    conta: lista.filter((entry) => entry.vocations?.includes(voc.id) && daCategoria(entry, categoria)).length,
  })).filter((voc) => voc.conta > 0);

  if (categorias.length > 1) {
    filtros.append(
      fileira(
        'Tipo',
        categorias,
        categoria,
        (id) => (ctx.tabs.itensCategoria = id),
        lista.filter((entry) => serveA(entry, vocacao)).length
      )
    );
  }
  if (vocacoes.length > 1) {
    filtros.append(
      fileira(
        'Vocação',
        vocacoes,
        vocacao,
        (id) => (ctx.tabs.itensVocacao = id),
        lista.filter((entry) => daCategoria(entry, categoria)).length
      )
    );
  }
  if (filtros.children.length) body.append(filtros);

  /*
   * Com o filtro em "Tudo", as peças da casa vêm na frente.
   *
   * `destaque` vem do servidor (0 para as Draevor, 1 para o resto) porque ordem de
   * vitrine é decisão de loja. Dentro de uma gaveta a ordem fica como está: ali
   * a comparação é entre iguais, e reordenar esconderia a diferença de preço.
   *
   * `slice()` antes do `sort`: ele ordena no lugar, e a lista é a do estado —
   * mexer nela reordenaria também a busca e a próxima abertura da loja.
   */
  let mostrados = lista.filter((entry) => daCategoria(entry, categoria) && serveA(entry, vocacao));
  if (categoria === 'tudo') {
    mostrados = mostrados.slice().sort((a, b) => (a.destaque ?? 1) - (b.destaque ?? 1));
  }
  const grid = el('div', 'store-grid');
  for (const entry of mostrados) grid.append(cartaoDeItem(entry));
  body.append(grid);

  if (!mostrados.length) {
    body.append(el('p', 'empty', lista.length ? 'Nada nesta gaveta.' : 'Nada por aqui ainda.'));
  }
}

function cartaoDeItem(entry) {
  const { state, send } = ctx;
  const store = state.store;
  const card = el('div', 'store-card item-card');
  const arte = storeArt(entry);
  if (arte) card.append(arte);

  // O nome vem do items.xml em minúsculas ('falcon longsword'); quem o veste é
  // a folha de estilo, com 'capitalize' — como no resto do jogo.
  card.append(el('b', 'item-card-nome', entry.name));
  if (entry.resumo) card.append(el('em', 'item-card-resumo', entry.resumo));
  // A nota só existe onde os números não bastam — "o dobro da que vem no kit".
  if (entry.nota) card.append(el('em', null, entry.nota));

  /*
   * ---- E a bag que a compra leva a conseguir ----
   *
   * Só os dois pergaminhos de acesso têm uma (ver `bag`, em `ITENS_A_VENDA`).
   * O desenho fica embaixo da nota, e o balão dele lista as peças que podem
   * sair — que é a pergunta que decide a compra: "vale 50 coins?".
   */
  if (entry.bag) {
    const premio = el('div', 'item-card-bag');
    const figura = el('i', 'item-card-bag-arte');
    try {
      figura.append(itemCanvas(entry.bag, 28));
    } catch {
      /* sem sprite fica só a frase */
    }
    tipFor(figura, entry.bag);
    premio.append(figura);
    premio.append(el('span', null, 'passe o mouse para ver o que pode vir'));
    card.append(premio);
  }

  /*
   * A regra de quem pode usar, na cor do aviso quando ela não bate.
   *
   * Vermelho não impede a compra — dá para comprar hoje a arma do level 300 e
   * guardá-la —, mas impede a compra ENGANADA, que é a única que dá arrependi-
   * mento. A vocação conta junto: uma wand na mochila de um knight é 250 coins
   * que não viram nada nunca.
   */
  const personagem = state.character;
  const faltaLevel = entry.minLevel > (personagem?.level ?? 0);
  // Modelo Path of Exile: não é mais "de outra vocação" — é o requisito de atributo (STR/DEX/INT) que falta.
  const outraVocacao = faltaRequisito(state.items?.[entry.id] ?? entry, personagem);
  const regra = el('span', `item-card-regra${faltaLevel || outraVocacao ? ' nao-serve' : ''}`);
  regra.append(el('i', 'item-card-voc', (entry.vocations ?? []).join(', ') || 'qualquer classe'));
  if (entry.minLevel) regra.append(el('i', null, `level ${entry.minLevel}`));
  if (entry.twoHanded) regra.append(el('i', null, 'duas mãos'));
  card.append(regra);

  const buy = el('button');
  buy.append(uiIcon('coin-store'), document.createTextNode(money(entry.coins)));
  /*
   * ---- O Instance Hunts sem premium ----
   *
   * Ele é o único item da loja que não FUNCIONA sem outra coisa ligada: o
   * pergaminho só liga o acesso se houver premium (ver `ligarAcesso`, no
   * servidor). Comprar sem saber disso é gastar 50 coins numa coisa que fica
   * na mochila sem uso.
   *
   * Então aqui o aviso vem com CAIXINHA, e não como um texto qualquer: sem
   * marcar, o Confirmar não funciona. Não é para impedir a compra — ele
   * continua comprável, e faz sentido comprar hoje e usar amanhã com o premium
   * — é para ela ser deliberada.
   *
   * O que decide é o premium DESTE personagem, agora: `character.premium` é o
   * que falta em milissegundos, o mesmo número que a porta das Especial Hunts
   * lê. Com premium ativo, a caixa de compra é a de sempre.
   */
  /*
   * ---- E o level da PORTA entra na mesma conversa ----
   *
   * O aviso era so' sobre premium, e faltava metade: as Instance abrem no level
   * 800 e as Divine no 1000 (seis delas; as outras cinco no 1300). Quem compra
   * no level 300 gasta 50 coins num passe que nao abre nada — exatamente o mesmo
   * prejuizo de comprar sem premium, e sem aviso nenhum.
   *
   * As duas razoes valem juntas, e a caixinha aparece se QUALQUER uma pegar:
   * quem nao tem premium E esta' abaixo do level precisa saber das duas antes de
   * pagar, nao de uma.
   */
  const passeDeAcesso = entry.itemId === ITEM_INSTANCE_HUNTS || entry.itemId === ITEM_DIVINE_HUNTS;
  const semPremium = passeDeAcesso && (personagem?.premium ?? 0) <= 0;
  const levelDaPorta = passeDeAcesso ? entry.levelDoAcesso ?? 0 : 0;
  const abaixoDaPorta = levelDaPorta > 0 && (personagem?.level ?? 0) < levelDaPorta;
  const naoVaiUsar = semPremium || abaixoDaPorta;

  /*
   * O recado diz o que FALTA, e nao "voce nao pode": faltando as duas coisas,
   * saber de uma so' faria a pessoa comprar premium e descobrir o level depois.
   */
  const oQueFalta = [
    semPremium ? 'nao e premium' : null,
    abaixoDaPorta ? `esta no level ${personagem?.level ?? 0} e a porta abre no ${levelDaPorta}` : null,
  ].filter(Boolean).join(' e ');

  buy.onclick = () =>
    confirmPurchase({
      title: entry.name,
      cost: entry.coins,
      balance: store.coins,
      preview: entry.itemId ? itemCanvas(entry.itemId, 48) : null,
      /*
       * O aviso entra na CONFIRMAÇÃO, e não só no card: é o último instante em
       * que dá para desistir, e é onde a pessoa está olhando quando decide.
       */
      exigencia: levelDaPorta ? `SÓ ENTRA COM LEVEL ${levelDaPorta}+ E PREMIUM ATIVO` : null,
      note: naoVaiUsar
        ? `Atenção: você ${oQueFalta}, então NÃO vai conseguir usar este item agora. ` +
          'Ele fica guardado na mochila até lá — nada se perde, e o relógio de 24 horas só começa quando você usar.'
        : outraVocacao
          ? `${outraVocacao} — o seu personagem ainda não consegue equipá-la (dá para subir o atributo com itens).`
          : faltaLevel
            ? `Pede level ${entry.minLevel}; você está no ${personagem?.level ?? 0}. Ela fica na mochila até lá.`
            : null,
      marcar: naoVaiUsar ? 'Quero comprar mesmo assim' : null,
      onConfirm: () => send({ t: 'store', action: 'buy', id: entry.id }),
    });
  card.append(buy);
  // Quantas já estão na mochila — a pergunta de quem volta à loja e não lembra.
  if (entry.tem) card.append(el('em', 'store-tem', `${entry.tem} na mochila`));
  return card;
}

function renderUtilities(body) {
  const { state, send } = ctx;
  const store = state.store;
  body.append(el('p', 'shop-note', 'Itens que vão direto para a sua mochila.'));

  const grid = el('div', 'store-grid');
  for (const entry of store.utilities ?? []) grid.append(cartaoDeUtilitario(entry));
  if (!(store.utilities ?? []).length) grid.append(el('p', 'empty', 'Nada por aqui ainda.'));
  body.append(grid);
}

function cartaoDeUtilitario(entry) {
  const { state, send } = ctx;
  const store = state.store;
  const card = el('div', 'store-card util-card');
  const arte = storeArt(entry);
  if (arte) card.append(arte);
  card.append(el('b', null, entry.name), el('em', null, entry.blurb));

  const buy = el('button');
  buy.append(uiIcon('coin-store'), document.createTextNode(money(entry.coins)));
  buy.onclick = () =>
    confirmPurchase({
      title: entry.name,
      cost: entry.coins,
      balance: store.coins,
      preview: entry.itemId ? itemCanvas(entry.itemId, 48) : null,
      onConfirm: () => send({ t: 'store', action: 'buy', id: entry.id }),
    });
  card.append(buy);
  return card;
}

/** Melhorias que se compram mais de uma vez, com um teto. */
/*
 * ---- A prateleira Extras ----
 *
 * "quero uma aba chamada Extras na store, e lá vai ter Renomear Summon (...) e
 *  também teria Mudar Aparência do summon".
 *
 * Os dez produtos são do FAMILIAR, e por isso a prateleira abre mostrando o
 * familiar de quem está olhando: o boneco no topo é o que a compra vai mudar.
 * Sem ele, escolher entre nove skins seria escolher entre nove desenhos sem
 * saber qual está posto agora.
 */
function renderExtras(body) {
  const { state, send } = ctx;
  const store = state.store;
  const lista = store.extras ?? [];
  const renome = lista.find((entry) => entry.kind === 'renomearSummon') ?? null;
  const skins = lista.filter((entry) => entry.kind === 'skinDoSummon');
  const resumo = lista.find((entry) => entry.kind === 'resumoDasSkins') ?? null;
  const lote = lista.find((entry) => entry.kind === 'loteDasSkins') ?? null;

  if (!renome && !skins.length) return void body.append(el('p', 'empty', 'Nada por aqui.'));

  body.append(
    el('p', 'shop-note', 'Estes mudam o seu familiar — o nome na plaqueta e o desenho dele em campo.')
  );

  if (resumo) body.append(faixaDasSkins(resumo));

  /*
   * O botão de levar todas, igual ao das montarias e dos outfits.
   *
   * Ele some sozinho quando não falta nenhuma — um lote de zero peças é um botão
   * que a pessoa tem de clicar para descobrir que não serve para ela. E o preço
   * cheio aparece riscado ao lado: desconto que ninguém percebe não faz o que um
   * desconto existe para fazer.
   */
  if (lote?.faltam) {
    const tudo = el('button', 'store-lote');
    tudo.append(
      el('b', null, `Comprar as ${lote.faltam} skin(s) que faltam`),
      el('span', null, `${money(lote.coins)} Draevor Coins`),
    );
    if (lote.desconto && lote.cheio > lote.coins) {
      tudo.append(
        el(
          'em',
          'lote-desconto',
          `de ${money(lote.cheio)} por ${money(lote.coins)} — ${lote.desconto}% de desconto`,
        ),
      );
    }
    const podePagar = (store.coins ?? 0) >= lote.coins;
    if (!podePagar) {
      tudo.classList.add('curto');
      tipTexto(tudo, `Faltam ${money(lote.coins - (store.coins ?? 0))} Draevor Coins.`);
    }
    tudo.onclick = () =>
      confirmPurchase({
        title: `${lote.faltam} skin(s) de summon`,
        cost: lote.coins,
        balance: store.coins ?? 0,
        onConfirm: () => send({ t: 'store', action: 'buy', id: lote.id }),
      });
    body.append(tudo);
  }

  if (renome) body.append(cartaoDeRenome(renome));

  /*
   * O botão de voltar ao padrão só existe quando há skin vestida.
   *
   * Ele desfaz uma escolha, e um botão de desfazer sem nada feito é um botão
   * que a pessoa tem de ler para descobrir que não serve para ela.
   */
  if (skins.some((skin) => skin.emUso)) {
    const voltar = el('button', 'store-lote');
    voltar.append(el('b', null, 'Voltar à aparência da vocação'));
    voltar.onclick = () => send({ t: 'store', action: 'summonSkin', look: null });
    body.append(voltar);
  }

  const grid = el('div', 'mount-grid');
  // O que já é dele desce para o fim, apagado — a mesma ordem das montarias.
  const ordenadas = [...skins.filter((s) => !s.owned), ...skins.filter((s) => s.owned)];
  for (const skin of ordenadas) grid.append(cartaoDeExtra(skin));
  body.append(grid);
}

/*
 * O card do renome: o campo do nome e o preço no mesmo lugar.
 *
 * O campo já vem com o nome de agora escrito, e não vazio: quem volta aqui na
 * maior parte das vezes quer ajustar o que pôs, e um campo vazio faria a pessoa
 * digitar de novo um nome que ela não lembra exatamente.
 */
/*
 * ---- A faixa que diz quanto as skins já pagam ----
 *
 * "isso seja bem explicado".
 *
 * Sem ela a prateleira seria dez cards prometendo cada um a sua fatia, e nenhum
 * lugar dizendo quanto a pessoa TEM somado. É a mesma ideia do
 * `collectionBanner` dos outfits, e as duas metades ficam separadas de
 * propósito: o que vem de TER (e cresce comprando) e o que vem da VESTIDA (e
 * muda ao trocar de desenho) respondem a perguntas diferentes.
 */
function faixaDasSkins(resumo) {
  const faixa = el('div', 'collection-note');
  faixa.append(uiIcon('prey-damage'));

  const texto = el('div');
  const pedacos = [];
  if (resumo.exp) pedacos.push(`+${percent(resumo.exp)} de experiência`);
  if (resumo.loot) pedacos.push(`+${percent(resumo.loot)} de loot`);
  if (resumo.dano) pedacos.push(`+${percent(resumo.dano)} de dano`);

  texto.append(
    el('b', null, pedacos.length ? `Skins: ${pedacos.join(', ')}` : 'Skins: nenhuma ainda'),
  );

  const daColecao =
    `Você tem ${resumo.tenho} de ${resumo.totalDeSkins}, e cada uma vale ` +
    `+${percent(resumo.porSkin.exp)} de experiência e +${percent(resumo.porSkin.loot)} de loot só por ter. `;
  const daVestida = resumo.daVestida
    ? `A vestida (${resumo.nomeDaVestida}) soma +${percent(resumo.daVestida.valor)} de ${resumo.daVestida.tipo === 'exp' ? 'experiência' : resumo.daVestida.tipo}.`
    : 'Vista uma para ganhar o bônus grande dela.';
  texto.append(el('em', null, daColecao + daVestida));

  faixa.append(texto);
  return faixa;
}

function cartaoDeRenome(entry) {
  const { state, send } = ctx;
  const store = state.store;
  const card = el('div', 'store-card');

  if (entry.look && outfitInfo(entry.look)) card.append(outfitCanvas(entry.look, { addons: 3, mount: 0 }, 72));
  card.append(el('b', null, entry.name), el('em', null, entry.blurb));
  card.append(el('em', 'card-crit', `Agora: ${entry.atual ?? entry.padrao ?? '—'}`));

  const campo = document.createElement('input');
  campo.type = 'text';
  campo.className = 'search';
  campo.maxLength = entry.maximo ?? 20;
  campo.placeholder = entry.padrao ?? 'nome do familiar';
  /*
   * O que foi digitado sobrevive ao redesenho.
   *
   * O servidor empurra o estado a cada ação da caçada e o modal se refaz
   * inteiro — foi o que já aconteceu com a quantidade do Summon Upgrade (ver
   * `cartaoDeQuantidade`). Sem isto, quem digitasse o nome enquanto caça o
   * veria sumir letra por letra.
   */
  campo.value = ctx.tabs.storeSummonNome ?? entry.atual ?? '';
  campo.oninput = () => {
    ctx.tabs.storeSummonNome = campo.value;
  };
  card.append(campo);

  const comprar = el('button');
  comprar.append(uiIcon('coin-store'), document.createTextNode(money(entry.coins)));
  comprar.onclick = () => {
    const nome = campo.value.replace(/\s+/g, ' ').trim();
    if (nome.length < (entry.minimo ?? 3)) {
      return void ctx.notice?.(`o nome precisa ter ao menos ${entry.minimo ?? 3} letras`);
    }
    confirmPurchase({
      title: `Chamar o seu familiar de "${nome}"`,
      cost: entry.coins,
      balance: store.coins ?? 0,
      onConfirm: () => send({ t: 'store', action: 'buy', id: entry.id, nome }),
    });
  };
  card.append(comprar);
  return card;
}

/*
 * O card de uma skin. Três estados, e não dois:
 *
 *   não é dele  → o preço, e a compra;
 *   é dele      → "usar", que veste de graça;
 *   está posta  → "em uso", desligado.
 *
 * O terceiro estado é o que falta nas montarias e nos outfits (lá "já
 * adquirido" cobre os dois), e aqui ele não podia faltar: nove skins compradas
 * e todas marcadas igual não diriam qual é a que o familiar está vestindo.
 */
function cartaoDeExtra(entry) {
  const { state, send } = ctx;
  const store = state.store;
  if (entry.kind === 'renomearSummon') return cartaoDeRenome(entry);

  const card = el('button', `mount-card${entry.owned ? ' owned' : ''}`);
  card.append(outfitCanvas(entry.look, { addons: 3, mount: 0 }, 72), el('b', null, entry.name));

  /*
   * O prêmio da skin, em cima do preço.
   *
   * É a única coisa que separa uma skin da outra além do desenho, e por isso ela
   * tem de estar no CARD e não só no balão: quem procura dano não pode ter de
   * passar o mouse por nove figuras para achar as três.
   */
  if (entry.premio) {
    card.append(
      el('em', 'card-crit', `vestida: +${percent(entry.premio.valor)} de ${entry.premio.nome}`),
    );
  }
  if (entry.blurb) tipTexto(card, entry.blurb);

  if (entry.emUso) {
    card.append(el('span', 'price owned-tag', 'em uso'));
    card.disabled = true;
    return card;
  }

  if (entry.owned) {
    card.append(el('span', 'price owned-tag', 'usar'));
    card.onclick = () => send({ t: 'store', action: 'summonSkin', look: entry.look });
    return card;
  }

  const price = el('span', 'price');
  price.append(uiIcon('coin-store'), document.createTextNode(money(entry.coins)));
  card.append(price);
  card.onclick = () =>
    confirmPurchase({
      title: entry.name,
      cost: entry.coins,
      balance: store.coins ?? 0,
      preview: outfitCanvas(entry.look, { addons: 3, mount: 0 }, 64),
      onConfirm: () => send({ t: 'store', action: 'buy', id: entry.id }),
    });
  return card;
}
function renderUpgrades(body) {
  const { state } = ctx;
  const store = state.store;
  body.append(el('p', 'shop-note', 'Estas você compra mais de uma vez — cada compra soma na anterior.'));

  const grid = el('div', 'store-grid');
  for (const entry of store.upgrades ?? []) {
    // O card de quantidade tem trilho nenhum para desenhar: o que ele conta nao
    // e' "quantas das N compras voce ja fez", e sim quantas voce quer agora.
    grid.append(entry.kind === 'quantidade' ? cartaoDeQuantidade(entry) : cartaoDeMelhoria(entry));
  }
  body.append(grid);
}

/*
 * ---- Um card, varias quantidades ----
 *
 * O card mostra o preco da quantidade ESCOLHIDA, e o quanto ela economiza logo
 * abaixo. O desconto so' vale a pena existir se for visivel na hora de decidir
 * — escondido no total ele e' um numero que ninguem compara.
 */
function cartaoDeQuantidade(entry) {
  const { send } = ctx;
  const card = el('div', `store-card${entry.owned ? ' owned' : ''}`);
  const arte = storeArt(entry);
  if (arte) card.append(arte);
  card.append(el('b', null, entry.name));
  // O recado que o produto quer que ninguém deixe de ler. Ver o slot de party, em store.mjs.
  if (entry.destaque) card.append(el('div', 'store-destaque', entry.destaque));
  if (entry.destaqueContas) card.append(el('div', 'store-destaque store-destaque-alerta', entry.destaqueContas));
  card.append(el('em', null, entry.blurb));

  /*
   * ---- O trilho, quando o produto TEM um teto ----
   *
   * O Summon Upgrade e o Tier Up não têm: são itens que se juntam aos montes, e
   * "quantas das N compras você já fez" não é pergunta para eles.
   *
   * O slot de party tem — são três, e acabaram. Ele veio do card de melhoria
   * (que desenhava esta barra) para cá quando ganhou o desconto por lote, e sem
   * o trilho a mudança teria custado a informação que dizia o que o produto faz:
   * quantos você tem, quantos existem, e de quantas pessoas para quantas.
   */
  let estado = null;
  if (entry.max != null) {
    const trilho = el('div', 'upgrade-track');
    for (let index = 0; index < entry.max; index++) trilho.append(el('i', index < entry.bought ? 'on' : ''));
    card.append(trilho);
    estado = el('em', 'upgrade-state');
    card.append(estado);
  }

  /*
   * ---- E a linha de estado segue a QUANTIDADE escolhida ----
   *
   * Ela veio do card de melhoria dizendo "Agora 2 → 3 pessoas", que é o que UMA
   * compra faz. Com o pacote de três marcado isso passa a mentir: o botão cobra
   * por três e a linha promete um.
   *
   * O salto só é calculado quando uma compra vale uma unidade (`next - now === 1`),
   * que é o caso do slot de party. Num produto em que o degrau não for de um, a
   * linha continua sendo a do servidor — chutar a conta dele daqui seria inventar.
   */
  const pintarEstado = (escolhida) => {
    if (!estado) return;
    const unidade = entry.unidade ?? '';
    if (entry.owned) {
      estado.textContent = `No máximo: ${entry.now}${unidade} (${entry.bought}/${entry.max})`;
      return;
    }
    const passoDeUm = entry.next - entry.now === 1;
    const quantos = escolhida?.quantos ?? 1;
    const depois = passoDeUm ? entry.now + quantos : entry.next;
    const levando = passoDeUm ? entry.bought + quantos : entry.bought + 1;
    estado.textContent = `Agora ${entry.now}${unidade} → ${depois}${unidade} (${levando}/${entry.max})`;
  };

  const opcoes = entry.opcoes ?? [];
  /*
   * Sem opção nenhuma não há escada para desenhar — é o produto de teto que
   * acabou. Sair aqui é o que impede o `desenhar()` lá embaixo de ler o preço de
   * uma escolha que não existe.
   */
  if (!opcoes.length) {
    pintarEstado(null);
    const cheio = el('button');
    cheio.textContent = 'no máximo';
    cheio.disabled = true;
    card.append(cheio);
    return card;
  }
  /*
   * ---- A quantidade escolhida SOBREVIVE ao redesenho ----
   *
   * "quando eu estou cacando automatico, a cada acao que o personagem faz, se
   * eu estou selecionado 5x da store -20%, volta sozinho pra 1x."
   *
   * Era isso mesmo, e nao tinha nada a ver com a loja: o servidor empurra o
   * estado a cada acao da cacada, o modal aberto se redesenha inteiro, e a
   * escolha morava numa variavel local deste cartao — que nasce de novo a cada
   * redesenho, no primeiro pacote. Quem cacava enquanto decidia via o botao
   * pular de volta para o 1x sozinho, varias vezes por segundo.
   *
   * Agora ela mora no `ctx.tabs`, que e' onde o resto da tela guarda o que o
   * jogador escolheu e o redesenho nao pode apagar — a mesma gaveta da
   * prateleira aberta e do texto da busca. Uma chave por produto, para o
   * Summon Upgrade e o Tier Up nao mandarem um no outro.
   */
  const lembrado = (ctx.tabs.storeQuantidade ??= {});
  let escolhida = opcoes.find((o) => o.quantos === lembrado[entry.id]) ?? opcoes[0];

  const botoes = el('div', 'store-qtd');
  const preco = el('em', 'lote-desconto');
  const comprar = el('button');

  const desenhar = () => {
    for (const [i, botao] of [...botoes.children].entries()) {
      botao.className = `store-qtd-botao${opcoes[i] === escolhida ? ' escolhido' : ''}`;
    }
    /*
     * ---- O corte de preco, escrito por extenso ----
     *
     * O mesmo formato do lote de montarias: "de X por Y — N% de desconto". So'
     * o numero final nao diz que houve desconto, e um desconto que ninguem
     * percebe nao faz o que um desconto existe para fazer.
     *
     * A unidade nao leva desconto nenhum, entao a linha dela nao promete um:
     * escrever "-0%" seria pior do que nao escrever nada.
     */
    preco.textContent = escolhida.desconto
      ? `de ${escolhida.cheio} por ${escolhida.coins} — ${escolhida.desconto}% de desconto (${escolhida.cada} cada)`
      : `${escolhida.coins} coins`;
    comprar.textContent = '';
    comprar.append(uiIcon('coin-store'), document.createTextNode(money(escolhida.coins)));
    pintarEstado(escolhida);
  };

  for (const opcao of opcoes) {
    const botao = el('button', 'store-qtd-botao');
    botao.type = 'button';
    botao.append(el('b', null, `${opcao.quantos}x`));
    // O desconto no proprio botao: e' o que faz a escada ser lida de relance,
    // sem ter de clicar em cada um para descobrir.
    if (opcao.desconto) botao.append(el('span', 'store-qtd-off', `-${opcao.desconto}%`));
    botao.onclick = () => {
      escolhida = opcao;
      lembrado[entry.id] = opcao.quantos;
      desenhar();
    };
    botoes.append(botao);
  }
  card.append(botoes, preco);

  comprar.onclick = () =>
    /*
     * `title`/`cost`/`balance`, e nao `name`/`coins`.
     *
     * Este card chamava a caixa com os nomes errados, e como ela le' os campos
     * por desestruturacao nada quebrava: a confirmacao de uma compra de mil
     * coins saia com o titulo vazio e "Preco - 0 Draevor Coins". O clique
     * cobrava certo — quem confere e' o servidor —, mas a ultima tela antes de
     * gastar mostrava outro numero.
     */
    confirmPurchase({
      title: `${escolhida.quantos}x ${entry.name}`,
      cost: escolhida.coins,
      balance: ctx.state.store?.coins ?? 0,
      onConfirm: () => send({ t: 'store', action: 'buy', id: escolhida.id }),
    });
  card.append(comprar);
  desenhar();
  return card;
}

function cartaoDeMelhoria(entry) {
  const { state, send } = ctx;
  const store = state.store;
  const card = el('div', `store-card${entry.owned ? ' owned' : ''}`);
  const arte = storeArt(entry);
  if (arte) card.append(arte);
  card.append(el('b', null, entry.name), el('em', null, entry.blurb));

  // A barra conta quantas das compras já foram feitas.
  const trilho = el('div', 'upgrade-track');
  for (let index = 0; index < entry.max; index++) trilho.append(el('i', index < entry.bought ? 'on' : ''));
  card.append(trilho);
  /*
   * A unidade vem do servidor, e não daqui.
   *
   * Este card dizia "espaços" cravado no texto, porque a única melhoria que
   * existia era a da bolsa de loot. Agora são duas — segundos de auto-venda e
   * pessoas na party — e o card que anunciasse "20 espaços" para um tempo de
   * espera estaria mentindo com todas as letras certas.
   */
  const unidade = entry.unidade ?? '';
  card.append(
    el(
      'em',
      'upgrade-state',
      entry.owned
        ? `No máximo: ${entry.now}${unidade} (${entry.bought}/${entry.max})`
        : `Agora ${entry.now}${unidade} → ${entry.next}${unidade} (${entry.bought}/${entry.max})`
    )
  );

  const buy = el('button');
  if (entry.owned) {
    buy.textContent = 'no máximo';
    buy.disabled = true;
  } else {
    buy.append(uiIcon('coin-store'), document.createTextNode(money(entry.coins)));
    buy.onclick = () =>
      confirmPurchase({
        title: `${entry.name} (${entry.bought + 1}ª)`,
        cost: entry.coins,
        balance: store.coins,
        onConfirm: () => send({ t: 'store', action: 'buy', id: entry.id }),
      });
  }
  card.append(buy);
  return card;
}

/*
 * ---- Transferir Draevor Coins ----
 *
 * Os coins são da CONTA, não do personagem: quem recebe é a conta de quem for
 * nomeado, então tanto faz qual personagem dela você escreve. Mandar para a
 * própria conta é barrado — seria só um jeito de se enganar.
 *
 * A tela era três campos numa linha e um botão. O problema não era feiúra: era
 * que ela não respondia a única pergunta que se faz aqui antes de apertar —
 * "quanto me sobra?". Agora o saldo está em cima, a barra mostra o quanto do
 * saldo está sendo enviado, e o resumo diz com quanto se fica. A transferência
 * não tem volta; a tela tem de ser lida inteira antes do clique.
 */
function renderTransfer(body) {
  const { state, send } = ctx;
  const store = state.store;
  const minimo = state.catalog.transferMin ?? 10;
  const saldo = store.coins ?? 0;

  const cartao = el('div', 'transfer-card');

  cartao.append(
    el(
      'p',
      'transfer-lead',
      'Os coins caem na conta de quem receber na hora, esteja essa pessoa online ou não. Escreva o nome de qualquer personagem dela.'
    )
  );

  // ---- o saldo, em cima e grande ----
  const bolsa = el('div', 'transfer-saldo');
  const bolsaEsq = el('div', 'transfer-saldo-nome');
  bolsaEsq.append(uiIcon('coin-store'), el('span', null, 'Saldo disponível'));
  bolsa.append(bolsaEsq, el('b', null, money(saldo)));
  cartao.append(bolsa);

  // ---- quanto ----
  const campoQuanto = el('label', 'transfer-campo');
  campoQuanto.append(el('span', 'transfer-rotulo', 'Quantidade'));
  const quanto = document.createElement('input');
  quanto.type = 'number';
  quanto.className = 'transfer-input';
  quanto.min = String(minimo);
  quanto.max = String(saldo);
  quanto.step = '1';
  quanto.value = '';
  quanto.placeholder = `mínimo de ${money(minimo)}`;
  campoQuanto.append(quanto);
  cartao.append(campoQuanto);

  /*
   * A barra e a caixa são o MESMO número, e cada uma corrige a outra: arrastar
   * é rápido mas impreciso, digitar é preciso mas lento. Quem digita 999999 vê
   * a barra bater no fim do saldo em vez de descobrir no erro do servidor.
   */
  const barra = document.createElement('input');
  barra.type = 'range';
  barra.className = 'transfer-barra';
  barra.min = '0';
  barra.max = String(saldo);
  barra.step = '1';
  barra.value = '0';
  cartao.append(barra);

  const escala = el('div', 'transfer-escala');
  escala.append(el('span', null, '0'), el('span', null, money(saldo)));
  cartao.append(escala);

  // ---- para quem ----
  const campoNome = el('label', 'transfer-campo');
  campoNome.append(el('span', 'transfer-rotulo', 'Destinatário'));
  const nome = document.createElement('input');
  nome.className = 'transfer-input';
  nome.placeholder = 'nome do personagem';
  nome.maxLength = 24;
  campoNome.append(nome);
  cartao.append(campoNome);
  cartao.append(el('small', 'transfer-dica', 'Vale qualquer personagem da conta de quem vai receber.'));

  // ---- o resumo e o botão ----
  const resumo = el('div', 'transfer-resumo');
  const enviar = el('button', 'transfer-enviar', 'Transferir');

  const valorAgora = () => Math.max(0, Math.min(saldo, Math.floor(Number(quanto.value) || 0)));

  const atualizar = () => {
    const valor = valorAgora();
    barra.value = String(valor);
    resumo.innerHTML = '';
    resumo.append(
      linhaResumo('Você envia', `${money(valor)} coins`, 'envia'),
      linhaResumo('Fica com', `${money(saldo - valor)} coins`, 'fica')
    );
    const ok = valor >= minimo && valor <= saldo && !!nome.value.trim();
    enviar.disabled = !ok;
    enviar.textContent = valor ? `Transferir ${money(valor)} coins` : 'Transferir';
  };

  quanto.oninput = atualizar;
  nome.oninput = atualizar;
  barra.oninput = () => {
    quanto.value = barra.value === '0' ? '' : barra.value;
    atualizar();
  };

  cartao.append(resumo);

  enviar.onclick = () => {
    const destino = nome.value.trim();
    const valor = valorAgora();
    if (!destino || valor < minimo) return;
    confirmPurchase({
      title: `${money(valor)} coins para ${destino}`,
      cost: valor,
      balance: saldo,
      onConfirm: () => {
        send({ t: 'transfer', name: destino, amount: valor });
        nome.value = '';
        quanto.value = '';
        atualizar();
      },
    });
  };
  cartao.append(enviar);

  cartao.append(
    el('p', 'transfer-aviso', 'Transferência não tem volta: confira o nome antes de confirmar.')
  );

  atualizar();
  body.append(cartao);
}

/** Uma linha do resumo da transferência: rótulo à esquerda, número à direita. */
function linhaResumo(rotulo, valor, classe) {
  const linha = el('div', classe);
  linha.append(el('span', null, rotulo), el('b', null, valor));
  return linha;
}

/** "R$ 15,00" a partir dos centavos que o servidor calculou. */
const reais = (centavos) =>
  (Number(centavos ?? 0) / 100).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

/*
 * ---- A tela de comprar coins ----
 *
 * Ela abre POR CIMA da loja, e não no lugar dela: todos os modais do jogo moram
 * no mesmo `#modal-body`, então trocar de tela aqui fecharia a loja e o jogador
 * voltaria para o mapa depois de pagar. É a mesma sobreposição da confirmação
 * de compra (`confirm-back`), que já existia por este motivo.
 *
 * São dois passos, e a ordem importa:
 *
 *   1. o pacote — quantas coins, quanto de bônus, quanto custa;
 *   2. a forma de pagamento — porque o cartão custa mais caro, e o preço tem de
 *      estar na tela ANTES do clique que gera a cobrança.
 *
 * Só no fim o servidor é chamado. Antes disso nada foi criado: fechar a janela
 * no meio não deixa pedido pendente nenhum.
 */
/*
 * ---- As moedas desenhadas (troca de Tibia Coins / Rubini Coins) ----
 *
 * O dono: "aonde estiver falando tibia coin coloque a Tibia_Coin.gif, e rubini
 * coin a rubinicoin.png", e a Draevor Coin com a moeda da loja. `comMoedas` corta
 * o texto nos nomes das três e põe o desenho na frente de cada um.
 */
const ICONE_DA_MOEDA = {
  'Tibia Coins': '/client/assets/ui/tibia-coin.gif',
  'Rubini Coins': '/client/assets/ui/rubini-coin.png',
  'Draevor Coins': '/client/assets/ui/coin-store.png',
};
function iconeDaMoeda(nome) {
  const img = document.createElement('img');
  // A classe por moeda deixa o CSS usar só tamanhos exatos (32→16/24, 12→12/24): fora deles o desenho borra.
  img.className = `troca-tc-moeda moeda-${nome.split(' ')[0].toLowerCase()}`;
  img.src = ICONE_DA_MOEDA[nome];
  img.alt = '';
  return img;
}
function comMoedas(tag, classe, texto) {
  const caixa = el(tag, classe);
  preencherComMoedas(caixa, texto);
  return caixa;
}
function preencherComMoedas(caixa, texto) {
  caixa.replaceChildren();
  for (const parte of String(texto).split(/(Tibia Coins|Rubini Coins|Draevor Coins)/)) {
    if (!parte) continue;
    if (ICONE_DA_MOEDA[parte]) {
      const junto = el('span', 'troca-tc-com-moeda');
      junto.append(iconeDaMoeda(parte), document.createTextNode(parte));
      caixa.append(junto);
    } else caixa.append(document.createTextNode(parte));
  }
}
/** As moedas de fora ⇄ a Draevor Coin, com a setinha de ida e volta do Transferir. */
function moedasTrocando(de) {
  const caixa = el('span', 'troca-tc-trocando');
  for (const nome of de) caixa.append(iconeDaMoeda(nome));
  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  svg.setAttribute('viewBox', '0 0 24 24');
  svg.setAttribute('class', 'troca-tc-setas');
  svg.innerHTML =
    '<path d="M4 8h14M14 4l4 4-4 4" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/>' +
    '<path d="M20 16H6M10 12l-4 4 4 4" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/>';
  caixa.append(svg, iconeDaMoeda('Draevor Coins'));
  return caixa;
}

export function abrirObterCoins() {
  const { state, send } = ctx;
  const store = state.store;
  if (!store) return;

  const { corpo, fechar } = janelaDoSaldo('Obter Draevor Coins');

  const total = (pack) => pack.coins + (pack.bonus ?? 0);
  /* O multiplicador DESTE pacote: a excecao dele, ou o geral. */
  const fatorDe = (pack) => {
    if (!store.promocao?.ativa) return 1;
    const proprio = store.promocao.porPacote?.[pack.id];
    return proprio > 0 ? proprio : (store.promocao.multiplicador ?? 1);
  };
  const totalPromo = (pack) => Math.round(total(pack) * fatorDe(pack));
  const emPromocao = () => !!store.promocao?.ativa;

  /** Passo 1: escolher o pacote. */
  const passoPacotes = () => {
    corpo.innerHTML = '';
    corpo.classList.remove('troca-tc-corpo');
    corpo.append(
      el(
        'p',
        'coins-lead',
        store.donate
          ? 'Pague com Pix ou cartão. O crédito é automático assim que o pagamento for confirmado — normalmente em segundos.'
          : 'A recarga ainda não está ligada neste servidor.'
      )
    );

    /*
     * ---- O aviso da promocao ----
     *
     * O desconto ja aparece em cada cartao, mas cartao a cartao a pessoa le
     * "2x" oito vezes sem entender que e' UM evento com hora para acabar. O
     * relogio e' o que muda a decisao: "termina em 8 dias" adia a compra,
     * "termina em 3 horas" nao.
     */
    if (store.aviso?.ativo) {
      const aviso = el('div', 'loja-aviso');
      aviso.append(el('b', null, store.aviso.titulo ?? ''));
      aviso.append(el('span', null, store.aviso.texto ?? ''));
      corpo.append(aviso);
    }

    if (emPromocao()) {
      const faixa = el('div', 'promo-faixa');
      faixa.append(el('b', null, 'PROMOÇÃO DE DRAEVOR COINS'));
      faixa.append(el('span', null, 'coins multiplicadas por tempo limitado'));

      const ate = store.promocao?.ate ?? 0;
      if (ate) {
        const relogio = el('em', 'promo-relogio');
        faixa.append(relogio);

        const tique = () => {
          const falta = ate - Date.now();
          if (falta <= 0) {
            relogio.textContent = 'a promoção acabou — recarregue a loja';
            clearInterval(giro);
            return;
          }
          const dias = Math.floor(falta / 86400000);
          const horas = Math.floor((falta % 86400000) / 3600000);
          const minutos = Math.floor((falta % 3600000) / 60000);
          const segundos = Math.floor((falta % 60000) / 1000);
          relogio.textContent = dias
            ? `termina em ${dias}d ${horas}h ${minutos}min`
            : `termina em ${horas}h ${minutos}min ${segundos}s`;
        };
        // Abaixo de um dia o segundo aparece, e e' quando ele passa a importar.
        const giro = setInterval(tique, 1000);
        tique();
      }

      corpo.append(faixa);
    }

    const grade = el('div', 'coins-grid');
    for (const pack of store.packs ?? []) {
      const card = el('div', 'coins-card');

      const topo = el('div', 'coins-card-topo');
      topo.append(uiIcon('coin-store'), el('b', null, money(pack.coins)));
      card.append(topo, el('span', 'coins-card-rotulo', 'coins do pacote'));

      if (emPromocao() && fatorDe(pack) > 1) {
        card.classList.add('coins-card-destaque');
        card.append(el('span', 'coins-selo', `${fatorDe(pack)}x COINS`));
        card.append(el('span', 'coins-riscado', `${money(total(pack))} coins`));
        card.append(el('span', 'coins-promo', `Você recebe ${money(totalPromo(pack))} coins`));
      } else if (pack.bonus) {
        card.append(el('span', 'coins-bonus', `+ ${money(pack.bonus)} de bônus`));
        card.append(el('span', 'coins-recebe', `Você recebe ${money(total(pack))} coins`));
      }

      card.append(el('span', 'coins-preco', reais(pack.centavosPix ?? pack.reais * 100)));

      const comprar = el('button', 'coins-comprar', 'Comprar');
      comprar.disabled = !store.donate && !store.stripe;
      comprar.onclick = () => passoPagamento(pack);
      card.append(comprar);
      grade.append(card);
    }
    corpo.append(grade);

    // A troca manual de Tibia Coins / Rubini Coins, abaixo dos pacotes. Ver `passoTroca`.
    if (store.trocaTc) {
      const troca = el('button', 'troca-tc-entrada');
      const texto = el('span', 'troca-tc-entrada-texto');
      texto.append(
        // Aqui só o desenho da esquerda leva moedas: no texto elas enchiam o cartão (pedido do dono).
        el('b', null, 'Trocar Tibia Coins ou Rubini Coins por Draevor Coins'),
        el('em', null, 'Tibia Global: 250 TC = 500 Draevor Coins · Rubinot: 250 RC = 200 Draevor Coins')
      );
      troca.append(moedasTrocando(['Tibia Coins', 'Rubini Coins']), texto, el('span', 'troca-tc-entrada-seta', '›'));
      troca.onclick = passoTroca;
      corpo.append(troca);
    }
  };

  /*
   * ---- A troca manual de Tibia Coins (Global) e Rubini Coins (Rubinot) ----
   *
   * Pedido do dono (15/09). Ninguém paga nada aqui: a pessoa manda as coins para
   * o char do dono no outro servidor, preenche e confirma. O servidor só grava o
   * pedido (`trocaTc`), e a última tela abre o WhatsApp DELA com a mensagem
   * pronta — é lá que vai o print do histórico da store. Quem credita é o dono,
   * pelo painel. Ver troca-tc.mjs.
   */
  const passoTroca = () => {
    const regra = store.trocaTc;
    corpo.innerHTML = '';
    // Mais apertada que as outras telas da janela: tem de caber sem rolar.
    corpo.classList.add('troca-tc-corpo');
    // O título do passo colado no bloco dele (o vão grande fica só ENTRE os passos).
    const grupoDoPasso = (rotulo, bloco) => {
      const grupo = el('div', 'troca-tc-grupo');
      grupo.append(el('span', 'troca-tc-passo', rotulo), bloco);
      return grupo;
    };
    const servidores = regra.servidores ?? [];
    let servidor = servidores[0];
    let quantidade = regra.minimo;

    corpo.append(
      comMoedas(
        'p',
        'coins-lead',
        'Troque coins de outro servidor por Draevor Coins. A entrega é feita à mão pelo dono, depois de conferir o envio.'
      )
    );

    // 1. Qual servidor
    const escolhas = el('div', 'troca-tc-servidores');
    corpo.append(grupoDoPasso('1. De qual servidor são as coins?', escolhas));

    // 2. Quanto
    const quanto = el('div', 'troca-tc-quanto');
    const envia = el('b', 'troca-tc-envia');
    const recebe = el('b', 'troca-tc-recebe');
    const barra = document.createElement('input');
    barra.type = 'range';
    barra.min = String(regra.minimo);
    barra.max = String(regra.maximo);
    barra.step = String(regra.passo);
    barra.value = String(quantidade);
    barra.className = 'troca-tc-barra';
    const linhaBarra = el('div', 'troca-tc-linha-barra');
    linhaBarra.append(barra);
    const resumo = el('div', 'troca-tc-resumo');
    const ladoEnvia = el('div', 'troca-tc-lado');
    ladoEnvia.append(el('span', null, 'Você envia'), envia);
    const ladoRecebe = el('div', 'troca-tc-lado troca-tc-lado-recebe');
    ladoRecebe.append(el('span', null, 'Você recebe no Draevor Idle'), recebe);
    // No meio, a mesma setinha verde de ida e volta do Transferir.
    const meio = el('span', 'troca-tc-igual');
    const setas = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
    setas.setAttribute('viewBox', '0 0 24 24');
    setas.setAttribute('class', 'troca-tc-setas');
    setas.innerHTML =
      '<path d="M4 8h14M14 4l4 4-4 4" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/>' +
      '<path d="M20 16H6M10 12l-4 4 4 4" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/>';
    meio.append(setas);
    resumo.append(ladoEnvia, meio, ladoRecebe);
    quanto.append(resumo, linhaBarra);
    corpo.append(grupoDoPasso('2. Quantas coins você vai enviar?', quanto));

    // 3. Para quem mandar (o aviso que não pode passar batido)
    const aviso = el('div', 'troca-tc-aviso');
    corpo.append(grupoDoPasso('3. Envie as coins para este char', aviso));

    // 4. Os nomes
    const campo = (rotulo, valor, dica) => {
      const caixa = el('label', 'troca-tc-campo');
      const input = document.createElement('input');
      input.type = 'text';
      input.maxLength = 30;
      input.value = valor;
      input.placeholder = dica;
      caixa.append(comMoedas('span', null, rotulo), input);
      return { caixa, input };
    };
    const origem = campo('', '', 'ex.: Nome Do Seu Char');
    const destino = campo('Nome do char que RECEBE os Draevor Coins aqui', state.character?.name ?? '', 'nome do char no Draevor Idle');
    const nomes = el('div', 'troca-tc-nomes');
    nomes.append(origem.caixa, destino.caixa);
    corpo.append(grupoDoPasso('4. Os nomes dos chars', nomes));

    // Os avisos finais e a confirmação
    const avisos = el('ul', 'troca-tc-avisos');
    const confirmo = document.createElement('input');
    confirmo.type = 'checkbox';
    const linhaConfirmo = el('label', 'troca-tc-confirmo');
    const textoConfirmo = el('span');
    linhaConfirmo.append(confirmo, textoConfirmo);
    const erro = el('p', 'troca-tc-erro');
    erro.hidden = true;
    const confirmar = el('button', 'coins-comprar troca-tc-confirmar', 'Confirmar troca');
    // Só acende com a caixinha marcada (pedido do dono).
    confirmar.disabled = true;
    confirmo.onchange = () => {
      confirmar.disabled = !confirmo.checked;
      if (confirmo.checked) erro.hidden = true;
    };
    const voltar = el('button', 'ghost coins-voltar', 'Voltar');
    voltar.onclick = passoPacotes;
    const botoes = el('div', 'troca-tc-botoes');
    botoes.append(voltar, confirmar);
    const final = el('div', 'troca-tc-final');
    final.append(linhaConfirmo, botoes);
    corpo.append(avisos, final, erro);

    /*
     * O nome do char do dono com um botão de copiar ao lado: digitar
     * "Galadriheal" à mão é onde a pessoa erra e manda as coins para outro.
     * `navigator.clipboard` só existe em conexão segura; sem ela, cai no
     * `execCommand` de uma caixa escondida.
     */
    const charComCopiar = (nome) => {
      const linha = el('div', 'troca-tc-char-linha');
      const botao = el('button', 'troca-tc-copiar', 'Copiar');
      botao.type = 'button';
      botao.onclick = async () => {
        let foi = false;
        try {
          await navigator.clipboard.writeText(nome);
          foi = true;
        } catch {
          const caixa = document.createElement('textarea');
          caixa.value = nome;
          caixa.style.cssText = 'position:fixed;opacity:0;';
          document.body.append(caixa);
          caixa.select();
          try { foi = document.execCommand('copy'); } catch { foi = false; }
          caixa.remove();
        }
        botao.textContent = foi ? 'Copiado!' : 'Não deu';
        botao.classList.toggle('copiado', foi);
        setTimeout(() => {
          botao.textContent = 'Copiar';
          botao.classList.remove('copiado');
        }, 1600);
      };
      linha.append(el('b', 'troca-tc-char-do-dono', nome), botao);
      return linha;
    };
    /** O alerta que não pode passar batido: triângulo de atenção, fundo vermelho e letra forte. */
    const atencao = (forte, resto) => {
      const caixa = el('div', 'troca-tc-atencao');
      const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
      svg.setAttribute('viewBox', '0 0 24 24');
      svg.innerHTML =
        '<path d="M12 2.8 1.6 21h20.8z" fill="#ffcf4a" stroke="#7a3b00" stroke-width="1.4" stroke-linejoin="round"/>' +
        '<path d="M12 9v5.5" stroke="#3a1a00" stroke-width="2.4" stroke-linecap="round"/><circle cx="12" cy="17.8" r="1.4" fill="#3a1a00"/>';
      const texto = el('div', 'troca-tc-atencao-texto');
      texto.append(el('b', null, forte), el('span', null, resto));
      caixa.append(svg, texto);
      return caixa;
    };
    const n = (v) => Number(v).toLocaleString('pt-BR');
    const coinsDe = (qtd) => Math.floor((qtd * servidor.recebe) / servidor.manda);
    const redesenhar = () => {
      escolhas.innerHTML = '';
      for (const s of servidores) {
        const b = el('button', `troca-tc-servidor${s.id === servidor.id ? ' escolhido' : ''}`);
        const nomeDoServidor = el('b', 'troca-tc-servidor-nome');
        nomeDoServidor.append(moedasTrocando([s.moeda]), document.createTextNode(s.nome));
        b.append(nomeDoServidor, comMoedas('em', null, `${n(s.manda)} ${s.moeda} = ${n(s.recebe)} Draevor Coins`));
        b.onclick = () => {
          if (servidor.id !== s.id) desmarcar();
          servidor = s;
          redesenhar();
        };
        escolhas.append(b);
      }
      preencherComMoedas(envia, `${n(quantidade)} ${servidor.moeda}`);
      preencherComMoedas(recebe, `${n(coinsDe(quantidade))} Draevor Coins`);
      // Fração de 0 a 1: o CSS acha o centro da bolinha com ela (ver `.troca-tc-barra`).
      barra.style.setProperty('--p', String((quantidade - regra.minimo) / (regra.maximo - regra.minimo)));

      aviso.innerHTML = '';
      aviso.append(
        comMoedas('span', null, `No ${servidor.nome}, envie as ${servidor.moeda} para o char:`),
        charComCopiar(servidor.char),
        atencao('Confira o nome com atenção antes de enviar.', 'Coins enviadas para outro char não têm como ser recuperadas.')
      );
      preencherComMoedas(origem.caixa.firstChild, `Nome do char que ENVIOU as ${servidor.moeda} no ${servidor.nome}`);

      avisos.innerHTML = '';
      for (const texto of [
        `A entrega dos Draevor Coins pode demorar até ${regra.prazo}.`,
        `Depois de confirmar, envie no WhatsApp ${regra.whatsapp} o print do histórico da store do ${servidor.nome} mostrando o envio para ${servidor.char}. Com o print enviado, a entrega dos coins fica mais rápida.`,
      ]) avisos.append(comMoedas('li', null, texto));
      preencherComMoedas(textoConfirmo, `Confirmo que enviei os ${n(quantidade)} ${servidor.moeda} para o char ${servidor.char} no ${servidor.nome}.`);
    };
    // Mudou o valor ou o servidor: a confirmação era de OUTRA troca, e desmarca.
    const desmarcar = () => {
      confirmo.checked = false;
      confirmar.disabled = true;
    };
    const mudar = (v) => {
      const antes = quantidade;
      quantidade = Math.min(regra.maximo, Math.max(regra.minimo, Math.round(v / regra.passo) * regra.passo));
      if (quantidade !== antes) desmarcar();
      barra.value = String(quantidade);
      redesenhar();
    };
    barra.oninput = () => mudar(Number(barra.value));

    confirmar.onclick = () => {
      erro.hidden = true;
      const falha = (texto) => {
        erro.textContent = texto;
        erro.hidden = false;
      };
      if (!origem.input.value.trim()) return falha(`Escreva o nome do char que enviou as ${servidor.moeda}.`);
      if (!destino.input.value.trim()) return falha('Escreva o nome do char que recebe os Draevor Coins.');
      if (!confirmo.checked) return falha(`Marque que você já enviou as ${servidor.moeda} para ${servidor.char}.`);
      confirmar.disabled = true;
      confirmar.textContent = 'Enviando…';
      ctx.aoTrocaTc = (resposta) => {
        ctx.aoTrocaTc = null;
        if (!corpo.isConnected) return;
        confirmar.disabled = !confirmo.checked;
        confirmar.textContent = 'Confirmar troca';
        if (!resposta.ok) return falha(resposta.reason ?? 'não deu para registrar a troca');
        passoTrocaFeita(resposta, regra);
      };
      send({
        t: 'store',
        action: 'trocaTc',
        servidor: servidor.id,
        quantidade,
        charOrigem: origem.input.value,
        charDestino: destino.input.value,
      });
    };

    redesenhar();
  };

  /** A última tela: o número do pedido e o botão que abre o WhatsApp. */
  const passoTrocaFeita = ({ troca, whatsapp }, regra) => {
    corpo.innerHTML = '';
    const n = (v) => Number(v).toLocaleString('pt-BR');
    const topo = el('div', 'troca-tc-feita');
    topo.append(
      el('b', null, `Pedido #${troca.id} registrado`),
      comMoedas('span', null, `${n(troca.quantidade)} ${troca.moeda} (${troca.servidorNome}) → ${n(troca.coins)} Draevor Coins para ${troca.charDestino}`)
    );
    corpo.append(topo);

    const falta = el('div', 'troca-tc-aviso');
    falta.append(
      el('span', null, 'Falta só um passo: mande o pedido e o print no WhatsApp'),
      el('b', 'troca-tc-char-do-dono', regra.whatsapp),
      el(
        'em',
        null,
        `Clique no botão abaixo: o WhatsApp abre com a mensagem pronta. Anexe o print do histórico da store do ${troca.servidorNome} mostrando o envio para ${troca.charDoDono} e envie. A entrega pode demorar até ${regra.prazo}.`
      )
    );
    corpo.append(falta);

    const zap = document.createElement('a');
    zap.className = 'troca-tc-whatsapp';
    zap.href = whatsapp;
    zap.target = '_blank';
    zap.rel = 'noopener';
    zap.textContent = 'Enviar no WhatsApp';
    const fecharBotao = el('button', 'ghost coins-voltar', 'Fechar');
    fecharBotao.onclick = fechar;
    const botoes = el('div', 'troca-tc-botoes');
    botoes.append(fecharBotao, zap);
    corpo.append(botoes);
  };

  /** Passo 2: Pix, cartão ou Stripe (internacional). */
  const passoPagamento = (pack) => {
    corpo.innerHTML = '';
    corpo.append(
      el('p', 'coins-lead', `${money(totalPromo(pack))} Draevor Coins — escolha a forma de pagamento.`)
    );

    const escolha = (rotulo, detalhe, centavos, metodo, classe) => {
      const botao = el('button', `coins-metodo ${classe}`);
      const esquerda = el('span', 'coins-metodo-nome');
      esquerda.append(el('b', null, rotulo), el('em', null, detalhe));
      botao.append(esquerda, el('b', 'coins-metodo-valor', reais(centavos)));
      botao.onclick = () => {
        // O servidor cria o pedido e responde `{ t: 'donate' }`; quem desenha o
        // QR é o `main.mjs`. Esta janela sai da frente para não ficar por baixo.
        send({ t: 'store', action: 'redeem', id: pack.id, metodo });
        fechar();
      };
      return botao;
    };

    const acrescimo = Math.round((store.cardFee ?? 0) * 100);
    if (store.donate) {
      corpo.append(
        escolha('Pix', 'cai na hora', pack.centavosPix ?? pack.reais * 100, 'pix', 'pix'),
        escolha(
          'Cartão de crédito',
          acrescimo ? `parcelado — acréscimo de ${acrescimo}%` : 'parcelado',
          pack.centavosCartao ?? pack.reais * 100,
          'cartao',
          'cartao'
        )
      );
    }
    /*
     * Para quem joga de fora do Brasil e não tem Pix nem cartão brasileiro.
     * O valor é cobrado em reais; o banco do jogador converte na fatura.
     */
    if (store.stripe) {
      corpo.append(
        escolha(
          'Stripe - Internacional',
          'international card · Apple Pay · Google Pay',
          pack.centavosStripe ?? pack.centavosCartao ?? pack.reais * 100,
          'stripe',
          'stripe'
        )
      );
    }

    const voltar = el('button', 'ghost coins-voltar', 'Voltar');
    voltar.onclick = passoPacotes;
    corpo.append(voltar);
  };

  passoPacotes();
}

/*
 * ---- O mercado numa tela só ----
 *
 * Eram DOIS modais: uma lista de itens e, ao clicar em "Ver", outro modal com
 * as ofertas daquele item. Comparar dois itens custava quatro cliques e voltar
 * ao começo da lista a cada um.
 *
 * Agora é uma casa de leilões de verdade, no formato que se espera dela: a
 * lista de itens à esquerda, sempre visível, e o item escolhido à direita com
 * as duas pontas do balcão lado a lado — quem está COMPRANDO e quem está
 * VENDENDO. Trocar de item é um clique, e o lado direito troca sozinho.
 *
 * As duas colunas da direita não são decoração: elas são as duas perguntas que
 * se faz aqui. "Quanto me pagam por isto?" olha a coluna de ordens de compra e
 * aperta Vender. "Por quanto consigo isto?" olha as ofertas de venda e aperta
 * Comprar. Empilhadas, como estavam, obrigavam a rolar de uma para a outra.
 */
/** Quantos desse item o personagem tem à mão (mochila e bolsa). */
function tenhoDesse(id) {
  const { state } = ctx;
  const somar = (lista) => (lista ?? []).filter((e) => e.id === id).reduce((t, e) => t + e.count, 0);
  return somar(state.character.inventory) + somar(state.character.pouch);
}

/*
 * ---- O campo de número do jogo ----
 *
 * O `<input type="number">` do navegador tem dois defeitos que aparecem justo
 * onde mais importa, que é escrevendo dinheiro:
 *
 *   1. as setinhas dele são desenho do NAVEGADOR. Fundo branco, seta cinza,
 *      tamanho fixo — no meio de um painel escuro elas são a única coisa que
 *      não pertence ao jogo, e não há CSS que as pinte de forma confiável;
 *   2. ele não aceita separador de milhar. "190005" é um borrão; "190.005" se
 *      lê de relance. E é assim que todo o resto da interface escreve número
 *      (ver `money`).
 *
 * Então o campo é de TEXTO, a formatação é nossa, e as setinhas são dois
 * botões do nosso estilo. O valor que sai é sempre inteiro.
 */
function campoDeNumero({ rotulo = null, valor = 1, min = 1, max = null, comMax = false, aoMudar = null } = {}) {
  const caixa = el('div', 'num-campo');
  if (rotulo) caixa.append(el('span', 'num-rotulo', rotulo));

  const linha = el('div', 'num-linha');

  const entrada = document.createElement('input');
  entrada.type = 'text';
  // `numeric` faz o teclado do celular abrir nos números sem virar `type=number`.
  entrada.inputMode = 'numeric';
  entrada.className = 'num-entrada';

  const limitar = (n) => {
    n = Math.floor(Number(n) || 0);
    if (min != null) n = Math.max(min, n);
    if (max != null) n = Math.min(max, n);
    return n;
  };

  let atual = limitar(valor);
  const escrever = () => {
    entrada.value = money(atual);
    aoMudar?.(atual);
  };

  /*
   * Digitar reformata a cada tecla, e o cursor volta para o fim.
   *
   * Manter a posição exata do cursor com os pontos entrando e saindo daria um
   * trabalho que ninguém percebe: este campo é curto e sempre se digita no fim
   * dele. O que NÃO pode acontecer é o valor pular ou o ponto sumir, e isso a
   * releitura garante.
   */
  entrada.oninput = () => {
    const so = entrada.value.replace(/\D/g, '');
    atual = limitar(so === '' ? min ?? 0 : Number(so));
    // Campo vazio continua vazio enquanto se digita: apagar tudo para escrever
    // outro número não pode reaparecer como "1" embaixo do dedo.
    if (so === '') {
      entrada.value = '';
      aoMudar?.(atual);
      return;
    }
    escrever();
    entrada.setSelectionRange(entrada.value.length, entrada.value.length);
  };
  // Saiu do campo com ele vazio: volta ao mínimo, para nunca sobrar um vazio.
  entrada.onblur = () => escrever();

  const passo = (delta) => {
    atual = limitar(atual + delta);
    escrever();
    entrada.focus();
  };

  const menos = el('button', 'num-passo', '−');
  menos.type = 'button';
  menos.onclick = () => passo(-1);
  const mais = el('button', 'num-passo', '+');
  mais.type = 'button';
  mais.onclick = () => passo(1);

  // Roda do mouse e setas do teclado andam também, como no campo nativo.
  entrada.onkeydown = (evento) => {
    if (evento.key === 'ArrowUp') {
      evento.preventDefault();
      passo(1);
    } else if (evento.key === 'ArrowDown') {
      evento.preventDefault();
      passo(-1);
    }
  };

  linha.append(menos, entrada, mais);

  if (comMax && max != null) {
    const tudo = el('button', 'num-max', 'Máx');
    tudo.type = 'button';
    tudo.onclick = () => {
      atual = limitar(max);
      escrever();
    };
    linha.append(tudo);
  }

  caixa.append(linha);
  escrever();

  return { wrap: caixa, ler: () => limitar(atual), por: (v) => { atual = limitar(v); escrever(); } };
}

/*
 * ---- A caixa de fechar negócio ----
 *
 * Vale para comprar item, comprar coin e vender coin: as três são a mesma
 * pergunta — "quantos, e por quanto no total?" —, e a diferença entre elas é
 * só o rótulo e a moeda.
 *
 * A quantidade existe porque o anúncio pode ser de um LOTE: comprar 10 de uma
 * pilha de 98 é o caso comum, e sem escolha a única opção seria levar as 98.
 * O total se refaz a cada passo, e o botão desliga quando não dá — é o último
 * instante em que dá para desistir, e é onde a pessoa está olhando.
 */
function confirmarNegocio({
  titulo,
  itemId = null,
  arteDaMoeda = null,
  nome,
  disponivel,
  unitario,
  /*
   * O que impede o negócio muda com o lado, e por isso quem sabe é quem chama.
   *
   * Comprando, a trava é o OURO e ela se mede no total. Vendendo coin, a trava
   * são as COINS e ela se mede na quantidade. Um "saldo" único aqui dentro
   * dava certo por acaso na conta e errado na frase: dizia "faltam 190.000
   * gold" para quem só não tinha coin bastante.
   */
  cabe = null,
  unidade = 'gold',
  acao = 'Comprar',
  aoConfirmar,
}) {
  const back = el('div', 'confirm-back');
  const box = el('div', 'confirm-box negocio');

  box.append(el('h3', null, titulo));

  // O cartão do que está sendo negociado: figura, nome e quanto há.
  const cartao = el('div', 'negocio-alvo');
  if (itemId != null) cartao.append(itemCanvas(itemId, 40, disponivel));
  else if (arteDaMoeda) cartao.append(uiIcon(arteDaMoeda));
  const texto = el('div', 'negocio-alvo-texto');
  texto.append(el('b', null, nome));
  texto.append(el('em', null, `${money(disponivel)} disponíve${disponivel === 1 ? 'l' : 'is'} · ${money(unitario)} ${unidade} cada`));
  cartao.append(texto);
  box.append(cartao);

  const total = el('div', 'negocio-total');
  const rotuloTotal = el('span', null, 'Total');
  const valorTotal = el('b', null, '');
  total.append(rotuloTotal, valorTotal);

  const falta = el('p', 'confirm-short');

  /*
   * O botao nasce ANTES do campo, e nao depois.
   *
   * `campoDeNumero` chama o `aoMudar` uma vez ao montar, para o total ja sair
   * escrito. Se o botao fosse criado depois, esse primeiro aviso esbarraria
   * nele antes de existir.
   */
  const confirmar = el('button', null, acao);

  const campo = campoDeNumero({
    rotulo: 'Quantidade',
    valor: 1,
    min: 1,
    max: disponivel,
    comMax: true,
    aoMudar: (n) => {
      const soma = n * unitario;
      valorTotal.textContent = `${money(soma)} ${unidade}`;
      const recusa = cabe ? cabe(n, soma) : null;
      confirmar.disabled = !!recusa || n < 1;
      falta.textContent = recusa ?? '';
      falta.hidden = !recusa;
    },
  });
  box.append(campo.wrap);
  box.append(total);
  box.append(falta);

  const acoes = el('div', 'confirm-actions');
  const cancelar = el('button', 'ghost', 'Cancelar');
  cancelar.onclick = () => back.remove();
  confirmar.onclick = () => {
    back.remove();
    aoConfirmar(campo.ler());
  };
  acoes.append(cancelar, confirmar);
  box.append(acoes);

  back.append(box);
  fecharAoClicarFora(back, () => back.remove());
  atalhosDaCaixa(back, { confirmar: () => !confirmar.disabled && confirmar.click(), fechar: () => back.remove() });
  document.body.append(back);
  confirmar.focus();
}

/*
 * ---- O balcão, anúncio por anúncio ----
 *
 * A tela anterior era um LIVRO DE OFERTAS: escolhia-se o item na lista da
 * esquerda e a direita mostrava quem comprava e quem vendia, em duas colunas.
 * Respondia bem "quanto vale isto", e mal a pergunta que se faz mais: "o que dá
 * para comprar agora". Para chegar num item à venda era preciso adivinhar o
 * nome dele antes.
 *
 * Agora a lista é dos ANÚNCIOS. Cada linha é uma oferta de alguém, com preço e
 * botão de comprar, e as peneiras são as do equipamento — slot, vocação,
 * raridade —, que é como se procura arma no jogo. Quem faz a peneira e a
 * paginação é o servidor (`marketOffers`), porque a lista inteira pode ter
 * milhares de linhas e mandar tudo para filtrar aqui seria mandar o mercado
 * inteiro a cada tecla digitada.
 */

const ABAS_DO_BALCAO = {
  ofertas: 'Ofertas',
  coins: 'Draevor Coins',
  minhas: 'Minhas ofertas',
  historico: 'Histórico',
};

const SLOTS_DO_BALCAO = {
  all: 'Todo slot',
  weapon: 'Arma',
  shield: 'Escudo',
  head: 'Elmo',
  body: 'Armadura',
  legs: 'Pernas',
  feet: 'Botas',
  neck: 'Colar',
  ring: 'Anel',
  ammo: 'Munição',
  backpack: 'Mochila',
};

const VOCACOES_DO_BALCAO = {
  all: 'Toda vocação',
  knight: 'Knight',
  paladin: 'Paladin',
  druid: 'Druid',
  sorcerer: 'Sorcerer',
  monk: 'Monk',
};

const RARIDADES_DO_BALCAO = {
  all: 'Toda raridade',
  comum: 'Comum',
  incomum: 'Incomum',
  raro: 'Raro',
  épico: 'Épico',
  lendário: 'Lendário',
  mítico: 'Mítico',
};

/*
 * As ordens do balcao, aos pares: cada coluna da tabela liga uma e o segundo
 * clique nela liga a irma invertida (ver `COLUNAS_DO_BALCAO`). O seletor mostra
 * todas porque ele e' quem diz, em palavras, o que a setinha da coluna esta
 * fazendo — e porque um `<select>` que nao tem o proprio valor na lista aparece
 * em branco.
 */
const ORDENS_DO_BALCAO = {
  barato: 'Mais barato',
  caro: 'Mais caro',
  nome: 'Nome A → Z',
  nomeZ: 'Nome Z → A',
  level: 'Level menor',
  levelZ: 'Level maior',
  slot: 'Slot (do elmo às botas)',
  slotZ: 'Slot (invertido)',
  novo: 'Mais recente',
};

/*
 * ---- As colunas da tabela, e o clique que ordena ----
 *
 * "onde está escrito item, slot, preço: depois de item tem que estar escrito
 * LEVEL, e mostrar o level de cada item. E ao clicar em cima de item ele vai
 * alternando em ordem de nome; em slot, ordem de slot; preço, a de preço; e
 * level, a do level."
 *
 * Cada coluna carrega o par de ordens dela e a palavra que descreve cada
 * sentido. O primeiro clique liga a primeira; o clique seguinte, na MESMA
 * coluna, inverte.
 *
 * A ordem em si é feita no servidor (ver `ORDENS`, no store.mjs): a tabela
 * mostra oito anúncios por página, e ordenar aqui ordenaria só a página aberta
 * — "o mais barato" seria o mais barato desta página, o que é pior do que não
 * ordenar.
 */
const COLUNAS_DO_BALCAO = [
  ['Item', ['nome', 'nomeZ'], ['A → Z', 'Z → A']],
  ['Level', ['level', 'levelZ'], ['do menor', 'do maior']],
  ['Slot', ['slot', 'slotZ'], ['do elmo às botas', 'ao contrário']],
  [null, ['barato', 'caro'], ['do mais barato', 'do mais caro']],
];

/*
 * Os dois lados do balcão moram na MESMA aba.
 *
 * "À venda" é o que dá para comprar; "Procurados" é quem está pagando por algo
 * — e é essa metade que diz a quem tem o item que vale a pena vender. Eram duas
 * telas no desenho antigo; aqui é um botão, e o servidor já filtra por `kind`.
 */
const LADOS_DO_BALCAO = { sell: 'À venda', buy: 'Procurados' };

/*
 * ---- E em que MOEDA o anúncio está ----
 *
 * O dono: "tem que ter a opção de comprar ou vender itens por draevor coins
 * também, mas não sei se seria junto com as ofertas de item ou separado".
 *
 * Ficou junto — mesma aba, mesma busca, mesmas peneiras — com um seletor de
 * PRATELEIRA embaixo dos dois lados. Separar em outra aba duplicaria a peneira
 * inteira e partiria a busca em duas: quem procura uma spectral bolt teria de
 * procurar duas vezes para saber se alguém a está vendendo.
 *
 * E são duas prateleiras, e não uma lista com coluna de moeda: "500 gold" e
 * "3 coins" na mesma tabela não se comparam, e "mais barato" misturando as
 * duas seria uma ordem sem significado.
 */
const MOEDAS_DO_BALCAO = {
  gold: { nome: 'Ouro', figura: () => itemCanvas(3043, 16, 1), unidade: 'gold', curto: 'g' },
  coin: { nome: 'Draevor Coins', figura: () => uiIcon('coin-store'), unidade: 'Draevor Coins', curto: ' coins' },
};

/** A moeda que a vitrine está mostrando agora. */
const moedaDoBalcao = () => (ctx.tabs.marketMoeda === 'coin' ? 'coin' : 'gold');
/** Quanto o personagem tem da moeda de agora — o ouro é dele, a coin é da conta. */
const saldoDaMoeda = () =>
  moedaDoBalcao() === 'coin' ? ctx.state.character?.coins ?? 0 : ouroDoJogador(ctx.state);
/** O preço escrito com a figura da moeda ao lado, e não com uma letra colada. */
const precoComMoeda = (valor, qual = moedaDoBalcao()) => {
  const caixa = el('div', 'balcao-preco-linha');
  caixa.append(MOEDAS_DO_BALCAO[qual].figura());
  caixa.append(el('b', null, money(valor)));
  return caixa;
};

/*
 * A raridade saiu da coluna e foi para a COR DO NOME.
 *
 * É onde ela custa zero espaço e serve mais: o olho varre a lista pelos nomes,
 * e a cor diz o que vale a pena olhar antes de ler qualquer número. O acento sai
 * porque classe de CSS com acento é pedir problema — `épico` vira `rar-epico`.
 */
const CLASSE_DA_RARIDADE = (rarity) =>
  `rar-${String(rarity ?? 'comum')
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')}`;

/*
 * ---- Os filtros do balcão ficam guardados ----
 *
 * Report do Kemm: "salvar filtros no mercado, mt ruim toda vez q entra
 * resetar". Eles moravam só em `ctx.tabs`, que some ao trocar de personagem e
 * ao recarregar a página — quem procura munição de paladino tinha de remontar
 * a peneira toda vez.
 *
 * A BUSCA fica de fora de propósito. Slot e raridade são um jeito de olhar; um
 * nome digitado é uma pergunta de um momento só, e voltar semanas depois a uma
 * tela que diz "nenhum anúncio" por causa de uma palavra esquecida seria pior
 * do que não guardar nada.
 *
 * E o que volta é conferido contra as listas de agora: um valor que não existe
 * mais deixaria o seletor em branco, mostrando uma peneira que ninguém escolheu.
 */
/*
 * ---- A prateleira das ESSÊNCIAS ----
 *
 * "no market tem que ter um filtro pra mostrar só essências também."
 *
 * Três estados e não dois: além do "só elas", há o "nenhuma delas". A segunda
 * existe porque a essência não tem slot no catálogo — ela cai em toda vitrine
 * sem filtro de slot, e uma mochila de essências no meio de uma busca por armas
 * é exatamente o ruído de que ele reclamou.
 */
const ESSENCIAS_DO_BALCAO = {
  all: 'com essências',
  so: 'só essências',
  nao: 'sem essências',
};

const CHAVE_DOS_FILTROS = 'draevor:mercado:filtros';
const FILTROS_GUARDADOS = () => ({
  marketSlot: SLOTS_DO_BALCAO,
  marketVocacao: VOCACOES_DO_BALCAO,
  marketRaridade: RARIDADES_DO_BALCAO,
  marketOrdem: ORDENS_DO_BALCAO,
  marketLado: LADOS_DO_BALCAO,
  marketMoeda: MOEDAS_DO_BALCAO,
  marketEssencias: ESSENCIAS_DO_BALCAO,
});

function guardarFiltros() {
  try {
    const bolo = {};
    for (const chave of Object.keys(FILTROS_GUARDADOS())) if (ctx.tabs[chave]) bolo[chave] = ctx.tabs[chave];
    localStorage.setItem(CHAVE_DOS_FILTROS, JSON.stringify(bolo));
  } catch {
    /* navegador sem storage: o mercado continua, só sem memória */
  }
}

function lembrarFiltros() {
  try {
    const bolo = JSON.parse(localStorage.getItem(CHAVE_DOS_FILTROS) ?? '{}');
    for (const [chave, validos] of Object.entries(FILTROS_GUARDADOS())) {
      // Só preenche o que ainda não foi escolhido nesta sessão: a escolha de
      // agora sempre ganha da lembrança.
      if (ctx.tabs[chave] == null && bolo[chave] != null && bolo[chave] in validos) ctx.tabs[chave] = bolo[chave];
    }
  } catch {
    /* JSON estragado não pode impedir o mercado de abrir */
  }
}

/*
 * ---- Uma oferta de ESSÊNCIA, desenhada e nomeada ----
 *
 * As três funções abaixo existem porque a essência é o único item do jogo cuja
 * identidade não está no catálogo (ver `ID_DA_ESSENCIA`, no servidor): id único,
 * sem sprite e sem slot, com tudo o que a distingue viajando na instância.
 *
 * ---- Elas servem à OFERTA e à PEÇA, que dizem o mesmo com outros nomes ----
 *
 * A vitrine tem uma oferta na mão (`item`, `essenciaDe`); a mochila tem uma
 * peça (`id`, `raridade`). São os mesmos dados com dois vocabulários, porque um
 * passou pelo banco do mercado e o outro não.
 *
 * As três aceitam os dois, e é por isso que a caixa de anunciar deixou de
 * desenhar buraco: ela mostra o que está NA MOCHILA, e antes só a vitrine tinha
 * quem soubesse desenhar uma essência. Duas funções para o mesmo desenho seriam
 * duas chances de uma delas ficar para trás — foi exatamente o que aconteceu.
 */
const idDaPeca = (o) => Number(o?.item ?? o?.id);
const ehEssenciaDaOferta = (oferta) => idDaPeca(oferta) === ID_DA_ESSENCIA;
const raridadeDaEssencia = (o) => o?.essenciaDe ?? o?.raridade ?? null;

/*
 * ---- A VERMELHA, reconhecida pelo afixo e não só pela marca ----
 *
 * "tem que mostrar sempre com o brilho piscando lá, e em vermelho, inclusive no
 * market."
 *
 * O `mitica` é a resposta rápida, e o anúncio o carrega desde `marketOffers`.
 * A segunda resposta é intrínseca e não se perde: o afixo de uma vermelha vale
 * 130% da régua, e `estrelasDosAfixos` só devolve `q4` acima do topo — nenhum
 * drop, rerroll ou transferência chega lá. Mesma conta do `ehVermelha` do
 * servidor e do balão.
 */
const vermelhaNaOferta = (o) => !!o?.mitica || estrelasDosAfixos(o?.af)[0]?.q === 4;

const NOME_DO_SLOT_NA_OFERTA = {
  head: 'elmo', neck: 'colar', body: 'armadura', legs: 'perneira', feet: 'bota',
  ring: 'anel', weapon: 'arma', shield: 'escudo', ammo: 'munição', backpack: 'mochila',
};

function nomeDaOferta(oferta) {
  if (!ehEssenciaDaOferta(oferta)) return oferta.name ?? ctx.state.items[idDaPeca(oferta)]?.name ?? `item ${idDaPeca(oferta)}`;
  const vermelha = vermelhaNaOferta(oferta);
  const partes = [vermelha ? 'essência vermelha' : 'essência de afixo'];
  const slot = NOME_DO_SLOT_NA_OFERTA[oferta.afixoDe] ?? null;
  if (slot) partes.push(slot);
  // A vermelha não tem qualidade: ela entra em qualquer uma do slot dela.
  const raridade = raridadeDaEssencia(oferta);
  if (!vermelha && raridade && raridade !== 'comum') partes.push(raridade);
  return partes.join(' · ');
}

function arteDaOferta(oferta, size) {
  if (!ehEssenciaDaOferta(oferta)) return itemCanvas(idDaPeca(oferta), size, oferta.count);
  return arteDaEssencia(oferta.afixoDe ?? null, size, vermelhaNaOferta(oferta), raridadeDaEssencia(oferta));
}

function filtrosDoBalcao() {
  return {
    search: ctx.tabs.marketBusca ?? '',
    slot: ctx.tabs.marketSlot ?? 'all',
    vocation: ctx.tabs.marketVocacao ?? 'all',
    rarity: ctx.tabs.marketRaridade ?? 'all',
    essencias: ctx.tabs.marketEssencias ?? 'all',
    kind: ctx.tabs.marketLado ?? 'sell',
    moeda: moedaDoBalcao(),
    ordem: ctx.tabs.marketOrdem ?? 'barato',
    pagina: ctx.tabs.marketPagina ?? 1,
    porPagina: 8,
  };
}

/** Pede ao servidor a página de anúncios com os filtros de agora. */
function pedirOfertas() {
  ctx.send({ t: 'market', action: 'offers', filtros: filtrosDoBalcao() });
}

/** O mesmo, para o balcão de coins. */
function pedirCoins() {
  ctx.send({ t: 'coinMarket', pagina: ctx.tabs.coinPagina ?? 1 });
}

function renderMarket(body) {
  ctx.tabs.marketAba ??= 'ofertas';

  /*
   * O canto do cabeçalho é limpo em TODO desenho, e não só ao abrir.
   *
   * A peneira mora lá (ver `corpoDasOfertas`), e ela é só da aba de ofertas:
   * sem esta limpeza, trocar para Draevor Coins deixaria os filtros do balcão
   * pendurados no topo, mexendo numa lista que não está mais na tela.
   */
  const cantoDoTopo = ctx.acoesDoModal?.() ?? null;

  body.append(cabecaDoBalcao());

  if (ctx.tabs.marketAba === 'coins') return void corpoDasCoins(body);
  if (ctx.tabs.marketAba === 'minhas') return void corpoDasMinhas(body);
  if (ctx.tabs.marketAba === 'historico') return void corpoDoHistorico(body);
  corpoDasOfertas(body, cantoDoTopo);
}

/** O topo: as três abas e o que você tem de cada moeda. */
function cabecaDoBalcao() {
  const { state } = ctx;
  const topo = el('div', 'balcao-topo');

  /*
   * Cada aba com a figura que já existe para o assunto dela: o mercado, a coin
   * da loja e o bestiário. `tabBar` procura `aba-<id>` quando não se diz nada,
   * e não há `aba-ofertas` nenhum — sem este mapa as três sairiam de texto puro
   * no meio de um jogo em que toda aba tem cara.
   */
  const ICONES_DO_BALCAO = { ofertas: 'market', coins: 'coin-store', minhas: 'bestiary', historico: 'cyclopedia' };
  topo.append(
    tabBar(
      ABAS_DO_BALCAO,
      ctx.tabs.marketAba,
      (aba) => {
        ctx.tabs.marketAba = aba;
        if (aba === 'coins') pedirCoins();
        if (aba === 'ofertas') pedirOfertas();
        if (aba === 'historico') ctx.send({ t: 'market', action: 'historico' });
        ctx.redraw?.();
      },
      ICONES_DO_BALCAO
    )
  );

  /*
   * As duas moedas juntas, e sempre visíveis.
   *
   * Ouro é do personagem e coin é da conta — quem está comprando precisa dos
   * dois números na mesma linha de visão, porque a aba de coins troca um pelo
   * outro e a conta se faz de cabeça.
   */
  const saldos = el('div', 'balcao-saldos');
  /*
   * As moedas de VERDADE, e não um disco desenhado no CSS.
   *
   * O ouro é a pilha de 100 crystal coins do próprio client (item 3043), a
   * mesma que a barra do topo usa — ver `renderGoldIcon` no main.mjs. A coin é
   * a arte da loja (`coin-store`), a mesma da Store. Repetir a figura que
   * o jogador já conhece vale mais do que qualquer ícone novo.
   */
  const moeda = (classe, figura, valor, titulo) => {
    const chip = el('div', `balcao-moeda ${classe}`);
    chip.append(figura);
    chip.append(el('b', null, money(valor)));
    tipTexto(chip, titulo);
    return chip;
  };
  saldos.append(
    moeda('ouro', itemCanvas(3043, 18, 1), state.market?.gold ?? ouroDoJogador(state), 'seu ouro')
  );
  saldos.append(moeda('coin', uiIcon('coin-store'), state.character?.coins ?? 0, 'suas Draevor Coins'));

  /*
   * Anunciar fica no ALTO, ao lado do saldo, e não no meio da lista.
   *
   * Ele é a única ação da janela que não é "comprar", e no meio da tabela
   * disputava a atenção com as linhas. Aqui em cima ele fica onde o olho já
   * volta para conferir quanto se tem — e vale para as três abas de uma vez.
   */
  /*
   * ---- E ele muda com o LADO em que a pessoa está ----
   *
   * "não dá pra criar uma ordem de compra em procurados, só pra vender."
   *
   * Estava certo: o botão só sabia vender, e a prateleira "Procurados" nunca
   * tinha como encher — o servidor aceitava ordens de compra desde sempre, e
   * não havia porta nenhuma para elas na tela.
   *
   * Um botão só, que faz o que a prateleira aberta pede: em "À venda" ele
   * anuncia algo da sua mochila; em "Procurados" ele abre uma ordem de compra
   * de qualquer item do catálogo — porque justamente o que se procura é o que
   * NÃO se tem.
   */
  const procurandoAgora = (ctx.tabs.marketLado ?? 'sell') === 'buy';
  const anunciar = el('button', 'balcao-anunciar');
  anunciar.append(el('span', null, procurandoAgora ? '+ Quero comprar' : '+ Anunciar item'));
  tipTexto(
    anunciar,
    procurandoAgora
      ? 'abre uma ordem de compra: você diz o que procura e por quanto paga'
      : 'põe algo da sua mochila à venda'
  );
  anunciar.onclick = () => (procurandoAgora ? escolherItemParaComprar() : escolherItemParaVender());
  saldos.append(anunciar);

  topo.append(saldos);

  return topo;
}

// ------------------------------------------------------------------ ofertas

/*
 * ---- Os dois lados do balcão, em tamanho de decisão ----
 *
 * Eram dois chips no meio da fila de filtros, do tamanho de um seletor de slot
 * — e não são a mesma coisa. Slot e raridade PENEIRAM a lista; o lado decide o
 * que ela significa: "à venda" é o que dá para comprar, "procurados" é quem
 * está pagando por algo, e é essa metade que diz a quem TEM o item que vale a
 * pena vender.
 *
 * Escolha desse tamanho fica no meio, grande, antes de qualquer filtro.
 */
function ladosDoBalcao() {
  const par = el('div', 'balcao-par');
  const atual = ctx.tabs.marketLado ?? 'sell';

  const botao = (id, titulo, legenda) => {
    const b = el('button', `balcao-lado-grande${atual === id ? ' on' : ''} ${id}`);
    b.append(el('b', null, titulo));
    b.append(el('span', null, legenda));
    b.onclick = () => {
      if (ctx.tabs.marketLado === id) return;
      ctx.tabs.marketLado = id;
      ctx.tabs.marketPagina = 1;
      guardarFiltros();
      pedirOfertas();
      ctx.redraw?.();
    };
    return b;
  };

  par.append(botao('sell', LADOS_DO_BALCAO.sell, 'o que dá para comprar'));
  par.append(botao('buy', LADOS_DO_BALCAO.buy, 'quem está pagando por algo'));

  const caixa = el('div', 'balcao-lados');
  caixa.append(par);
  caixa.append(moedasDoBalcao());
  return caixa;
}

/*
 * A prateleira: ouro ou Draevor Coins.
 *
 * Menor que os dois lados de propósito — ela não muda o que a lista SIGNIFICA,
 * muda em que moeda os preços estão. Fica logo abaixo deles porque é a segunda
 * pergunta de quem procura: primeiro "comprar ou vender", depois "pagando com o
 * quê". Ver `MOEDAS_DO_BALCAO`.
 */
function moedasDoBalcao() {
  const fila = el('div', 'balcao-moedas');
  fila.append(el('span', 'balcao-moedas-rotulo', 'pago em'));

  const atual = moedaDoBalcao();
  for (const [id, moeda] of Object.entries(MOEDAS_DO_BALCAO)) {
    const botao = el('button', `balcao-moeda-chip${atual === id ? ' on' : ''} ${id}`);
    botao.append(moeda.figura());
    botao.append(el('b', null, moeda.nome));
    tipTexto(
      botao,
      id === 'coin'
        ? 'Anúncios pagos em Draevor Coins. A coin é da conta, e não do personagem.'
        : 'Anúncios pagos em ouro, o mercado de sempre.'
    );
    botao.onclick = () => {
      if (moedaDoBalcao() === id) return;
      ctx.tabs.marketMoeda = id;
      ctx.tabs.marketPagina = 1;
      guardarFiltros();
      pedirOfertas();
      ctx.redraw?.();
    };
    fila.append(botao);
  }
  return fila;
}

/*
 * ---- Os selos de uma peça: tier e imbuement, com o tempo que RESTA ----
 *
 * O mesmo desenho serve três telas porque as três falam da mesma coisa: o que
 * ESTA peça é. Antes só a vitrine sabia dizer — na hora de anunciar a pessoa
 * via um item sem marca nenhuma e tinha de confiar, e em "minhas ofertas" o
 * anúncio aparecia pelado.
 *
 * Recebe qualquer coisa com `tier`, `imbu`, `imbuementSlots` e `aceitaTier`: a
 * linha da vitrine (`marketOffers`), o anúncio próprio (`resumoDaMinha`) ou uma
 * peça crua da mochila.
 *
 * O tempo sai de `left`, que é o que SOBROU — o mesmo número que viaja na
 * compra. Escrevê-lo aqui é o que impede a tela de responder pelo id e mostrar
 * as 20 horas cheias de outra cópia que ficou na mochila.
 */
function marcasDaPeca(peca) {
  const marcas = el('div', 'balcao-marcas');

  /*
   * ---- As estrelas vêm primeiro ----
   *
   * Antes do tier porque, no balcão, é a estrela que decide o preço de uma peça
   * que não sobe tier: duas spears do mesmo id só se distinguem por ela, e quem
   * está comparando anúncios compara isso antes de qualquer outra coisa.
   *
   * A contagem e as cores saem da MESMA função do inventário, então uma peça no
   * balcão é desenhada como a peça na mochila — se divergissem, o comprador
   * estaria comparando duas linguagens diferentes na mesma tela.
   */
  const estrelas = estrelasDosAfixos(peca.af);
  if (estrelas.length) {
    const selo = el('span', 'balcao-afixo');
    selo.append(seloDeEstrelas('item-estrelas', estrelas));
    selo.append(el('b', null, estrelas.length === 1 ? '1 afixo' : `${estrelas.length} afixos`));
    tipTexto(
      selo,
      `${estrelas.length} atributo(s) extra(s) desta cópia — passe o mouse no nome para ver quais. ` +
        'A cor de cada estrela diz o quanto aquele afixo rolou perto do máximo dele.'
    );
    marcas.append(selo);
  }

  if (peca.tier > 0) {
    const tier = el('span', 'balcao-tier', `Tier ${peca.tier}`);
    tipTexto(tier, 'a peça vem com este tier — ele é dela, e vai junto na compra');
    marcas.append(tier);
  } else if (peca.aceitaTier) {
    const tier = el('span', 'balcao-tier vazio', 'Tier 0');
    tipTexto(tier, 'esta peça aceita tier, mas está sem nenhum');
    marcas.append(tier);
  }

  const ativos = (peca.imbu ?? []).filter((imbued) => (imbued?.left ?? 0) > 0);
  if (ativos.length) {
    // O MENOR tempo, e não o maior: é o que vence primeiro, e é ele que decide
    // por quanto tempo a peça ainda vale inteira.
    const menor = Math.min(...ativos.map((imbued) => imbued.left));
    const imb = el('span', 'balcao-imbu cheio', `${ativos.length} imbu · ${restanteDoImbuement(menor)}`);
    tipTexto(
      imb,
      `${ativos.length} imbuement(s) ativos — o primeiro a vencer tem ${restanteDoImbuement(menor)}. ` +
        'Vão com a peça pelo tempo que está sobrando agora: nada é reiniciado na venda.'
    );
    marcas.append(imb);
  } else if (peca.imbuementSlots > 0) {
    const imb = el('span', 'balcao-imbu', `${peca.imbuementSlots} slots`);
    tipTexto(imb, `${peca.imbuementSlots} espaço(s) de imbuement, nenhum preenchido`);
    marcas.append(imb);
  }

  return marcas;
}

/**
 * O cabeçalho da tabela de anúncios: quatro colunas que ordenam, e a coluna
 * vazia do botão. Ver `COLUNAS_DO_BALCAO`.
 */
function cabecaDasColunas(procurando) {
  const cabecalho = el('div', 'balcao-linha cabeca');
  const atual = ctx.tabs.marketOrdem ?? 'barato';

  for (const [rotulo, [sobe, desce], [comoSobe, comoDesce]] of COLUNAS_DO_BALCAO) {
    // A coluna do preço muda de nome com o lado: do lado "Procurados" o número
    // é o que a ordem PAGA, e não o que ela cobra.
    const nome = rotulo ?? (procurando ? 'Paga' : 'Preço');
    const cela = el('span', 'balcao-ordena', nome);
    const ligada = atual === sobe || atual === desce;
    const proxima = atual === sobe ? desce : sobe;
    if (ligada) {
      cela.classList.add('ordenando');
      // A setinha diz para que lado a lista está ordenada AGORA.
      cela.append(el('i', null, atual === sobe ? '▲' : '▼'));
    }
    tipTexto(cela, `ordenar por ${nome.toLowerCase()}, ${proxima === sobe ? comoSobe : comoDesce}`);
    cela.onclick = () => {
      ctx.tabs.marketOrdem = proxima;
      // A página volta ao começo: a página 3 da ordem antiga não quer dizer
      // nada na ordem nova, e ficar nela parece uma lista que sumiu.
      ctx.tabs.marketPagina = 1;
      guardarFiltros();
      pedirOfertas();
      ctx.redraw?.();
    };
    cabecalho.append(cela);
  }

  cabecalho.append(el('span', null, ''));
  return cabecalho;
}

function corpoDasOfertas(body, cantoDoTopo = null) {
  const { state, send } = ctx;

  /*
   * ---- A peneira sobe para o cabeçalho ----
   *
   * Ela ocupava a primeira faixa do corpo, e ali roubava a altura de uma linha
   * e meia da tabela — numa janela que já mostra oito anúncios, isso é o
   * suficiente para o jogador rolar. No cabeçalho ela fica ao lado do título,
   * no espaço que já existe entre ele e o X (`#modal-acoes`), sem cobrir
   * nenhum dos dois: quem empurra os três é o título, que estica.
   *
   * Sem cabeçalho — é o caso do teste de telas, que monta o corpo solto — ela
   * volta para dentro do corpo. A tela não pode depender de onde está sendo
   * desenhada.
   */
  const peneira = peneiraDoBalcao();
  if (cantoDoTopo) {
    peneira.classList.add('no-topo');
    cantoDoTopo.append(peneira);
  } else {
    body.append(peneira);
  }

  // A escolha do lado fica embaixo do filtro, que é a ordem de quem usa:
  // primeiro estreita o que procura, depois decide de que lado olhar.
  body.append(ladosDoBalcao());

  const dados = state.marketOffers;
  if (!dados) {
    pedirOfertas();
    return void body.append(el('p', 'empty', 'carregando...'));
  }

  /*
   * Do lado "Procurados" a linha é uma ordem de COMPRA: quem clica está
   * vendendo, e o botão tem de dizer isso. Trocar o rótulo de lado é o erro
   * clássico desta tela.
   */
  const procurando = (ctx.tabs.marketLado ?? 'sell') === 'buy';

  const tabela = el('div', 'balcao-tabela');
  tabela.append(cabecaDasColunas(procurando));

  for (const oferta of dados.offers ?? []) {
    const linha = el('div', 'balcao-linha');

    const nome = el('div', 'balcao-item');
    /*
     * ---- A ESSÊNCIA no balcão ----
     *
     * "a essência de afixo no market: a sprite não mostra às vezes."
     *
     * Era todas as vezes. Ela é o único item do jogo sem desenho próprio: o que
     * ela mostra é a silhueta do SLOT de onde o afixo saiu, e esse slot mora na
     * instância, não no catálogo. `itemCanvas` desenhava pelo id, o id não tem
     * sprite, e saía o buraco.
     *
     * O NOME tem o mesmo problema e a mesma cura: no catálogo todas se chamam
     * "essência de afixo", porque todas compartilham um id. O nome que distingue
     * uma da outra é montado da instância — "essência de afixo · bota · mítico"
     * —, e é o mesmo que a mochila e o balão mostram.
     */
    /*
     * A arte vem numa moldura só quando é essência: é ela que dá o canto em que a
     * estrela pousa. Peça normal continua como sempre foi — a estrela dela já sai
     * em `marcasDaPeca`, na linha de baixo.
     */
    if (ehEssenciaDaOferta(oferta)) {
      const moldura = el('div', 'forja-moldura mini');
      moldura.append(arteDaOferta(oferta, 32));
      const estrelas = estrelasDosAfixos(oferta.af);
      if (estrelas.length) moldura.append(seloDeEstrelas('selo-afixo', estrelas));
      nome.append(moldura);
    } else {
      nome.append(arteDaOferta(oferta, 32));
    }
    const texto = el('div', 'balcao-item-texto');
    texto.append(
      el(
        'b',
        CLASSE_DA_RARIDADE(
          ehEssenciaDaOferta(oferta)
            ? vermelhaNaOferta(oferta)
              ? 'mítico'
              : oferta.essenciaDe
            : oferta.rarity
        ),
        nomeDaOferta(oferta)
      )
    );

    /*
     * A segunda linha diz o que ESTA peça é, e não só de quem ela é.
     *
     * Desde que tier e imbuement passaram a morar na peça, o que aparece aqui é
     * o que o comprador vai receber — o tier exato e quanto tempo resta em cada
     * imbuement. Antes isto mostrava o tier de QUEM OLHAVA, porque não havia
     * tier preso à peça para mostrar.
     */
    const marcas = marcasDaPeca(oferta);
    marcas.append(el('em', null, `de ${oferta.seller}${oferta.count > 1 ? ` · ${money(oferta.count)}un` : ''}`));
    texto.append(marcas);

    nome.append(texto);
    // A OFERTA vai junto: é ela que carrega o tier e os imbuements desta peça,
    // e sem isso o balão responderia pelo id (ver `tipFor`).
    tipFor(nome, oferta.item, null, oferta.slot ?? null, oferta);
    linha.append(nome);

    /*
     * ---- O LEVEL que a peça pede, logo depois do nome ----
     *
     * "depois de item tem que estar escrito level, e mostrar o level de cada
     * item que pode ser usado."
     *
     * É a primeira pergunta de quem olha um anúncio — "isto serve para mim?" —,
     * e até agora a resposta só existia dentro do balão, para quem parasse o
     * mouse em cima. Ela vale uma coluna.
     *
     * Em VERMELHO quando pede mais do que o seu level. A peça continua à venda
     * e o botão continua ligado de propósito: comprar uma arma para o level que
     * falta pouco é uma coisa que as pessoas fazem, e a coluna avisa sem
     * impedir.
     *
     * Traço quando não pede nada (potion, munição, mochila): "level 0" seria um
     * número que não existe no jogo.
     */
    const pede = Math.floor(Number(oferta.minLevel) || 0);
    const meuLevel = state.character?.level ?? 0;
    const celaDoLevel = el('span', `balcao-level${pede > meuLevel ? ' alto' : ''}`, pede ? money(pede) : '—');
    tipTexto(
      celaDoLevel,
      !pede
        ? 'qualquer level usa'
        : pede > meuLevel
          ? `pede level ${money(pede)} — você está no ${money(meuLevel)}`
          : `pede level ${money(pede)}`
    );
    linha.append(celaDoLevel);

    /*
     * A essência não tem slot próprio, mas tem um slot de DESTINO — e é ele que
     * decide se ela serve para quem está olhando. É a resposta mais útil que
     * esta coluna pode dar sobre ela.
     */
    linha.append(
      el(
        'span',
        'balcao-slot',
        ehEssenciaDaOferta(oferta) ? SLOTS_DO_BALCAO[oferta.afixoDe] ?? 'afixo' : SLOTS_DO_BALCAO[oferta.slot] ?? '—'
      )
    );

    /*
     * A moeda ao lado do número, e não um "g" colado nele.
     *
     * É a mesma pilha de crystal coins do topo da tela (item 3043): o jogador
     * já sabe o que ela quer dizer, e a coluna fica legível de relance sem
     * precisar ler a letra.
     */
    const preco = el('div', 'balcao-preco');
    // A figura da moeda DO ANÚNCIO: uma crystal coin (e não a pilha — `count`
    // acima de 1 trocaria o sprite, ver `viewOf`) ou a Draevor Coin da loja.
    preco.append(precoComMoeda(oferta.price, oferta.moeda ?? 'gold'));
    if (oferta.count > 1) preco.append(el('em', null, `${money(oferta.total)} o lote`));
    linha.append(preco);

    /*
     * O botão diz o que dá para fazer, e o porquê quando não dá.
     *
     * Sem oferta própria e sem ouro são as duas recusas possíveis, e as duas
     * têm de aparecer ANTES do clique: um botão que só falha depois de apertado
     * faz o jogador achar que a tela travou.
     */
    const comprar = el('button', 'balcao-comprar');
    comprar.append(el('span', null, procurando ? 'Vender' : 'Comprar'));
    if (oferta.minha) {
      comprar.disabled = true;
      tipTexto(comprar, 'esta oferta é sua');
    } else if (procurando && tenhoDesse(oferta.item) < 1) {
      comprar.disabled = true;
      tipTexto(comprar, 'você não tem esse item');
    } else if (!procurando && saldoDaMoeda() < oferta.price) {
      /*
       * ---- A trava e' UMA unidade, e nao o lote ----
       *
       * O report do Garibas: "quando algum item e' anunciado no mercado em
       * LOTE, aparece o valor unitario, mas e' considerado o valor total; mesmo
       * que tenho dinheiro para comprar 1, nao e' possivel, o botao fica
       * desativado. Exemplo: item de 70kk vendido em lote de 3 — 210kk. Tenho
       * 80kk na bolsa: todos os outros itens de 70kk aparecem com botao
       * liberado, e o que vende em lote fica desativado."
       *
       * Ele achou uma contradicao DENTRO da propria tela. O botao conferia
       * `oferta.total` — o lote inteiro —, e a caixa que ele abre pergunta
       * QUANTOS e aceita compra parcial (o `disponivel`/`unitario` logo abaixo,
       * e o `acceptOffer` do servidor, que recebe `count`). Ou seja: a tela
       * trancava na porta a compra que ela mesma sabe fazer.
       *
       * O piso certo e' o preco de UMA: abaixo dele nao ha compra nenhuma
       * possivel, e acima dele a caixa e o `cabe` la' embaixo cuidam do resto —
       * eles ja' recusam a quantidade que nao cabe no bolso, com a conta certa.
       *
       * A mensagem acompanha: "faltam X para uma unidade" e' o que a pessoa
       * precisa saber. Dizer quanto falta para o lote inteiro e' responder uma
       * pergunta que ninguem fez.
       */
      comprar.disabled = true;
      tipTexto(
        comprar,
        `faltam ${money(oferta.price - saldoDaMoeda())}${MOEDAS_DO_BALCAO[moedaDoBalcao()].curto} para uma unidade`
      );
    } else {
      /*
       * A caixa pergunta QUANTOS antes de cobrar.
       *
       * O anúncio pode ser um lote — noventa e oito rope belts —, e levar as
       * noventa e oito era a única coisa que dava para fazer. O servidor já
       * aceita compra parcial (`acceptOffer` recebe `count`); o que faltava era
       * a tela perguntar.
       */
      comprar.onclick = () =>
        confirmarNegocio({
          titulo: procurando ? 'Vender para esta ordem' : 'Comprar do mercado',
          itemId: oferta.item,
          nome: oferta.name,
          /*
           * Vendendo, o teto é o menor entre o que a ordem PEDE e o que se
           * tem na mochila — oferecer mais do que se possui só daria recusa
           * do servidor depois do clique.
           */
          disponivel: procurando ? Math.min(oferta.count, tenhoDesse(oferta.item)) : oferta.count,
          unitario: oferta.price,
          cabe: procurando
            ? (n) => {
                const tenho = tenhoDesse(oferta.item);
                return tenho >= n ? null : `Você tem ${money(tenho)}.`;
              }
            : (_n, total) => {
                // A trava é a moeda DO ANÚNCIO: ouro é do personagem, coin é da
                // conta, e dizer "faltam X gold" para quem só não tem coin é
                // mandar a pessoa procurar a moeda errada.
                const meu = saldoDaMoeda();
                return meu >= total ? null : `Faltam ${money(total - meu)} ${MOEDAS_DO_BALCAO[moedaDoBalcao()].unidade}.`;
              },
          unidade: MOEDAS_DO_BALCAO[oferta.moeda ?? 'gold'].unidade,
          acao: procurando ? 'Vender' : 'Comprar',
          aoConfirmar: (quantos) =>
            send({ t: 'market', action: 'accept', offerId: oferta.id, count: quantos, filtros: filtrosDoBalcao() }),
        });
    }
    linha.append(comprar);
    tabela.append(linha);
  }

  if (!(dados.offers ?? []).length) {
    const emQue = moedaDoBalcao() === 'coin' ? ' em Draevor Coins' : ' em ouro';
    tabela.append(
      el(
        'p',
        'empty',
        procurando
          ? `Ninguém procurando nada${emQue} com esses filtros.`
          : `Nenhum anúncio${emQue} com esses filtros.`
      )
    );
  }
  body.append(tabela);

  body.append(
    paginador(dados.pagina, dados.paginas, dados.total, 'anúncios', (pagina) => {
      ctx.tabs.marketPagina = pagina;
      pedirOfertas();
    })
  );
}

/** A fila de peneiras: busca, slot, vocação, raridade, ordem e o limpar. */
function peneiraDoBalcao() {
  const fila = el('div', 'balcao-peneira');

  /*
   * ---- A busca, com a figura do item enquanto se digita ----
   *
   * Escrever "harnes" e receber uma lista de nomes não diz qual dos dois é o
   * que se procura — no jogo o item se reconhece pelo DESENHO. A lista sai do
   * catálogo que o cliente já tem em `state.items`, então ela aparece sem ida
   * ao servidor, a cada tecla.
   *
   * Escolher um item escreve o nome exato na busca: quem filtra continua sendo
   * o servidor, e o resultado passa a ser daquele item só.
   */
  const caixaDaBusca = el('div', 'balcao-busca');
  const busca = document.createElement('input');
  busca.className = 'search';
  busca.placeholder = 'buscar item...';
  busca.value = ctx.tabs.marketBusca ?? '';
  caixaDaBusca.append(busca);

  /*
   * A lista mora no BODY, e não dentro da caixa da busca.
   *
   * Dentro dela, o `overflow: hidden` do cabeçalho do modal a recortava; tirar
   * o recorte de lá soltava a fila de filtros inteira para fora da moldura. Em
   * camada fixa ela não depende de quem está por perto — só do retângulo do
   * campo, que é o que `posicionarSugestoes` lê.
   */
  const sugestoes = el('div', 'balcao-sugestoes');
  sugestoes.hidden = true;
  document.body.append(sugestoes);

  const posicionarSugestoes = () => {
    const r = busca.getBoundingClientRect();
    sugestoes.style.left = `${Math.round(r.left)}px`;
    sugestoes.style.top = `${Math.round(r.bottom + 4)}px`;
    // Nunca mais estreita que o campo, nunca mais larga que o que sobra à
    // direita: um nome comprido não pode empurrar a lista para fora da tela.
    sugestoes.style.width = `${Math.round(Math.max(r.width, 220))}px`;
    sugestoes.style.maxWidth = `${Math.round(window.innerWidth - r.left - 12)}px`;
  };

  const fecharSugestoes = () => {
    sugestoes.hidden = true;
    sugestoes.innerHTML = '';
  };

  /*
   * A lista sai do documento junto com a janela.
   *
   * Morando no `body`, ela não é levada quando o modal é redesenhado ou
   * fechado — ficaria pendurada na tela, sobre o jogo, sem dono. O observador
   * do campo é o que amarra o tempo de vida dos dois.
   */
  const vigia = new MutationObserver(() => {
    if (!busca.isConnected) {
      sugestoes.remove();
      vigia.disconnect();
    }
  });
  vigia.observe(document.body, { childList: true, subtree: true });

  const sugerir = (termo) => {
    sugestoes.innerHTML = '';
    const alvo = termo.trim().toLowerCase();
    if (alvo.length < 2) return void fecharSugestoes();

    // Oito é o que cabe sem virar uma segunda tela; quem quer o resto digita mais.
    const achados = [];
    for (const meta of Object.values(ctx.state.items ?? {})) {
      if (!meta?.name || !meta.name.toLowerCase().includes(alvo)) continue;
      achados.push(meta);
      if (achados.length >= 8) break;
    }
    if (!achados.length) return void fecharSugestoes();

    for (const meta of achados) {
      const linha = el('button', 'balcao-sugestao');
      linha.append(itemCanvas(meta.id, 28));
      const texto = el('div', 'balcao-sugestao-texto');
      texto.append(el('b', null, meta.name));
      const marcas = [SLOTS_DO_BALCAO[meta.slot], meta.rarity].filter(Boolean).join(' · ');
      if (marcas) texto.append(el('em', null, marcas));
      linha.append(texto);
      tipFor(linha, meta.id);
      linha.onclick = () => {
        ctx.tabs.marketBusca = meta.name;
        ctx.tabs.marketPagina = 1;
        busca.value = meta.name;
        fecharSugestoes();
        pedirOfertas();
      };
      sugestoes.append(linha);
    }
    posicionarSugestoes();
    sugestoes.hidden = false;
  };

  let timer = null;
  busca.oninput = () => {
    ctx.tabs.marketBusca = busca.value;
    ctx.tabs.marketPagina = 1;
    sugerir(busca.value);
    clearTimeout(timer);
    // Um quarto de segundo de espera: digitar "dragon" são seis teclas, e seria
    // uma consulta por tecla.
    timer = setTimeout(pedirOfertas, 250);
  };
  // Escape fecha a lista sem apagar o que foi digitado.
  busca.onkeydown = (evento) => {
    if (evento.key === 'Escape' && !sugestoes.hidden) {
      evento.stopPropagation();
      fecharSugestoes();
    }
  };
  busca.onblur = () => setTimeout(fecharSugestoes, 150);
  fila.append(caixaDaBusca);

  const escolha = (chave, opcoes, atual) => {
    const campo = document.createElement('select');
    /*
     * Cada seletor com o seu id — `marketSlot` vira `market-slot`.
     *
     * Não é enfeite: o redesenho do painel devolve o foco ao campo em que a
     * pessoa estava, e sem id ele casava os campos pelo `placeholder`, que num
     * `<select>` é `undefined` — e `undefined === undefined` casava QUALQUER
     * seletor com qualquer outro. Era daí que vinha o filtro "resetando"
     * sozinho no meio da caçada. Ver `refreshOpenPanel`, no main.mjs.
     */
    campo.id = chave.replace(/([A-Z])/g, '-$1').toLowerCase();
    for (const [valor, rotulo] of Object.entries(opcoes)) {
      const opcao = document.createElement('option');
      opcao.value = valor;
      opcao.textContent = rotulo;
      campo.append(opcao);
    }
    campo.value = ctx.tabs[chave] ?? atual;
    campo.onchange = () => {
      ctx.tabs[chave] = campo.value;
      ctx.tabs.marketPagina = 1;
      guardarFiltros();
      pedirOfertas();
    };
    fila.append(campo);
  };

  escolha('marketSlot', SLOTS_DO_BALCAO, 'all');
  escolha('marketVocacao', VOCACOES_DO_BALCAO, 'all');
  escolha('marketRaridade', RARIDADES_DO_BALCAO, 'all');
  escolha('marketEssencias', ESSENCIAS_DO_BALCAO, 'all');
  escolha('marketOrdem', ORDENS_DO_BALCAO, 'barato');

  const limpar = el('button', 'balcao-limpar', 'Limpar');
  limpar.onclick = () => {
    ctx.tabs.marketBusca = '';
    ctx.tabs.marketSlot = 'all';
    ctx.tabs.marketVocacao = 'all';
    ctx.tabs.marketRaridade = 'all';
    ctx.tabs.marketEssencias = 'all';
    ctx.tabs.marketOrdem = 'barato';
    ctx.tabs.marketLado = 'sell';
    ctx.tabs.marketMoeda = 'gold';
    ctx.tabs.marketPagina = 1;
    // Limpar limpa também o que estava guardado: senão a peneira antiga
    // voltaria na próxima vez que a janela abrisse.
    guardarFiltros();
    pedirOfertas();
    ctx.redraw?.();
  };
  fila.append(limpar);

  return fila;
}

/** Anterior / página / próxima, com a contagem do que foi peneirado. */
function paginador(pagina, paginas, total, unidade, ir) {
  const barra = el('div', 'balcao-paginas');

  const anterior = el('button', null, '‹ Anterior');
  anterior.disabled = pagina <= 1;
  anterior.onclick = () => ir(pagina - 1);
  barra.append(anterior);

  barra.append(el('span', 'balcao-conta', `${pagina} / ${paginas}${total != null ? ` — ${money(total)} ${unidade}` : ''}`));

  const proxima = el('button', null, 'Próxima ›');
  proxima.disabled = pagina >= paginas;
  proxima.onclick = () => ir(pagina + 1);
  barra.append(proxima);

  return barra;
}

// -------------------------------------------------------------- draevor coins

/*
 * ---- O câmbio ----
 *
 * Duas colunas, e o rótulo de cada botão sai do que a COLUNA é, nunca do lado
 * em que ela está — é o erro clássico desta tela. Na coluna de quem está
 * comprando coin, o seu botão é VENDER: você está aceitando a ordem dele.
 *
 * A mercadoria de toda ordem já está retida desde o anúncio (ver `coin_market`
 * no db.mjs), então aceitar aqui nunca esbarra em alguém que gastou no meio do
 * caminho.
 */
function corpoDasCoins(body) {
  const { state, send } = ctx;
  const dados = state.coinMarket;
  if (!dados) {
    pedirCoins();
    return void body.append(el('p', 'empty', 'carregando...'));
  }

  const aviso = el('div', 'balcao-cambio-nota');
  aviso.append(
    el(
      'p',
      null,
      'Draevor Coins são da CONTA e o ouro é do PERSONAGEM. O que você anunciar fica retido até alguém aceitar ' +
        'ou até você cancelar — nada é cobrado duas vezes. Ordens abertas valem 30 dias.'
    )
  );
  body.append(aviso);

  const colunas = el('div', 'balcao-cambio');
  colunas.append(
    colunaDeCoins('Ordens de compra', 'compra', dados.compra, 'Vender', 'buy', (linha) => (state.character?.coins ?? 0) >= linha.amount, 'você não tem essas coins')
  );
  colunas.append(
    colunaDeCoins('Ordens de venda', 'venda', dados.venda, 'Comprar', 'sell', (linha) => ouroDoJogador(state) >= linha.total, 'ouro insuficiente')
  );
  body.append(colunas);

  function colunaDeCoins(titulo, marca, lado, rotulo, kind, podeAceitar, recusa) {
    const bloco = el('div', `balcao-coluna ${marca}`);

    const topo = el('div', 'balcao-coluna-topo');
    topo.append(el('b', null, titulo));
    const criar = el('button', 'balcao-criar', kind === 'buy' ? '+ Quero comprar' : '+ Quero vender');
    criar.onclick = () => criarOrdemDeCoin(kind);
    topo.append(criar);
    bloco.append(topo);

    const grade = el('div', 'balcao-tabela coins');
    const cabecalho = el('div', 'balcao-linha cabeca');
    for (const r of ['Quem', 'Coins', 'Preço', 'Total', '']) {
      const celula = el('span', null, r);
      /*
       * A moeda ao lado da palavra, a pedido do dono.
       *
       * É a arte da própria loja (`coin-store`), a mesma do chip de saldo no
       * topo e da aba. As outras duas colunas são em OURO, e é justamente por
       * isso que esta precisa da figura: sem ela, quatro números seguidos não
       * dizem qual deles é a mercadoria e quais são o preço.
       */
      if (r === 'Coins') {
        celula.classList.add('balcao-coluna-coin');
        celula.prepend(uiIcon('coin-store'));
      }
      cabecalho.append(celula);
    }
    grade.append(cabecalho);

    for (const linha of lado.linhas ?? []) {
      const item = el('div', 'balcao-linha');
      item.append(el('span', 'balcao-quem', linha.seller));
      item.append(el('span', 'balcao-coin-qtd', money(linha.amount)));
      item.append(el('span', 'balcao-coin-preco', `${money(linha.price)}g`));
      item.append(el('span', 'balcao-coin-total', `${money(linha.total)}g`));

      const acao = el('button', 'balcao-comprar');
      acao.append(el('span', null, linha.minha ? 'Cancelar' : rotulo));
      if (linha.minha) {
        acao.classList.add('ghost');
        acao.onclick = () => send({ t: 'coinMarket', action: 'cancel', orderId: linha.id, pagina: ctx.tabs.coinPagina ?? 1 });
      } else if (!podeAceitar(linha)) {
        acao.disabled = true;
        tipTexto(acao, recusa);
      } else {
        acao.onclick = () =>
          confirmarNegocio({
            titulo: kind === 'buy' ? 'Vender Draevor Coins' : 'Comprar Draevor Coins',
            arteDaMoeda: 'coin-store',
            nome: 'Draevor Coins',
            disponivel: linha.amount,
            unitario: linha.price,
            /*
             * Aceitar uma ordem de COMPRA é vender coin: a trava são as coins.
             * Aceitar uma de VENDA é comprar coin: a trava é o ouro do total.
             */
            cabe:
              kind === 'buy'
                ? (n) => {
                    const minhas = state.character?.coins ?? 0;
                    return minhas >= n ? null : `Você tem ${money(minhas)} coins.`;
                  }
                : (_n, total) => {
                    const meu = ouroDoJogador(state);
                    return meu >= total ? null : `Faltam ${money(total - meu)} gold.`;
                  },
            unidade: 'gold',
            acao: rotulo,
            aoConfirmar: (quantas) =>
              send({ t: 'coinMarket', action: 'accept', orderId: linha.id, amount: quantas, pagina: ctx.tabs.coinPagina ?? 1 }),
          });
      }
      item.append(acao);
      grade.append(item);
    }
    if (!(lado.linhas ?? []).length) grade.append(el('p', 'empty', 'ninguém aqui ainda'));
    bloco.append(grade);

    bloco.append(
      paginador(lado.pagina, lado.paginas, lado.total, 'ordens', (pagina) => {
        ctx.tabs.coinPagina = pagina;
        pedirCoins();
      })
    );
    return bloco;
  }
}

/** A caixa de anunciar coin: quantas, por quanto, e o total já somado. */
function criarOrdemDeCoin(kind) {
  const { state, send } = ctx;
  const vendendo = kind === 'sell';

  const back = el('div', 'confirm-back');
  const box = el('div', 'confirm-box');
  box.append(el('h3', null, vendendo ? 'Vender Draevor Coins' : 'Comprar Draevor Coins'));
  box.append(
    el(
      'p',
      'confirm-short',
      vendendo
        ? `Você tem ${money(state.character?.coins ?? 0)} coins. Elas ficam retidas até alguém comprar.`
        : `Você tem ${money(ouroDoJogador(state))}g. O ouro fica retido até alguém vender.`
    )
  );

  const resumo = el('p', 'confirm-short');
  // `let` e guarda, pelo mesmo motivo de `criarOferta` logo acima.
  let quantas = null;
  let preco = null;
  const recalcular = () => {
    if (!quantas || !preco) return;
    const total = quantas.ler() * preco.ler();
    resumo.textContent = vendendo
      ? `Você recebe ${money(total)}g quando alguém comprar tudo.`
      : `Você paga ${money(total)}g agora, e recebe as coins conforme forem vendendo.`;
  };

  quantas = campoDeNumero({
    rotulo: 'Quantas coins',
    valor: 1,
    min: 1,
    max: vendendo ? state.character?.coins ?? 1 : null,
    comMax: vendendo,
    aoMudar: () => recalcular(),
  });
  preco = campoDeNumero({ rotulo: 'Ouro por coin', valor: 1000, min: 1, aoMudar: () => recalcular() });
  box.append(quantas.wrap, preco.wrap);
  recalcular();
  box.append(resumo);

  const acoes = el('div', 'confirm-actions');
  const cancelar = el('button', 'ghost', 'Cancelar');
  cancelar.onclick = () => back.remove();
  const confirmar = el('button', null, 'Anunciar');
  confirmar.onclick = () => {
    send({
      t: 'coinMarket',
      action: 'order',
      kind,
      amount: quantas.ler(),
      price: preco.ler(),
      pagina: ctx.tabs.coinPagina ?? 1,
    });
    back.remove();
  };
  acoes.append(cancelar, confirmar);
  box.append(acoes);

  back.append(box);
  document.body.append(back);
}

// ---------------------------------------------------------------- histórico

/*
 * ---- O extrato do balcão ----
 *
 * Item e coin na MESMA lista, ordenados no tempo. Para quem abre a janela, "o
 * que eu negociei" é uma pergunta só: separar em duas telas obrigaria a olhar
 * as duas para reconstruir a mesma tarde.
 *
 * Cada linha diz de que lado a pessoa esteve — quem decide é o servidor,
 * comparando o nome com as duas pontas da negociação (ver `meuHistorico`).
 * Compra sai em cobre com sinal de menos, venda em verde com mais: a cor
 * responde "isso entrou ou saiu?" antes da leitura do número.
 */
function corpoDoHistorico(body) {
  const { state } = ctx;
  const dados = state.marketHistorico;
  if (!dados) {
    ctx.send({ t: 'market', action: 'historico' });
    return void body.append(el('p', 'empty', 'carregando...'));
  }

  /*
   * ---- O somatório é POR MOEDA ----
   *
   * Ele era um só, e somava tudo o que passou pelo balcão. Desde que um item
   * pode ser pago em Draevor Coins isso virou uma conta sem sentido: dez coins
   * entravam na mesma pilha de trezentos gold. Agora são dois pares, e o par
   * das coins só aparece para quem negociou em coin — quem nunca fez isso não
   * ganha dois números vazios na tela.
   */
  const resumo = el('div', 'balcao-saldos hist-resumo');
  const chip = (classe, figura, valor, rotulo) => {
    const caixa = el('div', `balcao-moeda ${classe}`);
    caixa.append(figura);
    caixa.append(el('b', null, money(valor)));
    caixa.append(el('span', null, rotulo));
    return caixa;
  };
  resumo.append(chip('ouro hist-ganho', MOEDAS_DO_BALCAO.gold.figura(), dados.ganho, 'recebido'));
  resumo.append(chip('ouro hist-gasto', MOEDAS_DO_BALCAO.gold.figura(), dados.gasto, 'gasto'));
  if (dados.ganhoCoin || dados.gastoCoin) {
    resumo.append(chip('coin hist-ganho', MOEDAS_DO_BALCAO.coin.figura(), dados.ganhoCoin ?? 0, 'recebido'));
    resumo.append(chip('coin hist-gasto', MOEDAS_DO_BALCAO.coin.figura(), dados.gastoCoin ?? 0, 'gasto'));
  }
  body.append(resumo);

  const tabela = el('div', 'balcao-tabela');
  const cabecalho = el('div', 'balcao-linha cabeca hist');
  for (const r of ['Quando', 'O quê', 'Com quem', 'Total']) cabecalho.append(el('span', null, r));
  tabela.append(cabecalho);

  for (const linha of dados.linhas ?? []) {
    const item = el('div', `balcao-linha hist ${linha.lado}`);
    item.append(el('span', 'hist-quando', quandoFoi(linha.at)));

    const oque = el('div', 'balcao-item');
    if (linha.item != null) oque.append(itemCanvas(linha.item, 26, linha.count));
    else oque.append(uiIcon('coin-store'));
    const texto = el('div', 'balcao-item-texto');
    texto.append(el('b', null, linha.name));
    /*
     * A moeda da NEGOCIAÇÃO, e não o `g` de sempre.
     *
     * O dono: "o histórico no market tem que mostrar se foi gold ou draevor coins
     * que o item foi comprado ou vendido, com a sprite do draevor coins se for
     * draevor coins". Sem isso, um item vendido por 10 coins aparecia como "10g"
     * — e um extrato que mente sobre a moeda é pior do que não ter extrato.
     *
     * A linha do CÂMBIO fica em ouro: lá a mercadoria é a coin, e o preço
     * sempre foi em ouro. Ver `meuHistorico`.
     */
    const moedaDaLinha = linha.tipo === 'item' && linha.moeda === 'coin' ? 'coin' : 'gold';
    /*
     * E quando houve taxa, ela vem escrita: o preço combinado foi um e o que
     * entrou na conta foi outro. Só o mercado em coin desconta na hora — ver
     * `meuHistorico`.
     */
    const daTaxa = linha.taxa ? ` − ${money(linha.taxa)} de taxa` : '';
    texto.append(
      el(
        'em',
        null,
        `${linha.lado === 'compra' ? 'comprou' : 'vendeu'} ${money(linha.count)} × ` +
          `${money(linha.price)}${MOEDAS_DO_BALCAO[moedaDaLinha].curto}${daTaxa}`
      )
    );
    oque.append(texto);
    if (linha.item != null) tipFor(oque, linha.item);
    item.append(oque);

    item.append(el('span', 'hist-quem', linha.outro));

    const total = el('div', 'balcao-preco');
    const valor = el('div', `balcao-preco-linha ${moedaDaLinha}`);
    // A figura da moeda em que ESTA negociação foi paga.
    valor.append(MOEDAS_DO_BALCAO[moedaDaLinha].figura());
    // O LÍQUIDO, e não o preço de tabela: é o que a conta viu. Ver `meuHistorico`.
    valor.append(el('b', null, `${linha.lado === 'compra' ? '−' : '+'}${money(linha.liquido ?? linha.total)}`));
    total.append(valor);
    item.append(total);

    tabela.append(item);
  }

  if (!(dados.linhas ?? []).length) {
    tabela.append(el('p', 'empty', 'Você ainda não comprou nem vendeu nada por aqui.'));
  }
  body.append(tabela);

  body.append(
    el(
      'p',
      'shop-note',
      'As sessenta negociações mais recentes deste personagem, no mercado de itens e no de coins. ' +
        'A figura ao lado de cada valor diz em que moeda ela foi paga.'
    )
  );
}

/** "há 3 min", "há 2h", "ontem" — o relógio de quem lembra, não o do sistema. */
function quandoFoi(at) {
  const minutos = Math.max(0, Math.round((Date.now() - (at ?? 0)) / 60000));
  if (minutos < 1) return 'agora';
  if (minutos < 60) return `há ${minutos} min`;
  const horas = Math.round(minutos / 60);
  if (horas < 24) return `há ${horas}h`;
  const dias = Math.round(horas / 24);
  return dias === 1 ? 'ontem' : `há ${dias} dias`;
}

// ------------------------------------------------------------ minhas ofertas

function corpoDasMinhas(body) {
  const { state, send } = ctx;

  const topo = el('div', 'balcao-coluna-topo');
  topo.append(el('b', null, 'O que você tem anunciado'));
  body.append(topo);

  const minhas = state.market?.mine ?? [];
  const minhasCoins = state.coinMarket?.minhas ?? [];

  if (!minhas.length && !minhasCoins.length) {
    body.append(el('p', 'empty', 'Você não tem nenhuma oferta em pé.'));
    return;
  }

  const grade = el('div', 'balcao-tabela');
  for (const oferta of minhas) {
    const linha = el('div', 'balcao-linha minha');
    const nome = el('div', 'balcao-item');
    nome.append(arteDaOferta(oferta, 28));
    const texto = el('div', 'balcao-item-texto');
    texto.append(
      el('b', null, ehEssenciaDaOferta(oferta) ? nomeDaOferta(oferta) : state.items[oferta.item]?.name ?? `item ${oferta.item}`)
    );
    // Os selos do que está RETIDO ali. Sem eles esta linha aparecia pelada, e o
    // balão — sem peça para consultar — respondia pelo id, mostrando o
    // imbuement de outra cópia que ficou na mochila, com o tempo dela.
    if (oferta.kind === 'sell') texto.append(marcasDaPeca(oferta));
    nome.append(texto);
    tipFor(nome, oferta.item, null, state.items[oferta.item]?.slot ?? null, oferta.kind === 'sell' ? oferta : null);
    linha.append(nome);
    linha.append(el('span', 'balcao-slot', oferta.kind === 'sell' ? 'vendendo' : 'comprando'));
    linha.append(el('span', 'balcao-coin-qtd', `${money(oferta.count)}x`));
    const preco = el('div', 'balcao-preco');
    // A moeda do anúncio, e não o `g` de sempre: desde os anúncios em coin,
    // esta coluna mostrava tudo com o cifrão do ouro.
    preco.append(precoComMoeda(oferta.price, oferta.moeda ?? 'gold'));
    linha.append(preco);
    const cancelar = el('button', 'balcao-comprar ghost');
    cancelar.append(el('span', null, 'Cancelar'));
    cancelar.onclick = () => send({ t: 'market', action: 'cancel', offerId: oferta.id, filtros: filtrosDoBalcao() });
    linha.append(cancelar);
    grade.append(linha);
  }

  for (const ordem of minhasCoins) {
    const linha = el('div', 'balcao-linha minha');
    const nome = el('div', 'balcao-item');
    nome.append(el('b', null, 'Draevor Coins'));
    linha.append(nome);
    linha.append(el('span', 'balcao-slot', ordem.kind === 'sell' ? 'vendendo' : 'comprando'));
    linha.append(el('span', 'balcao-coin-qtd', `${money(ordem.amount)}`));
    const preco = el('div', 'balcao-preco');
    preco.append(el('b', null, `${money(ordem.price)}g`));
    preco.append(el('em', null, `${money(ordem.amount * ordem.price)}g o lote`));
    linha.append(preco);
    const cancelar = el('button', 'balcao-comprar ghost');
    cancelar.append(el('span', null, 'Cancelar'));
    cancelar.onclick = () => send({ t: 'coinMarket', action: 'cancel', orderId: ordem.id, pagina: ctx.tabs.coinPagina ?? 1 });
    linha.append(cancelar);
    grade.append(linha);
  }
  body.append(grade);

  body.append(
    el(
      'p',
      'shop-note',
      'Em ouro a taxa é de 2% do total (mínimo 20 gold), paga por quem anuncia. Em Draevor Coins ela é de 10%, ' +
        'descontada de quem RECEBE as coins na hora do negócio — anunciar não custa nada. ' +
        'O que você vende sai da mochila na hora; o pagamento chega para a outra pessoa no próximo login dela. ' +
        'Uma oferta dura 7 dias — vencida, a peça (ou o dinheiro) volta pelo correio.'
    )
  );
}

/*
 * Aberto para conferência, como o `_interno` da hunt e o da cidade.
 *
 * As caixas do balcão são construídas em JavaScript puro dentro de `onclick`, e
 * um erro de referência ali não aparece em lugar nenhum: a caixa não abre, e
 * pronto. `tools/test-telas.mjs` monta cada uma com um DOM de mentira e falha
 * se a montagem estourar. Nada da tela depende deste objeto.
 */
export const _telasDoBalcao = {
  campoDeNumero,
  confirmarNegocio,
  criarOferta,
  criarOrdemDeCoin,
  escolherItemParaVender,
  renderMarket,
  corpoDoHistorico,
  renderBlessings,
  renderBank,
  /*
   * O balcão da Zuma e a forja entram aqui pelo mesmo motivo, e com um a mais:
   * as duas telas ganharam CAIXAS DE CONFIRMAÇÃO, e uma caixa que não abre é
   * exatamente o defeito que este objeto existe para pegar. Ver
   * `tools/test-balcao-tela.mjs`.
   */
  renderLojaNpc,
  renderForja,
};

/*
 * ---- Escolher o que vender ----
 *
 * Com a lista de anúncios no lugar do catálogo, não há mais de onde clicar num
 * item para vendê-lo — e sem isto o mercado viraria só de compra. A escolha sai
 * do que a pessoa TEM à mão (mochila e bolsa), que é o único conjunto do qual
 * ela pode anunciar mesmo.
 */
function escolherItemParaVender() {
  const { state } = ctx;

  /*
   * ---- Uma linha por PEÇA, e não por id ----
   *
   * Isto somava tudo por id: três espadas iguais viravam um botão só, com
   * "3x" ao lado. Só que desde que tier e imbuement passaram a morar na peça,
   * três espadas iguais podem ser três coisas diferentes — uma tier 9, uma
   * imbuída com meio dia pela frente e uma limpa.
   *
   * Somadas, o jogador não escolhia coisa nenhuma: ele clicava no botão e o
   * servidor levava a PRIMEIRA cópia que achasse. Dava para anunciar a limpa e
   * ver a tier 9 sair da mochila.
   *
   * Então quem tem tier ou imbuement ganha linha própria, com os selos e o
   * tempo que resta escritos nela, e leva junto o endereço (lista e posição)
   * que o servidor usa para tirar exatamente aquela. O que não tem extra
   * nenhum continua somado — entre duas poções iguais não há o que escolher.
   *
   * ---- E os AFIXOS, que faltavam ----
   *
   * "nao da para saber o item q vc vai colocar a venda, so aparece o tipo; vc
   * precisa colocar a venda e depois tirar para conseguir vender o item".
   *
   * A conta era `tier > 0 || imbu.length`, e ela é de antes de os afixos
   * existirem. Duas espadas do mesmo id, mesmo tier e sem imbuement — uma com
   * três estrelas douradas e uma limpa — caíam as duas no balde do "somado":
   * viravam um botão só, sem estrela nenhuma na tela, e o servidor levava a
   * primeira que achasse. Era o defeito de sempre, de volta pela porta nova.
   *
   * A estrela é justamente o que separa duas cópias que o resto do jogo já não
   * distingue: sem tier e sem imbuement, ela é a ÚNICA diferença entre elas.
   */
  const comExtras = [];
  const limpos = new Map();
  /*
   * ---- E a BOSS POUCH e a terceira fonte ----
   *
   * "dentro da boss pouch... eu conseguiria arrastar pra mochila ou por esses
   * itens no market."
   *
   * Sem ela, anunciar o que caiu de um boss era tirar da bolsa, pos na mochila
   * de vinte vagas e so' entao abrir o mercado — tres passos para o que o resto
   * do jogo faz em um. O `onde` viaja no endereco e o servidor tira exatamente
   * daquela lista (ver `listaDaOrigem`, em store.mjs).
   */
  const fontes = [
    ['inventory', state.character?.inventory ?? []],
    ['pouch', state.character?.pouch ?? []],
    ['bossPouch', state.character?.bossPouch ?? []],
  ];
  for (const [onde, lista] of fontes) {
    lista.forEach((entrada, indice) => {
      const meta = state.items[entrada.id] ?? {};
      const dados = {
        id: entrada.id,
        count: entrada.count,
        tier: Number(entrada.tier) || 0,
        imbu: (entrada.imbu ?? []).filter((imbued) => (imbued?.left ?? 0) > 0),
        imbuementSlots: meta.imbuementSlots ?? 0,
        aceitaTier: !!state.catalog?.efeitosDeTier?.[meta.slot],
        // Os afixos DESTA cópia: é deles que saem as estrelas do botão, e é por
        // eles que o servidor sabe qual das cópias tirar.
        af: entrada.af ?? null,
        /*
         * ---- E o que faz de uma essência AQUELA essência ----
         *
         * "quando eu vou anunciar uma essência de afixo não mostra a sprite do
         * item, e no tooltip mostra a sprite errada também."
         *
         * As duas metades do mesmo esquecimento. A essência não tem sprite nem
         * slot no catálogo — o que ela é mora na instância —, e esta lista era
         * montada campo a campo, copiando só o que peça normal tem. Sem estes
         * quatro, `itemCanvas` desenhava o vazio e o balão respondia pelo id:
         * "comum · sem slot de origem", com a silhueta de mochila que é a
         * reserva de quem não sabe o slot.
         */
        afixoDe: entrada.afixoDe ?? null,
        raridade: entrada.raridade ?? null,
        origem: entrada.origem ?? null,
        mitica: !!entrada.mitica,
        // O endereço da peça E a assinatura do que a tela viu nela: o servidor
        // confere as duas antes de tirar (ver `pecaEscolhida`).
        alvo: {
          onde,
          indice,
          tier: Number(entrada.tier) || 0,
          imbus: (entrada.imbu ?? []).filter((imbued) => (imbued?.left ?? 0) > 0).length,
          /*
           * Os afixos viajam INTEIROS na assinatura, e não contados.
           *
           * Contar (como se faz com os imbuements) não bastaria: duas espadas
           * com dois afixos cada podem ter afixos diferentes, ou o mesmo afixo
           * com valores diferentes — que é a peça boa e a peça ruim. O servidor
           * compara o conjunto (ver `assinaturaDeAfixos`).
           */
          af: entrada.af ?? null,
        },
      };
      if (dados.tier > 0 || dados.imbu.length || dados.af?.length) return void comExtras.push(dados);
      const junto = limpos.get(entrada.id) ?? { ...dados, count: 0 };
      junto.count += entrada.count;
      limpos.set(entrada.id, junto);
    });
  }

  /*
   * A ordem é pelo nome que a pessoa LÊ, e não pelo do catálogo: as essências
   * têm todas o mesmo nome lá dentro, e ordenar por ele as deixaria embaralhadas
   * entre si. Por `nomeDaOferta` elas saem agrupadas por slot e qualidade, que é
   * como se procura uma.
   */
  const porNome = (a, b) => nomeDaOferta(a).localeCompare(nomeDaOferta(b));
  comExtras.sort(porNome);
  const simples = [...limpos.values()].sort(porNome);

  const back = el('div', 'confirm-back');
  const box = el('div', 'confirm-box largo');
  box.append(el('h3', null, 'O que você quer anunciar?'));

  if (!comExtras.length && !simples.length) {
    box.append(el('p', 'confirm-short', 'Sua mochila está vazia.'));
  } else {
    const botaoDe = (dados) => {
      const botao = el('button', 'balcao-escolha');
      botao.append(arteDaOferta(dados, 32));
      const texto = el('div', 'balcao-item-texto');
      texto.append(el('b', CLASSE_DA_RARIDADE(raridadeDaEssencia(dados) ?? state.items[dados.id]?.rarity), nomeDaOferta(dados)));
      // Os selos vêm da PEÇA: é o que o comprador vai receber, e é o que a
      // pessoa precisa ver ANTES de escolher qual das cópias vai embora.
      if (dados.tier > 0 || dados.imbu.length || dados.af?.length) texto.append(marcasDaPeca(dados));
      botao.append(texto);
      // A peça inteira vai para o balão — sem ela ele responderia pelo id e
      // mostraria o imbuement de outra cópia.
      tipFor(botao, dados.id, null, state.items[dados.id]?.slot ?? null, dados);
      botao.onclick = () => {
        back.remove();
        criarOferta(dados.id, 'sell', dados);
      };
      return botao;
    };

    if (comExtras.length) {
      box.append(
        el('p', 'confirm-short', 'Estas peças têm estrela, tier ou imbuement — cada uma é ela mesma:'),
      );
      const grade = el('div', 'balcao-escolher');
      for (const dados of comExtras) grade.append(botaoDe(dados));
      box.append(grade);
    }
    if (simples.length) {
      if (comExtras.length) box.append(el('p', 'confirm-short', 'E o resto da mochila:'));
      const grade = el('div', 'balcao-escolher');
      for (const dados of simples) grade.append(botaoDe(dados));
      box.append(grade);
    }
  }

  const acoes = el('div', 'confirm-actions');
  const fechar = el('button', 'ghost', 'Fechar');
  fechar.onclick = () => back.remove();
  acoes.append(fechar);
  box.append(acoes);
  back.append(box);
  document.body.append(back);
}

/*
 * ---- Escolher o que PROCURAR ----
 *
 * A irmã do `escolherItemParaVender`, e ela olha para o outro lado: vender sai
 * do que a pessoa TEM à mão, e procurar sai do CATÁLOGO — o que se procura é
 * justamente o que não se tem.
 *
 * Por isso ela é uma busca, e não uma grade: o catálogo tem seis mil itens, e
 * uma grade com seis mil desenhos não é uma escolha, é uma parede. A lista sai
 * do `state.items`, que o cliente já tem, então ela responde a cada tecla sem
 * ida ao servidor — o mesmo arranjo das sugestões da peneira.
 */
function escolherItemParaComprar() {
  const { state } = ctx;

  const back = el('div', 'confirm-back');
  const box = el('div', 'confirm-box largo');
  box.append(el('h3', null, 'O que você está procurando?'));
  box.append(
    el(
      'p',
      'confirm-short',
      'Uma ordem de compra fica no balcão dizendo quanto você paga. O dinheiro fica retido desde já, e volta inteiro se você cancelar.'
    )
  );

  const busca = document.createElement('input');
  busca.className = 'search';
  busca.placeholder = 'buscar item...';
  box.append(busca);

  const grade = el('div', 'balcao-escolher');
  box.append(grade);

  const desenhar = (termo) => {
    grade.innerHTML = '';
    const alvo = termo.trim().toLowerCase();
    if (alvo.length < 2) {
      grade.append(el('p', 'vazio', 'Digite duas letras para procurar.'));
      return;
    }
    // Doze é o que cabe sem virar uma segunda tela; quem quer o resto digita mais.
    const achados = [];
    for (const meta of Object.values(state.items ?? {})) {
      if (!meta?.name || !meta.name.toLowerCase().includes(alvo)) continue;
      achados.push(meta);
      if (achados.length >= 12) break;
    }
    if (!achados.length) {
      grade.append(el('p', 'vazio', 'Nenhum item com esse nome.'));
      return;
    }
    for (const meta of achados) {
      const botao = el('button', 'balcao-escolha');
      botao.append(itemCanvas(meta.id, 32));
      const texto = el('div', 'balcao-item-texto');
      texto.append(el('b', null, meta.name));
      const marcas = [SLOTS_DO_BALCAO[meta.slot], meta.rarity].filter(Boolean).join(' · ');
      if (marcas) texto.append(el('em', null, marcas));
      botao.append(texto);
      tipFor(botao, meta.id);
      botao.onclick = () => {
        back.remove();
        criarOferta(meta.id, 'buy');
      };
      grade.append(botao);
    }
  };

  let timer = null;
  busca.oninput = () => {
    clearTimeout(timer);
    timer = setTimeout(() => desenhar(busca.value), 120);
  };
  desenhar('');

  const acoes = el('div', 'confirm-actions');
  const fechar = el('button', 'ghost', 'Fechar');
  fechar.onclick = () => back.remove();
  acoes.append(fechar);
  box.append(acoes);
  back.append(box);
  fecharAoClicarFora(back, () => back.remove());
  document.body.append(back);
  busca.focus();
}

function criarOferta(id, kind, peca = null) {
  const { state, send } = ctx;
  const vendendo = kind === 'sell';
  /*
   * A moeda começa na prateleira que a pessoa está olhando — quem está na aba
   * de Draevor Coins provavelmente quer anunciar em coin —, mas ela é uma escolha
   * do anúncio e não do filtro: dá para trocar aqui dentro. Ver
   * `MOEDAS_DO_BALCAO`.
   */
  let moedaDoAnuncio = moedaDoBalcao();
  const tenho = tenhoDesse(id);
  if (vendendo && !tenho) return void ctx.notice?.('Você não tem esse item para vender.');

  /*
   * ---- Peça com extra vai UMA por vez ----
   *
   * Duas espadas do mesmo id podem ter tiers diferentes, e uma oferta guarda um
   * conjunto de extras só: anunciar as duas juntas entregaria as duas com o
   * tier da primeira. O servidor já recusa o lote (ver `createOffer`); aqui a
   * caixa nem oferece, e diz por quê.
   */
  const unica = !!peca && (peca.tier > 0 || (peca.imbu ?? []).length > 0);
  const maximo = unica ? 1 : tenho;

  const back = el('div', 'confirm-back');
  const box = el('div', 'confirm-box');
  box.append(el('h3', null, vendendo ? 'Vender no leilão' : 'Criar ordem de compra'));

  const topo = el('div', 'quantia-topo');
  /*
   * A segunda metade do mesmo defeito: a caixa de escolher já desenhava a
   * essência certa e esta, a do preço, voltava a desenhar o buraco. É a última
   * tela antes de o anúncio ir para o ar — se ela mostra a peça errada, a pessoa
   * confirma achando que está vendendo outra coisa.
   *
   * `peca` é a mesma que veio da caixa anterior, e ela traz o slot e a qualidade
   * (ver `escolherItemParaVender`); o `id` sozinho não distingue uma essência
   * mítica de bota de uma comum de arma.
   */
  const daEssencia = peca && Number(peca.id ?? id) === ID_DA_ESSENCIA ? peca : { id, count: 1 };
  topo.append(arteDaOferta(daEssencia, 40));
  const nomeETags = el('div', 'balcao-item-texto');
  nomeETags.append(
    el(
      'b',
      CLASSE_DA_RARIDADE(raridadeDaEssencia(daEssencia) ?? state.items[id]?.rarity),
      nomeDaOferta(daEssencia)
    )
  );
  // O balão sai da PEÇA, e não do id: sem ela ele responderia "comum · sem slot
  // de origem" para toda essência, que foi o que o dono viu.
  tipFor(topo, id, null, state.items[id]?.slot ?? null, peca ?? null);
  // O que ESTA peça é, escrito antes de a pessoa confirmar. Sem isto ela
  // anunciava no escuro: o tier e as horas de imbuement só apareciam depois,
  // na vitrine, quando já não dava para voltar atrás sem pagar a taxa de novo.
  if (peca && (peca.tier > 0 || (peca.imbu ?? []).length)) nomeETags.append(marcasDaPeca(peca));
  topo.append(nomeETags);
  box.append(topo);

  /*
   * ---- Em que moeda este anúncio vai ----
   *
   * Duas fichas, com a figura de cada moeda. Elas ficam ACIMA do preço porque a
   * moeda muda o que o número quer dizer: 50.000 em ouro e 50.000 em coin não
   * são a mesma ordem de grandeza, e escolher a moeda depois de digitar o preço
   * é o caminho para anunciar uma espada por trezentas coins sem querer.
   */
  const escolhaDaMoeda = el('div', 'balcao-moedas na-caixa');
  escolhaDaMoeda.append(el('span', 'balcao-moedas-rotulo', vendendo ? 'receber em' : 'pagar em'));
  const fichas = new Map();
  for (const [qual, moeda] of Object.entries(MOEDAS_DO_BALCAO)) {
    const ficha = el('button', `balcao-moeda-chip ${qual}`);
    ficha.append(moeda.figura());
    ficha.append(el('b', null, moeda.nome));
    ficha.onclick = () => {
      if (moedaDoAnuncio === qual) return;
      moedaDoAnuncio = qual;
      for (const [outro, botao] of fichas) botao.classList.toggle('on', outro === qual);
      // O preço de balcão do item é em OURO: trocar para coin deixando 12.000
      // no campo seria oferecer doze mil Draevor Coins.
      preco?.por(qual === 'coin' ? 1 : state.items[id]?.sell || 1);
      recalcular();
    };
    fichas.set(qual, ficha);
    escolhaDaMoeda.append(ficha);
  }
  fichas.get(moedaDoAnuncio)?.classList.add('on');
  box.append(escolhaDaMoeda);

  const resumo = el('p', 'confirm-short');
  /*
   * `let` e a guarda, e nao `const`.
   *
   * `campoDeNumero` avisa uma vez ao MONTAR, para o total ja sair escrito — e
   * esse primeiro aviso acontece antes de `quantos` receber o retorno. Com
   * `const` isso e um ReferenceError dentro do onclick, e o efeito na tela e o
   * pior possivel: a caixa simplesmente nao abre, sem erro visivel.
   */
  let quantos = null;
  let preco = null;
  const recalcular = () => {
    if (!quantos || !preco) return;
    const total = quantos.ler() * preco.ler();
    const emCoin = moedaDoAnuncio === 'coin';
    if (emCoin) {
      /*
       * A taxa em coin é de 10%, e sai de QUEM RECEBE — no fechamento, não no
       * anúncio. É a mesma conta do servidor (`taxaEmCoin`); esta linha só a
       * escreve na tela, e escreve dos dois lados: quem vende precisa ver
       * quanto sobra, e quem abre uma ordem precisa ver quanto o outro leva,
       * senão o preço anunciado não quer dizer nada.
       */
      const taxa = Math.max(0, Math.min(total - 1, Math.round(total * 0.1)));
      const moedas = (n) => `${money(n)} coin${n === 1 ? '' : 's'}`;
      resumo.textContent = vendendo
        ? `Total ${moedas(total)} — 10% de taxa = você recebe ${moedas(total - taxa)}`
        : `Ficam retid${total === 1 ? 'a' : 'as'} ${moedas(total)} — quem vender recebe ${moedas(total - taxa)} (10% de taxa)`;
      return;
    }
    const taxa = Math.max(20, Math.round(total * 0.02));
    resumo.textContent = vendendo
      ? `Total ${money(total)}g — taxa ${money(taxa)}g = você recebe ${money(Math.max(0, total - taxa))}g`
      : `Total ${money(total)}g + taxa ${money(taxa)}g = você paga ${money(total + taxa)}g`;
  };

  quantos = campoDeNumero({
    rotulo: vendendo ? `Quantos (você tem ${money(tenho)})` : 'Quantos você quer',
    valor: 1,
    min: 1,
    max: vendendo ? maximo : null,
    comMax: vendendo && !unica,
    aoMudar: () => recalcular(),
  });
  preco = campoDeNumero({
    rotulo: 'Preço por unidade',
    valor: moedaDoAnuncio === 'coin' ? 1 : state.items[id]?.sell || 1,
    min: 1,
    aoMudar: () => recalcular(),
  });
  box.append(quantos.wrap, preco.wrap);
  if (unica) {
    quantos.wrap.classList.add('travado');
    box.append(
      el(
        'p',
        'confirm-short',
        'Esta peça vai sozinha: o tier e os imbuements são dela, e vão junto com o tempo que está sobrando agora.'
      )
    );
  }
  recalcular();
  box.append(resumo);

  const acoes = el('div', 'confirm-actions');
  const cancelar = el('button', 'ghost', 'Cancelar');
  cancelar.onclick = () => back.remove();
  const confirmar = el('button', 'primary', vendendo ? 'Pôr à venda' : 'Criar ordem');
  confirmar.onclick = () => {
    back.remove();
    send({
      t: 'market',
      action: 'offer',
      kind,
      id,
      count: quantos.ler(),
      price: preco.ler(),
      // O endereço da peça escolhida. Sem ele o servidor leva a primeira cópia
      // do id — ver `pecaEscolhida`, em store.mjs.
      peca: vendendo ? peca?.alvo ?? null : null,
      moeda: moedaDoAnuncio,
      /*
       * Os filtros vão com a moeda ESCOLHIDA, e não com a que estava na tela:
       * anunciar em coin olhando a prateleira de ouro devolveria a lista de
       * ouro, e o anúncio recém-criado não apareceria em lugar nenhum — que é
       * indistinguível de "não funcionou".
       */
      filtros: { ...filtrosDoBalcao(), moeda: moedaDoAnuncio },
    });
    // E a vitrine passa a mostrar a prateleira em que o anúncio foi parar.
    ctx.tabs.marketMoeda = moedaDoAnuncio;
    ctx.tabs.marketPagina = 1;
    guardarFiltros();
    ctx.redraw?.();
  };
  acoes.append(cancelar, confirmar);
  box.append(acoes);

  back.append(box);
  fecharAoClicarFora(back, () => back.remove());
  // Enter cria a oferta, Escape desiste: a mão sai do campo de quantidade.
  atalhosDaCaixa(back, { confirmar: () => !confirmar.disabled && confirmar.click(), fechar: () => back.remove() });
  document.body.append(back);
  confirmar.focus();
}

// ---------- banco ----------

/*
 * ---- O locker: bau de recompensa e depot ----
 *
 * Abre com o botao direito em cima do locker da cidade (item 3499), que e o
 * mesmo gesto do client do dono. Sao dois compartimentos e eles nao fazem a
 * mesma coisa:
 *
 *   - BAU DE RECOMPENSA: so entra o que cai de boss, e so pelo servidor. Aqui
 *     o jogador retira. Nao tem "guardar" de proposito — nada que ele carrega
 *     deveria poder virar recompensa de boss;
 *   - DEPOT: o armario de sempre, com guardar e tirar nos dois sentidos.
 *
 * O bau vem primeiro porque e o unico dos dois que pode estar com coisa nova
 * esperando: e para ele que a faixa de vitoria manda o jogador olhar.
 */
/*
 * ---- As quatro portas do depósito ----
 *
 * O dono: "a gente separar as aba de recompensa de boss, compartilhado e
 * chegadas ok; lá em depósito na topbar vai ter uma setinha também, e aí
 * embaixo vai ter Baú, que será o depósito padrão, Baú da conta, que será o
 * baú compartilhado da conta, e Chegadas".
 *
 * As três especiais estavam misturadas na parede junto das dezesseis caixas
 * numeradas: quatro naturezas diferentes desenhadas como quadradinhos iguais. O
 * baú de boss tem PRAZO, a Compartilhada é da CONTA inteira e as Chegadas são
 * do que o jogo põe lá sozinho — nenhuma delas é "uma caixa sua numerada", e
 * procurar a certa entre dezenove parecidos era o trabalho.
 *
 * Agora cada uma é uma aba, e a gaveta da barra de cima leva direto a ela.
 */
/*
 * ---- A explicacao sai do corpo e vira um "?" ao lado do X ----
 *
 * "ao lado do x você coloca uma interrogação que aí teria essas informações
 *  sabe... o Baú da Conta também dava pra otimizar o tamanho horizontal? essa
 *  informação você coloca em uma interrogação ao lado do x, e isso você faz em
 *  Chegadas também."
 *
 * O paragrafo dizia a mesma coisa toda vez que a janela abria, e era ele quem
 * mandava na largura dela: uma frase de trinta palavras nao quebra antes de uns
 * 900px, entao a janela tinha de ser larga para caber um texto que, da segunda
 * visita em diante, ninguem le. A grade de itens embaixo tem 440px — o resto
 * era moldura vazia.
 *
 * No "?" a frase continua inteira, a um passar de mouse, e a janela volta a ter
 * a largura do que ela GUARDA. Quem nunca viu a tela acha a explicacao no lugar
 * onde se procura explicacao; quem ja sabe nao paga por ela.
 *
 * O botao mora em `#modal-acoes`, que e a faixa entre o titulo e o X — o mesmo
 * canto que a peneira do mercado e as marcacoes do filtro de loot ja usam.
 */
function ajudaNoCabecalho(texto) {
  const canto = ctx.acoesDoModal?.();
  if (!canto) return;
  const botao = el('button', 'ajuda-do-modal', '?');
  botao.type = 'button';
  botao.setAttribute('aria-label', 'O que e esta tela');
  tipTexto(botao, texto);
  canto.append(botao);
}

export const ABAS_DO_DEPOSITO = {
  deposito: 'Baú',
  recompensa: 'Baú de Boss',
  conta: 'Baú da Conta',
  chegadas: 'Chegadas',
};

export function openLocker(aba) {
  if (aba) ctx.tabs.deposito = aba;
  ctx.tabs.deposito ??= 'deposito';
  /*
   * ---- O título é o da SEÇÃO, e a janela não tem mais abas ----
   *
   * "você vai separar as abas do depósito porque agora já temos botões próprios
   *  pra elas."
   *
   * Ele tem razão e é a mesma conta que dividiu a janela de Tarefas: a barra de
   * abas existia para escolher entre quatro coisas, e a gaveta da barra de cima
   * passou a fazer essa escolha ANTES de a janela abrir. Mantendo as duas, todo
   * clique na gaveta abria uma janela que oferecia de novo as outras três — e a
   * pessoa tinha de reparar em qual aba estava acesa para saber onde caiu.
   *
   * O título passa a responder isso sozinho: "Baú da Conta" na barra do topo da
   * janela não deixa dúvida de onde ela está.
   */
  const titulo = ABAS_DO_DEPOSITO[ctx.tabs.deposito] ?? 'Depósito';
  /*
   * `solto`: o fundo do modal deixa o ponteiro passar, e o resto do jogo
   * continua vivo atras dele. E' o que permite arrastar da mochila para a
   * caixa — com o fundo normal a mochila ficava inalcancavel enquanto o
   * deposito estivesse aberto.
   */
  /*
   * ---- E cada seção tem a LARGURA do que ela guarda ----
   *
   * "o Baú da Conta também dava pra otimizar o tamanho horizontal sabe?"
   *
   * As quatro nasceram como abas de uma janela só, então herdaram a largura da
   * maior — 980px, que é o que o Baú precisa para pôr a parede de dezesseis à
   * esquerda e a caixa aberta à direita. Separadas, as outras três passaram a
   * pagar por um espaço que não usam: a grade do Baú da Conta tem 485px de
   * largura fixa, e os outros 400 eram moldura.
   *
   * Três medidas, uma por formato:
   *   Baú          — 980, a parede mais o conteúdo lado a lado;
   *   Baú de Boss  — 700, as sacolas numa coluna estreita e o que há dentro na
   *                  outra. Estreita de propósito: "deixa mais vertical, mais ou
   *                  menos igual da Baú do char";
   *   Conta/Chegadas — 620, que é a grade de itens e o respiro dela.
   *
   * O `solto` continua em todas: é ele que deixa o ponteiro passar pelo fundo,
   * e sem ele não há como arrastar da mochila para a caixa.
   */
  const molde =
    ctx.tabs.deposito === 'deposito'
      ? 'solto'
      : ctx.tabs.deposito === 'recompensa'
        ? 'solto deposito-boss'
        : 'solto deposito-estreito';
  ctx.openModal(titulo, (body) => {
    const draw = () => {
      body.innerHTML = '';
      renderLocker(body);
    };
    ctx.redraw = draw;
    draw();
  }, null, molde);
}

/*
 * Qual caixa esta aberta — guardado FORA da funcao de desenho.
 *
 * `renderLocker` e refeita a cada `pushState` (o ouro e o peso mudam a cada
 * segundo), e um estado dentro dela voltaria para a caixa 1 sozinho enquanto o
 * jogador estivesse olhando a caixa 7.
 */
let caixaAberta = null;
/*
 * Qual sacola do bau esta ABERTA para olhar — e nao para levar.
 *
 * O clique esquerdo despeja na mochila, que e o gesto de sempre. O dono pediu
 * o outro: ver o que tem dentro ANTES de decidir. E' botao direito, como o
 * "abrir" de qualquer container no client dele.
 */
let sacolaAberta = null;

/*
 * Qual caixa do deposito esta aberta AGORA, para quem esta fora deste arquivo.
 *
 * A mochila e' outra janela e outro modulo, e o clique nela precisa saber se ha
 * uma caixa esperando item. Ligada no `panelCtx` (main.mjs) como
 * `caixaDoDepositoAberta`.
 *
 * ---- Por que ela olha o `hidden` ANTES de procurar a grade ----
 *
 * O dono: "quando eu tou com as caixas do deposito FECHADA e clico pra equipar
 * o item, ta mandando pro deposito e nao equipando".
 *
 * Ela perguntava so' se a grade existia no documento. Mas `closeModal` nao
 * esvazia o `#modal-body` — ele so' poe `hidden = true` e deixa o conteudo la'
 * (quem limpa e' o `openModal` seguinte, ao montar outra tela). Entao, depois de
 * abrir o deposito UMA vez e fechar, a grade continuava no documento e esta
 * funcao continuava respondendo "a caixa 7 esta aberta" — para sempre. Todo
 * clique na mochila guardava em vez de vestir, ate' o jogador abrir outro painel
 * por acaso.
 *
 * `hidden` e' a MESMA marca que o `closeModal` liga, entao ela responde certo
 * para todas as formas de fechar: o X, o Esc e o clique fora.
 */
export const caixaDoDepositoAberta = () => {
  const modal = document.getElementById('modal');
  if (!modal || modal.hidden) return null;
  return modal.querySelector('.deposito-alvo') ? caixaAberta : null;
};

/** Quantos itens a tela mostra de uma vez. O resto vai para as paginas. */
/*
 * ---- A caixa aberta é um QUADRADO de slots, e não uma fileira ----
 *
 * O dono: "as caixa do depósito, cada uma que fosse aberta, os slots não
 * fossem linha única na horizontal, fosse um quadrado com os slots mesmo".
 *
 * A grade já quebrava linha sozinha (`auto-fill`), e era justamente esse o
 * problema: com seis itens guardados ela desenhava SEIS quadradinhos numa
 * fileira só, e a caixa não parecia uma caixa. No client dele o depot chest
 * é uma grade fixa, com as vagas vazias à mostra — é o vazio que diz quanto
 * ainda cabe.
 *
 * ---- E são as CEM vagas, não vinte e cinco ----
 *
 * A primeira versão paginava de 25 em 25, e o dono foi direto ao ponto: "tá
 * mostrando só 25 slots em vez de 100". A paginação era herança de quando a
 * grade só desenhava o que estava guardado; com as vagas vazias à mostra, ela
 * passou a esconder justamente o que a grade existe para mostrar — quanto ainda
 * cabe. Uma caixa de cem com quatro páginas de vinte e cinco não é uma caixa.
 *
 * Dez colunas: cem vagas viram dez por dez, o quadrado de verdade. E a
 * compartilhada, que começa com vinte, sai duas fileiras de dez — o mesmo
 * desenho, mais baixo.
 */
const COLUNAS_DA_CAIXA = 10;

/*
 * "expira em 6 dias", "expira em 4 horas", "expira em 12 minutos".
 *
 * Dias enquanto houver dias; abaixo disso a hora e' o que importa, e na ultima
 * hora o minuto — e' quando a frase deixa de ser informacao e vira aviso.
 */
/*
 * Quanto falta para a sacola de boss vencer.
 *
 * O servidor manda o INSTANTE (`venceEm`) e não a contagem, porque a contagem
 * mudava a cada milissegundo e arrastava a lista inteira de sacolas — com todos
 * os itens de todos os bosses do dia — pelo fio oito vezes por segundo. Ver
 * `rewardsView`, em systems.mjs, e `contarOsPrazos`, em main.mjs.
 */
const prazoDaSacola = (sacola) => Math.max(0, (sacola?.venceEm ?? 0) - Date.now());

function quantoFalta(ms) {
  const minutos = Math.max(0, Math.round(ms / 60000));
  if (minutos >= 48 * 60) return `${Math.floor(minutos / (24 * 60))} dias`;
  if (minutos >= 24 * 60) return '1 dia';
  if (minutos >= 120) return `${Math.floor(minutos / 60)} horas`;
  if (minutos >= 60) return '1 hora';
  return `${minutos} minutos`;
}

/*
 * `depot box I` no items.xml dele. As dezesseis caixas sao ids seguidos, e cada
 * sprite ja traz o numero romano pintado — o mesmo desenho do Depot Chest do
 * client.
 */
const PRIMEIRA_CAIXA_DO_DEPOSITO = 22797;
/*
 * A caixa das Chegadas não é uma depot box: ela é o PACOTE (item 3503), que no
 * client dele é o que chega pelo correio. A figura diferente é metade do
 * trabalho — quem abre o depósito precisa distinguir "as minhas dezesseis" de
 * "onde o jogo põe o que chegou" sem ler nada. Ver `CAIXA_DE_CHEGADAS`.
 */
const ITEM_DAS_CHEGADAS = 3503;
/*
 * A caixa COMPARTILHADA da conta usa a parcel carimbada (3504), e não a
 * parcel comum das Chegadas (3503): as duas precisam se distinguir de relance
 * na parede, e a encomenda é justamente a figura que o Appa usou para pedir a
 * caixa — "alguma forma de transferir itens tipo um PARCEL".
 */
/*
 * A caixa COMPARTILHADA é da CONTA, e o desenho dela é o mesmo do botão Party
 * da barra de cima — pedido do dono. É a figura certa: as duas coisas querem
 * dizer "isto não é só deste personagem".
 *
 * Vem de `assets/ui` e não do catálogo de itens, então é uma `<img>` e não um
 * `itemCanvas` — ver `arteDaCaixa`.
 */
const ARTE_DO_COFRE = 'ui:tb-party';
/* O baú de boss usa o reward chest do client dele (19250). */
const ITEM_DA_RECOMPENSA = 19250;
/* O endereço da caixa do baú de boss: ela não é do armário, então não tem índice. */
const CAIXA_DA_RECOMPENSA = 'recompensa';

/*
 * As quatro abas do depósito acharam a arte delas sozinhas.
 *
 * Havia aqui um mapa de desvios: cada aba emprestava o desenho que já
 * representava aquilo em outro lugar — o armário genérico, o baú das
 * recompensas de level, o prédio do banco. Os quatro desenhos próprios
 * chegaram (`aba-deposito`, `aba-recompensa`, `aba-conta`, `aba-chegadas`), e
 * `tabBar` acha cada um pelo id sem precisar de tabela nenhuma. Ver
 * `tools/prompt-icones-deposito.txt`.
 */

/**
 * O desenho de uma caixa da parede.
 *
 * Quase todas são um item do catálogo; a Compartilhada é arte da interface. Uma
 * função só porque o mesmo desenho aparece na parede e no topo da caixa aberta.
 */
function arteDaCaixa(caixa, size = 32) {
  if (caixa.arte?.startsWith('ui:')) {
    const img = document.createElement('img');
    img.src = `/client/assets/ui/${caixa.arte.slice(3)}.png`;
    img.alt = '';
    img.width = size;
    img.height = size;
    img.className = 'deposito-caixa-arte';
    return img;
  }
  return itemCanvas(caixa.itemArte, size);
}

/*
 * ---- O baú de boss é uma CAIXA, e não um bloco solto no alto ----
 *
 * O dono: "em vez do baú de recompensa do boss ser ali em cima avulso no modal,
 * faz uma caixa só pra ele; e retire de aparecer o baú de recompensa quando eu
 * tiver nas caixas de depósito e chegadas e compartilhada".
 *
 * Ele estava certo e o defeito era de arrumação: o baú ficava desenhado em cima
 * de TUDO — da parede de caixas e de qualquer caixa aberta —, então metade da
 * janela era sempre uma coisa que você não estava olhando. Com trinta sacolas de
 * boss, a caixa que você abriu ficava abaixo da dobra.
 *
 * Agora ele é a primeira caixa da parede e só aparece quando é ele o aberto.
 */
function bauDeRecompensa(body, voltar) {
  const { state, send } = ctx;
  const character = state.character;
  const rewards = character.rewards ?? [];

  /*
   * ---- O Baú de Boss, igual ao Baú ----
   *
   * "faz igual o Baú de Boss lá, igual do Baú: por exemplo vai ter sacola de
   *  boss e ao clicar aparece sabe? E um botão coletar e etc."
   *
   * As duas telas passam a ter o mesmo desenho: à esquerda o que se escolhe (os
   * dezesseis armários lá, as sacolas aqui), à direita o que está dentro do
   * escolhido. A diferença some, e com ela some a necessidade de aprender duas
   * telas.
   *
   * ---- E o clique esquerdo passou a ESCOLHER ----
   *
   * Ele despejava a sacola na Boss Pouch na hora. Numa grade de trinta sacolas
   * iguais, isso quer dizer que errar o alvo esvazia a sacola errada — e não há
   * como desfazer. Agora o clique mostra, e quem despeja é o "Coletar", que tem
   * nome e está do lado do que ele vai levar.
   *
   * O botão direito continua valendo: quem já tinha o dedo nele não perde nada.
   */
  const topo = el('div', 'locker-topo');
  topo.append(voltar);
  if (rewards.length) {
    // `primary` e' a mesma pintura dos outros botoes de acao do jogo. Sem classe
    // nenhuma ele saia com o cinza-claro de fabrica do navegador.
    const tudo = el('button', 'primary', 'Pegar tudo');
    /*
     * O destino é a BOSS POUCH, e não a mochila. Ver `abrirSacola`, no
     * servidor: as três portas do baú — esta, o "Levar tudo" de uma sacola e o
     * clique num item — desembocam lá desde o dia em que ela existe.
     */
    tipTexto(tudo, 'Leva tudo o que está no baú para a Boss Pouch, respeitando a capacidade e as mil vagas dela.');
    tudo.onclick = () => send({ t: 'reward', action: 'takeAll' });
    topo.append(tudo);

    /*
     * ---- E vender o que o NPC compra, sem passar pela mochila ----
     *
     * "poderia ter um jeito de vender os drops de boss mais rapido... ao lado de
     * pegar tudo coloca um botao vender tudo que npc compra".
     *
     * Ao lado do "Pegar tudo" porque e a mesma pergunta com duas respostas: o
     * que fazer com o bau. Antes a unica resposta era pegar — e pegar trinta
     * sacolas nao cabe numa mochila, entao o jeito era um vaivem de pegar e
     * vender. Ver `openVenderSacolas`.
     */
    const vender = el('button', 'ghost', 'Vender ao NPC');
    vender.title = 'ver tudo o que o NPC compra nas sacolas, quanto rende, e vender de uma vez';
    vender.onclick = () => openVenderSacolas();
    topo.append(vender);

    /*
     * ---- E o irmão dele: limpar todas de uma vez ----
     *
     * "eu faço todos os boss todo dia, coloca um botão pra limpar TODAS AS BAGS
     *  DE BOSS. tenho q limpar 30 bag uma a uma."
     *
     * O número dele é o argumento: quem roda a rotação inteira volta com trinta
     * sacolas, e a limpeza era de uma em uma, com uma confirmação em cada. Só
     * aparece com duas ou mais — com uma sacola só, o botão dela já resolve, e
     * dois botões para a mesma coisa é um a mais.
     */
    if (rewards.length > 1) {
      const limpar = el('button', 'ghost', `Limpar todas (${rewards.length})`);
      limpar.onclick = () => abrirLimparTodas(rewards);
      topo.append(limpar);
    }
  }
  body.append(topo);

  ajudaNoCabecalho(
    'O que cai de boss vem para aqui em vez da bolsa de loot — a bolsa é vendida sozinha a cada 30 segundos, e ' +
      'o drop de um boss não pode ir junto. Uma sacola por boss derrotado, e cada uma tem prazo: o que passar do ' +
      'prazo some. Clique numa sacola para ver o que tem dentro, num item para levar só ele, ou em Coletar para ' +
      'levar a sacola inteira para a Boss Pouch.'
  );

  if (!rewards.length) {
    body.append(el('p', 'vazio', 'O baú está vazio. Derrote um boss para enchê-lo.'));
  } else {
    /*
     * Uma SACOLA por boss morto, enfileiradas — como o reward chest do servidor
     * dele. O balao diz de quem veio e quanto falta para vencer; clicar despeja
     * na mochila.
     */
    /*
     * Uma sacola sempre escolhida: a coluna da direita não fica vazia à toa, e
     * a primeira é a mais recente que o jogador veio ver.
     */
    if (!rewards.some((sacola) => sacola.indice === sacolaAberta)) sacolaAberta = rewards[0].indice;

    const dois = el('div', 'deposito-dois');
    const esquerda = el('section', 'deposito-lado');
    esquerda.append(
      /* "boss" já termina em s: o plural do português cai no que vem antes. */
      el('h4', 'deposito-titulo', `Sacolas de boss — ${rewards.length}`)
    );
    const direita = el('section', 'deposito-lado deposito-conteudo');

    const grade = el('div', 'locker-grade');
    for (const sacola of rewards) {
      const cela = el('div', `cell sacola${sacolaAberta === sacola.indice ? ' aberta' : ''}`);
      cela.append(itemCanvas(sacola.item, 30));
      cela.append(el('b', null, String(sacola.itens.length)));
      /*
       * O balao mostra o QUE tem dentro, e nao quantos tipos.
       *
       * "4 tipo(s) de item" e' a informacao menos util possivel sobre uma sacola
       * de boss: quem passa o mouse quer saber se vale a pena carregar aquilo
       * agora. Com os desenhos e as quantidades, a resposta esta no balao — sem
       * abrir, sem clicar, sem tirar da sacola.
       */
      tipPanel(cela, () => {
        const caixa = el('div', 'tip-sacola');
        caixa.append(el('div', 'tip-bless-head', `Loot do boss ${sacola.boss}`));
        caixa.append(el('div', 'tip-sacola-prazo', `Expira em ${quantoFalta(prazoDaSacola(sacola))}`));
        const lista = el('div', 'tip-sacola-itens');
        for (const entry of sacola.itens) {
          const linha = el('div', 'tip-sacola-item');
          linha.append(itemCanvas(entry.id, 24, entry.count));
          linha.append(el('span', null, state.items?.[entry.id]?.name ?? `item ${entry.id}`));
          // E as estrelas na prévia sem abrir: é ela que decide se vale abrir.
          const naLinha = estrelasDosAfixos(entry.af);
          if (naLinha.length) linha.append(seloDeEstrelas('item-estrelas', naLinha));
          if (entry.count > 1) linha.append(el('b', null, `x${entry.count}`));
          lista.append(linha);
        }
        if (!sacola.itens.length) lista.append(el('span', 'vazio', 'vazia'));
        caixa.append(lista);
        caixa.append(el('div', 'tip-sacola-dica', 'Clique para ver o que tem dentro'));
        return caixa;
      });
      cela.onclick = () => {
        sacolaAberta = sacola.indice;
        ctx.redraw?.();
      };
      /*
       * Botao direito ABRE, como qualquer container no client dele: mostra o
       * conteudo aqui embaixo em vez de despejar na mochila. Sem isto so' dava
       * para saber o que veio de um boss depois de ja ter pegado.
       */
      cela.oncontextmenu = (evento) => {
        evento.preventDefault();
        sacolaAberta = sacolaAberta === sacola.indice ? null : sacola.indice;
        ctx.redraw?.();
      };
      grade.append(cela);
    }
    esquerda.append(grade);
    esquerda.append(
      el(
        'p',
        'deposito-limite',
        'Uma sacola por boss derrotado, e cada uma tem prazo. Clique para ver; o que passar do prazo some.'
      )
    );

    const olhando = rewards.find((sacola) => sacola.indice === sacolaAberta);
    if (olhando) direita.append(dentroDaSacola(olhando));

    dois.append(esquerda, direita);
    body.append(dois);
  }
}

function renderLocker(body) {
  /*
   * `send` entra aqui, e ele já faltou uma vez.
   *
   * Quando o baú de boss saiu daqui para a função dele, o `send` foi junto na
   * desestruturação e esta ficou só com o `state` — e TODO clique de dentro do
   * depósito passou a estourar um ReferenceError: tirar item, guardar, mover
   * tudo, renomear, comprar vaga. A tela desenhava perfeita e não fazia nada,
   * que é o pior jeito de quebrar: não há o que ver.
   */
  const { state, send } = ctx;
  const character = state.character;
  const rewards = character.rewards ?? [];
  const armario = character.deposito ?? [];

  /*
   * O "‹ Todas as caixas" saiu: a parede não sai mais da tela.
   *
   * Ela e a caixa aberta agora dividem a janela (ver `deposito-dois`), e um
   * botão que volta para uma coisa que está à vista é um botão que não faz
   * nada. O baú de boss ainda recebe um `<span>` vazio no lugar dele — é a
   * assinatura de `bauDeRecompensa`, que nasceu quando havia para onde voltar.
   */

  /*
   * ---- A aba manda, e `caixaAberta` obedece ----
   *
   * `caixaAberta` continua sendo quem diz o que desenhar — é dele que a mochila
   * pergunta para onde soltar um item (ver `caixaDoDepositoAberta`), e mexer
   * nisso quebraria o arrasto. O que a aba faz é ESCOLHER o valor dele antes do
   * desenho: a Compartilhada e as Chegadas têm índice de verdade no armário, e
   * o baú de boss usa a chave própria dele.
   *
   * A aba "Baú" é a única em que `caixaAberta` continua livre: lá dentro o
   * jogador abre e fecha as dezesseis, e o "‹ Todas as caixas" é o que volta.
   */
  const aba = ctx.tabs.deposito ?? 'deposito';
  const daConta = armario.find((caixa) => caixa.compartilhada) ?? null;
  const asChegadas = armario.find((caixa) => caixa.chegadas) ?? null;

  if (aba === 'recompensa') caixaAberta = CAIXA_DA_RECOMPENSA;
  else if (aba === 'conta') caixaAberta = daConta?.indice ?? null;
  else if (aba === 'chegadas') caixaAberta = asChegadas?.indice ?? null;
  else if (caixaAberta === CAIXA_DA_RECOMPENSA) caixaAberta = null;
  else if (caixaAberta != null && (caixaAberta === daConta?.indice || caixaAberta === asChegadas?.indice)) {
    // Veio de outra aba com uma especial aberta: a aba "Baú" não a mostra.
    caixaAberta = null;
  }

  /*
   * ---- Na aba Baú há SEMPRE uma caixa aberta ----
   *
   * Era "parede OU caixa": a grade de dezesseis ocupava a janela inteira, e
   * clicar numa trocava a tela toda por ela. O dono mandou a foto do depósito do
   * client dele, que resolve isso do jeito certo — as duas ao mesmo tempo, a
   * parede à esquerda e o conteúdo à direita. Trocar de caixa passa a ser um
   * clique que muda metade da tela, e não a tela.
   *
   * Com as duas à vista, não existe mais o estado "nenhuma aberta": ele
   * deixaria a metade direita vazia sem motivo. A primeira numerada é o padrão.
   */
  const numeradas = armario.filter((caixa) => !caixa.compartilhada && !caixa.chegadas);
  if (aba === 'deposito' && caixaAberta == null) caixaAberta = numeradas[0]?.indice ?? null;

  /*
   * A barra de abas saiu daqui: quem escolhe é a gaveta do Depósito, na barra
   * de cima, e o título da janela diz onde a pessoa caiu. Ver `openLocker`.
   *
   * O aviso de sacola esperando não se perdeu com ela — ele mora no botão
   * "Recompensa de Boss" da gaveta (`alerta`, em `DO_DEPOSITO`), que é onde a
   * pessoa está olhando quando ainda não abriu nada.
   */

  /*
   * O baú de boss, sem o "‹ Todas as caixas": ele é a janela inteira agora, e
   * não há para onde voltar dentro dela.
   */
  if (aba === 'recompensa') return bauDeRecompensa(body, el('span'));

  if (aba !== 'deposito' && caixaAberta == null) {
    return void body.append(
      el('p', 'empty', aba === 'conta' ? 'Esta conta ainda não tem o baú compartilhado.' : 'Não há caixa de Chegadas.')
    );
  }

  if (aba === 'deposito') {
    /*
     * ---- As duas colunas ----
     *
     * À esquerda a parede de baús, à direita o que está dentro do escolhido —
     * o desenho do depósito do client, que o dono mandou de referência.
     *
     * `body` é TROCADO pela coluna da direita no fim deste bloco. É um truque,
     * e é o menor: todo o resto da função (o cabeçalho da caixa, a grade, o
     * arrasto, o rodapé de vagas) já escreve em `body`, e mover cem linhas para
     * dentro de um `if` só para mudar onde elas caem seria reescrever o que
     * funciona para não mudar nada.
     */
    /*
     * ---- Duas fileiras: as ESPECIAIS em cima, as dezesseis embaixo ----
     *
     * O dono: "centralize o Recompensa de Boss em cima, Compartilhada e Chegadas,
     * e aí embaixo começa as caixa".
     *
     * As três de cima são de naturezas diferentes das dezesseis: o baú de boss tem
     * PRAZO, a Compartilhada é da conta inteira e as Chegadas são do que o jogo põe
     * lá sozinho. Nenhuma delas é "uma caixa sua numerada", e enfileirá-las junto
     * das outras fazia procurar entre dezenove quadradinhos parecidos.
     *
     * Centralizadas porque são três: encostadas à esquerda, uma fileira de três
     * embaixo de uma grade larga lê como uma grade que quebrou.
     *
     * A ordem é só de DESENHO: `caixa.indice` continua sendo a posição real no
     * armário, que é o endereço que volta no clique e no comando. Reordenar o
     * array de verdade trocaria o conteúdo das caixas de lugar.
     */
    /*
     * As três especiais saíram daqui: viraram abas (ver `ABAS_DO_DEPOSITO`).
     * A parede voltou a ser o que o nome dela diz — as caixas numeradas do
     * personagem, todas da mesma natureza, todas do mesmo tamanho.
     */
    const numeradas = armario.filter((caixa) => !caixa.compartilhada && !caixa.chegadas);

    const dois = el('div', 'deposito-dois');
    const esquerda = el('section', 'deposito-lado');
    esquerda.append(el('h4', null, 'Seus baús'));
    const direita = el('section', 'deposito-lado deposito-conteudo');

    const paredeDasCaixas = el('div', 'deposito-parede');
    for (const caixa of numeradas) {
      const alvo = paredeDasCaixas;
      const botao = el(
        'button',
        `deposito-caixa${caixa.tipos ? ' cheia' : ''}${caixa.chegadas ? ' chegadas' : ''}` +
          `${caixa.compartilhada ? ' compartilhada' : ''}${caixa.recompensa ? ' recompensa' : ''}`
      );
      if (caixa.recompensa) {
        tipTexto(
          botao,
          'Uma sacola por boss derrotado. O que cai de boss vem para cá em vez da bolsa de loot, ' +
            'que é vendida sozinha — e cada sacola tem prazo para ser recolhida.'
        );
      }
      if (caixa.chegadas) {
        tipTexto(
          botao,
          'Aqui chega o que você comprou na loja ou no mercado, o que veio pelo correio e o que saiu de um saco ' +
            'quando não havia espaço na mochila. Nada é guardado aqui à mão, e nada daqui é vendido sozinho.'
        );
      }
      if (caixa.compartilhada) {
        tipTexto(
          botao,
          'Esta caixa é da CONTA, e não deste personagem: o que você guardar aqui aparece em todos os seus ' +
            'personagens. É por ela que se passa uma peça de um para o outro sem precisar dos dois online.'
        );
      }
      /*
       * O desenho e' o item de VERDADE do servidor dele: `depot box I` e' o
       * 22797, e os dezesseis seguem em ordem ate o XVI. Antes era um retangulo
       * com o nome escrito — o numero romano ja esta pintado no proprio sprite,
       * que e' como ele reconhece a caixa no client.
       */
      botao.append(
        arteDaCaixa(
          {
            arte: caixa.compartilhada ? ARTE_DO_COFRE : null,
            itemArte: caixa.recompensa
              ? ITEM_DA_RECOMPENSA
              : caixa.chegadas
                ? ITEM_DAS_CHEGADAS
                : PRIMEIRA_CAIXA_DO_DEPOSITO + caixa.indice,
          },
          32
        )
      );
      botao.append(el('b', null, caixa.nome));
      /*
       * O baú de boss conta SACOLAS, e não tipos com teto: "3/3" ali seria um
       * limite que ele não tem.
       */
      botao.append(
        el(
          'span',
          null,
          caixa.recompensa
            ? caixa.tipos
              ? `${caixa.tipos} sacola${caixa.tipos > 1 ? 's' : ''}`
              : 'vazio'
            : caixa.tipos
              ? `${caixa.tipos}/${caixa.teto}`
              : 'vazia'
        )
      );
      /* A que está sendo mostrada à direita fica marcada na parede. */
      if (caixa.indice === caixaAberta) botao.classList.add('aberta');
      botao.onclick = () => {
        caixaAberta = caixa.indice;
        ctx.redraw?.();
      };
      alvo.append(botao);
    }
    esquerda.append(paredeDasCaixas);
    esquerda.append(
      el(
        'p',
        'deposito-limite',
        `${numeradas.length} baús · ${armario[0]?.teto ?? 100} tipos em cada. O Baú de Boss, as Chegadas e o ` +
          'Baú da Conta abrem pelo Depósito da barra de cima.'
      )
    );

    dois.append(esquerda, direita);
    body.append(dois);
    // Daqui para baixo, escrever em `body` é escrever na coluna da direita.
    body = direita;
  }

  if (caixaAberta == null) {
    return void body.append(el('p', 'empty', 'Este personagem ainda não tem caixas no depósito.'));
  }

  // ---- uma caixa aberta ----
  // O botao de voltar e' montado la em cima: o bau de boss usa o mesmo.
  const caixa = armario[caixaAberta] ?? armario[0];
  const linha = el('div', 'locker-topo');
  /* O `voltar` não existe mais: a parede fica à vista o tempo todo. */

  /*
   * A caixa das Chegadas não se renomeia e não recebe nada a mão: o nome dela é
   * o que diz o que ela é, e guardar coisas ali dentro a encheria justamente
   * para o que ela existe. O servidor recusa as duas coisas (ver `toDepot`);
   * aqui os botões nem aparecem, que é melhor do que um botão que dá erro.
   */
  /*
   * E a Compartilhada também não se renomeia: o nome dela é o que diz que ela
   * é de todos os personagens da conta, e um deles rebatizando-a mudaria a
   * caixa dos outros quatro.
   */
  if (!caixa.chegadas && !caixa.compartilhada) {
    const renomear = el('button', 'ghost', 'Renomear');
    renomear.onclick = () => perguntarNomeDaCaixa(caixa);
    linha.append(renomear);
  }

  /*
   * ---- "Mover tudo": a mochila inteira para esta caixa ----
   *
   * "colocar um botao no DP para mover ALL ITENS" — e ele mora DENTRO da caixa
   * aberta, porque é ela o destino. Um botão na parede de caixas teria de
   * escolher uma sozinho, e escolher errado é despejar trinta itens no armário
   * de outra pessoa dentro da sua própria cabeça.
   *
   * ---- Quantos cabem, dito ANTES do clique ----
   *
   * A conta é a mesma do servidor (ver `guardarMochilaNaCaixa`): pilha comum sem
   * extras que já está lá não gasta vaga; qualquer outra peça gasta uma. Ela é
   * repetida aqui só para o botão poder AVISAR — o servidor continua sendo quem
   * decide, e o que a tela diz é uma previsão, não a regra.
   *
   * Sem o aviso o jogador clicaria, veria a mochila esvaziar pela metade e
   * teria de ler a notificação para descobrir por quê. Com ele, a pergunta
   * "cabe?" é respondida no lugar em que ela é feita.
   */
  /*
   * Uma peça "com extras" é a que não pode ser empilhada com outra do mesmo id:
   * tier, imbuement ou afixo. É a mesma pergunta que `extrasDaPeca` faz no
   * servidor — e ela precisa concordar, senão a previsão do botão mente.
   */
  const temExtras = (peca) => !!(peca?.tier || peca?.imbu?.length || peca?.af?.length);
  const naMochila = character.inventory ?? [];
  if (naMochila.length && !caixa.chegadas) {
    const jaLa = new Set((caixa.itens ?? []).filter((e) => !temExtras(e)).map((e) => e.id));
    let vagas = (caixa.teto ?? 100) - (caixa.tipos ?? 0);
    let cabem = 0;
    for (const peca of naMochila) {
      const empilha = state.items?.[peca.id]?.stackable && !temExtras(peca) && jaLa.has(peca.id);
      if (empilha) {
        cabem++;
        continue;
      }
      if (vagas <= 0) continue;
      vagas--;
      jaLa.add(peca.id);
      cabem++;
    }

    const tudo = el('button', cabem ? 'primary' : 'ghost', 'Mover tudo');
    tudo.disabled = !cabem;
    tipTexto(
      tudo,
      cabem >= naMochila.length
        ? `Guarda os ${naMochila.length} itens da mochila em ${caixa.nome}.`
        : cabem
          ? `Cabem ${cabem} dos ${naMochila.length} itens da mochila — ${caixa.nome} enche antes do resto.`
          : `${caixa.nome} está cheia: nada da mochila cabe aqui.`,
    );
    tudo.onclick = () => send({ t: 'depot', action: 'storeAll', caixa: caixa.indice });
    linha.append(tudo);
  }

  /*
   * ---- O botãozinho de organizar, um POR CAIXA ----
   *
   * "cada um teria seu próprio botãozinho pequeno de organizar."
   *
   * Um por caixa, e não um que arruma o armário inteiro: quem abriu a Caixa VII
   * quer arrumar a Caixa VII, e um botão que mexesse nas dezessete de uma vez
   * seria impossível de desfazer.
   *
   * Vale para as Chegadas e para a Compartilhada também. A primeira é a que mais
   * embaralha (é onde tudo cai sem ordem nenhuma), e a segunda ficaria sendo a
   * única caixa da tela sem o botão — o que pareceria defeito, e não regra.
   *
   * A seta dupla é a mesma da mochila e da Boss Pouch, de propósito: é o mesmo
   * gesto em quatro lugares, e não quatro botões parecidos.
   */
  const organizar = el('button', 'ghost deposito-organizar', '⇅');
  organizar.disabled = (caixa.itens ?? []).length < 2;
  tipTexto(
    organizar,
    organizar.disabled
      ? `Não há o que organizar em ${caixa.nome}.`
      : `Põe ${caixa.nome} em ordem de nome. Não junta pilhas, não vende e não joga nada fora.`
  );
  organizar.onclick = () => pedirParaOrganizar(`depot:${caixa.indice}`);
  linha.append(organizar);

  /*
   * O nome da caixa vem ANTES dos botões, e é o cabeçalho do painel.
   *
   * Na foto do client cada metade tem um título no topo — "DEPOT CHESTS" de um
   * lado, "DEPOT I" do outro. Com o nome embaixo da fileira de ações, a coluna
   * da direita começava por três botões e só depois dizia de qual caixa eles
   * eram.
   */
  body.append(el('h4', 'deposito-titulo', `${caixa.nome} — ${caixa.tipos}/${caixa.teto} tipos`));
  body.append(linha);
  /*
   * As duas explicacoes subiram para o "?" do cabecalho (ver `ajudaNoCabecalho`).
   * O "sem conta" continua no corpo: ele nao explica a tela, ele explica por que
   * ela esta VAZIA — e isso ninguem vai procurar debaixo de um simbolo.
   */
  if (caixa.chegadas) {
    ajudaNoCabecalho(
      'O que você comprou na loja ou no mercado, o que chegou pelo correio e o que saiu de um saco espera aqui ' +
        'quando não cabe na mochila. Clique para levar — e nada daqui vai para a bolsa de loot, então a venda ' +
        'automática nunca leva o que está guardado aqui. Esta caixa não recebe nada à mão e não se renomeia.'
    );
  }
  if (caixa.compartilhada) {
    if (caixa.semConta) {
      body.append(
        el('p', 'shop-note', 'Este personagem não está ligado a uma conta, então não há caixa compartilhada para ele.')
      );
    } else {
      ajudaNoCabecalho(
        'Esta caixa é a MESMA em todos os personagens desta conta. Guarde aqui com um, entre com o outro e ' +
          'pegue — sem precisar dos dois online. Ela guarda o tier, os imbuements e os afixos da peça, como ' +
          'qualquer caixa do depósito. O nome dela não muda: ele é o que diz que ela é de todos.'
      );
    }
  }

  const itens = caixa.itens ?? [];
  /*
   * Tudo de uma vez: `inicio` fica em zero e existe só porque a POSIÇÃO da peça
   * viaja no clique (ver o `pos` mais abaixo, que é o que conserta o "clico no
   * último, tira o primeiro").
   */
  const inicio = 0;
  const naTela = itens;

  /*
   * A area de largar e' a grade INTEIRA, e nao cada celula: soltar em cima de
   * um item para guardar OUTRO nao quer dizer nada, e mirar um quadradinho de
   * 38px e' pior do que mirar a caixa toda.
   */
  const grade = el('div', `locker-grade caixa-quadrada${caixa.chegadas ? '' : ' deposito-alvo'}`);
  /*
   * ---- Arrastar um item em cima de outro TROCA os dois de lugar ----
   *
   * "seria poder trocar de lugar entre os itens de slot ... na mochila ou
   * deposito." O nome do lugar é o MESMO que o `from` da célula (`depot:3`),
   * e é ele que o servidor confere. Ver `trocarArrastando`.
   */
  const trocarNaCaixa = (carga, evento) => trocarArrastando(carga, `depot:${caixa.indice}`, evento);
  if (caixa.chegadas) {
    /*
     * As Chegadas não RECEBEM nada — só se tira delas —, mas se organizam como
     * qualquer outra. Por isso a escuta é própria, e não o `aceitarSoltura`:
     * este arrasto não guarda nada, só troca duas casas de lugar.
     */
    grade.addEventListener('dragover', (evento) => evento.preventDefault());
    grade.addEventListener('drop', (evento) => {
      evento.preventDefault();
      try {
        trocarNaCaixa(JSON.parse(evento.dataTransfer.getData('text/plain')), evento);
      } catch {
        /* arrasto de fora da página */
      }
    });
  } else aceitarSoltura(grade, (carga, evento) => {
    // Veio da PRÓPRIA caixa: é reorganizar, e não guardar de novo o que já está
    // guardado. Antes deste atalho o arrasto caía no `store` e não fazia nada.
    if (trocarNaCaixa(carga, evento)) return;
    // Guardar lê a MOCHILA: vindo da Store Inbox guardaria a cópia de lá.
    if (carga.from === 'storeInbox') return void ctx.notice?.('Leve da Store Inbox para a mochila primeiro.');
    /*
     * ---- O que é preso ao personagem não entra na Compartilhada ----
     *
     * O servidor recusa de qualquer jeito (ver `presos.mjs`); isto é para a
     * pessoa saber ANTES de escolher a quantidade, e não depois. É o mesmo
     * aviso que a mesa de troca já dá — a diferença é que ali vale para toda
     * troca, e aqui só para esta caixa: guardar uma exercise numa caixa SUA
     * continua sendo permitido, porque ela não muda de dono ali.
     */
    if (caixa.compartilhada && ctx.state.items?.[carga.id]?.fixo) {
      const nome = ctx.state.items[carga.id]?.name ?? 'Esse item';
      return void ctx.notice?.(`${nome} é fixa no personagem — não vai para a caixa compartilhada.`);
    }
    // A pilha inteira, e com shift a quantia escolhida. Ver `quantosMover`.
    quantosMover(carga, (quantos) => {
      // Da bolsa de loot o item passa pela mochila antes: o deposito guarda o que
      // esta com o personagem, e a bolsa e' a fila da venda automatica.
      if (carga.from === 'pouch') send({ t: 'pouch', id: carga.id, count: quantos, to: 'bag' });
      send({ t: 'depot', action: 'store', id: carga.id, count: quantos, caixa: caixa.indice });
    });
  });
  {
    /*
     * A POSICAO da entrada na caixa viaja com o clique.
     *
     * Cinco soulbleeders sao cinco entradas com o mesmo id, cada uma com os
     * afixos dela. Mandando so o id, o servidor tirava sempre a primeira — era
     * o report "clico no ULTIMO, tira o primeiro". `inicio` entra na conta
     * porque a caixa e paginada: a terceira celula da segunda pagina nao e a
     * terceira entrada da caixa.
     */
    naTela.forEach((entry, n) => {
      grade.append(
        itemCell(entry, `depot:${caixa.indice}`, {
          /*
           * A CASA em que esta peça está, para o arrastar-para-trocar saber
           * quem trocar com quem. É o mesmo número que já viajava no clique
           * como `pos` — ele só não chegava à célula, e sem ele o arrasto
           * dentro da caixa não tinha o que dizer.
           */
          pilha: inicio + n,
          // Clique leva a pilha; shift pergunta quanto (`itemCell` cuida disso).
          // E' o mesmo gesto do caminho de volta, na mochila.
          titulo: 'Quanto vai para a mochila?',
          onClick: (_, quantos) =>
            send({
              t: 'depot', action: 'take', id: entry.id,
              count: quantos ?? entry.count, caixa: caixa.indice, pos: inicio + n,
            }),
        })
      );
    });
    /*
     * E as vagas VAZIAS completam o quadrado, até o TETO da caixa.
     *
     * Elas não são enfeite: numa caixa com seis coisas, são elas que dizem que
     * ainda cabem noventa e quatro. Sem elas, a caixa com seis itens e a caixa
     * cheia têm o mesmo desenho, só de comprimentos diferentes.
     *
     * Nunca mais do que o teto: desenhar vaga que a caixa não tem é prometer
     * espaço que o servidor vai recusar — e na compartilhada o teto é comprado,
     * então ele muda.
     */
    const cabem = Math.max(naTela.length, caixa.teto ?? naTela.length);
    for (let vaga = naTela.length; vaga < cabem; vaga++) {
      grade.append(el('div', 'cell vaga'));
    }
  }
  body.append(grade);

  /* O que fazer com uma caixa vazia, dito embaixo da grade e não no lugar dela. */
  if (!itens.length) {
    body.append(
      el(
        'p',
        'shop-note',
        caixa.chegadas
          ? 'Nada esperando. O que chegar sem caber na mochila aparece aqui.'
          : caixa.compartilhada
            ? 'Vazia. Arraste uma peça da mochila e ela aparece nos seus outros personagens.'
            : 'Esta caixa está vazia. Arraste itens da mochila para guardar.'
      )
    );
  }

  /*
   * ---- E a compartilhada vende as vagas que faltam ----
   *
   * O dono: "poder comprar mais slots pra ela (máximo 100), cada compra viria 20
   * espaços e seria 25 Draevor Coins".
   *
   * O botão mora DENTRO da caixa, e não só na loja: é aqui que a pessoa descobre
   * que o espaço acabou, e mandá-la procurar a prateleira certa da Store
   * para resolver o que ela está olhando é uma volta que ninguém precisa dar.
   * Ele leva para a loja, que é quem cobra.
   */
  if (caixa.compartilhada && !caixa.semConta) {
    const rodape = el('div', 'deposito-vagas');
    if (caixa.podeComprarVagas) {
      const comprar = el(
        'button',
        'primary',
        `Comprar +${caixa.vagasPorCompra} vagas · ${caixa.coinsPorCompra} Draevor Coins`
      );
      /*
       * ---- E ela PERGUNTA antes de cobrar ----
       *
       * O dono: "o comprar vagas do depósito compartilhado tem que ter botão pra
       * confirmação".
       *
       * Ele está certo, e o motivo é onde o botão mora: ele fica encostado na
       * grade da caixa, no meio de um gesto repetitivo — clicar, arrastar, clicar
       * — e um clique perdido ali gastava Draevor Coins sem uma palavra. É a única
       * coisa nesta janela que custa dinheiro de verdade.
       *
       * A caixa diz o preço E o que ele compra: "25 coins" sozinho não deixa
       * ninguém decidir sem lembrar de cor quantas vagas vêm.
       */
      comprar.onclick = () =>
        confirmarDeNovo({
          titulo: 'Comprar vagas?',
          texto:
            `+${caixa.vagasPorCompra} vagas na caixa compartilhada por ${caixa.coinsPorCompra} Draevor Coins. ` +
            `Ela fica com ${Math.min(caixa.vagasNoMaximo, caixa.teto + caixa.vagasPorCompra)} de ${caixa.vagasNoMaximo}, ` +
            'e as vagas valem para todos os personagens da conta.',
          botao: `Comprar por ${caixa.coinsPorCompra} coins`,
          aoConfirmar: () => send({ t: 'store', action: 'buy', id: 'cofre-vagas' }),
        });
      rodape.append(comprar);
      rodape.append(
        el('em', null, `${caixa.teto} de ${caixa.vagasNoMaximo} vagas — as vagas são da conta toda.`)
      );
    } else {
      rodape.append(el('em', null, `A caixa está no máximo: ${caixa.teto} vagas.`));
    }
    body.append(rodape);
  }
}

/*
 * O que tem dentro de uma sacola do bau, sem tirar nada de dentro dela.
 *
 * A sacola era uma celula com um numero em cima: "7". Sete o que? Do lado de
 * quem joga, a unica forma de descobrir era despejar na mochila — e a poucos
 * dias de o prazo vencer, com a mochila cheia, essa e' exatamente a decisao que
 * nao da' para tomar no escuro.
 *
 * Cada item aparece com o desenho, a quantidade e o balao de sempre; o botao
 * embaixo faz o que o clique esquerdo na sacola ja fazia.
 */
function dentroDaSacola(sacola) {
  const { send } = ctx;
  const caixa = el('div', 'sacola-aberta');

  caixa.append(el('h4', 'deposito-titulo', `Sacola de ${sacola.boss}`));

  const topo = el('div', 'locker-topo');
  topo.append(el('span', 'sacola-prazo', `expira em ${quantoFalta(prazoDaSacola(sacola))}`));
  /* "e um botão coletar": o nome é o do dono, e ele diz melhor o que acontece. */
  const levar = el('button', 'primary', 'Coletar');
  tipTexto(levar, 'Leva o que está nesta sacola para a Boss Pouch.');
  levar.onclick = () => send({ t: 'reward', action: 'take', sacola: sacola.indice });
  topo.append(levar);
  /*
   * Limpar a sacola, no mesmo desenho do "Limpar" da bolsa de loot: aqui so' se
   * abre a confirmacao, e quem destroi e' ela — com o que vai fora marcado em
   * vermelho e um clique para salvar o que o jogador quiser.
   */
  const limpar = el('button', 'bag-clear', 'Limpar');
  tipTexto(limpar, 'Joga fora o que está na sacola. A tela seguinte mostra o que vai sumir e deixa escolher o que fica.');
  limpar.onclick = () => abrirLimparSacola(sacola);
  topo.append(limpar);
  caixa.append(topo);

  /*
   * ---- Uma celula por item, e clicar tira SO' ELE ----
   *
   * As celulas eram de olhar: sem arrasto, sem menu e sem clique. Ver o que ha'
   * dentro sem poder pegar so' o que interessa e' meia resposta — com a mochila
   * quase cheia, "levar tudo" e' justamente o que nao da' para fazer.
   *
   * `itemCell` continua de fora de proposito: ela deixa a celula arrastavel e
   * poe o menu de item (equipar, vender, proteger), e nada disso vale para um
   * item que ainda esta na sacola e nao na mochila.
   */
  const grade = el('div', 'locker-grade');
  for (const entry of sacola.itens) {
    const cela = el('div', 'cell sacola-item');
    cela.append(itemCanvas(entry.id, 30, entry.count));
    if (entry.count > 1) cela.append(el('b', null, entry.count > 9999 ? '9k+' : entry.count));
    /*
     * ---- As estrelas, aqui dentro também ----
     *
     * "a mensagem de quando abre bag e o modal lá têm que mostrar as estrelas
     * do item também." A sacola de boss guardava a peça sem afixo nenhum (era a
     * primeira pendência da nota de sincronia) e a célula não tinha como
     * mostrar o que não existia. Agora existe, e ela mostra.
     *
     * É a decisão de 'levo isto agora ou deixo para depois' com a mochila
     * quase cheia: sem a estrela, uma Draevor Knight Axe ★★★ e uma limpa são o
     * mesmo quadradinho.
     */
    const estrelasDaPeca = estrelasDosAfixos(entry.af);
    if (estrelasDaPeca.length) {
      cela.classList.add('com-afixo');
      cela.append(seloDeEstrelas('selo-afixo', estrelasDaPeca));
    }
    tipFor(cela, entry.id, `${entry.count > 1 ? `${entry.count} unidades — ` : ''}clique para levar só este para a Boss Pouch`, null, entry);
    cela.onclick = () => send({ t: 'reward', action: 'takeItem', sacola: sacola.indice, id: entry.id });
    grade.append(cela);
  }
  caixa.append(grade);
  return caixa;
}

/*
 * ---- Jogar fora o que sobrou numa sacola de boss ----
 *
 * Mesmo desenho do "Limpar" da bolsa de loot, e de proposito: e' a mesma
 * decisao ("isto vai sumir, e nao tem volta") e o jogador ja sabe le-la ali.
 * Tudo comeca marcado para sair, em vermelho; clicar num item o salva.
 *
 * Existe porque uma sacola de boss nao expira sozinha antes de sete dias, e o
 * bau tem cem vagas: quem so' queria a arma fica com quatro pilhas de lixo
 * ocupando lugar e um relogio contando.
 */
/*
 * ---- A limpeza do baú INTEIRO ----
 *
 * A mesma caixa da sacola sozinha, com uma diferença que é a razão de ela
 * existir: a grade é a UNIÃO dos tipos de todas as sacolas, e o que o jogador
 * salvar vale para as trinta. Marcar a Bag You Desire uma vez e limpar o resto
 * é exatamente o que ele pediu.
 *
 * A contagem diz unidades e sacolas, porque as duas importam: "402 itens de 7
 * tipos, em 30 sacolas" é o tamanho da decisão, e ela não tem volta.
 */
function abrirLimparTodas(sacolas) {
  const { send } = ctx;
  const guardados = new Set();

  ctx.openModal(`Limpar ${sacolas.length} sacolas`, (body) => {
    const desenhar = () => {
      body.innerHTML = '';
      /*
       * Do estado, e não da cópia recebida no clique: entre abrir esta tela e
       * confirmar, o `pushState` pode ter mudado o baú.
       */
      const atuais = ctx.state.character.rewards ?? [];
      if (!atuais.length) {
        body.append(el('p', 'gate-note', 'O baú já está vazio.'));
        const acoes = el('div', 'confirm-actions');
        const fechar = el('button', 'ghost', 'Fechar');
        fechar.onclick = () => ctx.closeModal();
        acoes.append(fechar);
        body.append(acoes);
        return;
      }

      body.append(
        el(
          'p',
          'shop-note',
          'Isto destrói o que estiver marcado em vermelho em TODAS as sacolas, e não tem volta. ' +
            'Clique num item para guardá-lo — o que você guardar fica em todas elas.'
        )
      );

      // A união dos tipos, com a soma das unidades e em quantas sacolas ele está.
      const porTipo = new Map();
      for (const sacola of atuais) {
        for (const entry of sacola.itens ?? []) {
          const antes = porTipo.get(entry.id) ?? { ...entry, count: 0, sacolas: 0 };
          antes.count += entry.count;
          antes.sacolas += 1;
          porTipo.set(entry.id, antes);
        }
      }

      const grade = el('div', 'filter-grid');
      let tiposFora = 0;
      let unidadesFora = 0;
      for (const entry of porTipo.values()) {
        const fica = guardados.has(entry.id);
        const cell = itemCell(entry, 'filter');
        cell.classList.add(fica ? 'protected' : 'barred');
        tipFor(
          cell,
          entry.id,
          `${money(entry.count)} unidade(s) em ${entry.sacolas} sacola(s) — ${fica ? 'FICA' : 'vai fora'}`
        );
        cell.onclick = () => {
          if (fica) guardados.delete(entry.id);
          else guardados.add(entry.id);
          desenhar();
        };
        grade.append(cell);
        if (fica) continue;
        tiposFora++;
        unidadesFora += entry.count;
      }
      body.append(grade);

      const resumo = el('p', 'gate-note');
      resumo.textContent = tiposFora
        ? `Vão fora ${money(unidadesFora)} item(ns) de ${tiposFora} tipo(s), em ${atuais.length} sacola(s).`
        : 'Nada marcado para jogar fora.';
      body.append(resumo);

      const acoes = el('div', 'confirm-actions');
      const cancelar = el('button', 'ghost', 'Cancelar');
      cancelar.onclick = () => ctx.closeModal();
      const jogar = el('button', 'danger', `Jogar fora de ${atuais.length} sacola(s)`);
      jogar.disabled = !tiposFora;
      jogar.onclick = () => {
        send({ t: 'reward', action: 'clearAll', keep: [...guardados] });
        ctx.closeModal();
      };
      acoes.append(cancelar, jogar);
      body.append(acoes);
    };

    ctx.redraw = desenhar;
    desenhar();
  });
}

function abrirLimparSacola(sacola) {
  const { send } = ctx;
  const guardados = new Set();

  ctx.openModal(`Limpar a sacola de ${sacola.boss}`, (body) => {
    const desenhar = () => {
      body.innerHTML = '';
      /*
       * A sacola vem do estado, e nao da copia recebida no clique: entre abrir
       * esta tela e confirmar, o `pushState` pode ter mudado o que ha dentro
       * dela (o jogador tirou um item pela tela de tras).
       */
      const atual = (ctx.state.character.rewards ?? []).find((s) => s.indice === sacola.indice);
      if (!atual?.itens?.length) {
        body.append(el('p', 'gate-note', 'A sacola já está vazia.'));
        const acoes = el('div', 'confirm-actions');
        const fechar = el('button', 'ghost', 'Fechar');
        fechar.onclick = () => ctx.closeModal();
        acoes.append(fechar);
        body.append(acoes);
        return;
      }

      body.append(
        el('p', 'shop-note', 'Isto destrói o que estiver marcado em vermelho, e não tem volta. Clique num item para guardá-lo.')
      );

      const grade = el('div', 'filter-grid');
      let tiposFora = 0;
      let unidadesFora = 0;
      for (const entry of atual.itens) {
        const fica = guardados.has(entry.id);
        const cell = itemCell(entry, 'filter');
        cell.classList.add(fica ? 'protected' : 'barred');
        tipFor(cell, entry.id, `${money(entry.count)} unidade(s) — ${fica ? 'FICA na sacola' : 'vai fora'}`);
        cell.onclick = () => {
          if (fica) guardados.delete(entry.id);
          else guardados.add(entry.id);
          desenhar();
        };
        grade.append(cell);
        if (fica) continue;
        tiposFora++;
        unidadesFora += entry.count;
      }
      body.append(grade);

      const resumo = el('p', 'gate-note');
      resumo.textContent = tiposFora
        ? `Vão fora ${money(unidadesFora)} item(ns) de ${tiposFora} tipo(s).`
        : 'Nada marcado para jogar fora.';
      body.append(resumo);

      const acoes = el('div', 'confirm-actions');
      const cancelar = el('button', 'ghost', 'Cancelar');
      cancelar.onclick = () => ctx.closeModal();
      const jogar = el('button', 'danger', 'Jogar fora');
      jogar.disabled = !tiposFora;
      jogar.onclick = () => {
        send({ t: 'reward', action: 'clear', sacola: sacola.indice, keep: [...guardados] });
        ctx.closeModal();
      };
      acoes.append(cancelar, jogar);
      body.append(acoes);
    };

    ctx.redraw = desenhar;
    desenhar();
  });
}

/** A caixinha de renomear, no mesmo desenho das outras confirmacoes. */
function perguntarNomeDaCaixa(caixa) {
  const { send } = ctx;
  document.querySelector('.confirm-back.nome-da-caixa')?.remove();

  const back = el('div', 'confirm-back nome-da-caixa');
  const box = el('div', 'confirm-box');
  box.append(el('b', null, 'Nome da caixa'));
  box.append(el('p', 'shop-note', 'Até 24 letras. Deixe em branco para voltar ao nome de fábrica.'));

  const campo = document.createElement('input');
  campo.type = 'text';
  campo.className = 'quantia-campo';
  campo.maxLength = 24;
  campo.value = caixa.nome;
  campo.autocomplete = 'off';
  box.append(campo);

  const fechar = () => back.remove();
  const acoes = el('div', 'confirm-actions');
  const cancelar = el('button', 'ghost', 'Cancelar');
  cancelar.onclick = fechar;
  const ok = el('button', 'primary', 'Salvar');
  ok.onclick = () => {
    send({ t: 'depot', action: 'rename', caixa: caixa.indice, nome: campo.value });
    fechar();
  };
  acoes.append(cancelar, ok);
  box.append(acoes);

  back.addEventListener('keydown', (evento) => {
    if (evento.key === 'Enter') {
      evento.preventDefault();
      ok.onclick();
    } else if (evento.key === 'Escape') {
      evento.preventDefault();
      fechar();
    }
    evento.stopPropagation();
  });

  back.append(box);
  fecharAoClicarFora(back, fechar);
  document.body.append(back);
  campo.focus();
  campo.select();
}

export function openBank() {
  ctx.openModal('Banco', (body) => {
    /*
     * ---- O que a pessoa digitou sobrevive ao redesenho ----
     *
     * Report do Garibas: "em hunt, ao tentar preencher Nome e Quantidade para
     * transferir, os inputs ficam resetando quando o dinheiro no banco ou
     * carregando aumenta (drop de gp, venda automática)... fica quase impossível
     * transferir".
     *
     * A janela se refaz inteira a cada moeda que entra, e os campos nasciam de
     * novo vazios. O `redesenharPreservando` só devolve o campo com o CURSOR —
     * o nome, preenchido antes de ir para o valor, sumia. E nem o do cursor
     * voltava de verdade: `campoDeNumero` guarda o número por dentro, e o texto
     * devolvido na tela ficava em cima de um zero, que era o que "Transferir"
     * mandava.
     *
     * O rascunho mora aqui, fora do desenho, e cada campo nasce dele e escreve
     * nele. O redesenho passa a mudar só os saldos.
     */
    const rascunho = { deposit: null, withdraw: null, nome: '', valor: 0 };
    const draw = () => {
      body.innerHTML = '';
      renderBank(body, rascunho);
    };
    ctx.redraw = draw;
    draw();
  });
}

/*
 * ---- O banco ----
 *
 * Ele mostrava dois números grandes lado a lado — "no banco" e "carregando" —
 * e três linhas de campo com botão. Nada dizia POR QUE existem dois lugares
 * para o mesmo ouro, e as linhas não diziam para que lado o dinheiro ia: quem
 * abria pela primeira vez tinha de deduzir de "Depositar" e "Sacar" qual dos
 * dois números cada um mexia.
 *
 * Agora cada saldo carrega a moeda e o que ele significa (um está protegido, o
 * outro paga 20% na morte), e cada linha carrega uma seta com a direção. A
 * regra que era um parágrafo solto virou a legenda dos próprios números — é
 * onde ela é lida.
 */
function renderBank(body, rascunho = { deposit: null, withdraw: null, nome: '', valor: 0 }) {
  const { state, send } = ctx;
  const character = state.character;
  const wrap = el('div', 'bank');

  // ------------------------------------------------------------ os saldos
  const figures = el('div', 'bank-saldos');
  const saldo = (valor, titulo, nota, classe) => {
    const caixa = el('div', `bank-figure ${classe}`);
    const topo = el('div', 'bank-figure-topo');
    topo.append(itemCanvas(3043, 20, 1));
    topo.append(el('b', null, money(valor)));
    caixa.append(topo);
    caixa.append(el('span', null, titulo));
    caixa.append(el('em', null, nota));
    return caixa;
  };
  figures.append(saldo(character.bank, 'no banco', 'a morte não tira nada daqui', 'seguro'));
  figures.append(
    saldo(character.gold, 'carregando', `morrer custa ${money(Math.round((character.gold ?? 0) * 0.2))}`, 'risco')
  );

  // --------------------------------------------------- depositar e sacar
  const form = el('div', 'bank-form');

  const makeRow = (label, action, seta, dica) => {
    const row = el('div', 'bank-linha');
    const teto = action === 'withdraw' ? character.bank : character.gold;

    const rotulo = el('div', 'bank-rotulo');
    rotulo.append(el('i', 'bank-seta', seta));
    rotulo.append(el('b', null, label));
    tipTexto(rotulo, dica);
    row.append(rotulo);

    const campo = campoDeNumero({
      valor: rascunho[action] ?? Math.min(1, teto),
      min: 0,
      max: Math.max(0, teto),
      aoMudar: (v) => {
        rascunho[action] = v;
      },
    });
    row.append(campo.wrap);

    const button = el('button', action === 'withdraw' ? 'ghost' : null, label);
    button.disabled = teto <= 0;
    button.onclick = () => {
      const quanto = campo.ler();
      if (!quanto) return;
      send({ t: 'bank', action, amount: quanto });
      campo.por(0);
    };
    const all = el('button', 'ghost', 'tudo');
    all.disabled = teto <= 0;
    all.onclick = () => send({ t: 'bank', action, amount: teto });
    row.append(button, all);
    return row;
  };

  form.append(
    makeRow('Depositar', 'deposit', '↓', 'do que você carrega para o banco'),
    makeRow('Sacar', 'withdraw', '↑', 'do banco para o que você carrega')
  );

  // ------------------------------------------------------ a transferência
  /*
   * Sai do SALDO DO BANCO e cai no banco do outro — nunca do que se carrega.
   * A linha do meio diz isso com as duas pontas, porque "transferir" sozinho
   * não conta de onde o dinheiro sai.
   */
  const cabeca = el('div', 'bank-cabeca');
  cabeca.append(artOrUiIcon('banco', ''));
  cabeca.append(el('h3', null, 'Transferir para outro personagem'));
  form.append(cabeca);
  form.append(
    el('p', 'shop-note', 'Sai do seu saldo no banco e entra no banco dele. O destinatário precisa ter vocação.')
  );

  const transfer = el('div', 'bank-transfer');
  const name = document.createElement('input');
  name.type = 'text';
  name.className = 'bank-nome';
  name.placeholder = 'nome do personagem';
  name.value = rascunho.nome;
  name.oninput = () => {
    rascunho.nome = name.value;
  };
  const value = campoDeNumero({
    valor: rascunho.valor,
    min: 0,
    max: Math.max(0, character.bank),
    aoMudar: (v) => {
      rascunho.valor = v;
    },
  });
  const confirm = el('button', null, 'Transferir');
  confirm.onclick = () => {
    const amount = value.ler();
    if (!name.value.trim() || !amount) return;
    send({ t: 'bank', action: 'transfer', name: name.value.trim(), amount });
    value.por(0);
  };
  transfer.append(name, value.wrap, confirm);
  form.append(transfer);

  wrap.append(figures, form);
  body.append(wrap);
}

// ---------- bestiary ----------

// Os quatro degraus do bestiary do servidor: cada um libera mais informação.
// O terceiro (metade das mortes) mostra elementos; o quarto, tudo.
const BESTIARY_STEPS = [0, 0.1, 0.5, 1];

/*
 * O nome do arquivo por elemento.
 *
 * Os sete principais já foram redesenhados e vivem em `icons/el-*`. Os três de
 * baixo — afogamento e os dois drenos — não têm desenho novo, e o nome sem
 * prefixo faz o `bestiaryArt` cair no recorte antigo do client sozinho.
 */
/** O nome do elemento em português, para o balão das resistências. */
const ELEMENT_LABEL = {
  physical: 'Físico', fire: 'Fogo', ice: 'Gelo', earth: 'Terra', energy: 'Energia',
  holy: 'Sagrado', death: 'Morte', drown: 'Afogamento', lifedrain: 'Dreno de vida',
  manadrain: 'Dreno de mana', poison: 'Veneno', agony: 'Agonia', healing: 'Cura',
};

const ELEMENT_ART = {
  physical: 'el-physical', fire: 'el-fire', ice: 'el-ice', earth: 'el-earth', energy: 'el-energy',
  holy: 'el-holy', death: 'el-death', drown: 'drown', lifedrain: 'lifedrain', manadrain: 'manadrain',
  // Agonia é dano de magia escura: até ela ter desenho próprio, usa o da morte.
  agony: 'el-death', healing: 'healing',
};

/** Em que degrau a criatura está, pelas mortes registradas. */
function bestiaryStep(kills, toKill) {
  if (!toKill) return kills > 0 ? 4 : 0;
  const ratio = kills / toKill;
  let step = 0;
  for (const [index, mark] of BESTIARY_STEPS.entries()) if (ratio >= mark && kills > 0) step = index + 1;
  return step;
}

/*
 * O desenho nosso primeiro, o recorte do client como rede.
 *
 * Os ícones de `bestiary/` são de 9x9 e aparecem a 18px — estão sendo ampliados
 * ao dobro, e por isso serrilham. Os de `icons/` nascem em 128 e descem, que é
 * onde o navegador acerta sozinho. A troca é por nome: pedindo `ficha-armadura`
 * em vez de `armor`, o desenho novo entra; um nome que ainda não existe em
 * `icons/` cai no antigo sem quebrar nada.
 *
 * O `image-rendering` muda junto com a fonte, pelo mesmo motivo de sempre:
 * reduzir pede suavização, ampliar pede `pixelated`.
 */
const semArteNova = new Set();

/**
 * `novo` é o nome em `icons/`; `antigo` é o recorte do client em `bestiary/`.
 *
 * Os dois nomes existem porque nem sempre coincidem: o desenho de armadura da
 * ficha se chama `ficha-armadura` e o recorte do client se chama `armor`. Caindo
 * para o mesmo nome, um ícone ainda não desenhado sumiria da tela em vez de
 * mostrar o antigo — foi o que aconteceu com vida e ocorrência na primeira
 * versão disto.
 */
const bestiaryArt = (novo, antigo = novo) => {
  const img = document.createElement('img');
  img.alt = '';

  const cair = () => {
    semArteNova.add(novo);
    img.className = 'bestiary-art antiga';
    img.onerror = () => img.remove();
    img.src = `/client/assets/bestiary/${antigo}.png`;
  };

  if (semArteNova.has(novo)) {
    cair();
    return img;
  }

  img.className = 'bestiary-art';
  img.onerror = cair;
  img.src = `/client/assets/icons/${novo}.png`;
  return img;
};

/*
 * ---- Cyclopedia ----
 *
 * A enciclopédia do jogo, montada SOBRE o que já existe: as criaturas vêm do
 * mesmo catálogo do bestiary, os itens do catálogo que o servidor já manda para
 * desenhar a mochila, e as magias do mesmo catálogo de ações da barra. Não há
 * segunda base de dados aqui — se um item existe no jogo, ele aparece; se
 * mudou, mudou aqui junto.
 *
 * O índice inverso "quem larga este item" é montado na hora a partir das
 * tabelas de loot das criaturas: é a mesma informação, lida do outro lado.
 */
export function openCyclopedia() {
  /*
   * Itens primeiro.
   *
   * Criaturas abria por padrão e, num personagem novo, a primeira coisa da
   * enciclopédia era "0 criaturas registradas de 1801" — uma tela vazia que só
   * enche depois de centenas de mortes. A aba de itens já vem cheia no minuto
   * um: são os 6417 do catálogo, e é a pergunta que o jogador faz mais ("para
   * que serve isso que caiu?"). O bestiary está inteiro na aba do meio — ele
   * tinha um botão próprio na barra, que saiu: dois ícones para a mesma
   * enciclopédia era ruído numa barra de vinte.
   */
  ctx.tabs.cyclo ??= 'itens';
  ctx.openModal('Cyclopedia', (body) => {
    const draw = () => {
      body.innerHTML = '';
      body.append(
        tabBar({ itens: 'Itens', criaturas: 'Bestiary', magias: 'Magias e runas' }, ctx.tabs.cyclo, (aba) => {
          ctx.tabs.cyclo = aba;
          draw();
        })
      );
      if (ctx.tabs.cyclo === 'criaturas') renderBestiary(body);
      else if (ctx.tabs.cyclo === 'itens') renderCicloItens(body);
      else renderCicloMagias(body);
    };
    ctx.redraw = draw;
    draw();
  });
}

/** De que criaturas cai cada item — montado uma vez e reaproveitado. */
let quemLarga = null;
function indiceDeDrops() {
  if (quemLarga) return quemLarga;
  quemLarga = new Map();
  for (const info of Object.values(ctx.state.catalog.bestiary ?? {})) {
    for (const drop of lootComGemas(info)) {
      if (!drop.id) continue;
      if (!quemLarga.has(drop.id)) quemLarga.set(drop.id, []);
      quemLarga.get(drop.id).push({ name: info.name, chance: drop.chance ?? 0 });
    }
  }
  for (const lista of quemLarga.values()) lista.sort((a, b) => b.chance - a.chance);
  return quemLarga;
}

/*
 * As famílias de item, para a lista não ser trinta mil linhas.
 *
 * A separação sai do que o próprio catálogo diz: `slot` conta onde a peça se
 * veste, e o resto é loot. Nada é escrito à mão.
 */
const FAMILIAS_DE_ITEM = {
  todos: { nome: 'Tudo', cabe: () => true },
  armas: { nome: 'Armas', cabe: (i) => i.slot === 'weapon' },
  armaduras: { nome: 'Armaduras', cabe: (i) => ['body', 'legs', 'head', 'feet', 'shield'].includes(i.slot) },
  acessorios: { nome: 'Acessórios', cabe: (i) => ['neck', 'ring', 'ammo', 'backpack'].includes(i.slot) },
  consumiveis: { nome: 'Consumíveis', cabe: (i) => !i.slot && (i.heal || i.mana || /potion|food/i.test(i.type ?? '')) },
  loot: { nome: 'Loot', cabe: (i) => !i.slot && (i.sell ?? 0) > 0 },
};

/*
 * ---- Os filtros da lista de itens ----
 *
 * A busca por nome e as famílias não davam conta da pergunta que se faz de
 * verdade nesta tela: "o que EU posso usar?". Um sorcerer de level 80 rolando
 * seis mil itens para achar as varinhas que ele veste é a tela trabalhando
 * contra ele.
 *
 * São três, e todos saem de dado que já existe no catálogo:
 *
 *   `soVocacao`  esconde o que pede outra vocação (o `vocations` do item)
 *   `soLevel`    esconde o que pede level acima do seu (`minLevel`)
 *   `soNpc`      esconde o que nenhum NPC compra (`sell`), que é o filtro de
 *                quem está decidindo o que vale a pena carregar
 *
 * Eles ficam guardados em `ctx.tabs` como o resto do estado da tela, então
 * trocar de aba e voltar não perde o que estava marcado.
 */
function filtrosDaLista(aoMudar) {
  const { state } = ctx;
  const caixa = el('div', 'ciclo-filtros');

  const marca = (chave, rotulo, dica) => {
    const linha = el('label', `ciclo-filtro${ctx.tabs[chave] ? ' on' : ''}`);
    tipTexto(linha, dica);
    const campo = document.createElement('input');
    campo.type = 'checkbox';
    campo.checked = !!ctx.tabs[chave];
    campo.onchange = () => {
      ctx.tabs[chave] = campo.checked;
      aoMudar();
    };
    linha.append(campo, el('span', null, rotulo));
    caixa.append(linha);
  };

  const vocacao = state.catalog.vocations?.find((v) => v.id === state.character.vocation);
  marca(
    'cicloSoVocacao',
    `Só ${vocacao?.name ?? 'a minha vocação'}`,
    'Esconde o que pede outra vocação. O que não pede vocação nenhuma continua na lista.'
  );
  marca(
    'cicloSoLevel',
    `Só até o level ${state.character.level}`,
    'Esconde o que pede level acima do seu.'
  );
  marca('cicloSoNpc', 'Só o que NPC compra', 'Esconde o que não tem comprador — o que fica no chão.');

  return caixa;
}

/** Aplica os três filtros a um item do catálogo. */
function passaNosFiltros(item) {
  const { state } = ctx;
  if (ctx.tabs.cicloSoVocacao && item.vocations?.length && !item.vocations.includes(state.character.vocation)) {
    return false;
  }
  if (ctx.tabs.cicloSoLevel && (item.minLevel ?? 0) > state.character.level) return false;
  if (ctx.tabs.cicloSoNpc && !(item.sell ?? 0)) return false;
  return true;
}

function renderCicloItens(body) {
  const { state } = ctx;
  ctx.tabs.cicloFamilia ??= 'todos';
  ctx.tabs.cicloItem ??= null;

  const bar = el('div', 'market-bar');
  const busca = document.createElement('input');
  busca.className = 'search';
  busca.placeholder = 'buscar item...';
  busca.value = ctx.tabs.cicloBusca ?? '';
  bar.append(busca);
  body.append(bar);

  body.append(
    tabBar(
      Object.fromEntries(Object.entries(FAMILIAS_DE_ITEM).map(([id, f]) => [id, f.nome])),
      ctx.tabs.cicloFamilia,
      (familia) => {
        ctx.tabs.cicloFamilia = familia;
        ctx.redraw?.();
      }
    )
  );

  const layout = el('div', 'ciclo-layout');
  const lista = el('div', 'ciclo-lista');
  const ficha = el('div', 'ciclo-ficha');

  // Os filtros só redesenham a LISTA: refazer a tela inteira tiraria o foco do
  // campo de busca a cada clique.
  body.append(filtrosDaLista(() => desenharLista()));

  const desenharLista = () => {
    lista.innerHTML = '';
    const termo = (ctx.tabs.cicloBusca ?? '').trim().toLowerCase();
    const familia = FAMILIAS_DE_ITEM[ctx.tabs.cicloFamilia] ?? FAMILIAS_DE_ITEM.todos;
    const cabem = Object.values(state.items).filter(
      (item) => item.name && familia.cabe(item) && passaNosFiltros(item) && (!termo || item.name.toLowerCase().includes(termo))
    );
    const achados = cabem.sort((a, b) => a.name.localeCompare(b.name)).slice(0, 300);

    // No telefone a lista vem aos poucos, conforme a rolagem (aos-poucos.mjs).
    montarAosPoucos(lista, achados, (item) => {
      const linha = el('button', `ciclo-item${ctx.tabs.cicloItem === item.id ? ' escolhido' : ''}`);
      linha.append(itemCanvas(item.id, 28));
      const texto = el('div', 'ciclo-item-texto');
      texto.append(el('b', null, item.name));
      texto.append(el('span', null, [item.type, item.slot ? `veste em ${item.slot}` : null].filter(Boolean).join(' · ')));
      linha.append(texto);
      if (item.sell) linha.append(el('em', 'ciclo-item-preco', `${money(item.sell)}g`));
      linha.onclick = () => {
        ctx.tabs.cicloItem = item.id;
        desenharLista();
        desenharFicha();
        mostrarAMetade();
      };
      return linha;
    });
    if (!achados.length) lista.append(el('p', 'empty', 'Nada com esse nome por aqui.'));
    else if (cabem.length > achados.length) {
      // Dizer quantos ficaram de fora é o que faz o jogador entender que a
      // lista está cortada, e não que o item que ele procura não existe.
      lista.append(el('p', 'gate-note', `Mostrando ${achados.length} de ${cabem.length} — refine a busca ou marque um filtro.`));
    }
  };

  /*
   * A ficha do item é a MESMA do balão da mochila.
   *
   * Aqui havia uma segunda versão: uma pilha de "rótulo: valor" em cinza, com
   * outra ordem, outros nomes e sem nada do que o balão tem — a faixa da
   * raridade, o ataque em vermelho, o dano elemental na cor do elemento, o
   * peso, o preço que o NPC paga. Duas fichas do mesmo item na mesma tela do
   * mesmo jogo, e a de cá já tinha divergido: mostrava `slot` cru ("weapon")
   * onde o balão diz "mão direita".
   *
   * `fichaDeItem` é o miolo daquele balão, extraído do `tooltip.mjs`. Quem
   * larga o item continua vindo daqui embaixo, porque isso é da enciclopédia e
   * não cabe num balão que aparece e some.
   */
  const desenharFicha = () => {
    ficha.innerHTML = '';
    const item = state.items[ctx.tabs.cicloItem];
    if (!item) {
      ficha.append(el('p', 'empty', 'Escolha um item na lista.'));
      return;
    }

    const balao = fichaDeItem(item.id);
    const caixa = el('div', `ciclo-balao ${balao?.classe ?? ''}`);
    if (balao) caixa.append(...balao.partes);
    ficha.append(caixa);

    const de = indiceDeDrops().get(item.id) ?? [];
    /*
     * A gema cai de quase mil bichos, e a lista de 24 nomes nao diz isso — ela
     * parece uma lista de lugares onde procurar, quando a resposta e' "em
     * qualquer lugar". A frase vem antes dos chips e responde a pergunta.
     */
    if (ehGema(item.id)) {
      const gemas = ctx.state.catalog?.gemas;
      ficha.append(
        el(
          'p',
          'shop-note',
          `Gema do Gem Atelier: cai de qualquer criatura com ${money(gemas?.expMinima ?? 0)} ou mais de ` +
            'experiência, e com chance maior de todo boss de sala.'
        )
      );
    }
    if (de.length) {
      ficha.append(el('div', 'sheet-sub', `Cai de ${de.length} criatura(s)`));
      const quem = el('div', 'ciclo-drops');
      for (const entrada of de.slice(0, 24)) {
        const chip = el('div', 'ciclo-drop');
        chip.append(el('b', null, entrada.name));
        chip.append(el('span', null, `${(entrada.chance * 100).toFixed(entrada.chance >= 0.01 ? 1 : 2).replace('.', ',')}%`));
        quem.append(chip);
      }
      ficha.append(quem);
      if (de.length > 24) ficha.append(el('p', 'gate-note', `e mais ${de.length - 24}.`));
    } else {
      ficha.append(el('p', 'gate-note', 'Nenhuma criatura conhecida larga este item.'));
    }
  };

  busca.oninput = () => {
    ctx.tabs.cicloBusca = busca.value;
    desenharLista();
  };
  // No telefone: a lista, ou só a ficha do item escolhido (lista-detalhe.mjs).
  const mostrarAMetade = () =>
    listaDetalhe(layout, ficha, {
      id: 'ciclo-itens',
      escolhido: !!(ctx.tabs.cicloItem && state.items[ctx.tabs.cicloItem]),
      voltar: () => {
        ctx.tabs.cicloItem = null;
        desenharLista();
        desenharFicha();
        mostrarAMetade();
      },
    });
  desenharLista();
  desenharFicha();
  layout.append(lista, ficha);
  body.append(layout);
  mostrarAMetade();
}

/*
 * A aba de magias, runas e poções — com o desenho de cada uma.
 *
 * Ela era uma grade de cartões de texto: nome, as palavras e uma linha de
 * "level 8 · 20 mana · 2s". A barra de ações já sabe desenhar qualquer uma
 * delas — recorta a folha `spell-icons.png` pelo `clientId` do próprio
 * spells.lua para as magias, e usa o sprite do item para runa e poção —, então
 * o que faltava não era arte, era chamar quem já a tinha. `actionIcon` vem de
 * lá; nenhum desenho novo entrou no jogo por causa desta tela.
 *
 * E o balão de cada cartão é o mesmo balão da barra (`fichaDeAcao`): passar o
 * mouse aqui mostra exatamente o que passar o mouse no slot mostra.
 */
function renderCicloMagias(body) {
  const { state } = ctx;
  const catalogo = state.actionCatalog;
  if (!catalogo) {
    body.append(el('p', 'empty', 'Catálogo de magias ainda não chegou.'));
    ctx.send({ t: 'actions' });
    return;
  }

  ctx.tabs.cicloMagia ??= 'spells';
  const bar = el('div', 'market-bar');
  const busca = document.createElement('input');
  busca.className = 'search';
  busca.placeholder = 'buscar magia ou runa...';
  busca.value = ctx.tabs.cicloBuscaMagia ?? '';
  bar.append(busca);
  body.append(bar);

  body.append(
    tabBar({ spells: 'Magias', runes: 'Runas', items: 'Poções' }, ctx.tabs.cicloMagia, (aba) => {
      ctx.tabs.cicloMagia = aba;
      ctx.redraw?.();
    })
  );

  const grade = el('div', 'ciclo-magias');
  const desenhar = () => {
    grade.innerHTML = '';
    const termo = (ctx.tabs.cicloBuscaMagia ?? '').trim().toLowerCase();
    const fonte = catalogo[ctx.tabs.cicloMagia] ?? [];
    const achados = fonte.filter((entry) => !termo || (entry.name ?? '').toLowerCase().includes(termo));

    for (const entry of achados) {
      const card = el('div', `ciclo-magia${entry.blocked ? ' bloqueada' : ''}`);

      const arte = el('div', 'ciclo-magia-arte');
      arte.append(actionIcon(entry, 34));
      card.append(arte);

      const texto = el('div', 'ciclo-magia-texto');
      const topo = el('div', 'ciclo-magia-topo');
      topo.append(el('b', null, entry.name));
      if (entry.words) topo.append(el('em', null, entry.words));
      texto.append(topo);

      const dados = [];
      if (entry.level) dados.push(`level ${entry.level}`);
      if (entry.magicLevel) dados.push(`magic ${entry.magicLevel}`);
      if (typeof entry.mana === 'number' && entry.mana) dados.push(`${entry.mana} mana`);
      if (entry.cooldown) dados.push(`${(entry.cooldown / 1000).toFixed(0)}s`);
      if (entry.vocations?.length) dados.push(entry.vocations.join('/'));
      if (entry.damage) dados.push(`${entry.heals ? 'cura' : 'dano'} ${money(entry.damage.min)}-${money(entry.damage.max)}`);
      if (Array.isArray(entry.heal)) dados.push(`cura ${entry.heal[0]}-${entry.heal[1]}`);
      if (Array.isArray(entry.mana)) dados.push(`mana ${entry.mana[0]}-${entry.mana[1]}`);
      texto.append(el('span', 'ciclo-magia-dados', dados.join(' · ')));
      if (entry.blocked) texto.append(el('em', 'ciclo-magia-trava', entry.blocked));
      card.append(texto);

      // O balão da barra, inteiro, pelo mesmo caminho que a barra usa.
      tipForAction(card, entry, () => actionIcon(entry, 40));
      grade.append(card);
    }
    if (!achados.length) grade.append(el('p', 'empty', 'Nada com esse nome.'));
  };
  busca.oninput = () => {
    ctx.tabs.cicloBuscaMagia = busca.value;
    desenhar();
  };
  desenhar();
  body.append(grade);
}

/*
 * O Bestiary não tem mais tela própria: ele é a aba do meio da Cyclopedia.
 *
 * A função continua exportada porque o resto do jogo aponta para ela — o balão
 * de uma criatura, o aviso de bestiary completo — e todos querem a mesma coisa:
 * "abre o bestiary". Ela leva à Cyclopedia já na aba certa.
 */
export function openBestiary() {
  ctx.tabs.cyclo = 'criaturas';
  openCyclopedia();
}

function renderBestiary(body) {
  const { state } = ctx;
  /*
   * ---- Os padrões moram AQUI, e não em quem chama ----
   *
   * Eles eram postos no `openBestiary`, o modal próprio — que saiu da barra
   * quando o bestiary virou aba da Cyclopedia. Entrando pela aba, ninguém
   * passava por aquelas duas linhas: o seletor de classe abria com `undefined`
   * e a lista saía sem o filtro, diferente da tela que o jogador conhecia.
   *
   * Uma função que desenha uma tela tem de saber montar a tela inteira sozinha.
   * Depender de um preâmbulo que só um dos chamadores executa é o tipo de
   * dependência que quebra calada no dia em que alguém abre por outro caminho —
   * e foi exatamente o que aconteceu.
   */
  ctx.tabs.bestiaryClass ??= 'all';
  ctx.tabs.bestiaryPick ??= null;
  ctx.tabs.bestiarySearch ??= '';

  const catalog = state.catalog.bestiary;
  const kills = state.character.bestiary ?? {};

  // ---- barra de busca e classe ----
  const bar = el('div', 'market-bar');
  const search = document.createElement('input');
  search.className = 'search';
  search.placeholder = 'buscar criatura...';
  search.value = ctx.tabs.bestiarySearch ?? '';

  const classes = new Set(['all']);
  for (const entry of Object.values(catalog)) if (entry.class) classes.add(entry.class);

  const pick = document.createElement('select');
  for (const name of [...classes].sort()) {
    const option = document.createElement('option');
    option.value = name;
    option.textContent = name === 'all' ? 'Todas as classes' : name;
    pick.append(option);
  }
  pick.value = ctx.tabs.bestiaryClass;

  /*
   * ---- Quem redesenha é o LAYOUT, e não a tela inteira ----
   *
   * O report: "a busca no bestiary tá tirando o cursor da barra de texto a cada
   * letra."
   *
   * Estava certo, e a causa é o `ctx.redraw()` que ficava aqui. Ele reconstrói
   * o corpo do modal do zero — inclusive esta caixa de busca. O elemento que
   * tinha o foco deixava de existir a cada tecla, e o navegador devolvia o foco
   * para o corpo do documento: a segunda letra ia para o vazio.
   *
   * A busca das magias, dois blocos acima, já fazia certo: o `oninput` dela
   * redesenha só a grade. Aqui é o mesmo trato — a barra fica de pé e quem se
   * refaz é a lista com a ficha ao lado.
   *
   * `pintar` também é o que os cartões chamam ao serem clicados. Poderia ser o
   * `ctx.redraw` ali, porque o clique já tirou o foco da caixa; usar o mesmo
   * caminho nos dois evita a pergunta "por que este é diferente do outro" e a
   * tela pisca menos.
   */
  const layout = el('div', 'bestiary-layout');

  const apply = () => {
    ctx.tabs.bestiarySearch = search.value;
    ctx.tabs.bestiaryClass = pick.value;
    pintar();
  };
  search.oninput = apply;
  pick.onchange = apply;
  bar.append(search, pick);
  body.append(bar);

  const registered = Object.keys(kills).length;
  body.append(
    el('p', 'shop-note', `${registered} criaturas registradas de ${Object.keys(catalog).length}. Cada degrau de mortes libera mais informação, como no bestiary do jogo.`)
  );

  function pintar() {
    layout.innerHTML = '';

    // ---- lista ----
    const list = el('div', 'bestiary-list');
    const term = (ctx.tabs.bestiarySearch ?? '').trim().toLowerCase();
    const entries = Object.entries(catalog)
      .filter(([, entry]) => (ctx.tabs.bestiaryClass === 'all' || entry.class === ctx.tabs.bestiaryClass))
      .filter(([, entry]) => !term || entry.name.toLowerCase().includes(term))
      .sort((a, b) => (kills[b[0]] ?? 0) - (kills[a[0]] ?? 0) || a[1].name.localeCompare(b[1].name))
      .slice(0, 200);

    // No telefone a lista vem aos poucos, conforme a rolagem (aos-poucos.mjs).
    montarAosPoucos(list, entries, ([key, entry]) => {
      const done = kills[key] ?? 0;
      const step = bestiaryStep(done, entry.toKill);
      const card = el('button', `bestiary-card${step ? '' : ' locked'}`);
      card.setAttribute('aria-selected', String(ctx.tabs.bestiaryPick === key));

      if (step && outfitInfo(entry.look)) card.append(outfitCanvas(entry.look, entry.colors, 40, 2, true));
      else card.append(el('i', 'bestiary-unknown', '?'));

      const text = el('div', 'action-text');
      text.append(el('b', null, step ? entry.name : 'desconhecida'));
      const stars = el('em', 'bestiary-stars', '\u2605'.repeat(entry.stars) + '\u2606'.repeat(Math.max(0, 5 - entry.stars)));
      text.append(stars);
      card.append(text);

      const progress = el('i', 'bestiary-progress');
      progress.style.width = `${Math.min(100, entry.toKill ? (done / entry.toKill) * 100 : done ? 100 : 0)}%`;
      card.append(progress);

      card.onclick = () => {
        ctx.tabs.bestiaryPick = key;
        pintar();
      };
      return card;
    });
    if (!entries.length) list.append(el('p', 'empty', 'nada com esse filtro'));
    layout.append(list);

    // ---- detalhe ----
    const detalhe = bestiaryDetail(catalog, kills);
    layout.append(detalhe);
    // No telefone: a lista, ou só o detalhe da escolhida (lista-detalhe.mjs).
    listaDetalhe(layout, detalhe, {
      id: 'bestiary',
      escolhido: !!(ctx.tabs.bestiaryPick && catalog[ctx.tabs.bestiaryPick]),
      voltar: () => {
        ctx.tabs.bestiaryPick = null;
        pintar();
      },
    });
  }

  pintar();
  body.append(layout);
}

const numero = (v) => money(Math.round(v));
const intervaloEmTexto = (ms) => `${String(Math.round((ms / 1000) * 10) / 10).replace('.', ',')} s`;

/** "Corpo a corpo", "Magia em área", "Magia em feixe", "Magia à distância": o nome do golpe, sem o nome cru do arquivo. */
function nomeDoAtaque(a) {
  if (a.tipo === 'melee') return 'Corpo a corpo';
  if (a.forma === 'area') return `Magia em área${a.raio ? ` (raio ${a.raio})` : ''}`;
  if (a.forma === 'feixe') return `Magia em feixe${a.comprimento ? ` (${a.comprimento} casas)` : ''}`;
  return 'Magia à distância';
}

/** Uma linha de ataque: ícone do elemento, nome, faixa de dano-base e o ritmo. */
function linhaDeAtaque(a) {
  const linha = el('div', `bestiary-ataque el-${a.elemento}`);
  linha.append(bestiaryArt(ELEMENT_ART[a.elemento] ?? 'el-physical', a.elemento));
  const texto = el('div', 'bestiary-ataque-texto');
  texto.append(el('b', null, nomeDoAtaque(a)), el('em', null, ELEMENT_LABEL[a.elemento] ?? a.elemento));
  linha.append(texto);
  // "~" quando o valor foi ESTIMADO na geração dos dados (a magia não tinha número no arquivo do monstro).
  const dano = el('span', 'bestiary-ataque-dano', `${a.estimado ? '~' : ''}${numero(a.min)}–${numero(a.max)}`);
  linha.append(dano);
  tipTexto(
    linha,
    `${nomeDoAtaque(a)} — dano ${ELEMENT_LABEL[a.elemento] ?? a.elemento}: ${numero(a.min)} a ${numero(a.max)} (dano-base).\n` +
      `Tenta a cada ${intervaloEmTexto(a.intervalo)}${a.chance < 100 ? `, em ${a.chance}% das vezes` : ''}.` +
      (a.estimado ? '\nValor ESTIMADO: o arquivo do monstro não tem o número exato desta magia.' : '')
  );
  return linha;
}

/** Preenche a área "para você" da ficha (XP e ataques) com o que o servidor respondeu. */
function pintarFichaDoBicho(alvo, r, { mostrarAtaques }) {
  alvo.textContent = '';
  const fase = r.escalaDaFase !== 1 ? ` × ${String(Math.round(r.escalaDaFase * 100) / 100).replace('.', ',')} da fase = ${numero(r.naFase)}` : '';
  alvo.append(
    el(
      'p',
      'sheet-nota bestiary-exp-voce',
      `Para você agora: ~${numero(r.final)} XP por morte (criatura normal). Conta: ${numero(r.base)} de base${fase}, mais level, estágio de level, stamina e boosts.`
    )
  );
  if (!mostrarAtaques) return;
  if (!r.ataques?.length) {
    alvo.append(el('p', 'sheet-nota', 'Dano: sem dados de ataque deste monstro.'));
    return;
  }
  const maior = Math.max(...r.ataques.map((a) => a.max));
  const menor = r.ataques.length === 1 ? r.ataques[0].min : null;
  const bloco = el('details', 'bestiary-ataques');
  // Poucos golpes cabem abertos; a lista longa fica recolhida, com o maior golpe no título.
  if (r.ataques.length <= 3) bloco.open = true;
  const resumo = el('summary', null);
  resumo.append(
    el('b', null, r.ataques.length === 1 ? 'Dano' : `Ataques (${r.ataques.length})`),
    el('span', null, menor != null ? `${numero(menor)}–${numero(maior)}` : `maior golpe até ${numero(maior)}`)
  );
  bloco.append(resumo);
  for (const a of r.ataques) bloco.append(linhaDeAtaque(a));
  const escala = r.escalaDoDano !== 1 ? ` Nesta fase o dano dele sai ×${String(Math.round(r.escalaDoDano * 100) / 100).replace('.', ',')}.` : '';
  bloco.append(
    el(
      'p',
      'sheet-nota',
      `Dano-BASE do arquivo do monstro, e não o que chega a você: raridade e fase o escalam, e a sua armadura, proteções e bloqueio o reduzem.${escala}`
    )
  );
  alvo.append(bloco);
}

const chaveDaFicha = (key, huntId, dificuldade) => `${key}|${huntId ?? ''}|${huntId ? dificuldade ?? '' : ''}`;

/** Chega `{t:'fichaDoBicho'}`: guarda e preenche a ficha, se ela ainda estiver aberta. */
export function chegouFichaDoBicho(r) {
  if (!ctx?.tabs) return;
  const chave = chaveDaFicha(r.key, r.huntId, r.dificuldade);
  (ctx.tabs.fichaDoBicho ??= {})[chave] = { ...r, em: Date.now() };
  const alvo = document.querySelector(`[data-ficha-do-bicho="${CSS.escape(chave)}"]`);
  if (alvo) pintarFichaDoBicho(alvo, r, { mostrarAtaques: alvo.dataset.ataques === '1' });
}

function bestiaryDetail(catalog, kills) {
  const { state } = ctx;
  const key = ctx.tabs.bestiaryPick;
  const entry = key && catalog[key];
  const detail = el('div', 'bestiary-detail');

  if (!entry) {
    detail.append(el('p', 'empty', 'Escolha uma criatura à esquerda.'));
    return detail;
  }

  const done = kills[key] ?? 0;
  const step = bestiaryStep(done, entry.toKill);

  const head = el('div', 'bestiary-head');
  if (step && outfitInfo(entry.look)) head.append(outfitCanvas(entry.look, entry.colors, 64, 2, true));
  const title = el('div', 'action-text');
  title.append(el('b', null, step ? entry.name : 'criatura desconhecida'));
  title.append(el('em', 'words', `${entry.class}${entry.stars ? ` · ${'★'.repeat(entry.stars)}` : ''}`));
  head.append(title);
  detail.append(head);

  // Progresso de mortes, como a barra do client.
  const bar = el('div', 'prof-bar');
  const fill = el('i');
  fill.style.width = `${Math.min(100, entry.toKill ? (done / entry.toKill) * 100 : 100)}%`;
  bar.append(fill, el('span', null, `${money(done)} / ${money(entry.toKill || done)} mortes`));
  detail.append(bar);

  if (!step) {
    detail.append(el('p', 'shop-note', 'Mate esta criatura uma vez para começar a registrá-la.'));
    return detail;
  }

  creatureSheet(detail, entry, step, { key });
  return detail;
}

/**
 * O corpo da ficha de uma criatura: números, resistências, loot e onde ela
 * aparece. O `step` é o degrau do bestiary — no bestiary ele cresce com as
 * mortes, na ficha da hunt ele já vem completo.
 */
function creatureSheet(detail, entry, step, { dicaDeLoot = true, key = null, huntId = null, dificuldade = null } = {}) {
  const { state } = ctx;

  const stats = el('div', 'bestiary-stats');
  /*
   * Cada quadradinho explica o que é no hover.
   *
   * "Armadura 4" e "velocidade 75" são números sem escala: não dá para saber se
   * 75 é rápido, nem o que a armadura desconta. A explicação é curta e mora no
   * balão do jogo, que é onde o resto das explicações já mora.
   */
  const stat = (art, label, value, antigo, dica) => {
    const cell = el('div', 'bestiary-stat');
    cell.append(bestiaryArt(art, antigo));
    cell.append(el('b', null, String(value)), el('em', null, label));
    if (dica) tipTexto(cell, dica);
    stats.append(cell);
  };
  /*
   * Quatro destes já tinham desenho pronto na ficha do personagem e no menu:
   * armadura, velocidade, experiência e os pontos de charm. Reaproveitar sai
   * mais barato que desenhar de novo, e mantém o mesmo símbolo significando a
   * mesma coisa nas duas telas — que é metade do trabalho de um ícone.
   *
   * `bes-vida` e `bes-ocorrencia` ainda não existem e caem no recorte antigo:
   * o coração da ficha é o da regeneração, com a gota, e aqui a conta é de vida
   * total; ocorrência não tem equivalente em lugar nenhum.
   */
  /*
   * Ocorrência saiu.
   *
   * O campo vem do bestiary do servidor e quase toda criatura o declara como 0,
   * que aqui virava um travessão. Um quadradinho que passa a vida mostrando "—"
   * ocupa o lugar de nada e ensina o olho a pular a fileira inteira.
   */
  stat('bes-vida', 'vida', money(entry.hp), 'health', 'Quanto de dano ela aguenta antes de morrer.');
  stat('ficha-exp', 'XP-base', money(entry.exp), 'exp', 'XP-BASE do bestiário: o que ela dá antes de tudo. Na campanha a fase multiplica este valor, e depois entram o seu level, o estágio de level, a stamina e os boosts — o quanto ISSO paga a você está logo abaixo.');
  if (step >= 2) {
    stat('ficha-armadura', 'armadura', entry.armor, 'armor', 'Desconta uma parte de cada golpe que ela recebe.');
    stat(
      'ficha-velocidade',
      'velocidade',
      entry.speed,
      'haste',
      `Com quanto ela anda. O seu personagem está em ${money(ctx.state.character.derived?.speed ?? 0)} — abaixo disso ela não alcança quem foge.`
    );
  }
  if (step >= 3) {
    stat(
      'charms',
      'pontos de charm',
      entry.charmPoints,
      'charm',
      `Pontos que o bestiary paga quando as ${money(entry.toKill || 0)} mortes dela fecharem. Uma vez só.`
    );
  }
  detail.append(stats);

  /*
   * ---- "Quanto isto paga a MIM" ----
   *
   * O número da fileira acima é o XP-BASE do bestiário, e o que cai na caçada é outro: a fase da campanha
   * multiplica o bicho, e o level, o estágio, a stamina e os boosts multiplicam de novo. A conta é do
   * servidor (`fichaDoBicho`: a mesma cadeia da morte e os mesmos ataques do combate) — aqui só se mostra, e não se refaz.
   */
  if (key) {
    const area = el('div', 'bestiary-ficha-voce');
    const chave = chaveDaFicha(key, huntId, dificuldade);
    area.dataset.fichaDoBicho = chave;
    // Como a armadura e a velocidade, o dano se revela com as mortes (degrau 2); a prévia da hunt já está no 3.
    area.dataset.ataques = step >= 2 ? '1' : '0';
    const guardada = ctx.tabs.fichaDoBicho?.[chave];
    // Vale por poucos segundos: stamina, level e boosts mudam, e o número tem de ser o de agora.
    if (guardada && Date.now() - guardada.em < 10_000) pintarFichaDoBicho(area, guardada, { mostrarAtaques: step >= 2 });
    else {
      area.append(el('p', 'sheet-nota bestiary-exp-voce', 'Calculando o XP e o dano para você…'));
      ctx.send({ t: 'fichaDoBicho', key, ...(huntId ? { huntId, dificuldade } : {}) });
    }
    detail.append(area);
  }

  /*
   * ---- Elementos: o que o SEU golpe faz nela ----
   *
   * Antes era uma fileira só, com o sinal invertido de propósito: o servidor
   * guarda "resistência de 20%" e a tela escrevia "-20%", porque o que interessa
   * é o dano que sai. Só que "-20%" com um floco de gelo do lado não diz de
   * quem é o menos — dá para ler como "ela causa 20% a menos de gelo", que é o
   * contrário. Era isso que estava confuso.
   *
   * Agora são dois grupos com NOME — "Resistências" e "Fraquezas" —, e é o
   * título que diz de quem é o número. Com ele dizendo isso, o número volta a
   * ser a porcentagem crua ("20%"), que é como o bestiary do jogo escreve e
   * como o jogador pensa; o multiplicador (`x0,80`) resolvia a ambiguidade mas
   * obrigava a fazer a conta de cabeça para saber quanto era em porcento.
   *
   * O balão continua dizendo a frase inteira, com o multiplicador dentro para
   * quem quiser a conta pronta.
   */
  if (step >= 3) {
    /*
     * O TETO da resistencia entra aqui tambem.
     *
     * O catalogo do servidor dele marca 100 em dois mil lugares, e o jogo nao
     * usa mais o 100: `applyElement` corta em `RESISTENCIA_MAXIMA`. Mostrar o
     * numero cru faria a ficha prometer uma parede que a luta nao tem — e
     * "100%, sai x0,00" e' a promessa de que nao adianta bater, justamente o
     * contrario do que passou a acontecer.
     *
     * Uma conta so' para os dois lados: a ficha diz o que o golpe vai fazer.
     */
    /*
     * E o teto do BOSS é outro: 20, contra os 80 do bicho comum. É o mesmo
     * número que a luta usa (ver `resistenciaDe`, em hunt.mjs) — a ficha de um
     * boss que anunciasse 100% mandaria o jogador trocar de arma por causa de
     * uma parede que não existe mais.
     */
    const teto = entry.boss ? RESISTENCIA_MAXIMA_DE_BOSS : RESISTENCIA_MAXIMA;
    const todos = Object.entries(entry.elements ?? {})
      .map(([element, valor]) => [element, valor > 0 ? Math.min(teto, valor) : valor])
      .filter(([, valor]) => valor !== 0);
    // Do mais forte para o mais fraco dentro de cada grupo: é a ordem em que a
    // decisão é tomada ("qual elemento eu evito? qual eu uso?").
    const resiste = todos.filter(([, valor]) => valor > 0).sort((a, b) => b[1] - a[1]);
    const fraca = todos.filter(([, valor]) => valor < 0).sort((a, b) => a[1] - b[1]);

    const grupo = (titulo, lista, classe, frase) => {
      if (!lista.length) return;
      const caixa = el('div', `bestiary-elgrupo ${classe}`);
      caixa.append(el('span', 'bestiary-elgrupo-titulo', titulo));
      const fileira = el('div', 'bestiary-elements');
      for (const [element, value] of lista) {
        const cell = el('div', `bestiary-element ${classe}`);
        // O segundo nome é o recorte do client, para os três sem desenho novo.
        cell.append(bestiaryArt(ELEMENT_ART[element] ?? 'el-physical', element));
        const fator = (1 - value / 100).toFixed(2).replace('.', ',');
        // O sinal é o do grupo, não o do número: sob "Resistências" um 20 já
        // quer dizer "tira 20%", e sob "Fraquezas" quer dizer "põe 20%".
        cell.append(el('b', null, `${Math.abs(value)}%`));
        cell.append(el('em', null, ELEMENT_LABEL[element] ?? element));
        tipTexto(cell, frase(ELEMENT_LABEL[element] ?? element, Math.abs(value), fator));
        fileira.append(cell);
      }
      caixa.append(fileira);
      detail.append(caixa);
    };

    grupo(
      'Resistências',
      resiste,
      'resist',
      (nome, quanto, fator) => `${nome}: ela resiste.
O seu dano deste tipo cai ${quanto}% — sai x${fator}.`
    );
    grupo(
      'Fraquezas',
      fraca,
      'weak',
      (nome, quanto, fator) => `${nome}: ponto fraco.
O seu dano deste tipo sobe ${quanto}% — sai x${fator}.`
    );

    if (!todos.length) {
      detail.append(el('p', 'empty', 'Nenhum elemento a favor nem contra: todo dano sai inteiro.'));
    }
  }

  // ---- loot ----
  /*
   * O teto de 40 vale para a tabela DO BICHO; as gemas vem depois dele.
   * Somadas antes, elas cairiam fora da lista nos 33 bichos cuja tabela ja
   * passa de 40 linhas — e some justamente na ficha de quem mais se olha.
   */
  const lootDaFicha = lootComGemas({ ...entry, loot: (entry.loot ?? []).slice(0, 40) });
  if (step >= 4 && lootDaFicha.length) {
    detail.append(el('h3', null, 'Loot'));
    const loot = el('div', 'bag');
    for (const drop of lootDaFicha) {
      if (!drop.id || !state.items[drop.id]) continue;
      const cell = el('div', 'cell');
      cell.append(itemCanvas(drop.id, 32));
      tipFor(cell, drop.id, `${(drop.chance * 100).toFixed(drop.chance < 0.01 ? 2 : 1)}% de chance`);
      loot.append(cell);
    }
    detail.append(loot);
  } else if (dicaDeLoot && entry.loot?.length) {
    // Só onde o loot é prêmio de bestiary. Na prévia da hunt ele está na coluna
    // ao lado, inteiro, e aí a frase mandaria completar o que já está na tela.
    detail.append(el('p', 'shop-note', 'Complete o bestiary desta criatura para ver o loot completo.'));
  }

  if (step >= 4 && entry.locations) {
    detail.append(el('h3', null, 'Onde aparece'));
    detail.append(el('p', null, entry.locations));
  }
  return detail;
}

// ---------- highscores ----------

/*
 * ---- Ajustes da barra e das janelas ----
 *
 * Era um menuzinho flutuante com um item só: uma frase inteira num retângulo
 * pendurado na engrenagem, larga demais para a fita e sem lugar para nada mais.
 * Aqui é um modal como os outros, e cabe o resto do que se quer arrumar na
 * tela: onde fica a ficha, a barra recolhida, e o arranjo das janelas.
 */
/*
 * ---- O que a tela de morte mostra, guardado no navegador ----
 *
 * A foto e o resumo são de quem quer ver. Quem morre trinta vezes por noite
 * treinando não quer o extrato inteiro em cada uma — o dono pediu a opção de
 * ocultar para sempre, e a de trazer de volta.
 *
 * Fica no navegador (e não no personagem) porque é preferência de TELA, não de
 * jogo: vale para todos os personagens da conta e não custa uma ida ao
 * servidor. Ler dentro de um `try` porque em aba anônima o acesso pode estourar.
 */
const CHAVE_DO_RESUMO = 'draevor:morte-resumo';

export function resumoDaMorteLigado() {
  try {
    return localStorage.getItem(CHAVE_DO_RESUMO) !== 'off';
  } catch {
    return true;
  }
}

export function ligarResumoDaMorte(ligado) {
  try {
    localStorage.setItem(CHAVE_DO_RESUMO, ligado ? 'on' : 'off');
  } catch {
    /* aba anônima: a preferência vale só para esta sessão */
  }
}

/*
 * ---- "Tem que ter a opção na config de sempre ocultar o card de boss" ----
 *
 * O cartaz do boss que nasce na área é um aviso para quem está caçando noutro
 * lugar — e para quem NÃO está, ele é um retângulo que aparece sozinho em cima
 * do mapa uma vez por dia. Quem não quiser, desliga.
 *
 * Fica no `localStorage`, como o resumo da morte logo acima e pelo mesmo
 * motivo: é preferência de TELA, não de personagem. Vale para todos os
 * personagens da conta, não custa uma ida ao servidor e não vira coluna no
 * banco.
 *
 * Ligado por padrão: quem não sabe que a opção existe tem de continuar vendo o
 * aviso, que é para o que ele serve.
 */
const CHAVE_DO_CARTAZ_DE_BOSS = 'draevor:cartaz-de-boss';

export function cartazDeBossLigado() {
  try {
    return localStorage.getItem(CHAVE_DO_CARTAZ_DE_BOSS) !== 'off';
  } catch {
    return true;
  }
}

export function ligarCartazDeBoss(ligado) {
  try {
    localStorage.setItem(CHAVE_DO_CARTAZ_DE_BOSS, ligado ? 'on' : 'off');
  } catch {
    /* aba anônima: a preferência vale só para esta sessão */
  }
}

/*
 * ---- Como a raridade aparece no ícone ----
 *
 * O dono: "sempre deixar nos itens anel na moldura". Havia quatro desenhos para
 * escolher nas configurações (sopro, anel, quina, nenhum); agora é o ANEL para
 * todos, em todo item — o comum também, em cinza. As regras moram no
 * `style.css`, escolhidas pelo atributo `data-raridade` do `<html>`.
 */
export function estiloDaRaridade() {
  return 'anel';
}

/** Põe o estilo no `<html>`. Chamada na entrada, antes de a mochila existir. */
export function aplicarEstiloDaRaridade() {
  document.documentElement.dataset.raridade = estiloDaRaridade();
}

/** A tela cheia de verdade, a do navegador. `null` quando ele não deixa. */
const telaCheiaLigada = () => !!document.fullscreenElement;

/*
 * ---- OS AJUSTES DA TELA, POR ABAS ----
 *
 * "faz as configurações lá da engrenagem ser separado e tals, tá muito
 *  desorganizado, faz por abas igual config de jogo mesmo"
 *
 * Eram NOVE seções numa rolagem só: onde a ficha do personagem mora, os
 * relógios, a barra de ações, a assistência da caça, a tela cheia, a tela de
 * morte, a raridade dos itens, as janelas soltas e os gráficos. Uma atrás da
 * outra, sem nada dizendo onde um assunto acaba e o outro começa — quem
 * procurava uma coisa específica rolava a janela inteira lendo título por
 * título, e quem não sabia que uma opção existia nunca a encontrava.
 *
 * Agora são quatro abas, na MESMA fileira que o resto do jogo usa (`tabBar`):
 * o mesmo desenho de Aventuras, de Tarefas e da loja. Não é uma tela nova para
 * aprender — é a tela de sempre, dividida.
 *
 *   Interface — onde cada coisa FICA: a ficha, os relógios, a barra, a marca
 *               de raridade nos itens.
 *   Gráficos  — o que o jogo DESENHA, e a tela cheia.
 *   Janelas   — as janelas que se arrasta pela tela, e o arranjo salvo.
 *   Jogo      — o que o jogo FAZ sozinho: a assistência da caça online e o
 *               que aparece ao morrer.
 *
 * ---- Uma função por aba, e não um `if` gigante ----
 *
 * A parte "desorganizado" não era só da tela: eram 400 linhas dentro de um
 * `draw` só, e achar a seção da raridade no meio delas era o mesmo problema que
 * o jogador tinha na tela. Cada aba virou uma função com nome, e a de baixo só
 * escolhe qual chamar.
 *
 * As duas conferências que isto exige — que toda aba da fileira tenha uma
 * função, e que nenhuma seção tenha se perdido na mudança — moram no
 * `test-graficos`.
 */

/** As abas, na ordem em que aparecem na fileira. */
export const ABAS_DOS_AJUSTES = {
  interface: 'Interface',
  graficos: 'Gráficos',
  janelas: 'Janelas',
  jogo: 'Jogo',
};

/*
 * As três peças que toda aba usa. Elas nascem presas ao `body` da aba que está
 * sendo desenhada, e é por isso que são uma fábrica e não constantes soltas.
 */
function pecasDosAjustes(body, draw) {
  /*
   * Uma caixa por aba, e não as seções soltas no `#modal-body`.
   *
   * Ela existe para o CSS ter onde segurar uma altura mínima: "Janelas" tem uma
   * seção e "Interface" tem quatro, e sem isso a janela encolhia e crescia a
   * cada clique na fileira — com o botão da aba seguinte saindo de baixo do
   * ponteiro no meio do caminho.
   *
   * Uma classe no próprio `#modal-body` resolveria igual e seria um vazamento:
   * o corpo é o mesmo de todos os modais e `openModal` limpa o conteúdo dele,
   * não as classes.
   */
  const painel = el('div', 'ajustes-painel');
  body.append(painel);

  const secao = (titulo, ...filhos) => {
    const caixa = el('div', 'ajustes-secao');
    caixa.append(el('div', 'ajustes-titulo', titulo));
    caixa.append(...filhos);
    painel.append(caixa);
    return caixa;
  };

  const linha = (rotulo, dica, botao) => {
    const item = el('div', 'ajustes-linha');
    const texto = el('div', 'ajustes-texto');
    texto.append(el('b', null, rotulo), el('span', null, dica));
    item.append(texto, botao);
    return item;
  };

  /*
   * `ficha` é o botão que MOSTRA o estado sendo aceso ou apagado, e o balão
   * carrega a explicação que ocuparia uma linha inteira: quem já sabe não lê, e
   * quem não sabe passa o mouse.
   *
   * `fichaEm` recebe a FILEIRA e devolve o botão daquela fileira. Havia duas
   * cópias desta função — uma nos relógios, outra nos gráficos, iguais menos
   * pelo nome —, e a segunda nasceu porque a primeira estava presa à fileira
   * dela. Uma terceira fileira ia nascer com a terceira cópia.
   */
  const fichaEm = (onde) => (rotulo, ligada, dica, aoClicar) => {
    const botao = el('button', `ajustes-ficha${ligada ? ' acesa' : ''}`, rotulo);
    botao.type = 'button';
    tipTexto(botao, dica);
    botao.onclick = () => {
      aoClicar();
      draw();
    };
    onde.append(botao);
    return botao;
  };

  return { secao, linha, fichaEm };
}

/*
 * ---- A aba Interface: onde cada coisa fica na tela ----
 *
 * É a primeira porque é a que se mexe: a ficha do personagem, os relógios de
 * buff, a barra de ações e a marca de raridade dos itens. Todas respondem à
 * mesma pergunta — "onde isso aparece?" —, e nenhuma delas muda o que o jogo
 * faz.
 */
function abaDeInterface(body, draw) {
  const { secao, linha, fichaEm } = pecasDosAjustes(body, draw);

  /*
   * ---- No telefone: o que é do telefone, e nada do que não é ----
   *
   * O analógico (desligado de saída: tocar no mapa já anda) mora aqui e no
   * "Mais". A "Ficha do personagem" (canto ou barra de baixo) não existe no
   * telefone — o status é a faixa de cima — então a seção nem aparece.
   */
  if (ehTelefone()) {
    const ligado = analogicoLigado();
    const trocar = el('button', ligado ? 'primary' : 'ghost', ligado ? 'Ligado' : 'Desligado');
    trocar.onclick = () => {
      ligarAnalogico(!ligado);
      draw();
    };
    secao(
      'Celular',
      linha('Analógico', 'Um controle de andar em cima do mapa. Sem ele, tocar no chão já leva o personagem até lá.', trocar)
    );
  }

  // ---- onde a ficha do personagem fica ----
  const encaixada = ajustesDaBarra.fichaEncaixada?.() ?? false;
  const trocarFicha = el(
    'button',
    encaixada ? 'ghost' : 'primary',
    encaixada ? 'Mandar para o canto' : 'Trazer para a barra'
  );
  trocarFicha.onclick = () => {
    ajustesDaBarra.encaixarFicha?.(!encaixada);
    draw();
  };
  if (!ehTelefone()) secao(
    'Ficha do personagem',
    linha(
      encaixada ? 'Encaixada na barra de baixo' : 'No canto superior esquerdo',
      'Vida, mana, experiência e stamina andam junto com ela.',
      trocarFicha
    )
  );

  // ---- o chat transparente e flutuante (também no ◐ do cabeçalho do chat) ----
  const flutua = chatFlutuante();
  const trocarChat = el('button', flutua ? 'primary' : 'ghost', flutua ? 'Ligado' : 'Desligado');
  trocarChat.onclick = () => {
    ligarChatFlutuante(!flutua);
    draw();
  };
  secao(
    'Chat',
    linha(
      'Transparente e flutuante',
      'Sem moldura nem fundo, com as falas por cima do mapa. As falas somem depois de alguns segundos, e as abas e a caixa de texto aparecem ao passar o mouse ou apertar Enter.',
      trocarChat
    )
  );

  /*
   * ---- Os relógios, numa linha só ----
   *
   * "em vez de configurações ter tantas linhas, tenta otimizar pra ficar em
   *  uma linha só — está muito poluído."
   *
   * Eram oito linhas: onde aparece, deitada ou em pé, três de tamanho,
   * voltar ao lugar e uma por grupo. Cada uma com título, frase e botão —
   * numa seção que fala de uma coisa só.
   *
   * Agora é UMA linha (o modo, que é a escolha que manda) e uma fileira de
   * fichas embaixo dela. Ficha acesa é ligada, apagada é desligada: o
   * estado é a própria aparência, e não uma frase dizendo o estado. Cabe
   * tudo em duas alturas de texto, e ninguém precisa ler para saber o que
   * está ligado.
   *
   * As fichas de arranjo e tamanho só aparecem no modo de pílulas, porque é
   * só lá que elas querem dizer alguma coisa.
   */
  const modo = modoDosEfeitos();
  const escolhaDoModo = el('div', 'ajustes-tamanhos');
  for (const opcao of MODOS_DE_EFEITO) {
    const botao = el('button', opcao.id === modo ? 'primary' : 'ghost', opcao.nome);
    botao.onclick = () => {
      trocarModoDosEfeitos(opcao.id);
      setVisible('buffs', opcao.id === 'janela');
      draw();
    };
    escolhaDoModo.append(botao);
  }
  const relogios = secao(
    'Relógios na tela',
    linha(
      MODOS_DE_EFEITO.find((o) => o.id === modo)?.nome ?? '',
      `${MODOS_DE_EFEITO.find((o) => o.id === modo)?.dica ?? ''} Buff Power, boosts de experiência e os passes.`,
      escolhaDoModo
    )
  );

  const fichas = el('div', 'ajustes-fichas');
  /*
   * `ficha` é o botão que MOSTRA o estado sendo aceso ou apagado. O balão
   * carrega a explicação que antes ocupava uma linha inteira — quem já sabe
   * não lê, e quem não sabe passa o mouse.
   */
  const ficha = fichaEm(fichas);

  if (modo === 'janela') {
    const aberta = isVisible('buffs');
    ficha(
      aberta ? 'Janela aberta' : 'Abrir janela',
      aberta,
      'A janela Buffs e Boosts, uma linha por coisa correndo. Move e redimensiona como o Analisador.',
      () => toggleWindow('buffs')
    );
  } else {
    const deitada = arranjoDasPilulas() === 'deitada';
    ficha(
      deitada ? 'Deitada' : 'Em pé',
      true,
      'Lado a lado ou uma embaixo da outra. Arraste a faixa na tela para mudá-la de lugar.',
      () => trocarArranjoDasPilulas(deitada ? 'em-pe' : 'deitada')
    );
    const tamanho = tamanhoDasPilulas();
    for (const opcao of TAMANHOS_DA_PILULA) {
      ficha(opcao.id, opcao.id === tamanho, `Tamanho ${opcao.nome.toLowerCase()}.`, () =>
        trocarTamanhoDasPilulas(opcao.id)
      );
    }
    if (posicaoDasPilulas()) {
      ficha('Voltar ao lugar', false, 'Devolve a faixa para o alto e no meio da tela.', () =>
        moverPilulasParaOLugar()
      );
    }
  }

  /*
   * E os quatro grupos, na mesma fileira, separados por uma barrinha.
   *
   * A dica de cada um diz onde o número CONTINUA depois de desligado — a
   * pessoa precisa saber que não perdeu o dado, só tirou da frente.
   */
  const ondeMais = {
    buffpower: 'O tempo continua na ficha do personagem.',
    exp: 'O bônus continua na barra de experiência e na ficha.',
    instance: 'O tempo continua na aba Aventuras → Especial Hunts.',
    divina: 'O tempo continua na aba Aventuras → Especial Hunts.',
  };
  fichas.append(el('i', 'ajustes-fichas-corte'));
  for (const grupo of GRUPOS_DE_EFEITO) {
    const ligado = efeitoNaTela(grupo.id);
    ficha(grupo.nome, ligado, `${grupo.dica} ${ondeMais[grupo.id] ?? ''}`.trim(), () =>
      mostrarEfeitoNaTela(grupo.id, !ligado)
    );
  }
  /*
   * ---- E a janela Boss Cooldown, na mesma fileira ----
   *
   * "faz um modal proprio que seria o Boss Cooldown... e pra abrir esse modal
   * e' la' nas configuracoes."
   *
   * Aqui e nao numa secao propria: esta secao chama-se "Relogios na tela", e a
   * espera de um boss e' um relogio na tela. A barrinha a separa dos grupos de
   * efeito porque ela e' outra janela, e nao outro grupo — a ficha dos Buffs,
   * la' em cima, e' a irma dela.
   */
  fichas.append(el('i', 'ajustes-fichas-corte'));
  const bossCdAberta = isVisible('bossCd');
  ficha(
    bossCdAberta ? 'Boss Cooldown aberto' : 'Boss Cooldown',
    bossCdAberta,
    'A janela Boss Cooldown: uma linha por sala fechada, com o bicho e quanto falta para ela reabrir. Saiu do Analisador de hunt e virou janela própria.',
    () => toggleWindow('bossCd')
  );

  relogios.append(fichas);

  // ---- a barra de ações ----
  const recolhida = ajustesDaBarra.minimizada?.() ?? false;
  const trocarBarra = el('button', 'ghost', recolhida ? 'Mostrar a barra' : 'Recolher a barra');
  trocarBarra.onclick = () => {
    ajustesDaBarra.minimizar?.(!recolhida);
    draw();
  };
  secao(
    'Barra de ações',
    linha(
      recolhida ? 'Recolhida' : 'Aberta',
      'Recolhida sobram o botão de caçada e a seta que traz a barra de volta.',
      trocarBarra
    )
  );

  // A raridade dos itens não tem mais escolha: o anel na moldura vale para todos (ver `estiloDaRaridade`).
}

/*
 * ---- A aba Gráficos: o que o jogo desenha ----
 *
 * As chaves de `graficos.mjs` e a tela cheia. A tela cheia mora aqui e não em
 * "Interface" porque ela é sobre a TELA — esconder a barra do navegador e
 * devolver aquela faixa para o mapa —, e é onde qualquer cliente de jogo a põe.
 */
function abaDeGraficos(body, draw) {
  const { send } = ctx;
  const { secao, linha, fichaEm } = pecasDosAjustes(body, draw);

  /*
   * ---- Gráficos ----
   *
   * Nasceu como um botão só, "modo lite", e o dono corrigiu a mira: "não
   * era pro jogo ficar sem fps, era pra tirar os efeitos das magias,
   * efeitos dos ícones e etc — ou faz uma aba em opções de gráficos que aí
   * a pessoa vai tirando o que quer".
   *
   * São as duas coisas, e nesta ordem: o botão para quem quer resolver, as
   * fichas para quem quer escolher. Quem abre por causa de um PC ruim
   * clica em "Deixar leve" e acabou; quem só não suporta o ícone que pisca
   * apaga aquela ficha e não perde o resto.
   *
   * A seção fica por ÚLTIMO na janela de propósito. As de cima são gosto —
   * onde a ficha mora, quais relógios aparecem. Esta é uma troca, e uma
   * troca não deve ser a primeira coisa que alguém encontra.
   *
   * ---- Por que fichas, e não uma linha por chave ----
   *
   * "em vez de configurações ter tantas linhas, tenta otimizar pra ficar em
   *  uma linha só — está muito poluído."
   *
   * São seis chaves: seis linhas com título, frase e botão seriam metade da
   * janela. Ficha acesa é ligada, apagada é desligada — o estado é a própria
   * aparência —, e a explicação de cada uma mora no balão, como nos
   * relógios logo acima.
   */
  const leve = noModoLeve();
  const botaoLeve = el('button', leve ? 'primary' : 'ghost', leve ? 'Está leve' : 'Deixar leve');
  botaoLeve.onclick = () => {
    deixarLeve(!leve);
    ctx.notice?.(
      leve
        ? 'Efeitos de volta.'
        : 'Pronto — sem efeitos de magia, projéteis, brilhos nem animações. Os quadros continuam os mesmos.'
    );
    draw();
  };
  const graficos = secao(
    'Gráficos',
    linha(
      leve ? 'Sem enfeite nesta máquina' : 'Completo',
      'Tira os efeitos de magia, os projéteis, os brilhos e as animações da interface de uma vez. ' +
        'Não mexe nos quadros: o jogo fica mais leve sem ficar travado. Vale só neste navegador.',
      botaoLeve
    )
  );

  const fichasDoGrafico = el('div', 'ajustes-fichas');
  const fichaDoGrafico = fichaEm(fichasDoGrafico);
  for (const chave of GRAFICOS) {
    const acesa = graficoLigado(chave.id);
    fichaDoGrafico(chave.nome, acesa, chave.dica, () =>
      // A do ritmo é a única que o servidor precisa saber; ver `trocarGrafico`.
      trocarGrafico(chave.id, !acesa, (economico) => send({ t: 'lite', on: economico }))
    );
  }

  /*
   * ---- E o teto de quadros, atrás de uma barrinha ----
   *
   * Ele fica SEPARADO das outras fichas, e não misturado no meio delas, porque
   * é de outra natureza: as seis de cima tiram coisas da tela, esta mexe na
   * fluidez de tudo o que ficou. Nasce em "Sem limite" — quem não souber o que
   * é, não precisa saber.
   *
   * "Sem limite" é o primeiro e é o padrão porque é o que o jogo sempre fez: o
   * mapa é pintado em `requestAnimationFrame`, no ritmo do monitor. Num monitor
   * de 144Hz isso já são 144 quadros por segundo, e nenhum número desta fileira
   * faz o jogo passar do que o monitor entrega. Ver `TETOS`, em `graficos.mjs`.
   */
  fichasDoGrafico.append(el('i', 'ajustes-fichas-corte'));
  const teto = tetoDeQuadros();
  /*
   * O ritmo medido do monitor entra na dica do "Sem limite".
   *
   * "eu acho que tá sempre limitando 60 fps mesmo que eu coloque 144 ou sem
   *  limite" — e não dava para saber olhando: 60 na tela pode ser um teto que
   * alguém pôs ou um monitor que entrega 60, e as duas coisas se parecem. Com o
   * número aqui, a pergunta se responde sem precisar de mim.
   */
  const doMonitor = quadrosDoMonitor();
  for (const opcao of TETOS) {
    fichaDoGrafico(
      rotuloDoTeto(opcao),
      opcao === teto,
      opcao === 0
        ? 'O ritmo do seu monitor, sem teto nenhum — o jogo desenha tão rápido quanto a sua tela atualiza. É o normal. ' +
          (doMonitor ? `A sua está entregando cerca de ${doMonitor} por segundo agora.` : '')
        : `Segura o desenho do mapa em ${opcao} por segundo. Alivia a placa de vídeo; em troca o passo do boneco fica menos liso. ` +
          'Nunca passa do que o seu monitor entrega, e o valor real é o degrau mais perto que ele permite.',
      () => trocarTeto(opcao)
    );
  }
  graficos.append(fichasDoGrafico);

  /*
   * ---- O contador do canto ----
   *
   * "faz uma opção pra ativar de mostrar o fps e ping no cantinho superior
   *  esquerdo, e escolhe se quer que mostra fps+ping"
   *
   * Seção própria, e não mais uma fileira dentro de Gráficos, porque a regra
   * das fichas se inverte aqui: lá em cima acesa quer dizer "o jogo está
   * inteiro" e apagar alivia; aqui acesa PÕE uma coisa na tela. Duas regras
   * opostas na mesma fileira não se leem.
   *
   * As duas são independentes: fps sozinho, ping sozinho, os dois ou nenhum
   * saem sozinhos de duas fichas, sem um seletor de quatro posições.
   */
  const fichasDoMedidor = el('div', 'ajustes-fichas');
  const fichaDoMedidor = fichaEm(fichasDoMedidor);
  for (const chave of MEDIDORES) {
    const acesa = medidorLigado(chave.id);
    fichaDoMedidor(chave.nome, acesa, chave.dica, () => {
      trocarMedidor(chave.id, !acesa);
      // Quem põe e tira o elemento da tela é o medidor; o painel só avisa.
      atualizarMedidor();
    });
  }
  secao(
    'Contador no canto',
    el(
      'p',
      'gate-note',
      'Aparece pequeno no canto superior esquerdo. O FPS diz se o peso é da sua máquina, e o ping ' +
        'diz se a demora é da sua internet — juntos eles separam as duas coisas. ' +
        'Com o ping apagado o jogo não manda nenhuma mensagem a mais.'
    ),
    fichasDoMedidor
  );

  /*
   * ---- Tela cheia ----
   *
   * É o F11 do navegador, pedido de dentro do jogo. Vale a pena estar aqui
   * porque no celular não existe F11, e porque a barra do navegador come
   * uma faixa da tela justamente em cima do mapa.
   *
   * O pedido PRECISA sair de um clique — o navegador recusa fullscreen que
   * não venha de um gesto do usuário —, e é por isso que ele mora num botão
   * e não numa preferência que se aplica sozinha ao entrar.
   */
  if (document.documentElement.requestFullscreen) {
    const cheia = telaCheiaLigada();
    const trocarTela = el('button', cheia ? 'ghost' : 'primary', cheia ? 'Sair da tela cheia' : 'Entrar em tela cheia');
    trocarTela.onclick = async () => {
      try {
        if (cheia) await document.exitFullscreen();
        else await document.documentElement.requestFullscreen();
      } catch {
        ctx.notice?.('O navegador não deixou entrar em tela cheia.');
      }
      // O navegador leva um quadro para trocar de estado; o desenho espera.
      setTimeout(draw, 150);
    };
    secao(
      'Tela cheia',
      linha(
        cheia ? 'Ligada' : 'Desligada',
        'Esconde a barra do navegador e devolve essa faixa para o mapa. Esc sai a qualquer momento.',
        trocarTela
      )
    );
  }
}

/*
 * ---- A aba Janelas: as que se arrasta pela tela ----
 *
 * Uma seção só, e uma aba só para ela. Elas são de outra natureza que o resto:
 * chat, inventário, bolsa e analisador não têm "ligado/desligado" — têm um
 * LUGAR, que a pessoa escolhe arrastando e que se guarda ou se devolve ao de
 * fábrica. Enfiada no meio da Interface, essa diferença sumia.
 */
function abaDeJanelas(body, draw) {
  const { secao, linha, fichaEm } = pecasDosAjustes(body, draw);

  // ---- as janelas soltas pela tela ----
  const salvar = el('button', 'ghost', 'Salvar este arranjo');
  salvar.title = 'guarda onde cada janela está agora, para o "reorganizar" voltar aqui';
  salvar.onclick = () => {
    const quantas = savePreset();
    ctx.notice?.(`Arranjo salvo com ${quantas} janelas.`);
  };
  const restaurar = el('button', 'ghost', 'Reorganizar');
  restaurar.title = 'devolve as janelas para o arranjo salvo, ou para o de fábrica';
  restaurar.onclick = () => {
    resetLayout();
    ctx.notice?.('Janelas reorganizadas.');
  };
  const esquecer = el('button', 'ghost', 'Esquecer o arranjo salvo');
  esquecer.onclick = () => {
    clearPreset();
    ctx.notice?.('Arranjo salvo apagado — "reorganizar" volta ao de fábrica.');
  };

  const botoes = el('div', 'ajustes-botoes');
  botoes.append(salvar, restaurar, esquecer);
  secao(
    'Janelas',
    el('p', 'gate-note', 'Chat, inventário, bolsa de loot e analisador podem ser arrastados e redimensionados.'),
    botoes
  );
}

/*
 * ---- A aba Jogo: o que ele faz sozinho ----
 *
 * As duas únicas opções daqui que não são desenho. A assistência decide se a
 * sua barra dispara sem você mandar, e a tela de morte decide o que você vê
 * quando o pior acontece.
 *
 * A assistência só aparece caçando ONLINE. Na automática a barra já dispara
 * sozinha, e um interruptor para ligar o que já está ligado não diz nada — mas
 * uma aba não pode ficar vazia por causa disso, e é por isso que a tela de
 * morte mora aqui e não em Interface.
 */
function abaDeJogo(body, draw) {
  const { state, send } = ctx;
  const { secao, linha, fichaEm } = pecasDosAjustes(body, draw);

  /*
   * ---- A assistencia da Caca Online ----
   *
   * Ela morava num botao encaixado entre os controles e os doze slots, e o
   * texto dele mudava de tamanho ao ligar — a barra inteira pulava de lugar
   * a cada clique. E' um ajuste, e ajuste mora aqui: esta tela e' a mesma
   * que o botao "Opcoes" da barra de cima abre.
   *
   * So' aparece na Caca Online. Na automatica a barra ja dispara sozinha, e
   * um interruptor para ligar o que ja esta ligado nao diz nada.
   */
  /*
   * ---- Dois interruptores, e em qualquer lugar (15/09) ----
   *
   * O dono: "no modo caça online, na sala de boss diário, em tudo que a pessoa
   * controla manualmente, tem que ter uma opção de ataque automático e de barra
   * de habilidade automática". Eram um só ("Assistência") e só apareciam
   * caçando online. Agora aparecem sempre: fora da caçada a escolha fica
   * guardada e vale na próxima entrada. Na caçada automática tudo já é
   * automático, e a seção diz isso em vez de sumir.
   */
  const naCacadaAutomatica = !!state.hunt && !state.hunt.manual;
  const ajustes = state.character?.settings ?? {};
  const noBraco = state.hunt?.manual;
  const ataqueLigado = noBraco ? !!state.hunt.assistencia : !!ajustes.assistencia;
  const barraLigada = noBraco ? !!state.hunt.autoBarra : !!(ajustes.autoBarra ?? ajustes.assistencia);
  const interruptor = (tipo, ligado) => {
    const botao = el('button', ligado ? 'ghost' : 'primary', ligado ? 'Desligar' : 'Ligar');
    botao.disabled = naCacadaAutomatica;
    botao.onclick = () => {
      send({ t: 'huntAssist', tipo, on: !ligado });
      // O servidor responde com o estado novo; o desenho acompanha.
      setTimeout(draw, 220);
    };
    return botao;
  };
  secao(
    'Jogo no braço (Caça Online e Boss Diários)',
    el(
      'p',
      'gate-note',
      naCacadaAutomatica
        ? 'Você está numa caçada automática: aqui o ataque e a barra já são automáticos. Estas escolhas valem quando você jogar no braço.'
        : 'Escolha o que o personagem faz sozinho quando você controla ele. A escolha fica guardada para as próximas vezes.'
    ),
    linha(
      `Ataque automático — ${ataqueLigado ? 'ligado' : 'desligado'}`,
      ataqueLigado
        ? 'O personagem escolhe o alvo sozinho pela regra de Alvo e Distância da barra, e o ataque básico sai sem clicar no bicho.'
        : 'Você escolhe o alvo clicando no bicho. O ataque básico só sai em quem você marcou.',
      interruptor('ataque', ataqueLigado)
    ),
    linha(
      `Barra de habilidades automática — ${barraLigada ? 'ligada' : 'desligada'}`,
      barraLigada
        ? 'A sua barra dispara sozinha com as condições que você configurou: magias, runas, curas e poções. As teclas continuam funcionando.'
        : 'Nada da barra sai sozinho: nem magia, nem runa, nem cura, nem poção. Só o que você apertar.',
      interruptor('barra', barraLigada)
    )
  );

  /*
   * ---- O que aparece ao morrer ----
   *
   * A caixa de "Você morreu" com a perda continua saindo sempre: ela é a
   * conta do que aconteceu, e escondê-la seria esconder um prejuízo. O que
   * se liga e desliga aqui é o EXTRA — a foto do momento e o extrato da
   * caçada.
   */
  const comResumo = resumoDaMorteLigado();
  const trocarResumo = el('button', comResumo ? 'ghost' : 'primary', comResumo ? 'Ocultar' : 'Mostrar de novo');
  trocarResumo.onclick = () => {
    ligarResumoDaMorte(!comResumo);
    draw();
  };
  secao(
    'Tela de morte',
    linha(
      comResumo ? 'Com foto e resumo da caçada' : 'Só a conta da perda',
      'A foto do instante da morte e o extrato do que a caçada rendeu até ali.',
      trocarResumo
    )
  );

  /*
   * ---- O aviso do boss que nasce na área ----
   *
   * Desligar aqui não desliga o boss: ele nasce igual, a Rotação continua
   * correndo e a barra de vida dele dentro da área continua aparecendo. O que
   * sai é só o cartaz que avisa — e é por isso que a frase diz onde ele
   * continua sendo visto, para ninguém desligar achando que perdeu o boss.
   */
  const comCartaz = cartazDeBossLigado();
  const trocarCartaz = el('button', comCartaz ? 'ghost' : 'primary', comCartaz ? 'Ocultar sempre' : 'Mostrar de novo');
  trocarCartaz.onclick = () => {
    ligarCartazDeBoss(!comCartaz);
    draw();
  };
  secao(
    'Aviso de boss na área',
    linha(
      comCartaz ? 'O cartaz aparece quando um boss nasce' : 'O cartaz nunca aparece',
      'O aviso com o desenho do boss e o loot dele, que some sozinho em um minuto. O boss nasce do mesmo jeito, e dentro da área de Boss Diários a vida dele continua na tela.',
      trocarCartaz
    )
  );
}

/**
 * A janela da engrenagem — a mesma que o botão "Opções" da barra de cima abre.
 *
 * `tabbedModal` guarda a última aba vista em `ctx.tabs.ajustes`, como faz com
 * Aventuras e Tarefas: quem entrou para mexer nos gráficos volta nos gráficos.
 */
export function openBarSettings() {
  // No telefone não há janelas para arrumar: cada tela abre por cima do jogo.
  const abas = ehTelefone()
    ? Object.fromEntries(Object.entries(ABAS_DOS_AJUSTES).filter(([id]) => id !== 'janelas'))
    : ABAS_DOS_AJUSTES;
  if (ehTelefone() && ctx.tabs.ajustes === 'janelas') ctx.tabs.ajustes = null;
  tabbedModal('Ajustes da tela', abas, 'ajustes', (body, aba, draw) => {
    /*
     * O `?? abaDeInterface` não é decoração: `ctx.tabs.ajustes` vem do estado
     * guardado, e uma aba renomeada aqui deixaria a janela em branco para quem
     * tivesse a antiga guardada — sem erro nenhum no console.
     */
    const desenhar = {
      interface: abaDeInterface,
      graficos: abaDeGraficos,
      janelas: abaDeJanelas,
      jogo: abaDeJogo,
    }[aba] ?? abaDeInterface;
    desenhar(body, draw);
  });
}


/*
 * ---- Lista de amigos ----
 *
 * A VIP list do Tibia, com solicitação: escrever um nome manda um PEDIDO, e a
 * pessoa entra na lista só quando aceita. Quem recebe vê o "+1" no ícone da
 * barra de cima até responder.
 */
export function openFriends() {
  const { state, send } = ctx;
  send({ t: 'friends', action: 'list' });

  ctx.openModal('Amigos', (body) => {
    const draw = () => {
      body.innerHTML = '';
      const dados = state.friends ?? { amigos: [], pedidos: [], enviados: [], max: 100 };

      const topo = el('div', 'amigos-topo');
      const campo = document.createElement('input');
      campo.className = 'search';
      campo.placeholder = 'nome do personagem...';
      campo.maxLength = 32;
      const adicionar = el('button', 'primary', 'Enviar pedido');
      const mandar = () => {
        const nome = campo.value.trim();
        if (!nome) return;
        send({ t: 'friends', action: 'add', name: nome });
        campo.value = '';
      };
      adicionar.onclick = mandar;
      campo.onkeydown = (evento) => {
        if (evento.key === 'Enter') mandar();
      };
      topo.append(campo, adicionar);

      /*
       * A porta da party. Ela morava numa setinha no ícone da barra e voltou
       * para cá: é o mesmo assunto — quem está com você —, e quem abre Amigos
       * já está a um clique de distância.
       */
      const verParty = el('button', 'ghost', state.character?.party ? 'Ver a party' : 'Party');
      verParty.title = 'Quem está no seu time, com vida, mana e o convite para a caçada.';
      verParty.onclick = () => openParty();
      topo.append(verParty);
      body.append(topo);

      const nomeDaVocacao = (id) => state.catalog.vocations.find((v) => v.id === id)?.name ?? '—';

      /** Uma linha de pessoa, com os botões que aquele estado permite. */
      const linhaDe = (pessoa, botoes) => {
        const linha = el('div', `amigo${pessoa.online ? ' on' : ''}`);
        linha.append(el('i', 'amigo-ponto'));
        const meio = el('div', 'amigo-meio');
        meio.append(el('b', null, pessoa.name));
        meio.append(
          el(
            'span',
            null,
            pessoa.online
              ? `${pessoa.vocationName ?? nomeDaVocacao(pessoa.vocation)} · level ${pessoa.level} · ${pessoa.hunt ? `caçando em ${pessoa.hunt}` : 'na cidade'}`
              : `${pessoa.vocationName ?? nomeDaVocacao(pessoa.vocation)} · level ${pessoa.level} · offline`
          )
        );
        linha.append(meio);
        for (const botao of botoes) linha.append(botao);
        return linha;
      };

      const secao = (titulo, pessoas, montarBotoes, vazio) => {
        if (!pessoas.length && !vazio) return;
        body.append(el('div', 'sheet-sub', `${titulo}${pessoas.length ? ` (${pessoas.length})` : ''}`));
        const caixa = el('div', 'amigos-lista');
        const ordenadas = [...pessoas].sort(
          (a, b) => Number(b.online) - Number(a.online) || a.name.localeCompare(b.name)
        );
        for (const pessoa of ordenadas) caixa.append(linhaDe(pessoa, montarBotoes(pessoa)));
        if (!ordenadas.length && vazio) caixa.append(el('p', 'empty', vazio));
        body.append(caixa);
      };

      // ---- pedidos recebidos, primeiro: são os que pedem uma resposta ----
      secao('Pedidos de amizade', dados.pedidos ?? [], (pessoa) => {
        const aceitar = el('button', 'primary amigo-acao', 'Aceitar');
        aceitar.onclick = () => send({ t: 'friends', action: 'accept', name: pessoa.name });
        const recusar = el('button', 'ghost amigo-acao', 'Recusar');
        recusar.onclick = () => send({ t: 'friends', action: 'decline', name: pessoa.name });
        return [aceitar, recusar];
      });

      // ---- os amigos de verdade ----
      secao(
        'Amigos',
        dados.amigos ?? [],
        (pessoa) => {
          const botoes = [];

          /*
           * ---- Convidar para a party sai daqui ----
           *
           * É onde a pessoa já está quando pensa em montar time: a lista de
           * amigos, olhando quem está online. Mandá-la a outra tela para
           * escrever de novo um nome que está na frente dela seria trabalho
           * que a lista já fez.
           *
           * O botão só existe para quem está online e ainda não é da party —
           * um convite que vai ser recusado do outro lado é pior do que botão
           * nenhum.
           */
          const naParty = (state.character?.party?.membros ?? []).some((m) => m.name === pessoa.name);
          if (pessoa.online && !naParty) {
            const chamar = el('button', 'ghost amigo-acao', 'Party');
            chamar.title = `convidar ${pessoa.name} para a sua party`;
            chamar.onclick = () => send({ t: 'grupo', action: 'convidar', name: pessoa.name });
            botoes.push(chamar);
          } else if (naParty) {
            const selo = el('span', 'party-selo', 'na party');
            botoes.push(selo);
          }

          const tirar = el('button', 'ghost amigo-tirar', '✕');
          tirar.title = `tirar ${pessoa.name} da lista`;
          tirar.onclick = () => send({ t: 'friends', action: 'remove', name: pessoa.name });
          botoes.push(tirar);
          return botoes;
        },
        'Sua lista está vazia. Escreva o nome de alguém acima.'
      );

      // ---- o que eu pedi e ainda não foi respondido ----
      secao('Pedidos enviados', dados.enviados ?? [], (pessoa) => {
        const cancelar = el('button', 'ghost amigo-acao', 'Cancelar');
        cancelar.onclick = () => send({ t: 'friends', action: 'remove', name: pessoa.name });
        return [el('em', 'amigo-espera', 'esperando'), cancelar];
      });

      body.append(el('p', 'gate-note', `${(dados.amigos ?? []).length} de ${dados.max ?? 100} nomes.`));
    };
    ctx.redraw = draw;
    draw();
  });
}

export function openRanking() {
  const { state, send } = ctx;
  send({ t: 'ranking', category: ctx.tabs.ranking ?? 'exp' });

  ctx.openModal('Highscores', (body) => {
    const draw = () => {
      body.innerHTML = '';
      const categories = {
        exp: 'Experiência',
        level: 'Level',
        magic: 'Magic',
        ...Object.fromEntries(state.catalog.skills.map((skill) => [skill, skill])),
      };
      /*
       * A arte de cada aba, com o nome que ela tem na pasta. São as mesmas
       * figuras da ficha do personagem e da barra de perícias — a mesma coisa
       * medida em dois lugares deve ter o mesmo desenho nos dois.
       */
      const icones = {
        exp: 'ficha-exp',
        level: 'ficha-level',
        magic: 'sk-magic',
        ...Object.fromEntries(state.catalog.skills.map((skill) => [skill, `sk-${skill}`])),
      };
      const abas = tabBar(
        categories,
        ctx.tabs.ranking ?? 'exp',
        (category) => {
          ctx.tabs.ranking = category;
          send({ t: 'ranking', category });
        },
        icones
      );
      // Dez abas numa fileira só: a arte encolhe, senão cada botão fica com
      // trinta pixels de largura e o nome da perícia quebra em três linhas.
      abas.classList.add('tabs-miudas');
      body.append(abas);

      const table = el('table', 'list');
      const head = el('tr');
      for (const label of ['#', 'personagem', 'vocação', 'level', 'valor']) head.append(el('th', null, label));
      table.append(head);

      (state.ranking ?? []).forEach((entry, index) => {
        const row = el('tr');
        const name = el('td', entry.name === state.character.name ? 'me' : null, entry.name);
        if (entry.online) name.textContent += ' •';
        row.append(
          el('td', 'num', index + 1),
          name,
          el('td', null, entry.vocationName ?? state.catalog.vocations.find((v) => v.id === entry.vocation)?.name ?? '—'),
          el('td', 'num', entry.level),
          el('td', 'num', money(entry.value))
        );
        table.append(row);
      });
      body.append(table);
    };
    ctx.redraw = draw;
    draw();
  });
}

// ---------- reportar bug ou ideia ----------

/*
 * ---- A janela de report ----
 *
 * O jogo está em beta e o aviso disso está na tela o tempo todo. Faltava o
 * outro lado: um jeito de responder.
 *
 * Três decisões que valem escrever:
 *
 * 1. O PRINT É OPCIONAL, e há três jeitos de anexá-lo — colar (Ctrl+V), escolher
 *    um arquivo, ou pegar o que está no mapa agora. Quem acabou de ver um bug já
 *    apertou PrintScreen; pedir para salvar num arquivo antes seria pedir para
 *    desistir.
 *
 * 2. A IMAGEM É REDUZIDA AQUI, e não no servidor. Print de tela 4K em PNG passa
 *    de 8 MB; reduzido a 1280 de largura em JPEG ele fica em algumas centenas de
 *    KB sem perder nada do que interessa (é uma tela, não uma fotografia). O
 *    servidor tem teto próprio, mas chegar lá com 8 MB para ser recusado é
 *    desperdiçar a conexão de quem está reportando.
 *
 * 3. O CONTEXTO VAI SOZINHO e está ESCRITO na tela. Tamanho de janela,
 *    navegador, onde o personagem estava: é o que transforma "bugou" em algo
 *    consertável, e o jogador não tem como saber que importa. Mostrar o que vai
 *    junto é o mínimo — mandar dados de alguém sem dizer quais seria outra
 *    coisa.
 */
const REPORT_TIPOS = [
  { id: 'bug', nome: 'Bug', resumo: 'Algo quebrou, sumiu ou fez o que não devia.' },
  { id: 'melhoria', nome: 'Ideia de melhoria', resumo: 'Algo que funciona e poderia ser melhor.' },
];

/** Reduz e recodifica a imagem, para o print caber na conexão de quem manda. */
async function encolherImagem(fonte, larguraMax = 1280) {
  const bitmap = await createImageBitmap(fonte);
  const escala = Math.min(1, larguraMax / bitmap.width);
  const tela = document.createElement('canvas');
  tela.width = Math.round(bitmap.width * escala);
  tela.height = Math.round(bitmap.height * escala);
  tela.getContext('2d').drawImage(bitmap, 0, 0, tela.width, tela.height);
  bitmap.close?.();
  return tela.toDataURL('image/jpeg', 0.82);
}

/*
 * ---- A TELA INTEIRA, com as janelas onde o jogador as deixou ----
 *
 * O print do mapa é o `<canvas>` do jogo e sai de graça — mas ele mostra só o
 * mapa. Metade do que se reporta não está lá: é um modal cortado, um botão por
 * cima de outro, um número errado dentro de uma janela. Nada disso aparece num
 * `toDataURL` do canvas, porque nada disso é canvas: o HUD inteiro é DOM.
 *
 * Não existe jeito de rasterizar DOM no navegador sem biblioteca — o truque do
 * `foreignObject` desenharia o texto e perderia justamente o que importa aqui
 * (as molduras vêm de `url()`, e um SVG isolado não busca arquivo nenhum; os
 * ícones do inventário são canvas, que dentro dele saem em branco).
 *
 * Então quem tira a foto é o próprio navegador, pela captura de tela. Custa uma
 * permissão — e ela é pedida no momento certo, com o jogador já decidido a
 * mandar um print. Se ele recusar, o report vai assim mesmo, só com o mapa: a
 * foto é um acessório, e perder um acessório não pode custar a mensagem.
 *
 * A janela do report se esconde durante o clique do obturador. Sem isso, a foto
 * da tela seria a foto da própria caixa de report — o único pedaço da tela que
 * não interessa a ninguém.
 */
/**
 * Espera `quantos` quadros NOVOS saírem do stream de captura.
 *
 * Sem `requestVideoFrameCallback` (Firefox, por exemplo) não há como saber, e o
 * relógio é a única resposta honesta. Ver a nota em `pegarATelaInteira`.
 */
function esperarQuadroLimpo(video, quantos) {
  if (typeof video.requestVideoFrameCallback !== 'function') {
    return new Promise((pronto) => setTimeout(pronto, 400));
  }
  return new Promise((pronto) => {
    let faltam = quantos;
    // Rede de segurança: um stream que parou de entregar quadros (aba ao fundo,
    // monitor dormindo) não pode travar o report para sempre.
    const desistir = setTimeout(pronto, 1200);
    const proximo = () => {
      if (--faltam > 0) return void video.requestVideoFrameCallback(proximo);
      clearTimeout(desistir);
      pronto();
    };
    video.requestVideoFrameCallback(proximo);
  });
}

async function pegarATelaInteira() {
  if (!navigator.mediaDevices?.getDisplayMedia) return null;
  const modal = document.getElementById('modal');
  let stream = null;
  /*
   * ---- A caixa some ANTES de pedir a permissão ----
   *
   * Ela sumia depois, entre abrir o stream e desenhar o quadro, e as duas
   * tentativas de acertar esse instante falharam: primeiro dois
   * `requestAnimationFrame`, depois três quadros do próprio stream. Nas duas a
   * foto saiu com a caixa do report no meio, e com o botão escrito "Capturando
   * a tela..." — o retrato de um instante anterior ao esconder.
   *
   * A lição é que não há instante certo: entre o compositor da página, o
   * buffer do stream e a latência da captura há folga demais para adivinhar. O
   * jeito de não errar é não ter o que acertar — se a caixa já está invisível
   * quando o stream começa, nenhum quadro dele pode contê-la.
   *
   * O preço é a caixa sumir da tela enquanto o navegador pergunta "quer
   * compartilhar esta aba?". É pouco: a pergunta cobre a tela de qualquer
   * forma, e a caixa volta inteira — com as miniaturas — assim que ela é
   * respondida. `visibility` e não `hidden`, para o layout de trás não se mexer.
   */
  if (modal) modal.style.visibility = 'hidden';
  try {
    stream = await navigator.mediaDevices.getDisplayMedia({
      audio: false,
      video: { displaySurface: 'browser' },
      // Chrome já deixa a aba atual escolhida no seletor; os outros dois campos
      // tiram do caminho as opções que não servem aqui (trocar de aba no meio,
      // capturar o monitor inteiro).
      preferCurrentTab: true,
      selfBrowserSurface: 'include',
      surfaceSwitching: 'exclude',
    });

    const video = document.createElement('video');
    video.srcObject = stream;
    video.muted = true;
    video.playsInline = true;
    await video.play();

    /*
     * A caixa já está escondida desde antes do stream (ver o topo). O que
     * sobra é garantir que o quadro desenhado seja de DEPOIS que ele começou a
     * entregar imagem — um `drawImage` num vídeo recém-iniciado pode pegar
     * quadro vazio.
     *
     * ---- Esperar o QUADRO, e não o repinte ----
     *
     * Aqui havia dois `requestAnimationFrame`: um para o navegador repintar sem
     * a caixa, outro para o repinte chegar ao stream. O segundo é uma suposição,
     * e ela é falsa — `requestAnimationFrame` fala do desenho da PÁGINA, e o
     * stream de captura tem cadência própria, com buffer e latência de
     * compositor. `drawImage(video)` desenha o último quadro que o stream
     * entregou, que pode ser de centenas de milissegundos atrás.
     *
     * O resultado apareceu na primeira foto tirada com a captura automática: a
     * caixa do report no meio da imagem, com o botão ainda escrito "Capturando
     * a tela..." — o retrato de um instante anterior ao esconder.
     *
     * `requestVideoFrameCallback` é a pergunta certa: ele avisa quando um
     * quadro NOVO foi apresentado. Três deles, para atravessar qualquer quadro
     * que já estivesse na fila. Onde ele não existe, sobra o relógio — 400ms é
     * mais que a latência de captura de qualquer navegador que chegue aqui.
     */
    await esperarQuadroLimpo(video, 3);

    const tela = document.createElement('canvas');
    tela.width = video.videoWidth;
    tela.height = video.videoHeight;
    if (!tela.width || !tela.height) return null;
    tela.getContext('2d').drawImage(video, 0, 0);
    return await encolherImagem(tela, 1600);
  } catch {
    // Recusou, fechou o seletor, ou o navegador não deixa. Não é erro: é uma
    // resposta, e o report segue com o print do mapa.
    return null;
  } finally {
    if (modal) modal.style.visibility = '';
    for (const trilha of stream?.getTracks() ?? []) trilha.stop();
  }
}

export function openReport(tipoInicial = 'bug') {
  const { send } = ctx;
  let tipo = REPORT_TIPOS.some((t) => t.id === tipoInicial) ? tipoInicial : 'bug';
  let imagem = null;
  let imagemHud = null;
  let pedindoTela = false;

  ctx.openModal('Reportar', (body) => {
    const desenhar = () => {
      body.replaceChildren();

      const tipos = el('div', 'report-tipos');
      for (const opcao of REPORT_TIPOS) {
        const botao = el('button');
        botao.type = 'button';
        botao.setAttribute('aria-selected', String(tipo === opcao.id));
        botao.append(el('b', null, opcao.nome), el('em', null, opcao.resumo));
        botao.onclick = () => {
          tipo = opcao.id;
          desenhar();
        };
        tipos.append(botao);
      }
      body.append(tipos);

      const texto = document.createElement('textarea');
      texto.className = 'report-texto';
      texto.placeholder =
        tipo === 'bug'
          ? 'O que aconteceu? Se der, diga o que você estava fazendo antes — é o que permite repetir aqui.'
          : 'O que você mudaria, e por quê?';
      texto.value = body.dataset.rascunho ?? '';
      texto.oninput = () => (body.dataset.rascunho = texto.value);
      body.append(texto);

      /*
       * Colar direto na janela. Quem viu o bug já apertou PrintScreen — este é
       * o caminho de menos atrito, e nenhum botão o anuncia bem, então ele
       * aparece escrito no rótulo do anexo.
       */
      texto.addEventListener('paste', async (evento) => {
        const arquivo = [...(evento.clipboardData?.files ?? [])][0];
        if (!arquivo || !arquivo.type.startsWith('image/')) return;
        evento.preventDefault();
        imagem = await encolherImagem(arquivo);
        desenhar();
      });

      const anexo = el('div', 'report-anexo');
      const escolher = document.createElement('input');
      escolher.type = 'file';
      escolher.accept = 'image/*';
      escolher.hidden = true;
      escolher.onchange = async () => {
        if (escolher.files?.[0]) {
          imagem = await encolherImagem(escolher.files[0]);
          desenhar();
        }
      };
      // Verdes, como todo botão de ação do jogo: branco os deixava com cara de
      // link do navegador no meio de uma janela que não tem nenhum.
      const botaoArquivo = el('button', 'primary', imagem ? 'Trocar o print' : 'Escolher um print');
      botaoArquivo.type = 'button';
      botaoArquivo.onclick = () => escolher.click();
      anexo.append(escolher, botaoArquivo);

      /*
       * "Pegar o que está no mapa": o canvas do jogo, direto.
       *
       * É o print de um bicho no lugar errado, de um chão faltando, de um efeito
       * que não sai — e ele já entra sozinho ao abrir esta janela, porque não
       * custa permissão nenhuma e porque um print que depende de o jogador
       * lembrar de pedir é um print que quase nunca vem.
       */
      const mapa = document.getElementById('map');
      if (mapa) {
        const botaoMapa = el('button', 'primary', imagem ? 'Atualizar o mapa' : 'Pegar o mapa agora');
        botaoMapa.type = 'button';
        botaoMapa.onclick = async () => {
          imagem = await encolherImagem(mapa);
          desenhar();
        };
        anexo.append(botaoMapa);
      }
      /*
       * E a tela inteira, com as janelas. Ver `pegarATelaInteira`.
       *
       * A captura agora sai sozinha na abertura (ver o fim de `openReport`), e o
       * botão ficou para os dois casos em que ela não basta: quem recusou a
       * permissão e mudou de ideia, e quem quer a foto de OUTRO momento — abrir
       * a janela, arrumar o que quer mostrar, e refazer.
       */
      const botaoTela = el(
        'button',
        imagemHud ? 'primary' : 'primary destaque',
        pedindoTela
          ? 'Capturando a tela...'
          : imagemHud
            ? 'Refazer a foto da tela'
            : 'Fotografar a tela com as janelas'
      );
      botaoTela.type = 'button';
      botaoTela.disabled = pedindoTela;
      botaoTela.onclick = async () => {
        pedindoTela = true;
        desenhar();
        imagemHud = await pegarATelaInteira();
        pedindoTela = false;
        desenhar();
      };
      anexo.append(botaoTela);

      if (imagem || imagemHud) {
        const tirar = el('button', 'danger', 'Tirar os prints');
        tirar.type = 'button';
        tirar.onclick = () => {
          imagem = null;
          imagemHud = null;
          desenhar();
        };
        anexo.append(tirar);
      }
      anexo.append(el('em', null, 'ou cole com Ctrl+V na caixa de texto'));
      body.append(anexo);

      /*
       * As duas prévias, lado a lado e rotuladas.
       *
       * Rotuladas porque as duas fotos do mesmo instante são parecidas o
       * bastante para o jogador achar que mandou a mesma coisa duas vezes.
       */
      const previas = el('div', 'report-previas');
      for (const foto of [
        imagem ? { src: imagem, rotulo: 'mapa' } : null,
        imagemHud ? { src: imagemHud, rotulo: 'tela com as janelas' } : null,
      ].filter(Boolean)) {
        const caixa = el('figure', 'report-previa-caixa');
        const previa = document.createElement('img');
        previa.className = 'report-previa';
        previa.src = foto.src;
        previa.alt = `print anexado — ${foto.rotulo}`;
        caixa.append(previa, el('figcaption', null, foto.rotulo));
        previas.append(caixa);
      }
      if (previas.children.length) body.append(previas);

      const contexto = contextoDoReport();
      body.append(
        el(
          'p',
          'report-contexto',
          `Vai junto: ${contexto.tela}, ${contexto.navegador}, ${contexto.onde}${
            ctx.state.character ? ` — ${ctx.state.character.name}` : ''
          }.`,
        ),
      );

      const acoes = el('div', 'confirm-actions');
      const cancelar = el('button', 'danger', 'Cancelar');
      cancelar.onclick = () => ctx.closeModal();
      const enviar = el('button', 'primary', 'Enviar');
      enviar.onclick = () => {
        const corpo = texto.value.trim();
        if (corpo.length < 5) {
          texto.focus();
          return;
        }
        send({ t: 'report', tipo, texto: corpo, imagem, imagemHud, ...contexto });
        ctx.closeModal();
      };
      acoes.append(cancelar, enviar);
      body.append(acoes);
      texto.focus();
    };
    desenhar();

    /*
     * Os DOIS prints entram sozinhos, assim que a janela abre.
     *
     * O do mapa nunca custou nada e sempre foi automático. O da tela inteira era
     * um botão, e a razão escrita aqui era boa — pedir permissão sem a pessoa
     * ter pedido nada faz fechar a janela. Só que o resultado foi medido nos
     * reports que chegaram: um de três trazia o print com o HUD. E é justamente
     * ele que resolve metade dos defeitos, porque metade não está no mapa — é
     * um modal cortado, um botão sobreposto, um número errado dentro de uma
     * janela.
     *
     * O dono decidiu que a permissão pode aparecer sozinha. Continua sendo uma
     * pergunta que dá para recusar, e recusar não quebra nada: o report segue
     * com o print do mapa, como antes.
     *
     * ---- Por que os dois começam JUNTOS, e não um depois do outro ----
     *
     * `getDisplayMedia` exige "ativação transitória" — o navegador só a concede
     * enquanto o clique que abriu esta janela ainda conta, e essa janela dura
     * poucos segundos. Esperar o print do mapa terminar para então pedir a
     * permissão gastaria justamente esse tempo. Os dois saem no mesmo instante,
     * e o do mapa nem precisa de gesto nenhum.
     */
    const mapaDeAbertura = document.getElementById('map');
    if (mapaDeAbertura?.width) {
      encolherImagem(mapaDeAbertura)
        .then((foto) => {
          if (imagem) return;
          imagem = foto;
          desenhar();
        })
        .catch(() => {});
    }

    if (navigator.mediaDevices?.getDisplayMedia) {
      pedindoTela = true;
      desenhar();
      pegarATelaInteira()
        .then((foto) => {
          if (foto) imagemHud = foto;
        })
        .catch(() => {})
        .finally(() => {
          pedindoTela = false;
          desenhar();
        });
    }
  });
}

/** O que a TELA sabe e o servidor não: tamanho da janela e navegador. */
function contextoDoReport() {
  const hunt = ctx.state.hunt;
  return {
    tela: `${window.innerWidth}x${window.innerHeight}`,
    navegador: navigator.userAgent.slice(0, 180),
    versao: document.documentElement.dataset.versao ?? null,
    onde: hunt ? `hunt ${hunt.huntId}` : ctx.state.character ? 'cidade' : 'fora do personagem',
  };
}

/*
 * ---- A escolha rápida, do botão direito no boneco ----
 *
 * O mesmo conteúdo da tela de Exercise, sem o caminho até ela: quem clicou com
 * o direito no boneco já decidiu que vai treinar, e as quatro telas até lá
 * (Aventuras → Treino → Exercise → escolher) só ficam no caminho.
 *
 * É uma janela PRÓPRIA, e não a de Aventuras aberta na aba certa, porque ela
 * abre e fecha num gesto: escolheu a arma, sumiu, o treino começou. Reaproveitar
 * `escolherExercise` mantém as duas dizendo a mesma coisa — se um dia a
 * escolha ganhar um campo novo, ele aparece nas duas sem ninguém lembrar.
 */
export function openExerciseRapido() {
  // Mesma tela, mesma razão: os cartazes dizem quanto custa. Ver `openExercise`.
  ctx.send({ t: 'store' });
  ctx.openModal('Boneco de treino', (body) => {
    const desenhar = () => {
      body.replaceChildren();
      escolherExercise(body, { semVoltar: true });
    };
    ctx.redraw = desenhar;
    desenhar();
  });
}

/*
 * ---- O mesmo atalho, agora para o skill trainer ----
 *
 * "ao clicar no item da posição {32369, 32247, 7} tem que abrir a aba do treino
 * offline."
 *
 * O móvel está plantado na cidade e o caminho oficial até o que ele faz são
 * quatro telas (Aventuras → Treino → Treino offline → escolher a perícia). Quem
 * clicou nele já decidiu; é o mesmo argumento do direito no boneco de treino.
 *
 * A janela é a de AVENTURAS, e não uma janela própria como a do boneco. A
 * diferença é o "‹ voltar" que `confirmarOffline` já desenha: ele leva à lista
 * dos três modos de treino, e essa lista é a de Aventuras. Abrir isto com outro
 * título faria o botão de voltar aterrissar numa janela que nunca foi aberta.
 */
export function openTreinoOffline() {
  ctx.openModal('Aventuras', (body) => {
    const desenhar = () => confirmarOffline(body);
    ctx.redraw = desenhar;
    desenhar();
  });
}

// ---------- as recompensas de nível ----------

/*
 * ---- Um calendário, e não duas janelas ----
 *
 * São oito marcos ao todo: cinco de arma de treino (8, 20, 30, 40, 50) e três
 * de equipamento (100, 300, 400). Eles chegavam em telas diferentes, e isso
 * respondia mal à única pergunta que o jogador faz aqui — "o que eu ganho
 * subindo?". Metade da resposta em cada lugar é o mesmo que resposta nenhuma.
 *
 * Agora é uma grade só, em ordem de level, com os oito SEMPRE à vista: o do 400
 * aparece para quem está no level 12, com o outfit desenhado e "faltam 388
 * levels". Um prêmio que só se vê depois de alcançado não anima ninguém a
 * alcançá-lo — e é para isso que ele existe.
 *
 * A escolha da arma continua sendo um segundo passo, dentro da mesma janela: o
 * cartão do marco de exercício disponível leva a ela e volta. Ela não some
 * porque escolher É o presente ali — e um presente que sai uma vez na vida não
 * pode ir embora num clique errado.
 */

/** A moeda de ouro, só para o preço do marco ter cara de preço. */
const MOEDA_DE_OURO = 3031;

/** Os cinco degraus de arma de treino. O servidor manda o resto do estado. */
const DEGRAUS_DE_EXERCICIO = [8, 20, 30, 40, 50];

/*
 * O calendário, desenhado DENTRO de um corpo qualquer.
 *
 * Ele nasceu como janela própria (o presente da barra de baixo) e agora também
 * é uma aba de Tarefas — o dono quis os dois caminhos, e é justo: quem está
 * olhando as tarefas do personagem está fazendo a mesma pergunta ("o que falta
 * para mim?").
 *
 * Uma função só para os dois. Duplicar o calendário seria duplicar oito
 * cartões, a escolha da arma e a confirmação da compra — e no dia de mexer em
 * um deles, mexer em dois.
 */
export function corpoDasRecompensas(body, comFechar = true) {
  const { state, send, closeModal } = ctx;
  const presentes = state.character?.presentes;
  if (!presentes) return void body.append(el('p', 'empty', 'Nenhuma recompensa por aqui ainda.'));

  /*
   * O calendário desenha DENTRO de uma área própria, e não direto no corpo.
   *
   * Ele se redesenha inteiro a cada passo (grade → escolha da arma → confirmar
   * a compra), e fazia isso limpando o corpo da janela. Dentro da aba de
   * Tarefas o corpo é de todo mundo: junto com a grade ia embora a FILEIRA DE
   * ABAS, e quem clicasse em "Escolher" ficava preso na tela da escolha, sem
   * caminho de volta para as Tasks a não ser fechar a janela.
   */
  const area = el('div');
  body.append(area);

  const marcos = presentes.marcos ?? [];
  const meuLevel = state.character?.level ?? 0;
  const meuOuro = state.character?.gold ?? 0;
  const jaPegou = presentes.pegos ?? 0;

  /*
   * Os oito cartões, numa lista só e em ordem de level.
   *
   * O de exercício não sabe QUAL arma vai sair (a escolha é do jogador), então
   * o prêmio dele é a categoria; o de equipamento traz as peças.
   */
  /*
   * Os degraus de exercício vêm do SERVIDOR.
   *
   * A tela os escrevia à mão e marcava "pego" pela CONTAGEM — com o degrau do
   * 150 na trilha, o sexto cartão apareceria como pego assim que cinco tivessem
   * saído. Quem sabe o que já foi pego é quem guarda. Ver `presentesDe`.
   */
  const degraus =
    presentes.degraus ??
    DEGRAUS_DE_EXERCICIO.map((level, i) => ({
      level,
      custo: 0,
      pego: i < jaPegou,
      aberto: meuLevel >= level && i >= jaPegou,
    }));

  const cartoes = [
    ...degraus.map((degrau) => ({
      ...degrau,
      trilha: 'exercicio',
      titulo: degrau.boosted ? 'Exercise boosted' : 'Arma de treino',
      resumo: degrau.boosted ? 'à sua escolha — rende o dobro por carga' : 'à sua escolha, cheia de cargas',
      itens: [],
    })),
    ...marcos.map((marco) => ({ ...marco, trilha: 'equipamento', resumo: marco.tipo === 'bau' ? 'abre 1 item aleatório — com raridade' : null })),
  ].sort((a, b) => a.level - b.level);

  /* `null` = a grade; um número = a escolha da arma daquele degrau. */
  let escolhendo = null;
  let escolhido = null;
  /* E o cartão que está esperando a confirmação da compra. Ver `desenharCompra`. */
  let confirmando = null;

  const desenharCartao = (cartao) => {
    const caixa = el('div', `recompensa-cartao${cartao.pego ? ' pego' : cartao.aberto ? ' aberto' : ''}`);
    caixa.append(el('b', 'recompensa-level', `Level ${cartao.level}`));
    caixa.append(el('span', 'recompensa-titulo', cartao.titulo));

    const arte = el('div', 'recompensa-arte');
    if (cartao.trilha === 'exercicio') {
      /*
       * As quatro primeiras armas, só para dar cara ao cartão: a escolha é do
       * jogador, e mostrar as oito encheria a grade de repetição.
       *
       * O cartão do 150 desenha as BOOSTED mesmo faltando cem levels para
       * chegar nele — o desenho é metade de "o que eu ganho subindo".
       */
      const pilha = cartao.boosted ? presentes.escolhasBoosted ?? presentes.escolhas : presentes.escolhas;
      for (const escolha of (pilha ?? []).slice(0, 4)) {
        const a = itemCanvas(escolha.arte ?? escolha.itemId, 26);
        // O balão fala do ITEM, e não do desenho: `arte` é só a figura que a
        // arma usa, e algumas compartilham a mesma.
        if (a) arte.append(tipFor(a, escolha.itemId));
      }
    }
    for (const item of cartao.itens ?? []) {
      const a = itemCanvas(item.itemId, 26);
      if (a) {
        /*
         * O balão do jogo, e não o `title` do navegador.
         *
         * É o mesmo balão do set na ficha e da loja — com ataque, defesa,
         * peso e imbuements. Era o que faltava aqui: a peça aparecia
         * desenhada e sem um número, e decidir se um set vale 100k pelo
         * desenho não dá. Ver `fichaDeItem`.
         */
        arte.append(tipFor(a, item.itemId, item.count > 1 ? `${item.count} unidades` : null));
      }
    }
    if (cartao.tipo === 'outfit' && cartao.look != null && outfitInfo(cartao.look)) {
      arte.append(outfitCanvas(cartao.look, { addons: 3 }, 48));
    }
    /*
     * A montaria desenha pelo LOOK, e não pelo id.
     *
     * O id da montaria (223) não é um look de criatura — passá-lo ao
     * `outfitCanvas` devolvia canvas vazio, e o cartão do 300 saía sem
     * desenho. O servidor manda os dois agora; ver `premioDoMarco`.
     */
    if (cartao.tipo === 'montaria' && cartao.look != null && outfitInfo(cartao.look)) {
      arte.append(outfitCanvas(cartao.look, null, 48));
    }
    if (arte.childElementCount) caixa.append(arte);

    if (cartao.resumo) caixa.append(el('em', 'recompensa-resumo', cartao.resumo));
    if (cartao.tipo === 'outfit' && cartao.name) {
      caixa.append(el('em', 'recompensa-resumo', `${cartao.name} — com os 2 addons`));
    }
    if (cartao.tipo === 'montaria' && cartao.name) caixa.append(el('em', 'recompensa-resumo', cartao.name));

    /*
     * O PREÇO fica no cartão, sempre — inclusive no que ainda não abriu.
     *
     * Do marco 50 em diante o prêmio é comprado (`custoDoMarco`), e saber
     * disso com trinta levels de antecedência é o que deixa a pessoa juntar.
     * Mostrar o preço só na hora do clique seria uma recusa, e não um aviso.
     */
    const custo = cartao.custo ?? 0;
    const temOuro = !custo || meuOuro >= custo;
    if (custo && !cartao.pego) {
      const preco = el('div', `recompensa-preco${temOuro ? '' : ' curto'}`);
      const moeda = itemCanvas(MOEDA_DE_OURO, 14);
      if (moeda) preco.append(moeda);
      preco.append(el('span', null, `${custo.toLocaleString('pt-BR')} gold`));
      caixa.append(preco);
    }

    /*
     * ---- Os estados: bloqueada, disponível, resgatada — e, na montaria/outfit, onde está ----
     *
     * O selo de "pego" da montaria e do outfit vem do que o SERVIDOR leu no sistema de Aparência
     * (`entregue`, `emUso`), e não só do `pego`: resgatada e ainda não usada mostra onde equipar,
     * com um botão que abre a Aparência; sem a entrega registrada, avisa em vez de dizer "pego".
     */
    if (cartao.pego && (cartao.tipo === 'montaria' || cartao.tipo === 'outfit')) {
      const usar = cartao.tipo === 'montaria' ? 'montar' : 'vestir';
      if (cartao.entregue === false) caixa.append(el('em', 'recompensa-espera', 'resgatada — liberação pendente, entre de novo no jogo'));
      else if (cartao.emUso) caixa.append(el('em', 'recompensa-selo', 'pego · em uso'));
      else {
        caixa.append(el('em', 'recompensa-selo', 'pego'));
        const ir = el('button', 'ghost recompensa-onde', `Para ${usar}: ${cartao.onde ?? 'Personagem › Aparência'}`);
        ir.onclick = () => {
          ctx.closeModal?.();
          ctx.abrirAparencia?.();
        };
        caixa.append(ir);
      }
    } else if (cartao.pego) caixa.append(el('em', 'recompensa-selo', 'pego'));
    else if (cartao.aberto) {
      const pegar = el('button', 'recompensa-pegar', cartao.trilha === 'exercicio' ? 'Escolher' : 'Pegar');
      // Sem ouro o botão fica apagado e DIZ o quanto falta, em vez de aceitar
      // o clique para responder com um erro depois.
      pegar.disabled = !temOuro;
      if (!temOuro) tipTexto(pegar, `faltam ${(custo - meuOuro).toLocaleString('pt-BR')} gold`);
      pegar.onclick = () => {
        if (cartao.trilha === 'exercicio') {
          escolhendo = cartao.id ?? cartao.level;
          escolhido = null;
          return void desenhar();
        }
        /*
         * Nada sai no primeiro clique.
         *
         * O marco cobra ouro, e ouro é o que o jogador levou a semana para
         * juntar: um clique num cartão de calendário não pode gastar 130k sem
         * perguntar. A confirmação diz o preço, o que sobra depois, e o que
         * entra na mochila.
         */
        confirmando = cartao;
        desenhar();
      };
      caixa.append(pegar);
    } else {
      /*
       * ---- "faltam -885" ----
       *
       * Este texto dizia `cartao.level - meuLevel` sem olhar o sinal, e na
       * trilha de exercício isso vira negativo: só o degrau MAIS BAIXO em
       * aberto fica clicável (ver `presentesDe`), então quem está no level
       * 1035 e não pegou o do 20 vê o cartão do 150 fechado com "faltam -885".
       *
       * São dois motivos diferentes para o cartão estar fechado, e agora cada
       * um diz o seu: falta level, ou falta pegar o anterior.
       *
       * A classe também é outra: `recompensa-selo` virou a FAIXA de "pego" (a
       * mesma da Recompensa Diária), e este texto não é um selo — é um aviso.
       */
      const faltam = cartao.level - meuLevel;
      caixa.append(el('em', 'recompensa-espera',
        faltam > 0 ? `faltam ${faltam} levels` : 'pegue o anterior primeiro'));
    }

    return caixa;
  };

  /*
   * ---- "Confirma?" ----
   *
   * Três números e dois botões. O do meio — o que SOBRA — é o que o dono
   * pediu e é o que decide: saber que custa 130k não diz nada a quem não
   * lembra quanto tem no bolso, e é justamente na hora de comprar um set que
   * a pessoa está com o ouro das supplies da semana em cima.
   */
  const desenharCompra = () => {
    const cartao = confirmando;
    const custo = cartao.custo ?? 0;
    const sobra = meuOuro - custo;

    area.append(el('p', 'shop-note', `Marco do level ${cartao.level} — ${cartao.titulo}.`));
    if (cartao.tipo === 'bau') area.append(el('p', 'relatorio-motivo', 'Abre UM item, sorteado entre os mostrados — com raridade, faixa de valores e atributos como num drop.'));

    if (cartao.itens?.length) {
      const grade = el('div', 'recompensa-arte confirmar-itens');
      for (const item of cartao.itens) {
        const arte = itemCanvas(item.itemId, 32);
        if (arte) grade.append(tipFor(arte, item.itemId, item.count > 1 ? `${item.count} unidades` : null));
      }
      area.append(grade);
    }
    if (cartao.look != null && outfitInfo(cartao.look)) {
      const arte = el('div', 'recompensa-arte');
      arte.append(outfitCanvas(cartao.look, cartao.tipo === 'outfit' ? { addons: 3 } : null, 56));
      area.append(arte);
    }

    const conta = el('div', 'rows confirmar-conta');
    const linhaDaConta = (rotulo, valor, classe) => {
      const linha = el('div');
      linha.append(el('span', null, rotulo), el('b', classe, valor));
      conta.append(linha);
    };
    linhaDaConta('Você tem', `${meuOuro.toLocaleString('pt-BR')} gold`);
    linhaDaConta('Vai sair', `−${custo.toLocaleString('pt-BR')} gold`, 'bad');
    linhaDaConta('Vai sobrar', `${sobra.toLocaleString('pt-BR')} gold`, sobra >= 0 ? 'good' : 'bad');
    area.append(conta);

    area.append(
      el(
        'p',
        'relatorio-motivo',
        'O que não couber na mochila vai para o depósito — nada se perde. Cada marco só sai uma vez.'
      )
    );

    const acoes = el('div', 'confirm-actions');
    const cancelar = el('button', 'ghost', 'Cancelar');
    cancelar.onclick = () => {
      confirmando = null;
      desenhar();
    };
    const confirmar = el('button', 'recompensa-pegar', 'Confirmar');
    confirmar.disabled = sobra < 0;
    confirmar.onclick = () => {
      confirmar.disabled = true;
      send({ t: 'marco', id: cartao.id, level: cartao.level });
      closeModal();
    };
    acoes.append(cancelar, confirmar);
    area.append(acoes);
  };

  const desenharEscolha = () => {
    // Pelo ID: no level 50 há DUAS recompensas (a arma de treino e o baú), e o level não as separa.
    const doDegrau = cartoes.find((c) => (c.id ?? c.level) === escolhendo) ?? {};
    const custoDaEscolha = doDegrau.custo ?? 0;
    area.append(
      el(
        'p',
        'shop-note',
        `Presente do level ${doDegrau.level} — escolha uma ${doDegrau.boosted ? 'exercise boosted' : 'arma de treino'}. ` +
          `Ela vem cheia, com ${(presentes.escolhas?.[0]?.cargas ?? 64400).toLocaleString('pt-BR')} cargas` +
          (doDegrau.boosted ? ', e cada carga rende o dobro de uma durable.' : '.')
      )
    );

    const grade = el('div', 'presente-escolha');
    for (const escolha of presentes.escolhas ?? []) {
      const botao = el('button');
      botao.setAttribute('aria-selected', String(escolhido === escolha.itemId));
      const arte = itemCanvas(escolha.arte ?? escolha.itemId, 40);
      if (arte) botao.append(tipFor(arte, escolha.itemId));
      botao.append(el('b', null, escolha.name.replace('Durable Exercise ', '')));
      botao.append(el('em', null, PERICIA_EM_PT[escolha.skill] ?? escolha.skill));
      botao.onclick = () => {
        escolhido = escolha.itemId;
        desenhar();
      };
      grade.append(botao);
    }
    area.append(grade);

    const escolha = (presentes.escolhas ?? []).find((e) => e.itemId === escolhido);
    area.append(
      el(
        'p',
        'relatorio-motivo',
        escolha
          ? `Você vai receber uma ${escolha.name}, com ${escolha.cargas.toLocaleString('pt-BR')} cargas.`
          : 'Clique numa arma para escolher.'
      )
    );

    /*
     * A conta, quando o degrau cobra.
     *
     * Só o do 150 cobra; nos cinco de graça ela nem aparece — um "vai sair: 0
     * gold" na frente de quem não vai pagar nada é ruído.
     */
    if (custoDaEscolha) {
      const conta = el('div', 'rows confirmar-conta');
      const linhaDaConta = (rotulo, valor, classe) => {
        const linha = el('div');
        linha.append(el('span', null, rotulo), el('b', classe, valor));
        conta.append(linha);
      };
      const sobra = meuOuro - custoDaEscolha;
      linhaDaConta('Você tem', `${meuOuro.toLocaleString('pt-BR')} gold`);
      linhaDaConta('Vai sair', `−${custoDaEscolha.toLocaleString('pt-BR')} gold`, 'bad');
      linhaDaConta('Vai sobrar', `${sobra.toLocaleString('pt-BR')} gold`, sobra >= 0 ? 'good' : 'bad');
      area.append(conta);
    }

    const acoes = el('div', 'confirm-actions');
    const voltar = el('button', 'ghost', 'Voltar');
    voltar.onclick = () => {
      escolhendo = null;
      desenhar();
    };
    const confirmar = el('button', 'recompensa-pegar', 'Confirmar');
    // Sem escolha não há o que confirmar: o botão diz isso ficando apagado,
    // em vez de responder com um erro depois do clique. Sem ouro, idem.
    confirmar.disabled = !escolha || meuOuro < custoDaEscolha;
    confirmar.onclick = () => {
      if (!escolhido) return;
      send({ t: 'presente', itemId: escolhido, ...(typeof escolhendo === 'string' ? { id: escolhendo } : {}) });
      closeModal();
    };
    acoes.append(voltar, confirmar);
    area.append(acoes);
  };

  const desenhar = () => {
    area.replaceChildren();
    if (confirmando) return void desenharCompra();
    if (escolhendo != null) return void desenharEscolha();

    const emAberto = cartoes.filter((c) => c.aberto).length;
    area.append(
      el(
        'p',
        'shop-note',
        emAberto
          ? `Você tem ${emAberto} ${emAberto > 1 ? 'recompensas' : 'recompensa'} para pegar. As outras abrem conforme você sobe.`
          : cartoes.some((c) => !c.pego)
            ? 'Cada marco abre ao chegar no level. Estes são todos:'
            : 'Você já pegou todas.'
      )
    );

    const grade = el('div', 'recompensas-grade');
    for (const cartao of cartoes) grade.append(desenharCartao(cartao));
    area.append(grade);

    /*
     * O "Fechar" só existe quando este corpo É a janela.
     *
     * Dentro da aba de Tarefas ele fecharia a janela inteira a partir de uma
     * aba — um botão que faz mais do que a aba onde ele está.
     */
    if (comFechar) {
      const acoes = el('div', 'confirm-actions');
      const fechar = el('button', 'ghost', 'Fechar');
      fechar.onclick = () => closeModal();
      acoes.append(fechar);
      area.append(acoes);
    }
  };

  desenhar();
}

/** O calendário como janela — o botão de presente da barra de baixo. */
export function openPresente() {
  if (!ctx.state.character?.presentes) return;
  ctx.openModal('Recompensas de nível', (body) => corpoDasRecompensas(body));
}

/*
 * ================================ A PARTY =================================
 *
 * O time, que não é a caçada. Ele se forma na cidade, sobrevive à troca de
 * caverna, e é de onde os convites de caçada partem — em vez de reescrever o
 * nome de cada amigo a cada hunt nova.
 *
 * ---- A diferença que o painel precisa mostrar ----
 *
 * Estar na party não é estar na caçada, e o card diz qual das duas: quem está
 * fora ganha um "chamar", quem está dentro ganha um selo. É a mesma distinção
 * que guarda a experiência — a Shared Experience se divide entre quem está na
 * SESSÃO, e um amigo parado na cidade não recebe nada por estar na sua lista.
 */

/* O mesmo mapa de motivos do rodapé — a frase tem de ser a mesma nos dois. */
const MOTIVO_DA_PARTY_DO_PAINEL = {
  sozinho: 'você está caçando sozinho',
  parado: 'alguém do grupo está sem participar',
};

/*
 * ---- O ícone é o MESMO da barra de habilidade ----
 *
 * Aqui havia uma segunda tentativa de desenhar uma ação: procurava a magia em
 * `state.catalog` e, não achando, caía num arquivo `spell-<id>.png` que não
 * existe. O catálogo mora no módulo da barra, não no estado — então só as
 * poções apareciam, porque elas se resolvem pelo `item-` do próprio id.
 *
 * Agora quem desenha é `actionIcon`, a mesma função da barra: ela conhece a
 * folha de sprites das magias (`icon`) e o item das runas e poções (`itemId`).
 * Uma função só, e as duas telas não têm como divergir.
 */
function iconeDaAcao(id, tamanho = 20) {
  const entrada = entradaDaAcao(id);
  if (entrada) return actionIcon(entrada, tamanho);
  // O catálogo ainda não chegou: a poção pelo menos se resolve pelo id.
  if (String(id).startsWith('item-')) return itemCanvas(Number(String(id).slice(5)), tamanho);
  return el('span', 'rune-mark', String(id).slice(0, 2).toUpperCase());
}

function nomeDaAcao(id) {
  const { state } = ctx;
  const entrada = entradaDaAcao(id);
  if (entrada) return entrada.name ?? null;
  if (String(id).startsWith('item-')) return state.items?.[Number(String(id).slice(5))]?.name ?? null;
  return null;
}

/*
 * ---- Um slot de companheiro, com o leque do cooldown ----
 *
 * O tempo era um número escrito por cima do ícone apagado. Funciona, mas é
 * outro vocabulário: na barra de baixo o jogador aprendeu a LER O LEQUE — a
 * sombra que varre em círculo e diz de relance se falta muito ou pouco, sem
 * ninguém precisar ler o algarismo.
 *
 * Então é o mesmo desenho, o mesmo `conic-gradient` e o mesmo laço de quadros
 * (`acompanharCooldown`, no módulo da barra), num slot menor. O leque anda a 60
 * quadros por segundo mesmo com o estado chegando oito vezes — e ele não
 * remonta nada: só muda uma variável de CSS.
 */
function slotDaAcaoDoAmigo(acao) {
  // O relógio chega como INSTANTE, contado no `clock` da caçada, e a subtração
  // é de quem desenha. Ver `faltaDoCooldown`, em packages/shared/src/prazos.mjs.
  const slot = el('div', `party-spell${faltaDoCooldown(acao, ctx.state.hunt?.clock ?? 0) > 0 ? ' frio' : ''}`);
  slot.append(iconeDaAcao(acao.id));
  const veil = el('i', 'cooldown');
  const texto = el('b', 'cooldown-text');
  veil.hidden = true;
  texto.hidden = true;
  slot.append(veil, texto);
  slot.title = nomeDaAcao(acao.id) ?? acao.id;
  return slot;
}

/** O escudo da party como imagem — o mesmo sprite do cliente do Tibia. */
function escudoDaPartyImg(lider, partilhando) {
  const img = document.createElement('img');
  const cor = lider ? 'yellow' : 'blue';
  img.src = `/client/assets/ui/shields/shield_${cor}${partilhando ? '_shared' : '_not_shared'}.png`;
  img.className = 'party-escudo';
  img.alt = '';
  img.width = 11;
  img.height = 11;
  return img;
}

/*
 * ---- Uma barra fina, com o ícone do que ela mede ----
 *
 * Elas eram três faixas de 12px com o número escrito dentro, e cinco cards
 * disso é uma parede de barras. O número não precisa estar sempre na tela: ele
 * mora no balão, e quem quer saber a vida exata passa o mouse.
 *
 * O ícone à esquerda é o que dispensa a legenda — coração é vida, gota é mana,
 * estrela é experiência. Em 7px de altura a cor sozinha já não bastaria.
 */
function barraDoCard(icone, classe, feito, total, titulo) {
  const linha = el('div', `party-linha-barra ${classe}`);
  /*
   * `artOrUiIcon` e não `uiIcon`: os ícones da ficha moram em
   * `client/assets/icons` e só caem para `client/assets/ui` quando não há arte
   * nova. É o mesmo caminho que a ficha usa, e é o que faz o card falar a
   * mesma língua dela.
   */
  linha.append(artOrUiIcon(icone, ''));
  const fora = el('div', 'party-barra');
  const dentro = el('i');
  dentro.style.width = `${Math.max(0, Math.min(100, (feito / Math.max(1, total)) * 100))}%`;
  fora.append(dentro);
  linha.append(fora);
  linha.title = titulo;
  return linha;
}

/*
 * A perícia que define cada vocação — é por ela que o jogador as reconhece.
 *
 * ---- Menos os dois magos, e foi um report ----
 *
 * Druid e sorcerer partilham o magic level, e por isso partilhavam o ícone. Só
 * que o chat já os separa desde que o sorcerer ganhou o cajado de PONTA ROXA
 * (`sk-magic-sorcerer`, ver VOCACAO_NO_CHAT em chat.mjs) — e a party ficou para
 * trás: a mesma pessoa aparecia de um jeito na linha do Global e de outro na
 * lista da party. Duas respostas para a mesma pergunta é pior do que uma
 * resposta grossa.
 */
/*
 * Exportado porque a lista de membros da guilda desenha o mesmo icone (ver
 * `client/src/guildas.mjs`). Uma segunda copia deste mapa seria a lista que um
 * dia mostra a espada para o druida, sem que nada acuse o erro.
 */
export const PERICIA_DA_VOCACAO = {
  knight: 'sk-sword',
  paladin: 'sk-distance',
  druid: 'sk-magic',
  sorcerer: 'sk-magic-sorcerer',
  monk: 'sk-fist',
  none: 'sk-misc',
};

/** O nome da vocação como o catálogo a chama. */
export const NOME_DA_VOCACAO = {
  knight: 'Knight',
  paladin: 'Paladin',
  druid: 'Druid',
  sorcerer: 'Sorcerer',
  monk: 'Monk',
  none: 'Sem vocação',
};

/*
 * ---- As escolhas de posição, e de quem é cada uma ----
 *
 * São duas, e a régua não é o cargo — é a POSIÇÃO NA FILA:
 *
 *   · quem lidera escolhe QUEM VAI NA FRENTE. É a decisão do grupo — quem
 *     conhece o percurso e sabe quem aguenta puxar;
 *   · quem não está na ponta escolhe A QUE DISTÂNCIA SEGUE quem está. É a
 *     decisão pessoal — um paladino quer espaço para atirar, um knight quer
 *     estar colado.
 *
 * Quem está na ponta não recebe a segunda: ele não segue ninguém, e o seletor
 * existiria só para não fazer nada.
 *
 * O líder que manda OUTRA pessoa para a frente passa a seguir também, e por
 * isso recebe as duas caixas — a primeira porque continua sendo dele a decisão
 * de quem puxa, a segunda porque ele passou a andar atrás de alguém e precisa
 * dizer a que distância. Enquanto ele mesmo está na ponta, só a primeira
 * aparece: não há de quem se afastar.
 *
 * `dicas` liga as linhas de explicação: cabem no painel largo de Amigos e não
 * cabem na janelinha do canto, que tem 232px.
 */
/**
 * A tabela da party: quem é quem, o movimento de cada um, quem ele segue e a distância. Os dados vêm do servidor (`hunt.party.membros`
 * traz modo, seguindo, coleira e emCombate; level, classe e vida vêm do personagem). Só mostra o que o servidor decidiu.
 */
function tabelaDaParty(body, grupo, state) {
  const membros = grupo.membros ?? [];
  if (membros.length < 2) return;
  const doPersonagem = new Map((state.character?.party?.membros ?? []).map((m) => [m.name, m]));
  const naPonta = grupo.frente ?? grupo.lider;
  const envoltorio = el('div', 'party-tabela-caixa');
  const tabela = document.createElement('table');
  tabela.className = 'party-tabela';
  const cabeca = document.createElement('tr');
  for (const titulo of ['Jogador', 'Classe', 'Lv', 'Vida', 'Movimento', 'Seguindo', 'Dist.']) cabeca.append(el('th', null, titulo));
  tabela.append(cabeca);
  for (const m of membros) {
    const info = doPersonagem.get(m.name) ?? {};
    const linha = document.createElement('tr');
    const ehPonta = m.name === naPonta;
    const movimento = ehPonta ? (m.name === grupo.lider ? 'Líder' : 'Na frente') : m.modo === 'independente' ? 'Independente' : 'Follow';
    const seguindo = ehPonta || m.modo === 'independente' ? '—' : m.seguindo ?? naPonta;
    const distancia = ehPonta || m.modo === 'independente' ? '—' : `${m.coleira} SQM`;
    const vida = info.maxHp ? `${Math.round((100 * (info.hp ?? 0)) / info.maxHp)}%` : '—';
    for (const texto of [`${m.emCombate ? '⚔ ' : ''}${m.name}`, info.vocationName ?? '—', info.level ?? '—', vida, movimento, seguindo, distancia]) linha.append(el('td', null, String(texto)));
    tabela.append(linha);
  }
  envoltorio.append(tabela);
  body.append(envoltorio);
}

/** Os controles do líder para chamar a party para perto de alguém (ou dele) e para cancelar o chamado. */
function controlesDeReagrupar(body, grupo, send) {
  const caixa = el('div', 'party-config party-reagrupar');
  caixa.append(el('span', null, 'Reagrupar a party'));
  const quem = document.createElement('select');
  for (const m of grupo.membros ?? []) {
    const opcao = document.createElement('option');
    opcao.value = m.name;
    opcao.textContent = m.name === grupo.lider ? `${m.name} (você)` : m.name;
    quem.append(opcao);
  }
  quem.value = grupo.lider;
  const chamar = el('button', 'party-botao', 'Reagrupar');
  chamar.type = 'button';
  chamar.onclick = () => send({ t: 'party', action: 'reagrupar', name: quem.value });
  const cancelar = el('button', 'party-botao', 'Cancelar');
  cancelar.type = 'button';
  cancelar.onclick = () => send({ t: 'party', action: 'cancelarReagrupar' });
  caixa.append(quem, chamar);
  if (grupo.reagrupar) {
    caixa.append(cancelar);
    caixa.append(el('em', null, `Chamando para perto de ${grupo.reagrupar.alvo} (${Math.ceil(grupo.reagrupar.resta / 1000)} s).`));
  }
  body.append(caixa);
}

export function escolhasDaPosicao(body, grupo, state, send, { dicas = false } = {}) {
  /*
   * Nada disso vale na Caça Online: lá quem anda é a pessoa, com a tecla na
   * mão. Oferecer os seletores seria prometer um comportamento que o modo não
   * tem — o jogador escolheria 3 sqm e veria o boneco ignorar.
   */
  if (!grupo || state.hunt?.manual) return;

  /*
   * Quem manda na formação é o líder da PARTY, e quem diz isso é o servidor.
   *
   * A tela deduzia do dono da sessão (`grupo.lider`), e os dois se separam num
   * caso real: o líder do time entra na caçada que outro abriu. Deduzir aqui e
   * decidir lá dá a caixa a quem o servidor vai recusar — pior do que não ter
   * caixa. `mandaNaFila` é a resposta de quem decide. Ver `quemMandaNaFila`.
   */
  const souOChefe = (grupo.mandaNaFila ?? grupo.lider) === state.character?.name;

  if (souOChefe && (grupo.membros ?? []).length > 1) {
    const frente = el('label', 'party-config');
    frente.append(el('span', null, 'Quem vai na frente'));
    const quem = document.createElement('select');
    for (const membro of grupo.membros ?? []) {
      const opcao = document.createElement('option');
      opcao.value = membro.name;
      opcao.textContent = membro.name;
      quem.append(opcao);
    }
    quem.value = grupo.frente ?? grupo.lider;
    quem.onchange = () => send({ t: 'party', action: 'frente', name: quem.value });
    frente.append(quem);
    if (dicas) frente.append(el('em', null, 'Quem anda na ponta puxa o bicho. Os outros seguem esse personagem.'));
    body.append(frente);
  }

  // A tabela da party (quem faz o quê) e, para o líder, o reagrupamento.
  tabelaDaParty(body, grupo, state);
  if (grupo.lider === state.character?.name && (grupo.membros ?? []).length > 1) controlesDeReagrupar(body, grupo, send);

  /*
   * E daqui para baixo é de quem SEGUE — líder incluído, quando ele mandou
   * outra pessoa para a ponta. Quem está na ponta para por aqui.
   */
  const naPonta = grupo.frente ?? grupo.lider;
  if (naPonta === state.character?.name) return;

  /*
   * ---- O MODO de movimento: seguir ou explorar sozinho ----
   * "Independente": não segue ninguém e a fase continua sendo da party (a exp segue dividida, os bichos são os mesmos). A distância e
   * "andar atrás de" só valem seguindo — por isso só aparecem nesse modo.
   */
  const modo = el('label', 'party-config');
  modo.append(el('span', null, 'Movimento'));
  const seletorDoModo = document.createElement('select');
  for (const [valor, texto] of [['seguir', 'Seguir'], ['independente', 'Explorar independente']]) {
    const opcao = document.createElement('option');
    opcao.value = valor;
    opcao.textContent = texto;
    seletorDoModo.append(opcao);
  }
  seletorDoModo.value = grupo.modo ?? 'seguir';
  seletorDoModo.onchange = () => send({ t: 'party', action: 'modo', valor: seletorDoModo.value });
  modo.append(seletorDoModo);
  if (dicas) modo.append(el('em', null, 'Independente: você anda sozinho pela fase (cada um limpa a sua região) e continua dividindo a exp com a party.'));
  body.append(modo);
  if (grupo.modo === 'independente') {
    const voltar = el('button', 'party-botao', 'Voltar a seguir quem está na frente');
    voltar.type = 'button';
    voltar.onclick = () => {
      send({ t: 'party', action: 'seguirQuem', name: '' });
      send({ t: 'party', action: 'modo', valor: 'seguir' });
    };
    body.append(voltar);
    return;
  }

  /*
   * ---- E QUEM este personagem segue ----
   *
   * "tem que ter a opção de seguir quem, pra caso eu queira fazer fila de
   * chares". Com A na ponta, B seguindo A e C seguindo B, sai a fila; sem
   * escolha nenhuma, todo mundo segue a ponta, que é o de sempre.
   *
   * A escolha é DE CADA UM e não do líder — como a coleira logo abaixo. Seguir
   * alguém é uma decisão sobre o próprio boneco.
   *
   * Só aparece com três ou mais na caçada: com dois não há fila possível, e o
   * único alvo seria a própria ponta — que já é o padrão.
   */
  const podeEscolher = (grupo.membros ?? []).filter(
    (membro) => membro.name !== state.character?.name && membro.name !== naPonta
  );
  if (podeEscolher.length) {
    const linha = el('label', 'party-config');
    linha.append(el('span', null, 'Andar atrás de'));
    const quem = document.createElement('select');
    const padrao = document.createElement('option');
    padrao.value = '';
    padrao.textContent = `${naPonta} (quem vai na frente)`;
    quem.append(padrao);
    for (const membro of podeEscolher) {
      const opcao = document.createElement('option');
      opcao.value = membro.name;
      opcao.textContent = membro.name;
      quem.append(opcao);
    }
    quem.value = grupo.seguirQuem ?? '';
    quem.onchange = () => send({ t: 'party', action: 'seguirQuem', name: quem.value });
    linha.append(quem);
    if (dicas) {
      linha.append(
        el(
          'em',
          null,
          'Para fazer fila: o segundo segue quem vai na frente, o terceiro segue o segundo. Se dois se escolherem em círculo, ninguém andaria — aí a escolha é ignorada e todos voltam a seguir a ponta.'
        )
      );
    }
    body.append(linha);
  }

  const coleira = el('label', 'party-config');
  coleira.append(el('span', null, grupo.seguirQuem ? `Seguir ${grupo.seguirQuem} a` : 'Seguir quem está na frente a'));
  const escolha = document.createElement('select');
  for (const casas of grupo.coleiras ?? [1, 2, 3, 5, 7, 9, 12]) {
    const opcao = document.createElement('option');
    opcao.value = String(casas);
    opcao.textContent = `${casas} sqm`;
    escolha.append(opcao);
  }
  escolha.value = String(grupo.coleira ?? 5);
  escolha.onchange = () => send({ t: 'party', action: 'coleira', valor: Number(escolha.value) });
  coleira.append(escolha);
  if (dicas) coleira.append(el('em', null, 'Mais perto: você fica junto e larga o alvo antes. Mais longe: persegue mais. Dentro da distância você não anda.'));
  body.append(coleira);
  if (grupo.reagrupar && grupo.lider !== state.character?.name) {
    const cancelar = el('button', 'party-botao', `Cancelar o reagrupamento (${grupo.reagrupar.alvo})`);
    cancelar.type = 'button';
    cancelar.onclick = () => send({ t: 'party', action: 'cancelarReagrupar' });
    body.append(cancelar);
  }
}

/*
 * ---- O interruptor da barra dos companheiros ----
 *
 * Ele morava só na janelinha do canto, embaixo de tudo — com cinco cards, fora
 * da vista sem rolar. Ele vive aqui para aparecer nos DOIS lugares em que a
 * party é vista, e no alto, onde não depende de rolagem.
 */
function opcaoDeVerAsAcoes(body, state, send) {
  const linha = el('label', 'party-opcao');
  const caixa = document.createElement('input');
  caixa.type = 'checkbox';
  caixa.checked = !!state.character?.settings?.verAcoesDaParty;
  caixa.onchange = () => send({ t: 'settings', verAcoesDaParty: caixa.checked });
  linha.append(caixa, el('span', null, 'Ver as habilidades do grupo'));
  linha.title = 'Mostra a barra de cada companheiro no card, com o cooldown de cada magia.';
  body.append(linha);

  /*
   * ---- E a chave da porta aberta, ao lado ----
   *
   * Pedido do dono: "ao lado tem que ter 'permitir entrar na caçada', que ao
   * ser marcado o jogador pode entrar na caçada de qualquer um que esteja na
   * party sem precisar de convite e aceitar".
   *
   * As duas são vizinhas na tela e opostas no sentido, e vale saber disso ao
   * ler: a de cima é sobre o que EU VEJO dos outros; esta é sobre o que os
   * outros podem fazer COMIGO. Por isso o balão dela fala na segunda pessoa —
   * quem marca está abrindo a própria caçada, não pedindo nada.
   */
  const aberta = el('label', 'party-opcao');
  const chave = document.createElement('input');
  chave.type = 'checkbox';
  chave.checked = !!state.character?.settings?.entrarSemConvite;
  chave.onchange = () => send({ t: 'settings', entrarSemConvite: chave.checked });
  aberta.append(chave, el('span', null, 'Permitir entrar na caçada'));
  aberta.title =
    'Com isto marcado, quem está na sua party entra na sua caçada direto, sem precisar pedir e sem você ter de aceitar.';
  body.append(aberta);

  /*
   * ---- "Seguir o líder em qualquer ocasião" ----
   *
   * Report do Garibas: seguir o líder até para voltar à cidade ou trocar de
   * hunt, sem abrir o char para aceitar. Só aparece para quem NÃO é o líder —
   * o líder não tem a quem seguir. As portas continuam valendo: level, premium,
   * task e cooldown de boss são conferidos no servidor, um a um.
   */
  const party = state.character?.party ?? null;
  if (party && !party.souLider) {
    const seguir = el('label', 'party-opcao');
    const marca = document.createElement('input');
    marca.type = 'checkbox';
    marca.checked = !!state.character?.settings?.seguirLider;
    marca.onchange = () => send({ t: 'settings', seguirLider: marca.checked });
    seguir.append(marca, el('span', null, 'Seguir líder em qualquer ocasião'));
    seguir.title =
      'Vai junto quando o líder entra numa hunt, boss ou instance, troca de hunt, volta para a cidade ou morre — ' +
      'mesmo com a sua aba fechada. Quem não tiver level, premium, task ou estiver com o boss em cooldown fica na cidade.';
    body.append(seguir);
  }
}

/*
 * ---- O cartão de um membro ----
 *
 * Compacto de propósito: cinco deles precisam caber numa janela estreita sem
 * virar uma parede. O que ocupa espaço é o que se lê de relance — o boneco, o
 * escudo do cargo, o nome e as três barras. Os números vão para os balões.
 */
/**
 * O progresso COLETIVO da instância por setor (`hunt.setores`, do servidor): nome, barra do que já foi limpo, quantos bichos restam e quem
 * está lá. Compacto: uma linha por setor, sem painel grande — no celular as linhas empilham.
 */
function blocoDosSetores(setores) {
  if (!setores?.length) return null;
  const caixa = el('div', 'party-setores');
  const feitos = setores.filter((x) => x.concluido).length;
  caixa.append(el('div', 'party-setores-titulo', `Setores: ${feitos} de ${setores.length} concluídos`));
  for (const x of setores) {
    const linha = el('div', `party-setor-linha${x.concluido ? ' feito' : ''}`);
    linha.dataset.setor = x.id;
    linha.append(el('span', 'party-setor-nome', `${x.concluido ? '✓ ' : ''}${x.nome}`));
    const barra = el('span', 'party-setor-barra');
    const cheio = el('i');
    cheio.style.width = `${x.total ? Math.round((100 * (x.total - x.vivos)) / x.total) : 100}%`;
    barra.append(cheio);
    linha.append(barra);
    linha.append(el('span', 'party-setor-resta', x.concluido ? 'limpo' : `restam ${x.vivos}`));
    if (x.jogadores?.length) linha.append(el('span', 'party-setor-quem', x.jogadores.join(', ')));
    caixa.append(linha);
  }
  return caixa;
}

function cardDaParty(membro, party, send) {
  // Quem vai na ponta e a coleira de cada um saem da CAÇADA (a party não anda).
  const noGrupo = (ctx.state.hunt?.party?.membros ?? []).find((m) => m.name === membro.name) ?? null;
  membro.naFrente = !!noGrupo && (ctx.state.hunt?.party?.frente ?? ctx.state.hunt?.party?.lider) === membro.name;
  membro.coleira = noGrupo?.coleira ?? null;
  /*
   * A barra de habilidade dele vem da CAÇADA também, e só quando quem olha
   * ligou a opção (ver `verAcoesDaParty`). Faltava esta linha: o servidor
   * mandava as ações, o card lia `membro.acoes` da party — que nunca as teve —
   * e a barra não aparecia por mais que a opção estivesse marcada.
   */
  membro.acoes = noGrupo?.acoes ?? null;
  /*
   * ---- O escudo é de CADA UM, e não do grupo ----
   *
   * Ele saía de um `party.partilhando` só, ligado assim que a partilha valesse
   * para a caçada. Quem estava na party e FORA da caverna herdava o escudo
   * cheio dos outros: entrava o terceiro personagem, longe e sem entrar na
   * caçada, e o card dizia que ele estava partilhando experiência.
   *
   * Partilha é da SESSÃO. Quem não está nela não partilha nada, e o escudo dele
   * é o vazio — o cargo, e mais nada.
   */
  membro.partilhando = !!ctx.state.hunt?.party?.ativa && !!noGrupo && (noGrupo.estado ?? 'ok') === 'ok';

  const card = el('div', `party-card${membro.eu ? ' eu' : ''}${membro.online ? '' : ' offline'}`);
  // O nome identifica o card: é por ele que as barras são achadas para o
  // ajuste sem remontagem. Ver `atualizarBarrasDaParty`.
  card.dataset.membro = membro.name;

  const topo = el('div', 'party-card-topo');
  const retrato = el('div', 'party-retrato');
  if (membro.outfit?.type && outfitInfo(membro.outfit.type)) {
    retrato.append(outfitCanvas(membro.outfit.type, membro.outfit, 32, 2, true));
  }
  topo.append(retrato);

  const nomes = el('div', 'party-nomes');
  const linhaDoNome = el('div', 'party-linha-nome');
  // Amarelo é líder, azul é membro — o mesmo escudo do mapa.
  linhaDoNome.append(escudoDaPartyImg(membro.lider, membro.partilhando));
  linhaDoNome.append(el('b', null, membro.name));
  nomes.append(linhaDoNome);

  /*
   * A vocação com o ícone dela, e o level ao lado. Numa party de cinco é o que
   * responde de relance "quem cura, quem segura e quem atira" — mais útil que o
   * nome da caverna, que é o mesmo para todo mundo.
   */
  const abaixo = el('div', 'party-sub');
  /*
   * O ícone da vocação é o da PERÍCIA dela, e não um retrato.
   *
   * É como o jogador pensa nas vocações: paladino é distância, mago é magic
   * level, monge é punho, cavaleiro é espada. Os ícones já existem — são os
   * mesmos da ficha do personagem —, e reusá-los faz o card falar a língua do
   * resto do jogo em vez de inventar uma figura própria.
   */
  const arte = artOrUiIcon(PERICIA_DA_VOCACAO[membro.vocation] ?? 'sk-misc', '');
  arte.classList.add('party-voc-icone');
  abaixo.append(arte);
  // `vocationName`: o nome depois da promoção, quando o servidor manda.
  abaixo.append(el('span', null, `${membro.vocationName ?? NOME_DA_VOCACAO[membro.vocation] ?? membro.vocation} ${membro.level}`));
  if (!membro.online) abaixo.append(el('i', 'party-fora', 'offline'));
  else if (membro.naMinhaCacada) abaixo.append(el('i', 'party-dentro', 'na caçada'));
  nomes.append(abaixo);
  // Onde ele está: o setor da instância (na minha caçada) ou, se desconectou, quanto falta para o prazo de volta acabar.
  if (!membro.online && membro.voltaEm != null) nomes.append(el('div', 'party-setor offline', `desconectado · volta em ${Math.max(1, Math.ceil(membro.voltaEm / 60_000))} min`));
  else if (membro.setor) nomes.append(el('div', 'party-setor', `Setor: ${membro.setor}`));
  topo.append(nomes);
  card.append(topo);

  if (membro.online) {
    /*
     * Os ícones são os da FICHA, e as cores as da barra de habilidade.
     *
     * O card tinha ícones próprios e um verde que não existia em nenhum outro
     * lugar do jogo. Vida é vermelha, mana é azul e experiência é dourada — o
     * jogador já aprendeu isso na barra de baixo, e um segundo vocabulário para
     * a mesma coisa é uma coisa a mais para aprender sem motivo.
     */
    card.append(barraDoCard('ficha-regen-vida', 'hp', membro.hp, membro.maxHp, `Vida ${membro.hp} de ${membro.maxHp}`));
    card.append(barraDoCard('ficha-regen-mana', 'mana', membro.mana, membro.maxMana, `Mana ${membro.mana} de ${membro.maxMana}`));
    card.append(
      barraDoCard(
        'ficha-exp',
        'exp',
        membro.progresso * 100,
        100,
        `${Math.floor(membro.progresso * 100)}% do level ${membro.level}`
      )
    );
    /*
     * ---- ONDE ele está caçando ----
     *
     * Pedido do dono: "fora da caçada, na party, se alguém estiver caçando tem
     * que mostrar escrito embaixo da barra de xp aonde ela está caçando".
     *
     * O nome da hunt já vinha no retrato e não aparecia em lugar nenhum: o card
     * dizia "na caçada" quando era a MINHA e não dizia nada quando era a dele.
     * Quem está na cidade decidindo se vai junto está justamente perguntando
     * para onde.
     *
     * Só quando é OUTRA caçada: dentro da minha, "na caçada" já está escrito ao
     * lado do nome, e repetir o lugar em que nós dois estamos não diz nada.
     */
    if (membro.hunt && !membro.naMinhaCacada && !membro.eu) {
      const onde = el('div', 'party-onde');
      onde.append(artOrUiIcon('ficha-alcance', ''), el('span', null, `caçando em ${membro.hunt}`));
      onde.title = `${membro.name} está caçando em ${membro.hunt}`;
      card.append(onde);
    }
  }

  /*
   * Os botões são ícones, e só aparecem quando dá para usá-los: um "chamar
   * para a caçada" que o outro lado vai recusar é pior do que botão nenhum.
   */
  /*
   * ---- Como ESTE personagem está configurado ----
   *
   * A escolha é pessoal, mas o efeito é do grupo: quem lidera precisa saber que
   * o paladino anda a 9 casas antes de estranhar por que ele está sempre atrás.
   * Sem isto, cada um só via a própria configuração e o comportamento dos
   * outros virava mistério.
   */
  if (membro.naFrente) {
    const selo = el('div', 'party-config-selo frente');
    selo.append(artOrUiIcon('ficha-progresso', ''));
    selo.append(el('span', null, 'vai na frente'));
    card.append(selo);
  } else if (membro.coleira != null && membro.naMinhaCacada) {
    const selo = el('div', 'party-config-selo');
    selo.append(artOrUiIcon('ficha-alcance', ''));
    selo.append(el('span', null, `segue a ${membro.coleira} sqm`));
    card.append(selo);
  }

  /*
   * Os botões com o nome do que fazem.
   *
   * Eram um caractere cada (`+`, `★`, `✕`) num quadrado de 20px — não dava para
   * ler nem para acertar com o mouse. Um ícone só é atalho quando já se sabe o
   * que ele faz; num botão que se usa uma vez por caçada, a palavra é mais
   * rápida que aprender o símbolo.
   */
  /*
   * ---- A barra de habilidade dele ----
   *
   * Só chega do servidor quando quem olha ligou a opção (ver
   * `verAcoesDaParty`). Mostra o ícone da magia e escurece o que está em
   * cooldown, com o tempo por cima — é o que responde "o druida ainda tem a
   * cura pronta?" sem ninguém precisar perguntar no chat.
   */
  if (membro.acoes?.length) {
    const barra = el('div', 'party-spells');
    for (const acao of membro.acoes) barra.append(slotDaAcaoDoAmigo(acao));
    card.append(barra);
  }

  const acoes = el('div', 'party-card-acoes');
  if (membro.podeChamar) {
    const chamar = el('button', 'party-acao chamar', '');
    chamar.append(artOrUiIcon('ficha-kills', ''), el('span', null, 'Chamar'));
    /*
     * Quem já está caçando por conta própria também pode ser chamado — e o
     * aviso vem ANTES do clique, porque aceitar encerra a caçada dele. Sem
     * isto, o líder convida sem saber que está tirando alguém do meio de uma
     * hunt, e quem recebe descobre depois de aceitar.
     */
    chamar.title = membro.cacandoPorFora
      ? `chamar ${membro.name} para a sua caçada — ele está caçando, e aceitar encerra a caçada dele`
      : `chamar ${membro.name} para a sua caçada`;
    if (membro.cacandoPorFora) chamar.classList.add('tira-da-hunt');
    chamar.onclick = () => send({ t: 'party', action: 'invite', name: membro.name });
    acoes.append(chamar);
  }
  /*
   * ---- E o caminho de volta: PEDIR para entrar na caçada dele ----
   *
   * Report do painel: "na PT, opção de 'Entrar na hunt' / dar TP para quem já
   * está nela". O "Chamar" acima é o TP; este é o pedido.
   *
   * Ele não entra ninguém — vira um cartão do lado de lá, e quem decide é o
   * dono da caçada. É a mesma regra do convite com os papéis trocados, e sem
   * ela qualquer um da party cairia dentro de uma caçada alheia sem ser
   * chamado. Ver `party pedir`, em index.mjs.
   */
  /*
   * ---- E o atalho, quando ele deixou a porta aberta ----
   *
   * Pedido do dono: "um botão de 'entrar na caçada' para a pessoa que não está
   * na caçada ainda, e só poderia entrar assim se a pessoa tiver com o
   * 'permitir entrar na caçada' marcado".
   *
   * É o mesmo lugar do botão de pedir, e um EXCLUI o outro: oferecer "Entrar" e
   * "Pedir para entrar" lado a lado obrigaria a pessoa a entender a diferença
   * entre os dois antes de clicar em qualquer um. Quem abriu a porta recebe o
   * atalho; quem não abriu, o pedido de sempre.
   */
  if (membro.podeEntrarDireto) {
    const entrar = el('button', 'party-acao entrar', '');
    entrar.append(artOrUiIcon('ficha-progresso', ''), el('span', null, 'Entrar na caçada'));
    entrar.title = membro.hunt
      ? `entrar na caçada de ${membro.name} (${membro.hunt}) — ele deixou a entrada liberada`
      : `entrar na caçada de ${membro.name} — ele deixou a entrada liberada`;
    entrar.onclick = () => send({ t: 'party', action: 'entrar', name: membro.name });
    acoes.append(entrar);
  } else if (membro.podePedirEntrada) {
    const pedir = el('button', 'party-acao entrar', '');
    pedir.append(artOrUiIcon('ficha-progresso', ''), el('span', null, 'Pedir para entrar'));
    pedir.title = membro.hunt
      ? `pedir a ${membro.name} para entrar na caçada dele (${membro.hunt})`
      : `pedir a ${membro.name} para entrar na caçada dele`;
    pedir.onclick = () => send({ t: 'party', action: 'pedir', name: membro.name });
    acoes.append(pedir);
  }
  if (party.souLider && !membro.eu) {
    const passar = el('button', 'party-acao', '');
    passar.append(el('i', null, '★'), el('span', null, 'Liderança'));
    passar.title = `passar a liderança da party para ${membro.name}`;
    passar.onclick = () => send({ t: 'grupo', action: 'lider', name: membro.name });
    acoes.append(passar);

    const tirar = el('button', 'party-acao perigo', '');
    tirar.append(el('i', null, '✕'), el('span', null, 'Tirar'));
    tirar.title = `tirar ${membro.name} da party`;
    tirar.onclick = () => send({ t: 'grupo', action: 'expulsar', name: membro.name });
    acoes.append(tirar);
  }
  if (acoes.childNodes.length) card.append(acoes);
  return card;
}

export function openParty() {
  const { state, send } = ctx;
  send({ t: 'friends', action: 'list' });

  ctx.openModal('Party', (body) => {
    const draw = () => {
      body.innerHTML = '';
      const party = state.character?.party ?? null;
      /*
       * O estado da partilha e a faixa de level vêm da CAÇADA, e não da party:
       * são coisas da sessão. Aparecem aqui porque é onde o jogador vai
       * procurar — e é isso que permite tirá-los do rodapé.
       */
      const grupo = state.hunt?.party ?? null;

      if (!party) {
        body.append(
          el('p', 'confirm-short', 'Você não está numa party. Convide alguém para começar — a party dura entre uma caçada e outra.')
        );
      }

      const topo = el('div', 'amigos-topo');
      if (!party || party.souLider) {
        const campo = document.createElement('input');
        campo.className = 'search';
        campo.placeholder = 'nome do personagem...';
        campo.maxLength = 32;
        const convidar = el('button', 'primary', 'Convidar');
        const mandar = () => {
          const nome = campo.value.trim();
          if (!nome) return;
          send({ t: 'grupo', action: 'convidar', name: nome });
          campo.value = '';
        };
        convidar.onclick = mandar;
        campo.onkeydown = (evento) => {
          if (evento.key === 'Enter') mandar();
        };
        topo.append(campo, convidar);
      } else {
        topo.append(el('p', 'confirm-short', 'Só o líder da party convida.'));
      }
      body.append(topo);

      /*
       * Os amigos online, com um clique cada. É o caminho curto: quem monta
       * party monta com quem já é amigo, e digitar o nome de novo é trabalho
       * que a lista já fez.
       */
      const naParty = new Set((party?.membros ?? []).map((m) => m.name));
      const amigos = (state.friends?.amigos ?? []).filter((amigo) => amigo.online && !naParty.has(amigo.name));
      if ((!party || party.souLider) && amigos.length) {
        const linha = el('div', 'party-amigos');
        linha.append(el('span', 'party-titulo', 'Amigos online'));
        for (const amigo of amigos.slice(0, 12)) {
          const botao = el('button', 'ghost', `+ ${amigo.name}`);
          botao.title = `Convidar ${amigo.name} (level ${amigo.level}) para a party`;
          botao.onclick = () => send({ t: 'grupo', action: 'convidar', name: amigo.name });
          linha.append(botao);
        }
        body.append(linha);
      }

      if (!party) return;

      const grade = el('div', 'party-grade');
      for (const membro of party.membros) grade.append(cardDaParty(membro, party, send));
      body.append(grade);
      const setoresDaInstancia = blocoDosSetores(state.hunt?.setores);
      if (setoresDaInstancia) body.append(setoresDaInstancia);
      body.append(el('p', 'shop-note', `${party.membros.length} de ${party.maximo} lugares.`));

      /*
       * ---- O estado da caçada, e as duas escolhas que moravam no rodapé ----
       *
       * "Quem vai na frente" e "seguir a X sqm" estavam espremidas na barra de
       * habilidade, entre o alvo e o lurar. Elas são de party, não de barra — e
       * aqui cabem, com espaço para dizer o que fazem.
       */
      /*
       * As escolhas de posição só valem na caçada AUTOMÁTICA: na Caça Online
       * quem anda é a pessoa. Ver a nota em `corpoDaJanelaDaParty`.
       */
      if (grupo) {
        const caixa = el('div', 'party-cacada');
        const estado = el('div', 'party-estado');
        estado.append(escudoDaPartyImg(true, !!grupo.ativa));
        estado.append(
          el(
            'b',
            null,
            grupo.ativa
              ? 'Shared Experience ativa'
              : `Sem partilha: ${MOTIVO_DA_PARTY_DO_PAINEL[grupo.motivo] ?? grupo.motivo}`
          )
        );
        /*
         * ---- O bônus de vocações, ao lado do escudo ----
         *
         * Ele só aparece com a partilha LIGADA, e de propósito: com ela
         * desligada o bônus não é aplicado, e mostrar "+70%" embaixo de "Sem
         * partilha" prometeria um número que ninguém vai receber.
         */
        if (grupo.ativa && grupo.bonus > 1) {
          const quantas = grupo.vocacoes ?? 1;
          const marca = el('em', 'party-bonus', `+${Math.round((grupo.bonus - 1) * 100)}% de experiência`);
          marca.title = [
            `${quantas} vocaç${quantas === 1 ? 'ão' : 'ões'} diferente${quantas === 1 ? '' : 's'} na caçada.`,
            'Mesma vocação +20% · duas +35% · três +70% · quatro ou mais +100%.',
            'Vale para criaturas de 20 de experiência para cima.',
          ].join('\n');
          estado.append(marca);
        }
        caixa.append(estado);

        escolhasDaPosicao(caixa, grupo, state, send, { dicas: true });
        body.append(caixa);
      }

      opcaoDeVerAsAcoes(body, state, send);

      const rodape = el('div', 'confirm-actions');
      const sair = el('button', 'ghost', 'Sair da party');
      sair.onclick = () => send({ t: 'grupo', action: 'sair' });
      rodape.append(sair);
      body.append(rodape);
    };

    /*
     * ---- Só redesenha quando MUDA ----
     *
     * `ctx.redraw` é chamado a cada envio de estado, quatro vezes por segundo, e
     * o card mostra vida e mana — números que mudam sempre. Redesenhar a cada
     * quadro mataria o seletor aberto no meio da escolha, que foi exatamente o
     * defeito do painel do rodapé.
     *
     * A assinatura é o que a tela DESENHA: quem está, o cargo, a vida, o estado
     * da partilha e as duas escolhas. As barras acompanham porque a vida entra
     * nela; o resto fica quieto.
     */
    let assinatura = null;
    const talvez = () => {
      const party = ctx.state.character?.party;
      const marca = JSON.stringify([
        party?.membros?.map((m) => [m.name, m.hp, m.mana, m.level, m.naMinhaCacada, m.lider, m.online, m.setor, m.voltaEm == null ? null : Math.ceil(m.voltaEm / 60_000)]),
        /* O progresso por setor: muda a cada bicho que morre, e só então a tela se refaz. */
        ctx.state.hunt?.setores?.map((x) => [x.id, x.vivos, (x.jogadores ?? []).join(',')]),
        party?.souLider,
        ctx.state.hunt?.party?.ativa,
        ctx.state.hunt?.party?.motivo,
        ctx.state.hunt?.party?.frente,
        ctx.state.hunt?.party?.mandaNaFila,
        ctx.state.hunt?.party?.coleira,
        /* O escudo de cada um sai daqui — ver a nota igual no `main.mjs`. */
        ctx.state.hunt?.party?.membros?.map((m) => [m.name, m.coleira, m.estado]),
        (ctx.state.friends?.amigos ?? []).map((a) => `${a.name}${a.online}`),
        /* Ver a nota igual na `cuidarDaJanelaDaParty`: os IDs montam a tela, o
         * cooldown é número e é escrito por fora. */
        !!ctx.state.character?.settings?.verAcoesDaParty,
        catalogoDeAcoesPronto(),
        ctx.state.hunt?.party?.membros?.map((m) => (m.acoes ?? []).map((a) => a.id).join(',')),
      ]);
      if (marca === assinatura) {
        // Estrutura igual: só os números — vida, mana e os relógios da barra.
        atualizarBarrasDaParty(body, ctx.state.character?.party, ctx.state.hunt?.party ?? null);
        return;
      }
      assinatura = marca;
      draw();
      // O `draw` acima refaz o corpo; o ponteiro tem de continuar apontando
      // para cá. Ver a nota do `desenharTroca`, no main.
      ctx.redraw = talvez;
    };
    talvez();
    ctx.redraw = talvez;
  });
}


/*
 * ---- O MESMO card, agora numa janela do jogo ----
 *
 * A informação da party morava numa faixa presa acima da barra de habilidade:
 * não dava para mover, não dava para fechar, e cabia uma linha. Com cinco
 * pessoas era uma fileira de nomes espremida num rodapé que já tem o alvo, a
 * distância do alvo e o lurar.
 *
 * Aqui ela é uma janela como as outras — arrasta, redimensiona e minimiza —, e
 * os cards são os MESMOS do painel de Amigos. Uma função de desenho só: duas
 * telas que mostram a mesma coisa não podem divergir com o tempo.
 */
/*
 * ---- Só os números, sem remontar a tela ----
 *
 * Vida e mana mudam a todo tique — a regeneração basta. Refazer a janela por
 * causa deles destruía o `<select>` aberto no meio da escolha, que foi o que o
 * dono viu duas vezes.
 *
 * Uma barra é uma largura em CSS. Mexer nela não pede DOM novo, e é isso que
 * esta função faz: acha as barras pelo nome do dono e ajusta. A estrutura só é
 * refeita quando ela realmente muda (ver `cuidarDaJanelaDaParty`, no main).
 */
export function atualizarBarrasDaParty(body, party, grupo = null) {
  if (!body || !party) return;
  /* Os cooldowns vêm da CAÇADA, por nome — a party não tem barra de ação. */
  const acoesDe = new Map((grupo?.membros ?? []).map((m) => [m.name, m.acoes ?? null]));

  for (const membro of party.membros ?? []) {
    const card = body.querySelector(`[data-membro="${CSS.escape(membro.name)}"]`);
    if (!card) continue;
    const ajustar = (classe, feito, total, titulo) => {
      const linha = card.querySelector(`.party-linha-barra.${classe}`);
      const barra = linha?.querySelector('.party-barra i');
      if (!barra) return;
      barra.style.width = `${Math.max(0, Math.min(100, (feito / Math.max(1, total)) * 100))}%`;
      if (linha) linha.title = titulo;
    };
    ajustar('hp', membro.hp, membro.maxHp, `Vida ${membro.hp} de ${membro.maxHp}`);
    ajustar('mana', membro.mana, membro.maxMana, `Mana ${membro.mana} de ${membro.maxMana}`);
    ajustar('exp', membro.progresso * 100, 100, `${Math.floor(membro.progresso * 100)}% do level ${membro.level}`);

    /*
     * ---- Os relógios da barra dele, pelo mesmo motivo das barras ----
     *
     * O que sobra de cooldown muda a cada quadro. Se isso entrasse na
     * assinatura, a janela seria remontada quatro vezes por segundo e os
     * seletores voltariam a fechar sozinhos — o defeito de sempre.
     *
     * Então a assinatura guarda só QUAIS magias estão na barra, e o número é
     * escrito aqui, por cima do que já existe.
     */
    const acoes = acoesDe.get(membro.name);
    if (!acoes) continue;
    const slots = card.querySelectorAll('.party-spell');
    if (slots.length !== acoes.length) continue;
    // O relógio de cada magia chega como INSTANTE, no mesmo formato do da barra
    // de ações e com o mesmo `clock` da caçada. Ver `faltaDoCooldown`.
    const clock = ctx.state.hunt?.clock ?? 0;
    acoes.forEach((acao, i) => {
      const slot = slots[i];
      const falta = faltaDoCooldown(acao, clock);
      slot.classList.toggle('frio', falta > 0);
      // O leque e o algarismo são desenhados pelo laço da barra, a 60 quadros.
      acompanharCooldown(slot, falta, acao.total);
    });
  }
}

export function corpoDaJanelaDaParty(body) {
  const { state, send } = ctx;
  const party = state.character?.party ?? null;
  const grupo = state.hunt?.party ?? null;

  body.innerHTML = '';
  if (!party) {
    /*
     * ---- Sem party, a janela é o convite ----
     *
     * Ela dizia "você não está numa party" e mais nada — uma janela que informa
     * um vazio e não oferece a saída dele. O botão da barra é a porta de
     * entrada da party, e quem clica nele sem ter uma quer COMEÇAR uma.
     *
     * Então aqui vai o que basta para isso: os amigos online, com um convite em
     * cada. Sem amigos online, a frase explica por que a lista está vazia.
     */
    body.append(el('p', 'empty', 'Você não está numa party. Chame alguém:'));
    const online = (state.friends?.amigos ?? []).filter((amigo) => amigo.online);
    if (online.length) {
      const lista = el('div', 'party-amigos');
      for (const amigo of online.slice(0, 12)) {
        const botao = el('button', 'ghost', `+ ${amigo.name}`);
        botao.title = `convidar ${amigo.name} (level ${amigo.level}) para a party`;
        botao.onclick = () => send({ t: 'grupo', action: 'convidar', name: amigo.name });
        lista.append(botao);
      }
      body.append(lista);
    } else {
      body.append(el('p', 'shop-note', 'Nenhum amigo online agora. Em Amigos dá para convidar pelo nome.'));
    }
    return;
  }

  /*
   * O estado da partilha primeiro: é a linha que o jogador procura quando algo
   * parece errado, e a que explica por que a experiência parou de dividir.
   */
  const estado = el('div', 'party-estado');
  estado.append(escudoDaPartyImg(true, !!grupo?.ativa));
  estado.append(
    el(
      'b',
      null,
      !grupo
        ? 'Fora de caçada'
        : grupo.ativa
          ? 'Shared Experience ativa'
          : `Sem partilha: ${MOTIVO_DA_PARTY_DO_PAINEL[grupo.motivo] ?? grupo.motivo}`
    )
  );
  /*
   * ---- O bônus de vocações, também na janela encaixada ----
   *
   * Esta é a que fica aberta durante a caçada, então é aqui que a pergunta
   * "por que estou ganhando isso?" aparece. Só com a partilha LIGADA: com ela
   * desligada o bônus não é aplicado, e mostrar "+70%" embaixo de "Sem
   * partilha" prometeria um número que ninguém vai receber.
   */
  if (grupo?.ativa && grupo.bonus > 1) {
    const quantas = grupo.vocacoes ?? 1;
    const marca = el('b', 'party-bonus', `+${Math.round((grupo.bonus - 1) * 100)}% de experiência`);
    marca.title = [
      `${quantas} vocaç${quantas === 1 ? 'ão' : 'ões'} diferente${quantas === 1 ? '' : 's'} na caçada.`,
      'Mesma vocação +20% · duas +35% · três +70% · quatro ou mais +100%.',
      'Vale para criaturas de 20 de experiência para cima.',
    ].join('\n');
    estado.append(marca);
  }
  body.append(estado);

  /*
   * ---- Alguém pediu para entrar na SUA caçada ----
   *
   * O cartão flutuante (`mostrarPedidoDeEntrada`, em main.mjs) some sozinho e
   * pode ser fechado sem querer. Este aviso fica: quem voltar à janela da party
   * acha o pedido em pé ali, com os mesmos dois botões.
   *
   * É a outra ponta do "Entrar na hunt" que aparece nos cards — ver
   * `podePedirEntrada`.
   */
  if (state.pedidoDeEntrada?.de) {
    const pedido = el('div', 'party-pedido');
    pedido.append(el('b', null, `${state.pedidoDeEntrada.de} quer entrar na sua caçada`));
    const escolhas = el('div', 'party-pedido-acoes');
    const deixar = el('button', 'primary', 'Deixar entrar');
    deixar.onclick = () => send({ t: 'party', action: 'aceitarPedido' });
    const recusar = el('button', 'ghost', 'Agora não');
    recusar.onclick = () => send({ t: 'party', action: 'recusarPedido' });
    escolhas.append(recusar, deixar);
    pedido.append(escolhas);
    body.append(pedido);
  }

  /*
   * O interruptor vem ANTES dos cards, e não depois.
   *
   * Ele estava no rodapé desta janela, que tem 232 por 320: com três cards já
   * ficava abaixo da dobra, e a opção simplesmente não existia para quem não
   * rolasse a lista até o fim. Uma opção que muda o que a janela mostra tem de
   * ser visível junto com o que ela muda.
   */
  opcaoDeVerAsAcoes(body, state, send);

  const grade = el('div', 'party-grade estreita');
  for (const membro of party.membros) grade.append(cardDaParty(membro, party, send));
  body.append(grade);
  const setoresDaInstancia = blocoDosSetores(ctx.state.hunt?.setores);
  if (setoresDaInstancia) body.append(setoresDaInstancia);

  /*
   * ---- As duas escolhas são da caçada AUTOMÁTICA ----
   *
   * "Na frente" e "seguir a X sqm" dizem ao piloto automático como se
   * posicionar. Na Caça Online não há piloto: quem anda é a pessoa, com a tecla
   * na mão. Oferecer os dois seletores ali seria prometer um comportamento que
   * o modo não tem — e o jogador escolheria 3 sqm e veria o boneco ignorar.
   */
  escolhasDaPosicao(body, grupo, state, send);

  const rodape = el('div', 'confirm-actions');
  const sair = el('button', 'ghost', 'Sair da party');
  sair.onclick = () => send({ t: 'grupo', action: 'sair' });
  rodape.append(sair);
  body.append(rodape);
}

/*
 * ---- A FORJA ----
 *
 * O pedido: "implemente o sistema de forja que é basicamente igual subir o tier
 * do item mas só usando kks (gold)... a princípio deixa só o sistema de subir
 * tier, e o sistema de passar tier pra outro item". E depois, com o print da
 * Exaltation Forge do client dele na mão: "a forja tem que ser bem feita,
 * bonita igual esse sistema e o sistema da crystal server ok, mas mantendo só
 * usar gold".
 *
 * ---- O desenho é o da BANCADA, e não o de uma lista ----
 *
 * A tela do client dele tem três partes, nesta ordem de cima para baixo:
 *
 *   1. as abas do que se pode fazer;
 *   2. a BANCADA — as peças escolhidas, lado a lado, com as setas entre elas;
 *   3. os REQUISITOS — o que a operação custa, e o botão que a executa.
 *
 * É esse o desenho aqui, e não por imitação: ele responde na ordem em que as
 * perguntas aparecem. "O que eu vou fazer", "com o quê", "quanto custa". Uma
 * lista de peças com um botão em cada linha responde as três de uma vez, em
 * vinte lugares ao mesmo tempo — e foi o que a primeira versão desta tela fez.
 *
 * A regra e o preço vêm do servidor (`forja.mjs`) dentro de cada ficha. A tela
 * não recalcula nada: repetir a fórmula aqui daria dois lugares para ela mudar,
 * e o segundo passaria a mentir sem ninguém notar.
 */
/*
 * ---- AS TRÊS ABAS DA FORJA ----
 *
 * "na forja terá 3 abas: a do Tier, que vai ser o que já temos na forja
 * atualmente; a aba dos Afixos, que será um sistema futuro de rerollar ou trocar
 * afixos entre os itens; e a terceira aba será a de Craft, que vai ser pra
 * craftar os sets craftado e crafted v2."
 *
 * O que era a forja inteira virou o miolo da PRIMEIRA aba — inclusive as duas
 * sub-abas que ela já tinha (subir tier e passar tier), que continuam onde
 * estavam. Nada do Tier mudou de comportamento: ele só ganhou um andar acima.
 */
/*
 * A ordem é a que o dono pediu: "deixa a página de craft em primeiro". A aba
 * que abre é a primeira, e é ela que a maioria vem procurar.
 */
/*
 * E a QUARTA, que chegou com o Crafted V2: o Desmanche.
 *
 * Ela fica ao lado do Craft de propósito, e não numa janela própria: a máquina
 * existe para alimentar a receita da aba vizinha — o V2 pede 500 Dismantle
 * Token por peça, e não há outra fonte deles no jogo. Separá-las faria a
 * pergunta ("onde arrumo o token?") e a resposta morarem em telas diferentes.
 */
const ABAS_DA_FORJA = { craft: 'Craft', desmanche: 'Desmanche', tier: 'Tier', afixos: 'Afixos' };

export function openForja() {
  ctx.send({ t: 'forja' });
  ctx.tabs.forjaAba ??= 'craft';
  // A sub-aba do Tier. Era `forjaAba`, e o nome subiu um andar junto com a tela.
  ctx.tabs.forjaTier ??= 'subir';
  if (ctx.tabs.forjaAba === 'craft') pedirCraft();
  /*
   * O retrato dos afixos é pedido junto quando a aba já está nela — abrir a
   * forja direto nos Afixos (a aba fica guardada entre visitas) mostraria
   * "carregando..." até alguém trocar de aba e voltar.
   */
  if (ctx.tabs.forjaAba === 'afixos') ctx.send({ t: 'forjaAfixos' });
  // E o desmanche pelo mesmo motivo: a aba fica guardada entre visitas.
  if (ctx.tabs.forjaAba === 'desmanche') ctx.send({ t: 'desmanche' });
  /*
   * ---- A janela da forja é MAIS LARGA que a padrão ----
   *
   * "a página da forja dá pra ser maior?"
   *
   * Dá, e não quebra no celular: a largura é `min(1180px, 96vw)`, e abaixo de
   * 900px de tela a regra de `@media` do `.modal-box` manda em 100vw de qualquer
   * jeito. É a mesma largura da loja, que é a outra janela deste jogo com duas
   * colunas de conteúdo lado a lado.
   */
  ctx.openModal(
    'Forja',
    (body) => {
      const draw = () => {
        body.innerHTML = '';
        renderForja(body);
      };
      ctx.redraw = draw;
      draw();
    },
    null,
    'forja'
  );
}

function renderForja(body) {
  const aba = ctx.tabs.forjaAba;
  body.append(
    tabBar(ABAS_DA_FORJA, aba, (next) => {
      ctx.tabs.forjaAba = next;
      /*
       * As peças escolhidas na bancada são do Tier, e só valem lá. Sair para os
       * Afixos e voltar com a doadora ainda marcada seria voltar para o meio de
       * uma operação que a pessoa já abandonou.
       */
      ctx.tabs.forjaAlvo = null;
      ctx.tabs.forjaDoadora = null;
      /*
       * O catálogo do craft só é pedido quando a aba abre. Ele é grande, e
       * mandá-lo junto com o retrato da forja faria toda subida de tier arrastar
       * cento e poucas receitas pelo socket sem ninguém ter aberto a aba.
       */
      if (next === 'craft') pedirCraft();
      // O mesmo para os Afixos: o retrato deles é outro pedido, e a aba abre
      // vazia sem ele. Ver a nota do `pedirCraft`.
      if (next === 'afixos') ctx.send({ t: 'forjaAfixos' });
      if (next === 'desmanche') ctx.send({ t: 'desmanche' });
      if (next !== 'afixos') limparBancadaDeAfixos();
      ctx.redraw();
    })
  );

  if (aba === 'afixos') return void renderForjaAfixos(body);
  if (aba === 'craft') return void renderForjaCraft(body);
  if (aba === 'desmanche') return void renderForjaDesmanche(body);
  renderForjaTier(body);
}

/* ---- A aba do Desmanche: a máquina do dono, aqui dentro ---- */

/*
 * ---- A MÁQUINA DE DESMANCHE ----
 *
 * "vc vai trazer o sistema desmanche pro servidor — dismantle_machine.lua está
 *  na área de trabalho, vê como funciona e implementa."
 *
 * O script dele é uma máquina no mapa com quatro janelas modais em fila:
 * categoria -> item -> quantidade -> prévia -> desmanchar. Quatro janelas
 * existem lá porque o Tibia só tem `ModalWindow`: não dá para pôr duas coisas
 * na mesma tela. Aqui dá, e por isso a fila virou UMA tela com dois andares:
 *
 *   em cima   os sete grupos, cada um mostrando só o que a pessoa TEM
 *   embaixo   a peça escolhida, com a quantidade e a conta do que ela rende
 *
 * O que foi mantido ao pé da letra é o que importa: os sete grupos, os ids de
 * cada um e quantos tokens cada grupo paga. Ver `desmanche.mjs`, no servidor —
 * quem decide tudo é ele, e esta tela não recalcula nada.
 */
/*
 * ---- A lista INTEIRA de um grupo, atrás da setinha ----
 *
 * "ao lado do nome dos negócio de desmanche, tipo ao lado de Soulwar, tem que
 *  ter uma setinha que ao clicar sobe um modalzinho que mostra itens de Soulwar
 *  que pode ser desmanchado e os valores."
 *
 * A grade da caixa mostra só o que a pessoa TEM — é o que o lua faz, e é o
 * certo para escolher. O que faltava era a outra pergunta: o que ENTRA neste
 * grupo. Quem tem uma peça Falcon via uma peça, e não tinha como saber se as
 * outras doze contavam.
 *
 * Uma caixinha por cima, e não uma aba nova: é consulta, some ao fechar, e a
 * escolha que estava sendo feita atrás continua onde estava. A mesma moldura do
 * `confirmarDeNovo`, que é a caixa que este jogo usa para o que aparece por
 * cima de outra tela.
 */
function listaDoGrupoDoDesmanche(categoria, itemDoToken) {
  const back = el('div', 'confirm-back');
  const box = el('div', 'confirm-box confirm-largo');
  box.append(el('h3', null, categoria.nome));

  const resumo = el('p', 'desmanche-lista-resumo');
  resumo.append(itemCanvas(itemDoToken, 18));
  resumo.append(el('b', null, String(categoria.tokens)));
  resumo.append(el('span', null, `${categoria.tokens === 1 ? 'token' : 'tokens'} por peça — ${categoria.todos.length} peças entram neste grupo`));
  box.append(resumo);

  /*
   * Quem TEM vem primeiro. A lista é de consulta, mas quem a abre quase sempre
   * está decidindo o que desmanchar agora — e as trinta peças do Umbral com
   * "0" em cima da única que ele tem seriam um catálogo, não uma resposta.
   */
  const ordenadas = [...categoria.todos].sort((a, b) => (b.tem ?? 0) - (a.tem ?? 0) || a.nome.localeCompare(b.nome));

  const lista = el('div', 'desmanche-lista');
  for (const item of ordenadas) {
    const linha = el('div', `desmanche-lista-linha${item.tem ? ' tem' : ''}`);
    linha.append(itemCanvas(item.id, 26));
    const texto = el('div', 'desmanche-lista-texto');
    texto.append(el('b', null, item.nome));
    texto.append(el('span', null, item.tem ? `você tem ${money(item.tem)}` : 'você não tem'));
    linha.append(texto);
    const paga = el('div', 'desmanche-lista-paga');
    paga.append(el('b', null, String(categoria.tokens)));
    paga.append(itemCanvas(itemDoToken, 14));
    linha.append(paga);
    lista.append(linha);
  }
  box.append(lista);

  const fechar = () => back.remove();
  const acoes = el('div', 'confirm-actions');
  const botao = el('button', 'ghost', 'Fechar');
  botao.onclick = fechar;
  acoes.append(botao);
  box.append(acoes);
  back.append(box);
  fecharAoClicarFora(back, fechar);
  atalhosDaCaixa(back, { confirmar: fechar, fechar });
  document.body.append(back);
  botao.focus();
}

/*
 * ---- A MÁQUINA DE DESMANCHE ----
 *
 * "vc vai trazer o sistema desmanche pro servidor — dismantle_machine.lua está
 *  na área de trabalho, vê como funciona e implementa."
 *
 * O script dele é uma máquina no mapa com quatro janelas modais em fila:
 * categoria -> item -> quantidade -> prévia -> desmanchar. Quatro janelas
 * existem lá porque o Tibia só tem `ModalWindow`: não dá para pôr duas coisas
 * na mesma tela. Aqui dá, e por isso a fila virou UMA tela com dois andares:
 *
 *   em cima   os sete grupos, cada um mostrando só o que a pessoa TEM
 *   embaixo   o que ela marcou, peça por peça, com a conta do que aquilo rende
 *
 * O que foi mantido ao pé da letra é o que importa: os sete grupos, os ids de
 * cada um e quantos tokens cada grupo paga. Ver `desmanche.mjs`, no servidor —
 * quem decide tudo é ele, e esta tela não recalcula nada.
 *
 * ---- VÁRIAS peças de uma vez ----
 *
 * "eu tenho que conseguir selecionar mais itens pra desmanchar ao mesmo tempo
 *  se eu quiser."
 *
 * Então a escolha é uma LISTA e não uma peça: clicar marca, clicar de novo
 * desmarca, e cada marcada ganha a linha dela embaixo com a própria quantidade.
 * O botão desmancha tudo de uma vez, e o servidor trata o pedido como tudo ou
 * nada (ver `desmanchar`) — cinco peças marcadas contra um total em tokens não
 * podem virar três peças e outro total.
 */
function renderForjaDesmanche(body) {
  const { state, send } = ctx;
  const view = state.desmanche;
  if (!view) return void body.append(el('p', 'empty', 'carregando a máquina...'));

  /* O que está marcado: `{ [itemId]: quantas }`. Sobrevive aos redesenhos. */
  const marcadas = (ctx.tabs.desmancheSel ??= {});

  /*
   * O cabeçalho responde as duas perguntas que a pessoa chega fazendo: quantos
   * tokens eu tenho, e para que eles servem. A segunda é a mais importante —
   * sem ela o token é um item sem uso, e a máquina, um botão de destruir peça.
   */
  const topo = el('div', 'desmanche-topo');
  topo.append(itemCanvas(view.itemDoToken, 28));
  const saldo = el('div', 'desmanche-topo-texto');
  saldo.append(el('b', null, `${money(view.token)} Dismantle Token`));
  saldo.append(
    el('em', null, 'Material do set Crafted V2, na aba ao lado. A máquina é a única fonte deles.')
  );
  topo.append(saldo);
  body.append(topo);

  /*
   * ---- A caixa de um grupo ----
   *
   * "quando tiver ali escrito embaixo tá feio — deixa mais bonito e deixa a
   *  sprite do token do lado."
   *
   * Dois andares: o nome em cima, com a setinha da lista e a contagem; embaixo
   * a sprite do Dismantle Token com o que ele paga. A sprite é a mesma do
   * cabeçalho e a mesma da conta lá de baixo — é ela que amarra as três partes
   * da tela como sendo sobre a mesma coisa.
   */
  const caixaDoGrupo = (categoria, vazia = false) => {
    const caixa = el('div', `desmanche-grupo${vazia ? ' vazio' : ''}`);
    /*
     * ---- Cada grupo é uma LINHA, e não um cartão ----
     *
     * Eram sete cartões embrulhando numa grade, e ficou torto: o Umbral tem
     * seis tipos e o Lions tem três, então os cartões saíam com alturas
     * diferentes, o embrulho deixava buracos entre eles e o último caía sozinho
     * numa fileira com meia tela vazia ao lado.
     *
     * Em linha isso não acontece: o nome e o pagamento ficam numa coluna fixa à
     * esquerda, as peças correm para a direita, e cada linha tem exatamente a
     * altura das peças dela. Sete linhas empilhadas, sem buraco nenhum.
     */
    const lado = el('div', 'desmanche-grupo-lado');
    const cabeca = el('div', 'desmanche-grupo-nome');
    cabeca.append(el('b', null, categoria.nome));

    /*
     * A setinha: a lista inteira do grupo, com o que cada peça paga.
     *
     * "a setinha pra eu ver o que pode ser desmanchado quase não dá pra ver."
     *
     * Era um caractere solto em cinza, do tamanho do texto ao lado. Virou um
     * botão com moldura e fundo, com a contagem do grupo escrita dentro — o
     * número é o que dá vontade de clicar ("22 peças entram aqui?"), e um
     * triângulo sozinho não conta isso.
     */
    if (categoria.todos?.length) {
      const seta = el('button', 'desmanche-seta');
      seta.type = 'button';
      seta.append(el('span', 'desmanche-seta-conta', String(categoria.todos.length)));
      seta.append(el('span', 'desmanche-seta-bico', '▾'));
      seta.title = `Ver as ${categoria.todos.length} peças que entram em ${categoria.nome}`;
      seta.onclick = (evento) => {
        evento.stopPropagation();
        listaDoGrupoDoDesmanche(categoria, view.itemDoToken);
      };
      cabeca.append(seta);
    }

    lado.append(cabeca);

    const paga = el('div', 'desmanche-grupo-paga');
    paga.append(itemCanvas(view.itemDoToken, 16));
    paga.append(el('b', null, String(categoria.tokens)));
    paga.append(el('span', null, `${categoria.tokens === 1 ? 'token' : 'tokens'} por peça`));
    lado.append(paga);
    caixa.append(lado);
    return caixa;
  };

  const comPeca = view.categorias.filter((categoria) => categoria.itens.length);
  if (!comPeca.length) {
    body.append(
      el(
        'p',
        'empty',
        'Você não tem nenhuma peça que a máquina aceite. Ela desmancha os conjuntos ' +
          'Destruction, Soulwar, Sanguine, Falcon, Lion, Primal e Umbral — e as bags deles.'
      )
    );
    /*
     * Os sete grupos aparecem mesmo vazios. Uma tela que só diz "você não tem
     * nada" não ensina o que procurar, e este é o primeiro contato de todo
     * mundo com a máquina — a setinha de cada um responde o que entra ali.
     */
    const vazios = el('div', 'desmanche-grupos');
    for (const categoria of view.categorias) vazios.append(caixaDoGrupo(categoria, true));
    body.append(vazios);
    return;
  }

  /* Só o que continua existindo: uma peça desmanchada some da marcação. */
  const porId = new Map(comPeca.flatMap((c) => c.itens.map((item) => [item.id, item])));
  for (const id of Object.keys(marcadas)) {
    const item = porId.get(Number(id));
    if (!item || !item.pode) delete marcadas[id];
    else marcadas[id] = Math.min(marcadas[id], item.pode);
  }

  const grupos = el('div', 'desmanche-grupos');
  for (const categoria of comPeca) {
    const caixa = caixaDoGrupo(categoria);

    const grade = el('div', 'filter-grid');
    for (const item of categoria.itens) {
      /*
       * ---- A sprite aqui é MAIOR que a do filtro de loot ----
       *
       * "a sprite dos itens ali do desmanche pode aumentar."
       *
       * O quadradinho de 44px com desenho de 30px é o do filtro, onde a grade
       * tem oitenta itens e o que se procura é um id conhecido. Aqui são três
       * ou quatro peças, e o que se procura é QUAL delas — o desenho é a única
       * coisa que diferencia uma soulcrusher de uma soulmaimer.
       */
      const cela = itemCell({ id: item.id, count: item.pode || item.presas }, 'filter', { size: 42 });
      if (marcadas[item.id]) cela.classList.add('protected');
      if (!item.pode) cela.classList.add('barred');
      /*
       * O balão diz o que a peça rende E o que a segura. O lua escondia a peça
       * presa, e quem tinha só peças com tier via um grupo vazio sem saber por
       * quê — é o tipo de silêncio que vira report.
       */
      const partes = [`${money(item.pode)} para desmanchar`, `${categoria.tokens} token cada`];
      if (item.presas) partes.push(`${money(item.presas)} fora: ${item.motivo}`);
      tipFor(cela, item.id, partes.join(' — '));
      cela.onclick = () => {
        if (!item.pode) return;
        if (marcadas[item.id]) delete marcadas[item.id];
        else marcadas[item.id] = 1;
        ctx.redraw?.();
      };
      grade.append(cela);
    }
    caixa.append(grade);
    grupos.append(caixa);
  }
  body.append(grupos);

  const escolhidas = Object.keys(marcadas)
    .map((id) => ({ item: porId.get(Number(id)), quantos: marcadas[id] }))
    .filter((linha) => linha.item);

  if (!escolhidas.length) {
    return void body.append(
      el('p', 'shop-note dica', 'Clique nas peças que quer desmanchar — dá para marcar várias de uma vez.')
    );
  }

  /*
   * ---- O andar de baixo: a prévia do lua, com uma linha por peça marcada ----
   *
   * Os degraus de quantidade são os dele (`montarEscolhasQuantidade`), cortados
   * pelo que a pessoa tem de CADA peça. Uma caixa de digitar número seria pior
   * aqui: quase sempre se quer "uma" ou "todas".
   */
  const ficha = el('div', 'desmanche-ficha');
  /*
   * ---- As linhas rolam; o total e os botões NÃO ----
   *
   * "o preview tá tampando muito a tela, e o botão de desmanchar e cancelar tem
   *  que scrolar pra ver ele."
   *
   * A ficha inteira rolava junto, então com quatro peças marcadas o botão
   * descia para fora da caixa. Agora a lista de peças é que rola, dentro de um
   * teto baixo, e o rodapé com a soma e os dois botões fica sempre no pé — que
   * é onde a pessoa olha depois de marcar.
   */
  const lista = el('div', 'desmanche-linhas');

  /*
   * ---- A conta é refeita SEM redesenhar a tela ----
   *
   * O deslizante (logo abaixo) muda o número a cada pixel arrastado, e um
   * `redraw` por pixel destruiria o próprio elemento que está sendo arrastado —
   * o ponteiro soltaria no primeiro quadro e o arrasto morreria.
   *
   * Então quem muda é o VALOR, e estas funções repintam só os três textos que
   * dependem dele: o número da linha, a conta da linha e a soma do rodapé. A
   * tela inteira só é refeita quando a peça sai ou entra da seleção.
   */
  const pintores = [];
  const repintarTudo = () => {
    for (const pintar of pintores) pintar();
  };

  for (const { item } of escolhidas) {
    const linhaEl = el('div', 'desmanche-linha');

    const nome = el('div', 'desmanche-ficha-nome');
    nome.append(itemCanvas(item.id, 28));
    const texto = el('div', 'desmanche-linha-texto');
    texto.append(el('b', null, item.nome));
    texto.append(el('em', null, `${money(item.pode)} para desmanchar`));
    nome.append(texto);

    const tirar = el('button', 'desmanche-tirar', '✕');
    tirar.type = 'button';
    tirar.title = 'Tirar da lista';
    tirar.onclick = () => {
      delete marcadas[item.id];
      ctx.redraw?.();
    };
    nome.append(tirar);
    linhaEl.append(nome);

    /*
     * ---- Quantas: um deslizante ----
     *
     * Primeiro eram os degraus fixos do lua (1, 5, 10, 25, 50, 100), cortados
     * pelo que a pessoa tem — com quatro peças ela via "1" e "Tudo (4)", e
     * pedir TRÊS era impossível. Virou menos-e-mais, e o dono pediu o passo
     * seguinte: "em vez de + e − pra adicionar quantidade, teria que ser um
     * scrollzinho horizontal".
     *
     * É um `range` de 1 até o que ele tem. Para quatro peças é um gesto; para
     * quatrocentas, também — que é onde o menos-e-mais ficava impossível e os
     * degraus fixos não acertavam o número.
     *
     * Os degraus continuam ao lado, como ATALHO do que eles sempre foram bons:
     * pular para 50 sem arrastar.
     */
    const passo = el('div', 'desmanche-passo');

    /*
     * ---- Uma cópia só não ganha deslizante ----
     *
     * "itens que só têm uma quantidade não precisa ter o scroll horizontal."
     *
     * Não precisa mesmo: um controle de 1 até 1 é um trilho travado, com o
     * botão encostado nas duas pontas ao mesmo tempo. Ele ocupava a fileira
     * inteira para não deixar escolher nada.
     *
     * Nesse caso sobra só a conta ("1x vira 5"), que é a resposta inteira.
     */
    const umaSo = item.pode <= 1;

    const trilho = el('input', 'desmanche-trilho');
    trilho.type = 'range';
    trilho.min = '1';
    trilho.max = String(Math.max(1, item.pode));
    trilho.step = '1';
    trilho.value = String(marcadas[item.id]);
    trilho.setAttribute('aria-label', `Quantas ${item.nome} desmanchar`);

    const numero = el('b', 'desmanche-passo-numero');
    const de = el('span', 'desmanche-passo-de', `de ${money(item.pode)}`);
    const conta = el('p', 'desmanche-conta');

    const degraus = el('div', 'desmanche-quantos');
    const atalhos = [];
    const porAtalho = (valor, rotulo) => {
      const botao = el('button', 'filtro-afixo-opcao');
      botao.type = 'button';
      botao.append(el('span', null, rotulo));
      botao.onclick = () => {
        marcadas[item.id] = valor;
        trilho.value = String(valor);
        repintarTudo();
      };
      atalhos.push({ botao, valor });
      degraus.append(botao);
    };
    for (const n of [5, 10, 25, 50, 100].filter((n) => n < item.pode)) porAtalho(n, String(n));
    if (item.pode > 1) porAtalho(item.pode, `Tudo (${money(item.pode)})`);

    /* O repintor desta linha. Ver `pintores`, lá em cima. */
    pintores.push(() => {
      const quantos = marcadas[item.id];
      numero.textContent = money(quantos);
      conta.innerHTML = '';
      conta.append(el('b', null, `${money(quantos)}x`));
      conta.append(el('span', null, quantos === 1 ? ' vira ' : ' viram '));
      conta.append(itemCanvas(view.itemDoToken, 16));
      conta.append(el('b', null, money(quantos * item.tokens)));
      for (const atalho of atalhos) atalho.botao.classList.toggle('ativo', atalho.valor === quantos);
    });

    trilho.oninput = () => {
      marcadas[item.id] = Math.max(1, Math.min(item.pode, Math.round(Number(trilho.value) || 1)));
      repintarTudo();
    };

    /*
     * ---- Dois andares por peça, e não quatro ----
     *
     * Eram o nome, o deslizante, a conta e o aviso, um embaixo do outro: quatro
     * fileiras vezes quatro peças marcadas tampavam a tela.
     *
     * Agora a CONTA anda junto do deslizante, na mesma fileira — ela é a
     * resposta do que ele acabou de arrastar, e é ali que o olho está. Quem tem
     * uma cópia só nem deslizante tem, então a conta sobe para a fileira do
     * nome e a peça inteira ocupa uma linha.
     */
    if (umaSo) {
      nome.insertBefore(conta, tirar);
    } else {
      passo.append(trilho, numero, de, degraus, conta);
      linhaEl.append(passo);
    }

    if (item.presas) {
      linhaEl.append(
        el(
          'em',
          'filter-legend',
          `${money(item.presas)} ${item.presas === 1 ? 'cópia' : 'cópias'} ${item.motivo} e ` +
            'não entra na máquina. A que sai é sempre a mais limpa que você tem.'
        )
      );
    }
    lista.append(linhaEl);
  }
  ficha.append(lista);

  const rodape = el('div', 'desmanche-total');
  const soma = el('p', 'desmanche-conta');
  rodape.append(soma);

  /* O total também é repintado a cada pixel do deslizante, e não redesenhado. */
  const quantasAgora = () => escolhidas.reduce((s2, l) => s2 + (marcadas[l.item.id] ?? 0), 0);
  const tokensAgora = () =>
    escolhidas.reduce((s2, l) => s2 + (marcadas[l.item.id] ?? 0) * l.item.tokens, 0);
  pintores.push(() => {
    const pecas = quantasAgora();
    soma.innerHTML = '';
    soma.append(el('b', null, `${money(pecas)} ${pecas === 1 ? 'peça' : 'peças'}`));
    soma.append(el('span', null, pecas === 1 ? ' vira ' : ' viram '));
    soma.append(itemCanvas(view.itemDoToken, 18));
    soma.append(el('b', null, `${money(tokensAgora())} Dismantle Token`));
  });

  const acoes = el('div', 'confirm-actions');
  const limpar = el('button', 'ghost', 'Limpar seleção');
  limpar.onclick = () => {
    ctx.tabs.desmancheSel = {};
    ctx.redraw?.();
  };
  const botaoDesmanchar = el('button', 'danger', 'Desmanchar');
  /*
   * Não tem volta, então passa por uma confirmação. A peça some com os afixos
   * dela, e "cliquei sem querer no 100" é o relato que esta caixa existe para
   * não acontecer.
   */
  /*
   * O número é lido NA HORA DO CLIQUE, e não no desenho: o deslizante mudou o
   * valor sem refazer a tela, e uma cópia guardada aqui seria a de antes do
   * arrasto — a caixa prometeria um total e o servidor receberia outro.
   */
  botaoDesmanchar.onclick = () => {
    const pecas = quantasAgora();
    confirmarDeNovo({
      titulo: 'Desmanchar',
      texto:
        `${money(pecas)} ${pecas === 1 ? 'peça vira' : 'peças viram'} ` +
        `${money(tokensAgora())} Dismantle Token. ` +
        (escolhidas.length > 1 ? `São ${escolhidas.length} tipos diferentes. ` : '') +
        'A peça é destruída, e isso não tem volta.',
      botao: 'Desmanchar',
      aoConfirmar: () => {
        send({
          t: 'desmancharPeca',
          pedidos: escolhidas.map(({ item }) => ({ id: item.id, quantidade: marcadas[item.id] })),
        });
        ctx.tabs.desmancheSel = {};
      },
    });
  };
  acoes.append(limpar, botaoDesmanchar);
  rodape.append(acoes);
  ficha.append(rodape);
  body.append(ficha);
  /* A primeira pintura: os textos nascem vazios e é esta chamada que os enche. */
  repintarTudo();
}

/* ---- A aba do Tier: a forja como ela já era ---- */
function renderForjaTier(body) {
  const { state, send } = ctx;
  const view = state.forja;
  if (!view) return void body.append(el('p', 'empty', 'carregando...'));

  const aba = ctx.tabs.forjaTier;
  body.append(
    tabBar({ subir: 'Subir tier', transferir: 'Passar tier' }, aba, (next) => {
      ctx.tabs.forjaTier = next;
      ctx.tabs.forjaAlvo = null;
      ctx.tabs.forjaDoadora = null;
      ctx.redraw();
    })
  );

  if (!view.pecas.length) {
    return void body.append(
      el('p', 'empty', 'Nenhuma peça que aceite tier no corpo ou na mochila. Arma, elmo, armadura e botas aceitam.')
    );
  }

  if (aba === 'subir') renderForjaSubir(body, view, send);
  else renderForjaTransferir(body, view, send);

  /*
   * A bolsa fica no RODAPÉ, como no client: ela é o que se confere depois de
   * ler o preço, e não antes de escolher a peça.
   */
  const bolsa = el('div', 'forja-bolsa');
  bolsa.append(itemCanvas(3031, 18), el('b', null, `${money(view.gold)}`), el('em', null, 'no bolso'));
  bolsa.append(
    el('em', 'forja-dica-rodape', `A Draevor Tier UP continua sendo o caminho barato. O teto é o tier ${view.tierMax}.`)
  );
  body.append(bolsa);
}

/*
 * ---- O efeito, quando a peça sai do fogo ----
 *
 * "tem que fazer um efeitinho quando forjar o item."
 *
 * O que ele resolve não é enfeite: subir tier troca UM DÍGITO num selo de
 * dezesseis pixels, no meio de uma tela que não muda em mais nada. Gastar 75
 * milhões e não ver nada acontecer é a definição de um clique que não deu
 * certo — e o aviso de texto passa no canto enquanto o olho ainda está na
 * bancada.
 *
 * Então o resultado aparece onde o olho já está, grande, com o brilho e as
 * fagulhas, e fica na tela até o próximo desenho.
 *
 * ---- Por quê UMA VEZ, e não a cada desenho ----
 *
 * `redraw` roda de novo a cada troca de aba e a cada peça escolhida. Sem a
 * trava, o mesmo brilho voltaria a piscar em cada um desses gestos, muito
 * depois de a forja ter acontecido. A marca é o retrato em si: o servidor manda
 * um objeto novo a cada resposta, e é a identidade dele que diz "isto é notícia
 * nova".
 */
let forjaJaMostrada = null;
/*
 * ---- O cartaz é GUARDADO, e não descartado ----
 *
 * A trava dizia "já mostrei este retrato" e voltava sem desenhar nada. Parecia
 * certo e escondia o cartaz por completo: o painel é redesenhado logo depois da
 * forja (o ouro mudou, e a ficha do personagem chega atrás), o corpo é
 * reconstruído do zero, e nessa segunda passada a trava impedia de repor o que
 * a primeira tinha acabado de pôr. O cartaz nascia e morria no mesmo instante —
 * medido: vinte forjas seguidas, nenhum `.forja-resultado` na tela.
 *
 * Agora o nó é construído UMA vez por resultado e reaproveitado: `append` move
 * o mesmo elemento, então a animação da palavra não recomeça a cada redesenho e
 * o cartaz fica até chegar um resultado novo.
 */
let cartazDaForja = null;

/*
 * ---- As palavras da forja ----
 *
 * FAILED!, SUCCESS! e UPGRADE! são efeitos do client 15.24 que o jogo tinha
 * perdido: o `efeitos-1525.mjs` reaproveitou a faixa 318-321 para as magias
 * novas. `tools/efeitos-da-forja.mjs` os trouxe de volta em ids próprios.
 */
const PALAVRA_UPGRADE = 343;
const PALAVRA_FALHOU = 345;
const PALAVRA_SUCESSO = 346;

/*
 * Um canvas que toca o efeito UMA vez e para no último quadro.
 *
 * Parar no fim, e não sumir, é de propósito: a palavra é o recado, e um recado
 * que apaga sozinho obriga a pessoa a estar olhando na hora exata. O laço
 * termina quando a animação termina — não fica girando atrás de uma aba fechada.
 */
/*
 * O `progress` que cai NO MEIO de um quadro, pelo tempo de cada um.
 *
 * `drawEffect` escolhe o quadro pela duração acumulada; para pousar num quadro
 * específico é preciso desfazer essa conta em vez de chutar uma fração.
 */
function progressoDoQuadro(id, indice) {
  const meta = effectInfo(id);
  const quadros = meta?.s?.length ?? 0;
  if (!quadros) return 0.5;
  const alvo = Math.min(indice, quadros - 1);
  const duracoes = meta.d?.length === quadros ? meta.d : new Array(quadros).fill(75);
  const total = duracoes.reduce((soma, d) => soma + d, 0) || 1;
  let antes = 0;
  for (let i = 0; i < alvo; i++) antes += duracoes[i];
  return Math.min(0.999, (antes + duracoes[alvo] / 2) / total);
}

function palavraDaForja(id, tamanho = 96) {
  const c = document.createElement('canvas');
  c.className = 'forja-palavra';
  c.width = tamanho;
  c.height = tamanho;
  const ctx = c.getContext('2d');
  ctx.imageSmoothingEnabled = false;
  const duracao = effectDuration(id) || 900;
  /*
   * Uma folga de 8px em volta: a palavra encosta na borda da célula de 64 do
   * sprite, e sem a folga o "F" de FAILED saía cortado.
   */
  const FOLGA = 8;
  const escala = (tamanho - FOLGA * 2) / 64;
  const comecou = performance.now();
  /*
   * ---- Toca UMA vez e para NO MEIO ----
   *
   * Três tentativas até aqui, e as duas primeiras estavam erradas por motivos
   * diferentes:
   *
   *   congelada no ÚLTIMO quadro   o fim destes efeitos é um fade, e o que
   *                                ficava na tela parecia um desenho quebrado
   *   repetindo para sempre        a palavra ficava piscando muito depois de a
   *                                forja ter acontecido, e virava ruído
   *
   * O meio da animação é onde a palavra está inteira e parada — é o quadro que
   * o próprio client usa como "pouso". Então ela toca do começo ao fim uma vez,
   * e fica ali.
   *
   * O laço acaba junto: nenhuma forja deixa um `requestAnimationFrame` girando
   * atrás de um painel fechado.
   */
  /*
   * ---- Onde ela POUSA: o segundo quadro ----
   *
   * "a animação tem que ir completa e parar no segundo quadro."
   *
   * Não dá para dizer isso em "metade": cada quadro destes efeitos tem a
   * duração dele (o FATAL, por exemplo, são 50, 50, 50 e 1200ms), então meio
   * caminho do TEMPO não é o meio dos QUADROS. A conta abaixo soma as durações
   * até o terceiro e mira no meio dele — assim o pouso é o quadro certo mesmo
   * que as durações mudem.
   */
  const POUSO = progressoDoQuadro(id, 1);
  const passo = (agora) => {
    const andado = agora - comecou;
    const acabou = andado >= duracao;
    const progresso = acabou ? POUSO : andado / duracao;
    ctx.clearRect(0, 0, tamanho, tamanho);
    ctx.save();
    // O sprite ancora no canto de baixo-direita: a origem vai para o canto
    // oposto para a palavra inteira caber.
    ctx.translate(FOLGA, FOLGA);
    ctx.scale(escala, escala);
    ctx.translate(64 - 32, 64 - 32);
    drawEffect(ctx, id, 0, 0, progresso);
    ctx.restore();
    if (!acabou) requestAnimationFrame(passo);
  };
  requestAnimationFrame(passo);
  return c;
}

/*
 * Qual palavra o resultado pede, e se ela já foi tocada.
 *
 * Devolve o canvas UMA vez por resultado: a bancada é redesenhada várias vezes
 * depois da forja (o ouro muda, a ficha chega atrás), e refazer o canvas a cada
 * redesenho faria a palavra recomeçar sem parar. Nas vezes seguintes volta o
 * MESMO nó, que o `append` apenas move de lugar.
 */
function palavraDoResultado(view) {
  const feito = view?.forjou;
  if (!feito) return null;
  if (forjaJaMostrada === view) return cartazDaForja;
  forjaJaMostrada = view;

  const id = feito.sucesso === false
    ? PALAVRA_FALHOU
    : feito.tipo === 'transferir'
      ? PALAVRA_SUCESSO
      : PALAVRA_UPGRADE;
  cartazDaForja = palavraDaForja(id, 128);
  return cartazDaForja;
}

/*
 * ---- A confirmação da forja ----
 *
 * "assim como na forja também precisa de confirmação."
 *
 * Os dois botões da forja são irreversíveis e caros: um gasta dezenas de
 * milhões, o outro DESTRÓI uma peça com tier. O tooltip dizia isso, e tooltip é
 * o que ninguém lê antes de clicar — só depois, procurando o que deu errado.
 *
 * A caixa repete o que a faixa de requisitos já mostra, de propósito: ela é a
 * última tela antes do irreversível, e ler o preço de novo com o dedo no botão
 * é justamente o gesto que ela existe para provocar. O que ela acrescenta é
 * como fica a bolsa depois — a mesma conta do balcão da Zuma, pelo mesmo
 * motivo.
 */
function confirmarForja({ id, tier, titulo, frases, custo, gold, acao, aoConfirmar }) {
  const back = el('div', 'confirm-back');
  const box = el('div', 'confirm-box forja-confirma');
  box.append(el('h3', null, titulo));

  const moldura = el('div', 'forja-moldura grande');
  if (id != null) moldura.append(itemCanvas(id, 48));
  if (tier) moldura.append(el('i', 'forja-selo', String(tier)));
  box.append(moldura);

  const lista = el('div', 'forja-confirma-frases');
  for (const frase of frases) {
    const linha = el('p', frase.perigo ? 'perigo' : null, frase.texto);
    lista.append(linha);
  }
  box.append(lista);

  const conta = el('div', 'balcao-conta');
  for (const [rotulo, valor, classe] of [
    ['Custa', `${money(custo)} de ouro`, null],
    ['No bolso agora', `${money(gold)} de ouro`, null],
    ['Fica com', `${money(gold - custo)} de ouro`, 'balcao-depois'],
  ]) {
    const item = el('div', 'balcao-conta-item');
    item.append(el('span', null, rotulo), el('b', classe, valor));
    conta.append(item);
  }
  box.append(conta);

  const fechar = () => back.remove();
  const acoes = el('div', 'confirm-actions');
  const cancelar = el('button', 'ghost', 'Cancelar');
  cancelar.onclick = fechar;
  const confirmar = el('button', 'primary', acao);
  confirmar.onclick = () => {
    fechar();
    aoConfirmar();
  };
  acoes.append(cancelar, confirmar);
  box.append(acoes);

  back.append(box);
  fecharAoClicarFora(back, fechar);
  atalhosDaCaixa(back, { confirmar: () => confirmar.click(), fechar });
  document.body.append(back);
  confirmar.focus();
}

/** Onde a peça está, em uma palavra — é o que separa duas espadas iguais. */
// O servidor manda o nome do lugar (`ondeNome`): com quatro lugares — corpo,
// mochila, bolsa de loot e depósito — a tela não tem como deduzir de `vestida`.
// O `??` cobre uma aba aberta desde antes da mudança.
const ondeAPecaEsta = (peca) => peca.ondeNome ?? (peca.vestida ? 'no corpo' : 'na mochila');

/** Duas fichas apontam para a mesma peça? */
// A CAIXA entra na comparação: o índice 0 da caixa 1 e o da caixa 2 são peças
// diferentes, e sem ela a bancada acharia que são a mesma.
const mesmoLugar = (a, b) =>
  !!a &&
  !!b &&
  a.onde === b.onde &&
  String(a.slot ?? a.indice) === String(b.slot ?? b.indice) &&
  String(a.caixa ?? '') === String(b.caixa ?? '');

const acharPeca = (view, lugar) => view.pecas.find((peca) => mesmoLugar(peca.lugar, lugar)) ?? null;

/**
 * ---- O QUADRO de uma peça na bancada ----
 *
 * Vazio ele é um alvo de clique: "escolha uma peça". Cheio, mostra a figura, o
 * nome e o tier — as três coisas que se confere antes de apertar o botão.
 *
 * O selo do tier fica no canto de cima, como o selo da mochila: é o mesmo dado,
 * e o olho já sabe onde procurá-lo.
 */
function quadroDaForja(peca, { rotulo, vazio, aoClicar, destaque = null, palavra = null }) {
  const quadro = el('button', `forja-quadro${peca ? ' cheio' : ''}${destaque ? ` ${destaque}` : ''}`);
  quadro.append(el('em', 'forja-rotulo', rotulo));

  const moldura = el('div', 'forja-moldura');
  if (peca) {
    moldura.append(itemCanvas(peca.id, 40));
    if (peca.tier) moldura.append(el('i', 'forja-selo', String(peca.tier)));
  } else {
    moldura.append(el('span', 'forja-vazio', '+'));
  }
  /*
   * A palavra do resultado sai AQUI, em cima da peça — e não numa faixa à parte.
   *
   * "em vez de ter essa parte extra em cima que mostra o sucesso, deveria
   *  aparecer lá onde está a peça colocada."
   *
   * Ela é filha do QUADRO, e não da moldura de 52px: dentro da moldura ela saía
   * cortada (foi a primeira tentativa, e virou três borrões atrás do elmo).
   * Aqui ela cobre o quadro inteiro, centrada, sem empurrar nada.
   */
  if (palavra) quadro.append(palavra);
  quadro.append(moldura);

  quadro.append(el('b', null, peca ? peca.nome : vazio));
  quadro.append(el('span', 'forja-onde', peca ? ondeAPecaEsta(peca) : 'clique para escolher'));
  quadro.onclick = aoClicar;
  return quadro;
}

/**
 * A lista de escolha, que abre por cima da bancada.
 *
 * Ela é uma tira e não uma janela nova: escolher a peça é parte do mesmo gesto,
 * e uma janela em cima da janela faria perder de vista o que já estava
 * escolhido do outro lado da seta.
 */
function escolherPeca(body, titulo, pecas, aoEscolher, vazio = 'Nenhuma peça serve aqui.') {
  body.append(el('h3', null, titulo));
  if (!pecas.length) return void body.append(el('p', 'empty', vazio));

  const tira = el('div', 'forja-escolha');
  for (const peca of pecas) {
    const botao = el('button', `forja-opcao${peca.tier ? ' tem-tier' : ''}`);
    /*
     * ---- O tier vai NO ITEM, e não só na linha de texto ----
     *
     * "na aba de transferência de tier tem que mostrar o tier ali, no próprio
     * item."
     *
     * Ele estava escrito ao lado do "no corpo", em cinza e em corpo 10, e é o
     * único número que importa nesta lista: escolher a doadora é escolher o
     * maior tier, e escolher a recebedora é escolher a que ganha mais. Lido
     * como palavra no fim de uma frase, ele obriga a ler quarenta frases.
     *
     * No selo dourado sobre a figura ele vira uma coluna que o olho percorre de
     * cima a baixo sem ler nada — e é o MESMO selo da bancada e da mochila, no
     * mesmo canto, o que dispensa aprender um segundo lugar de procurar.
     */
    const moldura = el('div', 'forja-moldura mini');
    moldura.append(itemCanvas(peca.id, 30));
    if (peca.tier) moldura.append(el('i', 'forja-selo', String(peca.tier)));
    botao.append(moldura);
    const texto = el('span', 'forja-opcao-texto');
    texto.append(el('b', null, peca.nome));
    texto.append(el('em', null, `${ondeAPecaEsta(peca)}${peca.tier ? ` · tier ${peca.tier}` : ''}`));
    botao.append(texto);
    botao.onclick = () => aoEscolher(peca);
    tira.append(botao);
  }
  body.append(tira);
}

/** A faixa de requisitos: o custo à esquerda, o botão à direita. */
function requisitosDaForja(body, { linhas, botao, aviso = null }) {
  const faixa = el('div', 'forja-requisitos');

  const custo = el('div', 'forja-custo');
  for (const linha of linhas) {
    const chip = el('div', `forja-chip${linha.ok === false ? ' falta' : ''}`);
    if (linha.item) chip.append(itemCanvas(linha.item, 20));
    chip.append(el('b', null, linha.valor));
    chip.append(el('em', null, linha.nome));
    custo.append(chip);
  }
  faixa.append(custo);
  faixa.append(botao);
  body.append(faixa);
  if (aviso) body.append(aviso);
}

function renderForjaSubir(body, view, send) {
  const escolhida = acharPeca(view, ctx.tabs.forjaAlvo);
  if (ctx.tabs.forjaAlvo && !escolhida) ctx.tabs.forjaAlvo = null;

  /*
   * O cartão inteiro se pinta pelo resultado: verde quando subiu, vermelho
   * quando caiu. Pedido do dono, e é a leitura mais rápida que existe — a cor
   * chega antes da palavra.
   */
  const deuCerto = view.forjou?.sucesso;
  const bancada = el(
    'div',
    `forja-bancada${deuCerto === true ? ' deu-certo' : deuCerto === false ? ' falhou' : ''}`
  );
  bancada.append(
    quadroDaForja(escolhida, {
      rotulo: 'Peça',
      vazio: 'Nenhuma peça escolhida',
      aoClicar: () => {
        ctx.tabs.forjaAlvo = null;
        ctx.redraw();
      },
    })
  );
  /*
   * ---- A seta fica VERDE quando a forja deu certo ----
   *
   * "quando for forja a setinha ali do meio fica verde."
   *
   * Ela é a passagem de uma peça para a outra; pintá-la é dizer que a passagem
   * aconteceu, no lugar onde o olho já está. Vermelha na falha, pela mesma
   * razão — e cinza enquanto nada foi tentado.
   */
  const setas = el(
    'div',
    `forja-setas${deuCerto === true ? ' deu-certo' : deuCerto === false ? ' falhou' : ''}`,
    '▶▶▶'
  );
  /*
   * A palavra fica NO MEIO, logo acima das setas.
   *
   * Em cima da peça ela tapava o desenho dela — e a peça é justamente o que a
   * pessoa quer ver. No meio, entre o "antes" e o "depois", ela é o que
   * aconteceu ENTRE os dois, que é exatamente o que ela diz.
   */
  const meio = el('div', 'forja-meio');
  const palavra = palavraDoResultado(view);
  if (palavra) meio.append(palavra);
  meio.append(setas);
  bancada.append(meio);

  /*
   * O quadro da DIREITA é o resultado, e não uma segunda escolha.
   *
   * Ele mostra a mesma peça com o tier que ela vai ter — é o que a forja do
   * client põe ali, e é o que responde "o que eu ganho com isso" sem obrigar a
   * ler o número do preço e fazer a conta de cabeça.
   */
  const resultado = escolhida?.subida ? { ...escolhida, tier: escolhida.subida.tier } : null;
  bancada.append(
    quadroDaForja(resultado, {
      rotulo: 'Fica',
      vazio: escolhida ? `Já está no tier ${view.tierMax}` : 'Escolha uma peça',
      aoClicar: () => {},
      destaque: 'resultado',
    })
  );
  body.append(bancada);

  if (!escolhida) {
    return void escolherPeca(body, 'Qual peça vai subir', view.pecas, (peca) => {
      ctx.tabs.forjaAlvo = peca.lugar;
      ctx.redraw();
    });
  }

  if (!escolhida.subida) {
    return void body.append(el('p', 'empty', `${escolhida.nome} já está no tier máximo (${view.tierMax}).`));
  }

  /*
   * ---- A forja PODE FALHAR, e a tela diz isso antes do clique ----
   *
   * É o sistema do crystalserver: 50% de chance, e falhar derruba a peça um
   * tier. O reforço custa mais ouro e leva a chance para 65% — o mesmo que o
   * núcleo faz lá.
   *
   * Dois botões, e não uma caixinha: a escolha é entre dois preços com duas
   * chances, e ver os dois lado a lado é o que permite decidir. Uma caixinha
   * esconderia metade da oferta atrás de um clique.
   *
   * A pedra `Draevor Tier UP` continua sem falhar — outro caminho, outro produto.
   */
  const botoes = el('div', 'forja-tentativas');
  const tentativa = (custo, rotulo, reforcada) => {
    const podePagar = view.gold >= custo.ouro;
    const botao = el('button', podePagar ? 'primary forja-botao' : 'ghost forja-botao');
    botao.append(el('b', null, rotulo));
    botao.append(el('em', null, `${custo.chance}% · ${money(custo.ouro)}`));
    botao.disabled = !podePagar;
    botao.title = podePagar
      ? `${custo.chance}% de subir ${escolhida.nome} para o tier ${custo.tier}.`
      : `Faltam ${money(custo.ouro - view.gold)} de ouro.`;
    botao.onclick = () =>
      confirmarForja({
        id: escolhida.id,
        tier: custo.tier,
        titulo: 'Subir o tier',
        frases: [
          { texto: `${escolhida.nome} (${ondeAPecaEsta(escolhida)}) tem ${custo.chance}% de chance de ir do tier ${escolhida.tier} para o tier ${custo.tier}.` },
          {
            texto: escolhida.tier > 0
              ? `Se FALHAR, ela CAI para o tier ${escolhida.tier - 1} e o ouro é gasto do mesmo jeito.`
              : 'Se FALHAR, só o ouro é gasto — no tier 0 não há tier a perder.',
            // `perigo` e' o que a caixa de confirmacao da forja pinta em vermelho.
            perigo: true,
          },
        ],
        custo: custo.ouro,
        gold: view.gold,
        acao: 'Forjar',
        aoConfirmar: () => send({ t: 'forjaSubir', lugar: escolhida.lugar, reforcada }),
      });
    return botao;
  };
  botoes.append(tentativa(escolhida.subida, 'Forjar', false));
  if (escolhida.reforcada) botoes.append(tentativa(escolhida.reforcada, 'Forjar reforçado', true));

  requisitosDaForja(body, {
    linhas: [
      { item: 3031, valor: money(escolhida.subida.ouro), nome: 'de ouro', ok: view.gold >= escolhida.subida.ouro },
      { valor: `tier ${escolhida.tier} → ${escolhida.subida.tier}`, nome: 'o degrau' },
      { valor: `${escolhida.subida.chance}%`, nome: 'de dar certo' },
    ],
    botao: botoes,
    aviso: el(
      'p',
      'forja-aviso',
      escolhida.tier > 0
        ? `A forja pode falhar. Falhando, ${escolhida.nome} cai para o tier ${escolhida.tier - 1} e o ouro é gasto igual. A pedra Draevor Tier UP nunca falha.`
        : 'A forja pode falhar. No tier 0 não há tier a perder: falhando, só o ouro é gasto. A pedra Draevor Tier UP nunca falha.',
    ),
  });
}

/*
 * ---- Passar tier: a doadora SOME, e a que recebe fica um tier abaixo ----
 *
 * É a regra do servidor do dono (`Player::forgeTransferItemTier`), e a tela diz
 * isso ANTES do botão — não depois, e não num balão. Quem clica aqui está
 * destruindo uma peça com tier; descobrir isso pelo aviso que aparece quando já
 * acabou seria descobrir tarde demais.
 */
function renderForjaTransferir(body, view, send) {
  const doadoras = view.pecas.filter((peca) => peca.tier > 0);
  const doadora = acharPeca(view, ctx.tabs.forjaDoadora);
  if (ctx.tabs.forjaDoadora && !doadora) ctx.tabs.forjaDoadora = null;
  const destino = doadora?.doa ?? null;

  const recebedora = acharPeca(view, ctx.tabs.forjaAlvo);
  if (ctx.tabs.forjaAlvo && !recebedora) ctx.tabs.forjaAlvo = null;

  const bancada = el('div', 'forja-bancada');
  bancada.append(
    quadroDaForja(doadora, {
      rotulo: 'Doa o tier',
      vazio: 'Escolha quem doa',
      aoClicar: () => {
        ctx.tabs.forjaDoadora = null;
        ctx.redraw();
      },
      destaque: doadora ? 'consome' : null,
    })
  );
  bancada.append(el('div', 'forja-setas', '▶▶▶'));
  bancada.append(
    quadroDaForja(recebedora ? { ...recebedora, tier: destino?.tier ?? recebedora.tier } : null, {
      rotulo: 'Recebe',
      vazio: 'Escolha quem recebe',
      aoClicar: () => {
        ctx.tabs.forjaAlvo = null;
        ctx.redraw();
      },
      destaque: 'resultado',
    })
  );
  body.append(bancada);

  body.append(
    el(
      'p',
      'shop-note dica',
      'A peça que DOA é consumida, e a que recebe fica com um tier abaixo do que a doadora tinha — uma tier 5 entrega tier 4. É a regra do servidor.'
    )
  );

  if (!doadoras.length) {
    return void body.append(el('p', 'empty', 'Nenhuma peça sua tem tier para passar adiante.'));
  }

  if (!doadora) {
    return void escolherPeca(body, '1. De qual peça sai o tier', doadoras, (peca) => {
      ctx.tabs.forjaDoadora = peca.lugar;
      ctx.tabs.forjaAlvo = null;
      ctx.redraw();
    });
  }

  /*
   * Só quem GANHA alguma coisa aparece. Uma peça que já é tier 4 recebendo um
   * tier 4 pagaria caro para não mudar nada, e uma tier 5 PIORARIA — o servidor
   * recusa as duas, e oferecê-las aqui seria oferecer um botão que volta com
   * erro.
   */
  const candidatas = view.pecas.filter(
    (peca) => !mesmoLugar(peca.lugar, doadora.lugar) && peca.tier < destino.tier
  );
  if (!recebedora) {
    return void escolherPeca(
      body,
      `2. Qual peça recebe o tier ${destino.tier}`,
      candidatas,
      (peca) => {
        ctx.tabs.forjaAlvo = peca.lugar;
        ctx.redraw();
      },
      `Nenhuma peça sua ficaria melhor com tier ${destino.tier}.`
    );
  }

  const podePagar = view.gold >= destino.ouro;
  const botao = el('button', podePagar ? 'primary forja-botao' : 'ghost forja-botao', 'Transferir');
  botao.disabled = !podePagar;
  botao.title = podePagar
    ? `${doadora.nome} será consumida e ${recebedora.nome} vira tier ${destino.tier}.`
    : `Faltam ${money(destino.ouro - view.gold)} de ouro.`;
  botao.onclick = () =>
    confirmarForja({
      id: recebedora.id,
      tier: destino.tier,
      titulo: 'Passar o tier',
      frases: [
        { texto: `${recebedora.nome} (${ondeAPecaEsta(recebedora)}) sai do tier ${recebedora.tier} para o tier ${destino.tier}.` },
        { texto: `${doadora.nome} (${ondeAPecaEsta(doadora)}), tier ${doadora.tier}, será DESTRUÍDA.`, perigo: true },
      ],
      custo: destino.ouro,
      gold: view.gold,
      acao: 'Transferir',
      aoConfirmar: () => {
        /*
         * As escolhas só se limpam DEPOIS de confirmado.
         *
         * Elas eram apagadas no clique do botão, e quem cancelasse a caixa
         * voltava para a bancada vazia — teria de escolher as duas peças outra
         * vez para chegar de novo à mesma pergunta.
         */
        ctx.tabs.forjaDoadora = null;
        ctx.tabs.forjaAlvo = null;
        send({ t: 'forjaTransferir', de: doadora.lugar, para: recebedora.lugar });
      },
    });

  requisitosDaForja(body, {
    linhas: [
      { item: 3031, valor: money(destino.ouro), nome: 'de ouro', ok: podePagar },
      { valor: `tier ${recebedora.tier} → ${destino.tier}`, nome: 'o que ela ganha' },
      { valor: doadora.nome, nome: 'será consumida', ok: false },
    ],
    botao,
  });
}

/*
 * ---- A ABA DE AFIXOS DA FORJA ----
 *
 * Quatro bancadas, e as quatro são o mesmo gesto: escolher a peça, escolher o
 * afixo, ler o preço, confirmar.
 *
 *   RERROLAR    um afixo é sorteado de novo, SEMPRE acima da porcentagem que
 *               estava — e no topo ele TROCA, saindo também em 100%. Cada
 *               rerroll do mesmo afixo custa 20% a mais que o anterior.
 *   TRANSFERIR  os afixos escolhidos mudam de peça; a doadora é consumida. Só
 *               entre peças do mesmo slot e da mesma raridade, e com PRÉVIA.
 *   ESSÊNCIAS   tirar da peça e pôr na peça, na MESMA bancada. Até três de uma
 *               vez, e o lote custa mais do que a soma das partes.
 *   UPGRADE     três essências douradas iguais viram uma vermelha, de 130%.
 *
 * ---- Por que "Retirar" e "Inserir" viraram UMA aba ----
 *
 * "se possível, unificar a aba de retirar e inserir, só que meio que manter a
 * função de cada um certinho."
 *
 * Elas eram duas telas quase idênticas — a mesma peça, a mesma lista de afixos,
 * o mesmo preço — e a diferença entre elas é a DIREÇÃO: uma tira o afixo da peça
 * e o guarda numa essência, a outra pega a essência e o devolve. Quem estava
 * arrumando uma peça ia e voltava entre as duas abas o tempo todo, e as duas
 * metades da mesma jogada nunca apareciam juntas.
 *
 * Agora é uma bancada com um botão de direção. A peça escolhida FICA ao trocar
 * de sentido — é o ponto: tira-se um afixo e põe-se outro sem sair do lugar.
 *
 * Nenhuma regra mora aqui. Quem decide preço, o que cabe onde e o que se perde é
 * `afixos-forja.mjs`; esta tela mostra o que o servidor disse e manda o pedido.
 * As prévias são as MESMAS funções que as operações usam para se validar — é por
 * isso que elas vêm do servidor em vez de serem calculadas aqui.
 */
const ABAS_DOS_AFIXOS = {
  reroll: 'Rerrolar',
  transferir: 'Transferir',
  essencias: 'Essências',
  upgrade: 'Upgrade',
};

/*
 * O id da essência de afixo, para o balão poder pedi-la ao catálogo. Ele mora
 * no servidor (`ID_DA_ESSENCIA`, em afixos-forja.mjs) e é repetido aqui pelo
 * mesmo motivo que a tabela de silhuetas: um número não vale uma dependência.
 */
const ID_DA_ESSENCIA = 900001;

/** Quantos afixos ou essências cabem numa operação de uma vez. */
const LOTE_MAXIMO = 3;

/** As sub-abas guardam escolhas diferentes; trocar de aba limpa todas. */
function limparBancadaDeAfixos() {
  ctx.tabs.afixoAlvo = null;
  ctx.tabs.afixoDoadora = null;
  ctx.tabs.afixoEssencias = [];
  ctx.tabs.afixoFusao = [null, null, null];
  ctx.tabs.afixoIndices = [];
  ctx.tabs.afixoPrevia = null;
  ctx.tabs.afixoPreviaRetirar = null;
  ctx.tabs.afixoPreviaInserir = null;
  ctx.tabs.afixoPreviaFundir = null;
}

function renderForjaAfixos(body) {
  const { state, send } = ctx;
  const view = state.forjaAfixos;
  if (!view) {
    send({ t: 'forjaAfixos' });
    return void body.append(el('p', 'empty', 'carregando...'));
  }

  ctx.tabs.afixoAba ??= 'reroll';
  ctx.tabs.afixoIndices ??= [];
  ctx.tabs.afixoEssencias ??= [];
  ctx.tabs.afixoFusao ??= [null, null, null];
  ctx.tabs.afixoModo ??= 'retirar';

  const aba = ctx.tabs.afixoAba;
  body.append(
    tabBar(ABAS_DOS_AFIXOS, aba, (next) => {
      ctx.tabs.afixoAba = next;
      limparBancadaDeAfixos();
      ctx.redraw();
    })
  );

  /*
   * ---- A BOLSA vai para cima, e com os ícones ----
   *
   * "na página de afixos, onde está ouro tem que ter o ícone do ouro, e onde
   * está Draevor Coins tem que ter o Draevor Coins; deixa a página melhor." E, no
   * mesmo fôlego: "está informando que eu tenho 0 Draevor Coins mesmo eu tendo
   * coins" — que era outro defeito, do servidor, e já foi.
   *
   * Ela subiu do rodapé para cá porque o preço é a primeira pergunta desta tela,
   * e não a última: quem abre a bancada quer saber se dá, e no rodapé a resposta
   * ficava embaixo de três listas.
   *
   * Os ícones são os MESMOS do resto do jogo — a moeda de ouro é o item 3031, e
   * a coin é o `coin-store` da loja. Desenhar um segundo símbolo para a mesma
   * moeda seria ensinar duas coisas onde há uma.
   */
  const bolsa = el('div', 'afixo-bolsa');
  for (const [classe, figura, valor, nome] of [
    ['ouro', () => itemCanvas(3031, 18), view.gold, 'no bolso'],
    ['coin', () => uiIcon('coin-store'), view.coins ?? 0, 'Draevor Coins'],
  ]) {
    const caixa = el('div', `afixo-bolsa-item ${classe}`);
    caixa.append(figura(), el('b', null, money(valor)), el('em', null, nome));
    bolsa.append(caixa);
  }
  body.append(bolsa);

  efeitoDoAfixo(body, view);

  if (aba === 'reroll') renderAfixoReroll(body, view, send);
  else if (aba === 'transferir') renderAfixoTransferir(body, view, send);
  else if (aba === 'essencias') renderAfixoEssencias(body, view, send);
  else renderAfixoUpgrade(body, view, send);
}

/* O cartaz do que acabou de sair da bancada. Irmão do `efeitoDaForja`. */
function efeitoDoAfixo(body, view) {
  const fez = view.fez;
  if (!fez) return;
  const cartaz = el('div', 'forja-efeito');
  const moldura = el('div', 'forja-moldura grande');
  if (fez.tipo === 'retirar' || fez.tipo === 'fundir') {
    moldura.append(
      arteDaEssencia(fez.slot ?? view.essencias.at(-1)?.slot ?? null, 48, fez.tipo === 'fundir', fez.raridade ?? null)
    );
  } else {
    moldura.append(itemCanvas(fez.id, 48));
  }
  cartaz.append(moldura);

  /*
   * O texto fala do BÔNUS, e não da régua.
   *
   * "ao tirar ou transferir está mostrando a porcentagem da estrela; na verdade
   * tinha que mostrar a porcentagem do bônus. Olha a foto: 'Resistência física
   * 24%' — isso é o tier da estrela. Era melhor mostrar o bônus que dá, 2,2% de
   * física."
   *
   * `texto` vem pronto do servidor com essa frase montada (ver `fichaDoAfixo`).
   * A régua continua existindo na régua desenhada de cada linha, que é onde ela
   * significa alguma coisa.
   */
  const texto = el('div', 'forja-efeito-texto');
  if (fez.tipo === 'reroll') {
    texto.append(el('b', null, fez.nome));
    texto.append(el('em', null, `${fez.antes.texto} → ${fez.depois.texto}`));
  } else if (fez.tipo === 'transferir') {
    texto.append(el('b', null, fez.nome));
    texto.append(el('em', null, `recebeu ${fez.levados.map((a) => a.texto ?? a.nome).join(', ')} · ${fez.doadora} foi consumida`));
  } else if (fez.tipo === 'retirar') {
    texto.append(el('b', null, fez.tirados.map((a) => a.texto).join(', ')));
    texto.append(
      el(
        'em',
        null,
        fez.ficaram.length
          ? `saiu de ${fez.nome} · ela continua com ${fez.ficaram.map((a) => a.nome).join(' e ')}`
          : `saiu de ${fez.nome} · ela ficou sem estrela`
      )
    );
  } else if (fez.tipo === 'fundir') {
    texto.append(el('b', 'afixo-vermelha', fez.ficha.texto));
    texto.append(el('em', null, `essência vermelha${fez.slotNome ? ` de ${fez.slotNome}` : ''} · 130% da régua`));
  } else {
    texto.append(el('b', null, fez.nome));
    texto.append(el('em', null, `recebeu ${fez.postos.map((a) => a.texto).join(', ')}`));
  }
  cartaz.append(texto);
  body.append(cartaz);
}

/*
 * ---- A essência desenhada: a silhueta do slot de onde ela veio ----
 *
 * "vem uma peça na backpack que seria igual do inventário quando tá sem nada
 * equipado." É o mesmo PNG que a casa vazia da ficha usa, e é de propósito que
 * seja o mesmo: a pessoa reconhece "isto é de arma" sem ler nada.
 *
 * A vermelha da fusão ganha uma classe a mais, e só isso: o desenho é o mesmo
 * (ela continua sendo de bota), o que muda é a cor da moldura.
 */
function arteDaEssencia(slot, size = 40, mitica = false, raridade = null) {
  const nome = ARTE_DO_SLOT[slot] ?? 'back';
  /*
   * ---- A COR é a da peça de origem ----
   *
   * "a essência do afixo tem que ficar com a cor da raridade do item que foi
   * retirado." A qualidade é metade da regra de onde ela pode entrar, e era a
   * metade invisível: todas as silhuetas saíam cinza. A classe é a mesma do
   * resto do jogo, então a paleta continua sendo uma só.
   */
  /*
   * A VERMELHA sai pintada de mítico venha de onde vier — "o fundo do item tem
   * que ser vermelho igual de mítico" —, e a classe `mitica` é o efeito a mais
   * que a separa de uma essência mítica de verdade. Ver `.afixo-essencia-arte`,
   * no CSS.
   */
  const cor = mitica ? 'mítico' : raridade;
  const caixa = el(
    'div',
    `afixo-essencia-arte${mitica ? ' mitica' : ''}${cor ? ' ' + CLASSE_DA_ARTE(cor) : ''}`
  );
  const img = document.createElement('img');
  img.width = size;
  img.height = size;
  img.src = `/client/assets/slots/${nome}.png`;
  img.alt = '';
  img.onerror = () => img.remove();
  caixa.append(img);
  return caixa;
}

/*
 * ---- Uma linha de afixo ----
 *
 * O que ela diz, em ordem de importância:
 *
 *   O BÔNUS       "+2,2% Resistência física". É o que o afixo FAZ, e é o número
 *                 que o dono apontou como o que devia estar ali.
 *   A RÉGUA       a barra e os "24%": onde aquele valor caiu na faixa possível
 *                 daquele afixo. Ela não some porque é o que o rerroll promete
 *                 superar — mas deixou de ser a manchete.
 *   OS RERROLLS   quantas vezes este posto já foi rerrolado, e só quando já
 *                 houve algum: é o que explica o preço subir.
 */
function linhaDoAfixo(afixo, { escolhido = false, aoClicar = null, numero = null } = {}) {
  const q = afixo.pct > 100 ? 4 : afixo.pct >= 67 ? 3 : afixo.pct >= 34 ? 2 : 1;
  const no = el(
    aoClicar ? 'button' : 'div',
    `afixo-linha q${q}${escolhido ? ' on' : ''}${afixo.torto ? ' torto' : ''}`
  );
  if (numero != null) no.append(el('i', 'afixo-ordem', String(numero)));
  no.append(el('b', null, afixo.texto ?? afixo.nome));

  const regua = el('div', 'afixo-regua');
  const cheio = el('i', null);
  cheio.style.width = `${Math.max(2, Math.min(100, afixo.pct))}%`;
  regua.append(cheio);
  no.append(regua);
  no.append(el('em', 'afixo-pct', `${afixo.pct}%`));
  if (afixo.rerrolls > 0) no.append(el('em', 'afixo-rr', `${afixo.rerrolls}× rerrolado`));
  if (afixo.torto) no.append(el('em', 'afixo-torto', 'não é desta peça'));
  if (aoClicar) no.onclick = aoClicar;
  return no;
}

/** O quadro de uma peça na bancada de afixos. Irmão do `quadroDaForja`. */
function quadroDoAfixo(peca, { rotulo, vazio, aoClicar }) {
  const quadro = el('button', `forja-quadro${peca ? ' cheio' : ''}`);
  quadro.append(el('em', 'forja-rotulo', rotulo));
  const moldura = el('div', 'forja-moldura');
  if (peca) {
    moldura.append(itemCanvas(peca.id, 40));
    if (peca.afixos?.length) moldura.append(seloDeEstrelas('selo-afixo', estrelasDosAfixos(peca.peca?.af)));
  } else {
    moldura.append(el('span', 'forja-vazio', '+'));
  }
  quadro.append(moldura);
  quadro.append(el('b', CLASSE_DA_RARIDADE(peca?.rarity), peca ? peca.nome : vazio));
  quadro.append(el('span', 'forja-onde', peca ? ondeAPecaEsta(peca) : 'clique para escolher'));
  quadro.onclick = aoClicar;
  /*
   * ---- O balão, o MESMO do inventário ----
   *
   * "ao colocar o mouse em cima dos itens na aba dos afixos tem que mostrar o
   * modal bonitinho igual do inventário, inclusive o preview."
   *
   * `tipFor` recebe a PEÇA crua (que o servidor manda em `peca`), e não a ficha
   * da bancada: é dela que o balão lê o tier e as estrelas. Sem isso ele
   * desenharia o item do catálogo — a espada limpa, sem nada do que esta cópia
   * tem, que é justamente o assunto desta tela.
   */
  if (peca) tipFor(quadro, peca.id, null, null, peca.peca ?? null);
  return quadro;
}

/** A tira de escolha, com as estrelas e a raridade no lugar do tier. */
function escolherPecaComAfixo(body, titulo, pecas, aoEscolher, vazio) {
  body.append(el('h3', null, titulo));
  if (!pecas.length) return void body.append(el('p', 'empty', vazio));
  const tira = el('div', 'forja-escolha');
  for (const peca of pecas) {
    const botao = el('button', `forja-opcao${peca.afixos.length ? ' tem-tier' : ''}`);
    const moldura = el('div', 'forja-moldura mini');
    moldura.append(itemCanvas(peca.id, 30));
    if (peca.afixos.length) moldura.append(seloDeEstrelas('selo-afixo', estrelasDosAfixos(peca.peca?.af)));
    botao.append(moldura);
    const texto = el('span', 'forja-opcao-texto');
    texto.append(el('b', CLASSE_DA_RARIDADE(peca.rarity), peca.nome));
    texto.append(el('em', null, `${ondeAPecaEsta(peca)} · ${peca.rarity}`));
    botao.append(texto);
    botao.onclick = () => aoEscolher(peca);
    tipFor(botao, peca.id, null, null, peca.peca ?? null);
    tira.append(botao);
  }
  body.append(tira);
}

/*
 * ---- A ESTRELA da essência ----
 *
 * "faltou mostrar a estrela das essências ali."
 *
 * As peças ganharam a estrela no canto da moldura e as essências não, e não há
 * razão para a diferença: a essência CARREGA um afixo, e a estrela é o que diz
 * quão bom ele é — azul, roxa, dourada, vermelha. É a pergunta que se faz ao
 * escolher qual usar, e sem ela era preciso ler a porcentagem linha por linha.
 *
 * É o mesmo selo do inventário (`selo-afixo`), pela mesma razão de sempre: uma
 * essência é a mesma essência nas duas telas.
 */
function estrelaDaEssencia(e) {
  const estrelas = estrelasDosAfixos(e?.peca?.af);
  return estrelas.length ? seloDeEstrelas('selo-afixo', estrelas) : null;
}

/** A mesma tira, para essências: silhueta do slot e o nome montado. */
function escolherEssencia(body, titulo, essencias, aoEscolher, vazio, { marcadas = [] } = {}) {
  body.append(el('h3', null, titulo));
  if (!essencias.length) return void body.append(el('p', 'empty', vazio));
  const tira = el('div', 'forja-escolha');
  for (const e of essencias) {
    const escolhida = marcadas.some((lugar) => mesmoLugar(lugar, e.lugar));
    const botao = el('button', `forja-opcao tem-tier${escolhida ? ' on' : ''}${e.mitica ? ' vermelha' : ''}`);
    const mini = el('div', 'forja-moldura mini');
    mini.append(arteDaEssencia(e.slot, 30, e.mitica, e.raridade));
    const estrela = estrelaDaEssencia(e);
    if (estrela) mini.append(estrela);
    botao.append(mini);
    const texto = el('span', 'forja-opcao-texto');
    texto.append(el('b', CLASSE_DA_RARIDADE(e.raridade), e.afixo.texto));
    texto.append(el('em', null, `${nomeDaEssenciaNaTela(e)} · ${e.ondeNome}`));
    botao.append(texto);
    botao.onclick = () => aoEscolher(e);
    tipFor(botao, ID_DA_ESSENCIA, null, null, e.peca ?? null);
    tira.append(botao);
  }
  body.append(tira);
}

/*
 * ---- Duas classes de raridade, e elas fazem coisas diferentes ----
 *
 * `CLASSE_DA_RARIDADE` devolve `rar-mitico`, que pinta o TEXTO. Esta devolve
 * `tier-mitico`, que define a variável `--tier` — a cor que as bordas e os
 * brilhos leem. São as mesmas seis cores; o que muda é onde elas pegam.
 *
 * A silhueta da essência precisa da segunda: ela não tem texto para pintar, e o
 * que se quer colorir é a moldura dela.
 */
const CLASSE_DA_ARTE = (rarity) =>
  `tier-${String(rarity ?? 'comum')
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')}`;

const acharPecaDeAfixo = (view, lugar) => view.pecas.find((p) => mesmoLugar(p.lugar, lugar)) ?? null;
const acharEssencia = (view, lugar) => view.essencias.find((e) => mesmoLugar(e.lugar, lugar)) ?? null;

/*
 * ---- O nome da essência, com uma RESERVA montada aqui ----
 *
 * O servidor manda o nome pronto (`nomeDaEssencia`, em afixos-forja.mjs), e é
 * ele que vale: a mesma frase precisa sair igual na bancada, no balão, na
 * mochila e no anúncio do mercado.
 *
 * A reserva existe porque esta tela sobrevive a um retrato velho. O retrato fica
 * guardado em `state.forjaAfixos` e não é pedido de novo a cada desenho — uma
 * aba aberta desde antes de um deploy mostra o que o servidor de ontem mandou, e
 * um campo que ainda não existia lá vira a palavra "undefined" na linha. Foi
 * exatamente o que apareceu na tela do dono.
 *
 * Ela monta a mesma frase com o que a ficha SEMPRE teve (slot e raridade), e é
 * por isso que é uma reserva e não uma segunda fonte: quando o nome chega, é ele
 * que sai.
 */
function nomeDaEssenciaNaTela(e) {
  if (e?.nome) return e.nome;
  const partes = [e?.mitica ? 'essência vermelha' : 'essência de afixo'];
  if (e?.slotNome) partes.push(e.slotNome);
  else if (e?.slot) partes.push(NOME_DO_SLOT_NA_OFERTA[e.slot] ?? e.slot);
  if (e?.raridade && e.raridade !== 'comum') partes.push(e.raridade);
  return partes.join(' · ');
}

/*
 * ---- A escolha da MOEDA, com os ícones ----
 *
 * Todas as operações aceitam as duas moedas, e a escolha é do jogador a cada vez
 * — não uma preferência guardada. Quem tem ouro sobrando e coin contada decide
 * diferente do outro lado do mês.
 *
 * O botão sem saldo não some: ele fica APAGADO, com o quanto falta. Sumir
 * esconderia a existência do caminho; apagado, a pessoa vê que dava para pagar
 * em coin e quanto lhe falta para isso.
 */
function moedaDaForja(custo, view) {
  ctx.tabs.afixoMoeda ??= 'gold';
  const tira = el('div', 'afixo-moedas');
  for (const [id, rotulo, valor, saldo, figura] of [
    ['gold', 'de ouro', custo.ouro, view.gold, () => itemCanvas(3031, 16)],
    ['coin', 'Draevor Coins', custo.coins, view.coins ?? 0, () => uiIcon('coin-store')],
  ]) {
    const da = saldo >= valor;
    const botao = el('button', `afixo-moeda${ctx.tabs.afixoMoeda === id ? ' on' : ''}${da ? '' : ' falta'}`);
    botao.append(figura());
    const texto = el('span', 'afixo-moeda-texto');
    texto.append(el('b', null, money(valor)));
    texto.append(el('em', null, da ? rotulo : `faltam ${money(valor - saldo)}`));
    botao.append(texto);
    botao.onclick = () => {
      ctx.tabs.afixoMoeda = id;
      ctx.redraw();
    };
    tira.append(botao);
  }
  return tira;
}

const moedaEscolhida = () => (ctx.tabs.afixoMoeda === 'coin' ? 'coin' : 'gold');
const valorNaMoeda = (custo) => (moedaEscolhida() === 'coin' ? custo.coins : custo.ouro);
const saldoNaMoeda = (view) => (moedaEscolhida() === 'coin' ? view.coins ?? 0 : view.gold);
const nomeDaMoeda = () => (moedaEscolhida() === 'coin' ? 'Draevor Coins' : 'de ouro');
const figuraDaMoeda = () => (moedaEscolhida() === 'coin' ? uiIcon('coin-store') : itemCanvas(3031, 20));

/** A linha de preço do rodapé, com o ícone da moeda escolhida. */
function precoDaForja(body, { custo, saldo, botao, aviso = null, extras = [] }) {
  const faixa = el('div', 'forja-requisitos');
  const conta = el('div', 'forja-custo');
  for (const linha of extras) {
    const chip = el('div', `forja-chip${linha.ok === false ? ' falta' : ''}`);
    chip.append(el('b', null, linha.valor));
    chip.append(el('em', null, linha.nome));
    conta.append(chip);
  }
  const chip = el('div', `forja-chip preco${saldo >= custo ? '' : ' falta'}`);
  chip.append(figuraDaMoeda());
  chip.append(el('b', null, money(custo)));
  chip.append(el('em', null, nomeDaMoeda()));
  conta.append(chip);
  faixa.append(conta);
  faixa.append(botao);
  body.append(faixa);
  if (aviso) body.append(aviso);
}

/* ------------------------------------------------------------- RERROLAR */

function renderAfixoReroll(body, view, send) {
  const escolhida = acharPecaDeAfixo(view, ctx.tabs.afixoAlvo);
  if (ctx.tabs.afixoAlvo && !escolhida) ctx.tabs.afixoAlvo = null;

  const bancada = el('div', 'forja-bancada');
  bancada.append(
    quadroDoAfixo(escolhida, {
      rotulo: 'Peça',
      vazio: 'Nenhuma peça escolhida',
      aoClicar: () => {
        ctx.tabs.afixoAlvo = null;
        ctx.tabs.afixoIndices = [];
        ctx.redraw();
      },
    })
  );
  body.append(bancada);

  if (!escolhida) {
    return void escolherPecaComAfixo(
      body,
      'Escolha a peça',
      view.pecas.filter((p) => p.afixos.length),
      (peca) => {
        ctx.tabs.afixoAlvo = peca.lugar;
        ctx.tabs.afixoIndices = [];
        ctx.redraw();
      },
      'Nenhuma peça com estrela no corpo, na mochila, na bolsa ou no depósito.'
    );
  }

  body.append(el('h3', null, 'Qual afixo rerrolar'));
  const lista = el('div', 'afixo-lista');
  const escolhido = ctx.tabs.afixoIndices[0] ?? null;
  escolhida.afixos.forEach((afixo, i) => {
    lista.append(
      linhaDoAfixo(afixo, {
        escolhido: escolhido === i,
        aoClicar: () => {
          ctx.tabs.afixoIndices = [i];
          ctx.redraw();
        },
      })
    );
  });
  body.append(lista);

  const alvo = escolhido != null ? escolhida.afixos[escolhido] : null;
  /*
   * ---- O preço é DAQUELE afixo, e sobe a cada rerroll ----
   *
   * "cada reroll em um slot de afixo, o ouro usado ou o coin usado vai
   * aumentando 20%."
   *
   * O número vem no `proximoReroll` da ficha, já composto pelo servidor — a
   * conta é dele, e refazê-la aqui seria uma segunda fórmula para o mesmo preço.
   * Sem afixo escolhido, mostra o de tabela, que é o que a operação custa
   * limpa.
   */
  const custo = alvo?.proximoReroll ?? view.custos.reroll;

  body.append(moedaDaForja(custo, view));
  const valor = valorNaMoeda(custo);
  const botao = el('button', 'primary', 'Rerrolar');
  botao.disabled = !alvo || saldoNaMoeda(view) < valor;
  botao.onclick = () =>
    confirmarForjaDeAfixo({
      id: escolhida.id,
      peca: escolhida.peca,
      titulo: 'Rerrolar afixo',
      frases: [
        { texto: `${alvo.texto} vai ser sorteado de novo.` },
        {
          texto:
            alvo.pct >= 100
              ? 'Ele já está no topo da régua: vem outro afixo, também em 100%.'
              : `Pode vir o mesmo afixo ou outro — sempre acima dos ${alvo.pct}% que ele está agora.`,
        },
        { texto: 'Os outros afixos da peça não são tocados.' },
      ],
      custo: valor,
      saldo: saldoNaMoeda(view),
      unidade: nomeDaMoeda(),
      acao: 'Rerrolar',
      aoConfirmar: () =>
        send({ t: 'forjaAfixoReroll', lugar: escolhida.lugar, indice: escolhido, moeda: moedaEscolhida() }),
    });

  precoDaForja(body, {
    custo: valor,
    saldo: saldoNaMoeda(view),
    botao,
    extras: alvo?.rerrolls ? [{ nome: 'já rerrolado', valor: `${alvo.rerrolls}×`, ok: true }] : [],
    aviso: el(
      'p',
      'forja-dica-rodape',
      alvo?.pct >= 100
        ? `${alvo.nome} está no topo: o rerroll TROCA de afixo, e o novo também sai em 100%.`
        : 'O novo afixo sai do que ESTA peça pode ter, com os mesmos pesos do loot. Cada rerroll do mesmo afixo custa 20% a mais que o anterior.'
    ),
  });
}

/* ----------------------------------------------------------- TRANSFERIR */

function renderAfixoTransferir(body, view, send) {
  const doadora = acharPecaDeAfixo(view, ctx.tabs.afixoDoadora);
  const recebedora = acharPecaDeAfixo(view, ctx.tabs.afixoAlvo);
  if (ctx.tabs.afixoDoadora && !doadora) ctx.tabs.afixoDoadora = null;
  if (ctx.tabs.afixoAlvo && !recebedora) ctx.tabs.afixoAlvo = null;

  const bancada = el('div', 'forja-bancada dupla');
  bancada.append(
    quadroDoAfixo(doadora, {
      rotulo: 'Doadora (some)',
      vazio: 'De qual peça',
      aoClicar: () => {
        ctx.tabs.afixoDoadora = null;
        ctx.tabs.afixoIndices = [];
        ctx.redraw();
      },
    })
  );
  bancada.append(el('span', 'forja-seta', '→'));
  bancada.append(
    quadroDoAfixo(recebedora, {
      rotulo: 'Recebe',
      vazio: 'Para qual peça',
      aoClicar: () => {
        ctx.tabs.afixoAlvo = null;
        ctx.redraw();
      },
    })
  );
  body.append(bancada);

  if (!doadora) {
    return void escolherPecaComAfixo(
      body,
      'De qual peça saem os afixos',
      view.pecas.filter((p) => p.afixos.length),
      (peca) => {
        ctx.tabs.afixoDoadora = peca.lugar;
        ctx.tabs.afixoIndices = [];
        ctx.redraw();
      },
      'Nenhuma peça com estrela.'
    );
  }

  if (!recebedora) {
    /*
     * A lista já vem PENEIRADA pelas duas travas do servidor — mesmo slot e
     * mesma raridade. Oferecer o que vai ser recusado é fazer a pessoa
     * descobrir a regra por tentativa.
     */
    return void escolherPecaComAfixo(
      body,
      `Para qual peça (${doadora.rarity}, mesmo slot)`,
      view.pecas.filter(
        (p) => !mesmoLugar(p.lugar, doadora.lugar) && p.slot === doadora.slot && p.rarity === doadora.rarity && p.vagas > 0
      ),
      (peca) => {
        ctx.tabs.afixoAlvo = peca.lugar;
        ctx.redraw();
      },
      `Nenhuma outra peça ${doadora.rarity} do mesmo slot com espaço livre.`
    );
  }

  body.append(el('h3', null, `Quais afixos levar (cabem ${recebedora.vagas})`));
  const lista = el('div', 'afixo-lista');
  const marcados = new Set(ctx.tabs.afixoIndices);
  doadora.afixos.forEach((afixo, i) => {
    lista.append(
      linhaDoAfixo(afixo, {
        escolhido: marcados.has(i),
        aoClicar: () => {
          if (marcados.has(i)) marcados.delete(i);
          else marcados.add(i);
          ctx.tabs.afixoIndices = [...marcados];
          pedirPreviaDoAfixo(doadora, recebedora, send);
          ctx.redraw();
        },
      })
    );
  });
  body.append(lista);

  /*
   * ---- A PRÉVIA, que foi um pedido explícito ----
   *
   * "tem que mostrar o preview de como ficaria a peça." Ela vem do SERVIDOR e
   * não é montada aqui: é a mesma função que a transferência chama para se
   * validar, e duas listas de regras seria uma delas passando a mentir.
   */
  const previa = ctx.tabs.afixoPrevia;
  const valeEsta =
    previa &&
    mesmoLugar(previa.de, doadora.lugar) &&
    mesmoLugar(previa.para, recebedora.lugar) &&
    previa.indices.join(',') === [...marcados].sort((a, b) => a - b).join(',');

  if (marcados.size && valeEsta) {
    if (previa.ok) previaDaPeca(body, `Como ${recebedora.nome} fica`, previa.depois);
    else body.append(el('p', 'forja-aviso', previa.reason));
  }

  const porAfixo = view.custos.transferencia[recebedora.rarity] ?? view.custos.transferencia.comum;
  const custoTotal = { ouro: porAfixo.ouro * marcados.size, coins: porAfixo.coins * marcados.size };
  body.append(moedaDaForja(custoTotal, view));
  const custo = valorNaMoeda(custoTotal);

  const botao = el('button', 'primary', 'Transferir');
  botao.disabled = !marcados.size || !valeEsta || !previa?.ok || saldoNaMoeda(view) < custo;
  botao.onclick = () =>
    confirmarForjaDeAfixo({
      id: recebedora.id,
      peca: recebedora.peca,
      titulo: 'Transferir afixos',
      frases: [
        { texto: `${recebedora.nome} vai receber ${previa.levados.map((a) => a.ficha?.texto ?? a.texto ?? a.nome).join(', ')}.` },
        { texto: `${doadora.nome} SOME, com tudo o que ela tem.`, perigo: true },
      ],
      custo,
      saldo: saldoNaMoeda(view),
      unidade: nomeDaMoeda(),
      acao: 'Transferir',
      aoConfirmar: () =>
        send({
          t: 'forjaAfixoTransferir',
          de: doadora.lugar,
          para: recebedora.lugar,
          indices: [...marcados],
          moeda: moedaEscolhida(),
        }),
    });

  precoDaForja(body, {
    custo,
    saldo: saldoNaMoeda(view),
    botao,
    extras: [{ nome: `por afixo (${recebedora.rarity})`, valor: money(valorNaMoeda(porAfixo)), ok: true }],
  });
}

/** Pede ao servidor a prévia da escolha de agora. Só lê — não cobra nada. */
function pedirPreviaDoAfixo(doadora, recebedora, send) {
  const indices = [...(ctx.tabs.afixoIndices ?? [])].sort((a, b) => a - b);
  if (!indices.length) {
    ctx.tabs.afixoPrevia = null;
    return;
  }
  send({ t: 'forjaAfixoPrevia', de: doadora.lugar, para: recebedora.lugar, indices });
}

/** O bloco "como a peça fica" — o mesmo desenho nas três bancadas que o têm. */
function previaDaPeca(body, titulo, afixos) {
  body.append(el('h3', 'afixo-previa-titulo', titulo));
  const depois = el('div', 'afixo-lista previa');
  if (!afixos.length) depois.append(el('p', 'empty', 'sem estrela nenhuma'));
  for (const afixo of afixos) depois.append(linhaDoAfixo(afixo));
  body.append(depois);
}

/* ------------------------------------------------------------ ESSÊNCIAS */

/*
 * ---- Uma bancada, dois sentidos ----
 *
 * O botão de cima diz para onde o afixo vai: para FORA da peça (retirar) ou para
 * DENTRO dela (inserir). A peça escolhida sobrevive à troca de sentido de
 * propósito — é o gesto que as duas abas separadas tornavam trabalhoso: tirar um
 * afixo ruim e pôr um bom na mesma peça, sem sair do lugar.
 */
const SENTIDOS_DA_ESSENCIA = {
  retirar: 'Tirar da peça →',
  inserir: '← Pôr na peça',
};

function renderAfixoEssencias(body, view, send) {
  const modo = ctx.tabs.afixoModo === 'inserir' ? 'inserir' : 'retirar';

  const sentido = el('div', 'afixo-sentido');
  for (const [id, rotulo] of Object.entries(SENTIDOS_DA_ESSENCIA)) {
    const botao = el('button', `afixo-sentido-botao${modo === id ? ' on' : ''}`, rotulo);
    botao.onclick = () => {
      ctx.tabs.afixoModo = id;
      /*
       * O que se limpa é a ESCOLHA DE AFIXO, e não a peça: a lista de índices
       * de um sentido não quer dizer nada no outro. A peça fica, que é o ponto
       * de as duas bancadas terem virado uma.
       */
      ctx.tabs.afixoIndices = [];
      ctx.tabs.afixoEssencias = [];
      ctx.tabs.afixoPreviaRetirar = null;
      ctx.tabs.afixoPreviaInserir = null;
      ctx.redraw();
    };
    sentido.append(botao);
  }
  body.append(sentido);

  if (modo === 'retirar') renderTirarAfixo(body, view, send);
  else renderPorAfixo(body, view, send);
}

/* ---- o sentido de FORA: a peça perde o afixo e ele vira essência ---- */

function renderTirarAfixo(body, view, send) {
  const escolhida = acharPecaDeAfixo(view, ctx.tabs.afixoAlvo);
  if (ctx.tabs.afixoAlvo && !escolhida) ctx.tabs.afixoAlvo = null;

  const bancada = el('div', 'forja-bancada');
  bancada.append(
    quadroDoAfixo(escolhida, {
      rotulo: 'Peça',
      vazio: 'Nenhuma peça escolhida',
      aoClicar: () => {
        ctx.tabs.afixoAlvo = null;
        ctx.tabs.afixoIndices = [];
        ctx.tabs.afixoPreviaRetirar = null;
        ctx.redraw();
      },
    })
  );
  body.append(bancada);

  if (!escolhida) {
    return void escolherPecaComAfixo(
      body,
      'De qual peça tirar',
      view.pecas.filter((p) => p.afixos.length),
      (peca) => {
        ctx.tabs.afixoAlvo = peca.lugar;
        ctx.tabs.afixoIndices = [];
        ctx.tabs.afixoPreviaRetirar = null;
        ctx.redraw();
      },
      'Nenhuma peça com estrela.'
    );
  }

  /*
   * ---- Até TRÊS de uma vez ----
   *
   * "o retirar ou inserir: eu tenho que ter a opção de retirar 3 afixos se eu
   * quiser, mas aí custaria mais."
   *
   * Cada afixo escolhido vira uma essência PRÓPRIA — três essências e não uma
   * com três linhas —, porque é assim que elas voltam a ser úteis: cada uma
   * entra numa peça diferente.
   */
  body.append(el('h3', null, `Quais afixos tirar (até ${LOTE_MAXIMO})`));
  const marcados = new Set(ctx.tabs.afixoIndices);
  const lista = el('div', 'afixo-lista');
  escolhida.afixos.forEach((afixo, i) => {
    lista.append(
      linhaDoAfixo(afixo, {
        escolhido: marcados.has(i),
        aoClicar: () => {
          if (marcados.has(i)) marcados.delete(i);
          else if (marcados.size < LOTE_MAXIMO) marcados.add(i);
          ctx.tabs.afixoIndices = [...marcados];
          pedirPreviaDaRetirada(escolhida, send);
          ctx.redraw();
        },
      })
    );
  });
  body.append(lista);

  const previa = ctx.tabs.afixoPreviaRetirar;
  const valeEsta =
    previa &&
    mesmoLugar(previa.lugar, escolhida.lugar) &&
    (previa.indices ?? []).join(',') === [...marcados].sort((a, b) => a - b).join(',');

  if (marcados.size && valeEsta) {
    if (previa.ok) previaDaPeca(body, `Como ${escolhida.nome} fica`, previa.depois);
    else body.append(el('p', 'forja-aviso', previa.reason));
  }

  /*
   * O preço vem da PRÉVIA, que já somou o acréscimo do lote. A tabela do `view`
   * é a reserva para quando ainda não há nada escolhido — ali ela mostra o preço
   * de um afixo, que é o que a operação custa limpa.
   */
  const porAfixo = view.custos.retirar[escolhida.rarity] ?? view.custos.retirar.comum;
  const custoTotal = valeEsta && previa.ok ? previa.custo : { ouro: 0, coins: 0 };
  body.append(moedaDaForja(custoTotal, view));
  const custo = valorNaMoeda(custoTotal);

  const botao = el('button', 'primary', marcados.size > 1 ? `Retirar ${marcados.size}` : 'Retirar');
  botao.disabled = !marcados.size || !valeEsta || !previa?.ok || saldoNaMoeda(view) < custo;
  botao.onclick = () =>
    confirmarForjaDeAfixo({
      id: escolhida.id,
      peca: escolhida.peca,
      titulo: marcados.size > 1 ? `Retirar ${marcados.size} afixos` : 'Retirar afixo',
      frases: [
        {
          texto: `${previa.tirados.map((t) => t.ficha.texto).join(', ')} ${
            marcados.size > 1 ? 'viram essências' : 'vira uma essência'
          } na mochila.`,
        },
        {
          texto: previa.depois.length
            ? `${escolhida.nome} continua com ${previa.depois.map((a) => a.nome).join(' e ')}.`
            : `${escolhida.nome} continua com você, sem estrela nenhuma.`,
        },
      ],
      custo,
      saldo: saldoNaMoeda(view),
      unidade: nomeDaMoeda(),
      acao: 'Retirar',
      aoConfirmar: () =>
        send({
          t: 'forjaAfixoRetirar',
          lugar: escolhida.lugar,
          indices: [...marcados],
          moeda: moedaEscolhida(),
        }),
    });

  precoDaForja(body, {
    custo,
    saldo: saldoNaMoeda(view),
    botao,
    extras: [
      { nome: `por afixo (${escolhida.rarity})`, valor: money(valorNaMoeda(porAfixo)), ok: true },
      ...(marcados.size > 1
        ? [{ nome: `lote de ${marcados.size}`, valor: `+${Math.round((view.custos.loteDoRetirar[marcados.size] - 1) * 100)}%`, ok: true }]
        : []),
    ],
    aviso: el(
      'p',
      'forja-dica-rodape',
      'Os outros afixos da peça NÃO se perdem — só sai o que você escolheu. A essência guarda o slot e a qualidade desta peça, e só entra em outra igual.'
    ),
  });
}

function pedirPreviaDaRetirada(peca, send) {
  const indices = [...(ctx.tabs.afixoIndices ?? [])].sort((a, b) => a - b);
  if (!indices.length) {
    ctx.tabs.afixoPreviaRetirar = null;
    return;
  }
  send({ t: 'forjaAfixoPreviaRetirar', lugar: peca.lugar, indices });
}

/* ---- o sentido de DENTRO: a essência entra na peça e some ---- */

function renderPorAfixo(body, view, send) {
  const marcadas = (ctx.tabs.afixoEssencias ?? []).filter((lugar) => acharEssencia(view, lugar));
  ctx.tabs.afixoEssencias = marcadas;
  const alvo = acharPecaDeAfixo(view, ctx.tabs.afixoAlvo);
  if (ctx.tabs.afixoAlvo && !alvo) ctx.tabs.afixoAlvo = null;

  if (!view.essencias.length) {
    return void body.append(
      el('p', 'empty', 'Nenhuma essência na mochila. Elas saem do outro sentido desta bancada.')
    );
  }

  const primeira = marcadas.length ? acharEssencia(view, marcadas[0]) : null;

  /*
   * ---- As essências escolhidas aparecem UMA A UMA ----
   *
   * "quando eu for aplicar 3 essências tem que mostrar lado a lado as essências
   * ali, e não '3 essências' e mostrando apenas 1."
   *
   * Ele está certo, e o defeito era de honestidade: o quadro dizia "3 essências"
   * e desenhava a PRIMEIRA — o rótulo prometia três coisas e a figura mostrava
   * uma, então não havia como conferir o que ia entrar sem clicar em cada uma na
   * lista de baixo e contar de cabeça.
   *
   * Agora são `LOTE_MAXIMO` casas fixas, como as três da fusão. Fixas e não uma
   * por escolhida: as vazias são o que diz que ainda cabe mais, e uma tira que
   * cresce não conta isso. Clicar numa casa cheia tira AQUELA essência — antes o
   * clique limpava as três de uma vez, que é o gesto errado quando se errou uma.
   */
  const bancada = el('div', 'forja-bancada dupla');
  const casas = el('div', 'afixo-casas');
  for (let i = 0; i < LOTE_MAXIMO; i++) {
    const escolhida = marcadas[i] ? acharEssencia(view, marcadas[i]) : null;
    const casa = el(
      'button',
      `forja-quadro casa${escolhida ? ' cheio' : ''}${escolhida?.mitica ? ' vermelha' : ''}`
    );
    casa.append(el('em', 'forja-rotulo', `${i + 1}ª`));
    const moldura = el('div', 'forja-moldura');
    if (escolhida) {
      moldura.append(arteDaEssencia(escolhida.slot, 34, escolhida.mitica, escolhida.raridade));
      const estrela = estrelaDaEssencia(escolhida);
      if (estrela) moldura.append(estrela);
    } else {
      moldura.append(el('span', 'forja-vazio', '+'));
    }
    casa.append(moldura);
    casa.append(
      el('b', CLASSE_DA_RARIDADE(escolhida?.raridade), escolhida ? escolhida.afixo.texto : 'vazia')
    );
    casa.append(
      el('span', 'forja-onde', escolhida ? nomeDaEssenciaNaTela(escolhida) : 'escolha abaixo')
    );
    casa.onclick = () => {
      if (!escolhida) return;
      ctx.tabs.afixoEssencias = marcadas.filter((lugar) => !mesmoLugar(lugar, escolhida.lugar));
      ctx.tabs.afixoPreviaInserir = null;
      if (alvo && ctx.tabs.afixoEssencias.length) pedirPreviaDaInsercao(alvo, send);
      ctx.redraw();
    };
    if (escolhida) tipFor(casa, ID_DA_ESSENCIA, null, null, escolhida.peca ?? null);
    casas.append(casa);
  }
  bancada.append(casas);
  bancada.append(el('span', 'forja-seta', '→'));
  bancada.append(
    quadroDoAfixo(alvo, {
      rotulo: 'Peça',
      vazio: 'Em qual peça',
      aoClicar: () => {
        ctx.tabs.afixoAlvo = null;
        ctx.tabs.afixoPreviaInserir = null;
        ctx.redraw();
      },
    })
  );
  body.append(bancada);

  const trocar = (e) => {
    const fora = marcadas.filter((lugar) => !mesmoLugar(lugar, e.lugar));
    if (fora.length !== marcadas.length) ctx.tabs.afixoEssencias = fora;
    else if (marcadas.length < LOTE_MAXIMO) ctx.tabs.afixoEssencias = [...marcadas, e.lugar];
    ctx.tabs.afixoPreviaInserir = null;
    if (alvo) pedirPreviaDaInsercao(alvo, send);
    ctx.redraw();
  };

  /*
   * As essências mostradas são só as que CABEM na peça escolhida — mesmo slot e
   * mesma qualidade, as duas travas do servidor. Oferecer as outras seria fazer
   * a pessoa descobrir a regra pela recusa, uma essência por vez.
   */
  /*
   * ---- A essência VELHA, que não sabe de onde veio ----
   *
   * As essências feitas antes de os campos de origem viajarem com a peça
   * perderam o slot e a qualidade no primeiro caminho que fizeram (mercado,
   * depósito). O servidor as deixa entrar em qualquer peça — é uma concessão à
   * história, e está escrita em `previaDaInsercao` —, e esta lista tem de
   * concordar com ele.
   *
   * Se ela peneirasse pelas duas travas sem exceção, a essência órfã ficaria
   * INVISÍVEL numa tela que a aceitaria: o servidor diria sim a um pedido que
   * a pessoa não tem como fazer.
   */
  const orfa = (e) => e.slot == null && e.raridade == null;
  /*
   * A VERMELHA pergunta só o slot: "tem que poder colocar em qualquer qualidade
   * de item (do mesmo slot)". A regra mora no servidor (`previaDaInsercao`), e
   * esta lista tem de concordar com ela — peneirar a vermelha por qualidade a
   * esconderia de peças em que ela entra.
   */
  const cabem = alvo
    ? view.essencias.filter(
        (e) =>
          orfa(e) ||
          (e.slot === alvo.slot && (e.mitica || e.raridade === alvo.rarity))
      )
    : view.essencias;

  escolherEssencia(
    body,
    alvo ? `Quais essências pôr (até ${LOTE_MAXIMO}, cabem ${alvo.vagas})` : `Escolha as essências (até ${LOTE_MAXIMO})`,
    cabem,
    trocar,
    alvo
      ? `Nenhuma essência de ${alvo.rarity} para este slot. A essência só entra em peça do mesmo slot e da mesma qualidade — só a vermelha entra em qualquer qualidade.`
      : 'Nenhuma essência na mochila.',
    { marcadas }
  );

  if (!alvo) {
    return void escolherPecaComAfixo(
      body,
      'Em qual peça',
      view.pecas.filter(
        (p) =>
          p.vagas > 0 &&
          (!marcadas.length ||
            orfa(primeira ?? {}) ||
            (p.slot === primeira?.slot && (primeira?.mitica || p.rarity === primeira?.raridade)))
      ),
      (peca) => {
        ctx.tabs.afixoAlvo = peca.lugar;
        ctx.tabs.afixoPreviaInserir = null;
        pedirPreviaDaInsercao(peca, send);
        ctx.redraw();
      },
      marcadas.length
        ? `Nenhuma peça ${primeira.raridade} deste slot com espaço livre.`
        : 'Nenhuma peça com espaço livre.'
    );
  }

  const previa = ctx.tabs.afixoPreviaInserir;
  const valeEsta =
    previa &&
    mesmoLugar(previa.lugar, alvo.lugar) &&
    (previa.essencias ?? []).length === marcadas.length &&
    (previa.essencias ?? []).every((lugar, i) => mesmoLugar(lugar, marcadas[i]));

  if (marcadas.length && valeEsta) {
    if (previa.ok) previaDaPeca(body, `Como ${alvo.nome} fica`, previa.depois);
    else body.append(el('p', 'forja-aviso', previa.reason));
  }

  const porAfixo = view.custos.inserir[alvo.rarity] ?? view.custos.inserir.comum;
  const custoTotal = valeEsta && previa.ok ? previa.custo : { ouro: 0, coins: 0 };
  body.append(moedaDaForja(custoTotal, view));
  const custo = valorNaMoeda(custoTotal);

  const botao = el('button', 'primary', marcadas.length > 1 ? `Inserir ${marcadas.length}` : 'Inserir');
  botao.disabled = !marcadas.length || !valeEsta || !previa?.ok || saldoNaMoeda(view) < custo;
  botao.onclick = () =>
    confirmarForjaDeAfixo({
      id: alvo.id,
      peca: alvo.peca,
      titulo: marcadas.length > 1 ? `Inserir ${marcadas.length} afixos` : 'Inserir afixo',
      frases: [
        { texto: `${alvo.nome} vai ganhar ${previa.entrando.map((l) => l.ficha.texto).join(', ')}.` },
        { texto: marcadas.length > 1 ? 'As essências são consumidas.' : 'A essência é consumida.' },
      ],
      custo,
      saldo: saldoNaMoeda(view),
      unidade: nomeDaMoeda(),
      acao: 'Inserir',
      aoConfirmar: () =>
        send({
          t: 'forjaAfixoInserir',
          essencias: marcadas,
          lugar: alvo.lugar,
          moeda: moedaEscolhida(),
        }),
    });

  precoDaForja(body, {
    custo,
    saldo: saldoNaMoeda(view),
    botao,
    extras: [
      { nome: `por afixo (${alvo.rarity})`, valor: money(valorNaMoeda(porAfixo)), ok: true },
      { nome: 'espaço livre', valor: String(alvo.vagas), ok: alvo.vagas >= marcadas.length },
    ],
  });
}

function pedirPreviaDaInsercao(peca, send) {
  const essencias = ctx.tabs.afixoEssencias ?? [];
  if (!essencias.length) {
    ctx.tabs.afixoPreviaInserir = null;
    return;
  }
  send({ t: 'forjaAfixoPreviaInserir', lugar: peca.lugar, essencias });
}

/* -------------------------------------------------------------- UPGRADE */

/*
 * ---- A bancada de FUSÃO: três casas ----
 *
 * "queria uma aba nova nos afixos, que seria a aba upgrade: teria 3 slots
 * vazios, e a pessoa, ao colocar 3 essências com o mesmo atributo no nível
 * máximo (100%, 3 douradas), faz a essência vermelha."
 *
 * As três casas são literais, e não uma lista com contador: é o desenho que ele
 * descreveu, e é o que faz a regra ficar óbvia antes de qualquer texto — três
 * buracos iguais dizem "três, do mesmo tipo" sem uma linha de explicação.
 *
 * A recusa vem inteira do servidor (são cinco travas: mesmo atributo, mesmo
 * slot, mesma qualidade, todas em 100%, nenhuma já vermelha), e sai escrita
 * embaixo das casas. Peneirar a lista pelas cinco daria a impressão de que a
 * pessoa não TEM as essências, quando o problema é que elas não combinam.
 */
function renderAfixoUpgrade(body, view, send) {
  const casas = (ctx.tabs.afixoFusao ?? [null, null, null]).map((lugar) =>
    lugar ? acharEssencia(view, lugar) : null
  );
  ctx.tabs.afixoFusao = casas.map((e) => e?.lugar ?? null);
  const postas = casas.filter(Boolean);

  const bancada = el('div', 'afixo-fusao');
  casas.forEach((e, i) => {
    const casa = el('button', `forja-quadro fusao${e ? ' cheio' : ''}${e?.mitica ? ' vermelha' : ''}`);
    casa.append(el('em', 'forja-rotulo', `Essência ${i + 1}`));
    const moldura = el('div', 'forja-moldura');
    if (e) {
      moldura.append(arteDaEssencia(e.slot, 40, e.mitica, e.raridade));
      const estrela = estrelaDaEssencia(e);
      if (estrela) moldura.append(estrela);
    } else {
      moldura.append(el('span', 'forja-vazio', '+'));
    }
    casa.append(moldura);
    casa.append(el('b', CLASSE_DA_RARIDADE(e?.raridade), e ? e.afixo.texto : 'vazia'));
    casa.append(el('span', 'forja-onde', e ? `${e.afixo.pct}% · ${nomeDaEssenciaNaTela(e)}` : 'clique numa essência abaixo'));
    casa.onclick = () => {
      const fusao = [...ctx.tabs.afixoFusao];
      fusao[i] = null;
      ctx.tabs.afixoFusao = fusao;
      ctx.tabs.afixoPreviaFundir = null;
      ctx.redraw();
    };
    if (e) tipFor(casa, ID_DA_ESSENCIA, null, null, e.peca ?? null);
    bancada.append(casa);
  });
  body.append(bancada);

  /*
   * ---- A lista já vem peneirada pelo que a fusão ACEITA ----
   *
   * Douradas (100%) e não-vermelhas: são as duas travas que não dependem das
   * outras essências, então elas podem ser aplicadas na lista sem esconder
   * nada que fosse escolha da pessoa. As outras três (mesmo atributo, slot e
   * qualidade) dependem do que já está nas casas, e ficam para a frase de
   * recusa — peneirar por elas faria a lista mudar de tamanho a cada clique.
   */
  const douradas = view.essencias.filter((e) => e.afixo.pct >= 100 && !e.mitica);
  const jaPostas = ctx.tabs.afixoFusao.filter(Boolean);

  if (!douradas.length) {
    body.append(
      el(
        'p',
        'empty',
        'Nenhuma essência dourada na mochila. A fusão só aceita essência em 100% — o topo exato da régua daquele afixo.'
      )
    );
  } else {
    escolherEssencia(
      body,
      'Essências douradas (100%)',
      douradas,
      (e) => {
        const fusao = [...ctx.tabs.afixoFusao];
        const onde = fusao.findIndex((lugar) => mesmoLugar(lugar, e.lugar));
        if (onde >= 0) fusao[onde] = null;
        else {
          const vaga = fusao.indexOf(null);
          if (vaga < 0) return;
          fusao[vaga] = e.lugar;
        }
        ctx.tabs.afixoFusao = fusao;
        ctx.tabs.afixoPreviaFundir = null;
        const cheias = fusao.filter(Boolean);
        if (cheias.length === LOTE_MAXIMO) send({ t: 'forjaAfixoPreviaFundir', essencias: cheias });
        ctx.redraw();
      },
      'Nenhuma essência dourada.',
      { marcadas: jaPostas }
    );
  }

  const previa = ctx.tabs.afixoPreviaFundir;
  const valeEsta =
    previa &&
    (previa.essencias ?? []).length === jaPostas.length &&
    (previa.essencias ?? []).every((lugar, i) => mesmoLugar(lugar, jaPostas[i]));

  if (postas.length === LOTE_MAXIMO && valeEsta) {
    if (previa.ok) {
      body.append(el('h3', 'afixo-previa-titulo', 'O que sai'));
      const saida = el('div', 'afixo-lista previa vermelha');
      saida.append(linhaDoAfixo({ ...previa.ficha, pct: previa.ficha.pct }));
      body.append(saida);
    } else {
      body.append(el('p', 'forja-aviso', previa.reason));
    }
  }

  const custoTotal = view.custos.fusaoTotal ?? { ouro: 0, coins: 0 };
  body.append(moedaDaForja(custoTotal, view));
  const custo = valorNaMoeda(custoTotal);

  const botao = el('button', 'primary', 'Fundir');
  botao.disabled = postas.length !== LOTE_MAXIMO || !valeEsta || !previa?.ok || saldoNaMoeda(view) < custo;
  botao.onclick = () =>
    confirmarForjaDeAfixo({
      id: null,
      arte: () => arteDaEssencia(previa.slot, 48, true, previa.raridade),
      titulo: 'Fundir três essências',
      frases: [
        { texto: `Sai uma essência vermelha: ${previa.ficha.texto}.` },
        { texto: 'É 130% da régua do afixo — 30% acima do que a dourada dá.' },
        { texto: 'As três essências douradas SOMEM.', perigo: true },
      ],
      custo,
      saldo: saldoNaMoeda(view),
      unidade: nomeDaMoeda(),
      acao: 'Fundir',
      aoConfirmar: () => send({ t: 'forjaAfixoFundir', essencias: jaPostas, moeda: moedaEscolhida() }),
    });

  precoDaForja(body, {
    custo,
    saldo: saldoNaMoeda(view),
    botao,
    extras: [
      { nome: 'por essência', valor: money(valorNaMoeda(view.custos.fusao ?? { ouro: 0, coins: 0 })), ok: true },
      { nome: 'nas casas', valor: `${postas.length}/${LOTE_MAXIMO}`, ok: postas.length === LOTE_MAXIMO },
    ],
    aviso: el(
      'p',
      'forja-dica-rodape',
      'As três precisam ser do MESMO afixo, do mesmo slot, da mesma qualidade e todas em 100%. A vermelha sai com o slot e a qualidade delas, e entra onde elas entrariam.'
    ),
  });
}

/*
 * A caixa de confirmar da bancada de afixos.
 *
 * Irmã do `confirmarForja` e separada dele por uma razão só: aquela conta em
 * ouro e escreve "de ouro" em três lugares, e metade destas operações é paga em
 * Draevor Coin. Passar a unidade por parâmetro naquela mudaria o texto de uma tela
 * que já está no ar por causa de outra.
 */
function confirmarForjaDeAfixo({ id, peca = null, arte = null, titulo, frases, custo, saldo, unidade, acao, aoConfirmar }) {
  const back = el('div', 'confirm-back');
  const box = el('div', 'confirm-box forja-confirma');
  box.append(el('h3', null, titulo));

  const moldura = el('div', 'forja-moldura grande');
  /*
   * `arte` existe para a FUSÃO, que não tem item para desenhar: o que sai dela é
   * uma essência, e essência não tem sprite própria (ver `arteDaEssencia`). Sem
   * isso a caixa mais cara da forja abriria com um quadrado vazio.
   */
  if (arte) moldura.append(arte());
  else if (id != null) moldura.append(itemCanvas(id, 48));
  box.append(moldura);
  /*
   * E o balão da peça também aqui, e não só na bancada: a caixa de confirmar é
   * o último lugar em que dá para desistir, e é onde a pergunta "é esta mesmo?"
   * aparece. Mandar fechar a caixa para conferir seria perder a escolha.
   */
  if (id != null && !arte) tipFor(moldura, id, null, null, peca);

  const lista = el('div', 'forja-confirma-frases');
  for (const frase of frases) lista.append(el('p', frase.perigo ? 'perigo' : null, frase.texto));
  box.append(lista);

  if (custo > 0) {
    const conta = el('div', 'balcao-conta');
    for (const [rotulo, valor, classe] of [
      ['Custa', `${money(custo)} ${unidade}`, null],
      ['Tem agora', `${money(saldo)} ${unidade}`, null],
      ['Fica com', `${money(saldo - custo)} ${unidade}`, 'balcao-depois'],
    ]) {
      const item = el('div', 'balcao-conta-item');
      item.append(el('span', null, rotulo), el('b', classe, valor));
      conta.append(item);
    }
    box.append(conta);
  }

  const fechar = () => back.remove();
  const acoes = el('div', 'confirm-actions');
  const cancelar = el('button', 'ghost', 'Cancelar');
  cancelar.onclick = fechar;
  const confirmar = el('button', 'primary', acao);
  confirmar.onclick = () => {
    fechar();
    aoConfirmar();
  };
  acoes.append(cancelar, confirmar);
  box.append(acoes);

  back.append(box);
  fecharAoClicarFora(back, fechar);
  atalhosDaCaixa(back, { confirmar: () => confirmar.click(), fechar });
  document.body.append(back);
  confirmar.focus();
}

/*
 * ---- A aba do CRAFT ----
 *
 * "a terceira aba será a de Craft, que vai ser pra craftar os sets craftado e
 * crafted v2... por enquanto só coloca lá certinho bonitinho separadinho vocação
 * por vocação, use ícones pra cada vocação tipo o fundo de criação de char."
 *
 * ---- A vocação primeiro, e a arte dela como o botão ----
 *
 * A tira de cima é a mesma da criação de personagem: as cinco artes de
 * `client/assets/ui/vocacao-*.webp`, com o mesmo degradê por cima para o nome
 * continuar legível. É de propósito que seja a MESMA arte e não um ícone novo —
 * é a imagem pela qual a pessoa já reconhece a vocação dela neste jogo, e
 * inventar um segundo desenho para a mesma ideia é ensinar duas coisas onde havia
 * uma.
 *
 * ---- Duas gerações, no mesmo lugar ----
 *
 * O Craftado e o V2 não são alternativas: o V2 EXIGE o craftado antigo como
 * material e herda os extras dele. É uma escada, e trocar entre os dois degraus na
 * MESMA boneca é o que deixa isso visível sem ninguém explicar.
 *
 * ---- O que o botão faz, e o que ele recusa ----
 *
 * Ele crafta de verdade, com confirmação (`confirmarForja`). A regra inteira mora
 * no servidor — `craftar`, em `craft.mjs` —, e esta tela não decide nada: ela
 * mostra o que a ficha do servidor diz que falta.
 *
 * As 59 receitas V2 nascem travadas, e não por escolha: todas pedem pelo menos um
 * dos oito itens que existem no OT do dono e nunca foram importados para cá (ver
 * `NOMES_DE_FORA`). Eles aparecem riscados na lista de material, e o rodapé diz
 * por que o botão não abre — em vez de a pessoa procurar na mochila um item que
 * não existe.
 */
/* O nome do lugar da peça, para a linha de baixo do título. */
const LUGAR_DA_PECA = {
  weapon: 'arma',
  shield: 'escudo',
  head: 'elmo',
  body: 'armadura',
  legs: 'pernas',
  feet: 'botas',
  neck: 'colar',
  ring: 'anel',
  ammo: 'amuleto de mão',
  backpack: 'mochila',
};

function pedirCraft(vocacao) {
  ctx.send({ t: 'craft', vocacao: vocacao ?? ctx.tabs.craftVoc ?? null });
}

/*
 * ---- A ORDEM DAS PEÇAS É A DO CORPO ----
 *
 * "eu queria que as peças ficassem organizadas igual como é vestida no
 * inventário".
 *
 * É a mesma lista de `SLOT_LAYOUT` (inventory.mjs), na mesma grade de três
 * colunas — colar, elmo, mochila / arma, armadura, escudo / anel, pernas,
 * munição / botas. Quem procura a bota do set procura embaixo à esquerda, porque
 * é onde a bota mora no inventário; uma lista alfabética obrigaria a ler nome por
 * nome para achar a mesma peça.
 *
 * As duas casas que a boneca do inventário usa para premium e bênçãos ficam
 * VAZIAS aqui, e não são removidas: tirá-las embaralharia as outras dez de lugar,
 * e o desenho deixaria de ser reconhecível — que é a única coisa que ele tem de
 * ser.
 */
/*
 * A arte de fundo de cada casa, a MESMA de `SLOT_ART` no inventário: o desenho
 * cinza de colar, elmo, mochila que aparece na casa vazia. É ele que faz a grade
 * ser reconhecível como o corpo antes de qualquer peça entrar nela.
 */
const ARTE_DO_SLOT = {
  neck: 'neck',
  head: 'head',
  backpack: 'back',
  weapon: 'right-hand',
  body: 'body',
  shield: 'left-hand',
  ring: 'finger',
  legs: 'legs',
  ammo: 'ammo',
  feet: 'feet',
};

const BONECA_DO_CRAFT = [
  'neck', 'head', 'backpack',
  'weapon', 'body', 'shield',
  'ring', 'legs', 'ammo',
  null, 'feet', null,
];

function renderForjaCraft(body) {
  const view = ctx.state.craft;
  if (!view) return void body.append(el('p', 'empty', 'carregando as receitas...'));
  ctx.tabs.craftVoc = view.vocacao;

  efeitoDoCraft(body, view);
  body.append(seletorDeVocacao(view));

  /*
   * ---- OS DOIS SETS, lado a lado ----
   *
   * "faz mostrar os 2 sets, tanto o craftado quanto o craftado v2, na mesma aba."
   *
   * Eram duas gerações num segmentado, e trocar entre elas escondia metade da
   * resposta: o V2 EXIGE o Craftado como material, então a pergunta que se faz
   * olhando o V2 é "e o Craftado dessa peça, eu tenho?" — e a resposta estava a um
   * clique que apagava a pergunta.
   *
   * Lado a lado, os dois degraus da escada ficam na mesma olhada. Cabe: cada
   * boneca são três colunas de 44px, 140px cada uma.
   */
  const sets = el('div', 'craft-sets');
  for (const [geracao, rotulo, dica] of [
    ['craftado', 'Craftado', 'O primeiro degrau: cada peça sai da peça Draevor da mesma vocação.'],
    ['v2', 'Craftado V2', 'O segundo degrau: cada V2 exige o Craftado correspondente e herda os extras dele.'],
  ]) {
    const receitas = geracao === 'v2' ? view.v2 : view.craftado;
    const prontas = receitas.filter((r) => r.pronto).length;

    const coluna = el('div', 'craft-set');
    const cabeca = el('div', 'craft-set-nome');
    cabeca.append(el('b', null, rotulo));
    cabeca.append(el('em', null, `${prontas}/${receitas.length}`));
    cabeca.title = dica;
    coluna.append(cabeca);

    /*
     * O lado para onde as peças extras crescem: o set da esquerda joga para a
     * ESQUERDA, o da direita para a DIREITA. Ver `bonecaDoCraft`.
     */
    coluna.append(bonecaDoCraft(receitas, geracao, geracao === 'v2' ? 'direita' : 'esquerda'));
    sets.append(coluna);

    /*
     * ---- A seta entre os dois ----
     *
     * "entre o set craftado e o craftado v2 coloca uma setinha verde no meio."
     *
     * Ela não é enfeite: diz que os dois são uma ESCADA e não duas opções — o V2
     * consome o Craftado. Aponta do primeiro para o segundo, e é a única coisa
     * verde da tela justamente para ser lida como "daqui vai para ali".
     */
    if (geracao === 'craftado') sets.append(el('div', 'craft-seta', '▶▶'));
  }
  body.append(sets);

  const escolhida = [...view.craftado, ...view.v2].find(
    (r) => `craftado:${r.id}` === ctx.tabs.craftAberta || `v2:${r.id}` === ctx.tabs.craftAberta
  );
  if (escolhida) {
    const geracao = ctx.tabs.craftAberta.startsWith('v2:') ? 'v2' : 'craftado';
    body.append(fichaDaReceita(escolhida, geracao, view, geracao === 'v2' ? view.v2 : view.craftado));
  } else {
    body.append(el('p', 'shop-note dica', 'Clique numa peça de qualquer um dos dois corpos para ver a receita dela.'));
  }

  const bolsa = el('div', 'forja-bolsa');
  bolsa.append(itemCanvas(3031, 18), el('b', null, `${money(view.gold)}`), el('em', null, 'no bolso'));
  body.append(bolsa);
}

/*
 * ---- A tira das vocações ----
 *
 * "deixe o nome das vocação escrito com uma fonte bonita medieval e um pouquinho
 * maior e com o ícone das vocação sabe? igual o ícone do chat."
 *
 * O ícone é literalmente o mesmo: `PERICIA_DA_VOCACAO` é o mapa que o chat e a
 * party já usam (espada para knight, arco para paladino, e as duas magias para
 * druida e sorcerer). Um terceiro desenho para a mesma ideia seria uma terceira
 * coisa a aprender.
 *
 * O fundo continua sendo a arte da criação de personagem, e o nome vai na Cinzel
 * — a mesma capitular dos títulos do jogo. Ver `--font-heading` no CSS.
 */
function seletorDeVocacao(view) {
  const tira = el('div', 'craft-vocs');
  for (const voc of view.vocacoes) {
    const escolhida = voc === view.vocacao;
    const botao = el('button', `craft-voc${escolhida ? ' escolhida' : ''}`);
    // `data-vocation` é o endereço da arte no CSS, o mesmo da criação de char.
    botao.dataset.vocation = voc;
    botao.setAttribute('aria-selected', String(escolhida));

    const nome = el('span', 'craft-voc-nome');
    const marca = PERICIA_DA_VOCACAO[voc];
    if (marca) {
      const icone = artOrUiIcon(marca, '');
      icone.classList.add('craft-voc-icone');
      nome.append(icone);
    }
    nome.append(el('b', null, NOME_DA_VOCACAO[voc] ?? voc));
    botao.append(nome);

    if (voc === view.minha) botao.append(el('em', 'craft-voc-minha', 'a sua'));
    botao.onclick = () => {
      if (escolhida) return;
      // O id aberto é de outra lista: ele ficaria aberto em nada.
      ctx.tabs.craftAberta = null;
      pedirCraft(voc);
    };
    tira.append(botao);
  }
  return tira;
}

/*
 * ---- E ela é a MESMA grade do inventário, casa por casa ----
 *
 * "a aba de craft tinha que mostrar exatamente desse jeito os sets lá, sem
 * espaço sabe, pra meio que a pessoa ver como ficaria."
 *
 * Então não é uma grade "inspirada" na do inventário: é a mesma medida — três
 * colunas de 44px, 4px de vão, centralizada, com a mesma arte cinza de fundo em
 * cada casa (ver `.equipment` e `.slot` no CSS). A primeira versão tinha rótulo e
 * caixa elástica por casa, e o desenho deixava de ser o corpo: virava uma lista
 * em três colunas.
 *
 * ---- E quando o slot tem VÁRIAS peças ----
 *
 * O knight tem seis armas na mesma casa (machado, espada, clava e as três Over).
 * A casa mostra UMA — a escolhida — porque é isso que "como ficaria" quer dizer:
 * um corpo vestido, e não seis armas empilhadas na mão. As outras aparecem numa
 * tira dentro da ficha, embaixo, onde há largura para elas.
 *
 * O cantinho com o número diz quantas variantes existem, para a casa não mentir
 * que só há uma.
 */
function bonecaDoCraft(receitas, geracao, lado = 'direita') {
  const grade = el('div', `craft-boneca lado-${lado}`);

  /*
   * ---- As extras vão na MESMA LINHA da que está vestida ----
   *
   * "mas não embaixo do set, na mesma linha da equipada."
   *
   * A boneca é desenhada linha a linha (três casas cada, as quatro do
   * inventário), e as peças que sobram de um slot saem à direita DA LINHA DELE.
   * As seis armas do knight ficam então na mesma altura da casa da arma, que é
   * onde o olho já está quando a pergunta é "e as outras?".
   *
   * Foi para cá que elas vieram depois de duas tentativas piores: uma coluna na
   * lateral (mais alta que o corpo, empurrava os dois sets para longe) e uma fila
   * no rodapé (longe do slot a que pertencem, e lida como uma segunda lista).
   *
   * ---- E elas crescem PARA FORA ----
   *
   * "as arma extra do set da esquerda você deixa à esquerda, e do set da direita à
   * direita."
   *
   * Os dois corpos ficam encostados na seta verde do meio, e o que sobra abre para
   * as bordas da janela. Crescendo os dois para o mesmo lado, o set da esquerda
   * empurrava a seta e o V2 para longe toda vez que uma vocação tivesse muitas
   * armas — e a comparação entre os dois degraus, que é o ponto da tela, ficava
   * com meio palmo de distância no meio.
   *
   * A ORDEM das peças é a mesma dos dois lados, e não espelhada: o Craftado e o V2
   * têm a mesma lista de armas, e mantendo a ordem a mesma arma cai na mesma
   * posição nos dois — que é o que deixa comparar sem procurar.
   */
  for (let i = 0; i < BONECA_DO_CRAFT.length; i += 3) {
    const daLinha = BONECA_DO_CRAFT.slice(i, i + 3);
    const linha = el('div', 'craft-linha');
    const sobrando = [];

    for (const slot of daLinha) {
      if (!slot) {
        linha.append(el('div', 'craft-casa vazia'));
        continue;
      }
      const daCasa = receitas.filter((r) => r.slot === slot);
      linha.append(casaDaBoneca(slot, daCasa, geracao));
      if (daCasa.length < 2) continue;
      const vestida = escolhaDoSlot(geracao, slot, daCasa);
      for (const receita of daCasa) if (receita.id !== vestida?.id) sobrando.push(receita);
    }

    if (sobrando.length) {
      const tira = tiraDeExtras(sobrando, geracao);
      if (lado === 'esquerda') linha.prepend(tira);
      else linha.append(tira);
    }
    grade.append(linha);
  }
  return grade;
}

/** Qual variante daquele slot está sendo mostrada. Só da tela, por geração. */
function escolhaDoSlot(geracao, slot, daCasa) {
  const guardadas = (ctx.tabs.craftSlot ??= {});
  const chave = `${geracao}:${slot}`;
  const guardada = daCasa.find((r) => r.id === guardadas[chave]);
  return guardada ?? daCasa[0] ?? null;
}

function casaDaBoneca(slot, daCasa, geracao) {
  const receita = escolhaDoSlot(geracao, slot, daCasa);
  if (!receita) {
    // Sem receita nenhuma para este slot: a casa fica, com a arte apagada. Tirá-la
    // embaralharia as outras nove de lugar.
    const vazia = el('div', 'craft-casa sem-receita');
    vazia.append(arteDoSlot(slot));
    return vazia;
  }

  const aberta = ctx.tabs.craftAberta === `${geracao}:${receita.id}`;
  const casa = el(
    'button',
    `craft-casa${aberta ? ' aberta' : ''}${receita.pronto ? ' pronta' : ''}`
  );
  // 40, o mesmo que o CSS reserva na casa de 54px — ver `.craft-casa canvas`.
  casa.append(itemCanvas(receita.id, 40));
  if (!receita.pronto) casa.append(el('i', 'craft-peca-falta', String(receita.falta)));
  if (daCasa.length > 1) casa.append(el('i', 'craft-peca-variantes', String(daCasa.length)));
  balaoDaPecaCraftada(casa, receita);
  casa.onclick = () => {
    ctx.tabs.craftAberta = aberta ? null : `${geracao}:${receita.id}`;
    ctx.redraw();
  };
  return casa;
}

/*
 * ---- O balão do item, com a peça COMO ELA SAIRIA ----
 *
 * "ao passar o mouse tem que ter o modal dos atributos e informações do item
 * igual o nosso modal que já temos ao passar o mouse sobre itens, e tem que
 * comparar com o item atual também."
 *
 * É o mesmo balão, e literalmente a mesma função: `tipFor`. Ele já faz as duas
 * coisas — desenha a ficha do item e, quando o `slot` NÃO é passado, compara com
 * o que está vestido naquele lugar do corpo (ver `comparacaoComOEquipado`). Aqui
 * o slot fica de fora de propósito: a peça craftada não está vestida, e é
 * exatamente a comparação que se quer.
 *
 * ---- E a peça mostrada é a que SAIRIA do craft ----
 *
 * O quinto argumento é a PEÇA, e não só o id: é ele que faz o balão desenhar
 * tier, imbuements e afixos. Como o craft herda os três da peça-base (ver
 * `HERDA_DA_BASE`), o balão monta a peça com os extras que ela vai herdar — e a
 * comparação passa a ser a que interessa: "a que eu faria hoje é melhor do que a
 * que estou usando?".
 *
 * Sem base na mão, `extras` vem nulo e o balão mostra a peça crua, que é a
 * verdade nesse caso.
 */
function balaoDaPecaCraftada(elemento, receita) {
  const extras = receita.herda?.tem ? receita.herda.extras ?? null : null;
  tipFor(elemento, receita.id, null, null, { id: receita.id, count: 1, ...(extras ?? {}) });
}

/*
 * ---- As peças que a boneca não mostra ----
 *
 * A casa mostra UMA peça por slot (é o que "como ficaria" quer dizer). O knight
 * tem seis armas na mesma casa, e as outras cinco estavam escondidas dentro da
 * ficha — o dono pediu para trazê-las para fora.
 *
 * Clicar numa troca a que o corpo veste. Nada some: o que está aqui é exatamente
 * o que a boneca não consegue mostrar por falta de casa.
 */
function tiraDeExtras(fora, geracao) {
  const tira = el('div', 'craft-extras');
  for (const receita of fora) {
    const aberta = ctx.tabs.craftAberta === `${geracao}:${receita.id}`;
    const botao = el(
      'button',
      `craft-extra${aberta ? ' aberta' : ''}${receita.pronto ? ' pronta' : ''}`
    );
    // 40, como a casa do corpo: são as mesmas peças, no mesmo tamanho.
    botao.append(itemCanvas(receita.id, 40));
    if (!receita.pronto) botao.append(el('i', 'craft-peca-falta', String(receita.falta)));
    balaoDaPecaCraftada(botao, receita);
    botao.onclick = () => {
      // Vestir a escolhida: é o que faz a boneca ao lado mostrar esta arma.
      (ctx.tabs.craftSlot ??= {})[`${geracao}:${receita.slot}`] = receita.id;
      ctx.tabs.craftAberta = `${geracao}:${receita.id}`;
      ctx.redraw();
    };
    tira.append(botao);
  }
  return tira;
}

function arteDoSlot(slot) {
  const nome = ARTE_DO_SLOT[slot];
  if (!nome) return el('span', 'craft-casa-nome', LUGAR_DA_PECA[slot] ?? slot);
  const arte = document.createElement('img');
  arte.className = 'slot-art';
  arte.src = `/client/assets/slots/${nome}.png`;
  arte.alt = LUGAR_DA_PECA[slot] ?? slot;
  // Sem a arte, o nome — o mesmo desenho de `slotArt` no inventário.
  arte.onerror = () => arte.replaceWith(el('span', 'craft-casa-nome', LUGAR_DA_PECA[slot] ?? slot));
  return arte;
}

function fichaDaReceita(receita, geracao, view, receitas) {
  const ficha = el('div', `craft-ficha${receita.pronto ? ' pronta' : ''}`);

  const topo = el('div', 'craft-ficha-topo');
  topo.append(itemCanvas(receita.id, 40));
  const texto = el('span', 'craft-ficha-texto');
  texto.append(el('b', null, receita.nome));
  texto.append(el('em', null, LUGAR_DA_PECA[receita.slot] ?? receita.slot ?? ''));
  topo.append(texto);
  topo.append(
    el(
      'span',
      `craft-falta${receita.pronto ? ' tem' : ''}`,
      receita.pronto ? 'tudo em mãos' : `faltam ${receita.falta}`
    )
  );
  ficha.append(topo);

  /*
   * ---- As outras peças do mesmo slot ----
   *
   * A boneca mostra uma por casa (ver `casaDaBoneca`), e as irmãs vêm para cá.
   * Escolher uma troca a que a casa exibe — o corpo passa a mostrar a espada em
   * vez do machado, que é o que "ver como ficaria" quer dizer.
   */
  const irmas = (receitas ?? []).filter((r) => r.slot === receita.slot);
  if (irmas.length > 1) {
    const tira = el('div', 'craft-irmas');
    for (const irma of irmas) {
      const botao = el(
        'button',
        `craft-irma${irma.id === receita.id ? ' escolhida' : ''}${irma.pronto ? ' pronta' : ''}`
      );
      botao.append(itemCanvas(irma.id, 26));
      balaoDaPecaCraftada(botao, irma);
      botao.onclick = () => {
        (ctx.tabs.craftSlot ??= {})[`${geracao}:${irma.slot}`] = irma.id;
        ctx.tabs.craftAberta = `${geracao}:${irma.id}`;
        ctx.redraw();
      };
      tira.append(botao);
    }
    ficha.append(tira);
  }

  /*
   * ---- O que a peça VAI HERDAR, e não só de quem ----
   *
   * "confirma pra mim que na hora do craft o item que vai ser feito tem que herdar
   * imbuiments, tier e afixos da peça base" — e a resposta é sim, os três.
   *
   * Então a linha diz os três, com os números de AGORA: é o que decide se vale
   * craftar já ou subir a peça-base antes, e um "herda o tier" genérico não
   * responde isso.
   */
  if (receita.herda) {
    const h = receita.herda;
    const partes = [];
    if (h.tier) partes.push(`tier ${h.tier}`);
    if (h.imbuements) partes.push(`${h.imbuements} imbuement${h.imbuements === 1 ? '' : 's'}`);
    if (h.afixos) partes.push(`${h.afixos} afixo${h.afixos === 1 ? '' : 's'}`);
    ficha.append(
      el(
        'p',
        'craft-herda',
        h.tem
          ? `Herda de ${h.nome} — a sua entrega ${partes.length ? partes.join(', ') : 'nada ainda (tier 0, sem imbuement e sem afixo)'}.`
          : `Herda tier, imbuements e afixos de ${h.nome} — você não tem nenhuma.`
      )
    );
  }

  const grade = el('div', 'craft-mats');
  for (const material of receita.materiais) grade.append(linhaDoMaterial(material));
  ficha.append(grade);

  const impossivel = receita.materiais.some((m) => m.deFora);
  const botao = el('button', receita.pronto ? 'primary forja-botao' : 'ghost forja-botao', 'Craftar');
  botao.disabled = !receita.pronto;
  botao.title = impossivel
    ? 'esta receita pede material que ainda não existe neste jogo'
    : receita.pronto
      ? `${receita.nome} será feita, e os materiais somem.`
      : `Faltam ${receita.falta} materiais.`;
  botao.onclick = () =>
    confirmarForja({
      id: receita.id,
      tier: receita.herda?.tier ?? 0,
      titulo: 'Craftar',
      frases: [
        { texto: `${receita.nome} vai ser feita.` },
        receita.herda?.tem
          ? { texto: `${receita.herda.nome} será CONSUMIDA, e a peça nova herda o tier, os imbuements e os afixos dela.`, perigo: true }
          : { texto: 'Todos os materiais da receita serão consumidos.', perigo: true },
      ],
      custo: receita.materiais.find((m) => m.dinheiro)?.precisa ?? 0,
      gold: view.gold,
      acao: 'Craftar',
      aoConfirmar: () => ctx.send({ t: 'craftFazer', vocacao: view.vocacao, geracao, id: receita.id }),
    });

  const rodape = el('div', 'craft-ficha-rodape');
  if (impossivel) {
    rodape.append(
      el('em', 'craft-impossivel', 'Esta receita pede material que ainda não existe neste jogo (riscado acima).')
    );
  }
  rodape.append(botao);
  ficha.append(rodape);

  return ficha;
}

function linhaDoMaterial(material) {
  const linha = el(
    'div',
    `craft-mat${material.ok ? ' ok' : ' falta'}${material.deFora ? ' de-fora' : ''}`
  );
  /*
   * A crystal coin da receita dele é DINHEIRO, e não uma pilha de moedas: o
   * `getMoney` do lua conta a moeda como ouro. Vinte mil crystal coins são 200
   * milhões — e é assim que a linha aparece, com o saco de ouro, porque pedir
   * vinte mil moedas na mochila seria uma receita que ninguém fecha.
   */
  linha.append(itemCanvas(material.dinheiro ? 3031 : material.id, 22));
  linha.append(el('b', null, material.nome));
  linha.append(el('em', null, `${money(material.tem)} / ${money(material.precisa)}`));
  if (material.deFora) {
    linha.title = 'este material está na receita do servidor e ainda não existe aqui';
  }
  return linha;
}

/*
 * O cartaz da peça que saiu do fogo. Mesma ideia do `efeitoDaForja`: subir um
 * tier ou fazer uma peça troca pouquíssimo pixel na tela, e um gesto que custa
 * bilhões não pode parecer um clique que não funcionou.
 */
let craftJaMostrado = null;

function efeitoDoCraft(body, view) {
  if (!view.craftou || craftJaMostrado === view) return;
  craftJaMostrado = view;
  const feito = view.craftou;

  const cartaz = el('div', 'forja-resultado');
  const moldura = el('div', 'forja-moldura grande forjando');
  moldura.append(itemCanvas(feito.id, 40));
  if (feito.herdou?.tier) moldura.append(el('i', 'forja-selo', String(feito.herdou.tier)));
  cartaz.append(moldura);
  for (let i = 0; i < 6; i++) moldura.append(el('i', `forja-faisca f${i}`));

  const partes = [];
  if (feito.herdou?.tier) partes.push(`tier ${feito.herdou.tier}`);
  const quantosImbu = feito.herdou?.imbu ? Object.keys(feito.herdou.imbu).length : 0;
  if (quantosImbu) partes.push(`${quantosImbu} imbuement${quantosImbu === 1 ? '' : 's'}`);
  const quantosAf = feito.herdou?.af?.length ?? 0;
  if (quantosAf) partes.push(`${quantosAf} afixo${quantosAf === 1 ? '' : 's'}`);

  const texto = el('div', 'forja-resultado-texto');
  texto.append(el('b', null, `${feito.nome} saiu da forja`));
  texto.append(
    el('em', null, partes.length ? `herdou ${partes.join(', ')} de ${feito.base ?? 'a peça-base'}` : 'sem nada a herdar da peça-base')
  );
  cartaz.append(texto);
  body.append(cartaz);
}
/*
 * ---- A loja de um NPC ----
 *
 * A Zuma Magehide, do servidor do dono: anéis, amuletos, as armas de treino e
 * três sacolas de boss que ela compra de volta.
 *
 * ---- Por que ela não é a loja de gold ----
 *
 * A loja de gold (o botão da barra) é uma ESCADA por level: ela mostra o melhor
 * que o personagem pode usar agora, e o que ele veste sai destacado. Nada disso
 * se aplica a um anel de 100 gold que qualquer um compra em qualquer level.
 *
 * Aqui a tela é o balcão: o preço, quantos você já tem, e o botão.
 *
 * ---- Duas ABAS, e não uma lista ----
 *
 * "separa 2 fileiras: uma do que ela compra e outra do que ela vende" — e
 * depois, porque a primeira tentativa não bastou: "faltou separar a aba da
 * Zuma de compra e venda".
 *
 * A tentativa do meio empilhava as duas listas na MESMA rolagem, com um título
 * no meio. Não separava nada de verdade: as três linhas de venda continuavam
 * embaixo de quarenta de compra, a quatro rolagens de distância, e quem entrasse
 * para vender uma primal bag encontrava a mesma parede de anéis de antes.
 *
 * Aba é o que separa: cada lado ocupa a janela inteira, e trocar é um clique.
 * É a mesma barra da forja e do balcão, então não há nada de novo para aprender.
 *
 * ---- Os nomes são do JOGADOR, e não da NPC ----
 *
 * "Comprar" é a aba do que ELA vende, e "Vender" a do que ela compra. Nomeá-las
 * do lado dela ("o que ela vende") obrigaria a inverter a frase de cabeça a
 * cada visita — e o botão dentro da linha já diz Comprar e Vender.
 *
 * Se um dia alguma peça tiver os dois preços, ela aparece nas duas abas — que é
 * o certo: são dois negócios diferentes com a mesma peça.
 */
export function openLojaNpc(id = 'zuma') {
  ctx.send({ t: 'falarComNpc', id });
  ctx.tabs.lojaAba ??= 'comprar';
  ctx.openModal('Loja', (body) => {
    const draw = () => {
      body.innerHTML = '';
      renderLojaNpc(body);
    };
    ctx.redraw = draw;
    draw();
  });
}

function renderLojaNpc(body) {
  const { state } = ctx;
  const loja = state.npcLoja;
  if (!loja) return void body.append(el('p', 'empty', 'carregando...'));

  const cabeca = el('p', 'shop-note');
  /*
   * "de ouro", e não "no bolso": desde que o balcão passa a contar o banco
   * junto (ver `falarComNpc`, no servidor), dizer "no bolso" seria um número
   * que não bate com o que a bolsa do jogador mostra.
   */
  cabeca.append(el('b', null, loja.nome), document.createTextNode(` — ${money(loja.gold)} de ouro (bolso + banco).`));
  body.append(cabeca);
  if (loja.fala) body.append(el('p', 'shop-note dica', loja.fala));

  const catalogo = loja.catalogo ?? [];
  const aVenda = catalogo.filter((linha) => linha.buy);
  const queElaCompra = catalogo.filter((linha) => linha.sell);

  /*
   * A contagem vai NO RÓTULO da aba.
   *
   * Sem ela, "Vender" é uma aba que não promete nada — e a maior parte das
   * lojas tem pouquíssimas linhas desse lado. Com o número, dá para decidir se
   * vale o clique antes de dá-lo.
   */
  const aba = ctx.tabs.lojaAba === 'vender' ? 'vender' : 'comprar';
  body.append(
    tabBar(
      { comprar: `Comprar (${aVenda.length})`, vender: `Vender (${queElaCompra.length})` },
      aba,
      (qual) => {
        ctx.tabs.lojaAba = qual;
        ctx.redraw();
      },
      /*
       * As duas abas usam arte que JÁ existe — a da loja e a da venda rápida —
       * em vez de pedir um `aba-comprar.png` que ninguém desenhou. Sem isto as
       * abas ficariam de texto puro no meio de um jogo em que toda aba tem
       * cara, e ainda pediriam dois arquivos inexistentes a cada abertura.
       */
      { comprar: 'shop', vender: 'quicksell' }
    )
  );

  if (aba === 'comprar') {
    fileiraDaLoja(body, {
      sub: 'você paga',
      linhas: aVenda,
      lado: 'comprar',
      loja,
      vazio: 'Ela não tem nada à venda agora.',
    });
  } else {
    fileiraDaLoja(body, {
      sub: 'ela paga',
      linhas: queElaCompra,
      lado: 'vender',
      loja,
      vazio: 'Ela não compra nada.',
    });
  }
}

/**
 * Uma das duas fileiras do balcão.
 *
 * O `lado` decide tudo o que difere entre elas — o preço que aparece, o rótulo
 * do botão e o que o botão manda —, e é por isso que as duas passam por aqui em
 * vez de terem cada uma o seu laço: o dia em que a linha ganhar um campo novo,
 * ele nasce nas duas.
 */
function fileiraDaLoja(body, { sub, linhas, lado, loja, vazio }) {
  const comprando = lado === 'comprar';

  /*
   * A cabeça não repete o nome: a aba acesa já o diz, dois centímetros acima.
   * O que sobra é o que a aba não cabe — quantos são e quem paga a quem.
   */
  const cabeca = el('div', 'loja-fileira-cabeca');
  cabeca.append(el('em', null, `${linhas.length} ${linhas.length === 1 ? 'item' : 'itens'} · ${sub}`));
  body.append(cabeca);

  if (!linhas.length) return void body.append(el('p', 'empty', vazio));

  /*
   * ---- A escolha é de CADA aba ----
   *
   * "cada aba tem a sua função, a de vender e a de compra, cuidado pra não
   * bugar." Duas chaves separadas, e não uma: com uma só, escolher uma primal
   * bag para vender deixaria o balcão de compra apontado para um item que ele
   * não vende — e o botão mandaria `npcComprar` com o id errado.
   *
   * A escolha vive em `ctx.tabs` porque a tela se refaz sozinha: cada compra
   * traz um `npcFala` novo do servidor, e uma escolha guardada aqui dentro
   * morreria a cada clique no botão.
   */
  const chave = comprando ? 'lojaItemComprar' : 'lojaItemVender';
  // `chave`: quando o mesmo item aparece em mais de uma linha (a gema em cada raridade, na Zuma).
  const chaveDa = (linha) => linha.chave ?? linha.id;
  const existe = (k) => linhas.some((linha) => chaveDa(linha) === k);
  if (!existe(ctx.tabs[chave])) ctx.tabs[chave] = chaveDa(linhas[0]);

  const lista = el('div', 'loja-npc');
  let categoriaAnterior = null;
  for (const linha of linhas) {
    // As categorias (a loja de gemas: Ataque, Cura, Reforço, Suporte — como no Path of Exile).
    if (linha.categoriaNome && linha.categoria !== categoriaAnterior) {
      categoriaAnterior = linha.categoria;
      lista.append(el('h4', 'loja-categoria', `${linha.categoriaNome} · ${linhas.filter((l) => l.categoria === linha.categoria).length}`));
    }
    const preco = comprando ? linha.buy : linha.sell;
    const card = el('button', 'loja-linha');
    card.type = 'button';
    // O balão do item (a gema: o que faz, com os números do seu personagem), como em qualquer lista de itens.
    tipFor(card, linha.id, null, null, { id: linha.id, count: 1, ...(linha.raridade ? { raridade: linha.raridade } : {}), ...(linha.categoria && linha.categoria !== 'orbes' ? { gema: { nivel: 1, xp: 0, qualidade: 0 } } : {}) });
    if (chaveDa(linha) === ctx.tabs[chave]) card.classList.add('escolhida');
    if (linha.raridade) card.classList.add(classeDaRaridade(null, { raridade: linha.raridade }));
    card.append(itemCanvas(linha.id, 32));

    const texto = el('div', 'loja-texto');
    texto.append(el('b', null, linha.nome));
    const detalhe = el('span', 'loja-sub');
    detalhe.append(
      comprando
        ? document.createTextNode(`${money(preco)} de ouro cada`)
        : el('i', 'loja-paga', `ela paga ${money(preco)} cada`)
    );
    if (linha.tenho) detalhe.append(el('i', 'loja-tenho', `você tem ${money(linha.tenho)}`));
    texto.append(detalhe);
    card.append(texto);

    card.onclick = () => {
      ctx.tabs[chave] = chaveDa(linha);
      ctx.redraw();
    };
    lista.append(card);
  }
  body.append(lista);

  body.append(balcaoDaLoja({ linha: linhas.find((l) => chaveDa(l) === ctx.tabs[chave]), lado, loja }));
}

/*
 * ---- O BALCÃO: um item escolhido, uma régua e um botão ----
 *
 * Pedido do dono: "em vez de ter vários botão de comprar no começo teria um
 * scroll rolável na horizontal pra escolher a quantidade e um botão comprar só;
 * aí selecionaria o item, escolheria a quantidade e comprava, igual como é na
 * base do crystal server".
 *
 * É o balcão do client dele: a lista em cima, e embaixo o item escolhido com a
 * barra de quantidade e o OK. O que ele troca não é aparência — é o número de
 * gestos. Antes cada linha tinha o seu botão, e cada botão abria uma caixa por
 * cima da tela para perguntar quantos; comprar três coisas eram três caixas
 * abertas e fechadas. Agora a pergunta está sempre à vista, no mesmo lugar, e
 * comprar de novo é arrastar e clicar.
 *
 * A régua é a MESMA de separar pilha e de pôr quantidade numa troca
 * (`controleDeQuantidade`): quem já usou uma, já sabe usar esta.
 *
 * ---- O teto sai do lado ----
 *
 * Comprando, é o que o ouro paga; vendendo, é o que existe na mochila. Os dois
 * cortados em cem, que é o teto do servidor (`POR_COMPRA`, em `npcs.mjs`):
 * uma régua que vai até um milhão de anéis é uma régua que promete um pedido
 * que vai ser recusado.
 */
function balcaoDaLoja({ linha, lado, loja }) {
  const comprando = lado === 'comprar';
  const balcao = el('div', 'loja-balcao');
  if (!linha) return balcao;

  const preco = comprando ? linha.buy : linha.sell;
  /*
   * Cem por vez, como o servidor. Ver a nota do `POR_COMPRA` em `npcs.mjs`:
   * sem o corte, um anel de 100 gold no bolso de quem tem 100kk viraria um
   * pedido de um milhão de anéis, que `addItem` empilha numa casa só.
   */
  const CABEM_POR_VEZ = 100;
  const teto = comprando
    ? Math.min(CABEM_POR_VEZ, Math.floor((loja.gold ?? 0) / Math.max(1, preco)))
    : Math.min(CABEM_POR_VEZ, linha.tenho ?? 0);
  const pode = teto >= 1;

  const alvo = el('div', 'loja-balcao-alvo');
  alvo.append(itemCanvas(linha.id, 40));
  const texto = el('div', 'loja-balcao-texto');
  texto.append(el('b', null, linha.nome));
  texto.append(el('em', null, `${money(preco)} de ouro cada`));
  alvo.append(texto);
  balcao.append(alvo);

  if (!pode) {
    balcao.append(
      el(
        'p',
        'loja-balcao-nao',
        comprando
          ? `Faltam ${money(preco - (loja.gold ?? 0))} de ouro para uma.`
          : `Você não tem ${linha.nome} na mochila.`
      )
    );
    return balcao;
  }

  const confirmar = el('button', 'primary', comprando ? 'Comprar' : 'Vender');
  const total = el('b', null, '');
  const depois = el('b', 'balcao-depois', '');

  const quantia = controleDeQuantidade({
    id: linha.id,
    max: teto,
    /*
     * Começa em 1, e não no teto.
     *
     * O botão está sempre à vista agora, e um balcão que abre com "comprar
     * cem" armado é um clique distraído de distância de gastar tudo. Quem
     * quer o máximo tem o atalho "Tudo" a um clique.
     */
    valor: 1,
    aoMudar: (quantos) => {
      const soma = quantos * preco;
      const sobra = (loja.gold ?? 0) + (comprando ? -soma : soma);
      total.textContent = `${money(soma)} de ouro`;
      depois.textContent = `${money(sobra)} de ouro`;
      // Ficar com menos ouro é o esperado numa compra; ficar sem, não.
      depois.classList.toggle('vazia', comprando && sobra <= 0);
      confirmar.disabled = quantos < 1 || (comprando && soma > (loja.gold ?? 0));
    },
  });
  balcao.append(quantia.node);

  /*
   * A conta que ninguém faz de cabeça: o total, e com quanto ele fica. Era o
   * miolo da caixa de confirmação, e é a única parte dela que fazia falta.
   */
  const conta = el('div', 'loja-balcao-conta');
  for (const [rotulo, valor] of [
    [comprando ? 'Custa' : 'Você recebe', total],
    ['Fica com', depois],
  ]) {
    const item = el('div', 'balcao-conta-item');
    item.append(el('span', null, rotulo), valor);
    conta.append(item);
  }
  confirmar.onclick = () => {
    const quantos = quantia.ler();
    // `pedido`: o id deste clique. O servidor ignora o mesmo pedido chegando de novo (duplo clique, reenvio) — a compra não duplica.
    const pedido = globalThis.crypto?.randomUUID?.() ?? `${Date.now()}-${Math.random()}`;
    ctx.send({ t: comprando ? 'npcComprar' : 'npcVender', id: linha.id, count: quantos, ...(comprando ? { pedido } : {}), ...(linha.raridade ? { raridade: linha.raridade } : {}) });
  };
  const acoes = el('div', 'loja-balcao-acoes');
  acoes.append(confirmar);

  // A conta e o botão na MESMA linha: são as duas metades da mesma frase.
  const rodape = el('div', 'loja-balcao-rodape');
  rodape.append(conta, acoes);
  balcao.append(rodape);

  return balcao;
}

/*
 * ---- E a CAIXA de confirmação saiu ----
 *
 * Ela perguntava quantos, dizia o total e com quanto o jogador ficaria. As
 * três respostas continuam existindo — mudaram de lugar. Agora moram no
 * balcão, à vista o tempo todo, em vez de aparecerem por cima da tela depois
 * de um clique e sumirem depois de outro.
 *
 * Era a única dona da régua e da conta; sem ela, `balcaoDaLoja` ficou com as
 * duas. Ver a nota de lá.
 */

/*
 * ---- A BOSS POUCH ----
 *
 * Pedido do dono: "ao abrir vai ter 1.000 slots, com botão limpar, vender igual
 * da mochila normal e etc... e o botão limpar e vender dessa boss pouch tem que
 * ter confirmação, cancelar, marcar tudo, marcar só o que NPC compra e etc".
 *
 * ---- Uma tela, e não três ----
 *
 * A mochila tem três: a grade, o "Vender" e o "Limpar", cada uma com a sua
 * seleção. Aqui é uma só, com DOIS botões no fim — e a razão é a bolsa em si:
 * mil vagas é uma lista que se percorre uma vez, e obrigar a pessoa a marcar
 * tudo de novo numa segunda tela para jogar fora o que ela acabou de decidir
 * não vender é trabalho que a tela cria para si mesma.
 *
 * A marcação é uma só; o que muda é o botão em que ela termina. Os dois pedem
 * confirmação, e os dois listam o que sai antes de fazer.
 *
 * ---- As duas peneiras, como em toda tela de venda deste jogo ----
 *
 * `motivo` é a trava dura (ninguém compra, ou o jogador marcou "não vender") e
 * `aviso` é a branda (tier, imbuement ou estrela), que nasce fora da seleção e
 * só sai com a segunda confirmação. Ver `previaDeUmaLista`, no servidor.
 *
 * Com UMA diferença, e ela é a razão de os dois botões viverem juntos: o que
 * "nenhum NPC compra" NÃO pode ser vendido, mas PODE ser jogado fora. É
 * justamente o entulho que enche a bolsa. Por isso a célula recusada continua
 * clicável, e só o botão de vender a ignora.
 */
export function openVenderBossPouch() {
  const { state, send } = ctx;
  // Fora do `desenhar`: o redesenho a cada clique não pode perder a escolha.
  const marcadas = new Set();

  // Pede a prévia agora; a resposta chega pelo websocket e redesenha.
  send({ t: 'bossPouch' });

  ctx.openModal('Boss Pouch', (body) => {
    const desenhar = () => {
      body.innerHTML = '';
      const previa = state.bossPouch;

      if (!previa) {
        body.append(el('p', 'gate-note', 'Abrindo a bolsa...'));
        return;
      }
      if (!previa.linhas.length) {
        body.append(
          el(
            'p',
            'gate-note',
            'A Boss Pouch está vazia. Tudo o que você tirar do baú de recompensa de boss cai aqui.'
          )
        );
        const acoes = el('div', 'confirm-actions');
        const fechar = el('button', 'ghost', 'Fechar');
        fechar.onclick = () => ctx.closeModal();
        acoes.append(fechar);
        body.append(acoes);
        return;
      }

      const vendaveis = previa.linhas.filter((linha) => !linha.motivo && !linha.aviso);
      const comAviso = previa.linhas.filter((linha) => linha.aviso);
      const recusadas = previa.linhas.filter((linha) => linha.motivo);

      body.append(
        el(
          'p',
          'shop-note',
          `${previa.usados} de ${previa.slots} vagas. O NPC paga o preço cheio. ` +
            'Clique para marcar o que sai — o mesmo conjunto serve para vender e para jogar fora.'
        )
      );

      const grade = el('div', 'filter-grid venda-grade rolagem');
      for (const linha of previa.linhas) {
        const marcada = marcadas.has(linha.i);
        const cell = itemCell({ ...linha }, 'filter');

        const caixa = el('div', 'venda-item');
        const preco = el('span', 'venda-preco', linha.motivo ? '—' : `${money(linha.total)}g`);
        caixa.append(cell, preco);

        /*
         * A peça que o NPC não compra fica APAGADA e clicável: ela não pode ser
         * vendida e pode ser jogada fora, e é a maior parte do que enche a
         * bolsa. Travá-la aqui deixaria de fora exatamente o que o "Jogar fora"
         * existe para tirar.
         */
        if (linha.motivo) cell.classList.add('venda-travada');
        if (linha.aviso && !marcada) cell.classList.add('venda-travada');
        cell.classList.add(marcada ? 'barred' : 'protected');
        if (marcada) caixa.classList.add('marcada');
        if (linha.aviso) caixa.classList.add('com-aviso');

        const oQueEla = linha.motivo
          ? `${linha.motivo} — só dá para jogar fora`
          : linha.aviso
          ? `${linha.aviso} — a tela pergunta de novo antes`
          : `vale ${money(linha.total)}g`;
        tipTexto(cell, `${marcada ? 'MARCADA para sair' : 'fica na bolsa'} · ${oQueEla}`);
        cell.title = `${money(linha.count)}x — ${oQueEla}`;

        caixa.onclick = () => {
          if (marcada) marcadas.delete(linha.i);
          else marcadas.add(linha.i);
          desenhar();
        };
        grade.append(caixa);
      }
      body.append(grade);

      if (comAviso.length) {
        body.append(
          el(
            'em',
            'filter-legend',
            `${comAviso.length} ${comAviso.length === 1 ? 'peça tem' : 'peças têm'} tier, imbuement ou estrela. ` +
              'Elas nascem fora da seleção e só saem se você clicar em cada uma — e aí a tela pergunta de novo.'
          )
        );
      }
      if (recusadas.length) {
        body.append(
          el(
            'em',
            'filter-legend',
            `${recusadas.length} ${recusadas.length === 1 ? 'peça não tem' : 'peças não têm'} comprador. ` +
              'Elas podem ser jogadas fora, mas não vendidas.'
          )
        );
      }

      /* ---- os três botões de marcação ---- */
      const marcacao = el('div', 'confirm-actions');
      const todasLimpas = vendaveis.length > 0 && vendaveis.every((linha) => marcadas.has(linha.i));

      const soVendaveis = el(
        'button',
        'ghost',
        todasLimpas ? 'Desmarcar os vendáveis' : 'Marcar só o que o NPC compra'
      );
      soVendaveis.disabled = !vendaveis.length;
      soVendaveis.onclick = () => {
        if (todasLimpas) for (const linha of vendaveis) marcadas.delete(linha.i);
        else for (const linha of vendaveis) marcadas.add(linha.i);
        desenhar();
      };

      const tudo = el('button', 'ghost', 'Marcar tudo');
      tudo.onclick = () => {
        for (const linha of previa.linhas) marcadas.add(linha.i);
        desenhar();
      };

      const nada = el('button', 'ghost', 'Desmarcar tudo');
      nada.disabled = !marcadas.size;
      nada.onclick = () => {
        marcadas.clear();
        desenhar();
      };
      marcacao.append(soVendaveis, tudo, nada);
      body.append(marcacao);

      /* ---- o que está marcado, e o que cada botão faria com isso ---- */
      const escolhidas = previa.linhas.filter((linha) => marcadas.has(linha.i));
      const paraVender = escolhidas.filter((linha) => !linha.motivo);
      const valiosas = escolhidas.filter((linha) => linha.aviso);
      const ouro = paraVender.reduce((soma, linha) => soma + linha.total, 0);
      const pecas = escolhidas.reduce((soma, linha) => soma + linha.count, 0);

      const resumo = el('p', 'gate-note');
      resumo.textContent = escolhidas.length
        ? `${money(pecas)} item(ns) em ${escolhidas.length} ${escolhidas.length === 1 ? 'quadradinho' : 'quadradinhos'}` +
          (paraVender.length < escolhidas.length
            ? ` — ${money(ouro)} gold ao vender (${escolhidas.length - paraVender.length} sem comprador).`
            : ` — ${money(ouro)} gold.`)
        : `Nada marcado. Há ${money(vendaveis.length)} ${
            vendaveis.length === 1 ? 'quadradinho' : 'quadradinhos'
          } que o NPC compra, somando ${money(previa.total)} gold.`;
      body.append(resumo);

      /*
       * O `mesmoAssim` viaja SÓ nas linhas travadas. O servidor recusa em
       * silêncio uma peça protegida que chegue sem a marca — ver
       * `venderDaBossPouch` e `limparBossPouch`.
       */
      const enderecos = (linhas) =>
        linhas.map((linha) => ({
          i: linha.i,
          id: linha.id,
          ...(linha.aviso || linha.motivo ? { mesmoAssim: true } : {}),
        }));

      const acoes = el('div', 'confirm-actions');
      const fechar = el('button', 'ghost', 'Fechar');
      fechar.onclick = () => ctx.closeModal();

      const vender = el('button', valiosas.length ? 'danger' : 'primary', `Vender por ${money(ouro)}g`);
      vender.disabled = !paraVender.length;
      vender.onclick = () =>
        confirmarVendaDaMochila(paraVender, valiosas, ouro, () => {
          send({ t: 'bossPouch', vender: enderecos(paraVender) });
          marcadas.clear();
        });

      const limpar = el('button', 'danger', 'Jogar fora');
      limpar.disabled = !escolhidas.length;
      limpar.onclick = () =>
        confirmarDeNovo({
          titulo: 'Jogar fora?',
          texto:
            `${money(pecas)} item(ns) em ${escolhidas.length} quadradinho(s) somem da Boss Pouch. ` +
            (valiosas.length
              ? `${valiosas.length} ${valiosas.length === 1 ? 'tem' : 'têm'} tier, imbuement ou estrela. `
              : '') +
            'Isto não tem volta, e não paga nada.',
          botao: 'Jogar fora assim mesmo',
          aoConfirmar: () => {
            send({ t: 'bossPouch', limpar: enderecos(escolhidas) });
            marcadas.clear();
          },
        });

      acoes.append(fechar, vender, limpar);
      body.append(acoes);
    };
    ctx.redraw = desenhar;
    desenhar();
  });
}

/*
 * ---- A Recompensa Diária: trinta dias na parede ----
 *
 * "tem que ser uma aba bem bonita". O desenho segue o reward shrine do
 * servidor dele: os dias em fileira, o de hoje aceso, os já pegos apagados e a
 * sequência escrita em cima.
 *
 * ---- Por que os TRINTA aparecem, e não só o de hoje ----
 *
 * Porque o que faz voltar amanhã não é o prêmio de hoje — é ver o do dia 30. Um
 * painel que mostrasse só o da vez seria um botão de pegar com moldura, e a
 * sequência inteira, que é o produto, ficaria invisível.
 *
 * ---- O fundo ----
 *
 * `diario-banner.png` é arte, e arte chega depois do código. Enquanto o arquivo
 * não existe a faixa fica com o degradê do próprio jogo — que é o motivo de o
 * degradê estar no CSS e não dentro da imagem: pondo o arquivo na pasta, ele
 * entra por cima sem tocar em nada.
 */
export function openDiario() {
  /*
   * Sem título e com a variante `diario`.
   *
   * A moldura pintada JÁ tem o nome dela, o medalhão e a borda trabalhada. A
   * caixa do modal traz outra borda e outro título por cima — duas molduras e
   * dois títulos para a mesma tela. A variante tira a caixa do caminho e deixa
   * a arte ser o painel; o X de fechar continua, que é a única coisa da caixa
   * que faz falta.
   */
  ctx.openModal('', (body) => corpoDoDiario(body), null, 'diario');
}

/*
 * O diário desenha dentro de um quadro próprio, e não limpando `body`.
 *
 * Hoje ele tem a janela toda para si, então dá na mesma. Mas ele já morou
 * dentro da aba de Tarefas por um momento, e ali `body.innerHTML = ''` apagava
 * a FILEIRA DE ABAS junto — a janela ficava sem caminho de volta. O quadro
 * custa uma div e tira essa armadilha do caminho.
 */
/*
 * ---- A sequência do quadro anterior mora FORA da função ----
 *
 * É o que diz que o dia FOI PEGO agora, e não que a tela apenas redesenhou
 * (ver `acenderDoGargoyle`). Estava dentro do `corpoDoDiario`, e não
 * funcionava nunca: nos dias de ESCOLHA o servidor manda abrir a janela de
 * novo, o `corpoDoDiario` roda outra vez do zero e a variável voltava a
 * `null` — exatamente no quadro em que ela existe para detectar alguma coisa.
 *
 * O NOME do personagem vai junto porque a sequência é dele: trocar de char
 * pode subir o número sem ninguém ter coletado nada, e o brilho comemoraria a
 * troca de personagem.
 */
let diarioVisto = { quem: null, sequencia: null };

function corpoDoDiario(body) {
  const { state, send } = ctx;
  const quadro = el('div', 'diario-quadro');
  body.append(quadro);

  /*
   * ---- A escolha tem DOIS passos: marcar e confirmar ----
   *
   * Antes o clique no icone entregava na hora. Oito Durable Exercises lado a
   * lado, um clique sem volta e nenhuma pergunta: quem errasse a arma ficava
   * com ela para sempre — e o erro e' facil, porque os oito desenhos sao
   * parecidos e pequenos.
   *
   * Estas tres variaveis moram AQUI, e nao dentro do `desenhar`: ele reconstroi
   * a tela inteira a cada quadro, e la' dentro a marca se perderia no primeiro
   * redesenho.
   *
   *   marcada     o que esta' escolhido, ainda sem valer nada;
   *   diaMarcado  de que dia e' essa marca — se o dia pendente mudar, a marca
   *               velha nao pode sobrar marcada num dia novo;
   *   adiada      a pessoa clicou em Cancelar. A escolha continua pendente no
   *               servidor (ela NAO perde o premio); so' a janela saiu da
   *               frente, e o botao de baixo a traz de volta.
   */
  let marcada = null;
  let diaMarcado = null;
  let adiada = false;

  const desenhar = () => {
    quadro.innerHTML = '';
    const diario = state.character?.diario;
    if (!diario) {
      return void quadro.append(el('p', 'empty', 'A recompensa diária ainda não chegou do servidor.'));
    }
    /* A carta do dia da vez, guardada enquanto a grade é montada: é o alvo do
       brilho quando o prêmio acabou de sair (ver `acenderDoGargoyle`). */
    let cartaDaVez = null;

    /*
     * ---- Tudo mora DENTRO da moldura pintada ----
     *
     * A arte (`diario-fundo.png`) não é enfeite atrás: ela tem lugares
     * marcados — o medalhão vazio no alto à esquerda, o painel escuro no meio,
     * o vão entre os arabescos embaixo. Cada peça da tela é posta em cima do
     * lugar dela, em PORCENTAGEM, porque a moldura tem proporção fixa e
     * encolhe junto com a janela.
     *
     * Os números saíram de medir a imagem, e estão escritos no CSS ao lado de
     * cada regra — se um dia a arte mudar, é lá que se mexe.
     */
    const moldura = el('div', 'diario-moldura');

    // O medalhão: a sequência, que é o que a pessoa vem ver.
    const selo = el('div', diario.sequencia > 0 ? 'diario-selo' : 'diario-selo vazio');
    /*
     * Sequência zero é quem nunca pegou. "0 DIAS" lê como derrota logo na
     * primeira vez que a pessoa abre a tela — e ela não perdeu nada ainda.
     */
    selo.append(
      el('strong', null, diario.sequencia > 0 ? String(diario.sequencia) : '·'),
      el('span', null, diario.sequencia === 0 ? 'comece' : diario.sequencia === 1 ? 'dia' : 'dias')
    );
    moldura.append(selo);

    // O título, na faixa da cripta, ao lado do medalhão.
    const titulo = el('div', 'diario-titulo');
    titulo.append(el('h3', null, 'Recompensa Diária'));
    titulo.append(el('p', null,
      diario.jaPegouHoje
        ? 'A de hoje já é sua — volte amanhã e a sequência continua.'
        : diario.vaiZerar
          ? 'Você faltou um dia: pegando agora, a sequência recomeça.'
          : `Dia ${diario.dia} de ${diario.dias.length} — a de hoje está esperando.`));
    moldura.append(titulo);

    // Os trinta dias, dentro do painel escuro.
    const grade = el('div', 'diario-grade');
    for (const dia of diario.dias) {
      const carta = el('div', 'diario-dia');
      if (dia.pego) carta.classList.add('pego');
      if (dia.aVez) { carta.classList.add('a-vez'); cartaDaVez = carta; }
      if (dia.tipo === 'escolha') carta.classList.add('de-escolha');
      carta.append(el('span', 'numero', String(dia.dia)));
      carta.append(desenhoDoDiario(dia, 34, 44));
      carta.append(el('span', 'premio', dia.curto ?? dia.rotulo));
      /*
       * ---- O dia pego diz COLETADO, e nao so' um visto ----
       *
       * O visto no canto era pequeno demais para o que ele informa. A faixa
       * atravessa a carta e responde de longe a unica pergunta que a pessoa faz
       * ao abrir a aba: "ja' peguei o de hoje?".
       */
      if (dia.pego) carta.append(el('span', 'coletado', 'Coletado'));
      /*
       * ---- O balão do mouse ----
       *
       * "ao deixar o mouse em cima da recompensa aparece um resumo do que ele
       * faz". Três partes, e cada uma tem dono:
       *
       *   1. o nome inteiro (`rotulo`), porque a carta só cabe o curto;
       *   2. o que a coisa FAZ (`explica`), que vem do servidor;
       *   3. e, quando o prêmio é uma peça do catálogo, a ficha dela — a mesma
       *      da mochila, com peso, valor e afixos. Ela é montada aqui e não no
       *      servidor porque quem sabe desenhar item é o cliente.
       */
      tipPanel(carta, () => {
        const balao = el('div', 'tip-diario');
        balao.append(el('div', 'tip-diario-dia', `Dia ${dia.dia} de ${diario.dias.length}`));
        balao.append(el('div', 'tip-diario-nome', dia.rotulo));
        if (dia.explica) balao.append(el('p', 'tip-diario-texto', dia.explica));
        if (dia.itemId && dia.tipo !== 'escolha') {
          const ficha = fichaDeItem(dia.itemId);
          if (ficha) balao.append(ficha);
        }
        if (dia.pego) balao.append(el('div', 'tip-diario-estado', 'Já resgatado nesta volta.'));
        else if (dia.aVez) balao.append(el('div', 'tip-diario-estado aceso', 'É o prêmio de hoje.'));
        return balao;
      });
      grade.append(carta);
    }
    moldura.append(grade);
    /*
     * As brasas nos olhos dos gargoyles. Elemento vazio de proposito: os quatro
     * pontos sao `background` no CSS, onde os lugares medidos na arte ficam
     * todos juntos. Aqui so' se diz QUE existem.
     */
    const olhos = el('div', 'diario-olhos');
    /* As fagulhas que sobem. Seis spans vazios: os lugares, a inclinacao e o
       atraso de cada uma moram no CSS, junto das coordenadas dos olhos. */
    for (let i = 1; i <= 6; i++) olhos.append(el('span', `diario-brasa b${i}`));
    moldura.append(olhos);

    /* Uma escolha nova zera a marca: a do dia passado nao vale para esta. */
    if ((diario.pendente?.dia ?? null) !== diaMarcado) {
      diaMarcado = diario.pendente?.dia ?? null;
      marcada = null;
      adiada = false;
    }

    // O botão, no vão dos arabescos de baixo.
    const pegar = el('button', 'diario-pegar');
    if (diario.pendente) {
      /* Com a escolha adiada, este botao e' o caminho de volta para ela — por
         isso ele fica CLICAVEL, e so' apagado enquanto a janela ja' esta' na
         frente. */
      pegar.textContent = 'Escolha o prêmio';
      pegar.disabled = !adiada;
      pegar.onclick = () => { adiada = false; desenhar(); };
    } else {
      pegar.textContent = diario.podePegar ? 'Coletar' : 'Coletado';
      pegar.disabled = !diario.podePegar;
      pegar.onclick = () => send({ t: 'diario' });
    }
    moldura.append(pegar);

    quadro.append(moldura);

    /*
     * ---- A escolha por CIMA da moldura, e nao embaixo dela ----
     *
     * Ela ficava fora, logo abaixo da arte, com a ideia de deixar a pessoa ver
     * as cartas e a escolha ao mesmo tempo. So' que a moldura ja' ocupa a tela
     * inteira: o que ficava "logo abaixo" ficava abaixo da BORDA DA JANELA, e
     * com oito Durable Exercises para escolher a lista sumia de vez.
     *
     * Entao ela entra DENTRO da moldura, escurecendo a grade. Escurecer e' o
     * que diz que agora so' existe uma decisao na tela — e a grade continua
     * visivel atras, que era o motivo de ter ficado fora no comeco.
     */
    /*
     * O prêmio acabou de sair? A sequência subiu de um quadro para o outro.
     *
     * É o servidor quem decide, e não o clique: clicar em "Coletar" pode ser
     * recusado (mochila cheia, escolha pendente), e o brilho comemoraria uma
     * coisa que não aconteceu.
     *
     * `requestAnimationFrame` porque a grade acabou de ser montada e ainda não
     * tem posição na tela — medi-la agora daria zero, e as fagulhas voariam
     * para o canto.
     */
    const quem = state.character?.name ?? null;
    const subiu =
      diarioVisto.quem === quem
      && diarioVisto.sequencia != null
      && diario.sequencia > diarioVisto.sequencia;
    diarioVisto = { quem, sequencia: diario.sequencia };
    /*
     * Pelo NÚMERO do dia, e não pelo elemento.
     *
     * O elemento desta carta morre em milésimos: logo depois do aviso do
     * diário chega o estado do jogo, o painel se redesenha e esta grade inteira
     * é trocada por outra. Guardar o nó era guardar um nó SOLTO — e um nó solto
     * mede zero, que era exatamente o que fazia o efeito não acontecer.
     *
     * Dois `requestAnimationFrame` encadeados: o primeiro deixa o quadro atual
     * terminar, o segundo acontece depois de o redesenho seguinte já ter
     * assentado. Aí a grade que está na tela é a definitiva.
     */
    if (subiu) {
      const oDia = diario.dia;
      requestAnimationFrame(() => requestAnimationFrame(() => acenderDoGargoyle(oDia)));
    }

    if (diario.pendente && !adiada) {
      const escolha = el('div', 'diario-escolha');
      const caixa = el('div', 'diario-escolha-caixa');
      caixa.append(el('h4', null, `Escolha o prêmio do dia ${diario.pendente.dia}`));
      const opcoes = el('div', 'diario-opcoes');
      for (const opcao of diario.pendente.opcoes ?? []) {
        const botao = el('button', marcada === opcao.id ? 'diario-opcao marcada' : 'diario-opcao');
        const arte = itemCanvas(opcao.itemId, 40);
        if (arte) botao.append(arte);
        botao.append(el('span', 'nome', opcao.nome));
        if (opcao.detalhe) botao.append(el('span', 'detalhe', opcao.detalhe));
        botao.onclick = () => { marcada = opcao.id; desenhar(); };
        opcoes.append(botao);
      }
      caixa.append(opcoes);

      const acoes = el('div', 'diario-escolha-acoes');
      /*
       * Cancelar NAO perde o premio — a escolha fica pendente no personagem e
       * este texto e' o que diz isso. Sem ele, "Cancelar" ao lado de um premio
       * le como "desistir do premio", e ninguem clicaria.
       */
      acoes.append(el('span', 'aviso', 'Você pode escolher depois: o prêmio fica guardado.'));
      const cancelar = el('button', 'diario-escolha-acao', 'Cancelar');
      cancelar.onclick = () => { adiada = true; desenhar(); };
      const confirmar = el('button', 'diario-escolha-acao confirma', 'Confirmar');
      confirmar.disabled = !marcada;
      confirmar.onclick = () => send({ t: 'diarioEscolher', escolha: marcada });
      acoes.append(cancelar, confirmar);
      caixa.append(acoes);

      escolha.append(caixa);
      moldura.append(escolha);
    }
  };

  ctx.redraw = desenhar;
  desenhar();
}

/*
 * ---- A brasa do gargoyle sobe até a carta ----
 *
 * "quando eu clicar em coletar, consegue fazer o efeito do olho da gargoyle
 *  meio que brilhar até o card e depois voltar como estava?"
 *
 * Duas fagulhas saem dos olhos — uma de cada cara —, atravessam a grade até a
 * carta do dia e apagam ali, com a carta acendendo no instante em que elas
 * chegam. Depois tudo volta ao que era: nada do que isto faz sobrevive a um
 * segundo, e por isso não há estado para limpar se der errado no meio.
 *
 * ---- Por que em JavaScript, e não em CSS ----
 *
 * Porque o DESTINO muda: a carta do dia 3 e a do dia 27 estão em cantos opostos
 * da grade. Uma animação em CSS precisaria de trinta variantes, ou de variáveis
 * escritas pelo JavaScript do mesmo jeito — e aí é o JavaScript que manda, só
 * que espalhado em dois lugares.
 *
 * A conta é em pixels e relativa à MOLDURA (`getBoundingClientRect` dos dois),
 * e não em porcentagem: a grade tem gap, borda e padding, e porcentagem da
 * moldura não sabe disso.
 */
function acenderDoGargoyle(dia) {
  /* Procurados na tela AGORA: ver o porquê em quem chama. */
  const moldura = document.querySelector('.diario-moldura');
  const carta = document.querySelectorAll('.diario-dia')[dia - 1];
  if (!moldura || !carta) return;
  /* Quem pediu menos movimento no sistema pediu por um motivo. */
  if (window.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches) return;

  const m = moldura.getBoundingClientRect();
  const c = carta.getBoundingClientRect();
  if (!m.width || !c.width) return;

  /*
   * ---- A camada fica FORA do painel, e é isso que faz o efeito existir ----
   *
   * A primeira versão punha as fagulhas dentro da moldura, e elas nunca
   * apareciam: o painel se redesenha a cada quadro do jogo (o ouro e o peso
   * mudam sozinhos), e o redesenho limpa o miolo inteiro. A fagulha nascia e
   * era apagada no quadro seguinte, antes de andar um pixel.
   *
   * Aqui ela mora numa camada própria, presa à JANELA (`position: fixed`), com
   * as coordenadas medidas uma vez. O painel pode se redesenhar quantas vezes
   * quiser; o efeito corre até o fim e se apaga sozinho.
   */
  const camada = el('div', 'diario-brilho');
  document.body.append(camada);
  const some = setTimeout(() => camada.remove(), 1500);

  /* Um centésimo da largura da moldura: o mesmo `cqw` do resto da tela, em px,
     para o efeito encolher junto com a janela. */
  const u = m.width / 100;
  const destinoX = c.left + c.width / 2;
  const destinoY = c.top + c.height / 2;

  /* Os mesmos olhos do CSS — ver `.diario-olhos`. */
  for (const x of [0.06, 0.94]) {
    const saiX = m.left + x * m.width;
    const saiY = m.top + 0.861 * m.height;
    const faisca = el('div', 'diario-raio');
    faisca.style.left = `${saiX}px`;
    faisca.style.top = `${saiY}px`;
    faisca.style.width = `${0.9 * u}px`;
    camada.append(faisca);

    const dx = destinoX - saiX;
    const dy = destinoY - saiY;
    const anda = (p) => `translate(calc(-50% + ${dx * p}px), calc(-50% + ${dy * p}px))`;
    const voo = faisca.animate(
      [
        { transform: `${anda(0)} scale(.4)`, opacity: 0 },
        { transform: `${anda(0.06)} scale(1.6)`, opacity: 1, offset: 0.12 },
        { transform: `${anda(0.9)} scale(1)`, opacity: 1, offset: 0.76 },
        { transform: `${anda(1)} scale(3)`, opacity: 0 },
      ],
      { duration: 720, easing: 'cubic-bezier(.35,0,.25,1)' }
    );
    /*
     * Tirar a fagulha ASSIM QUE o voo acaba — e não junto com a camada.
     *
     * Sem isto ela voltava sozinha para a posição do CSS (o olho) e ficava lá,
     * acesa e parada, até o anel terminar: a animação acabou, o `transform` que
     * ela impunha evaporou, e o elemento reapareceu onde nasceu. Duas bolinhas
     * cravadas na cara do gargoyle por meio segundo.
     */
    voo.onfinish = voo.oncancel = () => faisca.remove();
  }

  /*
   * E a carta acende quando elas chegam. O anel é um elemento da camada, e não
   * uma classe na carta, pelo mesmo motivo das fagulhas: a carta é refeita a
   * cada redesenho e levaria a classe embora.
   */
  const anel = el('div', 'diario-anel');
  anel.style.left = `${c.left}px`;
  anel.style.top = `${c.top}px`;
  anel.style.width = `${c.width}px`;
  anel.style.height = `${c.height}px`;
  anel.style.borderRadius = `${0.6 * u}px`;
  camada.append(anel);
  anel.animate(
    [
      { opacity: 0, transform: 'scale(1)' },
      { opacity: 0, transform: 'scale(1)', offset: 0.55 },
      { opacity: 1, transform: 'scale(1.06)', offset: 0.68 },
      { opacity: 0, transform: 'scale(1)' },
    ],
    { duration: 1100, easing: 'ease-out' }
  ).onfinish = () => {
    clearTimeout(some);
    camada.remove();
  };
}


/*
 * ---- O desenho de cada dia ----
 *
 * Três origens, nesta ordem:
 *
 *   1. a PEÇA do catálogo (`itemId`) — a pedra de tier, a gema, o pergaminho;
 *   2. a arte da LOJA (`arte`) — wildcard, blessing, boost de experiência e
 *      charm não são peça, são número no personagem, e o desenho deles é o
 *      mesmo que a loja já usa;
 *   3. e, só se as duas faltarem, um símbolo.
 *
 * A ordem importa: o dono pediu "a imagem da exp 50%, a imagem do prey card" —
 * ou seja, o desenho que ele já conhece da loja, e não um ícone inventado aqui.
 *
 * Os dias de ESCOLHA não têm peça (são duas ou sete), então o losango fica: ele
 * já vem com a borda de cobre em volta dizendo que aquele dia é diferente.
 */
function desenhoDoDiario(dia, tamanho, sozinho = tamanho) {
  /*
   * ---- O dia de ESCOLHA mostra ENTRE O QUE se escolhe ----
   *
   * "onde está instance ou divine coloque o ícone dos dois item lado a lado, e
   *  também durable e boosted".
   *
   * Um ícone só dizia "ganha uma espada", e o dia não é isso — é "escolha".
   * Lado a lado, a carta conta a verdade sem precisar de texto.
   *
   * Eles encolhem conforme a quantidade: dois cabem grandes, quatro precisam
   * ser menores, senão transbordam a carta.
   */
  if (dia.itens?.length > 1) {
    const fila = el('div', 'diario-varios');
    /*
     * Eles encolhem conforme a quantidade, mas menos do que na primeira versao:
     * a carta tem ~160px de largura util, entao quatro de 30px com folga entre
     * elas ainda sobra espaco. Dois cabem maiores que o icone solto.
     */
    const cada = dia.itens.length >= 4 ? tamanho * 0.92 : tamanho * 1.2;
    for (const id of dia.itens) {
      const arte = itemCanvas(id, Math.round(cada));
      if (arte) fila.append(arte);
    }
    if (fila.children.length) return fila;
  }
  /*
   * O icone SOZINHO e' desenhado maior que os da fila: ele tem a carta inteira
   * para si, e e' o unico jeito de reconhecer o premio sem ler. O da fila fica
   * no tamanho de antes porque quatro deles ja' ocupam a largura util toda.
   */
  /*
   * ---- A montaria e o outfit ----
   *
   * Eles nao sao peca do catalogo: sao um LOOK, e quem sabe desenhar look e' o
   * mesmo `outfitCanvas` da loja e do quadro de party. `{ addons: 3 }` e' o que
   * a loja passa para mostrar a roupa vestida — sem isso o boneco sai pelado, e
   * o premio e' justamente a roupa COM os dois addons.
   */
  if (dia.look) {
    const boneco = outfitCanvas(dia.look, { addons: 3 }, sozinho, 2, false);
    if (boneco) return boneco;
  }
  if (dia.itemId) {
    const arte = itemCanvas(dia.itemId, sozinho);
    if (arte) return arte;
  }
  if (dia.arte) {
    const img = document.createElement('img');
    img.className = 'diario-arte';
    img.alt = '';
    img.width = sozinho;
    img.height = sozinho;
    img.src = dia.arte.startsWith('ui:')
      ? `/client/assets/ui/${dia.arte.slice(3)}.png`
      : dia.arte.startsWith('icone:')
        ? `/client/assets/icons/${dia.arte.slice(6)}.png`
        : `/client/assets/store/${dia.arte}.png`;
    return img;
  }
  return el('span', 'simbolo', dia.tipo === 'escolha' ? '❖' : '•');
}

/*
 * ---- O que está ATIVO, no balão do ícone da barra ----
 *
 * O dono: "quando eu passar o mouse no ícone de prey, gemas, charms,
 * proficiência, imbuements, tem que meio que mostrar o que tenho ativo sabe?
 * igual o da árvore que eu passo o mouse e já mostra (com ícones bem bonito)".
 *
 * A Árvore já fazia isso (`resumoDaArvoreParaBalao`, em arvore.mjs) e é o
 * balão mais usado do jogo pelo motivo óbvio: a resposta que o jogador procura
 * o tempo todo enquanto caça — "o que eu tenho ligado agora?" — estava a dois
 * cliques, e passar o mouse é mais barato do que isso.
 *
 * Os cinco moram AQUI e não em main.mjs porque os desenhos moram aqui:
 * `bonusIcon` e `stars` do prey, `perkIcon` da proficiência, `imbuementIcon`
 * dos encantamentos. Levá-los para lá seria mudar cinco funções de casa para
 * ganhar nada.
 *
 * Cada um devolve `null` quando não há o que contar — aí o balão fica só com o
 * nome e a frase do botão, como sempre foi.
 */

/** Uma linha de balão: ícone, rótulo e o valor à direita. */
function linhaDoResumo(arte, rotulo, valor, classe = null) {
  const linha = el('div', classe);
  if (arte) linha.append(arte);
  linha.append(el('span', null, rotulo));
  if (valor != null) linha.append(el('b', null, String(valor)));
  return linha;
}

/**
 * Prey: as três presas, o bônus de cada uma e quanto falta.
 *
 * `character.prey` vem em toda atualização do personagem (ver `preyView`, no
 * servidor), então este balão está certo sem ninguém ter aberto o painel.
 */
export function resumoDoPreyParaBalao() {
  const { state } = ctx;
  const slots = state.character?.prey ?? [];
  if (!slots.length) return null;

  const caixa = el('div', 'tip-resumo');
  let algum = false;
  for (const slot of slots) {
    if (slot.state === 'locked') {
      caixa.append(linhaDoResumo(null, 'slot travado', null, 'apagado'));
      continue;
    }
    if (!slot.key || slot.left <= 0) {
      /* Slot vazio é o que faz o ícone da barra acender: ele é um bônus parado. */
      caixa.append(linhaDoResumo(null, 'sem presa', 'escolher', 'chama'));
      continue;
    }
    algum = true;
    const nome = state.catalog?.bestiary?.[slot.key]?.name ?? slot.key;
    const oQue = state.catalog?.preyBonuses?.find((entry) => entry.id === slot.bonus)?.name ?? '';
    const linha = linhaDoResumo(bonusIcon(slot.bonus), nome, `+${slot.percent}%`);
    linha.append(el('em', null, `${oQue} · ${formatLeft(slot.left)}`));
    caixa.append(linha);
  }
  if (!algum && !caixa.childElementCount) return null;
  return caixa;
}

/**
 * Charms: os que já foram liberados, o tier e a criatura de cada um.
 *
 * `state.charms` NÃO vem na atualização do personagem — é pedido. A barra pede
 * uma vez ao montar (ver `buildTopbar`), e o que chega fica. Sem isso o balão
 * ficaria vazio até alguém abrir o painel, que é exatamente a viagem que ele
 * existe para poupar.
 */
export function resumoDosCharmsParaBalao() {
  const { state } = ctx;
  const view = state.charms;
  if (!view) return null;

  const caixa = el('div', 'tip-resumo');
  const meus = (view.list ?? []).filter((charm) => charm.tier > 0);
  if (!meus.length) {
    caixa.append(el('em', null, `${money(view.points)} pontos e nenhum charm liberado ainda.`));
    return caixa;
  }
  for (const charm of meus) {
    const arte = document.createElement('img');
    arte.className = 'charm-icon';
    arte.src = `/client/assets/charms/icon-charms-${charm.category}.png`;
    arte.alt = '';
    const apelido = apelidoDoCharm(charm.id);
    const linha = linhaDoResumo(arte, apelido ? `${charm.name} (${apelido})` : charm.name, `tier ${charm.tier}`);
    /* O charm (ofensivo ou defensivo) só dispara na criatura apontada: sem ela, ele está parado. */
    const bicho = state.catalog?.bestiary?.[charm.assigned]?.name;
    linha.append(el('em', bicho ? null : 'chama', bicho ?? 'sem criatura'));
    caixa.append(linha);
  }
  caixa.append(el('em', 'tip-resumo-pe', `${money(view.points)} ponto(s) de charm no bolso`));
  return caixa;
}

/**
 * Proficiência: a arma da mão, o nível dela e os perks escolhidos.
 *
 * `character.proficiency` vem na atualização do personagem, com os `levels` e o
 * `chosen` de cada um — é a mesma coisa que a tela desenha, só que resumida.
 */
export function resumoDaProficienciaParaBalao() {
  const { state } = ctx;
  const view = state.character?.proficiency;
  if (!view?.itemId) return null;

  const caixa = el('div', 'tip-resumo');
  const nome = state.items?.[view.itemId]?.name ?? 'arma';
  const topo = linhaDoResumo(itemCanvas(view.itemId, 20), nome, `nível ${view.level}/${view.max}`);
  if (!view.equipped) topo.append(el('em', 'apagado', 'não está na mão'));
  caixa.append(topo);

  const escolhidos = (view.levels ?? []).filter((passo) => passo.chosen != null);
  const esperando = (view.levels ?? []).filter((passo) => passo.unlocked && passo.chosen == null);
  if (!escolhidos.length) {
    caixa.append(el('em', null, 'nenhum perk escolhido ainda'));
  } else {
    for (const passo of escolhidos) {
      const perk = passo.perks?.find((p) => p.slot === passo.chosen);
      if (!perk) continue;
      caixa.append(linhaDoResumo(perkIcon(perk, 20), perkText(perk), `lv ${passo.level}`));
    }
  }
  if (esperando.length) {
    caixa.append(el('em', 'chama tip-resumo-pe', `${esperando.length} perk(s) esperando escolha`));
  }
  return caixa;
}

/**
 * Imbuements: o que está aceso em cada peça, e quanto falta.
 *
 * `character.imbuements` é um mapa de encaixe -> lista, e vem na atualização do
 * personagem. O balão junta tudo numa lista só, com a peça na frente.
 */
export function resumoDosImbuementsParaBalao() {
  const { state } = ctx;
  const character = state.character;
  if (!character) return null;

  const caixa = el('div', 'tip-resumo');
  let quantos = 0;
  for (const slot of IMBUEMENT_SLOTS) {
    for (const imbued of character.imbuements?.[slot] ?? []) {
      quantos++;
      const fonte = state.catalog?.imbuements?.find((entry) => entry.id === imbued.id);
      const arte = fonte?.iconId ? imbuementIcon(fonte.iconId, 20) : null;
      const apelido = apelidoDoImbuement(imbued.name);
      const linha = linhaDoResumo(
        arte,
        apelido ? `${imbued.name} (${apelido})` : imbued.name,
        formatLeft(imbued.left)
      );
      linha.append(el('em', null, state.items?.[character.equipment?.[slot]?.id]?.name ?? SLOT_LABEL[slot] ?? slot));
      caixa.append(linha);
    }
  }
  if (!quantos) {
    /* Quantos encaixes existem: "nenhum aceso" sem isso parece defeito. */
    const vagas = IMBUEMENT_SLOTS.reduce((total, slot) => total + (character.imbuementSlots?.[slot] ?? 0), 0);
    caixa.append(el('em', null, vagas ? `nenhum aceso — ${vagas} encaixe(s) livre(s)` : 'nenhuma peça sua aceita imbuement'));
  }
  return caixa;
}

/**
 * Gemas: o balão que a pílula do HUD já mostra, reaproveitado inteiro.
 *
 * Ele lista os modificadores acesos com ícone e valor — que é exatamente "o que
 * eu tenho ativo". Escrever um segundo resumo das gemas seria manter dois
 * textos para a mesma pergunta, e eles envelheceriam separados.
 */
export function resumoDasGemasParaBalao() {
  const view = ctx.state.gemas;
  if (!view) return null;
  return balaoDosBonusDasGemas(view);
}
